INSERT INTO `t_ai_cache` (`id`, `prompt`, `content`, `prompt_md5`, `create_time`) VALUES (286, '欧洲多国遭遇极端天气', '欧洲多国遭遇极端天气涉及的国家可能包括德国、法国、意大利、西班牙、波兰等。这些国家近年来都曾经历过不同程度的极端天气事件，如热浪、暴雨、干旱等。具体受影响国家会根据实际气象情况有所不同。', '80de2c1be2e548b830ce2dc0c58cf57a', '2025-08-15 21:05:07');
