INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2734, NULL, '基孔肯雅热为何在我国南方部分地区传播较快？张文宏解答', 0, 2, 197, '2025-07-26 15:46:42', '2025-07-26 15:12:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/115/w550h365/20250726/c535-038f48b18175587552b8c49c25cdff90.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-26/doc-infhuqsw7265614.shtml', '第一财经', '目前没有找到关于“基孔肯雅热为何在我国南方部分地区传播较快？张文宏解答”的详细新闻内容。您可以稍后再尝试查询，或者直接查看相关的权威新闻发布平台以获取最新信息。', '[\"https://k.sinaimg.cn/n/news/crawl/115/w550h365/20250726/c535-038f48b18175587552b8c49c25cdff90.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2735, NULL, '甘肃庆阳暴雨致人员失联 当地正在搜救', 0, 2, 302, '2025-07-26 16:45:34', '2025-07-26 16:01:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-26/doc-infhuuyu2089719.shtml', '央视', '### 甘肃庆阳暴雨致人员失联，当地正在搜救\n\n#### 概要\n自2025年7月25日起，甘肃东部的庆阳和平凉地区遭遇了强降雨天气，部分地区甚至出现了大暴雨。受此影响，庆阳市庆城县桐川镇发生了人员失联事件，目前当地政府正在积极进行搜救工作。\n\n#### 详细信息\n- **天气情况**：7月25日开始，甘肃东部地区出现强降雨，部分地区降水量达到大暴雨级别。\n- **受影响地区**：庆阳市庆城县桐川镇是此次事件的主要受影响区域。\n- **人员失联**：由于暴雨的影响，桐川镇有人员失联。\n- **搜救行动**：当地政府已经启动了紧急搜救行动，目前仍在进行中。\n- **媒体报道**：央视新闻客户端、新浪财经、中国新闻网、澎湃新闻等多家媒体对此事件进行了报道。\n\n#### 相关链接\n- [甘肃庆阳暴雨致人员失联 当地正在搜救 - 网易视频](https://www.163.com/v/video/VA4FNFRUT.html)\n- [甘肃庆阳暴雨致人员失联 当地正在搜救 - 新浪财经](https://finance.sina.com.cn/jjxw/2025-07-26/doc-infhuuyw3920427.shtml)\n- [甘肃庆阳暴雨致人员失联 当地正在搜救 - 中国新闻网](https://www.chinanews.com/gn/2025/07-26/10454096.shtml)\n- [甘肃庆阳暴雨致人员失联，当地正在搜救 - 澎湃新闻](https://www.thepaper.cn/newsDetail_forward_31248249)\n\n#### 责任单位\n- **总台记者**：安文剑、段博文\n\n#### 责任编辑\n- 柴敏懿\n\n此事件仍在持续更新中，建议关注官方媒体获取最新信息。', '[]');
