INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2737, NULL, '“高质量发展看新疆”网络主题活动丨七个星佛寺遗址博物馆是中华民族交往交流交融历史的珍贵物证', 0, 1, 31, '2025-07-26 16:45:55', '2025-07-26 15:47:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-26/doc-infhuuyu2084732.shtml', '石榴云', '未找到与“高质量发展看新疆”网络主题活动丨七个星佛寺遗址博物馆是中华民族交往交流交融历史的珍贵物证相关的新闻内容。请确认新闻标题或关键词是否正确，或尝试提供更详细的信息以进一步搜索。', '[]');
