INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2788, NULL, '北京市27日午后至28日上午大部分地区小时雨强可达30毫米以上', 0, 1, 1, '2025-07-27 15:27:02', '2025-07-27 14:34:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-27/doc-infhwxxu0972936.shtml', '千龙网中国首都网', 'news not found', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2789, NULL, '最新｜密云水库已超历史最大洪峰流量！下午3点启动泄流', 0, 1, 1, '2025-07-27 15:27:12', '2025-07-27 14:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-27/doc-infhwxxw2773954.shtml', '北京日报客户端', '## 北京密云水库启动泄流应对历史最大洪峰流量\n\n### 事件概览\n2025年7月27日下午3时，北京密云水库启动泄流工作，以应对入库最大洪峰流量已超过历史极值的情况。此次泄流是为了保障水库下游的安全，将水位逐步降至汛限水位以下。\n\n### 洪峰流量\n受本轮强降雨影响，密云水库上游来水量显著增加，最大入库洪峰流量达到了6550立方米/秒，已经超过了历史最大洪峰流量。\n\n### 泄流影响\n泄流期间，密云水库下游的潮河、白河、潮白河等河道水位将明显上涨，水流湍急。\n\n### 安全提示\n北京市水务局提醒下游密云、怀柔、顺义、通州等区市民密切关注通告，听从沿河河道管控要求，远离河道，确保自身安全。\n\n### 相关措施\n- **潮白河右堤路管控**：自7月27日14时起，潮白河右堤路进行管控。\n- **文化场所闭馆**：北京怀柔区图书馆、博物馆和文化馆已于7月27日13时起临时闭馆，恢复正常开馆时间另行通知。\n- **景区暂停开放**：北京市延庆区所有景区、露营地已暂停开放，民宿停止接待。\n\n以上信息综合了多方报道，确保公众安全并减少洪水带来的潜在风险。', '[]');
