INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2801, NULL, '山西一辆载12人中巴车凌晨因强降雨失联，当地：暂未找到，多部门正全力搜寻', 0, 1, 4, '2025-07-27 17:27:30', '2025-07-27 15:18:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250727/605/w668h737/20250727/7737-deb9c8ce0797f6c7d3e6757b8b7dcc29.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-27/doc-infhwxxx6743438.shtml', '极目新闻', '## 山西一辆载12人中巴车凌晨因强降雨失联，当地：暂未找到，多部门正全力搜寻\n\n### 事件概要\n\n2025年7月27日凌晨5时8分，山西省大同市天镇县发生一起因强降雨导致的中巴车失联事件。一辆载有12人的依维柯中巴车在谷前堡镇附近失联。事发后，多部门立即展开全力搜寻工作，但截至当日，仍未找到失联车辆。\n\n### 详细信息\n\n- **事件时间**：2025年7月27日5时8分\n- **事件地点**：山西省大同市天镇县谷前堡镇附近\n- **车辆信息**：一辆载有12人的依维柯中巴车\n- **天气情况**：天镇县从7月23日以来降雨量较大，事发时正值强降雨期间。天镇县于27日凌晨4时10分发布山洪灾害气象风险红色预警。\n- **救援情况**：省市县各级领导均在前线指挥搜寻工作。多部门正在天镇县谷前堡镇一畔庄村附近全力搜寻失联车辆。\n- **政府反应**：山西省委省政府高度重视此次事件，要求全力做好救援工作。\n\n### 来源\n\n- [快资讯](https://www.360kuai.com/pc/9390741f2a6dae059?cota=3&kuai_so=1&sign=360_e39369d1)\n- [观察者网](https://www.guancha.cn/politics/2025_07_27_784470.shtml?s=zwykx)\n- [新浪网](https://news.sina.com.cn/c/2025-07-27/doc-infhwxxx6743438.shtml)', '[\"https://k.sinaimg.cn/n/spider20250727/605/w668h737/20250727/7737-deb9c8ce0797f6c7d3e6757b8b7dcc29.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
