INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2811, NULL, '【受权发布】北京7月27日17时30分继续发布地质灾害气象风险红色预警', 0, 1, 1, '2025-07-27 19:26:44', '2025-07-27 19:12:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-27/doc-infhxkpq5787733.shtml', '千龙网', '### 北京升级发布地质灾害气象风险红色预警\n\n7月27日，北京市规划和自然资源委员会联合市气象局于8时升级发布地质灾害气象风险红色预警。根据预警内容，从7月27日8时至7月28日8时，以下地区面临较高的地质灾害风险：\n\n- **红色预警区域**：延庆东部、怀柔中部和西南部、密云西北部，存在发生崩塌、滑坡、泥石流等地质灾害的极高风险。\n- **橙色预警区域**：怀柔北部、密云中部，存在较高的地质灾害风险。\n- **黄色预警区域**：延庆东北部和东南部、怀柔南部、密云东南部，存在一定的地质灾害风险。\n- **蓝色预警区域**：房山、门头沟大部，丰台、石景山、海淀西部，昌平西部和北部，延庆北部和南部，平谷大部，存在发生地质灾害的可能性。\n\n此外，北京市还发布了洪水红色预警。北京市水文总站于7月27日0时30分升级发布洪水红色预警，预计当天3时至5时，潮白河流域张家坟断面流量将达到3000立方米每秒，达到红色预警等级。相关部门提醒市民远离河道，确保自身安全。\n\n北京市密云区目前处于暴雨红色预警中，并已启动防汛一级应急响应。截至27日上午，全区已转移18个镇149个村的1452户、3065人，实现了应转尽转。同时，65处工地已关闭，30家地质灾害景区全部关闭，63条山洪沟道全部关闭并加强管控。\n\n自然资源部也启动了北京地质灾害防御Ⅲ级响应，派出司局级同志带队的工作组赴北京指导地质灾害防范应对工作。\n\n请市民密切关注汛情动态，远离危险区域，做好防范措施。', '[]');
