INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2832, NULL, '以总理称以色列一直允许最低限度物资进入加沙', 0, 4, 95, '2025-07-28 00:26:33', '2025-07-27 22:35:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250727/533/w800h533/20250727/224f-6a6df194b88d09ed259f46d20575d943.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-27/doc-infhxqvt1003030.shtml', '央视', '### 以总理称以色列一直允许最低限度物资进入加沙\n\n以色列总理本雅明·内塔尼亚胡于当地时间2025年7月27日表示，以色列一直允许最低限度的人道主义物资进入加沙地带，并称这是以色列一贯执行的政策，且将继续执行。这一表态是在加沙地带持续面临严重人道主义危机的背景下作出的。\n\n#### 关键要点：\n1. **物资限制政策**：\n   - 内塔尼亚胡强调，以色列允许最低限度的人道主义物资进入加沙，包括食品、药品和其他基本生活物资。\n   - 这一政策旨在平衡安全考量与人道主义需求。\n\n2. **加沙地带现状**：\n   - 加沙地带的卫生部门在2025年7月27日发布声明称，过去24小时内因饥荒和营养不良新增6起死亡案例，使相关死亡人数上升至133人，其中儿童占87人。\n   - 此外，过去一天内有11人在领取援助物资时死亡，超过36人受伤，表明加沙民众在获取援助方面面临巨大困难。\n\n3. **国际压力**：\n   - 近期，包括法国、德国、西班牙、加拿大、澳大利亚等在内的22国外长发表联合声明，要求以色列立即全面恢复对加沙地带的援助，并允许联合国和人道主义组织独立、公正地开展工作。\n   - 联合声明指出，尽管有迹象显示援助正在有限度地恢复，但以色列已阻止人道主义援助进入加沙地带超过两个月，导致当地食品、药品和基本物资严重短缺。\n\n4. **以色列的回应**：\n   - 以色列方面表示，婴儿食品已开始通过卡车运入加沙地带，但这些物资远不能满足加沙民众的最低生活需要。\n   - 加沙地带媒体办公室指出，尽管部分物资进入加沙，但总体情况依然严峻，援助只是“杯水车薪”。\n\n#### 背景信息：\n- 以色列自2025年3月2日起对加沙地带实施封锁，全面禁止人道主义援助进入。这一举措加剧了加沙地带的粮食和医疗危机。\n- 尽管以色列在外界压力下允许部分物资进入加沙，但国际社会普遍认为这远远不够，呼吁以色列全面恢复援助。\n\n#### 结论：\n以色列的政策在国际社会引发了广泛关注和批评。虽然以色列表示允许最低限度的物资进入加沙，但加沙地带的人道主义危机仍在持续，亟需国际社会进一步介入和协调，以缓解当地民众的困境。', '[\"https://k.sinaimg.cn/n/spider20250727/533/w800h533/20250727/224f-6a6df194b88d09ed259f46d20575d943.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2833, NULL, '北京9座水库泄流中，包括密云水库！352条山洪沟道全封闭', 0, 1, 1, '2025-07-28 00:27:04', '2025-07-27 23:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250727/0/w1920h1280/20250727/a078-f1b37b6841001a6c0df7ef1a8dd369db.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-27/doc-infhxvcr0875634.shtml', '极目新闻', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250727/0/w1920h1280/20250727/a078-f1b37b6841001a6c0df7ef1a8dd369db.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250727/600/w1920h1080/20250727/26d4-d9e9d541b55324d04c6a59c1887c6115.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250727/0/w1920h1280/20250727/dd5d-34db538e365c9d7fd0d52d081178ee32.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250727/267/w675h392/20250727/6bbe-b6c56b86ee7ade4c09fa7e4b6caf7a1f.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2834, NULL, '泽连斯基与冯德莱恩通电话 讨论乌克兰入欧谈判准备工作等问题', 0, 4, 204, '2025-07-28 02:26:21', '2025-07-27 22:49:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/533/w1280h853/20250728/9935-a3f1b632c8ade8a5131c092ce81338b5.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhxvcr0884520.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250728/533/w1280h853/20250728/9935-a3f1b632c8ade8a5131c092ce81338b5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2835, NULL, '胡塞武装升级海上封锁 将袭击所有与以合作公司船只', 0, 4, 214, '2025-07-28 06:26:23', '2025-07-28 04:59:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/60/w1016h644/20250728/3c48-df10ccd3f38587254a1e4aec34cbc682.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhyftm0640527.shtml', '央视', '## 胡塞武装升级海上封锁 将袭击所有与以合作公司船只\n\n根据多家媒体报道，当地时间27日晚间，也门胡塞武装军事发言人叶海亚·萨雷亚发表声明，宣布将升级其海上封锁行动，并展开第四阶段的封锁措施。\n\n### 主要要点：\n- **袭击范围**：胡塞武装表示将对所有与以色列港口有合作的航运公司的船只进行袭击，无论这些船只的国籍或航行地点。\n- **警告内容**：胡塞武装警告所有航运公司在该声明发出后，应立即停止同以色列的航运合作。\n- **潜在威胁**：否则，相关公司的所有船只无论在什么地方航行，都有可能遭到胡塞武装的导弹或无人机袭击。\n\n此次声明表明，胡塞武装将进一步扩大其在红海和相关水域的封锁行动，对国际航运构成潜在威胁。', '[\"https://k.sinaimg.cn/n/spider20250728/60/w1016h644/20250728/3c48-df10ccd3f38587254a1e4aec34cbc682.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2836, NULL, '7300平方公里区域拉响红色预警，北京与暴雨鏖战24小时纪实', 0, 1, 1, '2025-07-28 07:26:31', '2025-07-27 22:57:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250727s/594/w2048h946/20250727/09a1-c506a80d4ab55987a033c8ef568d14ea.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-07-27/doc-infhxqvq2464855.shtml', '新京报', 'news not found', '[\"https://k.sinaimg.cn/n/sinakd20250727s/594/w2048h946/20250727/09a1-c506a80d4ab55987a033c8ef568d14ea.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/378/w1134h844/20250727/f1da-4f8ef80acf1f579fd2acced7162af15a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/516/w1270h846/20250727/a87a-4309c7b8a8043aa98e9e4e802da5c689.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/415/w1182h833/20250727/36a1-7539694666754d01f4f470ab3bb33608.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/384/w2048h1536/20250727/f628-79a2f6b2586af3c539cd1750ef178289.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/528/w2048h880/20250727/0749-00f5eaa320982b472de91694d8e440a0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/585/w1706h1279/20250727/b333-b8b5c4ea76f80566d23b5644417356e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250727s/510/w1263h847/20250727/41b1-2220d6a507eb5128b4d018432f14be01.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2837, NULL, '中方对柬泰冲突造成两国伤亡深感痛心 希望双方尽快止战', 0, 4, 102, '2025-07-28 08:26:30', '2025-07-27 23:33:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-07-28/doc-infhxvcr0886699.shtml', '央视', '## 中方对柬泰冲突造成两国伤亡深感痛心，希望双方尽快止战\n\n近日，柬埔寨和泰国在边境地区爆发了激烈的军事冲突，导致两国均出现人员伤亡。这一局势引起了国际社会的广泛关注，尤其是中方对此表示了深切的关切。\n\n### 中方立场\n\n中国外交部发言人表示，柬埔寨和泰国是搬不走的邻居，也都是中国的友好邻邦。中方对冲突造成柬、泰两国民众伤亡深感痛心，并向两国人民表示诚挚的慰问。\n\n中方强调，坚持睦邻互信、妥善管控分歧符合柬泰双方的根本和长远利益，有利于地区的和平与稳定。中方希望双方从两国人民的共同利益出发，秉持以和为贵、与邻为善的精神，保持冷静克制，尽快停火止战，通过对话协商和平解决分歧，早日恢复边境地区的和平稳定。\n\n### 国际社会的努力\n\n与此同时，国际社会也在积极介入，推动双方停火。东盟方面连日来积极推动柬泰停火，中方对此表示赞赏，并欢迎一切有利于缓解局势的努力。\n\n中方表示将秉持公道公允的立场，继续与柬、泰保持密切沟通，积极劝和促谈，为推动停火止战发挥建设性作用。\n\n### 结语\n\n当前，柬泰边境的局势依然紧张，但中方的呼吁和国际社会的努力为缓解冲突提供了希望。各方期待通过对话和协商，尽快实现停火止战，恢复地区的和平与稳定。', NULL);
