INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2845, NULL, '美国印第安纳波利斯市东北部发生枪击事件 致5人受伤', 0, 4, 207, '2025-07-28 09:26:38', '2025-07-28 06:43:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/450/w800h450/20250728/3efa-7c23535caedddb139bab3f103058e795.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhymzf5941006.shtml', '央视', '### 美国印第安纳波利斯市东北部发生枪击事件致5人受伤\n\n**时间**：当地时间2025年7月27日  \n**地点**：美国印第安纳波利斯市东北部一处居民区  \n\n---\n\n#### 事件概述\n在当地时间7月27日，美国印第安纳波利斯市的东北部居民区发生了一起枪击事件，导致5人受伤，其中1人伤势严重。枪击发生后，执法人员迅速赶到现场并封锁了区域。目前，所有伤者已经被送往医院接受救治，但警方尚未公布伤者身份。\n\n---\n\n#### 调查进展\n印第安纳波利斯都会警察局（IMPD）正在对案件展开调查，并呼吁知情群众提供线索。初步的消息显示，此次事件是否与帮派冲突或个人恩怨有关尚不清楚，同时嫌疑人身份也暂未确认。\n\n---\n\n#### 来源\n- [新浪财经](https://finance.sina.com.cn/roll/2025-07-28/doc-infhymzi0519218.shtml)\n- [楚天都市网](https://ctdsb.net/c1476_202507/2494972.html)\n- [汇通网](https://www.fx678.com/C/20250728/202507280653492065.html)', '[\"https://k.sinaimg.cn/n/spider20250728/450/w800h450/20250728/3efa-7c23535caedddb139bab3f103058e795.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2846, NULL, '关税依然很高 芬兰外贸和发展部长称欧美贸易协议不值得庆祝', 0, 4, 65, '2025-07-28 09:26:55', '2025-07-28 05:21:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/534/w800h534/20250728/4300-e0c93cb8349092602f0437d3606543fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhyftm0641390.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250728/534/w800h534/20250728/4300-e0c93cb8349092602f0437d3606543fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2847, NULL, '“水来得非常急 不超10分钟屋就满了” 总台记者直击怀柔山洪救援', 0, 1, 1, '2025-07-28 09:27:13', '2025-07-28 08:43:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250728/943e-bf3699e0e94aacb32a244bcdecf3420f.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-28/doc-infhysia1869702.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250728/943e-bf3699e0e94aacb32a244bcdecf3420f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250728/ee9f-b62289feabd2825ebfa0f9e9efe2c722.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250728/09fb-eb9ecdd0af5b3d4e9912ac1cc9ffeca5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2848, NULL, '贵州盘州至兴义高铁铺轨完成', 0, 1, 24, '2025-07-28 09:27:38', '2025-07-28 08:35:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-28/doc-infhysic5831442.shtml', '国资委网站', '### 贵州盘州至兴义高铁铺轨完成\n\n近日，贵州省盘州市茶厅左线隧道出口施工现场迎来了一个重要里程碑，随着新型长钢轨智能牵引车完成最后一对500米长钢轨铺设，盘州至兴义高铁（简称盘兴高铁）全线轨道铺设任务圆满完成。\n\n#### 项目概况\n- **线路长度**：盘兴高铁全长约98公里。\n- **设计时速**：250公里/小时。\n- **桥隧比例**：高达90.66%，是目前贵州高铁中桥隧比例最高的线路。\n- **建设单位**：由中国中铁旗下中铁一局承担全线铺轨（含站线）及铺砟施工任务。\n\n#### 工程亮点\n面对复杂地形、长大坡道及运输组织难度大等挑战，施工团队采取了多项先进技术和装备：\n- **新型长钢轨智能牵引车**。\n- **CPG500型铺轨机自适应巡航走行定位系统**。\n- **智能数显螺栓机器人、轨枕定位机器人**等。\n这些技术显著提升了轨道铺设精度和施工效率，并确保了施工全过程的安全可控。\n\n#### 建设意义\n- **交通网络完善**：盘兴高铁建成后，贵阳至兴义仅需2小时即可到达，贵阳至省内8个市（州）中心城市将形成1至2小时高铁交通圈。\n- **经济发展促进**：作为贵州省实现“市市通高铁”目标的最后一个项目，盘兴高铁的建成将极大改善区域间的互联互通条件，助力地方经济和社会发展。\n\n目前，盘兴高铁已进入建设关键冲刺期，桥梁和隧道工程等附属土建施工全面完工，车站建设和设备安装正在收尾阶段。接下来，全线将逐步进入线路精捣、精调、静态验收及联调联试等阶段。\n\n> 来源：[新浪财经](https://finance.sina.com.cn/jjxw/2025-07-28/doc-infhysic5831439.shtml)、[中国新闻网](https://www.chinanews.com/cj/2025/07-22/10451778.shtml)、[新华网](http://www.xinhuanet.com/20250722/0c12cbce3466450ebed8c66398c83bb7/c.html)', '[]');
