INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2855, NULL, '（讲述·典型故事）一个眼神交汇，深圳两名退役军人默契出手，合力救下一女子', 0, 2, 194, '2025-07-28 10:27:00', '2025-07-28 10:09:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/600/w1080h1920/20250728/eee0-e5d0e73485448eee7754632f87a92c84.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-28/doc-infhysif0468022.shtml', '退役军人事务部', '深圳两名退役军人在街头偶遇一名神色慌张的女子，凭借敏锐的观察力和军人本能，两人默契配合，成功将其从潜在的危险中解救出来。事件发生在深圳市某繁华街区，据目击者称，其中一名退役军人注意到女子的异常举动，随后与另一名战友仅凭眼神交流便迅速展开行动。他们一边安抚女子情绪，一边联系警方，并协助将女子安全送回家中。此事件再次展现了退役军人在关键时刻的担当与责任感，也传递了社会正能量。\n\n来源：深圳本地新闻平台  \n时间：2025年7月27日  \n标签：退役军人、社会正能量、深圳好人好事', '[\"https://k.sinaimg.cn/n/spider20250728/600/w1080h1920/20250728/eee0-e5d0e73485448eee7754632f87a92c84.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250728/425/w1080h945/20250728/0f9f-c8f06d232a085302b75db5c93f6fc2bf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250728/200/w1080h720/20250728/45f7-5a53657103bafd5f372a6540cae87326.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
