INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2869, NULL, '涉尹锡悦夫妇案，韩国一前议员被发现自杀身亡', 0, 4, 105, '2025-07-28 13:26:24', '2025-07-28 12:06:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/383/w710h473/20250728/7dcc-61b6c1d0c79b5d3970fdc8978fdc11c0.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhywqy1843604.shtml', '观察者网', '### 涉尹锡悦夫妇案，韩国一前议员被发现自杀身亡\n\n韩国前京畿道议会议员崔虎（音译）于2025年7月28日凌晨被发现身亡。崔虎因牵涉前总统尹锡悦夫妇介入国民力量党内公荐案而接受检方调查。\n\n据报道，崔虎的家属于28日凌晨2时许向警方报案称其失踪。警方在当天凌晨3时许于平泽市芝山洞的一座山上发现了他的遗体。警方初步认为，崔虎可能在27日下午5时左右离家后自尽，现场未发现遗书。由于案件仍在调查中，警方暂未透露更多详情。\n\n崔虎曾于2022年获得国民力量党平泽市市长候选人公荐。检方怀疑尹锡悦夫妇在平泽市长人选公荐过程中支持了亲尹派人士崔虎，并对此展开调查。\n\n此事件发生在韩国特别检察组传唤尹锡悦夫妇接受调查的敏感节点，引起了广泛关注。特检组指控尹锡悦涉嫌违反《公职选举法》，并要求其于7月29日上午10时以嫌疑人身份到案接受调查并提供协助。\n\n目前，警方正在进一步调查崔虎自杀的具体原因及其与尹锡悦夫妇案件之间的关联。', '[\"https://k.sinaimg.cn/n/spider20250728/383/w710h473/20250728/7dcc-61b6c1d0c79b5d3970fdc8978fdc11c0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2870, NULL, '北京发布今年首个全市范围暴雨红警，为何雨这么大、又总是夜雨？', 0, 1, 1, '2025-07-28 13:26:36', '2025-07-28 12:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250728s/542/w1221h921/20250728/c080-7dde7d9e7ba8d306c8d0612577dad84d.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-07-28/doc-infhywrc0392834.shtml', '新京报', 'news not found', '[\"https://k.sinaimg.cn/n/sinakd20250728s/542/w1221h921/20250728/c080-7dde7d9e7ba8d306c8d0612577dad84d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
