INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2872, NULL, '欧洲专家：“哎，欧盟当初要是配合中国反击就好了”', 0, 4, 36, '2025-07-28 14:26:31', '2025-07-28 14:04:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250728s/200/w600h400/20250728/c1e3-25df54ce61c8a28423c0276310dee073.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhzaww1742572.shtml', '观察者网', '### 欧洲专家：“哎，欧盟当初要是配合中国反击就好了”\n\n根据新浪新闻的一篇报道，欧洲专家对欧盟在贸易争端中的策略提出了批评。欧盟委员会官员格奥尔格·里克莱斯认为，欧盟最近威胁对美国商品征收930亿欧元报复性关税之举来得太晚。他指出，如果欧盟在4月就对美国做出有力回应，配合中国反击美国上调关税，对市场和特朗普造成巨大冲击，欧盟的处境本来会更好。\n\n这篇报道强调了欧盟在面对国际贸易紧张局势时的被动地位。专家认为，欧盟未能及时采取有效措施，导致其在全球贸易争端中处于不利位置。欧盟对美国的迟缓反应不仅未能保护其自身利益，还可能加剧了与中国的贸易摩擦。\n\n此外，报道还提到，欧盟在贸易政策上的犹豫不决和对中美两国的双重依赖，使其在全球贸易体系中变得更加孤立。欧盟试图在中美之间保持平衡，但这种策略并未能有效缓解其面临的贸易压力。\n\n总的来说，这篇报道反映了欧洲专家对欧盟贸易政策的担忧，并呼吁欧盟采取更加积极和果断的措施，以应对日益复杂的国际贸易环境。', '[\"https://k.sinaimg.cn/n/sinakd20250728s/200/w600h400/20250728/c1e3-25df54ce61c8a28423c0276310dee073.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250728s/195/w600h395/20250728/664f-3bf86fc3376fc1ec9d94835996d450d5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250728s/200/w600h400/20250728/7d0c-6b0e0397c37cdc9d32d165155560d4c6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2873, NULL, '泰国代理总理：泰柬谈判将讨论落实停火的细节', 0, 4, 194, '2025-07-28 14:26:44', '2025-07-28 14:01:00', NULL, NULL, NULL, 'https://news.sina.com.cn/o/2025-07-28/doc-infhzawz0288218.shtml', '新京报', 'news not found', NULL);
