INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2884, NULL, '泰国曼谷一市场发生枪击事件 已致包括凶手在内6人死亡', 0, 4, 194, '2025-07-28 16:26:42', '2025-07-28 15:01:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/163/w1129h634/20250728/9cfb-9054c02cf4cd58b01950c8ea5528cfed.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhziex0188477.shtml', '央视', '## 泰国曼谷市场枪击事件致6人死亡（包括凶手）\n\n**时间**：2025年7月28日  \n**地点**：泰国曼谷一市场  \n\n据泰国媒体报道，当地时间7月28日，泰国曼谷的一市场内发生了一起严重枪击事件。事件导致包括凶手在内的6人死亡。目前尚无关于事件具体原因的详细说明，调查正在进行中。\n\n### 事件概述\n- **伤亡情况**：6人死亡，其中包括凶手。\n- **发生地点**：泰国曼谷某市场，具体市场名称尚未公开。\n- **媒体来源**：央视新闻、澎湃新闻、网易新闻、搜狐新闻等。\n\n事件引发了当地社会的广泛关注，同时也为外国游客敲响了安全警钟。泰国警方正在全力调查事件的起因及更多细节。\n\n### 媒体报道\n- **央视新闻**：总台记者宋焕钰、李敏报道指出，事件发生后，泰国当局迅速采取行动，封锁了现场并展开调查。\n- **澎湃新闻**：详细报道了事件发生的时间和初步伤亡情况。\n- **网易新闻**：提到事件在当地造成了较大震动，相关部门正努力安抚民众情绪。\n- **搜狐新闻**：转载了相关消息，并呼吁公众保持警惕。\n\n目前，事件的详细背景和动机仍在调查中，更多更新将持续发布。', '[\"https://k.sinaimg.cn/n/spider20250728/163/w1129h634/20250728/9cfb-9054c02cf4cd58b01950c8ea5528cfed.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
