INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2891, NULL, '六大纪律全违反！琼海市委原书记田志强，在工作中搞“一刀切”损害群众利益', 0, 1, 21, '2025-07-28 17:28:04', '2025-07-28 16:23:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250728/02a9-2e272a008177bc089b2a928ad0a01886.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-28/doc-infhzies4904346.shtml', '政知见', 'news not found', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250728/02a9-2e272a008177bc089b2a928ad0a01886.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2892, NULL, '美媒爆料：美军挪用核导弹维护费用于翻修特朗普专机', 0, 4, 207, '2025-07-28 18:26:30', '2025-07-28 18:15:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-07-28/doc-infhzpnt5562720.shtml', '环球时报', '### 美媒爆料：美军挪用核导弹维护费用于翻修特朗普专机\n\n根据美媒报道，美国五角大楼近日从核导弹维护升级预算中挪用了9.34亿美元，用于一项机密工程。多名空军官员证实，其中部分资金将用于翻修一架由卡塔尔赠送、交给美国总统特朗普使用的波音747-8飞机。\n\n美国空军高层表示，空军已将所谓的被推迟的“哨兵”洲际导弹计划的多余资金用于改装这架前卡塔尔皇家专机，以用作特朗普总统的“空军一号”。空军部长特洛伊·梅恩克称，五角大楼为“哨兵”导弹项目分配的资金超出了2024年的需求，因此决定将这些多余的资金用于翻新这架波音747客机，改造成特朗普的新专机。\n\n然而，这一决定引发了广泛质疑。尽管空军部长保证这笔挪用不会影响“哨兵”项目的进度，但明眼人都看得出来，这种说法根本站不住脚。“哨兵”导弹是美国用来替换现役“民兵-3”洲际导弹的下一代陆基核威慑核心，原计划总预算约1000亿美元，光研发阶段就要砸300亿。但如今，该项目因为资金挪用和严重超支，陷入了停滞状态。\n\n2025年2月，美国空军不得不暂停“哨兵”项目的部分工作，理由是基础设施建设成本飙升，导致整个项目超支81%，预计总耗资将超过1400亿美元。讽刺的是，这些超支的费用中，有很大一部分是用来更新400多个发射井和铺设光纤网络的，结果却让项目变得更不安全了。\n\n与此同时，特朗普的专机改装却如火如荼地进行着。卡塔尔赠送的这架波音747-8原本是埃米尔的私人座驾，内部装修极尽奢华。要把它改造成符合“空军一号”标准的专机，还需升级通信系统、安装导弹防御设备等，预计实际成本可能高达10亿美元，整个改装过程至少要持续到2030年。\n\n更离谱的是，按照卡塔尔的要求，这架飞机在特朗普卸任后将转赠给他的总统图书馆，继续供特朗普家族使用。这一事件被外界视为权力私有化的新套路，引发了广泛的争议。', NULL);
