INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2894, NULL, '泰方称泰柬边境冲突已致23名泰国人死亡', 0, 4, 194, '2025-07-28 18:27:02', '2025-07-28 17:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/400/w1280h720/20250728/8ee3-7cc805a5481584f4e7ea8ffe3c757565.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhzpnq4803508.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250728/400/w1280h720/20250728/8ee3-7cc805a5481584f4e7ea8ffe3c757565.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2895, NULL, '印度一女子应聘军警晕倒后在救护车上被轮奸，当地卫生部门甩锅给私人机构', 0, 4, 89, '2025-07-28 18:27:12', '2025-07-28 17:16:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250728ac/320/w690h430/20250728/aabf-eee1f80b9ae390347fa00ab3742f4ae8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhzpnv0120017.shtml', '环球时报', 'news not found', '[\"https://k.sinaimg.cn/n/front20250728ac/320/w690h430/20250728/aabf-eee1f80b9ae390347fa00ab3742f4ae8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2896, NULL, '美海军上将警告：除非美国加倍造舰，否则将无法向澳大利亚出售任何核潜艇', 0, 4, 207, '2025-07-28 19:30:27', '2025-07-28 17:33:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/282/w697h385/20250728/2121-51b255c20bb64f919885c66e0a04a80b.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhzpns1574198.shtml', '环球网', '## 美海军上将警告：除非美国加倍造舰，否则将无法向澳大利亚出售任何核潜艇\n\n### 概要\n\n美国海军作战部部长提名人、海军上将达里尔·考德尔（Daryl Caudle）在7月24日向美国国会作证时表示，除非美国将其舰艇生产速度提高一倍，否则将无法根据奥库斯（AUKUS）协议向澳大利亚出售任何弗吉尼亚级核潜艇。这一表态凸显了美国在满足自身防务需求和履行国际协议之间的生产能力瓶颈。\n\n### 背景\n\n根据美国政府的数据，目前美军潜艇舰队的数量比目标值低了约四分之一，而舰艇的生产速度也仅略高于满足自用需求所需速度的一半。目前美国每年生产大约1.13艘弗吉尼亚级核潜艇，但为了满足美国自身防务需求，每年需要生产2艘。如果再加上向澳大利亚出售潜艇的需求，则年产量需达到约2.33艘。\n\n### 关键问题\n\n考德尔坦言，没有简单的解决方案能够提升美国僵化的造船能力。仅靠效率提升或边际改善无法满足与英国和澳大利亚达成的协议。他强调，这需要一次“变革性提升”，即产量必须提高100%。\n\n### 奥库斯协议与挑战\n\n2021年，美国、英国和澳大利亚宣布组建奥库斯（AUKUS）安全联盟，并签署协议，由美英向澳大利亚提供核潜艇。然而，由于美国潜艇生产能力的限制，这一协议面临重大挑战。\n\n澳大利亚已经向美国支付了16亿澳元（约合10.4亿美元），以帮助提振美国的造船业，但效果甚微。澳大利亚前总理马尔科姆·特恩布尔（Malcolm Turnbull）表示，美方潜艇短缺的现实意味着澳大利亚最终可能无法获得弗吉尼亚级潜艇，这将对澳大利亚的国防能力造成严重影响。\n\n随着澳大利亚现役的柯林斯级潜艇即将退役，而英国根据奥库斯协议为澳大利亚设计建造的核潜艇面临延期，澳大利亚在未来10到20年内可能完全不具备潜艇作战能力。\n\n### 国际反应与争议\n\n奥库斯协议自宣布以来一直面临多方质疑。该协议不仅因澳大利亚单方面撕毁与法国的潜艇采购协议而引发外交风波，还因潜在的核扩散风险和对地区安全格局的影响而受到广泛批评。\n\n此外，今年6月，美国彭博社报道称，美国国防部已启动对奥库斯核潜艇协议的重新审查，这进一步加剧了外界对协议能否顺利执行的担忧。\n\n### 结论\n\n当前，美国面临的挑战是如何在满足自身防务需求的同时，履行对盟友的承诺。若无法实现造船能力的突破性提升，奥库斯协议的实施将面临巨大风险，这不仅影响美国与澳大利亚的关系，也可能对全球安全格局产生深远影响。', '[\"https://k.sinaimg.cn/n/spider20250728/282/w697h385/20250728/2121-51b255c20bb64f919885c66e0a04a80b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
