INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2899, NULL, '“影响重大”！美媒爆：美国或将多达30%军力撤出欧洲', 0, 4, 207, '2025-07-28 20:30:28', '2025-07-28 20:00:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250728ac/362/w690h472/20250728/442c-5242f7e6d6ee84283943b6dac9f8c8fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhztut0047800.shtml', '环球网', '### 新闻概要\n\n根据美媒报道，美国可能从欧洲撤出多达30%的军力，这将是一次影响重大的部署调整。美国政治新闻网于7月28日援引匿名北约官员的消息称，尽管五角大楼关于该问题的报告仍在酝酿之中，但这一潜在调整无疑会对欧洲防务格局产生深远影响。\n\n#### 详细内容\n- **背景与报道**：美国在德国的军事存在是欧洲防务的重要支柱，但目前德国对于五角大楼报告的最终内容及其变动的推进速度均缺乏把握。\n- **专家意见**：德国外交关系委员会安全政策高级研究员艾琳·马特莱表示，无论撤军规模如何，关键是要以有序、协调的方式进行，以免让欧洲盟友措手不及。\n- **北约担忧**：自美国总统特朗普上台以来，美国与欧洲的传统盟友关系已受到极大冲击。北约军事委员会主席、意大利海军上将朱塞佩·卡沃·德拉戈内警告称，尽管目前尚无迹象表明美国会撤回承诺参与北约防御计划的部队，但北约必须为美国可能将注意力转向印太地区做好准备。\n\n#### 潜在影响\n这一撤军计划可能加剧欧洲盟国对美国安全承诺的疑虑，并促使北约重新评估其防务战略和资源配置。\n\n### 来源\n- [新浪网新闻中心](https://news.sina.com.cn/w/2025-07-28/doc-infhztut0047800.shtml)\n- [网易](https://www.163.com/dy/article/K5J30NNP0514R9OJ.html)\n- [凤凰网](https://news.ifeng.com/c/8lMZn26Cm3q)', '[\"https://k.sinaimg.cn/n/front20250728ac/362/w690h472/20250728/442c-5242f7e6d6ee84283943b6dac9f8c8fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2900, NULL, '泰国和柬埔寨就停火协议达成一致 28日24时生效', 0, 4, 102, '2025-07-28 20:30:42', '2025-07-28 17:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250728/372/w1280h692/20250728/c7ee-b96e1540978f3e7144efdc899ae365b8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-28/doc-infhzpnq4816515.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250728/372/w1280h692/20250728/c7ee-b96e1540978f3e7144efdc899ae365b8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
