INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2910, NULL, '国家防减救灾委针对北京、河北启动国家救灾应急响应', 0, 1, 3, '2025-07-28 23:30:35', '2025-07-28 23:11:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-28/doc-infhzyak4621880.shtml', '新京报', '国家防灾减灾救灾委员会针对北京、河北启动国家救灾应急响应。\n\n近日，北京市密云、怀柔等地以及河北省承德、张家口等多地持续强降雨，引发严重洪涝灾害。为应对灾情，7月28日，国家防灾减灾救灾委员会针对北京、河北启动了国家四级救灾应急响应。\n\n响应启动后，国家防灾减灾救灾委员会已派出工作组前往灾区，实地查看灾情，并指导和协助地方做好受灾群众的基本生活保障及其他灾害救助工作。同时，为满足灾区的紧急需求，国家防灾减灾救灾委员会办公室、应急管理部联合国家粮食和物资储备局在前期调拨中央救灾物资的基础上，进一步增加调拨4.3万件中央救灾物资，包括折叠床、毛巾被、毛毯、应急照明灯等，并与中国红十字会总会协作，援助2000套家庭应急箱。\n\n此外，通过应急物资政社协同保障机制，相关机构还联合阿里集团、壹基金、爱德基金会、字节跳动基金会、韩红基金会等，向灾区提供应急食品、饮用水、妇婴用品、卫生包等生活物资，以支持当地更好地开展受灾群众紧急转移安置和救灾救助工作。', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2911, NULL, '国家防总针对北京、天津、河北升级启动防汛三级应急响应', 0, 1, 1, '2025-07-28 23:30:49', '2025-07-28 22:55:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-07-28/doc-infhzyap5378419.shtml', '央视', 'news not found', '[]');
