INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2928, NULL, '北京地铁：早高峰最大运力投放时长延长2小时，计划加开临客40余列', 0, 1, 1, '2025-07-29 07:31:41', '2025-07-29 07:23:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250729s/204/w633h371/20250729/7924-57957b852228d9584472c36048739620.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-07-29/doc-infiavfy4154052.shtml', '新京报', 'news not found', '[\"https://k.sinaimg.cn/n/sinakd20250729s/204/w633h371/20250729/7924-57957b852228d9584472c36048739620.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2929, NULL, '提醒！请北京市民非必要不前往风险区', 0, 1, 1, '2025-07-29 07:31:58', '2025-07-29 07:04:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/744/w550h194/20250729/c4fb-4a2e58bf7b9c52c551c0652b1158aca1.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-29/doc-infiavfy4151876.shtml', '央视', 'news not found', '[\"https://k.sinaimg.cn/n/news/transform/744/w550h194/20250729/c4fb-4a2e58bf7b9c52c551c0652b1158aca1.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
