INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2934, NULL, '泰国军方：泰柬边境所有地区已经停火', 0, 4, 102, '2025-07-29 08:30:28', '2025-07-29 08:04:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-07-29/doc-infiavfy4163250.shtml', '界面', '## 泰国军方：泰柬边境冲突地区全面停火\n\n当地时间7月29日凌晨，泰国军方通报称，在7月28日24时（北京时间29日凌晨1时）泰国与柬埔寨无条件停火协议正式生效后，泰柬边境所有冲突地区已全面停火。\n\n此次停火协议是在柬埔寨首相洪玛奈和泰国代理总理普坦于7月28日在马来西亚吉隆坡举行的特别会议后达成的。两国在会议结束后的联合发布会上宣布同意停火，并承诺遵守停火协议。\n\n自7月24日起，泰国和柬埔寨在边境地区发生多日冲突，双方连续交火并互相指责对方违反国际法。根据双方公布的数据，此次冲突已造成上百人伤亡，超过10万民众被迫撤离至安全区域。\n\n目前，停火协议的实施情况正在持续监测中，双方表示将通过对话解决边境争端，以维护地区和平与稳定。', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2935, NULL, '密云水库已下泄流量1.2亿方', 0, 1, 1, '2025-07-29 08:30:46', '2025-07-29 07:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/65/w550h315/20250729/a6d3-e6ee0fa1576209b8f6cf4fcd4ad3b35b.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-29/doc-infiavhe9492411.shtml', '央视新闻客户端', 'news not found', '[\"https://k.sinaimg.cn/n/news/transform/65/w550h315/20250729/a6d3-e6ee0fa1576209b8f6cf4fcd4ad3b35b.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2936, NULL, '北京极端强降雨已造成30人死亡，北部山区损失严重！女子亲历：铲车车斗伸至二楼防盗窗救人转移', 0, 1, 1, '2025-07-29 08:31:00', '2025-07-29 07:45:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/483/w550h733/20250729/a1b8-26d71d44c2c2b3a2f9fdac682518bebc.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-29/doc-infiavhc4918253.shtml', '新闻晨报', '# 北京极端强降雨已造成30人死亡，北部山区损失严重\n\n## 概述\n\n北京近期连续遭遇极端强降雨，导致重大灾害。截至2025年7月28日24时，全市平均降水量达到165.9毫米，其中密云郎房峪和朱家峪的最大降水量达到了543.4毫米。最大降水强度出现在怀柔东峪，26日22时至23时的降水量达到了95.3毫米。\n\n## 人员伤亡及转移\n\n- **死亡人数**：全市因灾死亡30人，其中密云区28人，延庆区2人。\n- **人员转移**：全市累计转移80332人，转移人数最多的三个区分别为密云、怀柔和房山。具体数据如下：\n  - 密云区：19个乡镇转移16934人\n  - 怀柔区：15个乡镇转移10464人\n  - 房山区：21个乡镇转移9904人\n\n## 基础设施损毁\n\n- **道路损毁**：受灾地区道路损毁共计31处，涉及兴阳线、西火路等16条线路仍未修通。\n- **电力中断**：136个村庄电力中断。\n- **通信设施损毁**：光缆损毁62条，基站退服1825个。\n\n## 应对措施\n\n灾情发生后，北京市委市政府深入贯彻落实习近平总书记关于防汛救灾工作的重要指示精神和李强总理的批示，进一步强化防汛抗汛措施，全力搜救失联人员，并及时调配救援力量和救灾物资，妥善安置受灾群众，尽最大努力减少伤亡。\n\n## 预警及应对\n\n- **暴雨预警**：北京市气象台2025年07月29日07时10分降级发布暴雨黄色预警信号，预计当前至29日20时，北京市降雨持续，部分地区小时雨强可达50毫米以上，山区及浅山区出现山洪、泥石流、滑坡等次生灾害风险较高，低洼地区可能出现积水。\n- **交通影响**：因降雨预警，北京市郊铁路7月29日全部停运。部分列车在7月30日也将临时停运。\n- **景点闭馆**：故宫博物院和中国国家博物馆根据防汛一级应急响应要求，于7月29日临时闭馆一天，以确保观众安全。\n\n## 呼吁与提醒\n\n在灾情期间，呼吁广大北京市民关注天气预报预警，非必要不前往风险区域。同时，提醒市民注意防范山洪、泥石流、滑坡等次生灾害以及低洼地区的积水问题。', '[\"https://k.sinaimg.cn/n/news/crawl/483/w550h733/20250729/a1b8-26d71d44c2c2b3a2f9fdac682518bebc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/503/w550h753/20250729/5636-0961d931122538cfc27af0fc465af66a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
