INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2944, NULL, '美国内华达州一起枪击事件造成3死3伤', 0, 4, 207, '2025-07-29 09:30:31', '2025-07-29 09:10:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-07-29/doc-infiavha0960406.shtml', '新华视点', '### 美国内华达州一起枪击事件造成3死3伤\n\n据新华社洛杉矶7月28日电（记者高山）报道，美国内华达州警方于28日证实，一名枪手当天早晨在里诺市的一家大型综合度假酒店及赌场门外朝人群开火，造成3人死亡、3人受伤。\n\n警方官员在新闻发布会上表示，枪击事件发生在当地一家大型综合度假酒店及赌场的代客泊车区。嫌疑人是一名男性，在到达现场后掏枪行凶。据进一步报道，枪支一度发生故障，嫌疑人在排除故障后开始向人群射击，击中5人，其中3人死亡，3人受伤。\n\n嫌疑人逃离现场时与保安发生交火，最终受伤被捕，并被送往医院救治。\n\n这起事件再次引发了公众对公共场所安全措施的担忧，相关方面也在进一步调查事件的详细情况。\n\n相关报道来源：\n- [人民网](https://world.people.com.cn/n1/2025/0729/c1002-40531786.html)\n- [新华网](http://big5.news.cn/gate/big5/www.xinhuanet.com/world/20250729/7fe5084f0dc940658b3ff08e888b5bef/c.html)', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2945, NULL, '纽约曼哈顿发生枪击，警察在内至少6人中枪，嫌疑人已死亡！事发区域系黑石、NFL总部办公地', 0, 4, 207, '2025-07-29 09:30:42', '2025-07-29 08:44:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250729/201/w1080h721/20250729/56c6-a48c536708b066753da1627518cdbbfe.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-29/doc-infiavha0949595.shtml', '每日经济新闻', 'news not found', '[\"https://k.sinaimg.cn/n/spider20250729/201/w1080h721/20250729/56c6-a48c536708b066753da1627518cdbbfe.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250729/133/w560h373/20250729/910f-30cb9181fc9213bf375a9012e0c87700.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2946, NULL, '岛内首波“大罢免”全遭否决 赖清德的第一只“替罪羊”是他', 0, 1, 34, '2025-07-29 09:31:24', '2025-07-29 09:26:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/276/w550h526/20250729/facf-1d90fa0ce7be9cacac55ca2109ef2f25.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-29/doc-infiazpw4071825.shtml', '新浪新闻综合', '## 新闻概要\n\n### 岛内首波“大罢免”全遭否决，赖清德的第一只“替罪羊”是他\n\n在7月26日举行的台湾岛内首波“大罢免”投票中，针对24名国民党民意代表及新竹市长高虹安的罢免案全部遭到否决。这一结果对民进党而言无疑是一个重大的政治打击。\n\n根据报道，前民代郭正亮分析指出，如果罢免行动失败，民进党秘书长林右昌可能会成为赖清德政府的第一只“替罪羊”。他可能因此被“踢出家门”。这一观点反映了外界对于罢免失败后民进党内可能进行问责的猜测。\n\n此外，蓝绿阵营在此次罢免案中的攻防战异常激烈，但蓝营（国民党）似乎占据了优势。尽管赖清德试图通过寻找“替罪羊”来缓解政治压力，但整体局势显示，民进党在此次罢免风波中未能达成预期目标。\n\n更多相关报道：\n\n- [大罢免若失败，赖清德要找替罪羊？郭正亮点名这个人第一个滚蛋 - 网易](https://www.163.com/dy/article/K46RT098055080L4.html)\n- [赖清德的第一只“替罪羊”是他 - 腾讯新闻](https://news.qq.com/rain/a/20250728A09OP000)\n- [蓝委这回稳了！赖清德急找替罪羊？柯建铭成新目标 - 搜狐](https://www.sohu.com/a/913694429_121145184)', '[\"https://k.sinaimg.cn/n/news/transform/276/w550h526/20250729/facf-1d90fa0ce7be9cacac55ca2109ef2f25.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
