INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2956, NULL, '乌克兰和白俄罗斯黑客组织联手“突袭”俄航：信息关键系统遭入侵，42个航班一度被取消，7000台服务器受影响', 0, 4, 164, '2025-07-29 10:30:44', '2025-07-29 09:29:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250729/510/w840h470/20250729/019f-947b366b91d0f06fc04f4ed7f726f2ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-29/doc-infiazpy0861858.shtml', '每日经济新闻', '### 乌克兰和白俄罗斯黑客组织联手“突袭”俄航：信息关键系统遭入侵\n\n- **事件概述**  \n  当地时间7月28日，俄罗斯国际航空公司（俄航）发布消息表示，其公司信息系统遭到网络攻击，导致关键系统被入侵。受此影响，俄航被迫取消42个航班，其中大多数为俄罗斯国内航班，但也影响到了部分飞往白俄罗斯和亚美尼亚的航班。此外，约7000台物理服务器和虚拟服务器受到影响，黑客组织甚至控制了管理层和员工的个人电脑，并复制了大量数据。\n\n- **黑客组织声明**  \n  乌克兰和白俄罗斯的两个黑客组织在一份联合声明中宣称对此次攻击负责。他们表示，这次网络攻击是对乌克兰方面的支持。据报道，黑客组织声称他们已经入侵了俄航的企业网络长达一年之久，并在此过程中逐步摧毁了约7000台服务器，同时入侵了关键系统。\n\n- **机场影响**  \n  此次攻击导致大量旅客滞留在莫斯科谢列梅捷沃国际机场，许多航班延误或取消，对航空运营造成严重影响。\n\n- **俄航应对措施**  \n  俄罗斯国际航空公司表示，专家团队正在努力将风险降至最低，并尽快恢复正常运营。对于被取消航班的旅客，俄航提供退款或改签未来10天内其他航班的服务。\n\n- **官方反应**  \n  莫斯科检察部门已对该事件展开调查。俄罗斯总统新闻秘书佩斯科夫表示，俄方对此次网络攻击感到震惊，并称将等待相关部门给出合理的解释。\n\n- **相关报道来源**  \n  - [网易新闻](https://www.163.com/dy/article/K5KHMVR50512B07B.html)  \n  - [央视新闻](https://content-static.cctvnews.cctv.com/snow-book/index.html?item_id=12631104063634396631&channelId=1119&toc_style_id=feeds_default)  \n  - [新浪新闻](https://news.sina.cn/gj/)', '[\"https://k.sinaimg.cn/n/spider20250729/510/w840h470/20250729/019f-947b366b91d0f06fc04f4ed7f726f2ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250729/400/w1280h720/20250729/dd05-073236c51f8f3458850907ecd8250099.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
