INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2966, NULL, '“唐纳德德德德” 美媒曝马克龙常与特朗普进行非正式通话，在称呼对方名字时还拉长音', 0, 4, 207, '2025-07-29 11:30:31', '2025-07-29 11:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250729ac/390/w691h499/20250729/3dc0-70cad3ae31ae083980cd4a47c0419955.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-29/doc-infiazqa9455568.shtml', '环球网', '### 新闻概要\n\n根据相关报道，美媒透露法国总统埃马纽埃尔·马克龙经常与美国前总统唐纳德·特朗普进行非正式的私人通话。这些通话虽然在内容上并没有特别的约束，但其随意性和轻松的氛围与特朗普平时在公开场合所表现的即兴风格并无太大区别，然而，这种风格却让电话另一端的助理们感到惊讶。\n\n报道中提到，马克龙和特朗普之间的对话更像是兄弟之间的问候。例如，在称呼对方名字时，马克龙会以一种拉长音的方式称呼特朗普为“唐纳德德德德”，显示出两人之间的一种轻松和亲密的交流方式。这种非正式的互动方式在国际领导人之间的沟通中并不常见，也凸显了两人独特的个人关系。\n\n来源：[凤凰网](https://news.ifeng.com/c/8lNbUr42kr4)', '[\"https://k.sinaimg.cn/n/front20250729ac/390/w691h499/20250729/3dc0-70cad3ae31ae083980cd4a47c0419955.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
