INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2988, NULL, '特朗普配方，被拒了？', 0, 4, 207, '2025-07-29 15:30:26', '2025-07-29 12:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/15/w550h265/20250729/4c89-22c586a655ed45604f555931c24b28a1.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-07-29/doc-inficncz1085464.shtml', '中国新闻周刊', '特朗普配方，被拒了？\n\n近日，有关特朗普试图推动可口可乐公司更改其产品配方的新闻引发了广泛关注。根据报道，特朗普在当地时间7月16日于其社交平台表示，可口可乐公司已同意在美国使用真正的蔗糖生产可乐。然而，这一说法随即遭到了可口可乐公司的否认，该公司在回应美媒时明确表示，并未承诺做出任何改变。\n\n背景信息显示，特朗普长期以来是健怡可乐的忠实消费者，并曾在白宫椭圆形办公室安装可乐按钮，以便随时享用冰镇的健怡可乐。尽管如此，他此次对可口可乐配方的关注似乎并未得到公司的积极响应。\n\n对于特朗普的提议，玉米加工协会主席约翰·博德表达了反对意见，他认为用蔗糖取代高果糖玉米糖浆不仅不利于美国食品制造业的就业情况，还会对农场收入产生负面影响。此外，一些食品科学家也指出，虽然高果糖玉米糖浆和蔗糖在风味上有细微差别，但前者在成本上具有优势。\n\n面对这一争议，可口可乐公司在给Axios新闻网的一份声明中表示：“我们感谢特朗普总统对我们标志性品牌可口可乐的热情。我们将很快分享更多有关可口可乐产品系列中创新产品的细节。”\n\n尽管特朗普的提议未能获得可口可乐公司的认可，但这无疑再次将公众的目光聚焦于这位前总统及其对商业领域的持续影响力。\n\n参考资料：\n- [可口可乐拒绝特朗普改配方](https://m.gmw.cn/2025-07/17/content_1304085491.htm)\n- [特朗普配方，被拒了？](https://news.ifeng.com/c/8lNkxXlMFAM)', '[\"https://k.sinaimg.cn/n/news/crawl/15/w550h265/20250729/4c89-22c586a655ed45604f555931c24b28a1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/40/w550h290/20250729/82a0-a4c1ee28969814b2003a128c3e230af5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/700/w550h150/20250729/84b5-b2ebe4d88be680a94f95563642546ce4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/193/w550h443/20250729/fb79-a6983a59b8309e1af7406d90bd494759.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/233/w550h483/20250729/3e85-066275b97a2eec50528283d23db5f1e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/174/w550h424/20250729/3404-ef6644aebfafe0aa733a6c3067445dbb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/663/w277h386/20250729/ece0-92f6565f190e6e7fd80d6ef0ecba2ec8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/408/w486h722/20250729/b4b3-612063efbd2b41643e1ff00ebb5cb0dc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/591/w417h174/20250729/3da2-c39c0a089a8d54be6d8f33fc23f20c52.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/10/w550h260/20250729/9eea-97ee5c24679fe8f3b9ba25d19de2e20e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/39/w550h289/20250729/b9d8-b969067de2d7a528b8c032fb15ad69fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (2989, NULL, '“水势太猛，好吓人！”北京密云居民讲述水灾：60多岁第一次见这么大水，已平安转移', 0, 1, 1, '2025-07-29 15:30:38', '2025-07-29 15:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/601/w548h853/20250729/1910-c0c933a1475b04d527148e0d9f4b9f95.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-07-29/doc-inficncw9316174.shtml', '潇湘晨报', 'news not found', '[\"https://k.sinaimg.cn/n/news/crawl/601/w548h853/20250729/1910-c0c933a1475b04d527148e0d9f4b9f95.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/562/w548h814/20250729/3e3f-cb98841083901aac56270f268c8ee353.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/606/w545h861/20250729/c122-27faa59a22a661d282adc46a92d57fff.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
