INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3933, 171, '英国央行第五次降息，通胀率预计9月达4%后回落', 1, 4, 206, '2025-08-10 11:02:23', '2025-08-10 11:02:23', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250810_009.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250810_009_thumb.png', NULL, NULL, NULL, NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3934, 171, '法国南部林火持续，过火面积超170平方公里', 1, 4, 66, '2025-08-10 11:02:24', '2025-08-10 11:02:24', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250810_0011.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250810_0011_thumb.png', NULL, NULL, NULL, NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3935, NULL, '美警方：巴尔的摩发生大规模枪击事件', 0, 4, 124, '2025-08-10 11:30:20', '2025-08-10 11:06:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/2185-b80228e8ebededb5858d20351368b1b3.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-10/doc-infkniae9966487.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/2185-b80228e8ebededb5858d20351368b1b3.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月9日，美国巴尔的摩警方通过社交媒体称，他们正在对当日晚发生在该市西北部街区的一起“<font cms-style=\"font-L strong-Bold\">大规模枪击事件</font>”做出响应。</p> \n<p cms-style=\"font-L\">　　据悉，<font cms-style=\"font-L strong-Bold\">事发地区多条街道已被封锁</font>。目前事态还在发展中，尚无关于枪击事件的其他细节。（总台记者 赵淼）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/2185-b80228e8ebededb5858d20351368b1b3.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3936, NULL, '柬埔寨否认在柬泰边境埋设新地雷 要求泰方尊重边界协议', 0, 4, 102, '2025-08-10 11:30:28', '2025-08-10 10:11:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/df59-224f0b68251a8102a5c133d707a7ff95.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-10/doc-infknhzx7054938.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月10日，柬埔寨外交部发言人宗松里<font cms-style=\"font-L strong-Bold\">否认泰国外交部关于柬埔寨在柬泰边境埋设新地雷，造成三名泰国士兵触雷受伤的指控</font>。</p> \n<p cms-style=\"font-L\">　　柬埔寨要求泰国充分尊重边界总委员会特别会议达成的协议，尤其是要保持当前状况，双方不得向对方移动或做出任何行动。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　新闻多看点</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/df59-224f0b68251a8102a5c133d707a7ff95.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△资料图\">\n <span class=\"img_descr\">△资料图</span>\n</div> \n<p cms-style=\"font-L\">　　泰国陆军第二军区当地时间9日在社交媒体平台通报说，3名泰军士兵当天上午在泰国与柬埔寨边境巡逻时踩中地雷受伤。通报说，其中一人左脚踝以下被炸断，还有一人手臂及背部受伤，另一人鼓膜在爆炸冲击中受损，3人均已送往当地医院。泰国陆军发言人文泰·苏瓦里9日就此事表示，柬方所为明显违反禁止使用杀伤性地雷的《渥太华公约》。</p> \n<p cms-style=\"font-L\">　　柬埔寨排雷行动和援助受害者管理局9日晚驳斥泰方指控说，针对泰国士兵受伤事件，目前尚未进行任何官方透明调查。该机构呼吁各方在公开声明中保持克制，“毫无根据的指控”有可能破坏停火协议下建立的合作精神和信任。</p> \n<p cms-style=\"font-L\">　　（总台记者 付新日）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">泰方指责柬方违反《渥太华公约》 柬方驳斥&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">泰国陆军说3名士兵在泰柬边境巡逻时触雷受伤&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250810/251/w1600h251/20250810/7658-giffa96e468b77c7f8b6974f4a412503a8e.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/df59-224f0b68251a8102a5c133d707a7ff95.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3937, NULL, '广东一周新增1387例基孔肯雅热本地病例，佛山疫情快速上涨势头已得到初步遏制', 0, 2, 197, '2025-08-10 11:30:38', '2025-08-10 11:27:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-10/doc-infknhzz1646643.shtml', '南方日报', '<p>　　来源：南方日报</p> \n<p>　　8月10日上午，广东省疾控局发布通告：2025年8月3日0时至8月9日24时，全省新增报告1387例基孔肯雅热本地病例，未报告重症和死亡病例。病例分布在佛山1212例，广州103例，湛江39例，清远6例，深圳、珠海各5例，中山4例，惠州3例，韶关、东莞各2例，汕头、江门、阳江、潮州、揭阳、云浮各1例。</p> \n<p>　　<strong>专家解读：</strong></p> \n<p>　　广东省疾控中心传染病预防控制所所长、传染病防控首席专家康敏指出：基孔肯雅热是经伊蚊（俗称“花斑蚊”）叮咬传播的病毒性疾病。伊蚊偏好在小型的洁净水体中繁殖。因此，翻盆倒罐清积水，特别是清理各类小型容器积水，是控制疫情传播的基础。预防基孔肯雅热的关键是清积水、灭成蚊、防叮咬。没有积水就没有蚊虫孳生，没有蚊虫就没有疫情传播。</p> \n<p>　　康敏指出，佛山市疫情快速上涨势头已得到初步遏制，近期防控成效进一步巩固。全省新增报告病例数呈现连续下降趋势，但疫情波及面广，加上全球基孔肯雅热疫情高发，我省对外交流频繁，境外输入风险持续存在；同时叠加汛期台风、降雨等天气影响，蚊媒活动频繁，疫情防控还不能松劲。</p> \n<p>　　在此，我们呼吁市民积极响应省委、省政府关于开展爱国卫生运动的号召，共同参与防蚊灭蚊工作，践行“防蚊灭蚊七招工作法”：家家户户点蚊香、挂蚊帐、装纱窗、清积水、清垃圾，人人出门涂驱蚊水，一早一晚灭成蚊。请市民朋友积极参与“1130”防蚊灭蚊行动：上下班1分钟清积水，每周1次大扫除，每天3分钟排查孳生地，携手共建无蚊场所。此外如果您近期有基孔肯雅热流行地区旅居史，或者有明确的蚊虫叮咬史，出现发热、关节疼痛、皮疹等症状，请及时前往医疗机构就诊，并主动向接诊医生说明。</p> \n<p>　　基孔肯雅热可防、可控、可治，让我们立刻行动起来，从我做起，从家庭做起，从身边做起：清积水、清死角、灭蚊虫；挂蚊帐、装纱窗、防叮咬，用行动阻断疫情，共同守护健康家园。</p> \n<p>　　南方+记者 张梓望</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">广东发现基孔肯雅热</a>\n</div> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3938, NULL, '“男游客突然从背后对工作人员锁喉、捂嘴，将其摁倒在地，其他游客哄抢”，河南万岁山武侠城回应', 0, 1, 16, '2025-08-10 11:30:45', '2025-08-10 10:37:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/312/w399h713/20250810/6799-ea1da979ad297852aad5ec6960f4b4c2.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infkniaf7040180.shtml', '极目新闻', '<p cms-style=\"font-L\">　　8月9日，有网民发视频称，河南开封万岁山武侠城景区一工作人员被游客锁喉、捂嘴、摁倒在地。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/312/w399h713/20250810/6799-ea1da979ad297852aad5ec6960f4b4c2.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/default/crawl/305/w401h704/20250810/a17f-561714951cb950a15ef5d8f6a3018325.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　视频中，被锁喉的工作人员表示会受伤，但哄抢道具的游客却置之不理。</p> \n<p cms-style=\"font-L\">　　目击者称，事发8月7日，起因是游客哄抢工作人员手中道具。另一目击者称，当时一男游客突然从背后对工作人员锁喉、捂嘴，其他游客一同哄抢。</p> \n<p cms-style=\"font-L\">　　另据大河报，涉事工作人员小狼8月9日发视频回应：“可能他们玩得太开心忘我了，加上晚上天热，我也没力气了。”他坦言自己虽希望每位游客尽兴，但更呼吁大家把安全放在首位，“开心游玩，安全第一”。</p> \n<p cms-style=\"font-L\">　　景区工作人员向记者证实，事发后已派出安保人员及时制止，并强调目前NPC小狼“身体情况很好”，也未感受到游客恶意，认为这属“互动中的意外”。景区其实早已在大门口张贴禁止抢夺银票的告示，明确为保护游客与NPC安全。尽管遭遇不愉快，小狼仍以热情服务游客，其专业态度更获得了景区通报表扬。</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/312/w399h713/20250810/6799-ea1da979ad297852aad5ec6960f4b4c2.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/305/w401h704/20250810/a17f-561714951cb950a15ef5d8f6a3018325.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3939, NULL, '“津”彩跃动，彰显“何以中国”深厚底气', 0, 1, 2, '2025-08-10 11:30:55', '2025-08-10 10:34:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-10/doc-infkniaf7038802.shtml', '环球网', '<p>　　渤海之滨，海河之畔，一场文化盛宴如约而至。8月9日，“何以中国·和合共生”网络主题宣传活动在天津古文化街启幕，启动仪式分为“河海津韵”“津非昔比”“天下一家”三个篇章，多维立体展现独树一帜的津派文化，让世界感受中华文化魅力。</p> \n<p>　　文化根脉的当代传承，彰显“何以中国”深厚底气。中华优秀传统文化是民族的根脉。新时代要传承发展这些优秀内容，既需守护其本真，更要赋予其生生不息的时代活力。杨柳青年画传承人苏丽妍，二十载守护匠心，其“哪吒”系列文创、数字藏品等为四百年艺术注入青春血脉；非遗音乐家褚琪桂梓一曲《九河谣》，流淌着津腔津韵的深沉律动；天津大学霍元甲玄孙霍静虹以武证道，一招一式皆是文化自信的生动彰显；《镇馆之宝》节目，通过可视化叙事手法，将大运河文明、近代开埠风云、津门民俗精华与平津战役红色精神有机串联……立足津门大地，深耕中华优秀传统文化资源沃土，讲好中国故事的“津”彩篇章，生动诠释了“何以中国”深厚底气。</p> \n<p>　　科技创新的强劲驱动，赋予“和合共生”澎湃动能。发展新质生产力是推动高质量发展的内在要求和重要着力点。在津沽大地，科技工作者正书写着新时代“天工开物”的壮丽篇章。飞腾公司首席科学家窦强团队，勇闯国产CPU“从0到1”的原始创新之路，为国家信息产业安全筑基；国家超级计算天津中心首席科学家孟祥飞，以“天河”系列超级计算机为利器，拓展人类认知边界，赋能千行百业；天津大学刘秀云院长团队，致力于推动前沿脑机接口技术在医学重症领域的率先应用，点亮生命新希望……向新而行、攀高而上，天津以科技创新塑造发展新动能，为“和合共生”理念注入澎湃动力，彰显了中国式现代化的实践伟力。</p> \n<p>　　文明互鉴的开放胸怀，绘就“天下大同”和美愿景。文明因交流而多彩，文明因互鉴而丰富。海河之畔，文明交融的故事温暖人心。南开大学俄籍学子巴丽娜立志“以汉字为桥，把中国故事讲给世界听”；土耳其青年欧阳岚于南开园中领悟东方智慧，视其为宝贵人生际遇；马达加斯加青年唐磊以快板和相声为媒，让中华曲艺焕发青春光彩；《京津冀240小时》《美美与共》等节目，生动记录了各国青年在津求学、生活、筑梦的温馨画面……在2025年上海合作组织峰会即将到来之际，天津作为峰会主办城市，正以其深厚文化底蕴与时代魅力，吸引世界目光，为促进民心相通、推动构建人类命运共同体贡献中国智慧与天津力量。</p> \n<p>　　津门故里的弦歌不辍，既是对中华优秀传统文化生生不息的深情礼赞，亦是对新时代中国昂扬气象的铿锵宣言。天津以其深厚积淀与创新活力，向世界展示了一个灿烂文明走向伟大复兴的从容步伐。这步伐中，有传统血脉的汩汩流淌，有科技之光的璀璨闪耀，更有文明交流互鉴的宏大交响，共同汇聚成中华文明面向未来的磅礴自信。（甄郝）</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3946, NULL, '美国巴尔的摩大规模枪击事件致6人受伤', 0, 4, 124, '2025-08-10 12:30:13', '2025-08-10 11:19:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/da2f-ce12f706a6ca535d6abd7d49dee24262.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-10/doc-infknhzx7070220.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/da2f-ce12f706a6ca535d6abd7d49dee24262.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，美国巴尔的摩当地时间8月9日发生的<font cms-style=\"font-L strong-Bold\">大规模枪击事件造成6人受伤，包括一名5岁女童</font>。</p> \n<p cms-style=\"font-L\">　　据悉，女童手部中枪，<font cms-style=\"font-L strong-Bold\">伤者中1人情况危急</font>。有目击者称，枪击发生前，当地举办了社区聚会。</p> \n<p cms-style=\"font-L\">　　美国巴尔的摩警方9日通过社交媒体称，他们正在对当日晚发生在该市西北部街区的一起“大规模枪击事件”做出响应。事发地区多条街道已被封锁。（总台记者 赵淼）</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">相关新闻</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><a href=\"https://news.sina.com.cn/w/2025-08-10/doc-infkniae9966487.shtml\" data-comos-dataid=\"comos:nfkniae9966487\"><font cms-style=\"font-L strong-Bold color240\">美警方：巴尔的摩发生大规模枪击事件&gt;&gt;</font></a></font></p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250810/da2f-ce12f706a6ca535d6abd7d49dee24262.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3952, NULL, '北京8月10日发布山洪灾害蓝色预警', 0, 1, 1, '2025-08-10 13:30:17', '2025-08-10 13:25:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-10/doc-infknpka9870214.shtml', '千龙网中国首都网', '<p cms-style=\"font-L\">　　千龙网北京8月10日讯 据北京市突发事件预警信息发布中心最新消息，北京市水务局与市气象局2025年8月10日13时发布山洪灾害蓝色预警：预计8月10日13时至14日8时，我市密云区、平谷区、延庆区、怀柔区可能发生山洪灾害，请公众远离山洪沟道，暂停涉山涉水户外活动，防范山洪灾害。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3953, NULL, '8月10日13时，北京发布山洪灾害蓝色预警', 0, 1, 1, '2025-08-10 13:30:26', '2025-08-10 13:01:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/557/w550h807/20250810/5c53-d105794559dd46fcac3de64b83b1c451.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infknpkc6950940.shtml', '北京日报客户端', '<p cms-style=\"font-L\">　　市水务局与市气象局2025年8月10日13时发布山洪灾害蓝色预警：预计8月10日13时至14日8时，我市密云区、平谷区、延庆区、怀柔区可能发生山洪灾害，请公众远离山洪沟道，暂停涉山涉水户外活动，防范山洪灾害。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/557/w550h807/20250810/5c53-d105794559dd46fcac3de64b83b1c451.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/557/w550h807/20250810/5c53-d105794559dd46fcac3de64b83b1c451.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3954, NULL, '“爬楼爬不动，取快递要走10多分钟”，杭州78岁阿姨求助：为什么现在快递不送上门？加点费用也可以……', 0, 2, 84, '2025-08-10 13:30:37', '2025-08-10 08:09:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/2db2-00ba20f056893dd7eff4a7bd2dbd0d50.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infknpkc6953647.shtml', '都市快报', '<p cms-style=\"font-L\">　　来源：都市快报</p> \n<p cms-style=\"font-L\">　　姚大妈打进85100000热线：我住在拱墅区永丰巷1号4楼，<font cms-style=\"font-L strong-Bold color210\">我78岁了，现在很多快递不送货上门，直接放到驿站，</font>很多老年人都会遇到这种情况，我天天看都市快报，所以打电话问一问，<font cms-style=\"font-L strong-Bold color210\">现在快递为什么不送上门？加点费用也可以……</font></p> \n<p cms-style=\"font-L align-Center color210\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">下楼取快递要走10多分钟</font></p> \n<p cms-style=\"font-L\">　　永丰巷小区建于上世纪八九十年代，姚大妈和老伴住了30多年。</p> \n<p cms-style=\"font-L\">　　门口放了一箱饼干，姚大妈说是电视购物买的，<font cms-style=\"font-L strong-Bold color210\">因为货到付款，快递小哥会送到门口，然后收钱。</font>姚大妈还拿出之前从电视购物花1600元买的叶黄素蓝莓，“电视上说对眼睛好，去年买的，现在还在吃”。记者看了下，产品包装上写有“保健”“维生素E”等字样。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/2db2-00ba20f056893dd7eff4a7bd2dbd0d50.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　姚大妈说，<font cms-style=\"font-L strong-Bold color210\">她和老伴年纪大了，爬楼走路吃力，下楼不多，不太买菜，有时去附近世纪联华超市买点馒头，“早饭午饭我们只吃一顿，晚饭让邻居帮我们烧，矿泉水是农夫山泉送到门口”。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color210\">网上买的主要是生活日用品，都是儿子手机下单。</font>儿子住在文一路，收货地址填到永丰巷家里，<font cms-style=\"font-L strong-Bold color210\">有的快递小哥会送到门口，大多数会放到孩儿巷的快递驿站，要自己下楼走过去拿。上个月儿子帮她在网上买了衣服，“后来我也去拿了，还好是衣服，不算很重”。</font></p> \n<p cms-style=\"font-L\">　　“儿子说改一下邮寄地址，改成他住的地方，周末来看我们顺便送过来。”姚大妈家里现在用的餐巾纸、洗衣液等生活用品，都是快递送到儿子住处，儿子周末开车送过来的。</p> \n<p cms-style=\"font-L\">　　“儿子周末还要专门跑一趟，我们小区停车不容易，要停到娃哈哈大厦停车场，停车要收费，还要从车上搬到家里来，儿子也吃力的……”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color210\">“年纪大爬楼爬不动，还要走10多分钟路去拿快递，身体吃不消。有时候送快递的年轻人也会送上来，但总是麻烦他们也不太合适，</font>还是希望快递公司能考虑老年人需求，统一送上门。<font cms-style=\"font-L strong-Bold color210\">天气热，他们也辛苦，多付费也不打紧……”</font></p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/96b3-5edc574bd53a40a64996bbf373ce673f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L align-Center color210\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">快递小哥：没有明确要求的一般会放到驿站</font></p> \n<p cms-style=\"font-L\">　　永丰巷小区靠近中山北路有丰巢柜，很多快递员来这边存放快递，一位顺丰快递小哥说，他们的快递基本都直接送上门。</p> \n<p cms-style=\"font-L\">　　一位取快递的居民说，<font cms-style=\"font-L strong-Bold color210\">他知道顺丰和京东直接送到家，其他快递会存到这个丰巢柜，或者放到孩儿巷的驿站</font>。“这些年我自己的快递，要么送到家里，要么放到丰巢柜，要么去孩儿巷的驿站取。只要你跟快递员说具体放在哪里，基本都会放好的。”</p> \n<p cms-style=\"font-L\">　　圆通快递童师傅负责这一片两年多了，<font cms-style=\"font-L strong-Bold color210\">他说一般普通快递，会放在孩儿巷那边的快递网点。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/1c32-0c353dca41ad2fec351f31219b0a8803.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　“以前我们把没有特别说明的普通快递放在丰巢柜，<font cms-style=\"font-L strong-Bold color210\">经常有人忘了取，有的老人取快递不知道怎么操作，然后就有投诉，每个投诉要扣100块钱，</font>后来我们就把没有特别要求的快递，<font cms-style=\"font-L strong-Bold color210\">暂时都放在孩儿巷驿站，那边不收超时费。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color210\">“只要客户打电话给我们，都会按照他们要求，要送上门的会送上门，放丰巢柜的放丰巢柜，</font>没办法，我们是服务行业，每个人情况都不一样，只能尽量去满足。”</p> \n<p cms-style=\"font-L\">　　记者在姚大妈家楼下搜索了一下，最近的圆通妈妈快递驿站在永丰巷9号楼，距离<font cms-style=\"font-L strong-Bold color210\">311米。</font>小区里停的车多，道路较窄，路面不太平坦，出小区要过马路，路上来往车辆行人多，<font cms-style=\"font-L strong-Bold color210\">记者走到快递驿站花了5分钟。姚大妈说她出门下楼去拿一趟快递，路上要10多分钟。</font></p> \n<p cms-style=\"font-L align-Center color210\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">快递驿站负责人：只要老人提需求，我们肯定送上门</font></p> \n<p cms-style=\"font-L\">　　这个快递点虽然是圆通，但记者在快递柜上看到申通、中通等其他公司快递件。</p> \n<p cms-style=\"font-L\">　　圆通妈妈快递驿站负责人告诉记者，快递点就是给周边居民提供送货服务的，每天取件发货几千件，周边邻居大多都熟悉。“做服务业，说到底就是拼服务和质量，还有人情。快递点竞争也激烈，能开得下去的，首先就是服务要到位，大家相信你才选择你。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/default/crawl/28/w472h356/20250810/bce1-f65ecaba7d29f54622b7f0cc0e22cd1d.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　“竹竿巷周边几个小区都由我这边派送，快递柜上的货件，主要是年轻人白天上班，不便收件，先寄存在这里。针对老年人的服务，我们站点专门雇了一个小哥，他每天就是上上下下给老人送货、取件。”</p> \n<p cms-style=\"font-L\">　　这位负责人说，<font cms-style=\"font-L strong-Bold color210\">购物时只要标注留言“老人”“送货上门”，这样的快件就不会入库放货架，有专门的快递员派送</font>。“如果忘了备注，<font cms-style=\"font-L strong-Bold color210\">给驿站打个电话，我们也会安排，不会另外收费。</font>有的老人来站点取件，我也会和他（她）说，您家在哪里，下次我给您送上门。如果老人健康，没这方面需求，我们也尊重他们的选择。毕竟年龄大的人，走路不方便，为了取快递摔一跤，太不合适。”</p> \n<p cms-style=\"font-L\">　　圆通妈妈快递驿站负责人留下了姚大妈的联系方式和家庭住址，现场打电话告诉她，以后儿子网上买东西，可以备注一下，<font cms-style=\"font-L strong-Bold color210\">“我们包管送货上门，我们小哥每天派送100多件，不差你们家一件的，不用另外付费”。</font></p> \n<p cms-style=\"font-L\">　　姚阿姨听后很高兴，连说“好的好的”“谢谢谢谢”。</p> \n<p cms-style=\"font-L\">　　竹竿巷社区网格长厉剑告诉记者，竹竿巷社区离西湖近，周边医院多，生活方便适合养老，但老龄化问题也突出，<font cms-style=\"font-L strong-Bold color210\">60岁以上老人超过2000人，占总人口的三分之一，80岁以上老人550多人。“服务好老人，是社区的重点工作。”</font></p> \n<p cms-style=\"font-L\">　　社区旁边就是老年食堂，80岁、90岁以上老人吃饭有折扣，行动不方便的，食堂提供送餐上门。另外，社区成立了一支服务老人的志愿服务队，每人结对8到10个老人，一般一周上门一次，行动不便、子女不在身边、身体健康状况差一点的老人，每天都要登门拜访一次，给他们带点菜，扔个垃圾，取个快递，陪他们聊聊天，说说话，这都是常态化的服务。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold color210\">“如果其他老人，也遇到像姚阿姨这样的问题，可以随时找我们。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold color210\">”</font></font></p> \n<p cms-style=\"font-L align-right\">　　<font cms-style=\"font-L align-right\">橙柿互动·都市快</font><font cms-style=\"font-L align-right\">报 记者 董吕平 刘抗</font><font cms-style=\"font-L align-right\"><font cms-style=\"font-L align-right\"></font></font></p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/2db2-00ba20f056893dd7eff4a7bd2dbd0d50.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/96b3-5edc574bd53a40a64996bbf373ce673f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250810/1c32-0c353dca41ad2fec351f31219b0a8803.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/28/w472h356/20250810/bce1-f65ecaba7d29f54622b7f0cc0e22cd1d.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3959, NULL, '英军一F-35战机在日本鹿儿岛机场紧急着陆 跑道临时关闭', 0, 4, 99, '2025-08-10 14:30:15', '2025-08-10 13:48:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/751/w550h201/20250810/ecff-8be48ef66d91c1baa07face7d2c13faa.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-10/doc-infknpkc6957554.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/751/w550h201/20250810/ecff-8be48ef66d91c1baa07face7d2c13faa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△现场图\">\n <span class=\"img_descr\">△现场图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台报道员</font></font>获悉，当地时间10日上午11时30分左右，一架英军F-35战斗机在日本鹿儿岛机场紧急着陆。受此影响，机场跑道一度临时关闭约20分钟，部分民航飞机起降受到影响。事件未造成人员受伤。（总台报道员 柏春洋）</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/751/w550h201/20250810/ecff-8be48ef66d91c1baa07face7d2c13faa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3960, NULL, 'S104线抢通 甘肃榆中灾毁道路全面恢复通车', 0, 1, 28, '2025-08-10 14:30:30', '2025-08-10 14:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/545e-41b327c6570a532f83d4ce82635d695c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-08-10/doc-infknpiv6968629.shtml', '新京报', '<p cms-style=\"font-L\">　　据央视新闻消息，8月10日13时30分，经过现场30多台套大型机械设备、近200人连续24小时的抢险作业，甘肃省兰州市榆中县境内的<font cms-style=\"font-L strong-Bold\">S104线兴隆2号桥成功通车，标志着此次兰州榆中强降雨导致的所有灾毁道路均已恢复通车</font>。</p> \n<p cms-style=\"font-L\">　　据了解，S104线是榆中县城通往兴隆山腹地、受灾较严重的马坡乡的最快捷道路，该路段的抢通，<font cms-style=\"font-L strong-Bold\">将大大提高后续救援效率</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/545e-41b327c6570a532f83d4ce82635d695c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/cd19-abcd244779ab9ca7db5ed7edbce31de6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/ff8f-7b282d4aac30e5be68fbfe114ac9fdd7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　（总台记者 柴世文 王妍）</p> \n<p cms-style=\"font-L\">　　　</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754644472\" target=\"_blank\">甘肃榆中发生山洪灾害</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/545e-41b327c6570a532f83d4ce82635d695c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/cd19-abcd244779ab9ca7db5ed7edbce31de6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250810s/0/w2048h1152/20250810/ff8f-7b282d4aac30e5be68fbfe114ac9fdd7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3961, NULL, '赔本赚吆喝外卖大战“卷”坏商家 官方出手“反内卷”保护餐饮业', 0, 2, 71, '2025-08-10 14:30:38', '2025-08-10 12:35:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/5152-bdf9022255c19352a21cb06312ccc529.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infknpix1531685.shtml', '央视', '<p cms-style=\"font-L\">　　今年4月以来，各大外卖平台掀起了激烈的“补贴大战”，纷纷推出高额优惠券吸引用户下单，各平台订单量一次次破了纪录。表面看，这是一个消费者得了实惠，商家也能多卖货，好像两全其美的好事儿。然而，不少餐饮商家反映，这补贴战打起来后，钱没多赚不说，反倒让店里的日子更难了。来看记者的调查↓↓↓</p> \n<p cms-style=\"font-L\">　　外卖大战中，奶茶咖啡是主战场。这家位于宜昌城区核心商圈的茶饮店，主营堂食。以7月21日一笔19.4元的饿了么订单为例，扣除商家承担活动款9.5元、技术服务费1.05元、配送服务费2.9元以及其他费用0.9元后，实际收入仅为5.05元。据店长介绍，一杯奶茶的成本需5到6元，参与补贴后，入账的收入几乎与成本持平。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/5152-bdf9022255c19352a21cb06312ccc529.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　在安徽合肥某商场内的一家甜品店，过去一个月，这家店在京东平台总计销售超过400单。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/5613-2b28073eadbb85163536e58dd29193f3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">合肥甜品店 店长 马龙：</font>整个7月份我们在京东的营业额是11207元，实际营业收入只有6082元。</p> \n<p cms-style=\"font-L\">　　店长告诉记者，甜品成本加外卖打包的包装，本钱要占到45%左右，按7月份京东的订单量来算，需要5043元，实际收益仅为1039元，如果算上店面租金和人工成本，<font cms-style=\"font-L strong-Bold\">7月份外卖订单的收入，处于亏本的状态。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/4aca-aaa188dfc32390cfd9258b2df0ffa042.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　参与补贴，利润却被大幅压缩。不参与补贴，订单量则会被参与活动的商家分流。同样进退两难的还有经营粤菜馆的叶瑶，她的店铺主打广式烧腊，兼营堂食与外卖。上午十点半，还没到饭点，店铺就已经接到了五六笔来自美团的外卖订单，店员们忙着备餐出餐。然而，这番忙碌的场景却让叶瑶直叹气。</p> \n<p cms-style=\"font-L\">　　她在后台系统随机挑选了一笔外卖订单，现场算了一笔账：该订单中招牌四宝饭的售价为27元，打包费1元，总共是28元，减去商家对顾客的活动补贴5元、平台佣金1.47元以及配送服务费5.92元后，预计收入为15.61元。这笔预计收入减去食材成本后，所剩寥寥无几。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">宜昌餐饮经营者 叶瑶：</font>扣除售价50%的食材成本之后，这一单到手的利润看似有两块一毛一。</p> \n<p cms-style=\"font-L\">　　为何在利润后面加上“看似”两字？叶瑶又给记者算了一笔月度总账。</p> \n<p cms-style=\"font-L\">　　以6月份为例，店铺接到的美团外卖订单4158单，商品总价157548.8元，打包费4667元，合计营业额为162215.8元，减去商家对顾客的活动补贴30452.2元、平台佣金8409.81元、配送服务费20919.86元后，收入为102433.93元。这笔收入还要减去房租等固定支出及食材成本后，才是真实利润。</p> \n<p cms-style=\"font-L\">　　叶瑶介绍，店铺面积200平方米，聘请了11名员工，每个月固定支出90000元，分摊到外卖业务上约为34000元左右。食材成本按照50%计算，为78774.4元。<font cms-style=\"font-L strong-Bold\">计算下来，6月份通过线上成交的真实利润是-10340.47。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">宜昌餐饮经营者 叶瑶：</font>除去房租、人工，还有水电气的费用之后，这一个月美团外卖订单相当于亏本一万多，属于赔本赚吆喝的状态。</p> \n<p cms-style=\"font-L\">　　“言西早”是位于湖南长沙县的一家营业近10年的快餐店，主营手工粉、盖码饭等各类快餐，是当地外卖单量靠前的店铺。上午8点30分，记者来到该店时，店里有不少顾客正在吃早餐。言西早快餐店的老板谭聪告诉记者，最开始他并没有打算做外卖。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙快餐店 老板 谭聪：</font>原来我们做的是传统餐饮，一个店的收入能上万。但是现在没办法了，不做的话别人把生意都拿走了。</p> \n<p cms-style=\"font-L\">　　“言西早”目前一共有四家分店，在美团和饿了么外卖平台上均开通了外卖业务，平均一天有近1000个外卖订单，占到总单量的五分之一，看似销售量很高，但每一单外卖的利润却很低，甚至根本没有利润。</p> \n<p cms-style=\"font-L\">　　以该店一张美团账单为例，一份20元的口味鸡丝面，顾客到店堂食时，商家能实际收取20元。但是顾客通过外卖平台下单时，商家要承担对顾客活动补贴6.6元，平台佣金1.04元以及配送服务费2.45元，预计收入10.9元，约为商品原价的一半。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙快餐店 老板 谭聪：</font>我们做堂食的毛利基本上就是百分之五十七八左右，还有人工、房租和水电费，一算下来就没利润了。但是平台又必须要做，因为这个平台做起来之后，可以增加店曝光率。</p> \n<p cms-style=\"font-L\">　　老谭告诉记者，商家需要外卖平台增加曝光，让更多消费者知道，但是平台高额的补贴却让很多商家陷入了“为单忙活”的困境。那么，外卖平台真的能为商家带来实实在在的客流量和收入吗？</p> \n<p cms-style=\"font-L\">　　记者通过查阅该店的美团后台数据发现，平台“补贴大战”确实带动了订单增长。数据显示，该店近30日内下单新客增加了1514人，占下单总人数的55.4%。其中营业收入增长了17847元，看似增幅显著，但与此同时，商家的 “补贴及支出”费用也同步上涨16688元，几乎与新增营收持平。</p> \n<p cms-style=\"font-L\">　　数据进一步显示，<font cms-style=\"font-L strong-Bold\">商家平均每一单要比以前少收6.12元</font>，这对于一家每单生意在30元左右，且毛利润仅约55%左右的快餐店而言，这样的价格压缩无疑是对利润空间的直接挤压。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙快餐店 老板 谭聪：</font>平台有红包、折扣，配送我也要出钱，我只知道我做2000块钱的单，到店里只有900多块钱，生意怎么做？做不了。但是我要依附它，增加曝光率，但是又没钱赚，你又拿它无可奈何。</p> \n<p cms-style=\"font-L\">　　记者调查中发现，当前主流外卖平台的抽成机制颇为复杂，不仅包含基础佣金，通常为订单金额的5%~10%，且设有1.04元保底等固定支出，还有一层设计，<font cms-style=\"font-L strong-Bold\">那就是若商家想获得平台曝光，占据平台靠前位置，被更多顾客看到，就必须参与满减、折扣等各类促销活动</font>，这些活动往往需要商家承担一部分费用。</p> \n<p cms-style=\"font-L\">　　而让商家两难的是，外卖的普及已显著分流了堂食客流。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙快餐店 老板 谭聪：</font>堂食最少降了30%左右，客人都在平台上点外卖就不到店里来了。但是线上没有平台曝光，哪个年轻人知道我们店？平台就抓住商家这个思维。</p> \n<p cms-style=\"font-L\">　　老谭遇到的困境并非个案，记者走访了多家餐饮店了解到，如今，许多人依赖平台获取消费信息，若不参与平台活动、缺乏线上曝光，几乎难以被目标客群知晓，可一旦上线外卖，原本的堂食客人又会转向线上下单，直接导致到店人数减少。这种“不做外卖没客流，做了外卖难盈利”的困境，让许多商家不得不被动卷入外卖平台的规则体系中。</p> \n<p cms-style=\"font-L strong-Bold\">　　赔本赚吆喝 外卖大战中商户“夹缝”求生</p> \n<p cms-style=\"font-L\">　　半年时间，平台砸下近千亿资金，补贴券满天飞。</p> \n<ul cms-style=\"ul\"> \n <li cms-style=\"li\">2月11日，京东宣布正式启动京东外卖。</li> \n <li cms-style=\"li\">4月11日，京东外卖上线“百亿补贴”。</li> \n <li cms-style=\"li\">4月30日，饿了么启动“超百亿”补贴；淘宝闪购加入战局。</li> \n <li cms-style=\"li\">7月2日，淘宝闪购宣布投入500亿元补贴用户和商家。</li> \n <li cms-style=\"li\">7月5日，淘宝闪购和美团两大平台放出大量大额的外卖红包券。</li> \n <li cms-style=\"li\">7月7日，京东启动“双百计划”投入百亿补贴商家。</li> \n</ul> \n<p cms-style=\"font-L strong-Bold\">　　隐性成本层层叠加 传统餐馆陷入“为补贴买单”的恶性循环</p> \n<p cms-style=\"font-L\">　　对主打堂食的传统餐馆而言，平台抽佣、补贴分担、流量竞价、物流费用……几乎无一不是成本项。在“看似红火”的数据背后，是日益加重的经营压力。面对平台制定的“游戏规则”，商家话语权微弱、议价能力不足。这不只是个体困局，更是结构性困局。</p> \n<p cms-style=\"font-L\">　　泓先阁是长沙县一家经营了26年的老牌湘菜馆，其在外卖平台上最大的优惠券是“满38减18元”，这18元减免中，商家需承担10元，剩余8元由平台补贴。看似10元钱并不多，但也架不住订单量的叠加和长期持续的投入。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙餐饮店 店长 张欣：</font>一天<font cms-style=\"font-L\">发</font>200份消费券，如果200份消费券真的销完了，一天就是两千多块钱，一个月下来可能就是五万到六万，这是实实在在花出去的。那么我们要做多少单才能真正来把这五六万块钱回收回来，其实这是很难计算的，成本也是非常高的。</p> \n<p cms-style=\"font-L\">　　记者调查发现，外卖平台制定的优惠机制，<font cms-style=\"font-L strong-Bold\">补贴由平台和商家共同承担，部分订单因活动叠加，成本甚至超过收入，</font>出现商家倒贴出货的情况。尽管如此，大多数商户为维持平台曝光量，仍不得不参与各平台的补贴政策。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙餐饮店 工作人员 邹微：</font>以前一天一个平台就三四十单，现在有两百单左右，数据看着挺漂亮，但实际是不挣钱的。</p> \n<p cms-style=\"font-L\">　　记者在走访中观察到，外卖平台的快速发展确实改变了人们的消费习惯。多位餐饮商家表示，从抽成、补贴到人力、备货等层层叠加的成本，不断挤压着利润空间，甚至陷入“为平台打工”的困境。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">长沙餐饮店 店长 张欣：</font>单靠一方是很难改变的，真正要做到可能是平台和商家。这些促销活动没问题，给到顾客实惠也没问题，只是这个力度要控制好。顾客已经养成了这个习惯，没券就不下单，或者跑到另外的平台下单。如果所有的平台都保持平衡，适当的力度，再做适当推广，给出适当的优惠，大家消费习惯养成了，可能才是最好的一个未来的市场。</p> \n<p cms-style=\"font-L strong-Bold\">　　外卖大战“降温” 共赢是解法</p> \n<p cms-style=\"font-L\">　　为了促进平台经济健康发展，保证商户、消费者、外卖骑手等多方利益，市场监管总局等部门已经于今年5月份、7月18日、7月31日，约谈了相关平台企业，并对网络交易平台向平台内经营者收取佣金等收费行为进行规范。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“降温”的外卖大战给行业带来哪些启示？</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">资本主导下的烧钱竞赛又是否还会重演？</font></font></p> \n<p cms-style=\"font-L\">　　记者打开饿了么、美团、京东三家外卖平台App发现，之前随处可见的“0元购”等夸张的补贴广告已不见踪影，但当天的外卖红包推送依旧诱人。</p> \n<p cms-style=\"font-L\">　　网页上显示“官方补贴、全网低价、免运费”的字样吸引着顾客下单。</p> \n<p cms-style=\"font-L\">　　某家原价297元的餐饮补贴显示着“已补187元”后，价格显示仅需110元。而秋天的第一杯奶茶价格低的仅需5.2元。</p> \n<p cms-style=\"font-L\">　　专家表示，<font cms-style=\"font-L strong-Bold\">外卖大战的实质是资本驱动下的“以烧钱换市场”为特征的“内卷式”博弈，其本身就是“不可持续陷阱”</font>。从消费者角度而言，短期内能享受外卖大战带来的低价福利，收获“薅羊毛”的快乐感，但长期看，商家为压缩成本，可能降低食材品质、缩减包装成本，甚至通过“幽灵厨房”提供低质餐品，导致食品安全风险上升。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">三峡大学经济与管理学院副院长 副教授 袁亮：</font>提高补贴塑造的“低价依赖症”会使消费者对价格更加敏感。当未来补贴退坡、价格回升的时候，消费者消费意愿和消费感知将受到影响。</p> \n<p cms-style=\"font-L\">　　从骑手角度而言，订单暴涨、商家出餐变慢，配送效率降低、劳动强度和安全风险同步加剧。而商家迫于经营压力，放弃品牌建设，转而聚焦低价策略，则会致使市场同质化加剧。</p> \n<p cms-style=\"font-L\">　　专家建议，良好的市场生态应该让消费者获得合理价格下的优质服务，让商家获得公平的经营环境，让平台获得可持续的发展空间。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">中国法学会消费者权益保护法研究会副秘书长 陈音江：</font>平台企业还是要去把主要精力放在产业结构的优化和升级，中小企业通过优质产品和优质服务来赢得市场，消费者也不要盲目去为所谓补贴内卷式营销去欢呼，而要共同地去营造一个公平有序的市场竞争环境。</p> \n<p cms-style=\"font-L\">　　8月1日，淘宝天猫、饿了么、美团、京东先后发表声明，承诺杜绝不正当竞争，抵制恶性补贴，共同推动行业竞争规范有序。外卖补贴大战到此，似乎画上了休止符。</p> \n<p cms-style=\"font-L\">　　8月5日，北京市餐饮行业协会发出倡议，坚决抵制“内卷式”竞争，共同坚守合规经营底线，携手回归价值创造本源，守护行业健康生态。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">市场监管总局网监司网络交易监管处处长 荆峥：</font>市场监管总局及时约谈外卖平台，要求平台严格落实主体责任，依法依规参与竞争。约谈会后，各平台企业在市场监管总局指导下，主动规范价格补贴行为，着力提升服务品质，平台补贴逐步回归理性。下一步，市场监管部门将对有关平台企业加大指导力度，督促平台遵守有关法律法规和商业道德，积极履行主体责任和社会责任，合理控制补贴力度，保障消费者、商家、骑手各方权益，共同促进外卖行业健康有序发展。</p> \n<p cms-style=\"font-L\">　　外卖平台作为数字经济的重要组成部分，极大方便了消费者的日常生活，也帮助大量中小商户借助流量红利快速触达市场、积累口碑。然而，如果平台通过抬高佣金、压低价格等方式，将经营成本转嫁给商户和骑手，不仅会加剧行业内的无序竞争，也可能在服务质量和消费者体验上埋下隐患。短期“价格内卷”看似让利于用户，长期来看却可能导致行业生态失衡，最终受损的仍是消费者利益。</p> \n<p cms-style=\"font-L\">　　各方都在期盼平台经济的竞争焦点，从“卷价格”向“卷价值”“卷服务”转变，唯有共建共享、规范有序的平台生态，才能为中国餐饮产业和数字经济发展注入真正可持续的增长动力。</p> \n<p cms-style=\"font-L\">　　制片人丨张萍 王婧</p> \n<p cms-style=\"font-L\">　　主编丨毕德辉</p> \n<p cms-style=\"font-L\">　　记者丨焦畅 李晶晶 乐林峰 王利</p> \n<p cms-style=\"font-L\">　　责编丨苍丽莉 邢颖宏</p> \n<p cms-style=\"font-L\">　　摄像丨周志岳</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1751855116\" target=\"_blank\">外卖补贴大战持续升温</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/5152-bdf9022255c19352a21cb06312ccc529.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/5613-2b28073eadbb85163536e58dd29193f3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250810/400/w1280h720/20250810/4aca-aaa188dfc32390cfd9258b2df0ffa042.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3968, NULL, '爆料！白宫正考虑邀请泽连斯基！白宫称先按普京要求准备俄美会晤，泽连斯基：和平方案必须与乌共商', 0, 4, 207, '2025-08-10 15:30:15', '2025-08-10 14:36:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/505/w1920h985/20250810/c6a3-4fb4b024635eb4ece59a5aea65c5ea65.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-10/doc-infknpix1551847.shtml', '每日经济新闻', '<p cms-style=\"font-L\">　　乌克兰总统泽连斯基强调乌克兰的和平之路必须与乌克兰共同确定，反对在领土问题上让步。特朗普对与泽连斯基和普京在阿拉斯加举行三边峰会持开放态度，但目前美方应普京要求正准备美俄元首双边会晤。分析认为，俄美领导人同意会面各有政治与战略考量，特朗普政府试图借推动俄乌停火提振国内支持率，而俄罗斯或希望通过对话避免美方进一步制裁。目前泽连斯基是否出席会晤尚未确定。</p> \n<p cms-style=\"font-L\">　　每经编辑|毕陆名&nbsp;&nbsp;&nbsp;&nbsp;</p> \n<p cms-style=\"font-L \">　　<font cms-style=\"font-L\">据央视新闻，乌克兰</font><font cms-style=\"font-L\">总统泽连斯基9日表示，乌克兰的和平之路“必须与乌克兰共同确定，这是最基本的”。</font></p> \n<p cms-style=\"font-L\">　　根据乌克兰<font cms-style=\"font-L\">总统</font>网站9日发布的消息，泽连斯基在当天晚间发表视频讲话说，他收到了美国与欧洲国家的代表进行会谈的报告。他说：“我们想传达的所有信息都被传达了，我们的观点被听取了，各种风险都已被考虑在内。乌克兰的和平之路必须且只能与乌克兰共同确定，这是最基本的。”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/505/w1920h985/20250810/c6a3-4fb4b024635eb4ece59a5aea65c5ea65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"图片来源：视觉中国\">\n <span class=\"img_descr\">图片来源：视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　泽连斯基同时表示，“乌克兰一直支持美国<font cms-style=\"font-L\">总统</font><font cms-style=\"font-L\">特朗普</font>相关提议”，“乌克兰与美国保持着几乎全天候、多层次的接触，但并非所有内容都适合公开”。泽连斯基强调说，绝不允许再次出现分裂乌克兰的企图，乌方“必须在一个明确可靠的安全架构的基础上，以有尊严的和平来结束战争”。</p> \n<p cms-style=\"font-L\">　　另据美国媒体9日报道，一名白宫官员当天表示，<font cms-style=\"font-L\">特朗普</font>对与泽连斯基和俄罗斯<font cms-style=\"font-L\">总统</font><font cms-style=\"font-L\">普京</font>在美国阿拉斯加举行三边峰会持开放态度，不过目前美方应<font cms-style=\"font-L\">普京</font>要求在准备美俄元首双边会晤。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">特朗普</font>与<font cms-style=\"font-L\">普京</font>将于8月15日在阿拉斯加州会晤，讨论乌克兰危机。泽连斯基7日晚表示，乌克兰参与谈判才公平。8日早些时候，<font cms-style=\"font-L\">特朗普</font>在白宫对记者说，俄乌协议可能涉及俄乌双方“交换一些领土”。泽连斯基随后在社交媒体表示，不会在领土问题上让步。</p> \n<p cms-style=\"font-L\">　　另据参考消息，据美国《国会山》日报网站8月9日报道，一名白宫官员说，白宫正在考虑邀请乌克兰<font cms-style=\"font-L\">总统</font>泽连斯基参加<font cms-style=\"font-L\">特朗普</font>和俄罗斯<font cms-style=\"font-L\">总统</font><font cms-style=\"font-L\">普京</font>即将在阿拉斯加举行的领导人会晤。</p> \n<p cms-style=\"font-L\">　　报道称，目前尚不清楚泽连斯基是否会出席此次会晤，因为相关细节尚未敲定。<font cms-style=\"font-L\">特朗普</font>8日宣布，他将于下周在阿拉斯加与<font cms-style=\"font-L\">普京</font>举行会晤，讨论结束俄罗斯和乌克兰之间长达三年的冲突。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">特朗普</font>没有排除未来主持俄乌领导人会晤的可能性，此前克里姆林宫拒绝了这一提议。</p> \n<p cms-style=\"font-L\">　　一位白宫高级官员9日说：“（<font cms-style=\"font-L\">特朗普</font>）<font cms-style=\"font-L\">总统</font>对与俄乌两国领导人举行三边领导人会晤持开放态度。目前，白宫正在为<font cms-style=\"font-L\">普京</font><font cms-style=\"font-L\">总统</font>提出的双边领导人会晤作准备。”</p> \n<p cms-style=\"font-L\">　　此外，路透社援引美国全国广播公司报道称，白宫正在考虑邀请乌克兰<font cms-style=\"font-L\">总统</font>泽连斯基访问阿拉斯加。</p> \n<p cms-style=\"font-L\">　　一名听取讨论简报的人士称：“相关事宜正在讨论中。”报道还说，泽连斯基的访问尚未最终确定，目前还不清楚乌克兰领导人最终是否会在阿拉斯加出席会议，但存在可能性。</p> \n<p cms-style=\"font-L\">　　据新华社，分析人士认为，俄美领导人同意会面，背后各有政治与战略考量。</p> \n<p cms-style=\"font-L\">　　从美国角度看，<font cms-style=\"font-L\">特朗普</font>政府希望通过与<font cms-style=\"font-L\">普京</font>的会晤寻求外交成绩，从而获取政治收益。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">特朗普</font>在竞选期间声称能很快解决俄乌冲突，但就任<font cms-style=\"font-L\">总统</font>以来一直未能取得实质性进展。当前，<font cms-style=\"font-L\">特朗普</font>政府试图借“推动俄乌停火”提振自己在美国国内的支持率。此前威特科夫与<font cms-style=\"font-L\">普京</font>的会晤，被解读为对俄方立场的试探。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">特朗普</font>上任以来在俄乌问题上的表态反复无常，甚至一度威胁退出斡旋，被国际舆论形容为“政治真人秀式施压”。分析人士认为，这种反复无常会让俄乌对美方失去信任，加剧俄乌停火前景的不确定性。</p> \n<p cms-style=\"font-L\">　　对俄罗斯而言，美方制裁对俄经济造成巨大压力，与<font cms-style=\"font-L\">特朗普</font>的会晤或是为了突破制裁围堵。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">特朗普</font>政府此前曾警告，俄方必须于8月8日前结束俄乌冲突，否则将面临美方进一步制裁。在威特科夫与<font cms-style=\"font-L\">普京</font>会谈结束后数小时，<font cms-style=\"font-L\">特朗普</font>政府以印度购买俄罗斯石油为由对印输美产品征收额外的25%关税，此举也被视为对俄方的进一步施压。</p> \n<p cms-style=\"font-L\">　　英国广播公司认为，俄方可能希望通过对话避免<font cms-style=\"font-L\">特朗普</font>政府进一步的制裁措施。路透社称，在美俄领导人会晤敲定之际，<font cms-style=\"font-L\">特朗普</font>向俄方发出的“最后通牒”也已到期，美方没有宣布新的制裁措施，也没有就此作出说明。</p> \n<p cms-style=\"font-L\">　　每日经济新闻综合央视新闻、新华社、参考消息</p> \n<p cms-style=\"font-L\">　　封面图片来源：视觉中国</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250810/505/w1920h985/20250810/c6a3-4fb4b024635eb4ece59a5aea65c5ea65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3969, NULL, '7岁男孩在大理苍山参加户外独立营时走丢，失踪超24小时，知情人士称其患有自闭症', 0, 1, 25, '2025-08-10 15:30:24', '2025-08-10 14:45:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/622/w550h872/20250810/f979-ef98c7217646df5692cf0588917d585d.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infkntrv1423466.shtml', '扬子晚报', '<p cms-style=\"font-L\">　　来源：扬子晚报</p> \n<p cms-style=\"font-L\">　　8月9日，一名7岁男孩云南大理苍山走失。搜救人员介绍，孩子是来苍山参加户外独立营时走丢的。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">寻人启事信息显示，男孩于</font><font cms-style=\"font-L strong-Bold\">8月9日11时40分左右</font><font cms-style=\"font-L\">在大理元阳书院附近的苍山走失，其书包上有名字和电话号码。另有多名网友称，孩子是参加一个户外独立营时走丢的。</font></p> \n<p cms-style=\"font-L\">　　8月10日上午，大理某救援队负责人向极目新闻记者介绍，他们接到消息后，于9日下午集结到苍山配合警方等寻找男孩，一直找到了后半夜，10日一早又再次进山，目前仍无进展。“孩子是在山脚走丢的，但苍山面积比较大，走失的方向又不明朗，所以搜救的难度比较大。”上述救援队负责人还确认，据他了解，男孩的确是来苍山参加户外独立营，由老师带着进行户外活动时失踪的。</p> \n<p cms-style=\"font-L\">　　一名参加搜救的志愿者向记者表示，他连夜进行了搜救，“苍山上气温还好，晚上也不算太冷。”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/622/w550h872/20250810/f979-ef98c7217646df5692cf0588917d585d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　中国新闻周刊从知情人处了解到，王一铠是一名自闭症儿童。曾给王一铠上过轮滑课的教练李生（化名）向记者介绍，据其观察，孩子仅能进行简单语言交流，“比如问‘妈妈叫什么’会回答，能背《咏鹅》这首古诗，问‘几岁了’也会回答。不过他的运动能力挺强，跑得很快”。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">李生回忆，王一铠上课时总是独自玩耍，很少主动与人交流，只有被询问时才会开口说话，“但是不舒服、不高兴、高兴了、渴了饿了，他也会喊叫”。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">据李生介绍，王一铠平时就读于特殊儿童幼儿园，每月学费超过一万元。</font></font></p> \n<p cms-style=\"font-L\">　　李生担心，即使王一铠听到有搜救人员在喊他，也不一定会回应。</p> \n<p cms-style=\"font-L\">　　记者致电大理元阳书院，工作人员表示，他们书院在苍山脚下，和男孩失踪的地方相距有几百米，她也听说男孩是来参加户外活动走丢的。“这事和我们书院没有关系，我们也是昨天下午4点半左右看到搜救人员从门口经过，才知道这事的。”该工作人员表示，“有很多私人机构经常组织小朋友到苍山来采菌子，或进行户外徒步，却打着我们书院的名义，对我们的名誉造成了影响，我们以前也投诉过。”她表示，自己从9日晚到10日上午一直在等消息，目前还没听到有搜救进展。</p> \n<p cms-style=\"font-L\">　　记者联系辖区苍山派出所，暂时没有接到此事的最新回应。</p> \n<p cms-style=\"font-L\">　　综合极目新闻、中国新闻周刊</p> \n<p cms-style=\"font-L align-Center color0\"></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/622/w550h872/20250810/f979-ef98c7217646df5692cf0588917d585d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3970, NULL, '甘肃榆中马坡乡旧庄沟村2具失联人员遗体被找到', 0, 1, 28, '2025-08-10 15:30:37', '2025-08-10 14:35:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250810s/600/w1920h1080/20250810/978d-6f7d81e21582628174b1893ae3ddd3cc.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infknpiv6972333.shtml', '新京报', '<p cms-style=\"font-L\">　　据人民日报消息，8月10日10时20分，国家西北区域应急救援中心在甘肃省榆中县马坡乡旧庄沟村一社一间坍塌房屋内，经深入搜索挖掘<font cms-style=\"font-L strong-Bold\">找到2具失联人员遗体</font>，现正在对接地方公安、医护做好后续工作。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/600/w1920h1080/20250810/978d-6f7d81e21582628174b1893ae3ddd3cc.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/564/w1896h1068/20250810/2ce2-7f20ea689beff2c7b2a30eeb96661de0.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/354/w2275h1279/20250810/8080-e6e895d381f53d13ad300cd1cb810ac0.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754644472\" target=\"_blank\">甘肃榆中发生山洪灾害</a> \n <a href=\"https://news.sina.cn/hot_zt/subject-17547667415\" target=\"_blank\">甘肃榆中山洪已致15死28失联</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250810s/600/w1920h1080/20250810/978d-6f7d81e21582628174b1893ae3ddd3cc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250810s/564/w1896h1068/20250810/2ce2-7f20ea689beff2c7b2a30eeb96661de0.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250810s/354/w2275h1279/20250810/8080-e6e895d381f53d13ad300cd1cb810ac0.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3971, NULL, '台湾花莲县发生4.5级地震，震源深度10千米', 0, 1, 34, '2025-08-10 15:30:43', '2025-08-10 14:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250810s/391/w614h577/20250810/ff1e-7e04106374fac4ea9389e29fd56eb123.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-08-10/doc-infknpix1548687.shtml', '新京报', '<p cms-style=\"font-L\">　　新京报讯 据中国地震台网正式测定：08月10日14时03分在台湾花莲县（北纬23.73度，东经121.60度）发生4.5级地震，震源深度10千米。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/391/w614h577/20250810/ff1e-7e04106374fac4ea9389e29fd56eb123.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250810s/391/w614h577/20250810/ff1e-7e04106374fac4ea9389e29fd56eb123.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3975, NULL, '韩右翼团体示威时涉嫌辱华，韩警方立案调查', 0, 4, 105, '2025-08-10 17:30:27', '2025-08-10 15:48:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-10/doc-infkntry9762504.shtml', '观察者网', '<p>　　来源：观察者网</p> \n<p>　　韩联社8月10日报道，近期，有社会团体在中国驻韩大使馆附近示威时侮辱中方，韩国警方已对此展开立案调查。</p> \n<p>　　据报道，首尔南大门警察署近日传唤支持韩国前总统尹锡悦的右翼团体“自由大学”相关人员于11日到案接受调查。</p> \n<p>　　7月22日晚8时许，该团体曾在位于首尔中区的中国驻韩大使馆附近举行一场旨在谴责选举舞弊的集会，对中国进行指责抹黑，期间还撕毁印有中国国旗和中国大使头像的横幅。</p> \n<p>　　韩国《刑法》第108条规定，对派驻韩国的外国使节进行侮辱或侵犯其名誉的，可处三年以下有期徒刑或监禁。</p> \n<p>　　中国驻韩国大使此前通过微信公众号发文表示，韩国个别政治势力捏造所谓“中国干涉韩国大选”，对中国进行指责抹黑，中方坚决反对。一些人近期在中国游客集中的首尔明洞等地区举行反华集会游行，不排除个别人员采取过激行为。</p> \n<p>　　中国驻韩国大使馆已向韩方提出严正交涉，要求韩方采取措施保证中国公民人身安全。</p> \n<p>　　<font cms-style=\"strong-Bold\">本文系观察者网独家稿件，未经授权，不得转载。</font></p> \n<p class=\"show_author\">责任编辑：崔理斯 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3994, NULL, '橙色预警 四川12个县市区发生山洪灾害可能性大', 0, 1, 23, '2025-08-10 19:30:20', '2025-08-10 18:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/0/w3200h3200/20250810/b5a0-4a12bb6a8c523c498b41669d90f1d0f6.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infknxxr6762026.shtml', '央视', '<p cms-style=\"font-L \"></p> \n<p cms-style=\"font-L\">　　8月10日17时，四川省水利厅、四川省气象局联合发布山洪灾害橙色预警。这是继昨日发布山洪灾害黄色预警后，<font cms-style=\"font-L strong-Bold\">四川本月首次将山洪灾害预警升级为橙色等级。</font></p> \n<p cms-style=\"font-L\">　　预警信息显示，8月10日20时至11日20时，内江市威远、隆昌、资中，自贡市贡井、自流井、富顺、荣县，宜宾市翠屏、叙州，泸州市泸县，雅安市汉源、石棉等12个县（市、区）发生山洪灾害可能性大（橙色）；</p> \n<p cms-style=\"font-L\">　　内江市市中区、东兴，自贡市大安、沿滩，宜宾市江安、高县、珙县，资阳市安岳，乐山市金口河、沐川、马边、峨边、峨眉山，遂宁市安居、船山、蓬溪，泸州市纳溪，达州市大竹、开江、达川，雅安市荥经，眉山市洪雅等22个县（市、区）发生山洪灾害可能性较大（黄色）；</p> \n<p cms-style=\"font-L\">　　宜宾市南溪、兴文、长宁、屏山、筠连，资阳市雁江、乐至，乐山市犍为、沙湾、五通桥、井研、市中区，广安市武胜、前锋、岳池、广安、华蓥、邻水，泸州市江阳、龙马潭、叙永、合江，达州市渠县、通川、宣汉，雅安市雨城、天全，眉山市仁寿，南充市高坪、嘉陵、蓬安、顺庆、营山，凉山州甘洛、雷波、西昌、昭觉、布拖、金阳、盐源、木里，甘孜州得荣、稻城、乡城、雅江、泸定、丹巴，阿坝州小金、金川等49个县（市、区）可能发生山洪灾害（蓝色）。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/0/w3200h3200/20250810/b5a0-4a12bb6a8c523c498b41669d90f1d0f6.png/w700d1q75cms.jpg?by=cms_fixed_width\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　（总台记者 蒋林）</p> \n<p class=\"show_author\">责任编辑：崔理斯 </p>', '[\"https://k.sinaimg.cn/n/spider20250810/0/w3200h3200/20250810/b5a0-4a12bb6a8c523c498b41669d90f1d0f6.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (3997, NULL, '看见美丽中国丨20年“灰山”变“青山” 老乡村“长”出新业态', 0, 1, 11, '2025-08-10 20:30:39', '2025-08-10 01:42:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/0644-2d1d11a380093dda485f4f48f0a060da.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/xl/2025-08-10/doc-infkmmwm2090275.shtml', '央视', '<p>　　最近这些年你有没有发现，点开朋友圈，经常能看到大家晒好山好水好天气。</p> \n<p>　　出门旅游，跟风景同框美美地拍些照片；家门口的风景，抬眼就是绿，转角就有美。</p> \n<p>　　除了看得见的美，还有更绿色的产业、越来越多的新质生产力，另外还有经济结构的升级、生产生活方式的深刻变革。</p> \n<p>　　这一切的源头就在“绿水青山就是金山银山”这句话。</p> \n<p>　　2005年8月，时任浙江省委书记的习近平同志，在浙江安吉余村，首次提出“绿水青山就是金山银山”的理念。20年过去了，美丽中国一路走来，走进我们的生活，更走进我们的心里。</p> \n<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　小溪边、田野旁、草地上，没有天花板的“大自然工位”，是沈晨在余村最喜欢的办公地点。作为一名乡村影像记录者，他的工作就是给大家讲述中国乡村的故事。这个夏天，他和小伙伴们把镜头对准了余村。</p> \n<p>　　<strong>过去：</strong></p> \n<p>　　<strong>靠矿山吃饭 青山成“灰山”</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/0644-2d1d11a380093dda485f4f48f0a060da.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　这个暑期，葛叔家的民宿一房难求。天南海北的游客，为余村而来。民宿的一楼，摆满了葛叔从各地淘来的石头摆件，每一块都雕刻着他的回忆。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/47b5-e6354a69cb2b195724a2813702f638eb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　葛叔是村里的老矿工，他带着沈晨回望了那段石灰漫天的岁月。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/fad5-f8a7ec4fbb88cadfa4391d96569b7724.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>村民 葛元德</strong><strong>：</strong>我那块石头就是在这里捡到的。我们那时候开矿，是靠矿山吃饭的，当时余村也是一个首富村。后来环境越来越差。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/905b-a5ad3f289c50b7d90db1edb15c390a99.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　一车车矿石运出去，换回了真金白银，但青山也变成了灰山。这段经历，在老余村人心里仍然记忆犹新。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/6069-fd1b7966bd5d995c298d8eff41b9d280.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>葛元德儿子 村民 葛军</strong><strong>：</strong>那个时候，洗完脸、洗完手的水都是黑乎乎的，跟我写毛笔字洗笔的水差不多。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/cfcd-c2bda05af499dedf2303f78f7a318507.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>村民 胡青法</strong><strong>：</strong>那片山都是灰蒙蒙的。那时候很明显，靠近矿山、靠近水泥厂的毛竹，都很小的。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/4f64-98f63cd349e3844c2679844b34cc1126.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>原余村村委会主任 胡加仁：</strong>我们家门口不能晒棉被，也不能晒衬衫，白衬衫更不能晒，窗帘也不能开，开的话房间都是灰尘。</p> \n<p>　　<strong>现在：</strong></p> \n<p>　　<strong>从卖石头到卖风景 走绿色发展之路</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/8686-f8b6de220fc928d19b7e70d06f0d5804.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>余村创业者 沈晨：</strong>这里以前是村里的羽绒厂，现在被改造成余村文化礼堂，在白天的时候这边会放映宣传片，每逢周三和周六的晚上，这边还会播放电影，供村民和游客们免费观看。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/9197-15ece569569c3cdbe5dfc49cc8976e17.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　二楼的会议室，就是“两山”理念诞生的地方，每天都有许多来自天南地北的游客，来到这里感受矿山的“旧貌”和“新颜”。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/cc30-3faf35aa37553dc8d557233110f2ae58.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>导游 潘春林：</strong>我们当时开矿山的时候，村集体收入比较高，村里面家家户户成了万元户。随着炸山开矿，给我们的毛竹打得横七竖八。钱是赚到了，但是我们以健康与环境为代价。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/35e1-ee6adb432d60e5d8c56ff719c4aebf45.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　痛定思痛，余村人陆续关停了矿山、水泥厂，开始了矿山复绿、治理污水、改造农房。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/0cba-c4ee47ba8f24a2a1800e6ade3e0310ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>原余村党支部书记 鲍新民：</strong>以前我们办的企业都会破坏生态环境，现在你看我们要保护生态环境，把绿色发展的理念贯彻到每一处。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/6eae-236d6d9ad20202ab429adb761a5e2e5a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>余村创业者 沈晨：</strong>余村青年图书馆是全国首个乡村铂金级的碳中和建筑，它是由之前废弃的化工厂改造而成的。楼顶有光伏玻璃瓦片，为图书馆发电。在一二楼给我们提供阅读的地方、地下一层还有国漫主题茶咖，到了晚上图书馆还会有英语角和余村夜话等活动，给新老村民提供谈天说地的一个好地方。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/762f-2272d2a294cea62bd9fb73fdd846a07f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　曾经的石灰窑和矿区，变身矿山遗址公园；曾经脏乱差的小加工厂，变身“两山”会址公园；曾经的水泥厂和周边荒地，变身露营地和生态农业观光园；而曾经堆放化肥和杂物的仓库，则变身年轻人共享办公、交流音乐和创意的地方。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/8bcc-69fdf7a951c5a650cccec66bb18dda04.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　从卖石头到卖风景，如今的余村竹海摇曳、茶园飘香，主要发展生态农业、生态经济和生态旅游。原来在矿山工作的村民们开起了民宿、咖啡吧、生态农场。仅2024年，就吸引了122万名游客，带来6000多万元的旅游收入，人均可支配收入也从2005年的8000多元，增长到7.4万元。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/65b3-ff8afeb0b58793b6c17d8925d00d9035.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>游客：</strong>余村是一个风景很好、景色很美的地方，来这里我觉得很开心、很值得。</p> \n<p>　　<strong>未来：</strong></p> \n<p>　　<strong>筑巢引凤 绿水青山“长”出新业态</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/b222-c21042ddfd1c0fdddb1fdd71beffa572.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　余村的好风景，不只引来了游客，更吸引来许多新村民。热爱骑行的上海青年徐亮和女朋友卓莉，一起在余村创办了一家骑行俱乐部。来自上海、江苏甚至国外的骑友们慕名而来，除了可以享受速度与激情，还能在山水间饱览沿途的乡村美景。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/3f38-01bea8e6413ff5a4356cf94d7e5863b1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>余村乡野骑行俱乐部负责人 徐亮：</strong>“大山在召唤。”这里有高山有峡谷，可以体验上坡下坡的快乐，环境又这么优美，绿水青山，蓝天白云，还能看到真的是建设得非常现代化的乡村。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/a22d-843b7e3552e412d5823342fad62516ca.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　守住“青”和“绿”，引来“金”和“银”。</p> \n<p>　　2022年，安吉以余村为核心，统筹周边3个乡镇24个村发展“大余村”景区，向全球招募绿水青山“合伙人”。三年间，已有60多个合伙人和新项目落地，研学教育、文化创意、数字经济等人才不断涌入新余村。1200多名新村民，来到这里创业、就业、生活。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/2ba6-95d27b65a67d374dd6e8e0f12188d3a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>余村创业者 陈乙文：</strong>有一种很接地气、被群山环绕保护的感觉，这是我对余村的第一个印象。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/a28e-b5d434fe5feb8faf87987eebf2c428e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>DN余村数字游民基地创始人 许崧：</strong>几个人凑在一起，我们研发个新产品吧，我们做一个小程序吧，我们开发一个App吧……像这样的事情是很频繁地在发生的。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/2eea-b9e44d78af0e79bfa619444ee7161c2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>余村党支部书记 汪玉成：</strong>把绿水青山守护好，筑好这个巢，引来金凤凰。年轻人的入乡，他们的一些创新思维给乡村带来了新的活力。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/e3eb-81deee6be9449e8232034971076be59b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　20年，余村的调色盘被彻底改写。</p> \n<p>　　曾经的石灰白，变成了白墙黛瓦；曾经的灰山臭水，变成青峰叠翠；曾经的矿渣场，如今是漫山竹海；曾经浑浊的黄泥溪，此刻清澈流淌。曾经的“村村点火、户户冒烟”，如今“步步皆景、户户迎客”。这就是20年，余村人修复的家乡画卷。而这幅画卷里，如今正在加入更多的新余村人，为其挥毫泼墨、填色增辉。</p> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/0644-2d1d11a380093dda485f4f48f0a060da.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/47b5-e6354a69cb2b195724a2813702f638eb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/fad5-f8a7ec4fbb88cadfa4391d96569b7724.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/905b-a5ad3f289c50b7d90db1edb15c390a99.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/6069-fd1b7966bd5d995c298d8eff41b9d280.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/cfcd-c2bda05af499dedf2303f78f7a318507.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/4f64-98f63cd349e3844c2679844b34cc1126.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/8686-f8b6de220fc928d19b7e70d06f0d5804.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/9197-15ece569569c3cdbe5dfc49cc8976e17.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/cc30-3faf35aa37553dc8d557233110f2ae58.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/35e1-ee6adb432d60e5d8c56ff719c4aebf45.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/0cba-c4ee47ba8f24a2a1800e6ade3e0310ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/6eae-236d6d9ad20202ab429adb761a5e2e5a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/762f-2272d2a294cea62bd9fb73fdd846a07f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/8bcc-69fdf7a951c5a650cccec66bb18dda04.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/65b3-ff8afeb0b58793b6c17d8925d00d9035.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/b222-c21042ddfd1c0fdddb1fdd71beffa572.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/3f38-01bea8e6413ff5a4356cf94d7e5863b1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/a22d-843b7e3552e412d5823342fad62516ca.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/2ba6-95d27b65a67d374dd6e8e0f12188d3a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/a28e-b5d434fe5feb8faf87987eebf2c428e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/2eea-b9e44d78af0e79bfa619444ee7161c2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250810/e3eb-81deee6be9449e8232034971076be59b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4002, NULL, '广东多位市委书记、市长，深入一线大扫除', 0, 1, 19, '2025-08-10 21:30:13', '2025-08-10 20:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250810s/143/w1080h663/20250810/922b-a812ecd251492b3f2c1cbce0959b915a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infkpefv6642296.shtml', '新京报', '<p cms-style=\"font-L\">　　近期，为筑牢基孔肯雅热群防群控严密防线，广东多地在全市范围内开展爱国卫生运动统一行动，党政领导带头深入基层一线，与群众一起开展环境卫生整治。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">中山网消息，8月9日，</font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">中山市委书记郭文海</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">利用周末时间，到坦洲镇督导检查基孔肯雅热疫情防控工作和爱国卫生运动开展情况，并带头参与环境卫生整治。</font></font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/143/w1080h663/20250810/922b-a812ecd251492b3f2c1cbce0959b915a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　郭文海先后来到佳境康城小区、十四村社区，深入涉疫重点区域、居民小区、社区居委会、学校、里街暗巷，检查绿化带、排水口、低洼地带、房前屋后、闲置空地等部位的防蚊灭蚊措施落实情况，与镇村干部、志愿者、基干民兵等深入交流，详细了解蚊虫消杀、宣传动员群众等情况。他说，<font cms-style=\"font-L strong-Bold\">“家家户户、各行各业、每个单位都动起来，中山就会变得更加干净整洁！”</font></p> \n<p cms-style=\"font-L\">　　湛江市广播电视台消息，根据湛江市委、市政府统一部署，8月8日下午，湛江在全市范围内开展爱国卫生运动统一行动。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">湛江市委书记余钢</font><font cms-style=\"font-L strong-Bold\">等市领导带头深入基层一线，与广大党员干部群众一起开展环境卫生整治，全面清除蚊媒孳生地</font>，以“人人动手”的实际行动，带动全市上下共同环境卫生大整治，筑牢公共卫生安全防线，力争在最短时间内打赢基孔肯雅热疫情歼灭战。</p> \n<p cms-style=\"font-L\">　　当天下午5时许，余钢、刘智勇、谢水明、程凤英、郑浩然、宋会勇、陈峻华、于中泉、吴国雄、孔海文等市领导来到银帆公园西广场，与霞山区和挂点单位干部、职工、志愿者们一同拿起扫帚、夹子等工具，投入到爱国卫生运动统一行动中。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">佛山日报报道，8月7日，佛山在全市范围内开展爱国卫生运动统一行动。<font cms-style=\"font-L strong-Bold\">广东省政府党组成员陈良贤、国家疾控局副局长孙阳、佛山市委书记唐屹峰、佛山市市长白涛</font><font cms-style=\"font-L strong-Bold\">等领导带头下沉基层一线</font></font><font cms-style=\"font-L\">，与市民群众一起开展环境卫生整治，全面清除蚊媒孳生地，进一步巩固拓展基孔肯雅热疫情防控工作成效，力争在最短时间内打赢疫情歼灭战。</font></p> \n<p cms-style=\"font-L\">　　7月24日，佛山市委书记唐屹峰、市长白涛、市人大常委会主任胡钛、市政协主席李政华等领导，也曾带头下沉基层一线，深入开展爱国卫生专项行动。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color0\">疫情已得到初步遏制，广东7天新增报告1387例基孔肯雅热本地病例</font></p> \n<p cms-style=\"font-L\">　　央视新闻消息，从广东省疾控局了解到，2025年8月3日0时至8月9日24时，广东全省新增报告1387例基孔肯雅热本地病例，未报告重症和死亡病例。病例分布在佛山1212例，广州103例，湛江39例，清远6例，深圳、珠海各5例，中山4例，惠州3例，韶关、东莞各2例，汕头、江门、阳江、潮州、揭阳、云浮各1例。</p> \n<p cms-style=\"font-L\">　　广东省疾控中心传染病预防控制所所长、传染病防控首席专家康敏指出，基孔肯雅热是经伊蚊（俗称“花斑蚊”）叮咬传播的病毒性疾病。伊蚊偏好在小型的洁净水体中繁殖。因此，翻盆倒罐清积水，特别是清理各类小型容器积水，是控制疫情传播的基础。预防基孔肯雅热的关键是清积水、灭成蚊、防叮咬。没有积水就没有蚊虫孳生，没有蚊虫就没有疫情传播。</p> \n<p cms-style=\"font-L\">　　康敏指出，<font cms-style=\"font-L strong-Bold\">佛山市疫情快速上涨势头已得到初步遏制，近期防控成效进一步巩固。</font>广东全省新增报告病例数呈现连续下降趋势，但疫情波及面广，加上全球基孔肯雅热疫情高发，广东省对外交流频繁，境外输入风险持续存在；同时叠加汛期台风、降雨等天气影响，蚊媒活动频繁，疫情防控还不能松劲。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">广东发现基孔肯雅热</a>\n</div> \n<p class=\"show_author\">责任编辑：崔理斯 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250810s/143/w1080h663/20250810/922b-a812ecd251492b3f2c1cbce0959b915a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4010, NULL, '乌称打击俄一指挥所 指挥官和参谋长在内多人死亡', 0, 4, 204, '2025-08-10 22:30:24', '2025-08-10 21:14:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-10/doc-infkpefu9567349.shtml', '央视', '<p cms-style=\"font-L \"></p> \n<p cms-style=\"font-L\">　　当地时间8月10日，乌克兰武装部队总参谋部通报称，乌克兰空军打击了位于赫尔松州奥列什基地区的俄军营级指挥所。</p> \n<p cms-style=\"font-L\">　　据初步信息，约25名俄军被打死，至少11人受伤。情报显示，被打死人员中包括该营指挥官、参谋长等人。</p> \n<p cms-style=\"font-L\">　　俄方对此暂无回应。（总台记者 王晋燕）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：崔理斯 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4011, NULL, '大理发布通告寻找走失8岁男童线索', 0, 1, 25, '2025-08-10 22:30:33', '2025-08-10 21:18:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-10/doc-infkpkpt6523949.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">　央视网消息：</font>据大理发布微信公众号消息，大理市“8·9”搜救工作组发布关于积极提供寻找走失儿童相关线索的通告。</p>\n<p cms-style=\"font-L\">　　2025年8月9日，一名8岁男童在大理市大理镇阳和茶厂附近走失，接报后，大理市立即组织公安、消防救援、森林消防、应急、林草、“苍山卫士”及大理蓝天、大理山地救援队伍等多方力量开展全力搜救。</p>\n<p cms-style=\"font-L\">　　该男童身高约1.2米，体型偏瘦，走失时上身穿蓝白色相间上衣，下身穿深色牛仔裤，背橙色儿童背包，身上有标牌及家属电话号码。</p>\n<p cms-style=\"font-L\">　　如发现疑似线索请及时拨打110报警电话，对提供关键线索者核实后将予以适当奖励。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4012, NULL, '沈阳通报一河流现大量泡沫：洗手液原料进入河道所致 已立案调查', 0, 2, 35, '2025-08-10 23:30:24', '2025-08-10 21:56:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/133/w1206h2127/20250810/b0aa-f8fdac6d57d8ad2f09e7027fb9aa332b.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infkpkpw0420978.shtml', '央视', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　据沈阳市生态环境局通报，8月9日傍晚，沈阳市生态环境部门发现白塔堡河支流白支排干河道内出现大量泡沫。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/133/w1206h2127/20250810/b0aa-f8fdac6d57d8ad2f09e7027fb9aa332b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　调查数据显示，问题河段的阴离子表面活性剂（洗涤制品特征指标）超标0.38倍。当夜，浑南区对河道内的泡沫进行清理，10日凌晨，河道内泡沫全部清理完毕。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250810/135/w1206h2129/20250810/5824-556484b08e48de4dd572bd4ecf62466d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　经排查，出现大量泡沫的原因为，该处河段上游一家洗涤日用品生产企业院内临河一侧存放的洗手液生产原料（具有发泡性能），因保管不善进入河道，经“跌水坝”下泄搅动后形成大量泡沫。目前，公安机关配合生态环境部门已对涉事企业开展立案调查。</p> \n<p>　　8月10日，生态环境部门对白支排干及白塔堡河下游河段选取10个点位进行加密水质监测。数据显示，阴离子表面活性剂均已达标，对白塔堡河所汇入的浑河干流下游段监测显示，阴离子表面活性剂“未检出”，下游河流水质未受到影响。</p> \n<p>　　（总台记者 韦昊岩）</p> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/spider20250810/133/w1206h2127/20250810/b0aa-f8fdac6d57d8ad2f09e7027fb9aa332b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250810/135/w1206h2129/20250810/5824-556484b08e48de4dd572bd4ecf62466d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4057, NULL, '近12轮首胜！梅州2-1送三镇6轮不胜 恩戈姆传射绍尔世界波难救主', 0, 2, 165, '2025-08-11 00:30:48', '2025-08-10 23:48:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/480/w550h730/20250810/d797-7c5b7e798060955f979a44acbd8208d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-10/doc-infkpkpp1121845.shtml', '直播吧', '<p>　　来源：直播吧</p> \n<p>　　直播吧8月10日讯 北京时间20：00，中超第20轮武汉三镇vs梅州客家，比赛在武汉体育中心体育场打响！上半场，帕拉西奥斯进球被判无效；奥马尔松帮助梅州客家客场取得领先！下半场，绍尔任意球世界波扳平比分；恩戈姆禁区内抽射帮助梅州客家再次领先！最终，梅州客家2-1客胜武汉三镇，近12轮首胜！武汉三镇遭遇6轮不胜！</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/480/w550h730/20250810/d797-7c5b7e798060955f979a44acbd8208d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　[比赛关键事件]</p> \n<p>　　<strong>第19分钟，梅州客家客场率先取得领先！恩戈姆手术刀直塞，奥马尔松斜插禁区内左侧，左脚推射远角破门！梅州客家1-0领先武汉三镇↓</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/2b83-gifd6cc1ef3213270580100b23b39e152e8.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/1e1c-gif7e3257e8b04e866a218d63f91ecb7f15.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/a058-gif5495a0812b94de6b0a43532860d0277c.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>第49分钟，帕拉西奥斯倒在禁区边缘，主裁判判罚点球，随后经确认是禁区外的任意球↓</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/6c6c-gif1825d8006c5b5a804282de256de6e4f6.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/4eff-gifed50af64a46b44194615bb3b78f2efbe.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>第51分钟，绍尔主罚任意球，左脚直接兜进球门远角！武汉三镇1-1扳平梅州客家↓</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/36ce-gifec5b99a108a703e6010fd354bdcbe089.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/17f8-gif1cff5fed43f540ea7afe1f257553dd83.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>第65分钟，梅州客家再次领先！右路的传中打进禁区，三镇球员解围不远，禁区内恩戈姆得球左脚抽射破门！梅州客家2-1领先武汉三镇↓</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/58da-gif774e55f53d45781e18a0adb6fc9e0d3d.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/b5c8-gifdc3c56fb869a9a159587dc6c8da8b54c.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　[比赛焦点瞬间]</p> \n<p>　　第8分钟，帕拉西奥斯禁区外远距离内切，右脚远射打高了↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/040f-gif455ba45c48744af13307af9079709898.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第16分钟，帕拉西奥斯禁区内左脚抽射破门，但主裁判吹罚进攻过程中有手球，进球无效↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/aca3-gifca68c5606cc3c2eaeca262bc64e7ed39.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第34分钟，罗德里格有些受伤，到场边治疗一下↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/a83f-gifc6386b9ec4ab1f6927dbc9f62c481e3b.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第45分钟，武汉三镇断球后高速推进，但最后下底倒三角传中被解围↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/6b04-gif37cbebce1bafab93d446392da7075d52.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第73分钟，梅州客家反击，罗德里格禁区内右侧打远角！稍稍偏出↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/1209-gif13090dff6fd1f823db8f2e68b53034f6.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第81分钟，梅州客家禁区内多名球员相撞倒地↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/66f2-gifddba203024f967cbd4f822de085b5f92.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"//f.sinaimg.cn/news/gif_image/608/w384h224/20250810/9735-gif5d419a141c1718388629c373c51d9c9b.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　第87分钟，三镇右侧角球开出，皮球被解围出来，外围汪晋贤迎球怒射！打高了↓</p> \n<div class=\"img_wrapper\">\n <img src=\"//n.sinaimg.cn/news/gif_image/608/w384h224/20250810/b802-gife63df429103b0e8bf9116e5239f7059f.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　[双方阵容]</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/34/w550h2684/20250810/46fd-ff2c4bc8a19744f2313ebd6def4834a4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1733881296\" target=\"_blank\">2025赛季中超联赛</a>\n</div> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/480/w550h730/20250810/d797-7c5b7e798060955f979a44acbd8208d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/2b83-gifd6cc1ef3213270580100b23b39e152e8.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/1e1c-gif7e3257e8b04e866a218d63f91ecb7f15.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/a058-gif5495a0812b94de6b0a43532860d0277c.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/6c6c-gif1825d8006c5b5a804282de256de6e4f6.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/4eff-gifed50af64a46b44194615bb3b78f2efbe.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/36ce-gifec5b99a108a703e6010fd354bdcbe089.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/17f8-gif1cff5fed43f540ea7afe1f257553dd83.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/58da-gif774e55f53d45781e18a0adb6fc9e0d3d.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/b5c8-gifdc3c56fb869a9a159587dc6c8da8b54c.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/040f-gif455ba45c48744af13307af9079709898.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/aca3-gifca68c5606cc3c2eaeca262bc64e7ed39.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/a83f-gifc6386b9ec4ab1f6927dbc9f62c481e3b.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/6b04-gif37cbebce1bafab93d446392da7075d52.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/1209-gif13090dff6fd1f823db8f2e68b53034f6.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/66f2-gifddba203024f967cbd4f822de085b5f92.gif\",\"https://f.sinaimg.cn/news/gif_image/608/w384h224/20250810/9735-gif5d419a141c1718388629c373c51d9c9b.gif\",\"https://n.sinaimg.cn/news/gif_image/608/w384h224/20250810/b802-gife63df429103b0e8bf9116e5239f7059f.gif\",\"https://k.sinaimg.cn/n/news/crawl/34/w550h2684/20250810/46fd-ff2c4bc8a19744f2313ebd6def4834a4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4058, NULL, '北京楼市新政落地首个周末：二手房成交忙，有新盘看房需排队', 0, 1, 1, '2025-08-11 00:30:56', '2025-08-10 23:25:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250810s/155/w1080h675/20250810/a944-cb63761254d4c9d61a245144a3e304cf.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkpkpw0427922.shtml', '新京报', '<p>　　新京报贝壳财经记者 段文平 编辑 杨娟娟 校对 卢茜</p> \n<p>　　8月8日晚北京楼市新政出台后，这个周末（8月9日-8月10日）房地产市场迅速热闹了起来。</p> \n<p>　　8月10日，丰台角门一家房产中介门店的工作人员章音（化名）向新京报贝壳财经记者介绍，刚过去的两天，门店所在片区成交不少，周边在看的好几套房子都成交了。“我周日原本约了客户去看一套房源，结果已经卖掉了，那套房可是小区里性价比最高的。”他语气里带着点惋惜。</p> \n<p>　　不只是二手房市场热度攀升，一些位置优越、配套齐全的新房项目，周末的售楼处同样人流不断。多位楼盘销售人员告诉记者，来看房的人比之前增加了不少。</p> \n<p>　　<strong>有人犹豫间错失房源，有人为买房改行程</strong></p> \n<p>　　章音说：“我手头的另一个客户，之前看中了两套还不错的房子，还想着再讲讲价、让价格再便宜点。没想到，转头就被另一家中介的客户买走了。”</p> \n<p>　　在他看来，新政出台后，不少客户的心态明显有了变化。“有些客户担心，要是成交量上来了，房价就不好往下谈了。现在这会还好议价，所以也不等了，干脆直接出手买房。”</p> \n<p>　　另一家位于西四五环间的房产中介的门店经理在接受采访时表示，楼市新政出台后，门店的咨询量和成交量均出现回升。他解释道，此前市场经历了一段调整期，自7月20日以来交易量持续偏低，而新政的落地客观上带动了市场活跃度的提升，但这种增长并非爆发式的。从当前客户特征来看，两类因素影响着市场表现：一方面，现阶段入市的购房者多为有实际居住需求的群体；另一方面，受高温天气和暑期旅游季影响，不少客户选择通过线上渠道咨询。</p> \n<p>　　具体到成交数据，该经理说，新政后首个周末成交的房源以总价200万至400万的纯刚需户型为主。这与此次新政中公积金政策释放的多重利好密切相关，政策精准契合了刚需群体的置业需求，成为推动成交的重要动力。</p> \n<p>　　北京链家当代名筑南门店商圈经理张小磊向记者透露：“新政后的周六（8月9日），店里小伙伴开始忙碌了起来。此前周末单天门店人均带看量在1次，而周六这一数字达到了1.3次；线上购房咨询量也有所增加，店里展位多的伙伴一天就接到了9个咨询。门店的咨询量相较平时增幅约30%，大家确实比之前忙了不少。”</p> \n<p>　　“新政的出台，对于犹豫的客户也起到了一定的催化剂作用，让他们觉得这个时机适合买房。”张小磊说。他举例道，王女士一家原本约定8月9日回内蒙古老家，打算暑假结束后再回来看看其他房子做对比，因为孩子还有3年才上初中，并不着急。但8月8日晚上政策出台后，他们立刻推迟了行程，把买房的事情提上了加急日程，第二天就过来约业主谈判签约，觉得早晚都得买，现在入手正合适。</p> \n<p>　　<strong>部分新房市场升温，售楼处人流增加</strong></p> \n<p>　　新政落地后，北京新房市场表现如何？</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250810s/155/w1080h675/20250810/a944-cb63761254d4c9d61a245144a3e304cf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲8月9日，昌平区朱辛庄板块一楼盘售楼处现场。新京报贝壳财经记者 段文平 摄\">\n <span class=\"img_descr\">　▲8月9日，昌平区朱辛庄板块一楼盘售楼处现场。新京报贝壳财经记者 段文平 摄</span>\n</div> \n<p>　　周末，记者走进昌平区朱辛庄板块的越秀星樾项目售楼处，眼前的景象格外热闹，洽谈区里座无虚席，沙盘区围了不少人。“上个周末还没这么多人，今天上午人流量简直乌泱乌泱的。”一位第三方带看的销售人员笑着说，“我带的一个客户，本来想算个价格，愣是没找着空位，连看房都得排队等。”</p> \n<p>　　在他看来，该板块能吸引这么多人，关键在于地段优势、配套齐全，再加上北部区域本身就有不少潜在购买力，“客户大多是从海淀过来的，对这边的位置和配套都挺认可。”</p> \n<p>　　朱辛庄板块地处北五环至北六环之间，因紧邻海淀区且处于海淀产业群的辐射圈，已然成为楼市热门区域。从项目分布来看，以朱辛庄地铁站为核心，1公里范围内有三个在售项目——越秀星樾、中海未来之境与中海寰宇未来；而在约1.7公里处，还有由越秀操盘的星耀未来项目。</p> \n<p>　　记者之后前往中海未来之境售楼处，这里同样人头攒动，热闹程度丝毫不减。因现场客户较多，销售人员分身乏术，记者在一旁等了差不多20分钟，才等到一位销售人员接待。</p> \n<p>　　“今天实在太忙了，连中午饭都没来得及吃。”项目的工作人员表示，看房量比之前明显多了。</p> \n<p>　　距朱辛庄地铁站稍远些的星耀未来项目，记者在现场看到，这里的看房人数不及前两个项目密集，但看房热情也不低。“最近来看房的人确实比之前多了不少。”销售人员说道，尤其是公积金办理时间缩短后，对年轻的刚需客群来说，是实实在在的利好。</p> \n<p>　　位于六环外的一个新盘项目工作人员表示，新政后的两天，项目到访量较上个周末增加了16%左右。“新政可能还未发酵，目前来访和成交客户趋于理性，已成交客户还是基于原有产品力和客户生活圈。”</p> \n<p>　　<strong>政策力度超预期，有望助推成交量提升</strong></p> \n<p>　　8月8日晚，北京市住房和城乡建设委员会、北京住房公积金管理中心联合印发《关于进一步优化调整本市房地产相关政策的通知》（简称“《通知》”）。其中指出，符合本市商品住房购买条件的居民家庭，购买五环外商品住房（含新建商品住房和二手住房）不限套数。对成年单身人士在本市购买商品住房的，按照居民家庭执行限购政策。</p> \n<p>　　这是继续去年“9·30”政策非京籍社保年限“五环内5改3”“五环外5改2”后，北京在限购政策上的又一重要调整。</p> \n<p>　　除限购调整外，持续加大公积金支持力度也是此次新政的重要看点，包括首套认定标准“认房不认贷”、公积金贷款额度累积加快、二套房公积金贷款最高额度由60万元提高至100万元、二套房最低首付款比例统一调整为不低于30%等等。</p> \n<p>　　合硕机构首席分析师郭毅分析称，“这次政策调整及时、有效、准确，政策力度超越市场预期。对市场成交量将形成新一轮的提升。由于政策自8月9日起实施，在这个周末政策的效果就立竿见影地体现在市场的到访量和认购量的提升上。”</p> \n<p>　　在张小磊看来，新政促使一批有需求的客户加快了买房步伐，给此前观望的客户增添了一定的入市信心，促进刚需成交，从而带动成交的第一环。同时，二套公积金贷款额度的上浮，也减轻了购房者的还款压力。</p> \n<p>　　一位开发商相关负责人表示，放开五环外多套房购买限制，最先影响的可能是五环外的新房，其次是六环外，因为政策存在一定的发酵期。此次政策其实超出了预期，毕竟此前中央政治局会议并未提及房地产相关内容，预计政策效力可持续至年底。</p> \n<p></p> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250810s/155/w1080h675/20250810/a944-cb63761254d4c9d61a245144a3e304cf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4153, NULL, '爱丁堡著名景点亚瑟王座山发生大火 浓烟全城可见', 0, 4, 206, '2025-08-11 02:30:18', '2025-08-11 01:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-11/doc-infkpvcp6309623.shtml', '央视', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　当地时间10日下午，英国苏格兰爱丁堡著名景点亚瑟王座山发生大火。当天16时左右，火势在爱丁堡荷里路德公园的山坡上迅速蔓延，火焰与浓烟在爱丁堡全城清晰可见。警方已敦促民众远离该区域。</p> \n<p>　　苏格兰消防救援局表示，消防人员已抵达火灾现场展开扑救。目前火灾原因尚不清楚。</p> \n<p>　　亚瑟王座山位于荷里路德公园，邻近爱丁堡历史悠久的旧城区。（总台记者 陈占升）</p> \n<p class=\"show_author\">责任编辑：张玉 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4164, NULL, '土耳其地震已致10余栋建筑倒塌 2人被困', 0, 4, 200, '2025-08-11 03:30:14', '2025-08-11 01:58:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/354/w739h415/20250811/f355-df83f759747c6a1a2e35511b29dee72a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpvcs0190388.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/354/w739h415/20250811/f355-df83f759747c6a1a2e35511b29dee72a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　当地时间8月10日，土耳其灾害与应急管理中心发布消息称，当天19时53分，土耳其巴勒克埃希尔省森德尔格地区发生6.1级地震，震源深度11公里。</p> \n<p>　　森德尔格市市长塞尔坎·萨克表示，地震已导致10余栋建筑倒塌。在市中心一栋倒塌建筑中，已有4人获救，另有2人仍在搜救中。目前正对这两名被困人员展开救援。（总台记者 陈慧慧）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　土耳其发生6.3级地震 震源深度10千米&gt;&gt;</p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250811/251/w1600h251/20250811/bbeb-gif815145d6eb1942fc1bbe7e75f4662e31.gif\"></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754849295\" target=\"_blank\">土耳其发生6.3级地震</a>\n</div> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/354/w739h415/20250811/f355-df83f759747c6a1a2e35511b29dee72a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4200, NULL, '厄瓜多尔西部发生枪击事件 致8人死亡', 0, 4, 59, '2025-08-11 06:30:14', '2025-08-11 02:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/139/w1113h626/20250811/3311-236ec970d366fb220c10cd4ece1ea73b.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpvci0890520.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/139/w1113h626/20250811/3311-236ec970d366fb220c10cd4ece1ea73b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　当地时间8月10日凌晨，厄瓜多尔西部瓜亚斯省圣卢西亚市发生一起枪击事件，造成8人死亡。</p> \n<p>　　据了解，10日凌晨1时左右，一伙武装分子乘坐两辆汽车抵达圣卢西亚市北部一家夜总会外，随后持枪朝人群射击，致8人死亡、3人受伤。</p> \n<p>　　警方调查显示，其中一名死者是圣卢西亚市市长乌瓦尔多·乌尔基索的兄弟。警方后续将公布更多细节。</p> \n<p>　　瓜亚斯省暴力犯罪频发，帮派斗争是主要原因之一。厄总统诺沃亚8月6日发布政令，宣布因严重内部动荡，瓜亚斯省、马纳维省等4个省进入60天紧急状态。（总台记者 邓雪梅）</p> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/139/w1113h626/20250811/3311-236ec970d366fb220c10cd4ece1ea73b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4217, NULL, '“特普会”倒计时 美俄还在酝酿更大的核博弈', 0, 4, 207, '2025-08-11 07:30:22', '2025-08-11 06:59:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/153/w610h343/20250811/beb1-4c23b2bf451b1dc1a3da17d40989d5ec.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqftc0643213.shtml', '央视', '<p cms-style=\"font-L\">　　上周，就在美国设定俄乌达成和平协议的所谓“最后期限”仅剩1天时，传出俄美将举行元首会晤的消息。有分析称，这次会晤备受关注，但不能掩盖美俄间仍在激烈博弈的事实。近期双方口水战步步升级，有关核部署与核条约等话题不断被抛出，引发严重关切。美国公共广播公司称，如今美俄之间只剩下一个核武器条约，新的军备竞赛是可能的。</p> \n<p cms-style=\"font-L\">　　美国总统特朗普与俄罗斯总统普京将于8月15日在美国阿拉斯加州会晤，讨论乌克兰危机。<font cms-style=\"font-L strong-Bold\">此次会晤将是2019年在二十国集团峰会期间见面后，特朗普和普京再次面对面会晤。</font></p> \n<p cms-style=\"font-L\">　　至于特朗普此前提到的计划举行美俄乌三方会晤，他给予了模糊化回应。有记者提问：“普京是否必须先与泽连斯基会面，然后你才能与普京会面？”对此，特朗普只是回应说“不需要”。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/153/w610h343/20250811/beb1-4c23b2bf451b1dc1a3da17d40989d5ec.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L strong-Bold align-Center\">　　“最后通牒”仍有效</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　美俄“口水战”持续升级</p> \n<p cms-style=\"font-L\">　　不过，特朗普还表示，美方对俄“最后通牒”的期限仍然有效。</p> \n<p cms-style=\"font-L\">　　当地时间7月28日，特朗普在苏格兰访问时表示，他对俄罗斯总统普京“十分失望”，并考虑缩短此前对俄设置的50天内达成俄乌和平协议的期限。</p> \n<p cms-style=\"font-L\">　　对此，俄罗斯前总统、现任联邦安全会议副主席梅德韦杰夫第二天在社交媒体X上回怼称：“俄罗斯不是以色列或伊朗，每一条最后通牒都是一种威胁，是迈向战争的一步。”</p> \n<p cms-style=\"font-L\">　　7月31日，美国驻联合国代表约翰·凯利在安理会会议上强硬表态称：“特朗普总统已明确要求，俄乌必须在8月8日前达成停火协议。”</p> \n<p cms-style=\"font-L\">　　同一天，特朗普在真实社交上发文，称梅德韦杰夫为“失败的前总统”，并警告他要“注意措辞”。</p> \n<p cms-style=\"font-L\">　　很快，梅德韦杰夫又在电报平台回应说：</p> \n<p cms-style=\"font-L\">　　让他（特朗普）记住这些关于‘行尸走肉’的电影，以及自然界中的‘死亡之手’有多危险。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/181/w629h352/20250811/3411-d31cd43bf31315ffcfcf810481f7549f.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　美国媒体猜测，此番言论可能是指一部末世题材的美剧，暗示美俄核战争将导致世界毁灭。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　“最明确的核威胁”</p> \n<p cms-style=\"font-L\">　　另一方面，双方“口水战”还在继续升级。</p> \n<p cms-style=\"font-L\">　　当地时间8月1日，特朗普在“真实社交”宣称，已下令将两艘美国核潜艇部署至“适当区域”。据路透社报道，所谓“适当区域”很可能是指俄罗斯附近海域。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">美国总统 特朗普：</font>当你提到“核”这个词时，我的眼睛亮了起来。我说，我们最好小心点，因为这是终极威胁。</p> \n<p cms-style=\"font-L\">　　8月4日，俄罗斯总统新闻秘书佩斯科夫提醒称，核战争不可能有赢家，各方在涉及核问题上的表态都应保持严谨。</p> \n<p cms-style=\"font-L\">　　印度新德里电视台认为，<font cms-style=\"font-L strong-Bold\">当前美俄之间围绕“核”的对峙，是古巴导弹危机以来“最明确的核威胁”</font>。</p> \n<p cms-style=\"font-L\">　　美国智库“战争研究所”则认为，这是一场相互释放“战略信号”的压力测试。</p> \n<p cms-style=\"font-L\">　　据英国《每日电讯报》报道，虽然特朗普并未透露潜艇的具体型号，但军事分析人士推测，美国此次部署的<font cms-style=\"font-L strong-Bold\">很可能是美国海基核威慑体系的核心力量——“俄亥俄”级战略核潜艇</font>。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　“美俄核力量势均力敌</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　海陆空全面对峙”</p> \n<p cms-style=\"font-L\">　　根据非营利组织“核威胁倡议”的数据（Nuclear Threat Initiative），美国海军现役71艘核潜艇，是世界上规模最大的水下舰队，其中包括14艘“俄亥俄”级战略核潜艇（SSBN），每艘最多可携带24枚“三叉戟II”潜射洲际导弹，射程超过12000公里，单枚弹头的爆炸威力达47.5万吨TNT当量，相当于投掷在日本广岛原子弹威力的30倍。4艘是为搭载“战斧”导弹而改装的“俄亥俄”级巡航导弹核潜艇（SSGN），专用于远程打击和特种作战任务，以及53艘核动力攻击潜艇（SSNs），执行情报收集、反潜和巡航导弹支援等任务。</p> \n<p cms-style=\"font-L\">　　而俄罗斯同样拥有相当强大的战略核威慑力量。</p> \n<p cms-style=\"font-L\">　　俄罗斯海军拥有约30艘现役核潜艇，其中10艘为战略核潜艇，主要由新式的“北风之神-A”级和老式的“德尔塔-IV”级组成，配备“布拉瓦”洲际弹道导弹。</p> \n<p cms-style=\"font-L\">　　7月24日，在俄罗斯西北部阿尔汉格尔斯克州北德文斯克的北方造船厂（Sevmash），俄总统普京参加了“北风之神-A”级战略核潜艇“波扎尔斯基大公”号的交付仪式。</p> \n<p cms-style=\"font-L\">　　7月27日俄罗斯海军节，普京在讲话中强调，俄罗斯“三位一体”核力量中的海基力量正不断增强，其核心正是战略核潜艇部队。</p> \n<p cms-style=\"font-L\">　　按照普京宣布的《2050年前俄罗斯海军发展战略》，未来几年内，俄罗斯海军将新增4艘“北风之神-A”级战略核潜艇，持续推进“亚森-M”级核动力攻击潜艇的建造工作，加快水下舰队的现代化进程。</p> \n<p cms-style=\"font-L\">　　一位英国皇家海军退役准将和前潜艇指挥官认为，美俄无论在核潜艇数量还是能力上都无太大差别。事实上，美俄“核对峙”不仅发生在海洋，还发生在陆地和天空。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　美加紧部署核武</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　俄宣布不再受《中导条约》约束</p> \n<p cms-style=\"font-L\">　　当地时间8月4日，俄罗斯外交部宣布，俄方将不再维持依据《中导条约》单方面暂停部署陆基中程和中短程导弹系统的自我限制。</p> \n<p cms-style=\"font-L\">　　《中导条约》全称《苏联和美国消除两国中程和中短程导弹条约》，由时任美苏首脑里根和戈尔巴乔夫于1987年12月8日共同签署。条约规定，两国不得保有、生产或试验射程在500至5500公里的陆基巡航导弹和弹道导弹。作为这一协议的重要成果，双方共销毁了2600余枚导弹，被视为冷战时期的重要突破。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">该条约是战后美、苏裁军谈判历史上达成的第一个真正减少核武器数量的条约</font>。</p> \n<p cms-style=\"font-L\">　　然而，2019年，美国单方面宣布退出《中导条约》。</p> \n<p cms-style=\"font-L\">　　法国《费加罗报》批评称，美国退出《中导条约》是核裁军进程中的一处<font cms-style=\"font-L strong-Bold\">“刀伤”</font>。</p> \n<p cms-style=\"font-L\">　　俄外交部则发表声明称，美方此举意味着《中导条约》已经“正式失效”。在美方退约后，俄方表示，在相关地区出现美制导弹系统前，俄将自愿限制相关陆基导弹部署。</p> \n<p cms-style=\"font-L\">　　然而，美国战略与国际问题研究中心证实，美国在退出《中导条约》后，不断扩大其中导能力，并将其部署至盟国。</p> \n<p cms-style=\"font-L\">　　2024年，美国在菲律宾部署“堤丰”中程导弹系统，并在演习结束后将其滞留；</p> \n<p cms-style=\"font-L\">　　2025年7月，美军在澳大利亚举行的“护身军刀”联合军演中，首次在境外利用“堤丰”系统进行实弹发射测试。</p> \n<p cms-style=\"font-L\">　　同月，据英国《泰晤士报》报道，美国已将数枚B61-12型核弹正式部署至英国萨福克郡的拉肯希思皇家空军基地，这是美国时隔17年再次在英国境内部署核武器。</p> \n<p cms-style=\"font-L\">　　也是在7月，美德两国宣布，到2026年，美国将在德国部署能够打击俄罗斯腹地目标的陆基中程导弹，包括三种类型的美国陆基中程武器：标准-6导弹（SM-6）、战斧巡航导弹（LACMs）和远程高超音速武器。</p> \n<p cms-style=\"font-L\">　　而在俄宣布不受《中导条约》约束后，梅德韦杰夫在X上发帖称：“这是我们的所有反对者必须面对的新现实。”</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　“美秀肌肉却难掩捉襟见肘”</p> \n<p cms-style=\"font-L\">　　有分析称，美国一边借助海军以及核力量不断秀肌肉，一边又在军舰维护方面捉襟见肘，这体现出美国在维护全球霸权方面的虚张声势和力不从心。</p> \n<p cms-style=\"font-L\">　　美国在奥巴马政府后期，曾考虑宣布“不首先使用”核武器的政策。拜登政府则强调“降低核武器在美国战略中作用”。但特朗普的第一任期从未考虑过“不首先使用”核武器政策，并在第二任期宣布所谓的“金色穹顶”计划，被外界视为里根“星球大战”的2.0版本。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">这也间接推动了美俄重演“冷战核对抗”的剧本</font>。</p> \n<p cms-style=\"font-L\">　　据半岛电视台报道，美俄两国几乎掌握了全球核武力量的主导权。两国合计拥有约<font cms-style=\"font-L strong-Bold\">87%</font>的全球核武库存，并控制着约<font cms-style=\"font-L strong-Bold\">83%</font>已部署或具备实战能力的核弹头。</p> \n<p cms-style=\"font-L\">　　今年1月，瑞典斯德哥尔摩国际和平研究所发布报告显示，截至2025年1月，美国已在数百架轰炸机和导弹上共部署了1770枚核弹头，俄罗斯部署的数量为1718枚。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　“新军备竞赛不无可能”</p> \n<p cms-style=\"font-L\">　　美国公共广播公司分析认为，美俄之间只剩下一个核武器条约，新的军备竞赛是可能的。这个俄美间仅剩的核武器条约是指2010年4月签署的《新削减战略武器条约》，但该条约将于明年2月5日到期。</p> \n<p cms-style=\"font-L\">　　今年是世界第一枚原子弹爆炸80周年，人类从那时起正式进入“原子时代”。然而随着北约加速大规模增加国防开支、扩军备战，今年6月斯德哥尔摩国际和平研究所发布的年度报告警告说：<font cms-style=\"font-L strong-Bold\">新军备竞赛迫在眉睫，核风险也随之增加</font>。</p> \n<p cms-style=\"font-L\">　　正如“原子弹之父”奥本海默所说的：灾难降临的时候，没有人是一座孤岛。当越来越多“黑天鹅”事件可能发生的时候，<font cms-style=\"font-L strong-Bold\">大国间的战略稳定显得尤为重要</font>。</p> \n<p cms-style=\"font-L\">　　</p> \n<p></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/153/w610h343/20250811/beb1-4c23b2bf451b1dc1a3da17d40989d5ec.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/181/w629h352/20250811/3411-d31cd43bf31315ffcfcf810481f7549f.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4218, NULL, '伊朗谴责以色列接管加沙城计划', 0, 4, 91, '2025-08-11 07:30:29', '2025-08-11 06:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/105/w1024h681/20250811/3690-9174110788a56bd997f36c33204a879d.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqfti6080554.shtml', '央视', '<p cms-style=\"font-L\">　　伊朗外交部当地时间10日发表声明，谴责以色列接管加沙城计划，强调国际社会有责任制止种族灭绝并向加沙被压迫人民提供援助。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/105/w1024h681/20250811/3690-9174110788a56bd997f36c33204a879d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△当地时间8月7日，加沙地带\">\n <span class=\"img_descr\">△当地时间8月7日，加沙地带</span>\n</div> \n<p cms-style=\"font-L\">　　声明说，这是以色列实施对巴勒斯坦人种族灭绝和消灭巴勒斯坦计划的一部分。以色列政府必须立即停止对加沙的攻击，无条件向该地区运送人道主义援助，保证救济组织在该地区的行动自由，支持地区和国际社会实现全面停火的努力。</p> \n<p cms-style=\"font-L\">　　以色列总理办公室8日说，以安全内阁已批准总理内塔尼亚胡关于“击败哈马斯”的计划，以军准备接管加沙城。多个国家和国际组织纷纷发声谴责这一决定，敦促以方立即停止“战争计划”。</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L color240\"></font></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/105/w1024h681/20250811/3690-9174110788a56bd997f36c33204a879d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4220, NULL, '美财长：正牵头物色鲍威尔的继任人选', 0, 4, 207, '2025-08-11 07:30:37', '2025-08-11 05:48:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/700/w900h600/20250811/083e-2fd2cbc778075bd516e36ca16e196c4b.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpzmq0077585.shtml', '央视', '<p>　　当地时间8月10日，美国财政部长贝森特表示，他正牵头物色美国联邦储备委员会主席鲍威尔的继任人选。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/700/w900h600/20250811/083e-2fd2cbc778075bd516e36ca16e196c4b.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△美国财政部长贝森特（资料图）\">\n <span class=\"img_descr\">　△美国财政部长贝森特（资料图）</span>\n</div> \n<p>　　贝森特表示，新任美联储主席应具备审视整个机构的能力，赢得市场信任、能分析复杂经济数据，并注重前瞻性思维而非依赖历史数据。</p> \n<p>　　近期，美国总统特朗普连续发声，要求美联储委员会进一步降息，并以下一任美联储主席人选的话题对现任主席鲍威尔施压。鲍威尔回应称，美联储货币政策必须“完全非政治”，重申美联储仍在观察美国关税带来的影响，而后再进一步决策。</p> \n<p>　　鲍威尔的任期应于2026年5月结束，他在特朗普第一任期内被提名为美联储主席。美国总统通常会在现任美联储主席任期最后几个月才宣布下一任提名人选。（央视记者 吴汉婴）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　特朗普再次呼吁：鲍威尔应引咎辞职&gt;&gt;</p>\n<p cms-style=\"font-L\">　　特朗普：鲍威尔再不降息 美联储理事会应接管控制权&gt;&gt;</p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250811/251/w1600h251/20250811/bbeb-gif815145d6eb1942fc1bbe7e75f4662e31.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/700/w900h600/20250811/083e-2fd2cbc778075bd516e36ca16e196c4b.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4226, NULL, '美韩将举行联合军演 朝鲜：强烈谴责 严正警告', 0, 4, 147, '2025-08-11 07:30:43', '2025-08-11 05:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-11/doc-infkpzmq0076611.shtml', '央视', '<p>　　朝鲜国防相努光铁当地时间10日发表谈话，谴责美韩即将开始举行的“乙支自由护盾”联合军演。</p> \n<p>　　谈话称，美韩毫不掩饰地暴露出对朝鲜的军事对抗立场，给朝鲜半岛和地区的安保环境再次带来严重挑战。朝方强烈谴责美韩的有关挑衅行为，并就其将导致的负面后果作出严正警告。</p> \n<p>　　努光铁表示，向朝鲜炫耀武力，其效果将会适得其反，必将使美韩的安保处于更不安全的状态。遏制敌国的攻击行为，应对军事挑衅，维护国家安全和地区和平，是朝鲜武装力量的绝对使命。朝鲜将以彻底而果断的态度应对美韩演习，并将对越线的任何挑衅行为严正行使自卫权范围内的主权权利。</p> \n<p>　　此前，韩国联合参谋本部和驻韩美军共同发布消息称，2025年韩美“乙支自由护盾”联合军演将于8月18日至28日进行。（总台记者 董海涛）</p> \n<p class=\"show_author\">责任编辑：张玉 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4227, NULL, '土耳其地震已致1死29伤 十余栋建筑被毁', 0, 4, 200, '2025-08-11 07:30:49', '2025-08-11 05:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/520/w792h528/20250811/dce9-5832e9cdfb60b33ade563a5dc9dae180.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpzmq0073049.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/520/w792h528/20250811/dce9-5832e9cdfb60b33ade563a5dc9dae180.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△土耳其内政部长耶尔利卡亚\">\n <span class=\"img_descr\">　△土耳其内政部长耶尔利卡亚</span>\n</div> \n<p>　　当地时间8月10日晚，土耳其内政部长耶尔利卡亚表示，该国西部巴勒克埃希尔省森德尔格地区当天发生6.1级地震，目前已造成1人死亡、29人受伤。目前伤者整体情况良好。</p> \n<p>　　耶尔利卡亚表示，共有16栋建筑在地震中被毁，其中12栋为空置建筑。</p> \n<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　据悉，此次地震发生在当地时间10日19时53分，震源深度11公里，震感波及约200公里外的伊斯坦布尔等地。土耳其灾害与应急管理中心称，震后发生多次余震，其中一次为4.6级。（总台记者 陈慧慧）</p> \n<p></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754849295\" target=\"_blank\">土耳其发生6.3级地震</a>\n</div> \n<p class=\"show_author\">责任编辑：张玉 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/520/w792h528/20250811/dce9-5832e9cdfb60b33ade563a5dc9dae180.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4228, NULL, '以色列军方仍在研究进攻加沙城所需兵力', 0, 4, 95, '2025-08-11 07:31:02', '2025-08-10 23:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/107/w1024h683/20250811/44ea-debe3c6d97ee112d427eab52425ae6b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpvcn9230723.shtml', '央视', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>当地时间10日获悉，<font cms-style=\"font-L strong-Bold\">以色列军方目前仍在研究对加沙城发起进攻所需兵力</font>。有以军官员表示，这个时间预计可能要一周，届时以军才会知道所需兵力及驻扎时间。但无论如何，都需征召预备役士兵。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/107/w1024h683/20250811/44ea-debe3c6d97ee112d427eab52425ae6b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△当地时间8月10日，加沙地带\">\n <span class=\"img_descr\">△当地时间8月10日，加沙地带</span>\n</div> \n<p cms-style=\"font-L\">　　以色列总理办公室8日说，以安全内阁已批准总理内塔尼亚胡关于以军接管加沙城的计划。多国和国际组织纷纷发声予以谴责，认为这一决定“疯狂”，只会造成更多流血事件，敦促以方立即停止其“战争计划”。（总台记者 梁慧）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L color240\"></font></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/107/w1024h683/20250811/44ea-debe3c6d97ee112d427eab52425ae6b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4229, NULL, '苏丹西部法希尔市过去一周至少63人因饥饿死亡', 0, 4, 184, '2025-08-11 07:31:08', '2025-08-10 22:37:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250810/0/w1024h576/20250810/2e71-64229f92ea4066519142220a127b3956.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkpkpp1117778.shtml', '央视', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>当地时间8月10日获悉，在过去一周，苏丹西部北达尔富尔州法希尔市<font cms-style=\"font-L strong-Bold\">至少有63人因饥饿和营养不良死亡</font>，其中大部分是妇女和儿童。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250810/0/w1024h576/20250810/2e71-64229f92ea4066519142220a127b3956.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△法希尔市（资料图）\">\n <span class=\"img_descr\">△法希尔市（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　有媒体援引一名苏丹卫生部官员的话称，这个数字只统计了在当地医院和医疗机构内死亡的人员，由于安全局势危急，还有很多因饥饿死亡的当地民众并未统计在内。</p> \n<p cms-style=\"font-L\">　　法希尔市是苏丹武装冲突的主战场之一。自2024年5月以来，苏丹武装部队与苏丹快速支援部队围绕法希尔市的控制权展开持续争夺，当地人道主义局势持续恶化。</p> \n<p cms-style=\"font-L\">　　2023年4月15日，苏丹武装部队与苏丹快速支援部队在首都喀土穆爆发武装冲突，战火随后蔓延至其他地区。持续两年多的武装冲突已造成近3万人丧生，超1200万人流离失所。（总台记者 赵远方）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250810/0/w1024h576/20250810/2e71-64229f92ea4066519142220a127b3956.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4230, NULL, '早间播报【2025年8月11日】', 0, 1, 1, '2025-08-11 07:31:16', '2025-08-11 06:21:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/224/w1280h544/20250811/7514-2ed4a6151f75a7e9bf736a9544408dad.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqfth8992528.shtml', '安徽省纪委监委网站', '来源：安徽纪检监察网\n<br>\n<br>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/224/w1280h544/20250811/7514-2ed4a6151f75a7e9bf736a9544408dad.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/3e9e-dbad2e1c49501a487d7575773d69a3e1.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　● 8月9日夜间至8月10日凌晨，北京天安门地区举行了纪念中国人民抗日战争暨世界反法西斯战争胜利80周年大会第一次综合演练，演练组织有序，达到预期目标。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/e28f-8ffeef2a7d049e43d623043c5d6e499b.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"2\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　● 今天出版的中国纪检监察报头版头条刊发“注重家庭家教家风建设系列综述”之一《涵养良好家风 筑牢家庭防线》。</p>\n<p cms-style=\"font-L\">　　● 今天出版的中国纪检监察报头版发表评论《持续加强新时代党员干部家风建设》指出：党员干部特别是领导干部要持续涵养新时代共产党人良好家风，做优良家风的建设者和引领者，把家庭打造成砥砺品行的“磨刀石”、抵御贪腐的“防火墙”。</p>\n<p cms-style=\"font-L\">　　● 今天出版的中国纪检监察报头版以《坚持由风查腐、由腐纠风双向突破》为题，报道了纪检监察机关贯彻落实中央纪委四次全会精神，强化系统观念，树立整体思维，把准由风及腐的利益链，构建由腐纠风的工作链，深入推进风腐同查同治的相关举措。</p>\n<p cms-style=\"font-L\">　　● 今天出版的中国纪检监察报广安观潮专栏发表“增强党性系列谈”之四《纯正道德品质》指出：涵养高尚的道德品质是我们党对党员干部的一贯要求，只有不断加强党性锤炼，明大德、守公德、严私德，其才方能用得其所。</p>\n<p cms-style=\"font-L\">　　● 今天出版的中国纪检监察报以《当好案件质量把关人》为题，报道了全国纪检监察系统先进集体、甘肃省纪委监委案件审理室违纪违法审理处的先进事迹。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/41b0-95720524f212337e0c2edf5b0ed01098.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　● 10日，国家防总先后针对四川、贵州启动防汛四级应急响应。</p>\n<p cms-style=\"font-L\">　　● 截至目前，全国已建立退役军人服务中心（站）61万多个，基本形成了覆盖全域的退役军人服务保障体系。</p>\n<p cms-style=\"font-L\">　　● 山东临沂警方通报“树拍”APP涉嫌集资诈骗案，王某庆、崔某龙等多名犯罪嫌疑人已被采取刑事强制措施。</p>\n<p cms-style=\"font-L\">　　● 省水利厅消息：该厅根据《安徽省水利厅水旱灾害防御应急响应工作规程》，决定自8月9日22时起，对六安、安庆市启动洪水防御Ⅳ级应急响应。</p>\n<p cms-style=\"font-L\">　　● 省气象台10日预报：10日-11日沿淮到沿江部分地区大雨到暴雨、局部大暴雨。12-15日我省部分地区有雷阵雨天气。16-19日全省多云到晴天。10-16日全省无明显高温天气，仅16日江南部分地区最高气温35℃左右；17-19日全省大部分地区最高气温在34～37℃。</p>', '[\"https://k.sinaimg.cn/n/spider20250811/224/w1280h544/20250811/7514-2ed4a6151f75a7e9bf736a9544408dad.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/3e9e-dbad2e1c49501a487d7575773d69a3e1.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/e28f-8ffeef2a7d049e43d623043c5d6e499b.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/10/w720h90/20250811/41b0-95720524f212337e0c2edf5b0ed01098.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4231, NULL, '驻省政府办公厅纪检监察组：严把任前廉洁关 以考促学筑防线', 0, 1, 27, '2025-08-11 08:30:21', '2025-08-11 08:24:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/452/w750h502/20250811/9797-fd402718525057086224eb09949f7cb8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftm9968711.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　“此次考试是对我学习成果的一次检验，更是督促我知敬畏、守底线、存戒惧的提醒教育，今后我将以更高标准要求自己，守好廉洁自律底线，不辜负组织对我的培养与信任。”近日，省纪委监委派驻省政府办公厅纪检监察组对9家监督单位168名符合提拔晋升处级领导职务职级条件的干部开展廉政法规知识测试。</p>\n<p cms-style=\"font-L\">　　自2015年以来，纪检监察组坚持以任前廉政考试为抓手，持续推动纪律教育常态化长效化，为组织提拔干部提供有力支持。截至目前，累计有1762人参加任前廉政考试，合格率达到98%。</p>\n<p cms-style=\"font-L\">　　“将廉政法规知识考试作为干部任前的‘必经程序’，目的是增强党员干部学习党纪法规和党的理论知识的自觉性，强化纪法意识和理论修养，促使他们少犯错、不犯错。”纪检监察组主要负责人表示。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/452/w750h502/20250811/9797-fd402718525057086224eb09949f7cb8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　为达到以考促学、以考促廉的目的，纪检监察组不断探索建立廉政考试长效机制，各被监督单位提拔为正、副处级职务的领导干部，包括非领导职务转任领导职务、职务晋升等均须参加考试。目前，任前廉政考试已成为被监督单位干部廉政知识和理论知识的“补习班”、谨慎用权的“警醒剂”、领导干部履新的“硬指标”。</p>\n<p cms-style=\"font-L\">　　“通过廉政考试，改变了过去零星式、碎片化的学习方式，敦促自己对党纪法规进行全面、系统的掌握。”参与廉政考试的干部纷纷表示。</p>\n<p cms-style=\"font-L\">　　纪检监察组还精心汇编450余道《廉政法规知识测试复习资料》，以“政治品德+廉洁纪律”双维度考核，内容涵盖宪法法律、党纪党规、政治理论、理想信念、职业道德等。同时，根据新形势新要求对题库进行更新，确保考试内容与时俱进、精准聚焦。</p>\n<p cms-style=\"font-L\">　　与此同时，纪检监察组不断前移干部选拔任用关口，做实做细廉政档案规范化建设，探索建立处级干部大数据平台，按照“一人一档、动态管理”要求，准确如实采集个人信息，结合问题线索处置、党风廉政回复意见等情况，精准绘制廉洁“画像”，为选人用人、评先评优提供第一手资料。今年以来，党风廉政意见回复中运用廉政法规知识考试成绩117人次，重点岗位“一对一”提醒谈话76人次，开展警示教育16场次。</p>\n<p cms-style=\"font-L\">　　下一步，纪检监察组将持续推出“廉政套餐”，运用廉政谈话、警示教育、全覆盖“约谈月”活动、廉政专题党课、专题调研等方式，督促党员干部筑牢拒腐防变的思想防线。同时，运用好“室组地”联动、专项监督检查等方式，及时发现党员干部苗头性、倾向性问题，精准运用“四种形态”，把对党员干部的严管厚爱落到实处。（供稿 任俊颖&nbsp; 编辑 张莉）</p>', '[\"https://k.sinaimg.cn/n/spider20250811/452/w750h502/20250811/9797-fd402718525057086224eb09949f7cb8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4232, NULL, '广西桂林聚焦重点强化政治监督 保障重大发展项目落地见效', 0, 2, 215, '2025-08-11 08:30:43', '2025-08-11 07:51:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftc0656024.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　“施工进展如何？施工质量怎么把关？资金使用情况怎么样？”近日，在广西壮族自治区桂林市长塘水库项目施工现场，市纪委监委驻点监督小组对照政治监督工作清单，采取实地走访、个别谈话、查阅资料等方式开展监督检查。针对发现的征地拆迁、行政审批、项目招投标等方面的廉洁风险，梳理形成负面清单，进行点对点反馈，压实整改责任，保障项目建设廉洁高效。</p>\n<p cms-style=\"font-L\">　　长塘水库是纳入国家“十四五”规划、国务院部署实施的150项重大水利工程之一。桂林市纪委监委将长塘水库建设项目列入政治监督工作清单，统筹“室组地企”监督力量，成立驻点监督小组，聚焦项目规划、施工建设、资金拨付等关键环节开展驻点监督。今年以来，驻点监督小组共列席长塘水库工程建设工作推进会5次，开展实地监督检查39次，与相关部门主要负责人面对面提醒谈话5人次，推动完善“三重一大”议事规则实施细则等制度47项。</p>\n<p cms-style=\"font-L\">　　“我们联合发改、财政、商务等部门，结合全市产业园区改革发展2025年工作要点以及长塘水库等重大发展项目、市公共资源交易中心公开招投标工程项目等，开列政治监督工作清单，明确监督重点，细化监督方式，确保监督聚焦在关键人关键事。”桂林市纪委监委党风政风监督室主任刘峥介绍。</p>\n<p cms-style=\"font-L\">　　5月中旬，桂林市纪委监委驻市交通运输局纪检监察组在外环高速公路灵川段项目施工现场开展监督检查时，发现项目施工进度滞后。经走访了解，原来该项目在施工过程中，由于炸石震损多户村民房屋，村民向相关部门反映问题后，却迟迟未解决，导致产生矛盾纠纷，项目暂停施工。该纪检监察组将问题反馈至项目指挥部，督促相关部门组织召开协调会，邀请公安部门和第三方鉴定公司现场勘察，制定处置方案，依法依规及时处理，加快恢复项目施工。</p>\n<p cms-style=\"font-L\">　　办案是最有力的监督。桂林市各级纪检监察机关以深化保护好漓江保护好桂林山水监督、重大发展项目监督、领导干部插手工程建设和招投标腐败问题整治为有力抓手，对“靠水吃水”“管项目吃项目”等问题线索进行大起底大排查，梳理隐身幕后当“影子”、明来暗往铺路子等8种情形，贯通用好自查自纠、日常监督等措施，深化运用大数据监督平台追踪资金流、分析权力网、排查关系圈，严肃查处违纪违法典型案件。</p>\n<p cms-style=\"font-L\">　　今年以来，桂林市各级纪检监察机关深入重大发展项目建设一线开展监督检查239次，运用大数据监督平台对接民政、市场监管等数据，“线上+线下”筛查比对，锁定异常钱、异常人、异常事等潜在廉洁风险点242个，处置问题线索263件，立案查处违规插手工程建设和招投标腐败问题169件，处分145人，挽回经济损失5577万余元。（通讯员 潘攀 李雅婷）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4233, NULL, '我说变化丨“解决问题变快了”', 0, 2, 215, '2025-08-11 08:30:51', '2025-08-11 07:51:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftm9963669.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　刘兴群，广西壮族自治区资源县中峰镇枫木村村民。</p>\n<p cms-style=\"font-L\">　　今年4月，我开渠放水灌溉，发现水半天没流到田里。我怕耽误种田，就赶紧联系了村支书。村支书马上就到现场来了，其他村民听到消息也赶了过来。经过大家仔细观察，发现是公路边岔路下通水管道塌陷又堆积了淤泥和垃圾，导致水流不畅。</p>\n<p cms-style=\"font-L\">　　为了不影响灌溉，我们当即联名写了份申请维修水利渠道的报告到镇里。令我们没想到的是，仅仅过了3天，镇财经办就领着去年负责修这条水渠的施工老板来换了新的涵管，灌溉问题解决了。</p>\n<p cms-style=\"font-L\">　　这么快解决问题，放在之前难以想象。2005年，我们村的山林被列入生态公益林范围，并按户发放相应的补偿款。后来因为林权改革，为防止补偿款错发，2009年起暂停发放。直到2015年8月，县林业局发布通知：“凡在2015年9月25日前签订管护合同的，全额补发2009年至2014年的补偿基金。”</p>\n<p cms-style=\"font-L\">　　当时我收到通知后，就和几个村民把申报材料交到镇林业站。之后其他村民都陆续收到了补偿金，但我却一分钱都没收到。</p>\n<p cms-style=\"font-L\">　　我去林业站询问，起初工作人员还算耐心，告诉我走完程序就能收到补偿金了。可我迟迟没收到，就反复找林业站的工作人员问，去的次数多了，对方就不耐烦了，甚至还躲着我。</p>\n<p cms-style=\"font-L\">　　一直到2019年，我才收到400多元的补偿金。</p>\n<p cms-style=\"font-L\">　　去年，我和其他村民聊天，发现别的村民和我条件差不多，领的补偿金却比我多。我想难道是漏发了？于是我到镇农业农村综合服务中心反映情况，可根本没人搭理我。无奈之下，我只好把相关情况反映给县纪委监委。</p>\n<p cms-style=\"font-L\">　　经过调查，原来是原林业站站长唐某在我递交申报材料后，拖了3年才上报，导致漏发了我1300多元的补偿金。后来，唐某因为违反工作纪律，受到了党内警告处分，我也在去年底收到了漏发的补偿金。</p>\n<p cms-style=\"font-L\">　　针对这件事，镇纪委专门到村里开会通报案情，教育镇、村干部做事要认真负责，服务好群众。从那以后，镇里的干部工作态度好了很多，尤其是办事效率提高了。</p>\n<p cms-style=\"font-L\">　　想想以前跑断腿、磨破嘴都解决不了的问题，现在没几天就给处理好了，这变化让我打心眼里觉得温暖、踏实，也对今后的日子更有盼头了！（通讯员 滕春香 蒋泽银 整理）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4234, NULL, '清风为伴产业兴 | 路畅通 茶飘香', 0, 1, 18, '2025-08-11 08:30:58', '2025-08-11 07:05:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqfth9011896.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　当清晨第一缕阳光透过薄雾洒在茶园时，广西壮族自治区梧州市苍梧县六堡镇的茶农们已背着竹篓穿行在连绵的茶山上，指尖上下翻转间便娴熟地把一芽二三叶的嫩梢摘下、放入篓中，一派忙碌景象。</p>\n<p cms-style=\"font-L\">　　“路通产业兴！现在茶农们的鲜茶叶‘出山’的速度快了很多，茶厂以订单模式收购他们的茶青，大大增加了茶农的收入。”近日，苍梧县纪委监委“室组地”联合监督组来到六堡镇四柳村开展监督回访时，该村党支部书记易志渊向纪检监察干部介绍着茶山乡间道路修建通行后的变化。</p>\n<p cms-style=\"font-L\">　　此前，苍梧县纪委监委班子成员在四柳村蹲点监督时，一些茶农反映因茶园在高山深处，道路崎岖，运输困难，茶叶采摘后不能快速运到茶厂，成为他们难以摆脱的困境，村民们想要修建一条产业路的意愿十分强烈。</p>\n<p cms-style=\"font-L\">　　“高山云雾出好茶，丘陵山地为六堡茶生长提供优渥的自然条件，不能让道路不畅成为阻碍产业发展的绊脚石。”该县纪委监委将该问题列入重点监督清单跟进监督，督促六堡镇和县职能部门加强实地调研、主动履职，推动建成了一条连通茶园和茶厂的产业路。在此过程中，该县纪委监委紧盯项目资金管理使用、建设项目实施、干部作风等开展监督，为“路畅通，茶飘香”提供纪律保障。</p>\n<p cms-style=\"font-L\">　　近年来，梧州市坚持规划引领、提质赋能、服务优化、品牌塑造、集聚发展，进一步强龙头、补链条、聚集群，推动六堡茶产业做大做强，使其发展成为助力乡村振兴的支柱产业。2024年，梧州六堡茶精制茶产量近4万吨，综合产值超250亿元，呈现出产销两旺、量价齐升的良好势头。</p>\n<p cms-style=\"font-L\">　　“在全市推动六堡茶产业深入发展过程中，涉及资金项目增多，群众受益面逐步扩大，纪检监察机关要做到产业发展到哪里，监督检查就跟进到哪里。”梧州市纪委监委有关负责同志表示。</p>\n<p cms-style=\"font-L\">　　该市纪委监委制定监督工作方案，聚焦政策落实、茶园建设、强企培育、联农带农、品质品牌提升等重点领域重点环节强化监督，充分运用片区协作机制定期开展监督检查。针对监督发现的突出问题，该市纪委监委实行项目化推进、流程化运作、清单化管理，形成“发现问题—督促整改—堵塞漏洞”的监督闭环，推动解决产业发展中的难点堵点问题和茶农茶企的急难愁盼。今年以来，该市纪检监察机关围绕六堡茶产业发展共开展监督检查79次，发现并督促整改问题24个。</p>\n<p cms-style=\"font-L\">　　提档升级、提质增效才能更好地让六堡茶产业发展成为一张极具特色的“茗片”。该市纪委监委驻市农业农村局、驻市市场监督管理局纪检监察组“组组”联动，聚焦茶企培育、品质品牌建设对相关职能部门开展驻点监督，重点检查是否存在政策“空转”或执行变形走样问题，重点整治管理服务过程中的不作为、慢作为、乱作为，对监督发现的政策宣传解读不到位、审核材料进度慢等问题，通过制发监督整改函、约谈提醒等方式督促解决。</p>\n<p cms-style=\"font-L\">　　从“一叶”到“一业”，在纪检监察机关监督保障和相关部门通力协作下，六堡茶的品牌价值已实现连续多年上升，持续释放着“以茶兴业”的示范效应。目前，该市涉茶合作社496个，326个行政村入股六堡茶产业，31万名群众通过参与茶叶种植、加工、销售等获得收益。（通讯员 吕晓艺）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4235, NULL, '黔西南：召开全州国资国企系统警示教育会', 0, 1, 24, '2025-08-11 08:31:05', '2025-08-11 07:02:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftc0652902.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　近日，黔西南州组织召开全州国资国企系统警示教育会，州国资委领导班子成员及各科室负责同志，州国资委监管企业领导班子成员、专职外部董事及集团公司财务、项目、人资部门、子公司负责同志等关键岗位人员，各县(市)国资监管机构负责同志等80余人集中接受警示教育。</p>\n<p cms-style=\"font-L\">　　会前，全体人员集中观看了由州纪委监委制作的国企领域专题警示片《由风及腐  在推杯换盏中迷失》，该片通过通报典型问题、典型情节形成提醒、教育和震慑，推动党员干部和公职人员深刻汲取身边案件教训、筑牢崇廉拒腐思想防线。片中某州管国有企业原党委副书记出镜剖析了自己越纪破法的堕落轨迹，让人深受震撼和警醒。</p>\n<p cms-style=\"font-L\">　　会上，州纪委监委相关负责人深入分析了当前全州国企领域党风廉政建设和反腐败斗争面临的形势，要求发挥以案促改、促治作用，督促相关责任主体深入排查梳理议事决策、制度执行、权力运行各环节体制机制和管理漏洞，做到管好关键人、管到关键处、管住关键事、管在关键时。州纪委监委派驻州国资委纪检监察组组长通报了违反中央八项规定精神典型案例和全州国有企业违纪违法案件，为参会人员上了一堂警示教育课。</p>\n<p cms-style=\"font-L\">　　此外，州审计局主要负责同志通报了审计发现的风险点并提出工作建议，各州管企业作了发言。</p>\n<p cms-style=\"font-L align-right\">　　(黔西南州纪委监委)</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4236, NULL, '贵州精准监督筑牢粮食安全根基 环环相扣 改治发力', 0, 1, 24, '2025-08-11 08:31:11', '2025-08-11 07:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/109/w685h1024/20250811/e240-c7e9cb8148a60e4fe2016c9f02d21a30.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftc0652675.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　聚焦围绕“四新”主攻“四化”、贯彻落实中央八项规定精神等重点工作，省纪委监委以专项监督为抓手，推进政治监督具体化、精准化、常态化，以高质量监督护航中国式现代化贵州实践。</p>\n<p cms-style=\"font-L\">　　省纪委监委网站、微信公众号、客户端“清廉贵州”持续推出“专项监督护航贵州高质量发展”系列报道，交流展现全省纪检监察机关聚焦“国之大者”“省之大计”“民之大事”强化监督执纪的生动实践，敬请关注。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/109/w685h1024/20250811/e240-c7e9cb8148a60e4fe2016c9f02d21a30.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">贵州精准监督筑牢粮食安全根基</font></p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">环环相扣 改治发力</font></p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">——专项监督护航贵州高质量发展系列报道㉒</font></p>\n<p cms-style=\"font-L\">　　“针对巡察反馈的代储企业代储量不足问题，应采取切实措施保障代储企业库存足量的储备粮。”近日，贵州省六盘水市钟山区纪委监委联合区粮储公司到有关企业走访查看成品粮代储情况，对巡察整改提出明确要求。</p>\n<p cms-style=\"font-L\">　　今年以来，钟山区纪委监委联合区委涉粮问题巡察组开展联动监督，聚焦巡察“回头看”反馈的粮食购销领域腐败问题，督促相关单位限期抓好整改，推动保障粮食安全。</p>\n<p cms-style=\"font-L\">　　仓廪实，天下安。贵州省纪委监委把监督保障粮食安全作为政治监督的一项重要内容，聚焦粮食购销、物资储备、农资打假、农作物种植、涉粮补贴政策落实等方面，通过调研督导、统筹调度、实地走访等多种方式强化监督，切实保障粮食安全这一“国之大者”。</p>\n<p cms-style=\"font-L\">　　贵州省纪委监委驻省发展改革委纪检监察组聚焦粮食储备和购销领域监管体制机制改革、省级粮油仓储项目建设、储备粮油监管体系建设等重点工作，与省粮食和物资储备局密切沟通，听进展、提建议，持续压实粮食安全政治责任。围绕粮食收购、销售、存储等重点环节，采取“四不两直”方式深入贵阳市、安顺市、黔东南苗族侗族自治州等地开展调研式监督，以下看上深入剖析，督促省粮食和物资储备局指导各地抓好企业自查、市州检查、质量检验等环节工作。</p>\n<p cms-style=\"font-L\">　　安顺市纪委监委充分发挥派驻监督“探头”作用，督促市农业农村局加强统筹调度，细化任务清单，推动全市粮油生产任务有序推进，督促农业综合执法人员加大农资打假力度，严格品种管理和市场监管，全力净化农资市场。遵义市播州区纪委监委充分运用“室组地”监督力量，围绕粮食生产基础设施建设、农资储备、农作物种植、涉粮补贴政策落实、粮食收购等重点环节，通过走访农户、查看台账等方式，整治粮食生产过程中的不作为、慢作为、乱作为行为，以责任落实、政策落地情况倒查职能部门履职情况。</p>\n<p cms-style=\"font-L\">　　加强统筹协调，深化粮食购销领域腐败问题整治成果。贵州省纪委监委充分发挥牵头抓总作用，主动加强与省粮食行政主管部门协作，推动纪检监察机关监督责任与行业主管部门管理责任贯通协同、同向发力。统筹制发《关于开展粮食购销领域腐败问题专项整治“回头看”的通知》，聚焦粮食主管监管部门和国有粮食企业自查自纠、储备粮管理相关政策落实审计调查指出问题整改以及纪检监察机关监督检查发现问题整改、办结问题线索案件等情况，分自查梳理、集中抽查、督促整改3个阶段开展清底式“回头看”。</p>\n<p cms-style=\"font-L\">　　黔东南州纪委监委抓实抓细粮食购销领域腐败问题整改，有序推进线索、案件查办，建立健全规章制度，不断提升综合治理水平。针对案件查办过程中发现粮食储备部门暴露出的监管缺失、制度漏洞等问题，督促州、县两级粮食主管监管部门、国有粮食企业聚焦收购、储备、销售等方面出台完善规章制度、操作流程42项，推动形成靠制度管权、管粮、管人的长效机制。</p>\n<p cms-style=\"font-L\">　　此外，贵州省纪检监察机关持续督促行业部门整改整治，加强耕地保护，守牢粮食安全底线。</p>\n<p cms-style=\"font-L\">　　贵州省纪委监委聚焦日常监督发现的问题，督促指导省自然资源厅制定耕地保护和粮食安全突出问题整治实施方案，指导各级自然资源部门紧紧围绕乱占耕地建房、耕地流出图斑整治不到位、落实耕地保护责任失职渎职等5个方面突出问题深入排查、大力纠治，落实最严格的耕地保护制度。同时，推动相关部门制定耕地保护责任目标考核奖惩实施细则、关于高质量推进耕地保护提升耕地质量完善占补平衡的实施意见等，健全完善制度47项。</p>\n<p cms-style=\"font-L\">　　黔南布依族苗族自治州纪委监委通过监督检查、廉政约谈等方式，督促州农业农村局扎实推进高标准农田建设，重点查看项目选址、工程质量、资金拨付等情况，对耕地修复、灌排设施、田间道路等基础设施和质量进行全面“体检”，筑牢粮食安全根基。</p>\n<p cms-style=\"font-L\">　　赤水市纪委监委持续开展违法违规占用耕地监督，聚焦耕地保护、粮食生产、惠农政策落实等环节，强化监督检查，倒逼职能部门抓实抓细日常监管，以铁的纪律护航粮食安全。</p>\n<p cms-style=\"font-L\">　　榕江县车江坝区是该县重要的“米袋子”和“菜篮子”。近期洪水灾害造成车江坝区耕地灌溉沟渠被淤泥和杂物堵塞、部分农田水稻倒伏等问题。榕江县纪委监委立足职能职责，深入县农业农村、自然资源等职能部门开展监督，督促相关责任单位加快推进沟渠清理，组织农业技术人员到受灾一线指导，帮助受灾农户做好水稻病虫害防治、及时补种等工作，以最大力量减少农户损失。(作者：张娟娟)</p>', '[\"https://k.sinaimg.cn/n/spider20250811/109/w685h1024/20250811/e240-c7e9cb8148a60e4fe2016c9f02d21a30.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4237, NULL, '特朗普实在看不下去了', 0, 4, 207, '2025-08-11 09:30:14', '2025-08-11 08:19:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/400/w800h400/20250811/4459-5b9c5e1754756a9b9dca4794c1e7ef83.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqftc0659335.shtml', '牛弹琴', '<p>　　来源：牛弹琴</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/400/w800h400/20250811/4459-5b9c5e1754756a9b9dca4794c1e7ef83.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　特朗普实在看不下去了。</p> \n<p cms-style=\"font-L\">　　他生活的美国首都华盛顿，一是太脏，二是太乱，三实在是太差，玷污它作为美国首都的名声。</p> \n<p cms-style=\"font-L\">　　按照特朗普的说法，他要夺回美国人的首都，因为华盛顿已经成为“世界上最危险的城市之一”，现在充斥着“帐篷、肮脏、污秽和犯罪泛滥”。</p> \n<p cms-style=\"font-L\">　　美国首都很危险，这可不是我们说的。</p> \n<p cms-style=\"font-L\">　　这是美国总统说的。</p> \n<p cms-style=\"font-L\">　　怎么办？</p> \n<p cms-style=\"font-L\">　　在社交媒体上，特朗普披露了他拟议的一些做法：流浪汉必须立即搬走，“我们会给你们提供住处，但要远离首都”，罪犯们，你们不必搬走，“我们会把你们关进你们该去的地方”。</p> \n<p cms-style=\"font-L\">　　他并且威胁，他将终结美国首都的犯罪、谋杀和死亡，让城市变得更加美丽，在这方面，不会再有“好人”了，“我们要夺回我们的首都”！</p> \n<p cms-style=\"font-L\">　　特朗普说错了吗？</p> \n<p cms-style=\"font-L\">　　坦率地说，他还真没说错。</p> \n<p cms-style=\"font-L\">　　华盛顿是美国首都不假，华盛顿有些地方很漂亮也不假，但华盛顿一些地方很糟糕更不假。</p> \n<p cms-style=\"font-L\">　　即便是白宫外，也随处可见不少流浪汉；很多社区，坦率地说，当年我们也都是不敢去的。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/transform/98/w550h348/20250811/2339-0309cb7d119b22b18a3b9a4326ec9b9e.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　比脏乱差更可怕的，是治安。</p> \n<p cms-style=\"font-L\">　　美国首都的治安，实在不敢恭维。</p> \n<p cms-style=\"font-L\">　　最近一个事例，8月3日凌晨三点，在美国政府上班的科里斯汀，站在车外与友人交谈，遭到10名街头混混的围攻，他们要抢车。科里斯汀将朋友推入车内，自己却被当街痛殴，鲜血直流。</p> \n<p cms-style=\"font-L\">　　警察赶到现场时，肇事者已作鸟兽散。</p> \n<p cms-style=\"font-L\">　　科里斯汀年仅19岁，是一位编程高手，曾就职于马斯克的“政府效率部”，今年6月转到美国社保局工作。</p> \n<p cms-style=\"font-L\">　　事件发生后，马斯克震惊。</p> \n<p cms-style=\"font-L\">　　这可是美国首都啊，美国政府官员都被打了。</p> \n<p cms-style=\"font-L\">　　特朗普大发雷霆称：“华盛顿特区的犯罪活动已完全失控，当地这些青年帮派分子肆意伤害、劫掠无辜市民。他们对执法部门毫无畏惧，但很快他们就知道后果了！”</p> \n<p cms-style=\"font-L\">　　接着他话锋一转，称华盛顿如果不能改善治安，“我们只能让联邦政府接管这座城市”。</p> \n<p cms-style=\"font-L\">　　特朗普确实还想干一些事情的，华盛顿让他无法忍受，他要使出雷霆手段，将首都夺回来。</p> \n<p cms-style=\"font-L\">　　他能成功吗？</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/transform/100/w550h350/20250811/5eaf-e02d06314afbc10dffe395029345b8ed.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　很难！</p> \n<p cms-style=\"font-L\">　　很简单的一个问题，美国的流浪汉，为什么会这么多？你让他们到哪儿去？</p> \n<p cms-style=\"font-L\">　　今天，你可以将他们赶到其他地方，其他城市。其他城市的治安，怎么办？还有，再过几天，他们又回来了怎么办？</p> \n<p cms-style=\"font-L\">　　将他们投入监狱？</p> \n<p cms-style=\"font-L\">　　第一，美国监狱，已经很拥挤了，没有多余地方；</p> \n<p cms-style=\"font-L\">　　第二，他们很多都是土生土长美国人，没有国家可驱逐；</p> \n<p cms-style=\"font-L\">　　第三，他们虽然有碍观瞻，但流浪乞讨，好像也不犯法；</p> \n<p cms-style=\"font-L\">　　第四，如果真要关到监狱，冗长的法律程序，高昂的法律费用，最后不可持续。</p> \n<p cms-style=\"font-L\">　　更要看到，美国治安的恶化，一个重要原因，就是枪支的泛滥。</p> \n<p cms-style=\"font-L\">　　3亿美国人，3亿多条枪，每年打死3万多人。拜登当年就哀叹：<font cms-style=\"font-L strong-Bold\">枪支暴力在这个国家成了一种流行病，这让美国在国际上很难堪。</font></p> \n<p cms-style=\"font-L\">　　每一次惨烈枪击案后，都会是高涨的禁枪呼声；但每一次呼声，最终又都会被利益集团所击退。</p> \n<p cms-style=\"font-L\">　　为什么不禁枪？</p> \n<p cms-style=\"font-L\">　　因为触动利益。</p> \n<p cms-style=\"font-L\">　　触动利益比触及灵魂还难。而特朗普，美国人都知道，又是积极拥护持枪的总统。</p> \n<p cms-style=\"font-L\">　　所以，不排除“夺回首都”，如同特朗普不少政策一样，刚开始雷霆万钧，转眼就偃旗息鼓，最后不了了之。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/transform/182/w550h432/20250811/149f-0eecbd7821396f789d91f2dca48c321f.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　而且，这里面还不排除有政治的算计。</p> \n<p cms-style=\"font-L\">　　别忘了，作为首都的华盛顿特区，属于民主党的“深蓝票仓”，特朗普两次参选，在该市的得票率仅为4%和不到7%。</p> \n<p cms-style=\"font-L\">　　特朗普很生气，正好借治安问题，对华盛顿，对民主党下手。</p> \n<p cms-style=\"font-L\">　　但民主党又岂会善罢甘休？</p> \n<p cms-style=\"font-L\">　　别忘了，在美国全国，比华盛顿更脏乱差、治安更糟糕的城市，多得是。</p> \n<p cms-style=\"font-L\">　　看了一下，美国前10个最危险的城市，排名大致是：</p> \n<p cms-style=\"font-L\">　　1，孟菲斯；</p> \n<p cms-style=\"font-L\">　　2，圣路易斯；</p> \n<p cms-style=\"font-L\">　　3，小石城；</p> \n<p cms-style=\"font-L\">　　4，明尼阿波利斯；</p> \n<p cms-style=\"font-L\">　　5，底特律；</p> \n<p cms-style=\"font-L\">　　6，堪萨斯城；</p> \n<p cms-style=\"font-L\">　　7，新奥尔良；</p> \n<p cms-style=\"font-L\">　　8，克利夫兰；</p> \n<p cms-style=\"font-L\">　　9，伯明翰；</p> \n<p cms-style=\"font-L\">　　10，休斯敦。</p> \n<p cms-style=\"font-L\">　　每一个城市，都有太多的血泪。特朗普看不惯的美国首都，还根本排不上号。这些治安糟糕的城市，有些民主党掌权，有些是共和党执政。</p> \n<p cms-style=\"font-L\">　　所以，最根本的问题，不是如何治标，而是怎样治本。</p> \n<p cms-style=\"font-L\">　　但在当下的美国，治本，太难了。</p> \n<p cms-style=\"font-L\">　　就在去年年底，纽约发生了一件让人发指的事情：一位坐地铁的女士，突然衣服被人点燃，她被活活烧死在地铁里。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/transform/460/w509h751/20250811/7ec8-3471e8cd832af54a2721a47cae9d3402.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　让人难以相信。</p> \n<p cms-style=\"font-L\">　　想象一下，这可是纽约，在纽约的地铁，如果我们的北京、上海、广州，不管哪一个城市的地铁，也发生这样的事情，那会怎样让全国震惊，你可以想见外国媒体各种报道。</p> \n<p cms-style=\"font-L\">　　就在这位女士烧死的同一天，纽约另一条线路的地铁上，还发生了一起刺杀案，一人被刺身亡，另一人受伤。</p> \n<p cms-style=\"font-L\">　　2025年第一天，纽约还发生了一起严重的枪击案，至少11人受伤。当然，那天美国最严重的暴力事件，发生在新奥尔良，至少15人被车撞死，30多人受伤。</p> \n<p cms-style=\"font-L\">　　哦，记得有一年，就在纽约时代广场，好像是摩托车声或什么剧烈响声，周边人误听成了枪击声，于是，几个街区的人们，都拼了老命四处逃窜，最后，大街上，到处是丢掉的鞋子……</p> \n<p cms-style=\"font-L\">　　看看图片和视频，你可想而知当时美国人的恐惧和绝望。</p> \n<p cms-style=\"font-L\">　　触目惊心一幕幕，背后就是一个国家一个城市治理的问题。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/transform/43/w550h293/20250811/f363-3413c0e2867fb283bd3f736421bcbef7.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">中国有句古话这样说：</font><font cms-style=\"font-L strong-Bold\">国之将兴，必有祯祥，国之将亡，必有妖孽。</font>这话未必都对。美国肯定有我们值得学习的很多地方，但现在的美国，也有太多太多必须吸取的教训。</p> \n<p cms-style=\"font-L\">　　唉，<font cms-style=\"font-L strong-Bold\">一个国家强大崛起之时，往往各方面生机勃勃，政策自信开明，纠错能力也强；但当一个国家越来越不自信，问题无力解决，各种甩锅抹黑，感觉是眼睁睁地看着更大的危机发生。</font></p> \n<p cms-style=\"font-L\">　　特朗普要大干一场，里面夹杂着政治的算计，华盛顿成为了矛头，但禁枪却是万万不可能的。</p> \n<p cms-style=\"font-L\">　　华盛顿真会好起来吗？</p> \n<p cms-style=\"font-L\">　　很难，即便华盛顿短时间略有所好转，还有更糟糕的孟菲斯、圣路易斯、小石城、底特律，等等，他们的明天会怎样？</p> \n<p cms-style=\"font-L\">　　在美国，很多城市，治安是个老大难问题，几乎无解。</p> \n<p cms-style=\"font-L\">　　还是那句话，我们所习以为常的普通日子，却是很多国家老百姓最期待的。</p> \n<p cms-style=\"font-L\">　　但中国，千万千万不能骄傲，更要看到不足，更需要不断改进。</p> \n<p cms-style=\"font-L\">　　当然，也可以预料，即便华盛顿最后仍旧是老样子，甚至治安更糟糕，也不妨碍特朗普宣布：美国首都已经夺回，他又赢了……</p> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/400/w800h400/20250811/4459-5b9c5e1754756a9b9dca4794c1e7ef83.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/transform/98/w550h348/20250811/2339-0309cb7d119b22b18a3b9a4326ec9b9e.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/transform/100/w550h350/20250811/5eaf-e02d06314afbc10dffe395029345b8ed.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/transform/182/w550h432/20250811/149f-0eecbd7821396f789d91f2dca48c321f.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/transform/460/w509h751/20250811/7ec8-3471e8cd832af54a2721a47cae9d3402.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/transform/43/w550h293/20250811/f363-3413c0e2867fb283bd3f736421bcbef7.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4238, NULL, '美国密歇根州州长：关税正在伤害美汽车产业', 0, 4, 207, '2025-08-11 09:30:22', '2025-08-11 07:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/0077-8ed6f139444ead5d0de0c5b01007a22f.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqfti6103644.shtml', '央视', '<!--article_adlist[<p cms-style=\"font-L subpect-abstract\"></p>]article_adlist--> \n<p cms-style=\"font-L\">　　据美国哥伦比亚广播公司9日报道，美国密歇根州州长惠特默日前在一次私下会晤时对美国总统特朗普表示，特朗普政府当前的关税政策正在伤害美国汽车产业。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/0077-8ed6f139444ead5d0de0c5b01007a22f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　报道称，惠特默在会晤中强调，特朗普曾宣称他想拯救美国汽车产业，但美国政府的关税政策却正在伤害美国汽车产业，这可能给密歇根州带来严重的经济损失。而特朗普在会晤中并未对惠特默做出任何具体承诺。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/9ead-bea4a6ffa49d78e12d6fbc9df0ee4393.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　报道指出，汽车产业是密歇根州的支柱产业，美国三大汽车制造商通用、福特与斯特兰蒂斯汽车公司在密歇根州拥有约50家工厂，汽车产业为该州创造了近60万个工作岗位。然而美国劳工统计局数据显示，特朗普政府上台以来，密歇根州已经有7500个工作岗位消失，当地汽车产业遭到关税政策的沉重打击。专家指出，如果这一情况持续下去，密歇根州作为重要摇摆州之一，其民意将出现逆转，特朗普政府将受其关税政策的反噬。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/2c1e-71d466146cceee109c1a594e52dc69cd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据美国汽车研究中心数据，美国关税政策导致所有美国汽车制造商的成本激增。此前，美国三大汽车制造商通用、福特与斯特兰蒂斯汽车公司都发出警告称，关税政策将削弱美国汽车制造商。最新数据显示，美国关税政策导致今年二季度通用盈利减少11亿美元，福特盈利减少8亿美元，斯特兰蒂斯汽车公司上半年亏损23亿欧元。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/0077-8ed6f139444ead5d0de0c5b01007a22f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/9ead-bea4a6ffa49d78e12d6fbc9df0ee4393.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/2c1e-71d466146cceee109c1a594e52dc69cd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4239, NULL, '新乡胖东来千人招聘细节曝光：分批次网报，系统初筛，满3000人截止', 0, 2, 154, '2025-08-11 09:30:32', '2025-08-11 09:21:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/712/w550h962/20250811/e2e1-132a087ef8c9e11ee9935216dcb79177.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmyz0557535.shtml', '大河报', '<p style=\"text-align: left;\">　　8月10日，胖东来创始人于东来对外公布了新乡胖东来三胖招工的最新细节。</p> \n<p style=\"text-align: left;\">　　此前，于东来已宣布，该项目计划招聘约1000人。其中，200个岗位面向在新疆、西藏高原艰苦地区服役的退伍边防军人，20个岗位面向有犯罪前科人员。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/712/w550h962/20250811/e2e1-132a087ef8c9e11ee9935216dcb79177.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　据于东来介绍，此次招工方案正在制定标准，将分批次推进，不采取一次性招满的方式。</p> \n<p style=\"text-align: left;\">　　报名渠道确定为线上，同时设置系统初审环节，不符合标准的报名信息无法进入后续流程。</p> \n<p style=\"text-align: left;\">　　此次招工还特别设置了报名截止机制：总招聘名额约1000个，但当报名人数达到3000人时，将自动停止接收报名。</p> \n<p style=\"text-align: left;\">　　于东来解释，这样做是为了避免因报名人数过多、远超岗位数量，导致大量人员落空，减少不必要的失落感。</p> \n<p style=\"text-align: left;\">　　此前，大河报曾率先报道了该招聘事宜。报道详细披露了于东来对特殊岗位设置的背景及考量：胖东来将20%名额定向招募高原退伍边防军人，旨在“让为国家奉献的军人得到尊重”；2%岗位留给刑释人员，则是为“让走过弯路的群体重获尊严”。</p> \n<p style=\"text-align: left;\">　　这一举措很快引发社会广泛关注，不少网友涌入于东来社交账号评论区求职，形成“大型线上求职现场”。</p> \n<p style=\"text-align: left;\">　　作为胖东来在新乡的已有商业项目，大胖、二胖凭借优质服务积累了较高市场认可度。</p> \n<p style=\"text-align: left;\">　　目前，招工具体标准及后续进展仍待进一步公布。</p> \n<p style=\"text-align: left;\">　　来源：大河报</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/news/crawl/712/w550h962/20250811/e2e1-132a087ef8c9e11ee9935216dcb79177.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4240, NULL, '威海碳纤维产业链跻身国家集群，67家企业覆盖海陆空天', 0, 2, 140, '2025-08-11 09:30:38', '2025-08-11 09:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmzf5986862.shtml', '山东省政府网站', '来源：山东省政府网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　8月6日，市政府新闻办举行“产业链上的山东好品牌”威海主题系列新闻发布会第二场，主题是威海市碳纤维及复合材料产业链。市工业和信息化局党组成员、副局长刘海燕，威海光威复合材料股份有限公司副总经理王壮志，山东浩然特塑股份有限公司董事长徐铭，威海宝威新材料科技有限公司总工程师毕见强，介绍威海碳纤维及复合材料产业链发展举措有关情况，围绕产业链创新发展和品牌打造等主题分享交流。</p>\n<p cms-style=\"font-L\">　　碳纤维及复合材料产业链是我市重点培育的十大产业链之一，近年来威海市立足产业的既有优势，聚力打造优质产业生态、深化创新驱动，全力培育高质量发展的新动能，持续提升产业核心竞争力。目前，集群内共有碳纤维及复合材料规上企业67家，成功跻身国家中小企业特色产业集群、山东省先进制造业集群、山东省“十强”产业“雁阵形”集群之列，彰显了强劲的发展势头。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">以链群协同助推产业厚积成势</font></p>\n<p cms-style=\"font-L\">　　强抓企业筑根基。实施优质企业梯度培育工程，坚持梯度培育、分类施策，构建企业成长金字塔格局，努力打造龙头企业为引领，专精特新企业为中坚，创新型企业为基础的强企方阵。支持“链主”企业光威复材巩固行业领先地位，引导浩然特塑、宝威新材料等骨干企业深耕专业领域、做大规模体量，培育光轩新材料等新兴企业加速成长，累计培育省级制造业单项冠军企业4家、省级以上专精特新企业21家，碳纤维及复合材料产品实现“海陆空天”军民两用领域的全覆盖。光威复材是目前国内碳纤维行业生产品种最全、生产技术最先进、产业链最完整的龙头企业之一，是国产大飞机C919的碳纤维材料供应商；宝威新材料抢占低空经济发展机遇，成为全球最大的货运无人机白鲸航线W5000研发生产机翼壁板的供应商；碳纤维钓具本地配套率超80%，全球市场份额占比达60%以上。</p>\n<p cms-style=\"font-L\">　　强抓载体搭平台。整合各类优势资源，建成国内第一家政府性投资的碳纤维专业园区，配套研究院、产业化车间、专家公寓等基础设施30万平方米，打造集科研、孵化、产业化于一体的全产业链综合园区。引进国家碳纤维产业计量测试中心等22家高端科研平台，吸聚拓展纤维等48家产业链上下游企业，碳纤维产业园入选工信部2024年产业园区推进新型工业化典型案例，获评山东省数字经济园区。</p>\n<p cms-style=\"font-L\">　　强抓链条塑优势。将碳纤维及复合材料产业链纳入全市10条标志性产业链培育体系，由市领导担任产业链“链长”，出台支持碳纤维及复合材料产业链发展政策措施，精准绘制产业链生态图谱，为配套协作、项目招商等提供信息支撑。目前，全市已形成了从原丝到碳纤维、预浸料、树脂材料、复材制品和终端产品的全产业链生产制造体系，具备从研发创新到装备制造和分析检测的全产业链保障支撑能力。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">以科技创新赋能产业蝶变升级</font></p>\n<p cms-style=\"font-L\">　　聚焦创新驱动，提升产业核心竞争力。围绕产业链部署创新链，构建“平台赋能+企业主体”一体贯通的协同创新体系，建成碳纤维制备及工程化国家工程实验室等国家级创新平台3个，山东省碳纤维及复合材料制造业创新中心等省级创新平台15个，碳纤维及复合材料中试平台入选首批山东省制造业中试平台。强化企业创新主体地位，业内龙头骨干企业先后承担重大新材料专项等国家级重点攻关项目30余项，成功突破M65J级高强高模碳纤维制备关键技术，500米/分干喷湿纺高强度碳纤维高效制备技术国内领先，实现T1100级碳纤维产业化生产，高强高模碳纤维入选2024年山东省十大科技创新成果。</p>\n<p cms-style=\"font-L\">　　聚焦数智赋能，释放产业发展新活力。深入推进“智改数转”行动，聚焦企业改造难点痛点，系统开展“培训赋智、诊断赋能、标杆引路”活动，培育市级以上智能化项目11个，宝威新材料5G智能工厂入选全国名录。加快推进工业互联网示范应用，深度释放数据资源价值，建设碳纤维省级“产业大脑”，汇集利用生产监测、仓储物流、创投融资等数据1.4万条，培育省级工业互联网平台3个、数据驱动型“晨星工厂”8家。</p>\n<p cms-style=\"font-L\">　　聚焦品牌建设，提升产业区域影响力。实施质量品牌提升工程，推进“增品种、提品质、创品牌”三品行动。引导企业主持制定《聚丙烯腈基碳纤维》《碳纤维预浸料》国家标准，临港区碳纤维基地获评国家级“千企百城”商标品牌指导站，推进国内钓具行业首个区域品牌“威海钓具”集体商标成功注册，获评首批中国消费名品区域品牌，5家企业获评省级以上质量标杆、山东制造·齐鲁精品。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">以优质生态做强产业发展磁场</font></p>\n<p cms-style=\"font-L\">　　强化育才聚智，创新支撑成效显著。依托各级人才工程，靶向引进培育专业人才，积极营造“近悦远来”人才引育生态，吸引人才资源向威海集聚。建立杜善义、俞建勇等4名院士领衔的顶尖智库，累计引进省级以上人才12人，其中国家级人才2人。深化产才融合新模式，联合职业学院实施“订单式”技术人才培养，设立北京化工大学“研究生实践基地”，为企业累计输送各类专业人才300余人。推动全省唯一的碳纤维复合材料工程职称评审试点落地，拓宽技术人才职业发展通道。</p>\n<p cms-style=\"font-L\">　　强化平台聚能，科技成果加速转化。牵头成立胶东经济圈碳纤维及复合材料产业链联盟、威海市碳纤维产业链联盟，举办中国威海·国际英才创新创业大会、国际高性能纤维及复合材料科技会议、土木工程纤维增强复合材料发展大会等常态化品牌化的高能级对接活动，实现资源共享、优势互补，进一步提升产业链供应链的稳定性与竞争力。</p>\n<p cms-style=\"font-L\">　　强化要素保障，营商环境向优而进。完善服务机制，常态化开展企业大走访活动，创新推出“惠企政策集成卡”，发放“企业家专享卡”，精准服务企业。整合电源、电网、负荷、储能四大核心要素，建设全省首个碳纤维产业源网荷储试点项目，减轻企业用能成本。创新产业链金融辅导模式，设立威海港发股权投资基金等产业基金，搭建省级“金融管家”试点平台，引入中国建设银行、中国银行、恒丰银行等15家金融机构，以专业化金融护航企业发展。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4241, NULL, '江西7人乘船在水库钓鱼，船只翻沉后3人不幸溺亡，家属：哥哥救堂弟双双遇难', 0, 1, 14, '2025-08-11 09:30:43', '2025-08-11 08:59:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/654/w550h904/20250811/f5f9-6824eacc5bf5250a9997944a20642cf6.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmze8895808.shtml', '极目新闻', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　极目新闻记者 郭奕</p> \n<p>　　8月7日，江西抚州金溪县的郑先生发视频反映，6日下午1时30分左右，其哥哥等7人在当地坪上水库乘船钓鱼时船只翻沉，包含其哥哥在内共3人不幸遇难。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/654/w550h904/20250811/f5f9-6824eacc5bf5250a9997944a20642cf6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"坪山水库（视频截图）\">\n <span class=\"img_descr\">坪山水库（视频截图）</span>\n</div> \n<p>　　10日上午，郑先生告诉极目新闻记者，他33岁的亲哥哥和22岁左右的堂弟都在这次事故中遇难了，还有一名遇难者小伟（化名）今年29岁，也是他们镇上的。</p> \n<p>　　据郑先生回忆，6日下午，他的哥哥、堂弟等6人受坪上水库承包者邓先生邀请，前往水库钓鱼。当天下午5时许，他就收到哥哥朋友的语音，告知“你哥走了”。“我当时根本不信，因为我哥水性非常好，还是他教会我游泳的。”郑先生说，当时他在外地，得知此事后立即打车赶回老家。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/477/w550h727/20250811/d2e5-3e0a03036dbf07f95e3f2af6dfa28ba5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"事发船只\">\n <span class=\"img_descr\">事发船只</span>\n</div> \n<p>　　后来，郑先生听邓先生描述了事发的经过：当时6名钓友都坐在船头，因为船头坐着更舒服，只有老板邓先生坐在船尾操控船只。行驶约10至20米后，船头突然开始进水，邓先生随即呼喊大家跳船逃生，船不到15秒便沉了。船上7人都未穿救生衣，郑先生的哥哥本来会游泳，但他去救堂弟时两人一同溺亡。邓先生尝试营救离自己最近的小伟，但对方体重近180斤，他未能营救成功，随后自己上岸。除郑先生的哥哥、堂弟和小伟外，其他4人均得以逃生。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/225/w550h475/20250811/eb45-fb2fe4b03399dd948a3b4ff96558c9c1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"遇难者家属郑先生7日在事发地拍摄的游泳圈\">\n <span class=\"img_descr\">遇难者家属郑先生7日在事发地拍摄的游泳圈</span>\n</div> \n<p>　　10日，当地应急管理局工作人员告诉极目新闻记者，坪上水库6日确有3人因船翻沉溺亡，他们当天有人赶到现场参与救援。当地相关部门工作人员回应极目新闻记者称，此事正在处理中。</p> \n<p>　　公开资料显示，坪上水库位于江西抚州金溪县合市镇，于1963年建成。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/news/crawl/654/w550h904/20250811/f5f9-6824eacc5bf5250a9997944a20642cf6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/477/w550h727/20250811/d2e5-3e0a03036dbf07f95e3f2af6dfa28ba5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/225/w550h475/20250811/eb45-fb2fe4b03399dd948a3b4ff96558c9c1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4242, NULL, '南京地铁5号线全线贯通运营', 0, 2, 71, '2025-08-11 09:30:58', '2025-08-11 08:54:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/651/w1351h900/20250811/aa8b-53c0e4c3a4760367fe7b1bc4f2583eb6.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftm9978856.shtml', '国资委网站', '<p cms-style=\"font-L\">　　8月6日6时，随着列车开出始发站，中国中铁参建的南京地铁5号线北段正式开通运营，标志着5号线实现全线贯通运营。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/651/w1351h900/20250811/aa8b-53c0e4c3a4760367fe7b1bc4f2583eb6.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　南京地铁5号线起于吉印大道站，终至方家营站，是南北向贯穿主城的骨干线，线路全长37.4公里，全部为地下线，共设地下车站30座，其中有8座车站与既有线路换乘。中国中铁多家单位参与南京地铁5号线北段部分线路轨道、消防站、车站设备安装与装修工程。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/759/w1348h1011/20250811/2978-2bd8768a3c89029f005227a5f7a26089.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　地铁5号线作为南京市连接东南至西北方向的重要城区干线，途经夫子庙、南京博物院等重要旅游景点。线路开通运营将有效缓解秦淮区交通压力，极大地改善市民以及旅客的出行条件，进一步优化和完善南京的城市交通结构。</p>\n<p cms-style=\"font-L align-right\">　　【责任编辑：韩梦圆】</p>', '[\"https://k.sinaimg.cn/n/spider20250811/651/w1351h900/20250811/aa8b-53c0e4c3a4760367fe7b1bc4f2583eb6.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/759/w1348h1011/20250811/2978-2bd8768a3c89029f005227a5f7a26089.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4243, NULL, '重庆、湖南等地需警惕强降雨致灾 江南、华南高温耐力十足', 0, 1, 18, '2025-08-11 09:31:40', '2025-08-11 08:25:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/250/w600h450/20250811/8b6e-31206b839ee2e086032891e8a47575af.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqfth9014384.shtml', '央视', '<p cms-style=\"font-L\">　　今天（8月11日），四川盆地至江汉、江淮一带仍有强降雨，明天降雨将逐渐缩减，四川、重庆、湖北、湖南等地需持续警惕次生灾害。在主雨带南侧的江南、华南等地，本周依然高温天气频繁。未来随着副热带高压北抬，13日起北方闷热天气也会增多，黄淮、华北等地不少地方或热如“蒸桑拿”。</p> \n<ul cms-style=\"ul\"> \n <li cms-style=\"li\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">四川盆地至江淮一带仍有强降雨 华北东北部分地区需警惕雷暴大风</font></font></li> \n</ul> \n<p cms-style=\"font-L\">　　昨天，强降雨主要出现在长江沿线。监测显示，四川盆地东部和南部、陕西南部、湖北西部和南部、湖南北部、苏皖中部和云南东南部、海南中部等地部分地区出现暴雨或大暴雨。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">今天，主雨带仍将维持在四川盆地</font><font cms-style=\"font-L strong-Bold\">至</font><font cms-style=\"font-L strong-Bold\">江汉、江淮一带</font>，部分地区雨势猛烈，明天上述地区强降雨区域会有所南压，范围也会减小。随着高空槽东移，<font cms-style=\"font-L strong-Bold\">今明两天华北北部、东北地区也将出现降雨，且伴有雷暴大风等强对流天气</font>。</p> \n<p cms-style=\"font-L\">　　中央气象台预计，今天，苏皖中部、湖北东部和南部、湖南西北部、四川东部和南部、重庆、贵州中西部和东北部、云南北部以及内蒙古中东部等地部分地区有大到暴雨，其中，江苏中部、湖北西南部、湖南西北部、重庆中东部、贵州东北部等地部分地区有大暴雨，<font cms-style=\"font-L strong-Bold\">湖南西北部、重庆东南部等地局地特大暴雨</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/250/w600h450/20250811/8b6e-31206b839ee2e086032891e8a47575af.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　明天，内蒙古东南部、东北地区西部、华北中北部、江淮东部、江汉大部、江南北部、重庆、贵州、云南中北部、西藏东南部等地部分地区有中到大雨，其中，<font cms-style=\"font-L strong-Bold\">湖北西南部、湖南西北部、贵州东北部和中部、西藏东南部等地部分地区有暴雨或大暴雨</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/250/w600h450/20250811/820d-f5b306d9283418f201316300cd9a4d45.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　气象部门提醒，这次过程强降雨区域重叠度较高、短时雨强大、局地累计雨量大，其中<font cms-style=\"font-L strong-Bold\">四川、重庆、湖北、湖南等地部分地区需持续警惕地质灾害、山洪、中小河流洪水、城乡积涝等次生灾害</font>。</p> \n<ul cms-style=\"ul\"> \n <li cms-style=\"li\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">江南华南多地高温耐力十足 13日起北方闷热天气逐渐增多</font></font></li> \n</ul> \n<p cms-style=\"font-L\">　　在降雨和冷空气的共同影响下，今明两天，长江沿线高温天气将明显缩减，强降雨集中区的部分地区最高气温还可能下降至30℃以下，合肥、武汉等城市最高气温都将维持在25至29℃左右，体感凉快不少。</p> \n<p cms-style=\"font-L\">　　不过，本周南方大部地区高温依然耐力十足。南昌、杭州高温日数可达6至7天，加上湿度较大，闷热感持续，公众需做好防暑措施，尽量减少在高温时段进行户外活动，谨防中暑。</p> \n<p cms-style=\"font-L\">　　预计13日，副热带高压将加强北抬，湿热空气会再次向北输送，虽然北方高温天气不多，但黄淮、华北等地不少地方体感温度接近高温，将体验闷热的桑拿天。</p> \n<p cms-style=\"font-L\">　　（来源：中国天气网）</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/250/w600h450/20250811/8b6e-31206b839ee2e086032891e8a47575af.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/250/w600h450/20250811/820d-f5b306d9283418f201316300cd9a4d45.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4244, NULL, '“杨柳”最强可达台风级 将于13日白天在台湾东部沿海登陆', 0, 1, 34, '2025-08-11 09:31:45', '2025-08-11 07:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/311/w600h511/20250811/5918-8c0936a261d449c7f9e505cdfa12f897.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqftc0665990.shtml', '央视', '<p cms-style=\"font-L\">　　据中央气象台消息，今年第11号台风“杨柳”（强热带风暴级）的中心今天（8月11日）早晨5点钟位于台湾花莲市东偏南方向大约1340公里的西北太平洋洋面上，就是北纬21.2度、东经134.3度，中心附近最大风力11级（30米/秒），中心最低气压980百帕，七级风圈半径为160~220公里，十级风圈半径为50~80公里。</p> \n<p cms-style=\"font-L\">　　预计，“杨柳”将以每小时25~30公里的速度向偏西方向移动，强度先略有加强，最强可达台风级（33米/秒，12级），然后逐渐减弱，并向台湾以东洋面靠近，将于13日白天在台湾东部沿海登陆（强热带风暴级，25~30米/秒，10~11级），穿过台湾岛进入台湾海峡，强度进一步减弱，13日夜间至14日早晨登陆福建东部沿海（热带低压或热带风暴级，15~20米/秒，7~8级），之后逐渐减弱消散。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/311/w600h511/20250811/5918-8c0936a261d449c7f9e505cdfa12f897.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"（来源：中国天气网）\">\n <span class=\"img_descr\">（来源：中国天气网）</span>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/311/w600h511/20250811/5918-8c0936a261d449c7f9e505cdfa12f897.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4245, NULL, '战火中破碎的足球梦 “巴勒斯坦贝利”苏莱曼遭以军袭击身亡', 0, 4, 151, '2025-08-11 10:30:16', '2025-08-11 09:31:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/1f3d-b86072c7d49d047c718944e573f2823a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqmzi9878723.shtml', '央视', '<!--article_adlist[<p cms-style=\"font-L subpect-abstract\"></p>]article_adlist--> \n<p cms-style=\"font-L\">　　在本轮巴以冲突中，大量巴勒斯坦平民在以军袭击中遇难。不久前，被球迷誉为“巴勒斯坦的球王贝利”、曾随巴勒斯坦国家足球队征战世界赛场的<font cms-style=\"font-L strong-Bold\">苏莱曼·奥贝德</font>，<font cms-style=\"font-L strong-Bold\">在为家人领取援助物资时遭遇以军袭击死亡</font>，这一消息令他的家人和巴勒斯坦球迷伤心不已。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/1f3d-b86072c7d49d047c718944e573f2823a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">苏莱曼的妻子 杜阿：</font>他是我的一切，是我的一切。这件衣服上还有苏莱曼的气息，是逝去的亲人的气息，为了孩子寻找食物而死的英雄的气息。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/cdff-ed14cacd4ef82fc59ad8d5751a393cff.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　今年41岁的苏莱曼·奥贝德曾代表巴勒斯坦征战国际足球赛场，他在职业生涯中共有超100个进球。即使是在巴以冲突的炮火中，他仍然没有放弃足球运动。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/beb8-f5fe1cebb19ae57bbb2fc8d428b73e49.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">苏莱曼的女儿 伊娜斯：</font>他爱足球，你知道这意味着什么吗，他爱足球。如果有人说“咱们去踢球吧”，他会立即跳起来跟我们说“我去踢球了”。他会在一天结束时高高兴兴地回家，我们会问“今天进球了吗”。爸爸会告诉我们“我进球了”，他进了好几个球。他令我们开心，令我们为他骄傲。</p> \n<p cms-style=\"font-L\">　　然而足球带来的快乐也无法在炮火中幸存。今年早些时候，苏莱曼的家被以军摧毁，在一段当时的视频中，他在废墟中行走，试图寻找残存的职业生涯记忆。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">苏莱曼·奥贝德：</font>虽然都被炸烂了，但这些都是我的运动生涯，还有记忆中留下的东西。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">苏莱曼的妻子 杜阿：</font>整栋房子都没了，什么都没剩下，连他的一件衣服都没剩下，他去沙滩穿的衣服也没了。什么都没了，他的奖杯都找不到了，都找不到了。那天他很失落，真的很失落。他说 “就这样吧”“房子没了，没什么值得伤心了”。</p> \n<p cms-style=\"font-L\">　　随着以军加强对加沙地带的封锁，当地的人道危机愈发严峻，苏莱曼为了一家人的生存，被迫外出寻找援助物资。8月6日，在美以支持的所谓“加沙人道主义基金会”的一处物资分发点，以军的袭击让他的生命永远定格在41岁。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">苏莱曼的妻子 杜阿：</font>加沙的体育曾经是美好的。但是战争爆发后，体育就变成了悲剧。我们一开始是听到苏莱曼的体育界朋友，听到足球教练和球员遇害的消息，现在他们（以军）又杀害了苏莱曼。</p> \n<p cms-style=\"font-L\">　　巴勒斯坦足协称，苏莱曼在以军袭击中死亡是对巴勒斯坦体育界，尤其是足球界的巨大打击。本轮巴以冲突中，加沙地带已有数百名运动员死亡。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">巴勒斯坦足协官员 穆斯塔法·赛亚姆：</font>以军袭击造成了665名运动员死亡，其中有323名足球运动员。这些庞大的数字反映了以色列对巴勒斯坦体育运动和巴勒斯坦运动员造成了怎样的伤害。我们还要说说体育设施，超过80%的体育设施被以军完全摧毁。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/1f3d-b86072c7d49d047c718944e573f2823a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/cdff-ed14cacd4ef82fc59ad8d5751a393cff.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/600/w1920h1080/20250811/beb8-f5fe1cebb19ae57bbb2fc8d428b73e49.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4246, NULL, '以军空袭炸死5名记者 半岛电视台记者遗言曝光：他们让我噤声', 0, 4, 95, '2025-08-11 10:30:23', '2025-08-11 09:24:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/597/w1798h1199/20250811/c5cd-d166c1b2dcdb56e261732287944229d2.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqmyz0563313.shtml', '央视', '<p cms-style=\"font-L\">　　在10日晚的空袭中，以军击中加沙城希法医院附近的一个帐篷，导致半岛电视台5名记者身亡。</p> \n<p cms-style=\"font-L\">　　以军随后承认打死一名半岛电视台记者，指称他与巴勒斯坦伊斯兰抵抗运动（哈马斯）有关联。</p> \n<p cms-style=\"font-L strong-Bold\">　　以军瞄准记者帐篷 有人“被炸成碎片”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/597/w1798h1199/20250811/c5cd-d166c1b2dcdb56e261732287944229d2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△半岛电视台记者阿纳斯·谢里夫\">\n <span class=\"img_descr\">△半岛电视台记者阿纳斯·谢里夫</span>\n</div> \n<p cms-style=\"font-L\">　　据半岛电视台报道，该台记者阿纳斯·谢里夫和其4名同事在以色列对加沙的袭击中遇难。</p> \n<p cms-style=\"font-L\">　　希法医院负责人穆罕默德·阿布·萨尔米亚说，5名巴勒斯坦人在以军的袭击中丧生，包括半岛电视台记者和摄影师。巴勒斯坦民防部门消息人士称，<font cms-style=\"font-L strong-Bold\">以军袭击时直接瞄准记者在希法医院前搭设的帐篷，有人“被炸成碎片”。</font></p> \n<p cms-style=\"font-L strong-Bold\">　　以称谢里夫与哈马斯有关联</p> \n<p cms-style=\"font-L\">　　以色列国防军随后发表声明，承认他们在对加沙城发动的一次袭击中打死阿纳斯·谢里夫，<font cms-style=\"font-L strong-Bold\">并称他与哈马斯有关联，“伪装成半岛电视台记者”。</font></p> \n<p cms-style=\"font-L\">　　声明称，阿纳斯·谢里夫是哈马斯“一个行动小组头目”，并参与向以色列士兵和公民发射火箭弹。</p> \n<p cms-style=\"font-L\">　　声明还称，发现的一些文件显示，阿纳斯·谢里夫与哈马斯有联系。这些文件包括“人员名册、恐怖分子培训课程清单、电话簿和工资文件”。</p> \n<p cms-style=\"font-L\">　　但半岛电视台援引加沙地带作家兼分析师穆罕默德·谢哈达的话报道，<font cms-style=\"font-L strong-Bold\">“没有证据表明谢里夫参与了任何敌对行动”</font>。</p> \n<p cms-style=\"font-L strong-Bold\">　　遇难记者曾留遗言：他们让我噤声</p> \n<p cms-style=\"font-L\">　　身亡前不久，谢里夫在社交媒体上发布了一段视频，显示加沙的夜空被轰炸照亮，爆炸声不绝于耳。“无情的轰炸。”他写道，<font cms-style=\"font-L strong-Bold\">“两个小时以来，以色列对加沙城的侵略愈演愈烈。”</font></p> \n<p cms-style=\"font-L\">　　谢里夫家属在谢里夫社交媒体账号上发布其遗言说：“这是我的遗嘱，也是我最后的留言。如果这些话传到你耳中，那就说明以色列已经成功杀了我，并让我噤声。”</p> \n<p cms-style=\"font-L strong-Bold\">　　本轮巴以冲突已致加沙地带237名记者死亡</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/220/w2048h1372/20250811/5eba-eb19c3082cf4f5fdfe198e46250e1ca5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△加沙地带（资料图）\">\n <span class=\"img_descr\">△加沙地带（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　自2023年10月7日新一轮巴以冲突爆发以来，半岛电视台持续抨击以军行动。以政府指责半岛电视台偏袒哈马斯并煽动针对以色列的行动，于2024年5月关停卡塔尔半岛电视台在以色列的分支机构，并禁止其频道在以播放。</p> \n<p cms-style=\"font-L\">　　加沙地带媒体办公室11日凌晨发表声明，强烈谴责以军的空袭行为。声明表示，截至目前，<font cms-style=\"font-L strong-Bold\">加沙地带</font><font cms-style=\"font-L strong-Bold\">因</font><font cms-style=\"font-L strong-Bold\">以军军事行动死亡的记者数量已达237人</font>，呼吁相关国际组织对该行为予以谴责，采取措施确保巴勒斯坦记者和媒体机构得到充分保护，并追求以方相关人员责任。</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color240\"><font cms-style=\"font-L strong-Bold color240\">以军袭击加沙致5名记者身亡 本轮巴以冲突已致237名记者遇难&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/597/w1798h1199/20250811/c5cd-d166c1b2dcdb56e261732287944229d2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/220/w2048h1372/20250811/5eba-eb19c3082cf4f5fdfe198e46250e1ca5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4247, NULL, '7月份北京市居民消费价格环比由降转升', 0, 1, 1, '2025-08-11 10:30:33', '2025-08-11 10:22:00', NULL, NULL, NULL, 'https://news.sina.com.cn/o/2025-08-11/doc-infkqmzi9903724.shtml', '新京报', '<p cms-style=\"font-L\">　　新京报讯 据北京市统计局消息，7月份，北京市居民消费价格环比由降转升，同比降幅较上月小幅扩大。</p> \n<p cms-style=\"font-L\">　　从环比看，CPI环比由上月下降0.4%转为上涨0.7%。其中，食品价格下降0.9%，降幅比上月收窄0.5个百分点。食品中，大桃、油桃、巨峰葡萄等应季水果大量上市，鲜果价格下降7.4%，降幅比上月扩大0.8个百分点；市场供应充足，鸡蛋和水产品价格分别下降0.6%和0.3%；本月高温、雨水天气偏多，鲜菜价格上涨4.2%，涨幅比上月扩大4.1个百分点；猪肉价格由上月下降1.1%转为上涨0.6%。非食品价格由上月下降0.3%转为上涨0.9%。非食品中，服务价格由上月下降0.3%转为上涨1.1%，其中，暑期进出京旅游人数增多，飞机票、在外住宿和旅行社收费价格均由降转升，分别上涨37.8%、11.8%和6.1%；工业消费品价格由上月下降0.2%转为上涨0.9%，其中，汽、柴油价格分别上涨3.6%和4.0%，涨幅分别比上月扩大3.3个和3.6个百分点；大型家用器具价格由上月下降0.1%转为上涨2.7%；金饰品价格上涨0.3%。</p> \n<p cms-style=\"font-L\">　　从同比看，CPI同比下降0.2%，降幅比上月扩大0.1个百分点。其中，食品价格由上月上涨0.7%转为下降1.5%。食品中，水产品和鲜果价格分别上涨3.7%和2.5%，鲜菜价格由上月上涨4.0%转为下降5.3%，鸡蛋和猪肉价格分别下降10.1%和10.0%。非食品价格持平。非食品中，服务价格下降0.2%，降幅比上月扩大0.1个百分点，其中，旅行社收费和在外住宿价格分别下降10.0%和7.0%，飞机票价格由上月下降6.9%转为上涨8.5%；工业消费品价格由上月下降0.4%转为上涨0.2%，其中，大型家用器具价格上涨2.7%，金饰品价格上涨38.4%，汽、柴油价格分别下降9.3%和9.9%。&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4248, NULL, '凤阳：全链条质控严把案件“质量关”', 0, 2, 104, '2025-08-11 10:30:48', '2025-08-11 09:44:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmzi9879641.shtml', '安徽省纪委监委网站', '<p cms-style=\"font-L\">　　“该案违纪事实的时间节点表述不够清晰，证据链还需补充完整……”近日，凤阳县纪委监委对今年以来集中整治重点案件开展专项质量评查，列出问题清单，提出针对性意见，及时反馈承办部门限期整改。</p>\n<p cms-style=\"font-L\">　　案件质量是纪检监察工作高质量发展的生命线。凤阳县纪委监委牢固树立“案件质量共同体”意识，创新建立“前置会诊+专项评查+跟踪问效”全链条质控体系，坚决守牢案件质量底线。</p>\n<p cms-style=\"font-L\">　　如何充分发挥案件审理部门的“关口”“出口”和“窗口”作用？该县纪委监委审理室定期召开审理室务会，组织业务骨干围绕案件事实认定、定性处理、量纪平衡等关键环节开展集体研判，对移送审理案件实行“一案一清单”式质量体检，重点核查事实证据、程序手续、定性处理等核心指标，推动案件质量监督从“事后纠偏”向“过程管控”转变。</p>\n<p cms-style=\"font-L\">　　在夯实日常审核基础上，该县纪委监委以整治群众身边不正之风和腐败问题为契机，开展“靶向治疗”，组建由审理室牵头，案件承办部门、派驻机构共同参与的专项评查组，遵循重点案件全面覆盖的原则，围绕事实是否清楚、证据是否充分、程序是否合规等方面，对全县各级纪检监察机关查办的集中整治案件开展全覆盖、全流程、全方位专项评查。通过交叉互评、个案剖析、类案比对等方式，及时纠正各类问题110个。</p>\n<p cms-style=\"font-L\">　　为确保问题整改取得实效，该县纪委监委注重梳理分析评查发现的问题，充分用好评查结果推动以评促改。针对共性问题及疑难复杂问题，梳理出问题清单，定期组织经验交流、专题授课，定向补短板、精准强弱项，推动实现“质量评估—问题反馈—整改提升”闭环管理。将案件质量纳入纪检监察工作考核体系，实行“季度通报+年度考评”机制，对连续两次质量考评靠后的单位开展约谈提醒，倒逼办案部门树牢“铁案意识”。集中整治开展以来，全县纪检监察机关查办案件未有一起被申诉，处分决定执行到位率达100%。</p>\n<p cms-style=\"font-L\">　　“提升案件质量是一项系统性、长期性工程。下一步，县纪委监委将不断筑牢案件入口、过程、出口全链条质量防线，锻造经得起实践和历史检验的精品案件，不断提升纪检监察工作规范化法治化正规化水平。”该县纪委监委相关负责人表示。（滁州市纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4249, NULL, '寿县：向“质”而行  全流程提升案件查办质效', 0, 1, 12, '2025-08-11 10:30:56', '2025-08-11 09:44:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmyz0571736.shtml', '安徽省纪委监委网站', '<p cms-style=\"font-L\">　　“经评查，该案定性准确，但审查报告、审理报告和处分决定文书中，存在引用条款不准确，漏引或错引条款等问题，请承办单位立行立改......”这是寿县纪委监委案件质量评查组在评查某案件时当场指出问题，推动案件提质增效的生动实践。</p>\n<p cms-style=\"font-L\">　　今年以来，该县纪委监委以高标准开展“纪检监察工作规范化法治化正规化建设年”行动为契机，聚焦案件质量评查、处分执行情况、提升专业能力等重点任务，靶向发力、系统施治，全方位全流程规范案件查办程序，为案件质量提供坚实保障。</p>\n<p cms-style=\"font-L\">　　为持续提升案件办理整体质量和规范化水平，该县纪委监委坚持问题导向，重点聚焦“群腐”案件、上级纪委交办件、留置案件等，抽调审理、信访、案管、纪检监察室业务骨干，组建案件评查小组，定期开展案件质量评查，对事实和程序进行全面审核，确保评查靶向精准。今年以来，共计评查94起案件，发现问题414个，均已督促承办部门整改到位。针对个案存在的质量问题，从案件事实、证据链条、行为定性等方面制发审理工作提示15期，既点明“症状”，又找准“病理”。</p>\n<p cms-style=\"font-L\">　　此外，为做实做细案件审理“后半篇文章”，该县纪委监委制定《关于规范党纪政务处分决定执行工作的通知》，确保处分执行刚性落地、掷地有声。在向受处分党员、公职人员所在单位送达处分决定时，一并送达《处分决定执行事项清单》和处分决定执行情况报告模板，督促指导受处分人所在单位及其党组织依照清单，对处分决定宣布、职务职级调整、工资待遇调整、年度考核等次及奖金的发放、留党察看处分期满后恢复党员权利等事项规范执行，并协调解决疑难问题。2025年以来，已宣布、送达82名受处分人员党纪政务处分决定。</p>\n<p cms-style=\"font-L\">　　与此同时，该县纪委监委紧扣党纪法规解读、证据收集与审查等重点内容，聚焦执纪执法过程中定性量纪情节认定等关键疑难点，构建“线上+线下”培训体系，利用“寿县纪检监察网”开设“纪法知识小课堂”8期；将审理业务列入年度培训计划，通过年轻干部“微课堂”、业务座谈会、纪法宣讲等模式，以学促干，传授“干货”，提升纪检监察干部监督执纪执法能力。</p>\n<p cms-style=\"font-L\">　　“案件质量是纪检监察工作的生命线，下一步，我们将继续以案件质量评查为抓手，‘全周期’指导管控助推案件质量全方位提升。”寿县纪委监委相关负责同志表示。（淮南市纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4251, NULL, '关于推荐全省民族团结进步模范个人有关情况公示', 0, 1, 28, '2025-08-11 12:30:19', '2025-08-11 11:50:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqsif9813797.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　根据省委办公厅、省政府办公厅印发《关于做好全省民族团结进步模范集体和模范个人推荐评选工作的通知》（甘办发电〔2025〕76号），为充分发扬民主，广泛听取意见，接受社会监督，现将我委推荐的全省民族团结进步模范个人有关情况进行公示，公示时间：2025年8月11日至8月15日（5个工作日）。如对公示对象有不同意见，请于8月15日18:00前反映，反映情况须客观真实，反映形式为电话、信函（以到达日邮戳为准），以单位名义反映情况的材料需加盖单位公章，以个人名义反映情况的材料应署实名，并提供联系电话。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">一、公示对象名单</font></p>\n<p cms-style=\"font-L\">　　许可，男，汉族，省纪委监委第二监督检查室三级调研员、四级高级监察官。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">二、受理部门及联系方式</font></p>\n<p cms-style=\"font-L\">　　受理部门：省纪委监委纪检监察干部监督室</p>\n<p cms-style=\"font-L\">　　电话举报：0931-8922424&nbsp;</p>\n<p cms-style=\"font-L\">　　来信地址：兰州市城关区南昌路1648号</p>\n<p cms-style=\"font-L\">　　邮政编码：730030</p>\n<p cms-style=\"font-L align-right\">　　甘肃省纪委监委组织部</p>\n<p cms-style=\"font-L align-right\">　　2025年8月11日&nbsp; &nbsp;</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4258, NULL, '澳大利亚将承认巴勒斯坦国', 0, 4, 13, '2025-08-11 13:30:29', '2025-08-11 11:15:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250806s/107/w1024h683/20250806/9f32-253b358c7778f885b0f7a3b685029fb7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqshx0487771.shtml', '央视', '<p>　　当地时间8月11日，澳大利亚总理阿尔巴尼斯召开新闻发布会，<strong>宣布澳大利亚将承认巴勒斯坦国</strong>。（总台记者 王聪）</p> \n<p>　　<strong>相关报道</strong></p> \n<p>　　<strong>欧洲多国拟承认巴勒斯坦国，但习惯“孤独”的以色列无动于衷（澎湃新闻）</strong></p> \n<p cms-style=\"font-L\">　　以色列总理办公室当地时间8月5日发表声明称，以色列总理内塔尼亚胡当天召开了有限范围的安全会议讨论加沙局势。据以色列媒体报道，会后，内塔尼亚胡强烈倾向于全面占领加沙地带。该计划将于8月7日提交以色列安全内阁全体会议表决。</p> \n<p cms-style=\"font-L\">　　在加沙人道主义危机愈演愈烈之际，多个被视为以色列亲密盟友的欧洲国家转而施压以色列政府。英法两国发表声明，称将正式承认巴勒斯坦国，同时欧洲多国加强对加沙地带的物资援助。这一外交动作虽极具象征性，但在缺乏与美以协调合作的背景下，推动和平解决加沙局势的实际效力仍有待观察。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250806s/107/w1024h683/20250806/9f32-253b358c7778f885b0f7a3b685029fb7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间2025年8月2日，意大利罗马，教皇利奥十六世在托尔维尔加塔主持青年禧年祈祷守夜活动，现场展示着一面巴勒斯坦国旗。视觉中国 图\">\n <span class=\"img_descr\">当地时间2025年8月2日，意大利罗马，教皇利奥十六世在托尔维尔加塔主持青年禧年祈祷守夜活动，现场展示着一面巴勒斯坦国旗。视觉中国 图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">部分治标，远未治本</font></p> \n<p cms-style=\"font-L\">　　近日，法国与英国先后宣布将在9月的联合国大会召开时承认巴勒斯坦国合法地位，虽然短期内难以扭转巴以冲突走向，但仍具有深远意义。</p> \n<p cms-style=\"font-L\">　　首先，这一举措可视为对以色列政府现行加沙政策的否定性回应。自2023年新一轮巴以冲突爆发以来，以色列在加沙地带的物资限入政策与对“两国方案”的避而不谈屡遭欧洲国家批评。7月30日，英国首相斯塔默宣布，除非以色列实施停火并同意两国解决方案，否则英国将于9月承认巴勒斯坦国。8月4日，德国执政联盟的议员西姆捷·莫勒 （Siemtje Moeller）甚至称德国应考虑对以色列实施制裁，包括部分暂停武器出口或暂停欧盟范围内的政治协议。&nbsp;</p> \n<p cms-style=\"font-L\">　　其次，有利于巴以问题在欧洲外交议程中的“再中心化”。战争长期化与人道主义灾难持续，更使欧洲难以维系模糊路线，大国必须重申对“两国方案”的明确支持以维持道义性。通过承认巴勒斯坦国的合法地位，还可能促进欧洲与南方国家在巴以和平进程上的合作。</p> \n<p cms-style=\"font-L\">　　再者，该行动强化了欧洲在中东问题上相对美国的独立立场。美国对于以色列的一味偏袒已在盟友内部引发不满。欧盟长期反对以色列非法定居点扩张和吞并约旦河西岸，与美现政府存在分歧。</p> \n<p cms-style=\"font-L\">　　同时，欧美在关税与贸易问题上的纠纷，使欧洲更倾向于在外交上与美国“保持距离”。欧洲国家承认巴勒斯坦国合法地位，不仅是人道主义姿态，也是一种对美国的政策牵制，有利于掌握更多筹码，平衡双方谈判地位。</p> \n<p cms-style=\"font-L\">　　其中也包含了英法两国政府各自的利益考量。马克龙政府期望借此机会强化欧洲在中东地区的独立发声，同时回应国内人道主义的呼声以及穆斯林社区对巴勒斯坦的支持。英国工党政府则试图塑造国际道义领导者的形象。工党长期以来支持“两国方案”，承认巴勒斯坦的主权地位也是其兑现选举承诺的一环。</p> \n<p cms-style=\"font-L\">　　然而，这一政策转向仍具有高度象征性。一方面，英法的这一表态并不伴随对巴勒斯坦民族权力机构的现实支援，尤其是在美国宣布对后者实施制裁的情况下；另一方面，也未出台针对以色列的制裁措施或调整安全合作架构。2024年5月，挪威、爱尔兰和西班牙三国同日宣布承认巴勒斯坦国合法地位，尽管在外交上引发波澜，但并未对战场态势产生实质影响。英法等欧洲国家的举措也难以解决加沙地带的燃眉之急。</p> \n<p cms-style=\"font-L\">　　在人道主义援助方面，随着加沙地带人道主义危机持续恶化，欧洲数国宣布启动空投人道物资的紧急行动，法国、德国、西班牙等相继参与，意大利和荷兰亦表明即将加入。然而，空投成本高、风险大。物资坠落不当曾造成死伤；部分区域还出现饥民哄抢救援车队、踩踏事故等。“无国界医生”组织早已警告，空投“无效且危险”；联合国近东救济工程处（UNRWA）总干事菲利普·拉扎里尼也直言，空投是一种昂贵而低效的“干扰”，不能替代地面准入。</p> \n<p cms-style=\"font-L\">　　欧洲国家的承认与援助之举，虽展现了对巴勒斯坦民众更为直接的人道主义支持之意，但面对严重危机效果有限、代价高昂，难以作为加沙之困的止痛药。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250806s/106/w1024h682/20250806/41a3-ffda46c6d41b40511ab63da30abe9794.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间2025年8月1日，英国伦敦，在伦敦西南部金斯顿区，示威者手持巴勒斯坦旗帜参加“停止饿死加沙”抗议活动，谴责以色列的封锁，并呼吁关注加沙地带的人道主义危机。视觉中国 图\">\n <span class=\"img_descr\">当地时间2025年8月1日，英国伦敦，在伦敦西南部金斯顿区，示威者手持巴勒斯坦旗帜参加“停止饿死加沙”抗议活动，谴责以色列的封锁，并呼吁关注加沙地带的人道主义危机。视觉中国 图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“独居的民，不列在万民之中”？</font></p> \n<p cms-style=\"font-L\">　　2025年6月中旬以来，欧盟对以色列已从口头的敦促停火转向切实的外交动作。但事实上，外交上的“孤独”乃至“围困”，难以对以色列国内政治产生根本性影响。</p> \n<p cms-style=\"font-L\">　　正如美国前国务卿基辛格直言，<font cms-style=\"font-L strong-Bold\">以色列“只有对内政策，没有对外政策”。</font>其战略始终围绕“国家安全”展开。在右翼政治视野中，外交妥协往往被视为安全让步，尤其是在涉及哈马斯、伊朗、黎巴嫩真主党等“敌对实体”时。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“安全至上”原则不仅压缩了和平谈判空间，也削弱了对国际批评的敏感度。</font>在此原则指导下，用增加哈马斯的生存空间“换取”人质释放，被视为姑息长期安全威胁。以色列人质释放谈判小组高级成员、前国防军准将奥伦·塞特（Oren Setter）对以媒Ynet News表示，“只要这个政府还在（假如它不从根本上改变路线），就不会达成全面协议”。</p> \n<p cms-style=\"font-L\">　　极右翼政客的行为则呈火上浇油之势。8月3日是犹太传统的“圣殿被毁日”（Tisha B‘Av），本是沉静的哀悼之日。然而，以色列警察部门总负责人、安全部长伊塔玛·本-格维尔当天率队参拜圣殿山，即阿克萨清真寺所在地，引发阿拉伯世界的强烈不满，加剧民族和宗教矛盾。在无视国际反对声音的同时，一些极右翼高官甚至以辞职威胁，拒绝和谈妥协。</p> \n<p cms-style=\"font-L\">　　此外，从历史看，以色列社会对于“孤立”的国际环境的接受度并不低，甚至一定程度上存在所谓命定孤独的概念+。前以色列驻美国大使迈克尔·奥伦曾援引《民数记》“独居的民”一说，呼吁团结、反抗“注定孤独”的命运。对该国占人口多数的犹太民族而言，自中世纪以来的多次排犹浪潮、纳粹大屠杀以及独立建国初期遭遇的围攻战争，都曾使他们反复面对“社会死亡”和“国际孤立”的处境，已塑造出“外部世界不可靠”的集体心理。源于欧洲的道义施压，容易被视为旧偏见的延续，而非缓和局势的努力。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“持久战争”的危机</font></p> \n<p cms-style=\"font-L\">　　以色列与哈马斯谈判僵局持续，其在加沙的军事行动很有可能还将扩大。日前，总理内塔尼亚胡再次强调，战争的三大目标是：击败哈马斯、解救人质，以及防止加沙再度威胁以色列的安全。在这一框架下，军事行动而非外交妥协成为政策主轴。</p> \n<p cms-style=\"font-L\">　　尽管反战呼声日益高涨，但以政府的路线依然获得了相当一部分民众的支持。8月，反映被扣留人质埃维亚塔·大卫（Evyatar David）惨状的相关影像在以色列媒体上广泛传播，引发了大规模抗议浪潮，敦促政府尽快推动人质释放。而以色列国家安全研究所（INSS）6月下旬进行的民调显示，约63%的受访者（其中70%为犹太人）坚信以军将在加沙取得胜利，其中超过半数的人认为战争的目标“基本或完全能够实现”。2023年10月的袭击事件加剧了以色列民间的强烈不安全感和民族间的不信任情绪。</p> \n<p cms-style=\"font-L\">　　美国的中东政策转变促使以色列更急于寻求安全保障。美国“重返亚太”的大方向已历经三届总统维持。特朗普政府一边为以色列在联合国保驾护航，一边多次表示要减少在中东地区的军事投入。在美国的安全保障出现实质性缩水之前，为自己塑造一个无强敌的地区环境，或成为以色列决策者眼中的合理选择。</p> \n<p cms-style=\"font-L\">　　然而，安全无上限往往意味着威胁无边界。这也对以色列与更大范围内国家的交往产生了影响，其中最显著的是其对伊斯兰国家的态度。早在20世纪70年代，前总理梅纳赫姆·贝京就曾致信时任英国首相撒切尔夫人，呼吁阻止巴基斯坦的核计划，否则该计划将成为以色列人民的“致命威胁”。本轮巴以冲突使以色列与伊斯兰合作组织（OIC）之间关系紧张。除了政治和外交影响外，这也意味着以色列可能失去一个庞大且有潜力的未来市场。</p> \n<p cms-style=\"font-L\">　　总体上，持久的战争使以色列面临三重危机。其一，社会危机。由人质困境和战争损耗引发的经济负荷与民意割裂。其二，军事危机。部队长期作战逐渐疲劳，而预备役征召方面政府与拒服兵役的极端正统派存在冲突。其三，外交危机。其多个欧洲盟友宣布将承认巴勒斯坦国合法地位或是罕见地批评其行事，以及在美国公众舆论中形象下降，造成在国际上更为“孤立”的局面。</p> \n<p cms-style=\"font-L\">　　尽管欧洲国家的压力短期内难以扭转局势，但外交危机对以色列的负面影响不容忽视。长期而言，以色列与欧洲在科技和人才领域的密切交流将有所减弱，进而可能影响到防务技术的合作，与以右翼的安全追求实则背道而驰。有以色列学者对此表达担忧，预估未来两到三年内双方高校和研究机构间的共同发表量将出现下降。此外，继英法之后，更多欧洲国家，如比利时、葡萄牙等，也可能纷纷跟进，引发一轮西方国家承认巴勒斯坦国合法地位的浪潮。</p> \n<p cms-style=\"font-L\">　　三十年前，还是一位年轻外交官的内塔尼亚胡在《华盛顿邮报》上发表文章，强调公民社会的政治文化对于打击恐怖主义的重要性。他指出，恐怖主义在民主社会中走向毁灭的根源在于其认为社会的每个成员都是“有罪的”，任何人都可能成为受害者，因此无人能感到安全——这种观念必将遭到公民的普遍抵制，而“相信和平解决分歧，相信他人的基本权利，相信国家的法律——所有这些都是民主教育的基石，乃至民主世界观的根本。”</p> \n<p cms-style=\"font-L\">　　时过境迁，但尊重各方权利的和平手段仍是冲突解决的必经之路，也是弥合欧以分歧的重要渠道。</p> \n<p cms-style=\"font-L\">　　（王利莘，上海社会科学院国际问题研究所助理研究员）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1726618917\" target=\"_blank\">黎巴嫩多地寻呼机爆炸</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/sinakd20250806s/107/w1024h683/20250806/9f32-253b358c7778f885b0f7a3b685029fb7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250806s/106/w1024h682/20250806/41a3-ffda46c6d41b40511ab63da30abe9794.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4259, NULL, '“企图持续掩盖真相” 半岛电视台谴责以军袭击新闻工作者', 0, 4, 95, '2025-08-11 13:30:39', '2025-08-11 10:09:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/692/w994h498/20250811/77c7-610f1e5fb2236097173c72c23b304eac.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqmzf6061972.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，卡塔尔半岛电视台发表声明称，该台<font cms-style=\"font-L strong-Bold\">5名新闻工作者</font>10日晚在加沙地带遭遇以军袭击死亡。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/692/w994h498/20250811/77c7-610f1e5fb2236097173c72c23b304eac.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△阿纳斯·谢里夫\">\n <span class=\"img_descr\">△阿纳斯·谢里夫</span>\n</div> \n<p cms-style=\"font-L\">　　声明表示，以色列国防军10日晚对加沙城希法医院之外的帐篷营地发动袭击，造成7人死亡，其中包括半岛电视台记者阿纳斯·谢里夫和穆罕默德·克赖克赫，以及摄像易卜拉欣·扎赫尔、穆罕默德·努法勒和穆阿明·阿利瓦。</p> \n<p cms-style=\"font-L\">　　声明称，半岛电视台的新闻工作者在加沙向世界报道当地民众遭遇的饥饿和痛苦，<font cms-style=\"font-L strong-Bold\">以军针对他们的袭击是对新闻报道的压制，半岛电视台将追究以色列政府和相关人员的责任。</font></p> \n<p cms-style=\"font-L\">　　声明强烈谴责以军令人发指的罪行和持续掩盖真相的企图，呼吁国际社会采取果断措施，制止以军在加沙地带进行的种族灭绝行为，以及故意针对新闻工作者的犯罪行为。（总台记者 赵远方）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color240\"><font cms-style=\"font-L strong-Bold color240\"></font></font></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/692/w994h498/20250811/77c7-610f1e5fb2236097173c72c23b304eac.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4263, NULL, '北约秘书长：无论俄美会谈结果如何 北约都将继续向乌供武', 0, 4, 204, '2025-08-11 14:30:24', '2025-08-11 13:28:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/b03f-735ef003651bd25b9b3ddff489696529.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqsic6006994.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/b03f-735ef003651bd25b9b3ddff489696529.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　北约秘书长吕特10日在接受媒体采访时表示，无论俄美领导人会晤结果如何，北约都将继续向乌克兰提供武器。吕特称，北约致力于确保乌克兰拥有继续战斗所需的武器，在停火或和平谈判到来之际处于有利的位置。他还称，此次俄美领导人会晤不会就解决乌克兰冲突达成“最终协议”，欧洲和乌克兰都需要参与俄乌和平进程。</p> \n<p cms-style=\"font-L\">　　俄罗斯外交部此前曾表示，北约国家向乌克兰供应武器是“在玩火”，任何包含乌克兰武器的物资都将成为俄罗斯的合法打击目标。俄总统新闻秘书佩斯科夫也曾表示，西方向乌克兰输送武器无助于俄乌谈判取得成功，只会有消极效果。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1690874275\" target=\"_blank\">每日军情</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/b03f-735ef003651bd25b9b3ddff489696529.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4264, NULL, '消息人士：哈马斯代表团将访问埃及 旨在重启加沙停火谈判', 0, 4, 60, '2025-08-11 14:30:33', '2025-08-11 13:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/623/w906h517/20250811/2cb6-f771c6efb9eee0726b25333c414d716e.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwqy8796985.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/623/w906h517/20250811/2cb6-f771c6efb9eee0726b25333c414d716e.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　总台记者当地时间8月11日获悉，一名消息人士表示，<font cms-style=\"font-L strong-Bold\">一个巴勒斯坦伊斯兰抵抗运动（哈马斯）代表团将于当天抵达埃及首都开罗</font>，旨在重启陷入僵局的加沙地带停火谈判。</p> \n<p cms-style=\"font-L\">　　这名消息人士表示，哈马斯代表团由哈马斯首席谈判代表哈利勒·哈亚率领，该代表团此前访问了土耳其，与土方官员就加沙局势及停火谈判进展交换了意见。</p> \n<p cms-style=\"font-L\">　　以色列与哈马斯自7月6日起在多哈就加沙地带停火和交换被扣押人员等问题展开新一轮间接谈判。7月24日，美国和以色列分别召回各自在多哈参与停火谈判的人员，导致谈判暂时中止。（总台记者 赵远方）</p> \n<!--article_adlist[<p cms-style=\"font-L strong-Bold align-Center\"></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/623/w906h517/20250811/2cb6-f771c6efb9eee0726b25333c414d716e.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4265, NULL, '美国副总统万斯：乌克兰和平协议不太可能令双方都满意', 0, 4, 207, '2025-08-11 15:30:24', '2025-08-11 15:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwqz5925342.shtml', '参考消息', '<p cms-style=\"font-L\">　　来源：参考消息</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">参考消息网8月11日报道</font> 据新加坡《联合早报》网站8月11日报道，美国副总统万斯在10日播出的福克斯新闻频道采访中表示，俄罗斯和乌克兰通过谈判达成的和解不太可能让任何一方满意，任何和平协议都可能让莫斯科和基辅“不满意”。“这不会让任何人非常满意。俄罗斯和乌克兰最终可能都会对此感到不满意。” 他说，美国的目标是达成两国都能接受的解决方案。</p> \n<p cms-style=\"font-L\">　　据路透社报道， 特朗普此前曾暗示，俄罗斯和乌克兰已接近达成停火协议，协议内容可能涉及土地交换，但未披露详情。然而，泽连斯基9日表示，乌克兰不能在领土问题上违反宪法。“乌克兰人不会把自己的土地送给占领者。”</p> \n<p cms-style=\"font-L\">　　除此之外，万斯还强调，美国不愿再为乌克兰提供抵御俄罗斯的资金。</p> \n<p cms-style=\"font-L\">　　万斯长期以来对美国为乌克兰的武器装备买单提出质疑，他说，特朗普政府不希望再为乌克兰提供国防资金，但乌克兰要向美国公司购买武器是没有问题的。</p> \n<p cms-style=\"font-L\">　　他说：“我们不想再为乌克兰的战争提供资金。我们希望达成一个和平解决方案。我们希望停止杀戮。但我认为，美国人对继续把他们的钱、把美国纳税人的钱投入到这场冲突中已经感到厌倦。”</p> \n<p cms-style=\"font-L\">　　万斯说：“但如果欧洲人愿意出钱，向美国军火商购买武器，我们不会反对。但我们是不会再出资的。”</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4266, NULL, '罗马诺：一切都已签订，莫拉塔可以被视为科莫球员', 0, 4, 96, '2025-08-11 15:30:31', '2025-08-11 15:08:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250811/2946-6a837e1ad29263674c446d70af1859e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwqv0444992.shtml', '直播吧', '<p cms-style=\"font-L \">　　来源：直播吧</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250811/2946-6a837e1ad29263674c446d70af1859e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　直播吧8月11日讯 <font cms-style=\"font-L\">据记者罗马诺消息，莫拉塔已经可以被视为科莫球员。</font></p> \n<p cms-style=\"font-L\">　　在个人社媒，罗马诺写道：一切都已签订，在加拉塔萨雷租借合同结束后，莫拉塔可以被视为来自米兰的科莫新援。</p> \n<p cms-style=\"font-L\">　　此前据罗马诺消息，科莫向加拉塔萨雷支付接近500万欧的赔偿金以解除莫拉塔租借合同。 随后科莫将以租借附带强制买断的形式从米兰签下莫拉塔。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1749081642\" target=\"_blank\">2025国际足坛夏季转会窗</a>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250811/2946-6a837e1ad29263674c446d70af1859e2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4267, NULL, '特朗普忍不了白宫了', 0, 4, 207, '2025-08-11 15:30:38', '2025-08-11 12:00:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/200/w1080h720/20250811/4118-a943f8edf144a1889911ad858f7fe4c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqsif9819541.shtml', '中国新闻周刊', '<p>　　来源：中国新闻周刊</p> \n<p cms-style=\"font-L align-Center\">　　如同翻版海湖庄园</p> \n<!--article_adlist[<p cms-style=\"font-L align-Center\"></p>]article_adlist--> \n<p cms-style=\"font-L\">　　在对椭圆形办公室进行了金光闪闪的改造后，特朗普又开始对白宫建筑下手了：建造一个大型宴会厅。</p> \n<p cms-style=\"font-L\">　　当地时间7月31日，美国白宫新闻秘书卡罗琳·莱维特宣布，特朗普将在白宫内修建一座总面积约9万平方英尺（约8300平方米）的宴会厅，用来举办重要接待活动。她表示，白宫现有空间难以举办他国贵宾出席的重要仪式，除非在距离主楼入口约91米远的南草坪上临时搭建又大又丑的帐篷。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/200/w1080h720/20250811/4118-a943f8edf144a1889911ad858f7fe4c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"7月31日，美国华盛顿，白宫新闻秘书莱维特在每日简报会上展示白宫新宴会厅的效果图。\">\n <span class=\"img_descr\">7月31日，美国华盛顿，白宫新闻秘书莱维特在每日简报会上展示白宫新宴会厅的效果图。</span>\n</div> \n<p cms-style=\"font-L\">　　“150年来，历届总统、政府和白宫工作人员都渴望在白宫内拥有一个能够容纳更多宾客的大型活动空间。”莱维特说，“特朗普总统已表示，他致力于代表未来的政府和美国人民解决这个问题。”</p> \n<p cms-style=\"font-L\">　　“我们已经筹划这个很久了。”特朗普当天在接受白宫随行记者采访时表示，“但从来没有一位总统真正懂得如何建造宴会厅。”</p> \n<p cms-style=\"font-L\">　　据悉，作为白宫的“世纪工程”，新宴会厅耗资约2亿美元，计划于今年9月开工，在特朗普这届总统任期结束前完成。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">“一下雨简直是灾难”</font></p> \n<p cms-style=\"font-L\">　　白宫动工于1792年，1800年建成，成为美国总统官邸。白宫建筑群由主楼、西翼、东翼和地堡系统构成，外加南北草坪与多座花园。主楼是总统及其家人的官邸，也是举行国事活动的核心空间。西翼设有椭圆形办公室、内阁会议室与新闻发布厅，是总统及幕僚的日常办公场所。</p> \n<p cms-style=\"font-L\">　　此次特朗普计划建造的白宫宴会厅，位于白宫东翼。主要是第一夫人和白宫私人管家办公的地方，还设有白宫社交秘书办公室、白宫电影院、游客入口等。</p> \n<p cms-style=\"font-L\">　　历史上，东翼区域经历过多次翻修调整。据白宫历史协会官网介绍，如今的东翼建筑扩建于1942年富兰克林·罗斯福任内，主要目的是掩盖总统紧急行动中心的地下掩体建设。</p> \n<p cms-style=\"font-L\">　　通常，总统们会选择主楼一层西南侧的国宴厅举办正式晚宴。这里最早是一个小型起居间，曾被用作客厅、办公室和会议室。经过多次扩建，如今最多可容纳约140位宾客。</p> \n<p cms-style=\"font-L\">　　当活动规模更大时，场地往往会转至同层东侧的东厅。东厅是白宫现存最大的房间，配置简约，场地改造灵活，最多可容纳约200人。但即便是东厅，有时也难以满足一些大型活动的需求。而白宫长期以来的应对方案便是临时在户外南草坪上搭建豪华帐篷，配有地板、灯光与吊灯。</p> \n<p cms-style=\"font-L\">　　“这其实是一个大工程。”奥巴马当政时期的白宫社交秘书迪莎·戴尔在接受美国全国公共广播电台（NPR）采访时表示，“你必须打造出不那么像是在草坪上坐着的感觉。从花艺、灯光、吊灯到桌布摆设，每一个细节都要考虑周全。”</p> \n<p cms-style=\"font-L\">　　但显然，特朗普并不满意这种“临时搭棚”的方式，“一下雨简直是灾难”。他想要一个能容纳更多人的豪华宴会厅。根据规划，新建的白宫宴会厅可容纳多达650位宾客就座，容量是现有东厅的三倍多。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">翻版海湖庄园</font></p> \n<p cms-style=\"font-L\">　　特朗普对宴会厅的执念，并非一时兴起。</p> \n<p cms-style=\"font-L\">　　据《时代》周刊报道，早在2011年，当特朗普首次表达参选总统的意向时，他便在拉什·林博（Rush Limbaugh）的广播节目中提出修建白宫宴会厅的想法：“我们会走流程，交给委员会审议，挑选公众喜爱的建筑师和最棒的设计。我会免费建造它，这将是一份价值五千万至一亿美元的礼物。”</p> \n<p cms-style=\"font-L\">　　2016年2月，在艾奥瓦州西北部城市苏城（Sioux City）的一场演讲中，特朗普又提到在白宫建造宴会厅的想法，称自己联系过奥巴马政府，表示愿意无偿援建宴会厅，但从未得到任何回复。</p> \n<p cms-style=\"font-L\">　　“我们会找来最顶尖的建筑师，最专业的团队，建造最棒的宴会厅，因为我注意到他们总是在草坪上搭帐篷。”特朗普说，“首先，这在安保上不妥；其次，这让那些租帐篷的人赚了很多钱 。”</p> \n<p cms-style=\"font-L\">　　而时任白宫新闻秘书乔什·厄内斯特则表示，根本没有认真考虑过特朗普的这一提议，不确定在白宫的任何地方挂上一个闪闪发亮的“特朗普”金标牌是否合适。</p> \n<p cms-style=\"font-L\">　　时隔近10年，特朗普再次入主白宫，终于要兑现这项延宕已久的许诺。今年2月，特朗普在白宫东厅签署一项行政命令后，向周围人抱怨：“你们看，这个房间太拥挤了。”</p> \n<p cms-style=\"font-L\">　　“我曾经提出要为白宫建一座宴会厅，这里原本要作为接待厅……我把这个提议递给了拜登政府，一个非常‘积极活跃’的政府，但他们也没回应。”特朗普说。在他看来，“我们已经过了搭帐篷的阶段了”。</p> \n<p cms-style=\"font-L\">　　今年5月，特朗普在接受美国全国广播公司（NBC）专访时信心满满地强调，将为白宫建造一座“世界级、美丽”的宴会厅。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/88/w1080h608/20250811/3631-f95363a6e825cc3a9fc8e1eb0197fc3b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"白宫新宴会厅效果图。本文图/视觉中国\">\n <span class=\"img_descr\">白宫新宴会厅效果图。本文图/视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　白宫发布的效果图上，白金主色调、镶花地板、金色科林斯式柱子、镶金吊灯、巨大拱形窗……这样的风格装饰不免让人想到特朗普的豪华府邸海湖庄园。</p> \n<p cms-style=\"font-L\">　　特朗普第一任期内就称海湖庄园为“冬季白宫”，装饰风格极尽奢华，宴会厅也是以金色为主调，融合西班牙摩尔与法式巴洛克风格，充满金箔装饰、水晶吊灯、镜面天花与仿古雕像。</p> \n<p cms-style=\"font-L\">　　特朗普向来偏爱金色，这一点从重新装饰好的椭圆形办公室可见一斑。壁炉架上历史悠久的常春藤装饰，被替换成七件精致的镀金器皿，原本光滑的表面也镶上了两处金色花饰。先前简约的木制边桌换成了华丽的大理石台面，底座也由镀金老鹰支撑。在光滑的木桌中央，总统印章夹在一叠金色杯垫和刻着特朗普名字的镀金镇纸之间。办公桌后方是一座闪闪发光的金色奖杯，那是国际足联主席亲手送给特朗普的奖杯复制品，预示着即将在北美举办的世界杯。此外，白宫的门楣上还悬挂着特朗普特意从海湖庄园运来的金色天使雕像。</p> \n<p cms-style=\"font-L\">　　“一切可以是金子的东西都用金子。”《华盛顿邮报》形容道。</p> \n<p cms-style=\"font-L\">　　批评者认为，金碧辉煌的装饰打破了白宫一贯的庄重典雅。前白宫社交秘书迪莎·戴尔（Deesha Dyer）在接受采访时表示，一个大宴会厅更像是希尔顿酒店的场地，而不是白宫的一部分。不过，白宫也在声明中表示，宴会厅风格和装饰将与白宫的其他部分“几乎完全相同”。</p> \n<p cms-style=\"font-L\">　　“特朗普总统骨子里是个建造者，在细节上有着非凡的眼光。”白宫办公厅主任苏茜·威尔斯在声明中表示，总统和白宫将全力与相关机构合作，在保留白宫历史特色的同时，建造一座优美的宴会厅，让未来的历届政府和美国人民都能共享这一空间。</p> \n<p cms-style=\"font-L\">　　宴会厅的建筑设计将由总部位于华盛顿的麦克雷里建筑事务所承担。该事务所以古典建筑设计闻名，曾参与包括美国国会大厦、最高法院、诺克斯维尔主教座堂等诸多著名项目的设计与修复。施工部分，则将由克拉克建筑公司主导。该公司是美国规模最大的商业与土木工程承包商之一，曾承建联邦调查局中央档案馆、美国国家陆军博物馆以及白宫游客中心等标志性工程项目。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">对质疑不屑一顾</font></p> \n<p cms-style=\"font-L\">　　自1792年动工以来，白宫已历经多次改建。无论出于功能所需、预算考量，抑或是总统的个人审美，这座象征着最高权力的建筑的每一次变动，几乎都伴随着争议。</p> \n<p cms-style=\"font-L\">　　白宫历史协会主席斯图尔特·麦克劳林在《不断变化的白宫》一文中提到，由于木梁结构不堪重负、管线与电力系统严重老化，白宫不得不在1948年整体拆除重建。时任总统杜鲁门主导了一场耗资570万美元的大规模翻修工程，虽属必要之举，却遭到在野党猛烈批评，认为其在战后经济恢复阶段不合理动用高额公款，质疑其财政管理能力。</p> \n<p cms-style=\"font-L\">　　自那之后，白宫虽经历多次内部装修与功能调整，却未再出现大规模的结构性改建，直到特朗普提出建造一座全新的白宫宴会厅。</p> \n<p cms-style=\"font-L\">　　特朗普方面称，该宴会厅将完全由他本人及“爱国捐赠者”出资，但白宫并未公布任何捐赠者名单。这也并非特朗普首次依赖私人资金进行改造。6月，他为白宫新增两根高达88英尺的旗杆，同样宣称由私人出资。</p> \n<p cms-style=\"font-L\">　　在美国，个人捐赠行为受到多项法律的规范，特别是当捐赠对象涉及政府机构、公职人员或具有公共性质的项目时。例如《政府道德法案》就对包括总统在内的联邦官员任职期间接受“礼品、服务或捐赠”提出明确的限制要求。</p> \n<p cms-style=\"font-L\">　　《美国法典》第18卷第201章也规定，禁止公职人员寻求、接受、同意收取或接受有价物品，从而影响其履行公职，或者导致其违反其职责而作为或不作为。实物、现金、服务、建造项目、旅行安排、名誉宣传等，都被认定为“有价值之物”（thing of value）。</p> \n<p cms-style=\"font-L\">　　批评者担心，若宴会厅建成后显著提升白宫的接待能力，总统或将更便捷地向政治盟友与捐赠者提供公共资源，进而加剧“权钱交易”的风险。</p> \n<p cms-style=\"font-L\">　　“那些想讨好总统的人自然会写支票。”曾在小布什政府担任白宫法律道德顾问的理查德·佩因特警告称，“这完全是美国政治中付费游戏问题的延伸。”</p> \n<p cms-style=\"font-L\">　　因此，法律层面上，若私人捐赠者在资助宴会厅后获得政策便利、宴请邀约或联邦合同，都将面临违反公职伦理法规的风险。更合规的路径应是通过如白宫历史协会等独立的非营利机构，以明确用途、无利益交换的形式接收捐赠，且须向公众披露资金来源与使用情况。</p> \n<p cms-style=\"font-L\">　　根据美国《国家历史保护法》第106条规定，联邦机构在采取可能影响具有历史、建筑、考古或文化意义的遗址的行动之前，必须进行咨询，以评估和减轻行动的影响。而白宫作为总统公园的一部分，是美国国家历史地标，隶属国家公园管理局（NPS）管理。因此。特朗普的大改造计划可能还需要接受国家历史保护咨询委员会（ACHP）等机构的程序性审议与评估。</p> \n<p cms-style=\"font-L\">　　此外，在当前就业疲软、经济不振的大环境下，特朗普修建宴会厅的计划引发诸多质疑和批评。美国前劳工部长、加州大学伯克利分校公共政策教授罗伯特·赖克在自己的播客节目中评论称，在数百万人艰难度日的情况下，特朗普要在白宫建宴会厅。民主党籍的加州联邦参议员亚当·希夫更是在社交平台X上冷嘲热讽：“物价飞涨，工作难找，但别担心，特朗普正为你准备一个2亿美元的宴会厅。”</p> \n<p cms-style=\"font-L\">　　曾任前第一夫人劳拉·布什幕僚长的安妮塔·麦克布莱德认为，虽然临时搭帐篷使用起来确实有诸多不便，特别是在天气不佳时，但现在修建新建筑可能会影响东翼工作人员的工作。而且，东翼不仅是第一夫人团队的办公场所，也是公众参观白宫的起点。</p> \n<p cms-style=\"font-L\">　　但特朗普对这些不屑一顾，他以一贯高调的口吻在社交平台上写道：“这是一位名叫唐纳德·J。特朗普的人献上的礼物。”这个即将动工的白宫“大而美”工程，也是他试图在白宫这座象征权力的建筑上留下属于“建设者总统”的个人印记。</p> \n<p cms-style=\"font-L\">　　作为一个在纽约起家的地产大亨和品牌经营者，特朗普还毫不掩饰对自己建设者身份的认同：“我是一名出色的建设者，我擅长建东西，我喜欢建东西。”</p> \n<p cms-style=\"font-L\">　　发于2025.8.11总第1199期《中国新闻周刊》杂志</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">杂志标题</font><font cms-style=\"font-L\"><font cms-style=\"font-L\">：</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">特朗普的白宫“大而美工程”</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">作者：</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">殷晨浠</font></font></p> \n<p></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/200/w1080h720/20250811/4118-a943f8edf144a1889911ad858f7fe4c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/88/w1080h608/20250811/3631-f95363a6e825cc3a9fc8e1eb0197fc3b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4268, NULL, '百色教师性侵学生案最新进展，受害人家属：庭前会议对方提出赔偿十万调解，没说对不起', 0, 2, 222, '2025-08-11 15:30:45', '2025-08-11 15:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/367/w524h643/20250811/fd37-951b82a4a06e82f2121113aff7112acd.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwqy8845366.shtml', '新浪新闻综合', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">来</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">源 |</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">&nbsp;潇湘晨报</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">记者</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">&nbsp;|</font></font><font cms-style=\"font-L\"></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">钱嘉鑫</font></font></font></p> \n<p cms-style=\"font-L\">　　近日，广西百色祈福高中被班主任性侵致轻生的受害学生符某某表姐在网络发文称，8月7日此案进行了庭前会议，致表妹轻生的男教师唐某某方提出调解和赔偿，表妹父母出席了庭前会议，坚决反对调解，还说会议中唐某某没有一丝悔意，连一句对不起都没说。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/367/w524h643/20250811/fd37-951b82a4a06e82f2121113aff7112acd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"嫌疑人唐某某。网络截图。\" data-link=\"\">\n <span class=\"img_descr\">嫌疑人唐某某。网络截图。</span>\n</div> \n<p cms-style=\"font-L\">　　8月11日，符某某表姐薛女士告诉潇湘晨报记者，7日应唐某某方要求，法院召开庭前会议调解，唐某某说自己上有老下有小，今后会很不容易，愿意赔偿十万元，符某某的父母说不要赔偿，协商不了。薛女士说，唐某某说话语气不像是知道自己犯错了，全程没有一句道歉。</p> \n<p cms-style=\"font-L\">　　薛女士说，检察院以强奸、强制猥亵罪对唐某某提起公诉，家属的诉求是希望对唐某某的量刑能够最大化，“如果只有三年以下肯定是不认可的，至少要十年。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/38/w550h288/20250811/967c-7d7493797caa538a6989c88041febbb7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"祈福高中。网络截图。\" data-link=\"\">\n <span class=\"img_descr\">祈福高中。网络截图。</span>\n</div> \n<p cms-style=\"font-L\">　　薛女士还告诉记者，祈福高中事后没有联系过家属，既没有向家属了解过事情也没有向家属道歉慰问。</p> \n<p cms-style=\"font-L\">　　符某某生前在校成绩非常好，是学校的种子选手，本应该得到重点关注，可是符某某在校期间频繁闹自杀、剪掉准考证以及弃考，学校都没有过问过家属。薛女士说，在唐某某案后，将追究学校的责任。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">据媒体报道，</font><font cms-style=\"font-L\"><font cms-style=\"font-L\">2025年1月17日，患有重度抑郁症的符某某自杀身故，其三位堂表姐为其整理遗物时从日记和微信记录中，发现了妹妹精神状态长期恶化的可能诱因，即其高中班主任唐某某利用其教师身份和职权，对妹妹符某某进行情感操控，于是将其实名举报，引发舆论震动。之后，唐某某被停职、开除党籍并立案侦查。</font></font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/367/w524h643/20250811/fd37-951b82a4a06e82f2121113aff7112acd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/38/w550h288/20250811/967c-7d7493797caa538a6989c88041febbb7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4269, NULL, '南宁一公司董事长系17岁未成年人？当地市监称确为17岁，公司真实存在！当事人回应：本人系中职生', 0, 2, 213, '2025-08-11 15:30:52', '2025-08-11 15:17:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/601/w550h851/20250811/6966-68916656f5b054203f6bd6100666bc3f.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwqz5928430.shtml', '扬子晚报', '<p cms-style=\"font-L\">　　来源：扬子晚报</p> \n<p cms-style=\"font-L\">　　10日，社交平台上一则关于“广西某某科技有限公司董事长系未成年人”的帖子引发广泛关注。网传截图显示，该公司董事长谢某某出生于2008年4月，今年17岁，于2024年1月入职，并在公司任职董事长。在某招聘平台展示的公司页面中，谢某某的头像、简历均公开可见，其职务介绍为“全面主持公司董事会各项工作”。该公司注册地位于广西南宁市武鸣区，员工规模显示为20至99人。公司介绍为“非遗传承、绿色农业为一体的现代化企业”，并展示多名高管头像。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/601/w550h851/20250811/6966-68916656f5b054203f6bd6100666bc3f.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"网民发帖称有人17岁就当了企业董事长。 网络图\" data-link=\"\">\n <span class=\"img_descr\">网民发帖称有人17岁就当了企业董事长。 网络图</span>\n</div> \n<p cms-style=\"font-L\">　　未成年人当企业董事长的帖子引发不少网友讨论。在帖子评论区，有人表示好奇：“公司董事长这么年轻，不知道能不能胜任管理工作。”也有人质疑其任职资格：“未成年人不能独立承担完全民事责任，是否符合公司法规定值得关注。”还有网友惊讶于公司架构：“还有股东会和分公司，看着规模不小。”</p> \n<p cms-style=\"font-L\">　　8月11日，上游新闻记者通过社交平台私信联系到谢某某本人。他确认，自己确系该公司董事长和法定代表人，并透露自己是一名中等职业学校学生。“注册公司一方面是为了参加大学生创新大赛，另一方面也有一些正常的经营和公益项目活动。”谢某某表示，公司在经营过程中严格遵守法律法规，“不存在任何违法违规行为。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/223/w550h473/20250811/14db-971d60f8f1cd43113b170f9b63a86401.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"该企业参加了全国大学生创业大赛，参赛赛道是“职教赛道”，现在已注册公司。受访者供图\" data-link=\"\">\n <span class=\"img_descr\">该企业参加了全国大学生创业大赛，参赛赛道是“职教赛道”，现在已注册公司。受访者供图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">针对外界关心的“未成年人是否能担任公司董事长”问题，记者联系到南宁市武鸣区市场监督管理局城厢市场监督管理所了解情况，</font><font cms-style=\"font-L strong-Bold color210\">该所一名工作人员证实，该公司法定代表人为17岁。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">“根据相关法规，16至18岁之间的人，如果要担任管理人员职务，必须提供证明材料，能够证明其具备完全民事行为能力，否则只能作为公司股东。”该工作人员介绍，通常这类证明材料会涉及劳动能力、收入状况、独立生活能力等。“</font><font cms-style=\"font-L strong-Bold color210\">从登记信息看，这家公司是真实存在的，应该是提交了证明材料并通过了注册登记申请。</font><font cms-style=\"font-L\">”</font></p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/107/w550h357/20250811/dba1-6dabadd25d4c9ae5fbe71ba6a13913e9.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">《中华人民共和国公司法》明确规定，公司高管应当具备完全民事行为能力。北京盈科（重庆）律师事务所聂莎律师指出：“虽然法律对年满16周岁未满18周岁的自然人设定了特定条件下可视为完全民事行为能力人的规定，</font><font cms-style=\"font-L strong-Bold color210\">但在实际操作中，这一群体担任公司法定代表人相对少见，相关证明文件的合法性与充分性是关键。</font><font cms-style=\"font-L\">”</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">（上游新闻）&nbsp;</font></font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/601/w550h851/20250811/6966-68916656f5b054203f6bd6100666bc3f.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/223/w550h473/20250811/14db-971d60f8f1cd43113b170f9b63a86401.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/107/w550h357/20250811/dba1-6dabadd25d4c9ae5fbe71ba6a13913e9.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4270, NULL, '没有结婚证不能领育儿补贴？深圳卫健委：有待明确', 0, 2, 194, '2025-08-11 15:31:07', '2025-08-11 14:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/283/w550h533/20250811/55d2-1c8532aa066ab43249d428d2cd7309a4.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwqz5910003.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　8月6日，有网友发文反映称，自己收到深圳卫生健康委短信告知，因其未办理结婚登记生育，不属于符合法律、法规规定生育子女，无法领取相关育儿补贴，相关贴文立即引起网友热议。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/283/w550h533/20250811/55d2-1c8532aa066ab43249d428d2cd7309a4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/142/w550h1192/20250811/3a54-46bda9d37e8c483697f02033a812b350.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n</div> \n<p cms-style=\"font-L\">　　该网友进一步表达了对上述回复的不解，因为根据《广东省人口与计划生育条例》和《广东省卫生健康委员会关于生育登记的管理办法》，明确了非婚生育可以办理生育登记。“我也是依法登记了的。我孩子都登记了，生孩子也用生育险了，也正常领生育津贴了，也就是说全流程认可了她的出生。”</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/441/w550h691/20250811/69d0-6d2348ad751705f5bcce740dd1921389.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　对此，深圳市卫健委工作人员回应表示，当前政策中“符合法律法规规定生育”的界定确实以夫妻关系为前提。</p> \n<p cms-style=\"font-L\">　　但工作人员同时强调，具体实施细则需等待广东省统一部署：“目前答复是依据现行法规作出的，但最终是否需要结婚证明，要以8月底上线的全省统一育儿补贴申报系统要求为准。”</p> \n<p cms-style=\"font-L\">　　7月30日的国新办新闻发布会上，国家卫生健康委人口家庭司司长王海东曾明确表示，育儿补贴申领只需提交证明婴幼儿身份和抚养关系的必要材料。目前全国统一的育儿补贴信息管理系统已完成建设，正处于全流程测试阶段。按照计划，各地将在8月下旬陆续开放申领通道，确保8月31日前全面实现补贴申领服务。</p> \n<p cms-style=\"font-L\">　　据了解，即将上线的申报系统将要求申请人提供婴幼儿出生医学证明、户口簿等基础材料，但具体是否包含婚姻证明尚未最终确定。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/283/w550h533/20250811/55d2-1c8532aa066ab43249d428d2cd7309a4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/142/w550h1192/20250811/3a54-46bda9d37e8c483697f02033a812b350.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/441/w550h691/20250811/69d0-6d2348ad751705f5bcce740dd1921389.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4271, NULL, '上海一驴友穿越秦岭失联十余天后获救 警方：他摔进峡谷腿受伤，凌晨被找到', 0, 1, 27, '2025-08-11 15:31:13', '2025-08-11 14:51:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/615/w550h865/20250811/4b14-c0b5c40416450eeff98468117b99135d.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwrc9736127.shtml', '红星新闻', '<p cms-style=\"font-L\">　　8月11日，红星新闻记者从西安市多个救援队及当地派出所了解到，一名来自上海的驴友在周至县附近的都督门处非法穿越秦岭腹地，随后失联十余天。红星新闻从辖区警方处获悉，目前该驴友已被救援队找到，具体的情况还需要下山之后才能获悉。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/615/w550h865/20250811/4b14-c0b5c40416450eeff98468117b99135d.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/505/w550h755/20250811/4cb0-11c92cca0ee160a1b40404006146040b.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲失联人员获救现场 受访者供图\">\n <span class=\"img_descr\">　　▲失联人员获救现场 受访者供图</span>\n</div> \n<p cms-style=\"font-L\">　　参与此次搜寻的一名救援队成员表示，7月31日，西安市的鄠邑区、周至区和宝鸡的太白县以及省森林公安第二分局等地的派出所接报该驴友失联，8月1日多支救援队收到请求后上山参与救援。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">救援队成员称该名</font>失联驴友最初是与人结伴，双方在网上认识后相约爬山，7月28日早晨三点左右，从秦岭的都督门点位开始登山。后另一名驴友因为体能问题和性格不合，中途提前下山，失联的驴友自己一人坚持上山后下落不明。</p> \n<p cms-style=\"font-L\">　　失联驴友的家属曾向救援队表示，其本身患有心脏病，担心家人上山时随身携带的药不多。“现在已经换了好几拨救援队以及当地村民在山上来回搜寻。”该救援队表示，由于鳌太线涉及区域面积广，几乎每天都有非法穿越的驴友。“人也很多，根本不可能全部管住。”另一名驴友告诉记者，当地多个救援部门已经联合开展搜救工作。</p> \n<p cms-style=\"font-L\">　　8月11日，红星新闻记者从辖区警方处获悉，当天中午刚收到救援队反馈的信息，称失联的这名上海<font cms-style=\"font-L\">驴友</font>已经找到，<font cms-style=\"font-L\">他登山的时候不慎摔进峡谷，腿受伤，救援队在今天凌晨把人找到。</font></p> \n<p cms-style=\"font-L\">　　11日下午1时左右，红星新闻记者从参与救援的队员中获悉，该失联驴友已成功获救，目前正在组织人员下山。</p> \n<p cms-style=\"font-L\">　　红星新闻记者 钟梦哲</p> \n<p cms-style=\"font-L\">　　编辑 包程立 责编 冯玲玲</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/615/w550h865/20250811/4b14-c0b5c40416450eeff98468117b99135d.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/505/w550h755/20250811/4cb0-11c92cca0ee160a1b40404006146040b.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4272, NULL, '俄退休老太为追回积蓄成乌方杀手 目标：俄军人员', 0, 4, 164, '2025-08-11 16:30:18', '2025-08-11 13:10:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/595/w912h483/20250811/0ed7-2fa6f02714e74082fd09c27b197b81eb.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwrc9726536.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，俄罗斯联邦安全局通报称，乌克兰特种部队官员冒充俄罗斯安全部队人员，利用欺骗和心理压力手段，<font cms-style=\"font-L strong-Bold\">招募了5名俄退休人员企图杀害俄军事人员</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/595/w912h483/20250811/0ed7-2fa6f02714e74082fd09c27b197b81eb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　通报称，根据乌克兰特种部队的计划，为了实施恐怖袭击，这些退休人员需要亲自将伪装成家居用品的简易爆炸装置交给莫斯科州的军事人员，<font cms-style=\"font-L strong-Bold\">这些简易爆炸装置被引爆后也会炸死袭击者</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/700/w960h540/20250811/eaee-04f1db8be9a92ee1e9e4efde5c3bc970.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　俄联邦安全局当日公布的视频显示，这些退休老年妇女被乌方收买后，被要求将伪装的爆炸装置交给军人。据悉，<font cms-style=\"font-L strong-Bold\">这些退休老人因被骗损失了银行积蓄，为取回钱，她们被要求监视俄军人的住所和停车场</font>，再按计划将伪装的爆炸装置交给军事人员。</p> \n<p cms-style=\"font-L\">　　俄联邦安全局称，2025年俄方阻止了110起恐怖袭击，摧毁了45个恐怖分子窝点，拘留了1000多名参与恐怖主义活动的人。由于缺乏培训和受到西方合作伙伴援助减少的影响，乌克兰特种部队在俄罗斯的特工网络正处于危机之中。乌安全局越来越多地在暗中组织破坏活动，被招募者会与目标人员一起被炸死。</p> \n<p cms-style=\"font-L\">　　对于俄方上述说法，乌克兰方面暂无回应。（总台记者 王新俊）</p> \n<p cms-style=\"font-L\">　　&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/595/w912h483/20250811/0ed7-2fa6f02714e74082fd09c27b197b81eb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/700/w960h540/20250811/eaee-04f1db8be9a92ee1e9e4efde5c3bc970.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4273, NULL, '中央巡视期间，栾风江被查', 0, 1, 29, '2025-08-11 16:30:26', '2025-08-11 16:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/53f0-80136d33cbe51ba3795fd40f17e042f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawz9658399.shtml', '新京报', '<p cms-style=\"font-L\">　　据青海省纪委监委8月11日消息：青海省国有资产监督管理委员会党委委员、副主任栾风江涉嫌严重违纪违法，目前正接受青海省纪委监委纪律审查和监察调查。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/53f0-80136d33cbe51ba3795fd40f17e042f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"栾风江（资料图）\" data-link=\"\">\n <span class=\"img_descr\">栾风江（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　据公开简历显示，栾风江，男，汉族，1968年9月生，中共党员，大学学历。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">他曾任：青海省</font><font cms-style=\"font-L\">海西州</font><font cms-style=\"font-L\">格尔木市副市长，海西州冷湖工委副书记、行委主任，海西州大柴旦工委书记，海西州发改委党组书记、主任，海西州副州长，青海省工信厅党组成员，青海省国资委党委委员、副主任等职。</font></p> \n<p cms-style=\"font-L\">　　今年6月消息，青海省委、省政府通报第三轮中央生态环境保护督察移交问题追责问责情况，因柴达木盆地盐湖资源开发无序扩张，加剧生态环境承载负担问题，<font cms-style=\"font-L strong-Bold\">栾风江被诫勉谈话。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">今年</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">中央第十一巡视组</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">进驻</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">青海省</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">，开展</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">2</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">个半月左右的巡视。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">中央巡视组将紧盯权力和责任，紧盯</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">“一把手”和领导班子，紧盯群众反映强烈的问题，着力查找政治偏差，推动解决突出问题。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">巡视期间设专门值班电话：</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">0971-3686677</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">，每天受理电话的时间为</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">8：00</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">至</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">18：00</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">；专门邮政信箱：青海省西宁市</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">A219</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">号邮政信箱。巡视组受理信访时间截止到</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">2025</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">年</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">9</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">23</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日。根据巡视工作条例规定，中央巡视组主要受理反映青海省级领导班子及其成员、下一级党组织领导班子主要负责人和重点岗位领导干部问题的来信来电来访，重点是关于违反政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律等方面的举报和反映。其他不属于巡视受理范围的信访问题，将按规定由青海省和有关部门认真处理。</font></font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/53f0-80136d33cbe51ba3795fd40f17e042f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4274, NULL, '陇南市纪委监委通报3起群众身边不正之风和腐败问题典型案例', 0, 2, 304, '2025-08-11 16:30:34', '2025-08-11 16:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawt0355540.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">1.礼县退役军人事务局原党组成员、副局长窦立群非法收受财物问题。</font>2019年至2022年，窦立群在担任礼县水政监察大队队长期间，利用职务便利，为他人在办理采砂许可、生产经营、水政监察执法、承揽工程等方面提供帮助，先后多次非法收受他人财物。窦立群还存在其他严重违纪违法问题，2025年5月被开除党籍、开除公职，涉嫌犯罪问题被移送检察机关依法审查起诉。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">2.徽县地方病防治办公室原主任高晓峰骗取地方病防治项目资金问题。</font>2016年至2021年，高晓峰在担任徽县地方病防治办公室主任期间，利用职务便利，安排并伙同他人通过虚增发放药品数量和检查次数等方式，骗取国家地方病防治项目资金。高晓峰还存在其他严重违纪违法问题，2025年6月被开除党籍、取消相应退休待遇，涉嫌犯罪问题被移送检察机关依法审查起诉。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">3.康县供销联社原党委委员、副主任冯涛非法收受财物问题。</font>2016年至2024年，冯涛在担任康县交通运输局路政办主任、第四现场办负责人期间，利用职务便利，为他人在乡村道路建设、工程款支付、工程增量变更等方面提供帮助，先后多次非法收受他人财物。冯涛还存在其他严重违纪违法问题，2025年6月被开除党籍、开除公职，涉嫌犯罪问题被移送检察机关依法审查起诉。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4275, NULL, '广东佛山，与蚊子缠斗的一个月', 0, 2, 197, '2025-08-11 16:30:39', '2025-08-11 15:59:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250811/2c86-dd8584f2038c32762148e6571c62b92b.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawz9660402.shtml', '新浪新闻综合', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">来源：北青深一度</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">记者/杨宝璐 &nbsp;实习记者/</font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">蒋文昕 温柠宁 周妍</font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250811/2c86-dd8584f2038c32762148e6571c62b92b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"居民小区里正在灭蚊消杀\" data-link=\"\">\n <span class=\"img_descr\">居民小区里正在灭蚊消杀</span>\n</div> \n<p>　　在经历了大半个月的消杀和密集宣传之后，长居广东的居民们已经可以熟练地描述“基孔肯雅热”这个拗口的传染病了——这种病主要通过雌性白纹伊蚊和埃及伊蚊传播，被叮咬后，有一到两天的潜伏期，之后发作时，会有高烧、关节疼痛等症状。而就在一个多月前，大家甚至连这个名字都念不准，“我们就把它叫做‘肯德基热’。”采访中，一位采访对象对深一度说。</p> \n<p>　　广东打响了一场灭蚊的攻坚战——这是一场格外艰难的战斗，防蚊工作的重点，在于清理蚊虫滋生的积水环境。因此志愿者们套上长袖长裤，一日三遍地入户清理水生植物的积水、上街清理积水垃圾。七八月的广东，暴雨与高温交替出现，志愿者们往往刚清理过一波积水，一场大雨降下，清理工作又要重新开始。</p> \n<p>　　据广东省疾控局8月3日通报，7月27日-8月2日，全省新增2892例基孔肯雅热病例，未报告重症和死亡病例。2025年8月8日，佛山市新增病例148例，已连续5天每日新增病例数降至200例以下。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/160/w550h410/20250811/fba9-71abc9edfab059a45df86fda421f2cbe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"佛山市掀起了一场全员灭蚊行动\" data-link=\"\">\n <span class=\"img_descr\">佛山市掀起了一场全员灭蚊行动</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\">囤购驱蚊水</font></font></font></font></font></font></font></font></font></font><font cms-style=\"font-L strong-Bold\"></font></p> \n<p cms-style=\"font-L\">　　孩子是最重要的。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">自打基孔肯雅热爆发后，李楠最担心的就是孩子。根据既往病人的病症，当基孔肯雅热病毒进入人体后，往往会潜伏几天才发作，初期往往会关节剧烈疼痛，之后患者会高烧，体温可达</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">39</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">℃，持续</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">1</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">至</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">天，并伴随出现红色斑丘疹。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">那是一种剧烈的胀痛感。深一度采访到的感染者阿龙称，他也不知道自己是什么时候“中招”的，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">29</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日，他只是右手手腕关节痛，当天下午，疼痛蔓延到多处关节，手腕、脚踝、膝盖都有明显痛感。当时他就觉得自己可能是感染了基孔肯雅热，但并没有在意。直到一天后，他高烧到了</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">39</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">℃，并起了皮疹。</font></font></p> \n<p cms-style=\"font-L\">　　直到这时，阿龙才意识到，自己得去医院了，到了医院一验血，结果为阳性。</p> \n<p cms-style=\"font-L\">　　“这个和登革热非常像，但登革热是肌肉痛为主，基孔肯雅热是关节痛。”广州市海珠区华洲街小洲社区卫生服务站社区科文医生向深一度介绍，基孔肯亚热的确诊，需要把血样送到每个区的疾控中心进行核酸检测，目前没有特效药，治疗以对症为主。除了缓解关节痛、肺热的西药，医生也会开抗病毒的中成药，对患者开展中西医结合治疗。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">住院期间，阿龙的体温始终在</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">37</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">℃到</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">38</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">℃之间徘徊，而关节痛和皮疹一直持续着，到第四五天，关节不痛了，除了脸部，他全身开始大面积地长疹子，痒到半夜都睡不着。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">从</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">29</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日关节痛开始，到</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">8</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">3</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日出院，阿龙的症状持续了六天。这种难受大人抵抗尚可，李楠的孩子才一岁多，刚刚会走，受不得这种苦。为了避免孩子中招，李楠囤了四五种驱蚊产品，还泡在网上研究比较各种产品，“哪个更好用，哪个对幼儿的伤害最小，哪个最有效。”</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">李楠告诉深一度，在广东，驱蚊产品是夏季必备。往常夏季登革热严重时，她也会囤很多驱蚊产品，但今年买的更贵。一瓶驱蚊液</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">119</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">块，预售七天才能发货，她下单了</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">4</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">瓶。除了这种驱蚊液，她还买了好几种驱蚊产品，“到货一批就下单一批”，现在她家里已经有十来瓶不同品牌的驱蚊产品了。每次出门，她都要在孩子的小推车上放上四五瓶。</font></font></p> \n<p cms-style=\"font-L\">　　因为疫情，在户外遛娃的父母少了很多，如果碰上小孩想出去，她会首选带孩子去商场。</p> \n<p cms-style=\"font-L\">　　每一次出门，母子俩都是全副武装。除了穿长袖长裤包裹住每一寸皮肤外，李楠还得先涂驱蚊乳液，再喷驱蚊水，再在衣服上贴驱蚊贴。电梯里有驱蚊水，每当坐电梯有人从她身边经过时，她还得喷一下。</p> \n<p cms-style=\"font-L\">　　“我看到网上（中招的）全是皮疹，我最害怕就是这样。咬到我，我就不能带娃，咬到宝宝，我会更加自责。”李楠说。</p> \n<p cms-style=\"font-L\">　　李楠家在佛山禅城区，小区每隔几天就会在公共区域进行一次消杀，“说实话，喷药后，不仅蚊子死了，我在地上还看到了不少蝉的尸体。它对人应该没有什么毒性，但在这种情况下我也不太确定了，可是也只有这种方法能够防护。”李楠很矛盾，最终她选择把孩子送回到广州的父母身边，那里疫情较轻。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/172/w550h422/20250811/ae2a-0ae740de64828e525693fe5fda0ac3f2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"工作人员对中学校园进行消杀\" data-link=\"\">\n <span class=\"img_descr\">工作人员对中学校园进行消杀</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\">回溯消杀</font></font></font></font></font></font></font></font></font></font><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"></font></font></p> \n<p cms-style=\"font-L\">　　李楠的担心并非没有道理。在阿龙住院那一周，疫情中心的佛山顺德区乐从镇，医院床位十分紧张，在乐从镇确诊后，他被安排转到二三十公里以外的广州中医药大学顺德医院附属勒流医院。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">佛山顺德区一位政府工作人员张磊告诉深一度，七月初，他接到上面通知的时候，顺德区已经有两千多例病例了。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">27</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日，广东省疾控局微信公众号通报，截至</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">26</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">24</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">时，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">2025</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">年全省累计报告</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">4824</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">例基孔肯雅热本地病例。</font></font></p> \n<p cms-style=\"font-L\">　　广东全省掀起了一场跟蚊子斗争的激战。打开社交平台，跟基孔肯雅热相关的视频，总是伴随着烟雾缭绕和消毒水喷洒的细节。在一些地区，采用了在某个时间段居民集体电蚊香、使用驱蚊液将蚊子驱赶至户外，再由消杀人员统一消杀的方式去灭蚊。</p> \n<p cms-style=\"font-L\">　　卫生站是城市医疗系统的“毛细血管”，在基孔肯雅热爆发后，他们担任着下发学习材料、组织医护人员到社区进行宣传活动、向社区居民普及防蚊知识等任务。社区科医务人员和居委会工作人员一起上门重点排查积水区域，灭蚊消毒，“这个工作的重点就是把那些有积水的地方都排查一下，我们医生要跟着街道的人一起去上门检查，每天都喷灭蚊水。”文医生称。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">2025</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">年</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">8</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">1</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日，佛山市要求零售药店对</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">47</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">种重点管控药品实施实名购买登记制度。以加强疫情防控。数名接受采访的广东医疗界人士告诉深一度，此举目的是为了更有效地隔离传染源，做到“早发现、早诊断、早治疗”，切断传播途径，保护易感人群。</font></font></font></p> \n<p cms-style=\"font-L\">　　“尽管基孔肯雅热不会人传人。但有些人得了病，他不去医院看，只去药房买相关的药。所以（这个措施）主要还是用来排查。”</p> \n<p cms-style=\"font-L\">　　每当发现病例后，疾控部门要追溯该患者去过哪些地方，再跟随其足迹，对他每一个去过的地方进行重点消杀。“蚊子是到处乱飞的，繁殖性和流动性都很强。确实很难进行彻底的消杀。但这样回溯消杀，也能起到一定的作用。”张磊说。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">据媒体报道，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">29</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日，全国基孔肯雅热疫情防治工作电视电话会议在北京召开，会议强调加强基孔肯雅热疫情风险研判，科学有效灭蚊防蚊避蚊，规范开展病例救治，全力防范重症和死亡病例等。据媒体报道，平安洛阳等地方政务媒体也发出公告，提醒当地居民做好相关防护。</font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/ab8b-a569c0d5aaf90fc98bfc0f6edbc1b6c2.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"清理楼顶平台的杂物积水 &nbsp;摄影&nbsp;| 王璐\" data-link=\"\">\n <span class=\"img_descr\">清理楼顶平台的杂物积水 &nbsp;摄影&nbsp;| 王璐</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\">消灭积水</font></font></font></font></font></font></font></font></font></font><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\">李楠把小孩送回家还有一个考虑，就是作为一名老师，她所在的学校组织老师们参与</font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">协助入户，排查潜在的积水隐患。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">25</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">号，她开始了自己的志愿者生涯，上午</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">9</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">点，李楠和同事们在石湾街道的指定社区集合，“整个社区人头攒动，一股花露水的味道。”李楠说，在培训了一些入户的话术和技巧后，她领了一个袋子，一瓶杀虫剂，一支紫光手电筒，跟另一位已经入户过的老师同行入户。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">那天，她一共扫了</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">4</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">栋楼，每栋十层，每层</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">4</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">户。广东夏季炎热，衣服能拧出水来，但志愿者们没人敢裸露身体任何皮肤。</font></font></p> \n<p cms-style=\"font-L\">　　李楠称，入户要从天台往下扫，因为天台就是蚊虫最集中的孳生地之一。</p> \n<p cms-style=\"font-L\">　　“有些人喜欢在天台种菜，他们使用很多泡沫箱，箱子里积了水，水又臭。种菜需要施肥。有的人会用有机化合肥，有的人真的会用农家肥，那简直就是蚊虫的最爱。”她说，而他们这些志愿者，就负责清理泡沫箱的积水，再下楼去通知住户不能这样做。</p> \n<p cms-style=\"font-L\">　　“我当天做的大多数住户挺配合的，他们会觉得我们说的对。”李楠回忆。</p> \n<p cms-style=\"font-L\">　　也有不配合的住户。她记得有个三十多岁的住户，志愿者敲门时，对方就说，已经有人来过了。“我说我们会不断地来做宣传，看看大家有什么需要，她就说你别进来，我更怕你把蚊子带进来。你在门口说完就行了。”</p> \n<p cms-style=\"font-L\">　　“有一些就直接不给开门，说我家里很干净，也没有养这些水生植物，也没有蚊子，你们也不用过来了。”张磊说，“如果你家一天到晚被陌生人进来三次，一盆花被他们倒掉三次水再重新装水，是个人都会烦。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">他所在的村有</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">11</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">个生产小组，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">1000</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">户左右。工作人员分为三到四组，现在每天基本上入户三四十户左右。他已经连续加了三个周末的班了，目前，持续的入户检查和倾倒积水工作还要持续一段时间。</font></font></p> \n<p cms-style=\"font-L\">　　防蚊物资在这个夏天也是紧俏货。张磊告诉深一度，村里、镇上没那么多资金统一购买防蚊用品，当地的一些企业和热心人士，以及村里各生产小组会筹钱买蚊香，派发给居民。</p> \n<p cms-style=\"font-L\">　　入户还有一项重点，就是排查。志愿者们带着表格去登记，家里没有积水、没有水生植物、没有人感染，叫做“安全户”，“安全户我们是尽量不去打扰的。”李楠介绍，倘若某一家有特别大的阳台，则是“重点户”，“不是那种室内阳台，是户外大平层阳台。第一就是积水，积水特别多。第二就是养植物，这也是我们需要重点关注的。”她介绍。</p> \n<p cms-style=\"font-L\">　　排查工作的重点，就是水生植物，如富贵竹、水仙等。此类植物就可能意味着会有长蚊虫。碰上这种，她们就去喷一些驱蚊液。社区还会给志愿者发紫外线手电筒，一照植物，就能看到上面有没有虫卵，“怕的就是那种虫卵和蛆的混合物。”</p> \n<p cms-style=\"font-L\">　　还有一些住户养乌龟，“我们最怕的是那些龟盆，其实我们不怕鱼池，因为鱼它会吃虫卵。但乌龟不吃虫卵，而且乌龟又需要水，最容易滋生蚊虫。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/ea56-d5f7f4426cfee8009f8ce6347ac94545.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"重点清理暴雨后的积水、垃圾和卫生死角\" data-link=\"\">\n <span class=\"img_descr\">重点清理暴雨后的积水、垃圾和卫生死角</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\"><font cms-style=\"font-L strong-Bold color0\">跟暴雨反复“交战”</font></font></font></font></font></font></font></font></font></font><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"></font></font></p> \n<p cms-style=\"font-L\">　　除了在居民区入户，志愿者们还要在街道上进行清理，无论是卫生死角还是杂草、垃圾堆放的地方，都不能放过。“现在整个行动已经不单单是灭蚊了。也结合了部分的人居环境的整治。”张磊介绍。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">街头到处张贴着“禅城灭蚊队”的卡通海报，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">LED</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">屏也在循环滚动着灭蚊的宣传片，用普通话、粤语和英文反复提醒灭蚊要点，被当地居民笑称为“赛博蚊香”。初看到海报时，李楠的丈夫还以为上了新电影，她的儿子还以为是动画片的宣传海报。“结果是灭蚊的宣传海报，我就觉得佛山人真挺松弛的。”</font></font></p> \n<p cms-style=\"font-L\">　　但广东连日阴雨，还是给灭蚊工作带来很大困扰。李楠称，除了入户，老师们还要分批回学校清理积水。她所工作的校园很大，植物茂盛，风雨一过，满地花果。老师们只得把这些花果清扫干净。但刚清扫完，一阵雨来，又是满地积水。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">“但还是得这么干，如果等到天晴再来清理，可能蚊子已经飞出去了。”伊蚊繁殖能力很强，仅需一点点积水，就能繁殖后代，且一次产卵可上百颗，从卵到成虫仅需</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">10</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">到</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">15</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">天。为了跟蚊子“抢时间”，老师们不得不在雨停的第一时间，就出来“返工”。</font></font></p> \n<p cms-style=\"font-L\">　　“我们很多时候工作就是不断地重复，说实话也挺累的。”李楠最担心的，就是做了这么多事，都是“无用功”——刚清理完积水，又下雨，下完雨出太阳后，水汽蒸腾，老师们穿着长袖长裤、喷点花露水再去清理积水。闷热的气温让李楠呼吸不畅，给她一种湿漉漉的、又呛又黏腻的感觉。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“只能说天公不作美。”李楠说，“其实反复做清理也没关系，怕的是做了以后还是有蚊子。”</font></font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">尽管灭蚊紧张，但</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">8</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">2</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">号，李楠还是去南海体育馆看了一场演唱会。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">演唱会在晚上举行，入场时，李楠看见桌上放了一些防蚊喷雾，供现场观众使用，当天，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">4000</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">人左右的场馆几乎坐满，场馆里满是花露水的味道，大家都在炎热的夏夜穿着长袖长裤，“把前几十年的花露水全喷完了。”李楠称。</font></font></p> \n<p cms-style=\"font-L\">　　保证了小孩的安全之后，李楠难得轻松下来，她跟先生一起去了演唱会现场。“现场挺热烈的，大家都挺高兴，也很松弛。在这里，基孔肯雅热变成了一个梗，观众们还跟歌手开玩笑，让他们脱衣服，脱了又说有蚊子。”李楠说。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">晚上</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">10</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">点，演唱会结束，现场观众“高高兴兴地去，高高兴兴地回”，这个夜晚和之前任何一个夏夜并没有什么区别。</font></font></p> \n<p cms-style=\"font-L\">　　（应受访者要求，文中李楠、张磊为化名）</p> \n<p cms-style=\"font-L\">　　　</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">广东发现基孔肯雅热</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250811/2c86-dd8584f2038c32762148e6571c62b92b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/160/w550h410/20250811/fba9-71abc9edfab059a45df86fda421f2cbe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/172/w550h422/20250811/ae2a-0ae740de64828e525693fe5fda0ac3f2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/ab8b-a569c0d5aaf90fc98bfc0f6edbc1b6c2.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/ea56-d5f7f4426cfee8009f8ce6347ac94545.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4276, NULL, '江苏淮安被指有超规格豪华公墓，民政局：正推进整改和处罚，部分已拆除', 0, 2, 78, '2025-08-11 16:30:44', '2025-08-11 15:56:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/cb41-db3d4c1b1f1c02577cc3c50e3a32d33e.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkraww8735704.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　近日，有网友向澎湃新闻反映，江苏淮安福寿花园公墓存在超规格“豪华”墓地，“最大的占地超过20平方米”。对此，淮安市民政局相关负责人8月8日回应澎湃新闻（www.thepaper.cn）称：“目前没有安葬的超规定面积‘豪华’墓穴已经全部拆除，其他的超规定面积墓穴正在分类推进整改。”</p> \n<p cms-style=\"font-L\">　　该负责人说，目前已经落实全面封存管理措施，停止违规建设，停止销售墓穴，相关<font cms-style=\"font-L strong-Bold\">行政处罚还在处置流程中，“案子还没结”</font>。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/cb41-db3d4c1b1f1c02577cc3c50e3a32d33e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"2025年3月31日拍摄的淮安福寿花园公墓内的疑似超规格墓地。读者 供图\" data-link=\"\">\n <span class=\"img_descr\">2025年3月31日拍摄的淮安福寿花园公墓内的疑似超规格墓地。读者 供图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">被封存的淮安福寿花园公墓</font></p> \n<p cms-style=\"font-L\">　　公开信息显示，淮安市福寿花园公墓位于淮安市清江浦区武墩镇。</p> \n<p cms-style=\"font-L\">　　据淮安日报社微信公众号“淮海晚报”2023年3月20日报道，福寿花园公墓系南方长松建设有限公司租用淮安市城市资产经营有限公司土地建设并经营，双方的土地租赁合同已经于2022年11月30日到期并不再续签，“自2022年12月1日起，福寿花园公墓由市城市资产经营有限公司看管、封存并停止一切建设、经营活动。在此，郑重提醒广大市民不要再购买墓地，否则所有责任均由购墓人承担。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/07ee-7eccbb750b3b808113fc1b44858bbe93.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"2025‎年‎3‎月‎31‎日拍摄的福寿花园公墓内尚未销售的疑似超规格墓地。读者 供图\" data-link=\"\">\n <span class=\"img_descr\">2025‎年‎3‎月‎31‎日拍摄的福寿花园公墓内尚未销售的疑似超规格墓地。读者 供图</span>\n</div> \n<p cms-style=\"font-L\">　　2013年1月1日起施行的《殡葬管理条例》第十九条规定，墓穴占地面积超过省、自治区、直辖市人民政府规定的标准的，由民政部门责令限期改正，没收违法所得，可以<font cms-style=\"font-L strong-Bold\">并处违法所得1倍以上3倍以下的罚款</font>。</p> \n<p cms-style=\"font-L\">　　民政部网站2018年9月7日公布的《殡葬管理条例（修订草案征求意见稿）》显示，条例拟规定安葬骨灰的独立墓位占地面积不得超过0.5平方米，合葬墓位的占地面积不得超过0.8平方米。安葬遗体的墓位（含合葬墓位），占地面积不得超过4平方米。墓碑高度不得超过地面0.8米。</p> \n<p cms-style=\"font-L\">　　2023年4月1日起施行的《江苏省公墓管理办法》第十条规定，“独立墓位占地面积<font cms-style=\"font-L strong-Bold\">不得超过0.5平方米</font>，合葬墓位占地面积<font cms-style=\"font-L strong-Bold\">不超过0.8平方米</font>。”“公益性公墓应当使用卧式墓碑。倡导经营性公墓使用卧式墓碑；经营性公墓使用竖式墓碑的，<font cms-style=\"font-L strong-Bold\">最高不得超出地面一米</font>。”</p> \n<p cms-style=\"font-L\">　　2025年4月23日，民政部官网公布的最新的《殡葬管理条例（修订草案征求意见稿）》称，“县级以上地方人民政府民政部门应当严格限制公墓墓位占地面积和墓碑高度，公墓管理的具体办法由国务院民政部门制定。安葬骨灰的单体墓位、合葬墓位的占地面积分别不得超过0.5平方米、0.8平方米；安葬遗体的单体墓位、合葬墓位的占地面积分别不得超过4平方米、6平方米。墓碑高度不得超过地面0.8米。”</p> \n<p cms-style=\"font-L\">　　早在2008年12月26日印发的《民政部、国家发展和改革委员会、公安部、国土资源部、环境保护部、住房城乡建设部、国家工商总局、国家林业局关于进一步规范和加强公墓建设管理的通知》称，清理公墓违规经营行为。禁止建设、出售（租）超规定面积墓穴、墓地。公墓经营单位要严格按照国家规定的墓穴用地标准建设、出售（租）墓葬用地。公墓经营单位建设、出售（租）超规定面积墓穴、墓地的，依照《殡葬管理条例》的规定，由民政部门责令限期改正，没收违法所得，可以并处罚款。对尚未建成或已经建成、尚未出售（租）的，要依法拆除或限期改造；已经出售（租）并与丧户签订协议但尚未安葬骨灰的，也要依法拆除或限期改造，公墓经营单位应向丧户说明情况，协商变更或解除安葬协议，依协议承担有关法律责任；已经安葬骨灰的，要加强管理，待使用期满后依法处理。上述拆除或改造墓穴、墓地所发生的费用或赔偿责任由公墓经营单位承担。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">曾被民政局现场督查</font></p> \n<p cms-style=\"font-L\">　　2025年8月8日，澎湃新闻记者以公墓购买人的身份向淮安一名墓地中介人员，咨询福寿花园公墓的销售情况。该中介答复，福寿花园公墓近两个月已经停止销售，“福寿花园停（卖）了两个多月，什么时候再卖要等通知。”</p> \n<p cms-style=\"font-L\">　　对于能否购买邻近墓穴并连成一块大墓的想法，该中介称：“它（墓穴）没卖的话可以连在一起，关键现在不给卖。”</p> \n<p cms-style=\"font-L\">　　早在2019年，福寿花园公墓就曾因违规建设和销售超标准豪华大墓等问题，受到淮安相关部门的关注。</p> \n<p cms-style=\"font-L\">　　据淮安市民政局微信公众号“淮安市民政局”2019年6月1日发布的文章，时任淮安市民政局党组成员、时任副局长龚建新曾带队前往福寿花园公墓开展殡葬领域扫黑除恶专项斗争现场督查。该文章称，针对福寿花园存在的违规建设和销售超标准豪华大墓等问题，龚建新要求，福寿花园公墓立即停止建设和销售墓穴，立即整改违规建设的超标准豪华大墓，并将今年以来的违规销售情况统计报送市殡葬管理所。</p> \n<p cms-style=\"font-L\">　　据淮安市清江浦区民政局2020年7月23日发布的《对区政协一届四次会议401号提案的答复》，其中提到，镇（街道）存在“擅自将公墓对外承包，同时对超面积建设墓穴，高价销售，私自扩大面积，公益性公墓性质转变等问题缺乏监管”的问题。此外《答复》还提到：“我区公墓均未执行政府定价，除了个别五保户购墓价格以外，全部违规高价销售，近两年最低价格均在2万左右、最高达到15万。”</p> \n<p cms-style=\"font-L\">　　2025年7月8日，淮安市清江浦区民政局曾发布《关于开展福寿花园公墓墓位信息登记的公告》，其中提到，“因福寿花园公墓（位于淮安市清江浦区武墩街道境内）管理主体变动，为进一步规范公墓管理，做好后续服务工作，现集中时间对福寿花园公墓墓位开展信息登记”，登记范围包括福寿花园公墓内所有已安葬和已购买未使用的墓位。8月1日，淮安市清江浦区民政局再次发布公告，要求公墓购买者登记“已购买未使用墓位信息”。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/cb41-db3d4c1b1f1c02577cc3c50e3a32d33e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/07ee-7eccbb750b3b808113fc1b44858bbe93.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4277, NULL, '《杭州市促进具身智能机器人产业发展条例（草案）》公开征求意见', 0, 2, 84, '2025-08-11 16:30:49', '2025-08-11 15:46:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawz9645326.shtml', '界面', '<p cms-style=\"font-L\">　　8月11日消息，杭州市司法局发布公开征求《杭州市促进具身智能机器人产业发展条例（草案）》意见的公告，将具身智能机器人产业纳入全市政策支持框架，通过制度设计增强政策合力，进一步规范产业高质量发展路径。其中指出，面对当前研发训练需求和未来具身智能机器人的广泛应用需求，要求加强网络和算力基础设施规划布局，建立多元多元智算供给服务体系，提升算力资源利用效率，降低算力使用成本。明确核心技术主攻方向，聚焦具身智能“大脑”（具身智能大模型）、“小脑”（运动控制系统）及“本体”（机器人核心部件和整机）三大核心以及专用芯片等“卡脖子”环节。打造技术攻关平台，支持重大科技基础设施、重点实验室等具身智能机器人相关研发平台建设和运营，鼓励科研设施与仪器面向企业开放。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4278, NULL, '河北终止防汛Ⅳ级应急响应', 0, 1, 3, '2025-08-11 16:30:59', '2025-08-11 15:26:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwrc9769611.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">　央视网消息</font>：据“河北省应急管理”微信公众号消息，据河北省防汛抗旱指挥部消息，根据当前雨情水情形势，经会商研判，河北省防指决定于8月11日16时起，对廊坊市、雄安新区终止防汛Ⅳ级应急响应。</p>\n<p cms-style=\"font-L\">　　目前河北省仍处于汛期，省防指要求，各地各有关部门要继续密切监视雨水情变化，加强会商研判，及时发布预警信息，落实临灾预警“叫应”机制，强化山洪地质灾害防御，做好行洪河道巡查防守，提前转移受洪水威胁群众，确保安全度汛。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4279, NULL, '上海民警猥亵继女案一审宣判，男子因猥亵儿童、强制猥亵罪被判8年有期徒刑，生母：将申请刑事抗诉', 0, 1, 9, '2025-08-11 16:31:05', '2025-08-11 15:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/534/w550h784/20250811/4242-5836a29d32434bdb8ff16a285aedd2b7.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawx5834938.shtml', '新浪新闻综合', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">来</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">源 |</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">&nbsp;潇湘晨报</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">记者</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">&nbsp;|</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">&nbsp;吴陈幸子</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">8月11日下午，上海民警刘某涛猥亵继女案一审在虹口区人民法院宣判。潇湘晨报记者从家属处获悉，刘某涛一审获刑8年。对于该判决结果，当事人和母亲李女士表示将申请刑事抗诉。此前，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">李女士曾表示希望能对嫌疑人顶格处罚。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">8月7日，李女士曾告诉潇湘晨报记者，一直坚持维权后，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">梅子状态已好转很多，“开完庭后我们交流，她说自己感觉心里放下了很多，有安全感很多。”</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">李女士曾称，自己</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">愿意接受一切指责，是自己没有给女儿足够的安全感和保护空间。</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">此事多年来持续对梅子造成精神伤害，一审庭审时，她本担心梅子若出庭能否承受住，“她一提就哭，我觉得对她太残忍。”但梅子最后选择出庭直面，“我这么多年遭受的伤害，遭受的屈辱，他一直用各种方式恐吓我，我现在就想到庭上看看，到底法律会怎么审判他。”</font></font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/534/w550h784/20250811/4242-5836a29d32434bdb8ff16a285aedd2b7.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　潇湘晨报此前报道，2024年11月28日下午，上海民警刘某涛猥亵继女案一审在虹口区人民法院开庭。检察院以刘某涛涉嫌猥亵儿童罪、强制猥亵罪提起公诉。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">虹口区检察院出具的起诉书显示，经依法审查查明，2010年至2012年期间，刘某涛对未满14周岁的梅子</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">（化名）</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">实施蹭、摸下体等猥亵行为，存在猥亵儿童犯罪事实。2015年8月、2018年11月、2021年3月，刘某涛多次对梅子进行猥亵行为，存在强制猥亵犯罪事实。上述事实有被害人梅子及多名证人的证言，还有刘某涛自书承诺书等证据证实。</font></font></font></p> \n<p cms-style=\"font-L\">　　母亲李女士曾告诉潇湘晨报记者，早在梅子五年级时，自己其实就从梅子口中听说被继父猥亵一事。自己起初难以相信，担心是误会，为保护女儿将其送至前夫家照顾。</p> \n<p cms-style=\"font-L\">　　然而在2015年，满14周岁的女儿来过暑假时，刘某涛再次对其进行猥亵。李女士发现后和刘某涛当面对峙，“他又是跪，又是求，又是哭。女儿也跪下来求我。我错的就是，女儿跪下来没有多问一句。直到今年（2024年）年初，女儿才告诉我当时受到他的恐吓，如果我报警他就会杀了她和我。”</p> \n<p cms-style=\"font-L\">　　2023年12月，李女士发现刘某涛拿走自己保险柜里的黄金首饰，梅子在现场维护母亲，“女儿当时就骂他畜生了，这么多年对她造成的伤害，他不感觉到愧疚，如今还欺负妈妈。刘某涛直接冲过来把我女儿摁在地上，说我今天就当着你的面强奸你，又怎么样？”梅子和李女士当即清醒，忍耐没有用处。她们前往派出所报警。2024年1月29日，上海市公安局虹口分局对李女士女儿报被猥亵一案立案。</p> \n<p cms-style=\"font-L\">　　　</p> \n<p cms-style=\"font-L\">　　<strong>相关新闻</strong></p> \n<p cms-style=\"font-L\">　　<strong>民警涉嫌猥亵继女案开庭，被害人坚持出庭：希望给自己前半生一个交代（红星新闻 2024年11月28日）</strong></p> \n<p cms-style=\"font-L\">　　11月28日，上海民警刘某涛涉嫌猥亵继女案在上海市虹口区人民法院一审开庭。红星新闻记者从受害人梅子（化名）母亲李女士处获悉，梅子主动出庭，“她希望能给自己的前半生一个交代。”</p> \n<p cms-style=\"font-L\">　　据新黄河报道，李女士反映，她的前夫刘某涛是上海市公安局城市轨道和公交总队的一名民警，二人曾是再婚夫妇。李女士带着女儿离婚后，与刘某涛同居，后登记结婚，刘某涛曾多次猥亵李女士女儿黄某某。今年1月29日，上海市公安局虹口分局对李女士女儿黄某某被猥亵一案进行立案调查。</p> \n<p cms-style=\"font-L\">　　上海市公安局城市轨道和公交总队一名负责人曾称，“目前该单位已经对刘某涛宣布停止一切职务，将公安相关证件全部上缴，该案件属于刑事案件，只要刑事案件有结果了，肯定会对刘某涛进行处理，会给当事人一个公正的说法。”</p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">涉嫌猥亵儿童罪、强制猥亵罪</font></p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">证据包含承诺书、多名证人证言</font></p> \n<p cms-style=\"font-L\">　　红星新闻记者获悉，刘某涛被控猥亵儿童罪、强制猥亵罪。就猥亵儿童犯罪事实，上海市虹口区人民检察院在起诉书中提出，2010年至2012年，刘某涛多次对被害人实施猥亵行为，被害人未满14周岁；就强制猥亵犯罪事实，检察院提出，2015年、2018年、2021年，刘某涛有三次对被害人猥亵的行为。</p> \n<p cms-style=\"font-L\">　　被指控的犯罪事实均发生于同一地点。李女士告诉记者，事发地即为自己与刘某涛的共同居所。她回忆，在2010年前后，梅子小学五年级时，梅子曾清楚地表达过自己被刘某涛猥亵，而后，她将女儿送至生父处居住。2015年，女儿在假期再次来到李女士处，女儿告知李女士，自己再次被猥亵，李女士希望报警，“刘某涛跪下来求我，他写下了承诺书。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20241128/384/w1704h1080/20241128/044f-300580422805fa4ac4a402e06ffcb61d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲刘某涛手写承诺书\">\n <span class=\"img_descr\">▲刘某涛手写承诺书</span>\n</div> \n<p cms-style=\"font-L\">　　李女士提供的刘某涛手写承诺书显示，其中包含“我刘某涛在与李女士这段婚姻关系中多次犯下重大过错，给李女士身体与精神上造成不可逆的伤害（婚姻存续期间曾与多名女子发生无数次性关系，最不可饶恕的是2015年8月16日早上跑到房间对继女猥亵，这让李女士不肯再原谅我）”。</p> \n<p cms-style=\"font-L\">　　李女士称，2018年，女儿回家取衣服，又一次遭到刘某涛猥亵。她注意到女儿神色不对，获悉情况后，她的朋友介入协调，要求刘某涛不再有此类行为。2021年，考虑到女儿工作通勤问题，李女士建议女儿与自己居住，但一次做饭时，她曾听到女儿尖叫，注意到刘某涛从女儿房间走出。</p> \n<p cms-style=\"font-L\">　　2023年年底，李女士与刘某涛发生争吵，女儿介入时提到：“你（刘某涛）对我这么多年造成的伤害，我都没找过你。你现在又开始欺负我妈妈。”李女士回忆，刘某涛彼时将女儿摁在地上，称“今天我就当着你妈的面强奸你”。李女士与女儿逃出家门后，去派出所报警。</p> \n<p cms-style=\"font-L\">　　就犯罪事实，检察院提出，有被害人陈述、四人证言、刘某涛自书承诺书等证据证实。李女士介绍，提供证言的证人中，包括女儿梅子的同学，自己的朋友等人，“2018年，女儿曾经和朋友谈论起被猥亵的事。当时曾介入协调的朋友也作证了。”</p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">被害人主动出庭</font></p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">希望“给自己前半生一个交代”</font></p> \n<p cms-style=\"font-L\">　　李女士告诉记者，女儿梅子主动出庭，“我希望她不要去，但她自己坚持出庭。她认为刘某涛对自己造成了伤害，她要给自己前半生一个交代。她是一个善良、勇敢的人。”</p> \n<p cms-style=\"font-L\">　　今年7月前后，李女士曾与女儿长谈，“当时我问她为什么这次坚持报警，她说是为了保护母亲，而后一直哭泣。”李女士回忆，那时，母女两人一同休息，她才注意到，女儿在睡觉时必须开灯。在长谈时，梅子告诉李女士，自己曾长期被刘某涛恐吓，称如果报警将对母女俩施暴。</p> \n<p cms-style=\"font-L\">　　2023年底，李女士就梅子被猥亵情况第一次报警。今年1月29日，上海市公安局虹口分局对李女士女儿黄某某被猥亵一案进行立案调查。李女士称，此前未报警，经历过自己对事情半信半疑、希望刘某涛能“改正”、担忧孩子的名声和就业前途等心路历程，“但现在我知道，我们的忍让是在纵容犯罪行为。我希望能给其他类似家庭一个提醒。”</p> \n<p cms-style=\"font-L\">　　在将近一年的维权时间内，李女士总结，家庭内部性侵案具有隐秘和长期性，由于性侵者同时也是抚育者，被害人可能会通过遗忘、否认等方式保护自己，担忧自己是问题的来源、把经历说出来会造成家庭解体，而被害人精神状态不稳定，可能会难以搜集证据，造成取证困难。“许多的父母也面临着家庭社会多方面的压力，未必能够全心全意的支持受害者当事人维护自身权益，需要专业机构及时介入。 ”</p> \n<p cms-style=\"font-L\">　　李女士认为，作为孩子的家长，应该给予孩子更多关注，可以关注孩子是否出现睡眠不佳、恐惧的情况，人际交往是否受限，并应与孩子进行交流，对孩子进行性普及教育。孩子遭到猥亵后，需要关注孩子的心理创伤，越早介入关注越好，也应该使用法律武器，阻止孩子被侵害。</p> \n<p cms-style=\"font-L\">　　红星新闻记者 陈馨懿</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/534/w550h784/20250811/4242-5836a29d32434bdb8ff16a285aedd2b7.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20241128/384/w1704h1080/20241128/044f-300580422805fa4ac4a402e06ffcb61d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4280, NULL, '兰州大学科研团队调研榆中山洪受灾区：洪水携带森林漂木加重灾害破坏性', 0, 1, 28, '2025-08-11 16:31:21', '2025-08-11 14:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwqv0414486.shtml', '新京报', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　[兰州大学科研团队调研榆中山洪受灾区：洪水携带森林漂木加重灾害破坏性]8月11日，兰州大学发布消息，科研团队调研甘肃榆中山洪灾害受灾区。8月7日以来，甘肃兰州市榆中县等地遭遇连续强降雨引发山洪灾害。兰州大学地质科学与矿产资源学院利用无人机航测等技术调研受灾区，初查发现，马莲滩村正位于沟口位置，属于径流最大的地段，该流域上游地形陡峭，沟道内坡积层和松散物质丰富，排洪道过流能力不足，本次短历时强降雨致沟道汇水急剧增加，特别是洪水携带下的上游森林漂木和固体物质加重了本次灾害的破坏性。</p> \n<!--WeiboOriginalContent[{\"text\": \"【#兰州大学科研团队调研榆中山洪受灾区#：洪水携带森林漂木加重灾害破坏性】8月11日，兰州大学发布消息，科研团队调研甘肃榆中山洪灾害受灾区。8月7日以来，甘肃兰州市榆中县等地遭遇连续强降雨引发山洪灾害。兰州大学地质科学与矿产资源学院利用无人机航测等技术调研受灾区，初查发现，马莲滩村正位于沟口位置，属于径流最大的地段，该流域上游地形陡峭，沟道内坡积层和松散物质丰富，排洪道过流能力不足，本次短历时强降雨致沟道汇水急剧增加，特别是洪水携带下的上游森林漂木和固体物质加重了本次灾害的破坏性。 http://t.cn/A6s5aBoj\"}]WeiboOriginalContent--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754644472\" target=\"_blank\">甘肃榆中发生山洪灾害</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4281, NULL, '记者：佳夫今天接受纽卡体检，转会费3000万镑固定+430万镑浮动', 0, 4, 206, '2025-08-11 17:30:17', '2025-08-11 16:52:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/7048-62157feca787bb0ed2cdd5c47b8487ff.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkraww8780327.shtml', '直播吧', '<p cms-style=\"font-L \">　　来源：直播吧</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/7048-62157feca787bb0ed2cdd5c47b8487ff.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　直播吧8月11日讯 <font cms-style=\"font-L\">据天空体育记者Keith Downie消息，米兰24岁后卫佳夫今天接受纽卡体检。</font></p> \n<p cms-style=\"font-L\">　　在个人社媒，记者Keith Downie写道：佳夫今天在接受纽卡的体检，他将以3000万镑固定+430万镑浮动的价格从米兰加盟纽卡。</p> \n<p cms-style=\"font-L\">　　佳夫已于昨晚飞往纽卡斯尔，并将在接下来24小时完成转会手续，他有希望明天与球队一起训练，备战周六与维拉的英超首轮。</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/7048-62157feca787bb0ed2cdd5c47b8487ff.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4282, NULL, '防城港市委原常委、秘书长杨亚俊严重违纪违法被开除党籍和公职', 0, 2, 218, '2025-08-11 17:30:41', '2025-08-11 17:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawt0382467.shtml', '广西省纪委监委网站', '来源：广西纪检监察网\n<br>\n<br>\n<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　经自治区党委批准，自治区纪委监委对防城港市委原常委、秘书长杨亚俊严重违纪违法问题进行了立案审查调查。</p>\n<p cms-style=\"font-L\">　　经查，杨亚俊丧失理想信念，背弃初心使命，对党不忠诚不老实，对抗组织审查，毫无党性原则，搞迷信活动；无视中央八项规定精神，收受可能影响公正执行公务的礼品礼金，接受可能影响公正执行公务的宴请；违反组织原则，在组织谈话时不如实向组织说明问题，在干部选拔任用中为他人谋利并收受财物；廉洁底线失守，搞权色交易，道德败坏；毫无纪法底线，将公权力异化为谋取私利的工具，利用职务便利侵吞公共财物，大搞权钱交易，在项目承揽、人事调动等方面为他人谋利，并非法收受巨额财物。</p>\n<p cms-style=\"font-L\">　　杨亚俊严重违反党的政治纪律、组织纪律、廉洁纪律、生活纪律，构成严重职务违法并涉嫌贪污罪、受贿罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予严肃处理。依据《中国共产党纪律处分条例》《中华人民共和国监察法》《中华人民共和国公职人员政务处分法》等有关规定，经自治区纪委常委会会议研究并报自治区党委批准，决定给予杨亚俊开除党籍处分；由自治区监委给予其开除公职处分；终止其自治区第十二次党代会代表资格；收缴其违纪违法所得；将其涉嫌犯罪问题移送检察机关依法审查起诉；所涉财物一并移送。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4283, NULL, '内蒙古“婚内强奸案”起诉书曝光：案发前两人已提交离婚申请，妻子被鉴定为轻伤一级', 0, 1, 5, '2025-08-11 17:30:48', '2025-08-11 16:44:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/8/w550h258/20250811/ee4e-2541125bf6ed3ce52512b10c62c18e46.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawx5847866.shtml', '大河报·豫视频', '<p cms-style=\"font-L\">　　来源：大河报·豫视频</p> \n<p cms-style=\"font-L\">　　记者 杜倩雯 陈甜甜</p> \n<p cms-style=\"font-L\">　　一段录音笔的内容，成为一对婚姻存续十五年的夫妻俩走上法庭的导火索。</p> \n<p cms-style=\"font-L\">　　近日，内蒙古额尔古纳市“男子殴打妻子后发生性关系被告强奸”一事引发热议。男子刘军（化名）因听到录音笔中妻子与其他男子的通话内容怀疑妻子出轨，之后妻子报警称遭丈夫家暴、强奸。此案将于8月12日上午在额尔古纳市人民法院开庭审理，届时，刘军姐姐刘琳（化名）将出庭为弟弟辩护。记者从知情人处获取的起诉书上看到，检察院认为被告人刘军违背被害人王可（化名）意愿，使用暴力手段强行与被害人王可发生性关系，应当以强奸罪追究其刑事责任。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/8/w550h258/20250811/ee4e-2541125bf6ed3ce52512b10c62c18e46.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"起诉书部分内容\">\n <span class=\"img_descr\">起诉书部分内容</span>\n</div> \n<p cms-style=\"font-L\">　　<strong>案发前两人已提交离婚申请</strong></p> \n<p cms-style=\"font-L\">　　3月22日上午，刘琳接到弟弟刘军的电话，让其前去家里拿走一些不用的东西，这时她才知道，弟弟、弟媳前一日发生了矛盾。</p> \n<p cms-style=\"font-L\">　　在涉事房屋，弟弟刘军告诉姐姐，他放在卧室里的录音笔，录到王可和另一个男子贬低他的话，他怀疑王可出轨了。刘琳感到震惊和气愤，她告诉弟弟“不行的话就别过了”，但想到弟弟患有尿毒症，又改为劝和：“要是能回心转意，你们为了孩子再过过也行。”刘琳说，弟弟当时没有明确表态。也正是当天，刘琳才知晓这个她看起来关系和睦的弟弟和弟媳，已经商定协议离婚并提交申请。</p> \n<p cms-style=\"font-L\">　　不过，那时候的刘琳，不知道在这个干净整洁的家里发生了怎样的冲突。直到3月22日下午，刘琳接到弟媳家人的电话，对方称王可被刘军打住院，让其过来看看。刘琳没有去，她说，“我在21日上午，还看到了王可在店铺上班，走来走去打电话，第二天下午听说她住院。而且我觉得她也有错，我不愿意去道歉”。</p> \n<p cms-style=\"font-L\">　　刘琳和王可在同一个商场各开了一家店铺，两人店铺离得很近，刘琳往往能在自家店铺里看到王可的动态。</p> \n<p cms-style=\"font-L\">　　3月22日晚上，刘琳意识到两人事态升级。刘军给她打了一个不到两分钟的电话，称“王可报警了，我去派出所录个笔录，很快就回来了”。刘琳丈夫在当日晚十点去派出所询问时，得知刘军已经从派出所被刑警带走，多方打听得知“因弟媳王可告了刘军家暴、强奸”。</p> \n<p cms-style=\"font-L\">　　<strong>检方：男方违背女方意愿强行发生关系</strong></p> \n<p cms-style=\"font-L\">　　大河报《看见》记者从知情人处获取的起诉书提及，被告人刘军与被害人王可于2月27日申请协议离婚，进入离婚冷静期，双方处于分居状态。刘军因怀疑王可与他人有不正当关系，从网上购买具备录音功能的智能定位终端放置于王可卧室书架上，对王可日常生活进行窃听。</p> \n<p cms-style=\"font-L\">　　3月21日8时许，刘军用手机播放智能定位终端盗录的王可与他人通话音频后，拽其头发，用脚踢其大腿及腹部，并去厨房拿菜刀用刀面拍打王可肩膀部位。随后，刘军要求被害人王可给被怀疑的出轨对象拨打微信视频，视频接通后对方看见刘军后立即挂断。出于泄愤目的，刘军要求王可脱掉衣物，并对其继续殴打辱骂，最终造成王可l2-l4三处腰椎左侧横突骨折。随后，刘军违背王可意愿，强行与其发生性关系，并用手机拍摄两段视频。3月21日16时许，被害人王可以被殴打为由报警，次日20时许以被家暴、强奸为由再次报警。经呼伦贝尔市公安司法鉴定，王可被评定为轻伤一级。当地检察院以涉嫌强奸罪提起公诉。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/165/w550h415/20250811/7487-4a47ca78e280345478fd2cf9ed2dfed8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<strong>涉案人曾为丈母娘摔盆起灵</strong></p> \n<p cms-style=\"font-L\">　　事情的走向超乎了刘琳的想象。她意料不到内向的弟弟有此举动，更理解不了婚姻关系内的夫妻俩为何会存在“强奸”问题。</p> \n<p cms-style=\"font-L\">　　在刘琳眼中，弟弟刘军对弟媳比较爱护。刘琳说，弟媳是独生女，在弟弟丈母娘的葬礼上，是由弟弟刘军摔盆起灵，“我们当地习俗要求儿子只能摔盆两次，我父母都还健在，这也看出来我弟弟对弟媳一家多上心了”。</p> \n<p cms-style=\"font-L\">　　刘琳称，弟弟比较顾家，她向记者展示了3月22日当天和弟弟多个通话记录，除了最后两三个电话与本案相关，上午至中午五六个电话均在关心自家儿子在姑姑这里吃的什么、干了什么。</p> \n<p cms-style=\"font-L\">　　刘琳与弟媳也相识多年，“我们以前一起在商场卖货，是同事，我看她长得好看，说话温柔，就介绍她跟我弟认识了”。后来，因刘琳和王可开的店铺离得很近，两家交往密切，每次侄子来商场时，都会去姑姑的店铺里玩耍。</p> \n<p cms-style=\"font-L\">　　谈及案发后弟弟14岁儿子的态度，刘琳说有些难过，“我侄子现在不跟我们家来往了，在商场碰到也不说话”。</p> \n<p>　　<strong>同事：派出所曾调解，同事签联名信称男方无暴力倾向</strong></p> \n<p cms-style=\"font-L\">　　刘军的同事王伟（化名）同样对此事感到震惊。王伟和刘军在当地一国营农场共事十几年，感情深厚，在王伟印象中，他从未见到刘军和谁“红过脸”，也从未听说过夫妻俩人有何矛盾。刘军被传唤当天，主动喊王伟和其他两位一起吃饭的朋友前往派出所。</p> \n<p cms-style=\"font-L\">　　“当时派出所的人跟我们说可以去找女方调解下，要是对方谅解了就不会进去了，所以我和其他两人在22日晚上就赶去医院了。”王伟说，他们在医院见到女方时，女方可以自主行走，但行动缓慢。王伟认为刘军打人确实不对，积极关心和道歉后，他们向女方表达了请求谅解的意愿，“当天女方没有明确表态，但她爸表示不同意”。王伟说，他们几人连去医院三天，均未取得女方谅解，“女方家属一直不同意，我跟他们说考虑下十几岁孩子的未来，女方家属说，要怪只能怪他爸”。</p> \n<p cms-style=\"font-L\">　　王伟说，后来他和其他24名同事和男方亲属共同签署了一封联名信，以证明刘军在工作期间无任何暴力倾向或行为，“他人真挺好的，不想看到他走到这一步”。</p> \n<p cms-style=\"font-L\">　　8月11日前后，记者多次尝试与女方取得联系，未获有效回应。</p> \n<p cms-style=\"font-L\">　　8月12日上午，年近50岁的刘琳，将以辩护人的身份帮弟弟出庭辩护，她说自己很慌张、害怕，自从弟弟出事以后，她已经瘦了13斤，不善言辞的她被迫为弟弟奔走，“父母年纪大了，我爸得知儿子被告强奸罪，觉得抬不起头，家里的事情只能我来管了”。</p> \n<p cms-style=\"font-L\">　　刘军的辩护律师河南泽槿律师事务所主任付建告诉大河报《看见》记者，他准备做无罪辩护。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/8/w550h258/20250811/ee4e-2541125bf6ed3ce52512b10c62c18e46.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/165/w550h415/20250811/7487-4a47ca78e280345478fd2cf9ed2dfed8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4284, NULL, '美总统特朗普要遏制首都“暴力犯罪” 华盛顿市长驳斥', 0, 4, 207, '2025-08-11 18:30:26', '2025-08-11 17:26:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/6bfb-aca6710b72302153bcb8c86f56876fc8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrawz9697370.shtml', '央视', '<p cms-style=\"font-L\">　　针对美国总统特朗普威胁驱逐首都华盛顿流浪人员并“制止暴力犯罪”的言论，华盛顿市长10日予以驳斥，强调当地犯罪率已显著下降，当前并未出现犯罪激增现象。</p> \n<p cms-style=\"font-L\">　　同一天，媒体报道称，美国联邦政府准备向华盛顿派遣数百名国民警卫队人员。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　民主党市长公开反驳</p> \n<p cms-style=\"font-L\">　　民主党籍的华盛顿市长缪里尔·鲍泽10日接受媒体采访时强调，华盛顿2024年犯罪率已降至“30年来的最低水平”。警方数据显示，2025年前七个月，市内暴力犯罪案件数量较去年同期下降26%，全部犯罪案件数量同比下降约7%。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/6bfb-aca6710b72302153bcb8c86f56876fc8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△华盛顿市长缪里尔·鲍泽（资料图）\">\n <span class=\"img_descr\">△华盛顿市长缪里尔·鲍泽（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　鲍泽说，华盛顿2023年曾经出现犯罪率大幅增长，但“现在不是2023年”。<font cms-style=\"font-L strong-Bold\">该市过去两年已成功将暴力犯罪事件数量降至30年来最低水平。</font>她与特朗普数周前曾在白宫会面，后者“非常了解”联邦与当地执法人员的合作。</p> \n<p cms-style=\"font-L\">　　10日早些时候，特朗普在其社交媒体账号发文，称华盛顿流浪人员必须“立即搬走”，政府将为其提供住所，但会远离首都，罪犯则将被关进监狱。他计划第二天在白宫举行记者会，宣布“遏制华盛顿特区暴力犯罪”的举措。</p> \n<p cms-style=\"font-L\">　　据路透社报道，白宫方面未说明驱逐流浪人员的法律依据，且目前联邦政府仅控制特区内的联邦土地及建筑。</p> \n<p cms-style=\"font-L\">　　报道还以两名不愿公开姓名的美国政府官员为消息源报道，<font cms-style=\"font-L strong-Bold\">军方已准备好在华盛顿部署数百名国民警卫队人员</font>，其任务可能包括保护联邦人员或承担行政支援，这一部署的最终决定权在总统手中。</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　又将引发争议？</p> \n<p cms-style=\"font-L\">　　华盛顿特区当前由民主党主政。作为共和党籍总统，特朗普今年1月再次入主白宫以来，<font cms-style=\"font-L strong-Bold\">多次批评华盛顿特区暴力犯罪与流浪人员问题</font>，指责当地政府治理不力，并多次主张联邦政府全面介入管理华盛顿特区。</p> \n<p cms-style=\"font-L\">　　外界普遍认为，特朗普最新决定的直接导火索是一名政府效率部年轻职员近期在华盛顿遭一群青少年袭击。事发后，<font cms-style=\"font-L strong-Bold\">白宫宣布9日已增派450名联邦执法人员进驻华盛顿。</font></p> \n<p cms-style=\"font-L\">　　然而，据路透社等媒体10日报道，联邦执法人员周末处理的案件多为无证持枪、驾照吊销后无证驾驶等轻罪，与白宫宣称的应对“暴力犯罪”存在落差。</p> \n<p cms-style=\"font-L\">　　外界普遍预计，<font cms-style=\"font-L strong-Bold\">如果国民警卫队人员进驻华盛顿，无疑将再次引发争议。</font></p> \n<p cms-style=\"font-L\">　　早在今年6月特朗普下令调动加利福尼亚州国民警卫队人员进驻洛杉矶地区时，相关做法就遭到在洛杉矶及加州主政的民主党人强烈反对。当时双方围绕特朗普政府是否有权将军队部署到洛杉矶地区，展开激烈法律攻防战。美国第九巡回上诉法院当地时间6月19日裁决，特朗普政府拥有对部署到洛杉矶地区的加州国民警卫队的控制权。</p> \n<p cms-style=\"font-L\">　　华盛顿的国民警卫队指挥权则直属总统。2021年1月6日国会山发生骚乱后，国民警卫队曾进驻华盛顿维持秩序。</p> \n<!--article_adlist[<p cms-style=\"font-L strong-Bold align-Center\"></p>]article_adlist--> \n<p></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/6bfb-aca6710b72302153bcb8c86f56876fc8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4285, NULL, '法国最后一名街头卖报人将被授予国家功绩勋章', 0, 4, 66, '2025-08-11 18:30:33', '2025-08-11 16:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/112/w1019h693/20250811/9bfd-73e247791d7d569dbbf9070f946e563e.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrawt0382836.shtml', '极目新闻', '<p cms-style=\"font-L\">　　新华社北京8月11日电　七旬老翁阿里·阿克巴尔在法国首都巴黎卖了50多年报纸，是法国、甚至可能是欧洲的最后一名街头卖报人。法国总统埃马纽埃尔·马克龙定于9月授予阿克巴尔国家功绩勋章，以表彰他对法国文化领域的贡献。</p> \n<p cms-style=\"font-L\">　　据英国广播公司10日报道，阿克巴尔现年72岁，20世纪60年代晚期从巴基斯坦来到欧洲，1973年落脚巴黎，从此开启了在塞纳河左岸吆喝卖报的生涯。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/112/w1019h693/20250811/9bfd-73e247791d7d569dbbf9070f946e563e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　2005年9月15日，在法国首都巴黎的地铁列车上，一位乘客阅读当天出版的《巴黎人报》上关于个人所得税改革方案的报道。新华社记者宋立东摄</p> \n<p cms-style=\"font-L\">　　50多年来，阿克巴尔见证了报纸的逐渐衰落。“我1973年刚到这儿的时候，巴黎有35名到40名我这样的卖报人。”阿克巴尔回忆说：“现在只剩我自己了。”</p> \n<p cms-style=\"font-L\">　　每天卖报纸的收入一半归阿克巴尔，但当天没卖完的报纸他不能退还报社。他说，如今他往往8小时只能卖出20份《世界报》，因为“现在全是电子化的（产品），人们更喜欢刷手机”。</p> \n<p cms-style=\"font-L\">　　阿克巴尔说，互联网时代到来前，报纸上市的1小时内他就能卖出80份。“以前的日子里，人们会围着我要报纸，现在我得追着顾客跑才能卖出去一份。”</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/166/w1019h747/20250811/eb56-518aab5b3842b7bf76ea50129e1667ed.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"7月5日，两名女子在法国巴黎圣母院前自拍。新华社记者高静摄\">\n <span class=\"img_descr\">7月5日，两名女子在法国巴黎圣母院前自拍。新华社记者高静摄</span>\n</div> \n<p cms-style=\"font-L\">　　在他看来，以文艺气息著称的巴黎左岸也不复昔日景象。“以前这儿到处是作家、出版商，还有演员和音乐家。这个地方曾经有过灵魂，现在不过是个旅游景点。”</p> \n<p cms-style=\"font-L\">　　不过，阿克巴尔依然享受卖报纸的乐趣，想一直卖下去。“我有卖报纸的特别方法。我开玩笑逗乐人，我表现得积极主动，创造一种氛围……我努力走进人们内心，而不是（盯着）他们的钱包。”</p> \n<p cms-style=\"font-L\">　　附近街区的居民习惯了每天看到阿克巴尔。一名上世纪60年代迁居此地的女子说，自己好像和阿克巴尔“一起长大”，“他像个兄长”。</p> \n<p cms-style=\"font-L\">　　当马克龙还是一名学生时，也曾从阿克巴尔手里买过报纸。（袁原）</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/112/w1019h693/20250811/9bfd-73e247791d7d569dbbf9070f946e563e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/166/w1019h747/20250811/eb56-518aab5b3842b7bf76ea50129e1667ed.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4286, NULL, '“古今交响 一见钟‘秦’”——2025驻华外交官陕西调研行活动在咸阳启动', 0, 2, 286, '2025-08-11 18:30:48', '2025-08-11 18:16:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/1/w961h640/20250811/65d3-765309901fd635f34e886ee2a997bea3.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrieu8678760.shtml', '央视网', '<p>　　来源：央视网</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/1/w961h640/20250811/65d3-765309901fd635f34e886ee2a997bea3.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　“古今交响 一见钟‘秦’”——2025驻华外交官陕西调研行活动在咸阳正式启动</p>\n<p cms-style=\"font-L\">　　国际在线陕西消息（记者 张雨晨）：8月10日，由陕西省人民政府新闻办公室、中央广播电视总台国际在线联合主办的“古今交响 一见钟‘秦’”——2025驻华外交官陕西调研行活动在咸阳启动。</p>\n<p cms-style=\"font-L\">　　来自毛里塔尼亚伊斯兰共和国、约旦哈希姆王国、克罗地亚共和国、伊朗伊斯兰共和国等国的驻华外交官齐聚三秦大地，从文化历史、产业振兴、乡村发展等多方面深入调研陕西，以独特视角感受陕西魅力，探寻发展机遇。</p>\n<p cms-style=\"font-L\">　　陕西省委宣传部副部长、省政府新闻办主任单舒平；陕西省人民政府外事办公室副主任高进孝；中央广播电视总台国际在线总裁范建平；中国前驻奥地利科技参赞雷风云；咸阳市委常委、宣传部部长刘莉等中方领导嘉宾出席启动仪式。</p>\n<p cms-style=\"font-L\">　　从周秦故里到丝路起点，从科技创新到文化传承，陕西始终是中国与世界对话的重要平台。两千多年前，这里是丝绸之路的起点，推动东西方文明对话互鉴；今天，这里仍是内陆开放的前沿，以枢纽优势链接全球资源。陕西的发展轨迹，印证着开放合作是跨越时空的必然选择。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/799/w960h639/20250811/b329-3ee6496348ebd9737b22201d25e2adeb.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　陕西省委宣传部副部长、省政府新闻办主任单舒平致辞</p>\n<p cms-style=\"font-L\">　　单舒平在致辞中强调，近年来陕西持续扩大开放，注重与各国人文交流合作：开展文化遗产交流，近五年出境文物外展29场，推进考古国际合作及“一带一路”文化遗产国际合作联盟建设；开展文化艺术影视交流，承办上合组织国家电视节，与多国合拍影视，连续举办10届丝绸之路国际艺术节、11届与福州交替举办的丝绸之路国际电影节；推进媒体国际交流，举办三届“一带一路”国际智库（媒体）合作论坛，“丝绸之路万里行”活动持续11年、到访53国100多城，举办7届“丝路春晚”、邀请50国艺术家参演；开展“驻华外交官看陕西”系列活动6届，邀请70多国近100位驻华外交官到访，推动教育、农业、科技等领域务实合作。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/d04c-d477a2ef717fdb1c6ac1c412749405a0.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"2\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　陕西省人民政府外事办公室副主任高进孝致辞</p>\n<p cms-style=\"font-L\">　　高进孝在致辞时说，陕西是中华文明的“源代码”，更是中国向西开放的“桥头堡”。期待各位外交官朋友能够在秦咸阳宫遗址触摸大一统文明的基因密码，从茯茶中品味丝路“黑黄金”的醇厚；更期待大家在蓬勃发展的科技创新中感受陕西面向未来的澎湃动能，在“现代化枢纽”下见证内陆开放高地建设的“加速度”；在秦岭脚下感受艺术赋能、产业兴旺的乡村新貌；在千年窑火与瓷韵流光中体验东方美学的生生不息。他表示，热切期盼以此次“一见钟‘秦’”的调研行为契机，进一步架起与世界各国之间更加宽广的友谊与合作的桥梁，在文化互鉴、经贸往来、科技创新等领域开启交流合作的新篇章，共同谱写互利共赢的时代华章。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/985c-6f174d9dd47500128c753397611a00c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　咸阳市委常委、宣传部部长刘莉致欢迎辞</p>\n<p cms-style=\"font-L\">　　刘莉在致辞中提到，咸阳历史悠久、底蕴深厚；物华天宝、物产丰富；区位独特、产业发达。咸阳正在从一座文明包容的千年古城阔步迈向活力迸发的现代新城。她衷心希望通过本次活动，充分展示咸阳厚重的历史文化、独特的人文风情和广阔的发展前景，也诚挚邀请各位国际友人，常来咸阳走一走、看一看，加强沟通交流、开展务实合作、实现互惠共赢。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/25f3-01b77af8622baa0bd29333ce86b62556.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"4\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　哥伦比亚驻华大使塞尔希奥·卡夫雷拉致辞</p>\n<p cms-style=\"font-L\">　　哥伦比亚驻华大使塞尔希奥·卡夫雷拉在致辞中表示：中国和哥伦比亚之间开展了许多合作：中国的建设公司承建波哥大地铁一号线，波哥大的地铁工作人员前往西安进修，“把西安地铁开回家”；哥伦比亚的咖啡豆在咸阳老街的咖啡店里散发香气，年轻人们品着咖啡，讨论拉美文学大爆炸和马尔克斯。这也是自秦代发源的“大一统”思想的当代价值，不仅仅是疆域的统一，而是心灵的相通、技术的交流、利益的相融。“正值中哥建交45周年，愿哥中友谊恒久绵长；也愿这次陕西之行，能让我们不仅看见‘秦之雄’，更能读懂人类命运共同体“一以贯之，行稳致远”的理念。”塞尔希奥·卡夫雷拉说。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/1b69-bc69d33958d6dc2b2145c741e918ebc9.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"5\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-M align-Center\">　　中央广播电视总台国际在线总裁范建平致辞</p>\n<p cms-style=\"font-L\">　　范建平在致辞时表示，陕西，是中华文明的重要发祥地，更是“古今交响”的生动舞台。从周秦汉唐的文明曙光到新时代的科技腾飞，这片土地始终书写着传承与创新的精彩篇章。陕西，早已成为世界读懂中国历史厚度、感知中国发展活力的重要窗口。期待通过本次调研行，各位来宾能亲身感受陕西“古今交响”的独特魅力，成为陕西故事的传播者、中外合作的推动者。</p>\n<p cms-style=\"font-L\">　　当不同国家的目光聚焦陕西，既是对历史智慧的共同汲取，更是对未来发展的共同肯定。在全球化纵深发展的今天，唯有以文明对话凝聚共识，以务实合作破解挑战，才能在变局中开辟新局，这正是本次活动对构建人类命运共同体的生动实践。</p>\n<p cms-style=\"font-L\">　　活动现场，“秦地最胜 无如咸阳”——探索从公元前350年到2025年一座古城的发展史驻华外交官咸阳调研行主题活动同步启动。据了解，当日，驻华外交官一行已先后参访秦咸阳宫遗址博物馆、咸阳博物院、古渡廊桥，观看演出《赳赳老秦》。8月11日，驻华外交官还将参访茂陵博物馆，领略汉陵气势与石雕魅力；探秘咸阳茯茶工艺，体验 “筑茶” 非遗技艺，品味科技赋能带来的茯茶新魅力，共赏古城盛华。</p>', '[\"https://k.sinaimg.cn/n/spider20250811/1/w961h640/20250811/65d3-765309901fd635f34e886ee2a997bea3.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/799/w960h639/20250811/b329-3ee6496348ebd9737b22201d25e2adeb.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/d04c-d477a2ef717fdb1c6ac1c412749405a0.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/985c-6f174d9dd47500128c753397611a00c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/25f3-01b77af8622baa0bd29333ce86b62556.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/0/w960h640/20250811/1b69-bc69d33958d6dc2b2145c741e918ebc9.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4287, NULL, '甘肃省水利厅终止洪水防御Ⅲ级应急响应', 0, 1, 28, '2025-08-11 18:30:53', '2025-08-11 18:08:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkriex9584407.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：据“甘肃水利”微信公众号消息，8月7日—10日强降雨过程已结束，各河流、水库运行平稳。根据《甘肃省水利厅水旱灾害防御应急预案》规定，甘肃省水利厅决定自8月11日13时起，终止针对武威、白银、定西、临夏、甘南、陇南、天水的洪水防御Ⅲ级应急响应。</p>\n<p cms-style=\"font-L\">　　当前正值“七下八上”防汛关键期，请各地继续密切关注气象预报，加强监测预警、会商研判和值班值守，切实做好水工程调度、山洪灾害和中小河流洪水防御等工作，全力保障人民群众生命财产安全。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4288, NULL, '“他跟逛夜市似的溜达把我们看光了！”女子称沈阳一洗浴店女浴区内撞见男子，多方回应', 0, 2, 35, '2025-08-11 18:31:09', '2025-08-11 17:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/56/w550h306/20250811/a833-5225a6dadf22c93658f001f332ce8f66.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawx5883321.shtml', '新浪新闻综合', '<p cms-style=\"font-L\">　　来源 | 潇湘晨报</p> \n<p cms-style=\"font-L\">　　记者 | 吴陈幸子</p> \n<p cms-style=\"font-L\">　　有消费者如女士（化姓）向潇湘晨报·晨视频记者反映，8月9日凌晨，自己与亲友在辽宁沈阳旅游，前去一家洗浴店洗浴时，在女浴区突遇一名男子在“溜达”，“他在那逗留了快半小时，把我们都看光了，还站一米之内跟我们对视。他说他来上厕所。我们真的太生气了。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">8月11日，如女士告诉潇湘晨报记者，她与亲友从长春去沈阳旅游，9日凌晨1时许，他们前往位于铁西区的鹿儿岛温泉店。</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">她当时在更衣室换衣服，先去浴区上洗手间的妹妹突然慌张地跑回来，说在浴区看见了男的。如女士觉得不可思议，同妹妹一起前往浴区确认是否是其眼花，结果就在洗漱台附近，一名男子突然从他们身后冒出来，“手揣兜，跟逛夜市似的溜达。就离我们一米远的地方，在我俩完全光了的情况下和我们对视、对我俩说话。”</font></font></font></p> \n<p cms-style=\"font-L\">　　如女士称自己当时质问该男子进来干什么，男子只是说自己进来上厕所，语气强硬。如女士急忙喊浴区服务员，“当时两个人（服务员），一个在睡觉，一个在浴区外边扫地，都没发现他进来。”随后男子被推出浴区。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/56/w550h306/20250811/a833-5225a6dadf22c93658f001f332ce8f66.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△ 事发洗浴店公开发布的环境图\" data-link=\"\">\n <span class=\"img_descr\">△ 事发洗浴店公开发布的环境图</span>\n</div> \n<p cms-style=\"font-L\">　　如女士称，经洗浴店经理调监控发现，男子在女浴区待了近半小时，他们随后进行报警处理。但她后面得知，男子称自己有精神病。</p> \n<p cms-style=\"font-L\">　　此外，如女士认为洗浴店管理存在过错。其男女浴区入口未设门禁机器类设施，而是只要撩起帘子就可以进入。在当晚值守时，两名服务员也没有及时发现，事发时也未对自己一行表达过歉意，“他们认为不是他们的错。”</p> \n<p cms-style=\"font-L\">　　如女士提供的一段与洗浴店服务员沟通的视频显示，服务员称自己没看到男子进女厕，但看到了他从女厕那块出来。</p> \n<p cms-style=\"font-L\">　　潇湘晨报记者也就此事致电涉事洗浴店，工作人员并表示并非当天值班人员，不了解详细情况。相关负责人吴先生则表示不方便回答，“你自己找官方的人问去吧。”</p> \n<p cms-style=\"font-L\">　　辖区派出所值班人员表示，自己不是事发当天值班人员，对详情不了解。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/56/w550h306/20250811/a833-5225a6dadf22c93658f001f332ce8f66.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4289, NULL, '宁德时代确认宜春锂矿暂停开采，赣锋锂业等矿企股价、碳酸锂期货纷纷大涨', 0, 2, 128, '2025-08-11 18:31:53', '2025-08-11 14:09:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqwqy8808733.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　过去几周，江西宜春8家涉锂矿企的走向不确定性扰动着碳酸锂市场。8月11日上午，动力电池巨头宁德时代（300750.SZ/03750.HK）在互动平台对外确认，公司在宜春项目采矿许可证8月9日到期后已暂停了开采作业。</p> \n<p cms-style=\"font-L\">　　上述项目何时重启？目前尚无明确时间点。宁德时代目前的口径为，正按相关规定尽快办理采矿证延续申请，待获得批复后将尽早恢复生产。公司同时称，该事项对公司整体经营影响不大。</p> \n<p cms-style=\"font-L\">　　实际上，在此前7月30日的2025年上半年度业绩说明会上，宁德时代高管在回应投资者提问时回应称，目前公司宜春锂矿项目生产经营正常，公司已按要求提前向宜春市自然资源局递交了延续申请材料，经市、省两级收件确认延续登记要件齐全，内容完整，目前延续申请待批复。</p> \n<p cms-style=\"font-L\">　　宁德时代当时还提及，近期碳酸锂价格有一些波动，但本质上价格是由供需来决定的。并称公司有锂矿资源战略储备，也与供应商签订了长期协议，能够较好地应对碳酸锂价格的波动。</p> \n<p cms-style=\"font-L\">　　宜春市自然资源局在7月中旬已下发通知，要求当地8家涉锂矿山企业编制储量核实报告，并在9月30日前完成报告编制。据了解，此举目的为检查企业是否存在规避审批权限、越权办理手续等问题。</p> \n<p cms-style=\"font-L\">　　值得关注的是，受宁德时代宜春项目最新暂停消息影响，锂矿板块上市公司在8月11日上午应声集体大幅上涨。截至上午盘结束，天齐锂业（002466.SZ）、盛新锂能（002240.SZ）涨停，中矿资源（002738.SZ）、永杉锂业（603399.SH）、赣锋锂业（002460.SZ）涨幅均超9%，此外西藏矿业（000762.SZ）、盐湖股份（000792.SZ）、雅化集团（002597.SZ）等多家公司均涨势喜人。</p> \n<p cms-style=\"font-L\">　　碳酸锂期货所有合约则均触及涨停，其中主力合约（2511）现报81000元/吨。</p> \n<p cms-style=\"font-L\">　　2022年4月20日，宁德时代控股子公司宜春时代新能源矿业有限公司（下称“宜春时代”）以8.65亿元的报价成功竞得江西省宜丰县圳口里-奉新县枧下窝矿区陶瓷土（下称“枧下窝矿区”）（含锂）探矿权。该矿探矿权面积6.44平方公里，推断瓷石矿资源量96025.1万吨，伴生锂金属氧化物量265.678万吨。</p> \n<p cms-style=\"font-L\">　　据宜春市自然资源局此前披露的《江西省宜丰县圳口里-奉新县枧下窝矿区陶瓷土矿普查探矿权出让收益评估报告书》，该矿山评估设计项目建设投资为21.58亿元，枧下窝矿区可采储量为77492万吨，生产规模为3000万吨/年计算，矿山服务年限为25.83年。</p> \n<p cms-style=\"font-L\">　　此前即有分析师按平均氧化锂品位折算，上述生产规模可达20万吨碳酸锂/年。</p> \n<p cms-style=\"font-L\">　　宁德时代彼时称，宜春时代新能源矿业获得宜春市锂矿探矿权是其全产业链布局的重要举措，并提到将助推锂相关原材料价格回归理性。</p> \n<p cms-style=\"font-L\">　　不过，此后行业的发展态势表明，“价格回归理性”远比想象中来得快。2022年碳酸锂价格一路攀升至约60万元/吨的峰值，但也就是在宁德时代拿下枧下窝矿区项目后不久，行业开始急转直下，开启了至今难言见底的漫漫下跌之路。截至8月8日，据SMM锂电统计，电池级碳酸锂7.05万元/吨-7.33万元/吨，均价7.19万元/吨。</p> \n<p cms-style=\"font-L\">　　在过去的一个多月时间里，受国家“反内卷”政策带动，以及供应端消息扰动，锂价经历了一轮小范围的“过山车”。</p> \n<p cms-style=\"font-L\">　　碳酸锂主力合约从6月23日最低点的58400元/吨涨至7月25日盘中创下的80520元/吨的高位，最高涨幅多达37.88%。随后在7月底又步入了下行通道，但该月仍创下2024年2月以来的最大月线涨幅。近日则受宁德时代枧下窝矿区项目停产时间线或将逼近的消息影响，再度迎来连续上涨。</p> \n<p cms-style=\"font-L\">　　截至记者发稿，宁德时代A股股价为263.87元/股，上涨0.15%。自7月30日以来的几个交易日，宁德时代股价基本为持续下跌状态。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4290, NULL, '珀斯华人区连发枪击纵火案，中领馆提醒中国公民加强防范', 0, 4, 13, '2025-08-11 19:30:18', '2025-08-11 18:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-11/doc-infkriex9586120.shtml', '界面', '<p cms-style=\"font-L\">　　8月11日，中国驻珀斯总领馆提醒领区中国公民加强人身安全防范。提醒指出，近日，珀斯市连续发生多起枪击和纵火袭击事件，其中两起发生在华人聚集区域。</p> \n<p cms-style=\"font-L\">　　中国驻珀斯总领馆提醒领区中国公民密切关注当地新闻动态、留意治安形势，尽量减少夜间出行，同时提高自身安全防范意识，加强自我保护能力；检查住所与店铺安防措施，确保监控、报警等设备正常运行。如遇险情，保持冷静，以人身安全为首要，脱险后及时报警。</p> \n<p cms-style=\"font-L\">　　澳大利亚报警电话：000（紧急）；澳大利亚警方求助电话：131444（非紧急）。</p> \n<p cms-style=\"font-L\">　　外交部全球领事保护与服务应急呼叫中心电话：+86-10-12308或65612308（从澳境内拔打：00118610—65612308）</p> \n<p cms-style=\"font-L\">　　我馆领事保护与协助电话：0061—8—92213729（9：00—12：00，14：00—17：00）</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4291, NULL, '奖补不低于1000万元！河南科创新政带来这些利好→', 0, 1, 16, '2025-08-11 19:31:27', '2025-08-11 18:27:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/379/w1200h779/20250811/5a93-6a6e775954b2f71a6ab2490f1b3e3fef.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrier0282554.shtml', '河南省政府网站', '来源：河南政府网\n<br>\n<br>\n<p cms-style=\"font-L\">　　每年公开发布“揭榜挂帅”项目榜单100项以上；单个项目支持额度原则上不低于1000万元；对新建的中原学者工作站一次性给予20万元资金支持……</p>\n<p cms-style=\"font-L\">　　近日，省政府印发《河南省支持企业科技创新若干政策措施》（以下简称《政策措施》），聚焦强化企业科技创新主体地位，从技术攻关、企业培育、平台建设、服务保障等多方面，提出20条“真金白银”支持举措。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/379/w1200h779/20250811/5a93-6a6e775954b2f71a6ab2490f1b3e3fef.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"省政府网站截图。\" id=\"0\">\n <span class=\"img_descr\">省政府网站截图。</span>\n</div>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">　【研发】聚焦关键技术，单个项目奖补不低于1000万元</font></p>\n<p cms-style=\"font-L\">　　立式五轴车铣复合机床多项核心技术取得突破，实现进口替代；成功研制开发出大尺寸金刚石光学/散热材料，建成了产业化生产线……近些年，聚焦重点产业关键核心技术开展攻关，我省取得多项原创性、颠覆性技术成果。</p>\n<p cms-style=\"font-L\">　　据省科技厅公布的数据，去年我省获批国家科技创新2030重大项目3项、国家重点研发计划项目17项，启动实施22项省重大科技专项、243项省重点研发专项。</p>\n<p cms-style=\"font-L\">　　省科技厅相关负责人介绍，《政策措施》聚焦企业反映较为集中的问题和企业科技创新的迫切需求，对现行惠企科技政策进行了梳理、优化、提升、扩面。其内容设置涵盖了激发企业内生创新活力、促进科技型企业量质齐升、补足企业创新资源与人才缺口、支持科研成果转化、强化政策支持和创新服务等方面，全方位为企业创新护航。</p>\n<p cms-style=\"font-L\">　　《政策措施》将突破关键共性技术作为核心目标，推出“揭榜挂帅”机制破解产业技术瓶颈。其中提到，每年公开发布“揭榜挂帅”项目榜单100项以上，力争突破重点产业链群关键核心技术200项以上，单个项目支持额度原则上不低于1000万元。</p>\n<p cms-style=\"font-L\">　　同时，对企业承担的国家和省级科技项目给予阶梯式奖补：对承担国家重大科研项目的企业，按国家拨付经费的3%~5%进行奖补，单个项目奖补不超过60万元，每家企业年度奖补不超过500万元；对承担省级科技项目的企业，重大科技专项单个项目省财政资金支持额度原则上不低于1000万元，单个重点研发专项不低于100万元，单个科技攻关项目10万元。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"></font><font cms-style=\"font-L strong-Bold\"></font>【梯队】构建“分层培育+精准激励”的成长体系</font></p>\n<p cms-style=\"font-L\">　　创新是企业的生命，企业创新是推动经济高质量发展的核心要素。</p>\n<p cms-style=\"font-L\">　　在郑州市金水区，河南飙风信息科技公司通过无人机低空巡检与智能算法融合，为城市治理提供创新方案，这正是科技型中小企业快速成长的缩影。在郑州市高新区，一家名为汉威科技的高科技企业从传感器这一细分领域起步，凭借创新技术与市场拓展，成功将“小传感器”打造成上亿元的“大生意”，并长期稳居国内气体传感器市场占有率榜首，成为传感器行业的佼佼者。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/196/w1200h596/20250811/f90e-05ed08aab026dc197524fb9cc0e2b4b7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"由河南飙风信息科技有限公司搭建的网格化无人机平台。\" id=\"1\">\n <span class=\"img_descr\">由河南飙风信息科技有限公司搭建的网格化无人机平台。</span>\n</div>\n<p cms-style=\"font-L\">　　为壮大创新型企业队伍，《政策措施》围绕“培育—孵化—升级”全链条，构建梯次分明的创新型企业群体。对新认定为高新技术企业且年研发投入100万元以上的企业给予一次性10万元资金支持。对省级以上孵化载体实施奖补政策，每年给予不超过200万元资金支持。</p>\n<p cms-style=\"font-L\">　　在研发投入激励上，《政策措施》打出“全覆盖+重点扶”组合拳：推动规模以上工业企业研发活动全覆盖，明确营收1亿元以上企业建研发机构、100亿元以上企业成科技领军企业的阶梯目标；对研发经费投入500万元以上且占比高、增速快的企业，分档给予10万~100万元一次性资金支持；对研发经费投入前200强的规模以上工业企业，实行跟踪服务，集中项目、平台、人才等相关资源进行支持。</p>\n<p cms-style=\"font-L\">　　“《政策措施》分层分类政策精准支持企业科技创新，通过资金直补、资源整合等方式，加速技术转化效率，助力企业梯度成长。”河南省社会科学院数字经济与工业经济研究所助理研究员邱静说。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"></font>【保障】全链条服务保障，打通创新“最后一公里”</font></p>\n<p cms-style=\"font-L\">　　从人才引育到成果转化，从金融支持到环境优化，《政策措施》构建全链条服务网络，破解创新 “落地难”。</p>\n<p cms-style=\"font-L\">　　人才方面，《政策措施》提出，对入选中原科技创业领军人才的企业负责人，给予100万元资金支持；对入选中原学者、中原科技创新领军人才的企业科研人员，分别给予200万元、100万元补助。引导科技人才向企业一线有序流动，省财政资金将投入1.5亿元左右，在2027年前选派不低于3000名（次）“科技副总”服务企业创新。</p>\n<p cms-style=\"font-L\">　　“此外，在支持科研成果转化、强化科技金融服务、优化创新环境等方面，新政策举措也给出了一系列切实支持。”省科技厅相关负责人介绍。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/429/w768h461/20250811/4245-e39cab3e0bb53219e410e4701127d03e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"河南爱彼爱和新材料有限公司是全球最早为新能源汽车与动力电池提供防火绝热一体化解决方案的企业之一。\" id=\"2\">\n <span class=\"img_descr\">河南爱彼爱和新材料有限公司是全球最早为新能源汽车与动力电池提供防火绝热一体化解决方案的企业之一。</span>\n</div>\n<p cms-style=\"font-L\">　　如何加速科研成果从“实验室”走向“生产线”？《政策措施》提出，企业购买先进技术成果在豫转化的，按技术交易额分档奖补，每年最高100万元；建设省概念验证中心和省中试基地，按成果转化收入等绩效每年给予最高200万元支持。</p>\n<p cms-style=\"font-L\">　　科技金融服务持续升级。保险机构开发研发攻关、成果转化等科技保险产品，给予参保科技企业30%的保费补贴，每年不超过20万元。银行推出研发贷、人才贷等专属产品，推动科技型企业上市培育。同时，支持企业使用共享的大型科研设施、仪器，通过科技创新券对使用企业给予30%的补助，每年最高50万元。</p>\n<p cms-style=\"font-L\">　　“《政策措施》通过科技保险补贴分散研发不确定性风险，扩大信贷供给规模缓解轻资产企业融资难问题，同时打通科创板、新三板、港交所三级资本市场通道，拓宽直接融资渠道。”邱静说，这些措施系统性破解“融资难、融资贵”瓶颈，优化了科技企业全生命周期资金链。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"></font>【发展】创新驱动未来，激活发展新动能</font></p>\n<p cms-style=\"font-L\">　　“以科技创新开辟发展新领域新赛道、塑造发展新动能新优势，是大势所趋，也是高质量发展的迫切要求。”中国商业经济学会副会长宋向清说，通过推动创新链、产业链、资金链、人才链深度融合，就能以链式布局激活“聚变效应”，培育发展新动能、打造发展新优势。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/480/w768h512/20250811/ef8f-c4e95344e74efc62723c78e58a08b435.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center color210\">许昌安彩新能科技有限公司通过“机器换人”“设备换芯”，让智能制造成为企业发展的核心动力。</font></p>\n<p cms-style=\"font-L\">　　“《政策措施》通过关键技术攻关、企业梯度培育、创新平台建设、科技服务保障等方面，重构区域创新系统的激励机制与风险分担结构，将显著增强河南省科技型企业核心竞争力。”邱静分析说，一是优化创新生态，通过完善“企业+行业+院校”“三三制”决策机制，提升政策供给与企业需求的适配性；二是构建“初创期—成长期—成熟期”梯度化企业全生命周期培育体系，覆盖企业从技术验证到产业化的完整演进路径；三是加速产业技术范式转型，通过“揭榜挂帅”与创新联合体等机制，加快发展新质生产力。</p>\n<p cms-style=\"font-L\">　　省科技厅相关负责人表示，下一步，我省将进一步完善决策机制，吸纳更多科技型骨干企业专家参与创新管理等，努力实现从“找服务”到“送服务”的转变。着重通过制度创新、生态培育、要素协同，打破“科技—产业”之间的壁垒，形成“创新驱动产业升级、产业升级反哺创新突破”的良性循环。（张家祺 部分图片来源河南日报客户端）</p>', '[\"https://k.sinaimg.cn/n/spider20250811/379/w1200h779/20250811/5a93-6a6e775954b2f71a6ab2490f1b3e3fef.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/196/w1200h596/20250811/f90e-05ed08aab026dc197524fb9cc0e2b4b7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/429/w768h461/20250811/4245-e39cab3e0bb53219e410e4701127d03e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/480/w768h512/20250811/ef8f-c4e95344e74efc62723c78e58a08b435.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4292, NULL, '3架飞机在俄罗斯被扣无法收回！山河智能公告：收到1.6亿元保险赔款', 0, 4, 164, '2025-08-11 20:30:19', '2025-08-11 19:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/656/w1080h1176/20250811/f0cd-e98754086ffb0ddc5dcf09bfcfe9fd54.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkriex9614614.shtml', '成都商报', '<p cms-style=\"font-L\">　　3架租出去的飞机滞留俄罗斯后，山河智能终于收到了保险赔偿金。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">山河智能获1.64亿元保险赔偿</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">公司去年净利润7300万元</font></p> \n<p cms-style=\"font-L\">　　8月11日，山河智能装备股份有限公司公告，公司全资子公司Avmax曾与俄罗斯客户签订三份飞机租赁合同。自2022年2月地缘政治冲突以来，航空业在制裁范围内。Avmax根据相关政策，多次尝试召回上述租赁在俄罗斯的飞机。尽管已持续进行交涉与回收操作，仍无法成功收回涉事飞机。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/656/w1080h1176/20250811/f0cd-e98754086ffb0ddc5dcf09bfcfe9fd54.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　近日，Avmax与飞机保险承保人就赔付方案达成一致意见，确认Avmax可从保险承保商获得的保险理赔款为2900万美元，扣除律师费用等后的保险赔付款净额为2296.51万美元。截至目前，Avmax已全额收到2296.51万美元保险赔付款，按照8月8日美元对人民币汇率中间价，折算人民币约1.64亿元。保险赔付款项扣税后对公司净利润影响金额为1.26亿元，会计核算计入营业外收入，占公司上一年度归母净利润的172.92%。</p> \n<p cms-style=\"font-L\">　　Avmax前期已对此三架飞机全额计提减值，本次赔款为意外赔款，不具有持续性，为非经常性损益。</p> \n<p cms-style=\"font-L\">　　公开资料显示，山河智能装备集团由中南大学教授何清华领衔创办于1999年，是世界500强企业——广州工业投资控股集团有限公司旗下子公司，已发展为以上市公司——山河智能装备股份有限公司为核心，以长沙为总部，在国内外具有一定影响力的国际化企业集团。</p> \n<p cms-style=\"font-L\">　　4月25日，上市公司山河智能（002097）公布2025年一季报，公司营业收入为15.1亿元，同比下降9%；归母净利润为3246万元，同比上升57.3%；扣非归母净利润自去年同期亏损2750万元成功扭亏，实现扣非归母净利润891万元；经营现金流净额为-4.34亿元，同比增长6.8%。</p> \n<p cms-style=\"font-L\">　　截至一季度末，公司总资产216.37亿元，较上年度末增长3.2%；归母净资产为47.23亿元，较上年度末增长2.4%。</p> \n<p cms-style=\"font-L\">　　2024年公司营业收入为71.19亿元，同比下降1.53%。归属于上市公司股东的净利润为7299.56万元，同比增长46.03%。基本每股收益为0.0679元/股，同比增长46.02%。</p> \n<p cms-style=\"font-L\">　　7月10日，山河智能境外全资子公司Avmax的全资子公司Avmax Aircraft Leasing Inc。与Qantas签署两份《飞机销售协议》，购置16架DHC-8 300型涡桨飞机，资产购买不含税总价5114.21万美元，将现金支付，预计2025年12月31日前分批交付，交易已开展尽职调查，不存在资金及流动性风险，但有交易失败等风险。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250811/200/w1080h720/20250811/0c2b-f6308e8b090189213979ab940b0becbc.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"DHC-8-400（图片来源：视觉中国）\">\n <span class=\"img_descr\">DHC-8-400（图片来源：视觉中国）</span>\n</div> \n<p cms-style=\"font-L\">　　根据双方近日签署的协议，此次交易中，16架飞机将采用分批交付的方式，预计2025年12月31日前全部完成交付，交付地点为澳大利亚塔姆沃思区域机场或双方协商的澳大利亚境内其他机场。</p> \n<p cms-style=\"font-L\">　　Avmax由山河智能2016年收购而来，也是从2016年起，山河智能将航空业务板块营收情况单列。</p> \n<p cms-style=\"font-L\">　　从业务占比来看，山河智能航空业务板块营收占比于2017年达到27.49%，为近年最高值。2017年后，山河智能航空业务板块营收占比连续4年下滑，至2021年降至5.41%。</p> \n<p cms-style=\"font-L\">　　2022年以来，山河智能航空业务板块营收规模逐年增长，营收占比逐步恢复至10%以上，至2024年升至14.24%。</p> \n<p cms-style=\"font-L\">　　近期，超级工程装备、军工概念驱动，山河智能股价大涨。7月21日来的16个交易日，山河智能录得9个涨停，期间累计涨幅达116%，目前市值达192亿元。</p> \n<p cms-style=\"font-L\">　　山河智能8月11日在互动平台回答投资者提问时表示，截至2025年8月8日收盘，公司持有人数245046户。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">日发精机曾因飞机在俄被扣起诉保险</font></p> \n<p cms-style=\"font-L\">　　值得注意的是，今年6月26日，浙江日发精密机械股份有限公司（以下简称“日发精机”，002520.SZ）公告，公司全资子公司Airwork Holdings Limited（以下简称“Airwork公司”）下属公司Airwork Ireland Limited已向新西兰奥克兰高等法院正式起诉QBE Insurance （Australia） Limited及Aon NZ。该诉讼事项近日被正式受理。</p> \n<p cms-style=\"font-L\">　　QBE，即QBE保险（澳大利亚）有限公司；Aon NZ，即怡安新西兰公司，是怡安控股新西兰公司的全资子公司，隶属于怡安集团（Aon PLC）。Aon NZ为Airwork公司的保险经纪人和顾问。</p> \n<p cms-style=\"font-L\">　　日发精机在公告中称，Airwork公司与俄罗斯客户Aviastar共签订六份B757-200货机租赁合同，西方地缘政治冲突后，欧盟、美国、新西兰等与俄罗斯双边关系相互制裁，受此影响，Airwork公司与俄罗斯客户不得不终止合作。Airwork公司于2022年3月向俄罗斯客户正式发出终止合作通知，并要求其归还上述飞机。在未得到对方回复后，Airwork公司此后多次重申终止租赁，要求该客户停止商业飞行并将上述飞机交付至俄罗斯境外的Airwork公司指定地点。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250811/762/w1080h482/20250811/e7c7-7c7631e928ecaf2c46baef639de37b96.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　Airwork公司通过多次努力争取，收回了其中1架飞机（飞机序列号：MSN27051）。</p> \n<p cms-style=\"font-L\">　　日发精机及其子公司Airwork公司曾以多种方式试图取回另外5架飞机，但均未能成功。</p> \n<p cms-style=\"font-L\">　　Airwork公司于2022年9月末收到俄罗斯客户回信，对方表示基于俄罗斯政府目前的制裁政策，几乎不可能归还上述飞机。截至目前，上述5架飞机仍被扣留在俄罗斯境内。</p> \n<p cms-style=\"font-L\">　　根据Airwork公司与保险公司所签署的保险合同，就上述飞机被扣事项，Airwork公司与保险公司通过协商谈判的方式争取保险赔偿，截至目前双方未达成一致。经过审慎论证，Airwork公司认为通过诉讼途径具有可行性，因此，为维护股东权益，Airwork公司向法院提起诉讼，索赔金额尚未确定。</p> \n<p cms-style=\"font-L\">　　值得一提的是，2022年10月，日发精机曾对Airwork公司被扣留在俄罗斯境内的5架波音757飞机计提资产减值准备7.41亿元。</p> \n<p cms-style=\"font-L\">　　（本文不构成投资建议，据此操作风险自担）</p> \n<p cms-style=\"font-L\">　　编辑 孙志成 综合自公开资料、每日经济新闻、中国经营报等</p> \n<p cms-style=\"font-L\">　　封面图自视觉中国</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/656/w1080h1176/20250811/f0cd-e98754086ffb0ddc5dcf09bfcfe9fd54.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/200/w1080h720/20250811/0c2b-f6308e8b090189213979ab940b0becbc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250811/762/w1080h482/20250811/e7c7-7c7631e928ecaf2c46baef639de37b96.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4293, NULL, '15%保护费！这回不提“国安”了？谁还会信美国？', 0, 4, 207, '2025-08-11 20:30:36', '2025-08-11 17:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250811s/546/w800h546/20250811/85c5-eb0c5d98be091c111eff0eec540e5975.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrawz9697866.shtml', '观察者网', '<p cms-style=\"font-L\">　　[文/观察者网 王恺雯]《金融时报》8月11日报道，美国芯片企业英伟达和超威半导体公司（AMD）已同意向美国政府“上贡”其在中国销售芯片收入的15%，以换取特朗普政府颁发的出口许可证。</p> \n<p cms-style=\"font-L\">　　这一消息让外界感到错愕。向企业索要部分收入来换出口许可证的做法可谓前所未有，彭博社形容，此举“不同寻常”。有分析指出，特朗普政府的行为会让美国惯用的“国家安全”借口失效。</p> \n<p cms-style=\"font-L\">　　《金融时报》援引美国官员的说法称，英伟达将“分享”其在中国销售H20芯片收入的15%，AMD也会将其MI308人工智能（AI）芯片同等比例的收入上缴给美国政府。两名知情人士表示，特朗普政府尚未决定如何使用这笔资金。</p> \n<p cms-style=\"font-L\">　　彭博社认为，这样的安排反映出美国总统特朗普一贯的做法，即通过在贸易上的“让步”，为美国争取财政方面的回报。但是，在现代企业历史上，这样一个小范围的、有选择性的“出口税”几乎没有先例。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250811s/546/w800h546/20250811/85c5-eb0c5d98be091c111eff0eec540e5975.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间2025年4月30日，美国华盛顿，英伟达公司总裁兼首席执行官黄仁勋与美国总统特朗普握手。 东方IC\" data-link=\"\">\n <span class=\"img_descr\">　　当地时间2025年4月30日，美国华盛顿，英伟达公司总裁兼首席执行官黄仁勋与美国总统特朗普握手。 东方IC</span>\n</div> \n<p cms-style=\"font-L\">　　美国乔治城大学安全与新兴技术中心（CSET）研究员雅各布·费尔德戈伊斯（Jacob Feldgoise）表示：“从出口管制角度来看，这种看似等价交换前所未有。这一安排可能使美国在出口管制上所使用的国家安全理由失效。”</p> \n<p cms-style=\"font-L\">　　“这也可能会削弱美国在与盟友协商实施配套管制措施时的立场。”费尔德戈伊斯补充道，“如果美国的决策者愿意为了经济而向美国企业或外国政府让步，牺牲国家安全关切，盟友可能不会再相信他们。”</p> \n<p cms-style=\"font-L\">　　曾在拜登政府时期担任美国商务部顾问的菲利普斯-罗宾斯（Alasdair Phillips-Robins）对路透社表示：“如果这些报道属实，这表明政府为了给财政部增加收入，正在牺牲国家安全保护措施。”</p> \n<p cms-style=\"font-L\">　　近年来，美国为了遏制打压中国，已经把美国的“国家安全”泛化成无所不装的大筐。今年4月，美国正是打着“国家安全和经济安全”的旗号，禁止英伟达向中国销售H20芯片。</p> \n<p cms-style=\"font-L\">　　“这真是荒唐。”华盛顿智库新美国安全中心（CNAS）高级研究员杰弗里·格茨（Geoffrey Gertz）对路透社表示。</p> \n<p cms-style=\"font-L\">　　“如果向中国销售H20芯片确实存在国家安全风险，那我们一开始就不该这么做。如果它不存在国家安全风险，那我们为什么要对这种销售行为施加额外惩罚？”格茨问道。</p> \n<p cms-style=\"font-L\">　　彭博社称，如果华盛顿推进这一安排，美国政府将获得一部分资金。</p> \n<p cms-style=\"font-L\">　　在截至4月27日的财季中，H20芯片为英伟达带来了46亿美元的收入，但由于此前出台的限制措施，还有价值25亿美元的产品未能交付。以此推算，如果能恢复正常水平，美国政府每季度能从这些交易中赚取约10亿美元。据摩根士丹利估计，如果限制解除，AMD在2025年的营收可能会增加30至50亿美元。</p> \n<p cms-style=\"font-L\">　　在彭博社看来，这一数额并不算太大，且英伟达和AMD都表示，即使订单量能恢复此前水平，重新提升针对中国市场产品的产能仍需时间。</p> \n<p cms-style=\"font-L\">　　但瑞联银行董事总经理凌炜森（Vey Sern Ling）表示：“考虑到美国的财政赤字及其急于收取关税的态度，美国政府显然需要这笔钱。”</p> \n<p cms-style=\"font-L\">　　值得一提的是，彭博社提到，中国近期对中国企业采用H20芯片愈发谨慎。</p> \n<p cms-style=\"font-L\">　　中国中央广播电视总台旗下的新媒体账号“玉渊谭天”日前发文，点名H20芯片“不环保，也不先进，更不安全”，并非“好选择”。</p> \n<p cms-style=\"font-L\">　　对此英伟达回应称，“网络安全对我们至关重要。英伟达的芯片不存在‘后门’，不会让任何人通过远程方式访问或控制芯片。”</p> \n<p cms-style=\"font-L\">　　对于美方动辄将经贸科技问题政治化，滥用和泛化国家安全概念，中放多次强调，制裁、遏制、打压阻止不了中国发展，只会增强中国自立自强、科技创新的决心和能力。</p> \n<p cms-style=\"font-L\">　　“哪里有封锁，哪里就有突围；哪里有打压，哪里就有创新，”中共中央政治局委员、外交部长王毅在今年的两会记者会上表示，“小院高墙挡不住创新思维，脱钩断链最终将孤立自己。”</p> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250811s/546/w800h546/20250811/85c5-eb0c5d98be091c111eff0eec540e5975.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4294, NULL, '澳大利亚总理和新西兰总理会晤：中国非常重要，我俩最近都去过', 0, 4, 42, '2025-08-11 20:30:47', '2025-08-11 14:07:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/440/w550h690/20250811/81bd-635dc8411d35a9bf1e79d1c4fbedff17.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwqy8807352.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 王恺雯】当地时间8月9日，正在新西兰访问的澳大利亚总理阿尔巴尼斯与新西兰总理拉克森举行年度会晤。</p> \n<p cms-style=\"font-L\">　　这是阿尔巴尼斯2023年以来第二次访问新西兰，受到拉克森热情接待。据美联社报道，拉克森将澳大利亚称为新西兰“唯一的盟友”，并表示希望与澳大利亚建立更紧密的军事合作。</p> \n<p cms-style=\"font-L\">　　“我们一直非常重视与澳大利亚的协同作战能力，希望成为彼此的力量倍增器。”拉克森对记者表示。他补充说：“我们希望打造一支在本地区行动的、不可或缺的‘澳新军团（ANZAC）’。”</p> \n<p cms-style=\"font-L\">　　澳新军团是第一次世界大战期间，由澳大利亚和新西兰共同组建的陆军部队，在1915年的加里波利战役中首次参战，并成为两国军事合作的象征。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/440/w550h690/20250811/81bd-635dc8411d35a9bf1e79d1c4fbedff17.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月9日，新西兰皇后镇，新西兰总理拉克森和澳大利亚总理阿尔巴尼斯举行会晤。\">\n <span class=\"img_descr\">当地时间8月9日，新西兰皇后镇，新西兰总理拉克森和澳大利亚总理阿尔巴尼斯举行会晤。</span>\n <font cms-style=\"font-L\"> 拉克森X账号</font>\n</div> \n<p cms-style=\"font-L\">　　最近几个月来，澳大利亚方面频频炒作中国军舰在澳附近海域进行军演。澳大利亚广播公司（ABC）称，“中国在太平洋地区的存在”是阿尔巴尼斯和拉克森此次会谈的焦点之一。</p> \n<p cms-style=\"font-L\">　　会后的两国联合声明也提到一系列涉华议题，包括美中竞争和对话、南海及东海问题。声明还提到台海问题，称“（澳新）两国总理强调维护台海和平与稳定的重要性，呼吁通过对话和平解决两岸问题”。</p> \n<p cms-style=\"font-L\">　　据ABC报道，在阿尔巴尼斯和拉克森的联合记者会上，两人证实在会晤中讨论了中国及印太地区的安全问题，同时也提到他们近期都访问了中国这个重要的贸易伙伴。</p> \n<p cms-style=\"font-L\">　　“当然，地缘战略竞争，尤其是大国之间的竞争，是澳大利亚和新西兰共同讨论并在政治上进行合作的问题。”阿尔巴尼斯说。</p> \n<p cms-style=\"font-L\">　　拉克森表示，新西兰和澳大利亚在和中国的双边交往中“几乎遵循了相同的策略”。他强调：“中国是重要的世界大国，能够与其接触交流非常重要。”</p> \n<p cms-style=\"font-L\">　　“我们现在能够真诚地（与中国）进行对话，我认为这是非常成熟的对话，”拉克森表示，“坦率地说，我们有着非常不同的历史，不同的制度，不同的价值观，这意味着我们之间确实存在分歧。但好的伙伴不应该害怕谈论这些问题。”</p> \n<p cms-style=\"font-L\">　　“中国在全球是一个举足轻重的角色，是国际事务中的长期存在。”阿尔巴尼斯说。他重申：“我们的方针是，在可以合作的领域合作，在存在分歧的地方坚守立场。”</p> \n<p cms-style=\"font-L\">　　英国《卫报》称，除了涉华议题，澳大利亚和新西兰在加沙和美国关税问题上也保持统一步调。</p> \n<p cms-style=\"font-L\">　　拉克森和阿尔巴尼斯表示，以色列占领加沙城并进一步扩大在加沙地带军事行动的计划是错误的，这一举动可能违反国际法。</p> \n<p cms-style=\"font-L\">　　上个月，包括澳大利亚和新西兰在内的15国签署文件，重申“坚定不移地致力于两国解决方案”。不过，澳大利亚和新西兰尚未确定承认巴勒斯坦国的具体时间表。</p> \n<p cms-style=\"font-L\">　　据报道，对于美国总统特朗普可能因澳新两国承认巴勒斯坦国而对其实施贸易报复，阿尔巴尼斯和拉克森均表示，这不会影响他们的立场。</p> \n<p cms-style=\"font-L\">　　“我们对自己的经济和安全利益做出了自己的评估。”拉克森表示。阿尔巴尼斯回应道：“澳大利亚的立场完全相同。”</p> \n<p cms-style=\"font-L\">　　据澳大利亚特别广播服务公司（SBS）报道，阿尔巴尼斯9日表示，澳大利亚和新西兰面临着一个伴随着“地缘政治紧张、贸易问题和全球冲突”的充满不确定性的世界。</p> \n<p cms-style=\"font-L\">　　“但有一件事是确定的，那就是澳大利亚和新西兰始终站在一起。”阿尔巴尼斯说。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/440/w550h690/20250811/81bd-635dc8411d35a9bf1e79d1c4fbedff17.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4295, NULL, '美俄阿拉斯加峰会令欧洲担忧被边缘化：“可能成为历史的注脚”', 0, 4, 164, '2025-08-11 20:30:55', '2025-08-11 13:07:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250811s/54/w1024h1430/20250811/82f4-720c82b3f514e361440efe7f38137e82.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqwrc9715743.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　即将于8月15日举行的美俄领导人阿拉斯加峰会令欧洲国家非常担忧。</p> \n<p cms-style=\"font-L\">　　据新华社报道，欧盟外交与安全政策高级代表卡拉斯10日在接受媒体采访时表示，美国和俄罗斯之间关于结束俄乌冲突的任何协议都必须将乌克兰和欧盟考虑在内。英法德等6个欧洲国家领导人和欧盟委员会主席冯德莱恩9日晚发表联合声明说，唯有积极外交斡旋、继续支持乌克兰并施压俄罗斯，才有可能实现乌克兰和平与安全。</p> \n<p cms-style=\"font-L\">　　8月6日，特朗普与欧洲领导人通电话时曾表示计划与俄乌领导人会谈，但参与者不包括任何欧洲领导人。有报道称，目前欧洲国家对美俄两国的实质性谈判内容知之甚少，担忧其已经被特朗普政府排除在了乌克兰问题的谈判之外。匿名欧盟外交官员表示：“欧洲国家不认为美国政府会在乎欧洲国家的领土问题，因而对此深感不安。”</p> \n<p cms-style=\"font-L\">　　据悉，普京已向美国方面提交了俄乌冲突停火的提议，内容涉及交换乌克兰东部地区的领土。乌克兰总统泽连斯基9日指出，乌克兰不会将领土割让给俄罗斯，并且必须参与任何旨在结束战争的谈判。</p> \n<p cms-style=\"font-L\">　　当地时间10日，美国副总统万斯接受美国媒体采访时表示，美国正在安排普京与泽连斯基之间的会谈。但在特朗普与普京会面之前，俄乌领导人直接会谈不会有成效。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">欧洲提方案反对俄领土交换提议</font></p> \n<p cms-style=\"font-L\">　　欧盟和乌克兰官员称，在6日与美国中东问题特使威特科夫会谈期间，普京已向特朗普提出了一份停火提议，要求乌克兰全面放弃该国东部的顿巴斯地区（即顿涅茨克州和卢甘斯克州所在地区），以换取俄罗斯方面全面停火。报道称，威特科夫上周通过电话告诉欧洲盟友，上述提议表明普京正朝着和平的方向迈进，即使最终协议可能与俄罗斯领导人提出的方案有所不同。</p> \n<p cms-style=\"font-L\">　　报道还指出，普京没有坚持此前的部分立场，包括：乌克兰必须非军事化，更换泽连斯基政府，割让赫尔松和扎波罗热全部地区。</p> \n<p cms-style=\"font-L\">　　俄罗斯目前控制了顿涅茨克州的大部分地区和卢甘斯克州全境，但乌克兰军队仍然控制着顿涅茨克州的部分领土，其中包括该地区最重要的两座城市克拉马托尔斯克和斯拉维扬斯克。军事分析人士指出，尽管俄罗斯军队今年来在乌克兰东部地区取得一定程度的进展，但几乎不可能在短期内夺取上述两座城市。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250811s/54/w1024h1430/20250811/82f4-720c82b3f514e361440efe7f38137e82.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　美国智库战争研究所的分析指出，俄罗斯方面要求乌克兰军队撤出仍然控制的顿涅茨克州所有地区作为停火的前提，意味着乌克兰将被迫放弃该国在东部地区抵御俄罗斯进攻的主要防线，使乌克兰在未来更加难于抵御来自俄罗斯的攻击。</p> \n<p cms-style=\"font-L\">　　据了解谈判情况的欧洲官员透露，欧洲大国和乌克兰针对普京的停火计划提出了一项自己的提议。</p> \n<p cms-style=\"font-L\">　　欧洲的方案拒绝了俄罗斯提出的以乌克兰控制的顿涅茨克部分地区换取停火的提议。欧洲官员说，欧洲的目标是与乌克兰一起划出一条共同的红线，今后与俄罗斯的任何潜在谈判都必须遵守这条红线。</p> \n<p cms-style=\"font-L\">　　欧洲的提议包括在采取任何其他步骤前先停火。提议还说，领土交换只能以对等的方式进行，这意味着如果乌克兰军队从某些地区撤出，俄罗斯军队就必须从其他相应的地区撤出。关键一点是，欧洲的提议要求，基辅的任何领土让步都必须伴随可靠的安全保障——这包括乌克兰有可能成为北约成员国。</p> \n<p cms-style=\"font-L\">　　这些提议是在9日于英国举行的同美国高级官员的磋商会议上提出的。据参考消息援引美国《纽约时报》报道，由于担心在特朗普与普京即将举行的会晤上被边缘化，欧洲和乌克兰领导人9日在伦敦郊外与美国高级官员会面，一来是为了解普京的立场，二来是确保特朗普明白此事的利害关系。</p> \n<p cms-style=\"font-L\">　　两名了解会议情况、不愿透露姓名的欧洲官员表示，欧洲各国一如既往地支持乌克兰的立场，坚持以下几点：任何关于领土变更的谈判都必须以停火为前提；乌克兰不会将俄罗斯尚未占领的领土割让给俄方；任何协议都必须附带安全保障，其中包括来自美国的保障。</p> \n<p cms-style=\"font-L\">　　他们还坚称，华盛顿和莫斯科不能越过乌克兰人或欧洲人达成任何协议。此外，他们一如既往地强调，不会关闭乌克兰加入北约的大门，即便目前实现这一目标尚不现实。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“不可信任的对象”</font></p> \n<p cms-style=\"font-L\">　　芬兰总统斯图布9日致电特朗普，介绍上述欧洲倡议。斯图布在社交媒体上发文称：“欧洲与乌克兰团结一致，我们将继续与特朗普总统和美国密切合作。”德国总理默茨10日在接受电视采访时表示，欧洲领导人希望泽连斯基也能参加阿拉斯加会谈。</p> \n<p cms-style=\"font-L\">　　卡拉斯在会后给欧洲官员的一封信中表示：“脆弱的停火只会对俄罗斯有利，巩固他们的征服，并抑制乌克兰反击的机会……美国和俄罗斯之间的任何协议都必须包括乌克兰和欧盟，因为这事关乌克兰和整个欧洲的安全。”</p> \n<p cms-style=\"font-L\">　　然而，美国媒体分析指出，尽管欧洲国家希望支持和保护乌克兰，但他们目前只能寄希望于“恳求”特朗普政府。新华社援引美国《纽约时报》报道说，特朗普视欧洲为“不可信任的对象”。</p> \n<p cms-style=\"font-L\">　　美国智库卡内基国际和平基金会的赖姆·蒙塔兹将欧洲国家的政策称为“乘坐过山车”：“自特朗普今年1月就职以来，欧洲人就一直无限次购买‘特朗普过山车’的通行证。他们爬上去，系好安全带，不时发出惊恐的尖叫，却怎么也下不来。”</p> \n<p cms-style=\"font-L\">　　伦敦国王学院俄罗斯政治学教授萨姆·格林称，特朗普与普京就乌克兰领土问题进行谈判，可能会导致美欧联盟遭到分化。“如果你能让特朗普承认俄罗斯对其占领的大部分领土拥有主权，并让他明白乌克兰人和欧洲人可能不会参与其中，那么你就会在美国和欧洲之间造成长期隔阂。”</p> \n<p cms-style=\"font-L\">　　一位因未获授权公开发言而拒绝透露姓名的欧洲外交官告诉美国媒体：“我们有可能成为历史的注脚。”</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250811s/54/w1024h1430/20250811/82f4-720c82b3f514e361440efe7f38137e82.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4296, NULL, '哥伦比亚总统反对美国以缉毒名义干涉拉美国家主权', 0, 4, 43, '2025-08-11 20:31:06', '2025-08-11 11:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/761/w960h601/20250811/d2f0-2ce0b5ffa5950d76b0b9460a3b6fc5dc.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqsif9798474.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/761/w960h601/20250811/d2f0-2ce0b5ffa5950d76b0b9460a3b6fc5dc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△哥伦比亚总统佩特罗（资料图）\">\n <span class=\"img_descr\">△哥伦比亚总统佩特罗（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　哥伦比亚总统佩特罗10日在社交媒体平台上发文，明确反对美国以缉毒为名干涉拉美地区国家主权。</p> \n<p cms-style=\"font-L\">　　“哥伦比亚与委内瑞拉同属一个民族、一面旗帜、一段历史。”佩特罗表示，“任何未经兄弟国家批准的军事行动，都是对拉丁美洲和加勒比地区的侵犯。这从根本上违背了我们的自由原则。”</p> \n<p cms-style=\"font-L\">　　当日早些时候，佩特罗在社交媒体平台上回应了一段有关委内瑞拉的视频。视频中，委内瑞拉反对美国借打击毒品贩运之名，企图干涉委内瑞拉内政。</p> \n<p cms-style=\"font-L\">　　9日，佩特罗还在社交媒体平台上表示，他的政府愿意与美国以及任何希望加强打击贩毒组织的国家合作，但前提是尊重国家主权。</p> \n<p cms-style=\"font-L\">　　美国政府7日悬赏5000万美元缉拿委内瑞拉总统马杜罗，宣称其涉嫌通过犯罪组织向美国输送毒品。委方谴责美国再次尝试粗暴干涉委内政，扰乱其和平稳定。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/761/w960h601/20250811/d2f0-2ce0b5ffa5950d76b0b9460a3b6fc5dc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4297, NULL, '新西兰称考虑承认巴勒斯坦国 将在9月正式决定', 0, 4, 143, '2025-08-11 20:31:11', '2025-08-11 11:03:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/a966-b980057eb7ed2a9467e7eea4a66e0c9a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkqsif9805060.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/a966-b980057eb7ed2a9467e7eea4a66e0c9a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△新西兰外交部长彼得斯（资料图）\">\n <span class=\"img_descr\">△新西兰外交部长彼得斯（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　据新西兰政府当地时间8月11日发表的声明，新西兰外交部长彼得斯表示，<font cms-style=\"font-L strong-Bold\">该国考虑承认巴勒斯坦国，并将于9月作出正式决定</font>。</p> \n<p cms-style=\"font-L\">　　近日，多个国家相继表示将承认巴勒斯坦国。7月29日，法国外交部长巴罗与安道尔、澳大利亚、加拿大、芬兰、冰岛、爱尔兰、卢森堡、马耳他、新西兰、挪威、葡萄牙、圣马力诺、斯洛文尼亚和西班牙14个国家外长发表联合声明，表示“愿意承认巴勒斯坦国”，并邀请尚未表态承认的国家加入这一集体呼吁。8月11日，澳大利亚总理阿尔巴尼斯召开新闻发布会，宣布澳大利亚将在9月召开的联合国大会上承认巴勒斯坦国。</p> \n<p cms-style=\"font-L\">　　（总台记者 姚瑞昕）</p> \n<!--article_adlist[<p cms-style=\"font-L strong-Bold align-Center\"></p>]article_adlist--> \n<p></p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250811/213/w2048h1365/20250811/a966-b980057eb7ed2a9467e7eea4a66e0c9a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4298, NULL, '广西一女孩考上清华大学，学校奖励100万元，校方：属实', 0, 1, 20, '2025-08-11 20:33:07', '2025-08-11 17:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/409/w550h659/20250811/f199-e91a9a2ff319445783437e489a2bb626.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkraww8796286.shtml', '大象新闻', '<p>　　来源：大象新闻</p> \n<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　近日，广西贵港一女生考上清华大学，高中奖励其100万元奖学金，引发关注。该校工作人员表示情况属实，奖学金金额依据毕业生录取大学的全国排名而定。</p> \n<p>　　视频显示，贵港市大将国际学校颁奖大会上，一名女生站在台上，手里拿着一张“清华大学奖学金100万元”的奖金牌，面前的小凳子上摆着厚厚几沓百元现金。8月11日，九派新闻就此事询问贵港市大将国际学校党政办，对方工作人员表示情况属实。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/409/w550h659/20250811/f199-e91a9a2ff319445783437e489a2bb626.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"女孩站在台上领奖。图/长天新闻\" data-link=\"\">\n <span class=\"img_descr\">女孩站在台上领奖。图/长天新闻</span>\n</div> \n<p>　　九派新闻以市民身份询问该校招生办，一工作人员称被985、211和“双一流”学校录取的学生才会获得升学奖励，“要求是211以上的大学，具体的奖学金金额依据毕业生录取大学的全国排名而定，每年政策不同。”</p> \n<p>　　九派新闻注意到，该校2022年高考升学奖励措施类别中，考上清华大学、北京大学、香港大学，奖学金30万-50万元/人，考取其他一本大学并就读的3000元/人。</p> \n<p>　　据其公众号介绍，贵港市大将高级中学在校学生8000多人，教师500多人。过去几年间，学校的学考通过率始终保持在98%以上，连续多年荣获“高考质量提升一等奖”。2021年6月，学校经自治区评估确认为自治区示范性高中。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/transform/409/w550h659/20250811/f199-e91a9a2ff319445783437e489a2bb626.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4299, NULL, '云南省委书记的“五问”', 0, 1, 25, '2025-08-11 20:34:50', '2025-08-11 12:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/36f5-12ef6fc6cee04a3b82750e834f6fa02b.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrawx5854289.shtml', '北京青年报', '<p>　　来源：北京青年报</p> \n<p cms-style=\"font-L strong-Bold align-Center\">　　编辑 | 董鑫</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">据《云南日报》消息，《云岭之窗》杂志刊发云南省委书记王宁</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">2025</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">年</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">6</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">月</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">26</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">日在全省巩固拓展脱贫攻坚成果同乡村振兴有效衔接工作会议上的讲话。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">王宁表示，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">过渡期以来，经过不懈努力，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">云南</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">消除了人均纯收入</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">1</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">万元以下的脱贫户，为实现</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“3815”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">战略发展目标</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">（即三年上台阶、八年大发展、十五年大跨越）</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">三年上台阶</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">奠定了基础。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">过渡期以来，全省农民收入年均增长8%、脱贫县农民收入年均增长8.6%，均高于全省经济增速。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">截至去年底，全省农村劳动力转移就业1547万人，带动工资性收入增长6.5%，其中脱贫人口县内务工154万人。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">巩固脱贫成果，根本在于农民增收。站在新的起点上，要进一步回答好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">群众持续增收之问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">。认真思考和回答好</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">乡村产业怎么富民、就业怎么拓展、</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">农村改革怎么深化、</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">美丽乡村怎么建好、</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">防返贫的底线怎么越筑越牢</font><font cms-style=\"font-L\">这5个问题。</font></font></font></font></font></font></font></font></font></p> \n<p cms-style=\"font-L\">　　心里要始终想着群众的问题，多问一问自己，为农民增收、为百姓生计、为乡村振兴，应该谋划什么、抓好什么，经常看看是否问准了、答对了、干好了。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/36f5-12ef6fc6cee04a3b82750e834f6fa02b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">讲话摘编如下：</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">巩固脱贫成果，根本在于农民增收。过渡期以来，经过不懈努力，我省消除了人均纯收入</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">1</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">万元以下的脱贫户，为实现</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“3815”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">战略发展目标</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">三年上台阶</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">奠定了基础。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">站在新的起点上，我们要进一步回答好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">群众持续增收之问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">。也就是过渡期之后，巩固脱贫成果怎么办？群众增收靠什么？收入的增长点在哪里？</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">为此，从省里开始，到各州（市），再到各县（市、区），一直到乡镇和村，都要用好省委提出和倡导的</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">主动想、扎实干、看效果</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">这一工作方法，问一问怎么办，以</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">入手、以</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">破题，认真思考和回答好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">5</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">个问题，问出思路、问出办法、问出创新、问出成果成效，这也是下步工作的努力方向。</font></font></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">一</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">乡村产业怎么富民？</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">产业是群众增收最重要的基础。</font><font cms-style=\"font-L strong-Bold\">大家要思考和回答，乡村产业怎么从有资源到有产品、从有优势到有品牌、从传统到现代？</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">实现从有资源到有产品，就要做好资源转换文章。云南的资源十分丰富，要以资源换产业。这种转换既可以是种植新作物，也可以是提升现有的品种。</font><font cms-style=\"font-L strong-Bold\">只要我们用好资源、选准赛道，高原特色农业发展之路一定会越走越宽。各地尤其是县、乡、村三级要好好盘一盘农业资源的账，看一看自己有什么、能够做什么。</font></p> \n<p cms-style=\"font-L\">　　要组织力量专门研究全国各地有哪些高附加值的农业品种、我省有哪些地方可以种、怎样试验推广，拿出具体方案，指导各地引进发展。有条件的州（市）要研究世界上有什么好品种，论证后也可以试种，推广那些价值高的、受市场欢迎的品种。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">实现从有优势到有品牌，关键要做好品牌培育文章。云南的农产品都是绿色、生态、高品质的，</font><font cms-style=\"font-L strong-Bold\">但</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">酒香也怕巷子深</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">，只有注重品牌建设，好东西才能卖得出好价格，农产品才有大市场。</font><font cms-style=\"font-L\">要培育一批各具特色、有影响力的区域公用品牌，大力支持企业打造产品品牌。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">实现从传统到现代，就要做好科技兴农文章。依靠科技发展现代农业，一个重点就是设施农业。今年，国家将设施农业更新改造纳入</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">两新</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">政策支持范围。各地要做好项目谋划，争取花卉、蔬菜、小浆果等领域的高端设施化率有明显提升。</font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/cef7-9a9cdf1e1cc97a68cf9f4bd67efeb2d8.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△丽江现代花卉产业园内的鲜花长势良好\" data-link=\"\">\n <span class=\"img_descr\">△丽江现代花卉产业园内的鲜花长势良好</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">二</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">就业怎么拓展？</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">大家要认真思考，如何加强就业服务，拓展就业空间？既抓好外出务工，也促进就地就近就业。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">关于外出务工方面。全省每年有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">700</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">万名农民外出务工，其中到省外的有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">400</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">万人。要精准对接需求，做好就业、用工需求的信息归集和发布，提高劳务输出的组织化程度。要加强技能培训，有针对性地开展建筑、维修、家政、餐饮等相关职业技能培训，</font><font cms-style=\"font-L strong-Bold\">让农民掌握</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">一技之长</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">，提高工资收入</font><font cms-style=\"font-L\">。要维护劳动权益，进一步完善农民工工资监管机制，</font><font cms-style=\"font-L strong-Bold\">保障劳有所得。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">关于就地就近就业方面。要承接产业转移。我省农村劳动力富足，这是我们的优势。各地要抓住机遇，积极发展劳动密集型产业，扩大县域就业容量。要加大返乡创业支持力度，为农民工、大学生返乡创业搭建平台。要建好零工市场。随着我省产业逐步壮大，临时性的用工需求也多了起来。各地要探索建设更多的零工市场，用好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">幸福里</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">就业服务平台，支持农民多渠道灵活就业。</font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/46/w550h296/20250811/c6cb-fbf64de824c62c1dfcf21784cf9984df.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△昆明市呈贡区的卧龙古渔村成了乡村旅游胜地\" data-link=\"\">\n <span class=\"img_descr\">△昆明市呈贡区的卧龙古渔村成了乡村旅游胜地</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">三</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">农村改革怎么深化？</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">去年，党的二十届三中全会出台了很多农村改革举措。比如，完善农村基本经营制度、加强扶贫资产管理等。</font><font cms-style=\"font-L strong-Bold\">大家要思考，如何抓好这些改革落地，唤醒沉睡的农村资产，拓宽农民增收渠道？</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">深化集体林权制度改革，向林地要效益、要增收。</font><font cms-style=\"font-L strong-Bold\">我省有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">3.75</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">亿亩林地，目前仅利用了</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">5000</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">多万亩，还有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">1</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">亿多亩可开发利用，值得好好探索。</font><font cms-style=\"font-L\">楚雄州姚安县通过林下种植花卉，不仅带动</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">3600</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">户农民增收，还有效破解了种花缺地的瓶颈。要总结推广各地的创新做法，加强统筹指导，大力发展林下经济。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">管好用好帮扶项目，推动</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">家门口</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">的资产用起来、活起来。</font><font cms-style=\"font-L strong-Bold\">脱贫攻坚以来，我省实施了一大批帮扶项目，仅经营性项目就有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">1.78</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">万个，用好这些资产，可以极大促进农民增收。</font></font></font></p> \n<p cms-style=\"font-L\">　　大理州漾濞县阿尼么村用好沪滇协作项目，促进农文旅深度融合，这种做法模式好、业态新、带富强。各地要认真学习借鉴，盘活用好各类资产，使之成为农民增收致富的重要依托。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/3135-3af91c753c5363ce53613d3f11b8d8a6.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△大理州漾濞县阿尼么村\" data-link=\"\">\n <span class=\"img_descr\">△大理州漾濞县阿尼么村</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">四</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">美丽乡村怎么建好？</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">乡村美起来，才能吸引人、留住人，发展才有活力。</font><font cms-style=\"font-L strong-Bold\">大家要认真思考，现代化的乡村，应该是什么样子？怎么才能建好？让农村既留得住乡愁，又有现代化的生活，更有文明和谐的乡风。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">做好村庄规划。农房怎么建、设施怎么布、耕地红线和生态底线怎么守？都要通过规划明确下来。定了规划，就要认真执行。需要强调的是，规划编制要实事求是，尊重农民意愿、体现特色风貌。</font><font cms-style=\"font-L strong-Bold\">我省有</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">777</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">个中国传统村落、数量全国第</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">1</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">，这是宝贵的文化财富和旅游资源。各地要把保护放在第一位，防止拆真建假、失管失修，在保护中促发展。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">提升环境和服务。各地要深化绿美村庄建设，发动群众在房前屋后、村庄道路种树，留住青山绿水、田园风光。</font><font cms-style=\"font-L strong-Bold\">要积极回应和解决群众上学看病、养老抚幼等关切，持续做好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">一老一小</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">和残疾人关爱服务。</font><font cms-style=\"font-L\">要积极引导有条件的村，弘扬守望相助、扶危济困的传统美德，关心扶持低收入群众，帮扶弱势群体，共享发展成果。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">加强乡村治理。农村</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">硬件</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">上去了，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">软件</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">也要跟上，做好滋润人心、德化人心、凝聚人心的工作。</font><font cms-style=\"font-L strong-Bold\">要持续推进移风易俗，重点治理铺张浪费、酗酒斗气等陋习。</font><font cms-style=\"font-L\">要多组织一些群众性文体活动，丰富村民精神文化生活。要持续抓好农村普法宣传和命案防控，</font><font cms-style=\"font-L strong-Bold\">严厉打击赌博、诈骗、传销等违法犯罪，</font><font cms-style=\"font-L\">让广大农民安居乐业。</font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/68/w550h318/20250811/f562-2e716a45801c79aafa5fb26461882d1d.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△永仁县莲池乡查利么“幸福里”社区\" data-link=\"\">\n <span class=\"img_descr\">△永仁县莲池乡查利么“幸福里”社区</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">五</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">防返贫的底线怎么越筑越牢？</font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">进入常态化帮扶阶段，工作要求不是低了，而是更高了；工作责任不是轻了，而是更重了。</font><font cms-style=\"font-L strong-Bold\">大家要认真思考，如何抓实抓细常态化帮扶工作？长久守住不发生规模性返贫致贫底线，让各族群众的生活更上一层楼。</font></p> \n<p cms-style=\"font-L\">　　在优化监测帮扶机制上下功夫。发现和消除返贫致贫风险，监测是基础，要及时响应、应纳尽纳；帮扶是关键，要务实精准、应扶尽扶，稳定消除风险。要推进行业部门数据共享，建立统一的监测系统，统一识别口径，提高监测和帮扶效能。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">在用好协作帮扶机制上下功夫。这些年，中央定点帮扶单位和上海市投入资金、引进企业、选派干部人才，给予云南大力支持和帮助。</font><font cms-style=\"font-L strong-Bold\">各地各相关部门要主动对接，把我们的资源与他们的技术、资金、人才、管理、市场等有效</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">嫁接</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">起来，积极承接东部地区产业梯度转移。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">要管好用好衔接资金、帮扶资金，更多投向产业培育、投向联农带农、投向稳岗就业，发挥好</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">造血</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">的功能。</font><font cms-style=\"font-L strong-Bold\">加强各类帮扶资金、项目、资产的监管，决不允许在这上面动</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">歪脑筋</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">在激发群众内生动力上下功夫。乡村振兴为农民而兴，也必须靠农民而兴。各地要建立</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">以效定补</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">等激励机制，倡导多干多补、少干少补、不干不补，</font><font cms-style=\"font-L strong-Bold\">防止政策</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">养懒汉</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">。坚持</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">富脑袋</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">和</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">富口袋</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">并重</font><font cms-style=\"font-L\">，培育和树立勤劳致富先进典型，引导广大农民靠自我奋斗，过上更加幸福的生活。</font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/06a3-6515da809d3926d11dbd9bbc4087a889.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△中央教育人才组团帮扶马关县第一中学\" data-link=\"\">\n <span class=\"img_descr\">△中央教育人才组团帮扶马关县第一中学</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">以上这</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“5</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">，是</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">群众持续增收之问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">的具体化，问和答的最终目的，是要让各族群众日子越过越好。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">这</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“5</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">是省委对大家的要求，州、县、乡、村各级</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">一把手</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">也要结合实际，心里要始终想着群众的问题，多问一问自己，为农民增收、为百姓生计、为乡村振兴，应该谋划什么、抓好什么，经常看看是否问准了、答对了、干好了。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">“</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">三农</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">”</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">战线的广大干部要发扬脱贫攻坚精神，不断提高政策水平和专业本领，</font><font cms-style=\"font-L strong-Bold\">多下基层、多跑田埂、多进农家，为农民解决实际问题</font><font cms-style=\"font-L\">。千斤重担众人挑，每个人都要拿出担当、拿出状态、拿出干劲，把各项工作扎扎实实做到位。</font></font></font></p> \n<p cms-style=\"font-L\">　　脱贫攻坚创造了彪炳史册的人间奇迹，靠的是实打实、硬过硬。我们要更加紧密地团结在以习近平同志为核心的党中央周围，守底线、抓巩固、促振兴，奋发进取、真抓实干，推动农业基础更加稳固、农村地区更加繁荣、农民生活更加红火，朝着共同富裕目标一步一步扎实迈进。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/36f5-12ef6fc6cee04a3b82750e834f6fa02b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/cef7-9a9cdf1e1cc97a68cf9f4bd67efeb2d8.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/46/w550h296/20250811/c6cb-fbf64de824c62c1dfcf21784cf9984df.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250811/3135-3af91c753c5363ce53613d3f11b8d8a6.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/68/w550h318/20250811/f562-2e716a45801c79aafa5fb26461882d1d.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/06a3-6515da809d3926d11dbd9bbc4087a889.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4300, NULL, '广西百色农林投资发展集团有限公司原党委书记、董事长唐星善严重违纪违法被开除党籍和公职', 0, 2, 222, '2025-08-11 20:35:15', '2025-08-11 10:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmze8970456.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　据百色市纪委监委消息：经百色市委批准，百色市纪委监委对广西百色农林投资发展集团有限公司原党委书记、董事长唐星善严重违纪违法问题进行了立案审查调查。</p>\n<p cms-style=\"font-L\">　　经查，唐星善丧失理想信念，背弃初心使命，搞封建迷信活动；违反中央八项规定精神，违规收受礼品、礼金，接受可能影响公正执行公务的旅游活动安排；以权谋私，利用职务便利为他人在项目推进、工程承揽、工程款拨付等方面谋利，并非法收受巨额财物。</p>\n<p cms-style=\"font-L\">　　唐星善严重违反党的政治纪律、廉洁纪律和生活纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予严肃处理。依据《中国共产党纪律处分条例》《中华人民共和国监察法》《中华人民共和国公职人员政务处分法》等有关规定，经百色市纪委常委会会议研究并报百色市委批准，决定给予唐星善开除党籍处分；由百色市监委给予其开除公职处分；收缴其违纪违法所得；将其涉嫌犯罪问题移送检察机关依法审查起诉，所涉财物一并移送。（百色市纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4301, NULL, '暴雨黄色预警：5省市部分地区有大暴雨 重庆等局地特大暴雨', 0, 1, 22, '2025-08-11 20:35:23', '2025-08-11 10:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/387/w650h537/20250811/4594-9c1d08ddeb12ab19fd37582ce4575768.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkqmzi9924302.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：中央气象台8月11日10时继续发布暴雨黄色预警：</p>\n<p cms-style=\"font-L\">　　预计，8月11日14时至12日14时，重庆大部、四川南部、云南北部、贵州北部和中部、湖北南部和东部、湖南西北部、安徽中部、江苏中部以及甘肃中部、内蒙古东部等地部分地区有大到暴雨，其中，重庆东部、贵州东北部、湖北西南部、湖南西北部、江苏中部等地部分地区有大暴雨，重庆东南部等地局地特大暴雨（250～260毫米）。上述部分地区伴有短时强降水（最大小时降雨量20～50毫米，局地可超过70毫米），局地有雷暴大风等强对流天气。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250811/387/w650h537/20250811/4594-9c1d08ddeb12ab19fd37582ce4575768.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　防御指南：</p>\n<p cms-style=\"font-L\">　　1、政府及相关部门按照职责做好防暴雨工作；</p>\n<p cms-style=\"font-L\">　　2、交通管理部门应当根据路况在强降雨路段采取交通管制措施，在积水路段实行交通引导；</p>\n<p cms-style=\"font-L\">　　3、切断低洼地带有危险的室外电源，暂停在空旷地方的户外作业，转移危险地带人员和危房居民到安全场所避雨；</p>\n<p cms-style=\"font-L\">　　4、检查城市、农田、鱼塘排水系统，采取必要的排涝措施。</p>', '[\"https://k.sinaimg.cn/n/spider20250811/387/w650h537/20250811/4594-9c1d08ddeb12ab19fd37582ce4575768.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4302, NULL, '美媒：美俄领导人会晤地点或在阿拉斯加阿尔耶斯卡度假村', 0, 4, 207, '2025-08-11 21:30:26', '2025-08-11 20:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250811s/259/w800h259/20250811/e0e0-05c773d64e1fe491a029e071dbe90426.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-08-11/doc-infkrier0319393.shtml', '新京报', '<p cms-style=\"font-L\">　　据新华社旧金山8月11日电　据美国“阿拉斯加地雷”网站11日报道，美国总统特朗普和俄罗斯总统普京可能在美国阿拉斯加州度假小镇格德伍德的阿尔耶斯卡度假村会晤。</p> \n<p cms-style=\"font-L\">　　该网站在社交媒体上写道：“得到消息说，特朗普与普京的会晤可能在格德伍德的阿尔耶斯卡度假村举行。有趣的是，8月12日至16日这段时间在他们的预订日历上完全被涂掉了。”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250811s/259/w800h259/20250811/e0e0-05c773d64e1fe491a029e071dbe90426.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　今日俄罗斯通讯社转发美国“阿拉斯加地雷”网报道，但这一消息尚未得到美俄两国官方证实。</p> \n<p cms-style=\"font-L\">　　此前，美俄双方宣布，两国领导人将于15日在阿拉斯加举行会晤，但没有公布具体地点。</p> \n<p cms-style=\"font-L\"></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250811s/259/w800h259/20250811/e0e0-05c773d64e1fe491a029e071dbe90426.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4303, NULL, '践行“两山”理念 建设美丽新疆丨四万亩荒漠长出“黄金草”', 0, 1, 31, '2025-08-11 21:31:08', '2025-08-11 20:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/799/w550h249/20250811/b308-f5bd1097c53cc693899f68cf00b08c84.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrpnp0195682.shtml', '石榴云', '<p>　　来源：石榴云</p> \n<p>　　北纬47度，曾是吉木乃县地图上一道醒目的黄褐色印记。这片被风沙裹挟的土地，一度因过度放牧和干旱退化，成为沙漠化问题较为突出的区域。</p> \n<p>　　如今，这里的4万亩荒漠，在科学技术的加持下，成为亩产干草超1000公斤的牧草“黄金带”，书写着荒漠逆袭的生态奇迹。</p> \n<p>　　从荒漠到“黄金带”：</p> \n<p>　　科技破解草场困局</p> \n<p>　　眼下，正值第三茬牧草收割关键期，位于吉木乃县万驼园的4万亩牧草地里，收割机来回穿梭，成捆的牧草在田垄间码成方阵，不远处的公路上，挂着“蒙”“宁”“甘”等牌照的重型卡车排成长龙，司机们等着将这批刚收割的优质牧草运出边境小城。</p> \n<p>　　“第三茬牧草品质照样好，蛋白质含量差不了，牲畜适口性也好。”恰勒什海乡达冷海齐村牧民叶尔达吾·米拉木别克说。</p> \n<p>　　谁能想到，这片亩产超1000公斤干草的“黄金带”，曾是连牛羊都不愿光顾的退化草场。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/799/w550h249/20250811/b308-f5bd1097c53cc693899f68cf00b08c84.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　7月中旬，吉木乃县优质牧草在装车，计划运往宁夏、甘肃等地。董发勇摄</p> \n<p>　　吉木乃县的草场困局，是西北干旱区生态与发展矛盾的缩影。作为传统畜牧业大县，吉木乃县有905万亩天然草场，但51.34%的土地面临沙化威胁，“守着草场缺草料”的局面使得养殖户不得不高价从外地采购草料，极大制约了当地畜牧业转型升级和农牧民增收致富。</p> \n<p>　　2024年1月，中央组织部、共青团中央第24批博士服务团成员杨海军来到吉木乃县，如何在生态脆弱的边境地区让生态与产业协同发展实现共赢，成为摆在他面前的重大课题。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/53/w550h303/20250811/790f-596424cb57d0a08709f2126c5cd0af95.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　7月10日，中央组织部、共青团中央第24批博士服务团成员杨海军（中）在给工作人员讲解通过禾本科和豆科草种的组合实现资源的有效利用。李森摄</p> \n<p>　　凭借多年的科研积淀，杨海军深谙科技是破局之钥。他带领团队邀请自治区优质饲草产业技术体系、新疆农业大学、中国科学院植物研究所等单位的专家学者组成联合调研组，深入吉木乃县草场开展实地调研。最终，饲草产业被定为破题的钥匙，并创新推出禾本科+豆科6种牧草“免耕混播”技术，在最大程度保护草原原生植被的基础上，实现多草种共生，优化植物群落结构，提高生物多样性和生产力。</p> \n<p>　　“通过特制播种机将草种精准植入土层，实现‘微扰动、根系全保留’原生植被保护。经检测，混播牧草粗蛋白质含量高达21.3%，远超普通牧草15%的行业标准，成为名副其实的牲畜‘黄金营养源’。”杨海军介绍。</p> \n<p>　　饲草产业崛起：</p> \n<p>　　生态与经济的双向突破</p> \n<p>　　“第一茬牧草长出来时，牧民都来看了。”8月9日，吉木乃县农业农村局二级主任科员杨运发回忆。</p> \n<p>　　2024年5月，在自治区优质饲草产业技术体系的支持下，当地开展了1500亩天然草原免耕补播改良和生产力提升试点，原本裸露的沙丘冒出成片新绿。监测数据显示，补播区域植被盖度从不足30%跃升至80%。更意外的是，免耕技术让水分利用效率提高30%，在年降水量仅180毫米的吉木乃县北沙窝区域，免耕混播技术以“锁水魔法”实现生态跃迁，驱动贫瘠沙地蜕变，涵水固碳、生产力提升等功能得以充分发挥。</p> \n<p>　　如今，4万亩免耕补播的天然草场上，紫花苜蓿、红豆草、沙打旺等与原生植被混生，在科学管护下，实现一年四茬收割，亩产干草突破1000公斤，产草量较传统天然草场提升了10倍以上。</p> \n<p>　　眼下正是当地牧民储备优质饲草的最佳季节。今年吉木乃县气候干旱，天然草场牧草受旱情影响，长势较差，但4万亩优质牧草可有效抵御气候波动对畜牧业生产带来的影响。</p> \n<p>　　“今年天气干旱，雨水少，山上的草长得不好，要是过去，牛羊冬季是不够吃的。但现在县里有饲草基地了，我们也不担心了。”乌拉斯特镇乌拉斯特村牧民哈依那尔·阿达力说。</p> \n<p>　　当地政府通过“惠民饲草直供”政策，以低于市场价的价格将饲草出售给当地牧民，切实降低其越冬成本。</p> \n<p>　　以草为媒：</p> \n<p>　　铺就兴边富民可持续发展之路</p> \n<p>　　饲草产业的增长，让吉木乃重新审视自己的区位优势。吉木乃口岸距离哈萨克斯坦东哈州斋桑县仅60公里，东哈州拥有广袤的农田，“他们有土地和水，我们有技术和市场，合作是必然的。”吉木乃边境经济合作区（吉木乃农业对外开放合作试验区）党工委委员、管委会副主任周存合介绍。</p> \n<p>　　在吉木乃边境经济合作区（吉木乃农业对外开放合作试验区）3.76万平方米的饲草储备库里，从哈萨克斯坦进口的300吨牧草被加工成颗粒。“温水一泡，就成了可饲牧草。”周存合介绍，依托“境外种植+境内加工”模式，预计年加工产能达15万吨。</p> \n<p>　　从生态痛点到经济增长点的转变，在数据上尤为直观。今年上半年，吉木乃县饲草产业带动就业500余人次，产值突破3780万元。“苜蓿品质好，蛋白质含量高，叶片也完整，早早就与疆外客商达成销售意向。以前怕草场长不出草，现在怕草太多运不走。”吉木乃县农业农村局副局长郑婷婷说。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/799/w550h249/20250811/67d2-bcd6c277b21a16a72935775289bd4627.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　7月中旬，吉木乃县4万亩牧草在有序进行第三茬收割。董发勇摄</p> \n<p>　　根据相关规划，吉木乃县计划在未来几年将人工牧草面积扩大至28.5万亩，进一步提升饲草产业规模和效益。</p> \n<p>　　饲草产业的蓬勃发展，不仅让吉木乃县的戈壁穿上了绿色生态外衣，更成为撬动乡村振兴的有力支点。“未来，我们将以饲草产业为支点，撬动‘生态—生产—生活’三生融合，助力乡村振兴，走出一条以草固沙、以草富民、以草兴边的可持续发展之路，让祖国的西北角既看得见绿水青山，更守得住幸福平安。”杨海军说。</p> \n<p>　　从退化草场到牧草“黄金带”，这片土地的逆袭，不仅是一片草场的重生，更是边境地区在生态与发展的平衡中探索出的可持续路径，书写着人与自然和谐共生、生态富民的新篇章。</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/799/w550h249/20250811/b308-f5bd1097c53cc693899f68cf00b08c84.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/53/w550h303/20250811/790f-596424cb57d0a08709f2126c5cd0af95.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/799/w550h249/20250811/67d2-bcd6c277b21a16a72935775289bd4627.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4304, NULL, '北京机器人产业稳居国内第一梯队', 0, 1, 1, '2025-08-11 22:30:17', '2025-08-11 22:10:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/117/w550h367/20250811/c795-f3dd7f9709e35fe74024df862153d55c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrpnp0223744.shtml', '北京日报客户端', '<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/117/w550h367/20250811/c795-f3dd7f9709e35fe74024df862153d55c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\" data-link=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　本报记者 曹政</p> \n<p cms-style=\"font-L\">　　“到2025年，培育100种高技术高附加值机器人产品、100种具有全国推广价值的应用场景”——2023年，北京推出第二轮机器人产业创新发展行动方案时，提出了“双百工程”的建设目标。两年多时间过去了，“双百”目标超额完成。</p> \n<p cms-style=\"font-L\">　　昨天，在世界机器人大会主论坛上，市经信局局长姜广智介绍了“双百工程”成果：本市已支持形成了12类200项机器人创新产品，支持机器人创新产品在11个领域134个场景完成首试首用和迭代升级，北京机器人产业稳居国内第一梯队。</p> \n<p cms-style=\"font-L\">　　连创三个“全国第一”</p> \n<p cms-style=\"font-L\">　　AI技术将手术前规划周期从数周压缩至分钟级，还能实时模拟骨骼运动状态，结合亚毫米级导航定位与机械臂，实现对髋膝假体植入位置及角度的精准控制，降低远期并发症风险——本届大会的长木谷展区里，一款骨科手术机器人让不少观众感叹：“没想到机器人已经进手术室了！”</p> \n<p cms-style=\"font-L\">　　几乎每年世界机器人大会，北京长木谷公司都会带新品前来首发。该公司董事长张逸凌透露，今年首发的新一代ROPA骨科智能手术机器人搭载了人工智能系统，脑、眼、手都比以往更“聪明”，打破了传统骨科手术各环节割裂的难题，实现了从三维重建、智能规划到精准执行与数智评估的全流程一体化操作。</p> \n<p cms-style=\"font-L\">　　年年上新代表着澎湃的创新活力。姜广智透露，目前，北京已经培育了57家机器人专精特新“小巨人”企业，获批33个手术机器人注册证，集聚人形机器人产业整机单位近30家，均居全国首位。所形成的200项机器人创新产品中，医疗领域成果颇丰：天智航天玑骨科手术机器人实现了一机多适应症，并可通过5G远程手术；术锐机器人自主研发的单孔蛇形臂手术机器人可在患者体内实现多个自由度全域运动，处于世界领先水平，也是国内首款覆盖四大外科的单孔机器人。</p> \n<p cms-style=\"font-L\">　　“‘双百工程’中的‘百项机器人新品工程’将人形机器人作为核心领域进行谋划和布局，带动协作、医疗、特种、物流四类优势机器人跃升发展，高端产品体系基本形成。”姜广智说，去年北京机器人产业营收同比增长50%，今年上半年又实现40%的增长。</p> \n<p cms-style=\"font-L\">　　134个场景里首试首用</p> \n<p cms-style=\"font-L\">　　今年的世界机器人大会专门设置了会客厅，会客厅外排队等候入场的观众队伍绕了三道弯，不少家长都带着孩子一起参观。“孩子觉得有趣好玩，而我想看看未来生活的每个场景。”市民郭贝贝抱起三岁的孩子，挨个儿跟会客厅里的机器人合影。</p> \n<p cms-style=\"font-L\">　　会客厅里，星海图“R1 Pro”机器人正在“卖”机器人，仿人机器人“小柒”热情地和人打招呼，可乐机器人、饮料机器人、薯条机器人等正在制作“赛博美食”，会射箭、下棋的各种机器人引来人们围观互动，20家企业、26个机器人展品让人目不暇接，展开了“机”智生活的新图景。</p> \n<p cms-style=\"font-L\">　　有了机器人，用在哪儿？这个难题困扰不少机器人企业。为此，本市实施“百种应用场景示范工程”，发挥北京超大城市场景丰富优势，加大场景创新和供需对接力度，支持机器人在11个领域134个场景里首试首用，不同领域的机器人应用深度和广度都持续拓展。会客厅正是这些场景的浓缩。</p> \n<p cms-style=\"font-L\">　　目光从会场移至整座城市，机器人公园里形成了生态巡护、消杀、水面清洁、库面清扫等6款机器人的解决方案，通过融资租赁的方式在市属公园和园博馆推广应用了104台；机器人课堂初步形成课堂学伴、老师助教、课间玩伴和物品运送4类方案，先后在14所中小学部署了38台机器人；机器人美食则囊括拉花咖啡机器人、智能鲜饮站、煎饼机器人和炒菜机器人等，在京部署应用了210余台。</p> \n<p cms-style=\"font-L\">　　酒店餐厅等场景将加速开放</p> \n<p cms-style=\"font-L\">　　下周，世界人形机器人运动会就将拉开帷幕。这场专门给机器人举办的运动会开创了人形机器人综合竞技的先河，激发机器人场景活力和产业热度。“北京将持续在创新产品和高价值场景两端发力，服务机器人产业快速发展。”姜广智透露，本市将率先建设人形机器人整机中试验证平台，解决自动化、标准化、规范化等量产关键问题，推动形成人形机器人等产品高水平规模生产能力。</p> \n<p cms-style=\"font-L\">　　北京更多地方、更多场景也将迎来机器人。记者获悉，本市将面向全球机器人企业和产品，打造并开放一批酒店、餐厅、街区等公共服务全域场景，在关系民生的餐饮等重点领域形成一批具有广泛推广价值的“机器人+智慧生活”方案，打造人与机器人协同共进的全球机器人应用标杆城市。</p> \n<p cms-style=\"font-L\">　　姜广智透露，本市将支持建设机器人产教融合平台和实训基地，促进人才引育，优化产业功能布局，携手津冀统筹布局整机制造与配套环节，打造特色优势产业集群。</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/transform/117/w550h367/20250811/c795-f3dd7f9709e35fe74024df862153d55c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4305, NULL, '砍掉年销低的经销商？娃哈哈：基于市场和意愿动态优化，并非针对特定规模客户', 0, 1, 11, '2025-08-11 22:30:27', '2025-08-11 21:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250811s/0/w1024h576/20250811/143e-e427a1e4a3cb49c4d533148c47550d66.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-11/doc-infkrpnt5706084.shtml', '澎湃新闻', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250811s/0/w1024h576/20250811/143e-e427a1e4a3cb49c4d533148c47550d66.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　娃哈哈回应砍掉年销售额300万以下经销商，称经销商新增数量远大于解合数量。</p> \n<p cms-style=\"font-L\">　　近日，有媒体报道，在杭州娃哈哈集团董事长兼总经理宗馥莉的“铁腕”策略下，娃哈哈正在陆续砍掉年销低于300万元的经销商。有些经销商结束了与娃哈哈的合作，而有些则被并入大型经销商，于是又引发了经销商之间的款项结算问题。</p> \n<p cms-style=\"font-L\">　　8月11日，娃哈哈集团向澎湃新闻记者表示：“今年以来，娃哈哈经销商新增数量远大于解合数量，经销商体系的变化是基于市场策略和合作意愿，属正常的动态优化，并非针对特定规模客户。”</p> \n<p cms-style=\"font-L\">　　前述报道指出，由娃哈哈“大经销商”接管一些“小经销商”是此次“大洗牌”的背后模式之一，此举可能是治理一些区域经销商之间或涉及的串货、多角债务等问题，由数量相对少且具有实力的“大经销商”来统一运作。</p> \n<p cms-style=\"font-L\">　　自宗庆后去世后，宗馥莉的“接班”过程一波三折，在企业经营过程中，一些争议也屡见报端。除上述经销商调整外，娃哈哈还出现部分工厂停工、员工投诉维权等事宜。</p> \n<p cms-style=\"font-L\">　　今年5月，娃哈哈集团方面也向澎湃新闻记者表示，去年因水产品市场需求快速增长，故公司的产品结构对应调整，导致公司出现产能紧张，娃哈哈迅速启动了应对措施，委托代工厂生产同时进行自有设备改造与投资新建工厂。</p> \n<p cms-style=\"font-L\">　　“为增强终端市场的响应能力，需要调整优化产销布局结构，导致部分工厂停工停产。对于停工停产的公司我司已按相关法律程序开展清算流程。”娃哈哈方面表示，对于员工劳动合同转签、投诉、维权等一系列现象是公司向内合规化改革和管理优化所带来的短期阵痛，对于这些员工的安置工作均合法合规。</p> \n<p cms-style=\"font-L\">　　据澎湃新闻记者了解，对于娃哈哈2025年的增长路径，宗馥莉曾表示，要重点突破水、茶，五大产品全面均衡发展，实施多渠道网络布局、挖掘多业态销售潜力，集中资源加强终端建设，做到2025年决胜终端。</p> \n<p cms-style=\"font-L\">　　另值得关注的是，“宗庆后遗产争夺战”也引发媒体关注。8月1日，据香港高等法院官网公布的裁决书，法院颁发临时禁制令和披露令，要求宗馥莉在杭州中级人民法院及浙江高级人民法院诉讼有结果前，除非法庭有其他命令，否则不得从Jian Hao Ventures Limited的香港汇丰银行账户提款或转账任何资产。香港高等法院认为，保全令有助于确保杭州诉讼的有效性。</p> \n<p cms-style=\"font-L\">　　根据裁决书，2024年12月27日，三名原告向杭州中院提交了起诉状及申请，正式启动针对被告宗馥莉及第三人Jian Hao Ventures Limited的诉讼程序。2025年7月8日浙江省高院出具受理通知书，确认案件正式立案。</p> \n<p cms-style=\"font-L\">　　对于“宗庆后遗产争夺战”，娃哈哈方面曾向媒体表示：“家族内部事务，与公司的运营及业务并无关联。公司不会提供任何答复口径或相关回应。”</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250811s/0/w1024h576/20250811/143e-e427a1e4a3cb49c4d533148c47550d66.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4306, NULL, '特朗普：正部署国民警卫队协助加强华盛顿治安', 0, 4, 207, '2025-08-11 23:30:13', '2025-08-11 22:59:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-11/doc-infkrtuq8514601.shtml', '新华网', '<p>　　新华社华盛顿8月11日电（记者熊茂伶　胡友松）美国总统特朗普11日在白宫新闻发布会上说，他正在部署国民警卫队，以协助华盛顿特区恢复法律秩序和公共安全。</p> \n<p cms-style=\"font-L \">　　<strong>相关新闻</strong></p> \n<p>　　<strong>特朗普宣布华盛顿特区进入公共安全紧急状态（财联社）</strong></p> \n<p>　　财联社8月11日电，据央视新闻，当地时间11日，美国总统特朗普发表讲话称，将把华盛顿特区警察局置于联邦的直接管辖之下，并当天开始部署国民警卫队，帮助重建华盛顿特区的法律、秩序和公共安全。同时宣布华盛顿特区进入公共安全紧急状态。</p> \n<p cms-style=\"font-L \"></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4307, NULL, '“清除”流浪汉，派兵出国“扫毒”？特朗普可能真做得出来', 0, 4, 207, '2025-08-11 23:30:20', '2025-08-11 22:56:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250811ac/166/w1024h742/20250811/2b20-2022333bb4e20b3e09de7151b0965322.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrtur5602727.shtml', '北京日报客户端', '<p cms-style=\"font-L\">　　美国总统特朗普10日表示，首都华盛顿的流浪汉必须“立即搬走”，政府将为他们提供住所，但将远离华盛顿，而罪犯将被关进监狱。有政府官员称，美军即将在华盛顿部署数百名国民警卫队士兵。</p> \n<p cms-style=\"font-L\">　　此前一天，特朗普表示，华盛顿特区已成为世界上最危险的城市之一，但很快将成为最安全的城市之一。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“华盛顿是民主党‘治理失败’的典型”</font></p> \n<p cms-style=\"font-L\">　　特朗普为什么盯上华盛顿的流浪汉？虽然华盛顿是美国联邦政府机关、各国驻美使馆与世界银行等国际组织总部的所在地，大量人口为联邦政府工作，但这里的暴力与财产犯罪率长期位居全美前列。以2023年为例，华盛顿的暴力犯罪率约为每10万人1151起，是全美平均数的三倍以上；全年274起凶杀案，更创下20多年来的纪录。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/front20250811ac/166/w1024h742/20250811/2b20-2022333bb4e20b3e09de7151b0965322.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　根据华盛顿都会区政府委员会今年5月的一份报告，华盛顿每晚无家可归者达5138人。虽然这一数字与纽约、洛杉矶等城市相比不算太多，但考虑到70万的人口数，华盛顿流浪汉在人口中的比例在全美名列前茅。</p> \n<p cms-style=\"font-L\">　　“特朗普盯上华盛顿特区的流浪汉，与美国当前的政治环境有关系。华盛顿是美国民主党的票仓，也被特朗普认定是民主党人地方治理失败的典型。”外交学院国际关系研究所教授李海东对北京日报客户端记者说，如果特朗普像他宣称的那样把华盛顿的流浪汉全部“清理干净”，就能够展现出共和党人在治理华盛顿方面和民主党人的鲜明对比。流浪汉和社会治安问题关乎美国整体的国家形象，也是美国的“老大难”问题，从特朗普的角度看，他将会非常努力地把清理华盛顿流浪汉的行动推进下去，就如同清理“深层政府”一样。但他是否能够成功还存在不确定性，因为民主党人很可能会对此进行抵制。</p> \n<p cms-style=\"font-L\">　　特朗普已经宣布要“夺回首都”。他计划11日在白宫召开新闻发布会，不仅将涉及打击犯罪问题，还将讨论华盛顿的清洁和整体修缮计划。他再次批评华盛顿市长鲍泽没能把首都治理好。联邦调查局（FBI）已派出多达120名特工，协助华盛顿执法部门防止劫车和暴力犯罪。</p> \n<p cms-style=\"font-L\">　　1973年颁布的 《华盛顿哥伦比亚特区自治法》 确立了华盛顿的自治地位，明确华盛顿市政府可自行管理内部事务，包括公共安全、交通等领域。特朗普再次入主白宫以来，多次批评华盛顿暴力犯罪与流浪汉问题，指责当地政府治理不力，主张联邦政府应全面介入管理华盛顿特区。</p> \n<p cms-style=\"font-L\">　　李海东说，作为美国首都的华盛顿之所以有这么多的流浪汉，很大程度上与民主党在城市治理中着重强调的“开放性”“包容性”“平等性”等理念有关，也与美国种族问题方面的政治正确性有关。纽约、洛杉矶等民主党执政的城市普遍存在流浪汉较多的现象，至于这是展现出美国的优点还是缺陷，民主党和共和党有各自的说法。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/front20250811ac/98/w1019h679/20250811/bdb5-fc18ab358e5dd8d35ae7b8502b8af624.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">派兵出国“打击犯罪”不无可能</font></p> \n<p cms-style=\"font-L\">　　特朗普似乎对解决美国长期以来存在的社会治安领域问题具有某种“执念”。几天前，有消息说特朗普已经秘密签署指令，允许对被列为“外国恐怖组织”的拉美贩毒集团启用军事力量。他还命令美国国防部做好准备，可考虑的选项包括了出动特种部队。今年2月，美国政府已将墨西哥的锡那罗亚贩毒集团等犯罪组织列为“外国恐怖组织”。对此，墨西哥总统辛鲍姆强硬回应，美国军队不会进入墨西哥境内，墨西哥不会遭到入侵。</p> \n<p cms-style=\"font-L\">　　李海东说，在特朗普的观念中，美国最大的安全威胁来自非法移民，甚至远超其他大国在国际和外交层面造成的威胁。他们不仅带来社会治安问题，而且会造成很大的政治冲击——通常在选举中支持民主党。因此，对特朗普来说，打击非法移民不仅是解决社会问题和治安问题，也是共和党人在未来选举中能否保持优势的关键。</p> \n<p cms-style=\"font-L\">　　“特朗普上台后，打击非法移民就不再只是警察和国民警卫队的事，特朗普直接动用军队在边境防范非法移民越境。”李海东说，至于特朗普是否会动用军队到别国对“犯罪组织”进行先发制人的打击，这种可能性不能排除，因为这是美国固有的一种传统行为，在历史上不乏先例，在美国看来再正常不过。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/front20250811ac/166/w1024h742/20250811/2b20-2022333bb4e20b3e09de7151b0965322.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/front20250811ac/98/w1019h679/20250811/bdb5-fc18ab358e5dd8d35ae7b8502b8af624.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4308, NULL, '特朗普：开始部署国民警卫队 华盛顿特区进入公共安全紧急状态', 0, 4, 207, '2025-08-11 23:30:27', '2025-08-11 22:42:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/20f6-663ee599715bf4fb0234d47deec249c2.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrtur5604540.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/20f6-663ee599715bf4fb0234d47deec249c2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间11日，美国总统特朗普发表讲话称，将把华盛顿特区警察局置于联邦的直接管辖之下，并于当天开始部署国民警卫队，帮助重建华盛顿特区的法律、秩序和公共安全。同时，特朗普宣布华盛顿特区进入公共安全紧急状态。</p> \n<p cms-style=\"font-L\">　　10日早些时候，特朗普在其社交媒体账号发文，称华盛顿流浪人员必须“立即搬走”，政府将为其提供住所，但会远离首都，罪犯则将被关进监狱。</p> \n<p cms-style=\"font-L\">　　针对美国总统特朗普威胁驱逐首都华盛顿流浪人员并“制止暴力犯罪”的言论，华盛顿市长10日予以驳斥，强调当地犯罪率已显著下降，当前并未出现犯罪激增现象。（央视记者 刘旭）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754925007\" target=\"_blank\">华盛顿特区进入紧急状态</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250811/20f6-663ee599715bf4fb0234d47deec249c2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4309, NULL, '莫迪与泽连斯基通话 讨论双边关系及俄乌冲突', 0, 4, 89, '2025-08-11 23:30:32', '2025-08-11 21:19:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250811/533/w1280h853/20250811/0188-b6371c45840b78b3f398c5ea694dee88.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrpnv9535361.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，乌克兰总统泽连斯基与印度总理莫迪进行了电话交谈。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250811/533/w1280h853/20250811/0188-b6371c45840b78b3f398c5ea694dee88.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△泽连斯基（资料图）\">\n <span class=\"img_descr\">△泽连斯基（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　泽连斯基在社交媒体上表示，双方讨论了双边合作、整体外交局势等议题。泽连斯基表示，印度认同 “任何涉及乌克兰的议题都必须有乌克兰参与” 的立场至关重要。此外，双方还深入探讨了针对俄罗斯的制裁问题。泽连斯基表示，<font cms-style=\"font-L strong-Bold\">须限制俄罗斯能源产品，特别是石油产品的出口</font>，以削弱其继续为冲突提供资金的能力。</p> \n<p cms-style=\"font-L\">　　此外，泽连斯基称与莫迪同意计划在9月联合国大会期间举行面对面会晤，双方还将推动未来的互访安排。</p> \n<p cms-style=\"font-L\">　　印度总理办公室11日晚间发表公报表示，总理莫迪重申印度坚定不移地支持和平解决冲突，并支持早日恢复和平的努力。印度承诺为此提供一切可能的支持。莫迪与泽连斯基还回顾了印度与乌克兰双边伙伴关系的进展，并讨论了进一步加强共同关心领域合作的途径。（总台记者 董薇 张玥）</p> \n<p cms-style=\"font-L\">　　&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250811/533/w1280h853/20250811/0188-b6371c45840b78b3f398c5ea694dee88.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4310, NULL, '卫健委回应武汉现基孔肯雅热输入病例：将在官方渠道公开', 0, 2, 165, '2025-08-11 23:30:39', '2025-08-11 22:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-11/doc-infkrpnp0220699.shtml', '澎湃新闻', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　【卫健委回应武汉现基孔肯雅热输入病例：将在官方渠道公开】近日，多条网络信息显示，武汉市已出现由佛山输入的基孔肯雅热病例。8月11日，澎湃新闻记者就该信息向武汉市卫健委核实，工作人员回应，相关信息将在官方渠道公开。</p> \n<!--WeiboOriginalContent[{\"text\": \"【#卫健委回应武汉现基孔肯雅热输入病例#：将在官方渠道公开】近日，多条网络信息显示，武汉市已出现由佛山输入的基孔肯雅热病例。8月11日，澎湃新闻记者就该信息向武汉市卫健委核实，工作人员回应，相关信息将在官方渠道公开。 http://t.cn/A6sViZYI \"}]WeiboOriginalContent--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">广东发现基孔肯雅热</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4311, NULL, '这些沿海大市，要开始“抱团”发展了？', 0, 2, 194, '2025-08-12 00:30:24', '2025-08-11 21:26:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/784/w550h234/20250812/393b-f20e533d5089a85c7ef258bf36e3c3c6.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infkrtut9428519.shtml', '每日经济新闻', '<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/784/w550h234/20250812/393b-f20e533d5089a85c7ef258bf36e3c3c6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">一个“全球海洋城市群”的设想</font></p> \n<p cms-style=\"font-L\">　　10.54万亿元，这是2024年我国海洋经济的总规模。下一个10万亿元还会远吗？</p> \n<p cms-style=\"font-L\">　　根据自然资源部近日发布的数据，初步核算，上半年海洋生产总值5.1万亿元，目标完成过半；同比增长5.8％，比国内生产总值增速高出0.5个百分点。</p> \n<p cms-style=\"font-L\">　　从发展前景的角度出发，海洋经济的爆发期其实才刚刚开始。不久前举行的中央财经委员会第六次会议提出，“推动海洋经济高质量发展”，强调加强顶层设计、加大政策支持；加强海湾经济发展规划研究。</p> \n<p cms-style=\"font-L\">　　据统计，在我国长达3.2万公里的海岸线上，面积大于10平方千米的海湾有150多个。发展海湾经济，全国多地正在进行新的探索尝试。在第三届深圳产业科技创新论坛现场，不少专家提出，规划建设大湾区全球海洋城市群。</p> \n<p cms-style=\"font-L\">　　一直以来，全球海洋中心城市被认为是海洋经济的塔尖城市。自2017年以来，已有深圳、上海、广州、天津、宁波、舟山、大连、厦门、青岛等多座城市相继提出这一目标。但单一的海洋中心城市经济总量毕竟有限，整合周边海洋城市，才能创造更大的可能。</p> \n<p cms-style=\"font-L\">　　“抱团”发展的，不只是大湾区。在此之前，山东、浙江等沿海大省均有所布局。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">1</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">争相“抱团”</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L underline italic\">海洋城市群是以港口群为纽带，以海洋经济为核心，通过多城市协同形成的城市集群。基本要素包括分工协作的港口群、全链条的海洋产业链、全联通的海洋朋友圈。</font></p> \n<p cms-style=\"font-L\">　　根据论坛现场发布的由上海交通大学安泰经管学院、深圳行业研究院联合编撰的相关报告，全球约60%的经济总量集中于港口海湾及其毗邻区域，75%的大城市和70%的工业资本分布在海岸带100公里范围内。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/60/w550h310/20250812/b861-5213bb1474d4656d6b6b3735401e8fbc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　以“旧金山湾区”“东京湾区”“粤港澳大湾区”等为代表的海洋城市群，在其核心城市的引领带动下，已成为全球经济版图的重要组成部分，并在科技创新、产业发展、航运贸易、国际合作等方面位于世界领先地位。</p> \n<p cms-style=\"font-L\">　　论坛现场，专家详细拆解了大湾区海洋城市群的“抱团”模式，即通过香港、深圳、广州三座中心城市构成的“黄金三角”，形成全球独特的多中心协同发展格局：</p> \n<p cms-style=\"font-L\">　　香港依托维多利亚港与北部都会区，打造国际航运金融中心、海事法律仲裁枢纽及离岸贸易总部基地，辐射东南亚航线并对接国际标准；</p> \n<p cms-style=\"font-L\">　　深圳以前海、海洋新城和大鹏湾为载体，建设海洋科技研发中试基地、智能装备总装中心及LNG 加注枢纽，成为衔接香港高端服务与珠西先进制造的产业化桥梁；</p> \n<p cms-style=\"font-L\">　　广州以南沙港和龙穴岛为核心，布局冷泉大科学装置等基础科研平台、江海联运枢纽及汽车滚装母港，联动珠江西岸装备制造带激活内陆腹地市场。</p> \n<p cms-style=\"font-L\">　　更重要的是，三地直线距离均不足100公里，通过深中通道、广深港高铁实现“1小时产业闭环”，使海洋科技研发—高端装备制造—国际航运服务的响应速度较单核城市提升50%，显著提高了资源配置效率与全球竞争力。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/783/w550h233/20250812/f224-8f251229f4a4519c89f42248af9ee285.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">事实上，“抱团”发展的想法并非大湾区独有。不久前，《青岛日报》理论周刊刊登了一篇名为“国际海洋城市群发展对青岛引领型现代海洋城市建设的启示”的文章，</font><font cms-style=\"font-L\">探究青岛建设引领型现代海洋城市的发展路径</font><font cms-style=\"font-L\">；此次报告中也提到，</font><font cms-style=\"font-L\">以青岛为中心的海洋城市群所构建的全产业链，即青岛聚焦海洋前沿技术研发，烟台承接海工装备制造，威海发展“海上粮仓”。</font></p> \n<p cms-style=\"font-L\">　　更早的是浙江，2023年便提出“推动宁波舟山共建海洋中心城市”。彼时多座沿海强市已经提出建设海洋中心城市。与这些城市相比，宁波、舟山各有特色和优势，但在港口支撑发展、临港产业能级、科技创新实力等方面显然还有差距。</p> \n<p cms-style=\"font-L\">　　推动共建，两地已签订《宁波市舟山市打造海洋中心城市共推高质量一体化发展合作框架协议》，目前甬舟铁路正在加速建设中。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">2</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“突围”需要</font></p> \n<p cms-style=\"font-L\">　　“抱团”发展的一大客观因素在于单一的海洋中心城市经济总量有限，整合周边海洋城市，可以形成海洋城市群能够扩大经济规模，形成规模经济和范围经济优势。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/news/crawl/73/w550h323/20250812/3fc3-da6c527460cb3f9318bcf94f783ae082.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　从全国海洋大市来看，“海洋经济第一城”仍是上海。早在2019年，上海成为全国第一座海洋经济破万亿的城市。到2024年，上海海洋生产总值攀升到11387亿元，创历史新高。紧随其后的是天津(5659.5亿元）、青岛(5513.2亿元)，深圳以5409亿元的成绩排名第四。</p> \n<p cms-style=\"font-L\">　　在报告课题组首席专家、上海交通大学安泰经济与管理学院教授、上海交通大学深圳行业研究院研究员陈宪看来，大湾区海洋城市群的“抱团”，确实基于一些现实需要，也就是深圳、香港、广州都存在短板，单座城市的综合性不及上海和新加坡。</p> \n<p cms-style=\"font-L\">　　细分全球海洋中心城市的基本要素，包括航运基础雄厚，港口物流高效；海洋产业发达，资源要素集聚；海洋科创引领，产业体系完整；海洋治理枢纽，营商环境优良。但从深圳、香港和广州各自的实际情况看，都没有同时具备上述要素。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">比如航运物流。20年前，香港曾是全球集装箱第一大港口，现在已跌出前十位。尽管深圳的集装箱港口业务呈现出较高水平，曾长期位居国内集装箱港口的榜眼，近年来也逐渐被宁波舟山港和青岛港超越。如果看港口货物总吞吐量，</font><font cms-style=\"font-L\">仅有广州港进入全球前10，深圳、香港分别排在全球第22、第41位。</font></p> \n<p cms-style=\"font-L\">　　但总部位于深圳的震兑工业智能科技有限公司董事长、总经理邱照沣向城市进化论表示，如果把香港、深圳、广州视作一个整体，一年超7000万TEU的吞吐量，在全世界罕有。</p> \n<p cms-style=\"font-L\">　　以水运新兴物流体系连接城市群，面向广阔海域进行海洋资源开发、新型海上渔业建设，这些既符合国家海洋强国战略，同时又符合粤港澳海洋城市群建设的方向。</p> \n<p cms-style=\"font-L\">　　更进一步分工，广深可以结合自身禀赋特点在海洋科技创新、海事技术研发、营商便利度、政策制度等方面持续发力。香港则可以借助在海事金融与法律方面的资源与制度优势，成为三地协同发展的关键动力。</p> \n<div class=\"img_wrapper\">\n <img id=\"5\" src=\"https://k.sinaimg.cn/n/news/crawl/27/w550h277/20250812/9249-21a41ff42ecc165b31084c4c189694fc.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　如陈宪所说，海洋城市群具备产业协同效应，城市群中各城市充分发挥差异化优势，可以形成产业联动和协同。此外，通过海上或陆上联通网络参与国际科技、产业生态等方面的合作，可以成为代表国家参与全球经济科技竞争合作的重要行动者。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">3</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">放大“边际”</font></p> \n<p cms-style=\"font-L\">　　在深圳、香港、广州的“抱团”之外，大湾区海洋城市群还有更大的想象空间。</p> \n<p cms-style=\"font-L\">　　珠海、东莞、惠州可以成为城市群的二级节点，打造专业制造与物流枢纽，重点建设船舶配套基地与冷链物流中心；</p> \n<p cms-style=\"font-L\">　　中山、江门、肇庆是三级节点，承载特色产业，聚焦风电安装船制造与海缆生产；</p> \n<p cms-style=\"font-L\">　　澳门、汕尾、阳江是四级节点，承担功能补充与战略储备任务，布局葡语国家贸易平台与深海养殖基地。</p> \n<p cms-style=\"font-L\">　　在陈宪看来，这种节点网络使90%涉海企业可在1小时内抵达配套港口或实验室，较传统分散布局模式效率提升50%以上，显著增强了海洋产业要素集聚与协同发展能力。</p> \n<div class=\"img_wrapper\">\n <img id=\"6\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/69aa-a96e108b0d5a2eb90e3a935689fcac14.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　城市间的协同，首先考验的是城市内外联通的交通基建。去年6月通车的深中通道，将深圳海洋装备研发中心与中山制造基地的通勤时间从2小时压缩至30分钟，促进了研发与制造无缝衔接。规划中的深珠高铁，将直连深圳海洋新城与珠海万山深海养殖试验区，未来有望打通又一条海洋科研与产业化的快速通道。</p> \n<p cms-style=\"font-L\">　　不过相比硬联通，软实力更能影响海洋城市群未来的发展。首先是科技创新。企业创新是深圳的强项，但创新还有另一大源头，那就是基于海洋相关高校和科研院所的基础创新。</p> \n<p cms-style=\"font-L\">　　一个典型的例子是上海，其能够登顶“海洋经济第一城”，除了近2万家涉海企业的托举，背后还有12家科研院所、13所涉海院校、20余家市级创新平台等隐形支柱。</p> \n<p cms-style=\"font-L\">　　还有青岛，之所以海洋经济总额领先于深圳，很大程度也得益于青岛拥有唯一“国字号”的中国海洋大学，还有中科院海洋研究所、自然资源部第一海洋研究所，成为青岛发力海洋经济的先手棋。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">目前深圳也在积极筹建专业的海洋大学。</font><font cms-style=\"font-L\">海洋大学（一期）项目部分工程将于2026年竣工，办学规模为全日制在校生约8000人。此外，南方科技大学也增设了相关专业。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">其次是制度创新。哈尔滨工业大学(深圳)智能海洋工程研究院法学教授赵劲松表示，深圳一方面要与香港深度融合，</font><font cms-style=\"font-L\">一方面还要创造内地的与海洋发展相关的法律制度。</font><font cms-style=\"font-L\">陈宪亦表示，大湾区作为“一国两制”下海洋治理创新的试验场，完全可以通过制度创新探索形成具有示范意义的海洋治理新模式。</font></p> \n<p cms-style=\"font-L\">　　近年来，最高人民法院两次发文，支持深圳国际仲裁院海事仲裁中心建设，打造多元化国际海事法律服务中心和国际海事纠纷争议解决优选地。自然资源部也在近期发文，鼓励深圳依托深国仲，积极争取建设国际海事仲裁中心。</p> \n<p cms-style=\"font-L align-right\">　　文字 | 肖纯</p> \n<p cms-style=\"font-L\"></p> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/784/w550h234/20250812/393b-f20e533d5089a85c7ef258bf36e3c3c6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/60/w550h310/20250812/b861-5213bb1474d4656d6b6b3735401e8fbc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/783/w550h233/20250812/f224-8f251229f4a4519c89f42248af9ee285.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/73/w550h323/20250812/3fc3-da6c527460cb3f9318bcf94f783ae082.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/27/w550h277/20250812/9249-21a41ff42ecc165b31084c4c189694fc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/69aa-a96e108b0d5a2eb90e3a935689fcac14.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4312, NULL, '美国宾夕法尼亚州工厂发生爆炸 已有多人受伤', 0, 4, 207, '2025-08-12 01:30:22', '2025-08-12 00:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/287/w696h391/20250812/06fc-6e58feba23cda8af973d25627a6ddfd0.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infkrtuv4009689.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/287/w696h391/20250812/06fc-6e58feba23cda8af973d25627a6ddfd0.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　央视记者当地时间8月11日获悉，<font cms-style=\"font-L strong-Bold\">美国钢铁公司位于宾夕法尼亚州的克莱顿工厂发生爆炸，已有多人受伤</font>，多架医疗直升机已被派往该地区。</p> \n<p cms-style=\"font-L\">　　克莱顿市市长称工厂发生爆炸，请求调配多辆救护车前往现场。当地相关部门宣布发生“大规模伤亡事件”。（央视记者 刘旭）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/287/w696h391/20250812/06fc-6e58feba23cda8af973d25627a6ddfd0.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4313, NULL, '“印度主导的这个市场，中国品牌领先了”', 0, 4, 139, '2025-08-12 01:30:40', '2025-08-11 23:29:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250811s/411/w725h486/20250811/8e35-ae3b69aed3689c655936422cf332cae7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-11/doc-infkrtut9422219.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 柳白】</p> \n<p cms-style=\"font-L\">　　8月9日，尼泊尔首都加德满都，夏日酷暑笼罩着布里库提曼达普展览馆。</p> \n<p cms-style=\"font-L\">　　但这并没有阻止52岁居民劳尼亚尔在车展上来回穿梭。一排排闪亮的高科技电动汽车映入他的眼帘，金属车身在灯光下熠熠生辉。</p> \n<p cms-style=\"font-L\">　　“这里的电动车比我预想的还多！”在比较了好几款车型后，劳尼亚尔得出结论，“中国电动车制造商在装配和做工上更胜一筹，技术也更先进。”</p> \n<p cms-style=\"font-L\">　　随着尼泊尔电动汽车市场迅猛发展，中国品牌正在占得先机。</p> \n<p cms-style=\"font-L\">　　尼泊尔《加德满都邮报》8月11日报道指出，曾经印度电动汽车是尼泊尔市场主力，但中国车企正在改变市场格局。2024至2025财年尼泊尔进口的四轮乘用车中，电动车占比高达73%，为全球最高之一。其中，中国品牌占据绝对优势，在16701辆售出的电动车中，中国品牌达13338 辆（占比79.86%），遥遥领先印度等竞争对手。</p> \n<p cms-style=\"font-L\">　　今年加德满都的汽车进口商与制造商协会（NAIMA）车展于上周三（6日）开始，堪称中印电动汽车的竞争战场。由于关注度飙升，车展已延长至本周结束。几乎每个展位都提供诱人的优惠——最高70万卢比（1元人民币约合19.52尼泊尔卢比）的现金奖励和丰厚折扣。</p> \n<p cms-style=\"font-L\">　　主办方表示，展会上的竞争反映了对尼泊尔电动汽车市场主导地位的争夺，今年中国品牌显然处于领先地位。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250811s/411/w725h486/20250811/8e35-ae3b69aed3689c655936422cf332cae7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　位于尼泊尔的比亚迪汽车展厅</p> \n<p cms-style=\"font-L\">　　比亚迪的展位是最热闹的展位之一，如今比亚迪已成为尼泊尔最畅销的电动汽车品牌之一。在印度车企马恒达（Mahindra）展位的正对面，比亚迪推出了起售价为289万卢比的 Atto 1，吸引了源源不断的参观者。</p> \n<p cms-style=\"font-L\">　　本次车展上，其中一款高端车型是来自中国的极氪X，这是一款基于沃尔沃平台的中国豪华电动车，起价 850万卢比，自去年进入尼泊尔市场，首年销量超过50辆。</p> \n<p cms-style=\"font-L\">　　“仅前三天我们就收到了10多份订单。”极氪X的尼泊尔经销商销售主管基肖尔·马哈詹说。</p> \n<p cms-style=\"font-L\">　　另一个中国品牌零跑于2024年11月进入尼泊尔市场，目前已售出260辆。本次车展上，售价低于600万卢比的车型B10单次充电续航里程可达460公里。</p> \n<p cms-style=\"font-L\">　　电动汽车目前占尼泊尔所有四轮乘用车进口量的73%，是全球比例最高的国家之一。</p> \n<p cms-style=\"font-L\">　　截至7月中旬的上一财年，尼泊尔包括客车、微型客车和私家车在内的四轮车进口量同比增长27.04%。仅电动汽车进口量就增长了23.33%。在该国进口的价值508.8亿卢比的22907辆乘用车中，有16701辆是电动汽车，价值412.3亿卢比。</p> \n<p cms-style=\"font-L\">　　就在五年前，市场格局还大不相同。</p> \n<p cms-style=\"font-L\">　　2019至2020财年，尼泊尔仅进口了236辆电动汽车，价值6.74亿卢比。那一年，尼泊尔燃油汽车的进口总量为10310辆，价值92.4亿卢比。</p> \n<p cms-style=\"font-L\">　　直到2022年，塔塔Nexon电动汽车因其价格亲民而受到尼泊尔消费者的青睐。2021年4月至2022年3月，也就是新冠疫情限制放宽后不久，尼泊尔人开始认真购买电动汽车。塔塔汽车在尼泊尔的授权经销商Sipradi Trading表示，那一年他们售出了2000多辆电动汽车，其中Nexon占销量的90%。Nexon电动汽车的价格在389万卢比至439万卢比之间。</p> \n<p cms-style=\"font-L\">　　当时，印度是尼泊尔最大的电动汽车供应国，中国紧随其后。</p> \n<p cms-style=\"font-L\">　　但比亚迪进入市场后，凭借全新的智能座舱体验，迅速在尼泊尔占据了主导地位。</p> \n<p cms-style=\"font-L\">　　印度媒体报道称，印度最近向尼泊尔运送了几百辆电动汽车，但由于国内制造业进展缓慢以及来自中国品牌的激烈竞争，出货量受到了阻碍。</p> \n<p cms-style=\"font-L\">　　“今年的反响好于预期，预订情况非常好。”比亚迪在当地的营销主管普雷娜·马哈尔詹说。</p> \n<p cms-style=\"font-L\">　　她提到了一个令人惊讶的趋势：女性企业家正成为客户群体中的重要组成部分，在比亚迪Atto 3和海豚车型的购买者中，女性约占40%。</p> \n<p cms-style=\"font-L\">　　马恒达汽车国际业务主管萨钦·阿罗卡尔说，中国品牌的竞争帮助扩大了电动汽车市场。</p> \n<p cms-style=\"font-L\">　　“这推动了电动汽车基础设施的发展，也提高了客户的期望，”他对《加德满都邮报》表示，“但我们有信心，凭借值得信赖的售后服务、品牌传承和产品质量，马恒达能够脱颖而出。”</p> \n<p cms-style=\"font-L\">　　美国《纽约时报》早前也关注到中国电动汽车在尼泊尔受到广泛欢迎。</p> \n<p cms-style=\"font-L\">　　报道称，尼泊尔政府正寻求减轻对进口化石燃料的依赖并改善空气质量，来自中国的先进电动汽车有力推动了这一进程。尼泊尔海关数据显示，去年尼泊尔进口的电动汽车中，近70%产自中国。</p> \n<p cms-style=\"font-L\">　　尼泊尔海关总署署长马赫什·巴特拉伊表示：“对我们来说，使用电动汽车是一种比较优势。这对我们有好处。在全球市场上，中国电动汽车正在扩张，尼泊尔也在经历同样的情况。”</p> \n<p cms-style=\"font-L\">　　尼泊尔的汽车经销商最初对电动汽车持怀疑态度，但他们很快从中看到了潜力。亚穆纳·什雷斯塔原先是比亚迪太阳能发电设备的经销商，她于2016年造访比亚迪公司时注意到了电动汽车，并在几年后成为比亚迪汽车在尼泊尔的经销商。</p> \n<p cms-style=\"font-L\">　　什雷斯塔说，当时许多人都在推动化石燃料，但没有多少人提倡电动汽车。不过，在比亚迪推出续航能力更强且能够适应尼泊尔崎岖道路的车型后，什雷斯塔的公司开始腾飞，现在她拥有18家经销店，预计2025年可以售出4000辆汽车。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250811s/411/w725h486/20250811/8e35-ae3b69aed3689c655936422cf332cae7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4314, NULL, '堪察加地区发生5.7级地震', 0, 4, 164, '2025-08-12 02:30:16', '2025-08-12 01:51:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/17/w490h327/20250812/a4bb-bab2b369b134b7c1e40b8587508ae162.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infkryar9315820.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/17/w490h327/20250812/a4bb-bab2b369b134b7c1e40b8587508ae162.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，俄罗斯科学院“统一地球物理局”堪察加分部通报称，<font cms-style=\"font-L strong-Bold\">堪察加地区发生5.7级地震</font>。（总台记者 王德禄）<span class=\"img_descr\"></span></p> \n<p></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/17/w490h327/20250812/a4bb-bab2b369b134b7c1e40b8587508ae162.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4315, NULL, '苏丹一难民营遭武装分子袭击 超40人死亡', 0, 4, 184, '2025-08-12 02:30:24', '2025-08-12 01:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/228/w1200h628/20250812/e7a0-7807c2ac66d6150ce15ce063af1aada4.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infkryap5514748.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，苏丹西部北达尔富尔州首府法希尔市地方组织法希尔抵抗委员会发布声明称，法希尔市以北的阿布舒克难民营当天遭遇武装分子袭击，<font cms-style=\"font-L strong-Bold\">造成40多人死亡，19人受伤</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/228/w1200h628/20250812/e7a0-7807c2ac66d6150ce15ce063af1aada4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　声明称苏丹快速支援部队发动此次袭击，指责该武装蓄意伤害手无寸铁的平民。快速支援部队尚未对此作出回应。</p> \n<p cms-style=\"font-L\">　　阿布舒克难民营是苏丹最大的难民营之一，收容了超过50万名流离失所者。近期，该难民营多次遭遇袭击。</p> \n<p cms-style=\"font-L\">　　2023年4月15日，苏丹武装部队与快速支援部队在首都喀土穆爆发武装冲突，战火随后蔓延至其他地区。持续两年多的武装冲突已造成近3万人丧生，超1200万人流离失所。达尔富尔地区是冲突的主战场之一。该地区所辖五个州中，除北达尔富尔州外，其余四州均已被快速支援部队控制。自2024年5月以来，冲突双方围绕法希尔市的控制权展开持续争夺。（总台记者 赵远方）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/228/w1200h628/20250812/e7a0-7807c2ac66d6150ce15ce063af1aada4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4316, NULL, '美民众和被拘留者家属抗议 要求关闭“鳄鱼恶魔岛”', 0, 4, 207, '2025-08-12 02:30:34', '2025-08-12 01:15:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/400/w1280h720/20250812/830b-e9f61b64cd3b0a871bd9dbeeb666c82c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infkryat3887642.shtml', '央视', '<p cms-style=\"font-L\">　　“鳄鱼恶魔岛”作为美国关押移民的拘留中心而被大家知晓。当地时间10日，不少美国民众和被拘留者家属聚集在“鳄鱼恶魔岛”外，要求关闭这座惨无人道的拘留设施，并强烈谴责美国政府的移民政策。</p> \n<p cms-style=\"font-L\">　　抗议者手举“鳄鱼恶魔岛不人道”的标识、身穿带有“废除美国移民与海关执法局”字样的T恤，高呼要求美国政府关闭该设施。目前，在“鳄鱼恶魔岛”关押着数百名移民。</p> \n<p cms-style=\"font-L\">　　抗议者索尼娅控诉，她的未婚夫已经被关押了一个多月。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/400/w1280h720/20250812/830b-e9f61b64cd3b0a871bd9dbeeb666c82c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">被拘留移民的未婚妻 索尼娅：</font>他被关一个月零三天了，他告诉我里面的条件糟透了——食物难以下咽，看守者一直开着灯不让他们睡觉，他们只有五分钟时间吃饭，而且每餐只给一小杯水。如果他们站起来，就会遭到殴打。</p> \n<p cms-style=\"font-L\">　　索尼娅在与另一位被拘留移民通话中得知，其未婚夫将被戴上手铐、脚铐。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/4435-5e58574f93105d30d1d3a7b49851af0e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　索尼娅说，未婚夫告诉她，在拘留中心，连时间和日期都不知道。更不知道这些看守者的身份。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/e262-630f67266a35e426963ddff3324e6fbf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">被拘留移民的未婚妻 索尼娅：</font>看守者不是警察，也不是政府官员。没有任何移民局的官员进来和他们谈话，告诉他们接下来会发生什么，什么都没有。</p> \n<p cms-style=\"font-L strong-Bold\">　　“鳄鱼恶魔岛”饱受争议</p> \n<p cms-style=\"font-L\">　　“鳄鱼恶魔岛”前身是位于佛罗里达州大沼泽地的戴德-科利尔训练与中转机场，<font cms-style=\"font-L strong-Bold\">四周环绕着满是鳄鱼的沼泽地，只有一条路进出、与世隔绝</font>。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">佛罗里达州总检察长 詹姆斯·乌斯迈尔：</font>人们要是想逃，等待他们的除了短吻鳄，也就只有蟒蛇了。</p> \n<p cms-style=\"font-L\">　　作为特朗普政府加大驱逐移民力度的措施之一，7月1日，“鳄鱼恶魔岛”拘留中心未完工就投入使用，里面已拘留了数百移民。</p> \n<p cms-style=\"font-L\">　　这座拘留中心自宣布建立以来，就招致广泛非议。移民权益倡导组织批评美国政府侵犯被拘留者权益；环保组织和佛州大沼泽地原住民部落之一“米科苏基”发起诉讼，称“鳄鱼恶魔岛”相关工程威胁到对环境敏感的湿地生态。美国一名联邦法官8月7日下令，因涉及环保官司，“鳄鱼恶魔岛”的施工暂停两周，但<font cms-style=\"font-L strong-Bold\">对该设施的执法和移民监管活动未作限制</font>。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/400/w1280h720/20250812/830b-e9f61b64cd3b0a871bd9dbeeb666c82c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/4435-5e58574f93105d30d1d3a7b49851af0e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/e262-630f67266a35e426963ddff3324e6fbf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4317, NULL, '受森林火灾影响 土耳其达达尼尔海峡单向封航', 0, 4, 200, '2025-08-12 02:30:46', '2025-08-12 00:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/377/w753h424/20250812/3a10-253e986e010876f234119a2591f9a3af.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infkrtut9434672.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，土耳其西北部恰纳卡莱省多地发生森林火灾，在强风作用下迅速蔓延。当局已启动空地联合灭火，并组织大规模人员疏散。受火情影响，<font cms-style=\"font-L strong-Bold\">达达尼尔海峡由南向北通航临时封闭</font>，<font cms-style=\"font-L strong-Bold\">恰纳卡莱机场暂停航班</font>，恰纳卡莱—埃济内公路部分路段也已关闭。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/377/w753h424/20250812/3a10-253e986e010876f234119a2591f9a3af.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据悉，火灾最早在恰纳卡莱市凯佩兹镇和艾瓦哲克县的垃圾场发生，随后蔓延至林区。恰纳卡莱省省长托拉曼表示，当地风力强劲、火势蔓延迅速，消防部门已出动9架飞机、10架直升机、69辆灭火车及近700名人员参与救援。目前，部分学校、宪兵营地及居民区已疏散，风险区域居民通过海路转移。共有84名受困人员经海路安全撤离，另有47人吸入浓烟后接受治疗，暂无生命危险。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250812/200/w640h360/20250812/e0cc-9d42feeb6e9b5eb9230ea0a8c3fbf3e7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　恰纳卡莱省森林面积占比高，夏季干燥多风，易发山火。本月初，当地曾因高温干旱发布森林防火最高级别警报。两天前，该省发生的野火已造成近1000名居民紧急疏散，并导致达达尼尔海峡一度双向封航。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250812/354/w739h415/20250812/601a-eacd454c21046a0de8abf594c74ece4b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　达达尼尔海峡与马尔马拉海、博斯普鲁斯海峡相连，构成土耳其海峡，是连接黑海与地中海的唯一航道，也是世界最繁忙水道之一。（总台记者 陈慧慧）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/377/w753h424/20250812/3a10-253e986e010876f234119a2591f9a3af.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/200/w640h360/20250812/e0cc-9d42feeb6e9b5eb9230ea0a8c3fbf3e7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/354/w739h415/20250812/601a-eacd454c21046a0de8abf594c74ece4b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4318, NULL, '西班牙多地发生山火 过火面积超5000公顷', 0, 4, 179, '2025-08-12 04:30:10', '2025-08-12 03:12:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250812/996c-8e38218b4d675159aeec9e9c096ffe65.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekr3773691.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间8月11日，西班牙热浪持续，全国多地相继发生山火，<font cms-style=\"font-L strong-Bold\">过火面积已超过5000公顷</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250812/996c-8e38218b4d675159aeec9e9c096ffe65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据官方通报，目前仍有10余处火点在持续燃烧，其中加利西亚自治区奥伦塞省的圣德雷萨-德凯萨以及卡斯蒂利亚-莱昂自治区莱昂省的耶雷斯火情最为严峻，<font cms-style=\"font-L strong-Bold\">当地已紧急撤离逾千名居民</font>。</p> \n<p cms-style=\"font-L\">　　大量应急人员、直升机及消防设备正全力投入扑救工作。与此同时，气象部门发出警告，高温、干旱和强风天气仍将持续，火险等级处于极高水平。（总台记者 廖军华）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250812/996c-8e38218b4d675159aeec9e9c096ffe65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4319, NULL, '巴西称美方取消两国财长视频会议', 0, 4, 29, '2025-08-12 04:30:18', '2025-08-12 02:50:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250812/b26c-c0fad9efbb2989446c3c2db5aa8608f1.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekp9193774.shtml', '央视新闻客户端', '<p>　　当地时间8月11日，巴西财政部长哈达德透露，原定13日与美国财政部长贝森特就巴西产品关税问题举行的视频会议已被美方取消，目前新的会议日期尚未确定。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250812/b26c-c0fad9efbb2989446c3c2db5aa8608f1.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\" △巴西财长哈达德\">\n <span class=\"img_descr\"> △巴西财长哈达德</span>\n</div> \n<p>　　根据美国政府7月30日颁布的行政令，美国从8月6日起对巴西输美产品加征40%的从价关税。加之美方4月颁布的关税政策，大部分巴西输美产品的关税税率提高到50%，包括肉类、咖啡、水果等。</p> \n<p>　　当地时间8月11日，世界贸易组织宣布，巴西已就美国实施的关税措施在世贸组织启动争端磋商程序，指控美方相关措施违反多项贸易条款。（总台记者 马天静 雷湘平）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1743637146\" target=\"_blank\">特朗普关税政策冲击全球</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250812/b26c-c0fad9efbb2989446c3c2db5aa8608f1.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4320, NULL, '美国总统特朗普在白宫举行新闻发布会 说了两次要去俄罗斯见普京', 0, 4, 207, '2025-08-12 05:30:14', '2025-08-12 05:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250812ac/367/w700h467/20250812/4299-37a10a395e205094577f2d91ed1afd01.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekk8342642.shtml', '央视', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　当地时间8月11日，美国总统特朗普在白宫举行新闻发布会。在发表讲话及回答记者提问环节中，特朗普两次似乎混淆了俄罗斯和美国阿拉斯加。他先是表示，“我要去见普京，周五我要去俄罗斯。”随后又重复道：“我们去俄罗斯是件大事，重磅事件”。</p> \n<p>　　特朗普上周宣布，他将于当地时间8月15日在美国阿拉斯加与俄罗斯总统普京会晤。</p> \n<p>　　　<strong>　此前报道：</strong></p> \n<p>　　<strong>特朗普称见普京将是一次“试探性会晤”（央视新闻）</strong></p> \n<p cms-style=\"font-L\">　　当地时间8月11日，美国总统特朗普在白宫记者会上谈及将与俄罗斯总统普京会晤一事，称<font cms-style=\"font-L strong-Bold\">这是一次“试探性会晤”</font>，他认为双方“将进行建设性对话”，他将“告诉普京结束战争”。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/front20250812ac/367/w700h467/20250812/4299-37a10a395e205094577f2d91ed1afd01.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　特朗普表示，他将与乌克兰总统泽连斯基通话，<font cms-style=\"font-L strong-Bold\">“下次会晤将与泽连斯基举行，或与普京和泽连斯基同时举行”</font>，会晤后还将与欧洲领导人通话。</p> \n<p cms-style=\"font-L\">　　当地时间8月10日，美国副总统万斯表示，美方正协调安排俄罗斯总统普京与乌克兰总统泽连斯基会晤讨论结束冲突事宜，并将保持与乌克兰的对话渠道畅通。但他认为在普京与特朗普会晤前进行俄乌元首会面并不具有建设性。</p> \n<p cms-style=\"font-L\">　　当地时间8月9日，俄罗斯总统助理乌沙科夫表示，普京和特朗普会谈的重点是实现乌克兰长期和平的方案。此外，乌沙科夫表示，在阿拉斯加会晤之后，普京与特朗普的下一次会晤将在俄罗斯境内举行。俄罗斯方面已经向美国方面发出了相应邀请。（央视记者 刘旭）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/front20250812ac/367/w700h467/20250812/4299-37a10a395e205094577f2d91ed1afd01.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4321, NULL, '美国得州一商店发生枪击事件 2人死亡', 0, 4, 207, '2025-08-12 05:30:21', '2025-08-12 04:54:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/113/w550h363/20250812/a500-3aa5adae7dbe40f09533361af0f48c88.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekp9203223.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/113/w550h363/20250812/a500-3aa5adae7dbe40f09533361af0f48c88.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　总台记者当地时间8月11日获悉，美国警方称得克萨斯州奥斯汀市一商店发生枪击事件，<font cms-style=\"font-L strong-Bold\">造成2人死亡</font>，目前一名嫌疑人已被拘留。奥斯汀警方表示，现场仍在处理，相关调查正在进行中。（总台记者 张颖哲）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/113/w550h363/20250812/a500-3aa5adae7dbe40f09533361af0f48c88.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4322, NULL, '墨西哥总统强硬表态：绝不允许美军入境', 0, 4, 130, '2025-08-12 05:30:29', '2025-08-12 04:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/124c-7d31e9397fa92c34ad74d5bb3cb48582.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekm5426575.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间8月11日，墨西哥总统辛鲍姆表示，政府绝不会损害墨西哥人民的主权与独立，也<font cms-style=\"font-L strong-Bold\">绝不允许美国军队进入墨西哥领土</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/124c-7d31e9397fa92c34ad74d5bb3cb48582.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　辛鲍姆重申，墨西哥永远不会屈从于他国，并指出与美国在安全领域的合作，包括请求飞机支援等特殊情况在内，都需严格符合条件，且不意味着允许外国军事力量存在。</p> \n<p cms-style=\"font-L\">　　辛鲍姆同时坚决反对美国政府实施任何形式的干预，包括使用无人机打击墨西哥境内贩毒集团等行动。针对可能出现的航空器越境情况，辛鲍姆表示，必须“完全基于墨方协调与请求，仅用于特定监控支援”。</p> \n<p cms-style=\"font-L\">　　美国国务卿鲁比奥此前在接受美国媒体采访时表示，美国政府先前已将多个拉丁美洲贩毒集团列为“外国恐怖组织”，眼下美方可能对这些贩毒集团采取军事行动。（总台记者 马天静 盛嘉迪）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/124c-7d31e9397fa92c34ad74d5bb3cb48582.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4323, NULL, '这该如何估值？美国微盘股募资15亿美元购买特朗普家族币 股价剧烈震动', 0, 4, 207, '2025-08-12 05:30:36', '2025-08-12 04:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/27/w550h277/20250812/cdd6-953908cda5ea2cd0afaf903afd3ec600.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekk8332229.shtml', '财联社', '<p cms-style=\"font-L \">　　来源：财联社</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">财联社8月12日讯（编辑 史正丞）</font>加密货币产业又促成了一笔令美股市场弹眼落睛的疯狂交易。</p> \n<p cms-style=\"font-L\">　　当地时间周一，鲜为人知的医疗技术公司Alt5 Sigma宣布从慢性疼痛治疗转向“币圈”，计划出售股份募集15亿美元资金，并将<font cms-style=\"font-L strong-Bold\">所得款项用于购买World Liberty发行的加密货币WLFI</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/27/w550h277/20250812/cdd6-953908cda5ea2cd0afaf903afd3ec600.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">要知道，这家公司在上周五收盘时市值只有1.8亿美元。</font>毫无疑问，这笔交易将显著稀释现有股东的股权。</p> \n<p cms-style=\"font-L\">　　World Liberty成立于2024年，特朗普家族在该事业中持有约40%的股份。公司官网显示，<font cms-style=\"font-L strong-Bold\">特朗普的三个儿子，美国总统中东问题特使维特科夫的两个儿子都是World Liberty的联合创始人</font>。特朗普与维特科夫也被标为“名誉联合创始人”。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/109/w550h359/20250812/e3f8-b99988ff23883344e198450ba9b320fc.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　公告透露，<font cms-style=\"font-L strong-Bold\">交易完成后扎克·维特科夫将成为公司董事长，而埃里克·特朗普将进入公司董事会</font>。</p> \n<p cms-style=\"font-L\">　　这笔交易也意味着公司股权结构将彻底改头换面。公告显示，本次ALT5 Sigma总共将发行2亿股普通股，其中1亿股私募配售由World Liberty Financial以WLFI代币的形式出资。另外还有1亿股通过直接注册发行，认购者包括“多家全球最大型机构投资者”和“知名加密风险投资公司”，公告并没有透露具体出资形式。</p> \n<p cms-style=\"font-L\">　　Alt5 Sigma也宣布，<font cms-style=\"font-L strong-Bold\">交易完成后上市公司将持有WLFI代币总供应量的7.5%</font>。不过由于这款代币目前并没有上交易所，所以很难判断这块资产的净值。World Liberty此前曾表示，WLFI代币总供应量为1000亿个。</p> \n<p cms-style=\"font-L\">　　受此影响， Alt5 Sigma股价日内大幅波动，在上涨超7%后又转头跳水，跌幅最多时超过30%。这也与“WLFI代币值多少钱”尚未形成共识有关。截至发稿，跌幅收窄至21%。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/112/w550h362/20250812/44a9-4564a8d93b1ecaa98add8c48d49f02d9.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　Alt5 Sigma的举动也反映出美股市场与加密货币圈子热烈纠缠的现状。<font cms-style=\"font-L strong-Bold\">随着白宫频吹加密产业的利好政策，一系列美股上市公司开始大量购买数字货币，大有将自己的股票变成加密货币替代品的趋势。</font></p> \n<p cms-style=\"font-L\">　　这类操作的优势在于受众面巨大——美股投资者无需设置数字钱包或额外开户，就能拥有“类加密货币资产”，缺点则是这类“加密股票”往往存在非理性溢价。</p> \n<p cms-style=\"font-L\">　　在最著名的案例中，按照最新价格计算，Strategy拥有近750亿美元的比特币，但公司市值达到1150亿美元。所以押注这只股票的投资者，相当于用1.5倍的市价购买比特币。因此尽管概念很火，但客观存在的巨大泡沫也令投资者不时感到警觉。</p> \n<p cms-style=\"font-L\">　　Alt5 Sigma也是特朗普家族在美股市场的最新“币圈”布局。此前，Hut 8 Corp.与特朗普家族合作新设了一家比特币挖矿企业，并将在数周内剥离成为独立上市公司。另外，Truth Social母公司特朗普媒体科技集团也在筹划发行比特币ETF。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/27/w550h277/20250812/cdd6-953908cda5ea2cd0afaf903afd3ec600.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/109/w550h359/20250812/e3f8-b99988ff23883344e198450ba9b320fc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/112/w550h362/20250812/44a9-4564a8d93b1ecaa98add8c48d49f02d9.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4324, NULL, '法国最大核电站因水母入侵导致停运', 0, 4, 66, '2025-08-12 05:30:53', '2025-08-12 03:58:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/377/w706h471/20250812/e9d5-d8995eb701619fd54fa99230f0d7d549.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksekp9204021.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，法国电力集团宣布，位于法国北部的<font cms-style=\"font-L strong-Bold\">格拉沃利讷核电站因设备系统附近出现大量水母而停机，整座核电站暂停运营</font>。</p> \n<p cms-style=\"font-L\">　　法国电力集团发表声明说，大量水母聚集导致水泵站过滤设备触发保护机制，4台反应堆机组于10日晚至11日清晨相继停机。这座核电站其余两台机组因接受维护，先前已关机停运。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/377/w706h471/20250812/e9d5-d8995eb701619fd54fa99230f0d7d549.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　格拉沃利讷核电站位于法国北部省，临海而建，是法国最大核电站，共配备6座反应堆，总装机容量5.4吉瓦。这次事件未对核电站、人员或环境造成安全影响。工作人员正进行紧急诊断和维修，以确保核电站安全重启。</p> \n<p cms-style=\"font-L\">　　据法国媒体报道，全球变暖导致海温上升，有利于水母繁殖加快。格拉沃利讷核电站发言人说，水母入侵导致反应堆停机“相当罕见”，但历史上也发生过类似事件。<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/377/w706h471/20250812/e9d5-d8995eb701619fd54fa99230f0d7d549.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4325, NULL, '美国蒙大拿州机场2架飞机相撞', 0, 4, 207, '2025-08-12 06:30:14', '2025-08-12 05:29:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infksksp3653293.shtml', '央视', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　当地时间8月11日下午，美国蒙大拿州卡利斯佩尔市机场发生飞机相撞事故。初步报告显示，一架小型飞机在跑道上遇到问题，随后偏离跑道并与滑行道上的另一架飞机相撞，现场起火并冒起滚滚浓烟。目前尚不清楚两架飞机的机型及机上分别有多少人，也不确认是否有人员伤亡。大规模救援工作正在展开。有美国媒体报道，相撞的两架飞机都是小型飞机。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4326, NULL, '美国5000万美元悬赏马杜罗 委内瑞拉谴责：公然违反国际法', 0, 4, 211, '2025-08-12 06:30:23', '2025-08-12 05:23:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/ae13-3aa3d2b75e5a918e49bf334ceaf1141f.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksksp3655175.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间8月11日，委内瑞拉最高法院发表声明，<font cms-style=\"font-L strong-Bold\">坚决反对并严厉谴责美国政府针对委内瑞拉总统马杜罗的通缉和侵犯行为</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/ae13-3aa3d2b75e5a918e49bf334ceaf1141f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　声明称此举企图通过抹黑行为破坏委内瑞拉民主，是对委内瑞拉内政的干涉，公然违反国际法，侵犯国家主权。</p> \n<p cms-style=\"font-L\">　　声明强调，委内瑞拉始终坚持严厉打击恐怖组织、有组织犯罪和毒品走私的坚定政策。同时重申对总统马杜罗及委内瑞拉人民捍卫国家权益的坚定支持。</p> \n<p cms-style=\"font-L\">　　美国司法部长帕姆·邦迪当地时间8月8日在讲话中称，美国政府已将缉拿委内瑞拉总统马杜罗的悬赏金额提高至5000万美元，此前针对马杜罗的悬赏金额是2500万美元。邦迪还表示，美国司法部已查封马杜罗超过7亿美元的资产。（总台记者 马天静 宫祥诚）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/ae13-3aa3d2b75e5a918e49bf334ceaf1141f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4327, NULL, '泽连斯基：乌克兰需要“明确的安全保障”', 0, 4, 204, '2025-08-12 07:30:27', '2025-08-12 06:09:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/107/w1024h683/20250812/fee4-bf25c18df4cdecc62441feb045997298.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksksh8231839.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月11日，乌克兰总统泽连斯基在社交媒体发文说，他当天分别与加拿大总理卡尼和立陶宛总统瑙塞达通电话，就俄罗斯与乌克兰停火相关议题协调立场，<font cms-style=\"font-L strong-Bold\">强调乌克兰需要“明确的安全保障”</font>。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/107/w1024h683/20250812/fee4-bf25c18df4cdecc62441feb045997298.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△乌克兰总统泽连斯基（资料图）\">\n <span class=\"img_descr\">△乌克兰总统泽连斯基（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　泽连斯基说，他和卡尼都认为，在没有乌方参与的情况下，不能就乌克兰的未来和乌民众安全作出任何决定。如果没有对乌克兰明确的安全保障，对俄制裁必须保持有效并持续强化。</p> \n<p cms-style=\"font-L\">　　泽连斯基说，他和瑙塞达均赞同必须先停火，然后寻找以公正和持久和平的方式结束这场战争的外交解决方案。他说，双方都认为，如果没有对乌克兰明确的安全保障，任何协议“只会给俄方再次集结兵力的机会”。</p> \n<p cms-style=\"font-L\">　　泽连斯基说他还同瑙塞达讨论了乌克兰加入欧盟的谈判进程，称立陶宛完全支持乌方关于乌克兰和摩尔多瓦同步加入欧盟的立场。（总台记者 张颖哲 董薇）&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250812/107/w1024h683/20250812/fee4-bf25c18df4cdecc62441feb045997298.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4328, NULL, '埃及和卡塔尔提出新加沙停火方案', 0, 4, 60, '2025-08-12 07:30:36', '2025-08-12 05:34:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/dca9-305bd4228709cadc60963c8bd1d04da3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksksp3663094.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间11日晚，据阿拉伯天空新闻报道称，<font cms-style=\"font-L strong-Bold\">埃及和卡塔尔在土耳其协助下正在提出一项新的加沙停火提案</font>，该提案包括结束战争和释放所有被扣押人员，并将提交给哈马斯领导层。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/dca9-305bd4228709cadc60963c8bd1d04da3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　报道称，根据该协议，将移交所有活着的以色列被扣押人员和已故人员遗体，以换取巴勒斯坦被扣押人员，而以色列将“在阿拉伯裔美国人的监督下”制定新的以色列军事部署地图，直到就哈马斯武器和治理问题得到全面解决。在过渡阶段，土耳其和调解人将保证哈马斯冻结所有军事活动，以便就永久结束战争进行谈判。</p> \n<p cms-style=\"font-L\">　　报道称，该提议<font cms-style=\"font-L strong-Bold\">旨在“消除以色列总理内塔尼亚胡占领加沙城的任何借口”</font>，如果哈马斯接受其中的条款，该提议将被送交美方，并转交给以色列。（总台记者 李享）<span class=\"img_descr\"></span></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/dca9-305bd4228709cadc60963c8bd1d04da3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4329, NULL, '江苏财政票据今年将全面实现无纸化 “看不见”的凭证带来“看得见”的便利', 0, 1, 10, '2025-08-12 07:30:41', '2025-08-12 07:24:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksksm9095182.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　在徐州丰沙公路丰县收费站，车辆通过MTC人工车道时，车主缴纳通行费后，无需等待打印票据即可驶离收费站，之后可通过“江苏高速96777票据服务”微信小程序或“江苏高速96777”微信公众号获取电子发票。“通行费电子票据启用后，车主等待时间平均减少3至5秒，票据纸张成本也大幅下降。”丰县收费站站长赵波说。</p>\n<p cms-style=\"font-L\">　　“财政票据流转从‘指间传递’到‘云端飞递’的转变，不仅是技术层面的升级，更是政务服务理念的革新。这让更多单位和个人享受到便利，也让每一张电子票据都成为优化营商环境的数字化基石。”省财政厅综合处负责人说。</p>\n<p cms-style=\"font-L\">　　水上及边远地区，以前曾是行政处罚电子支付的“空白区”。省滆湖渔管办渔政处负责人周志军介绍，渔业违法案件多发生于交通不便地区，且案发时间集中在夜间。电子支付、电子票据推行后，办理过程从往返折腾数公里到现场“码上办”，处理时间从数小时变成5分钟左右。</p>\n<p cms-style=\"font-L\">　　为实现财政票据数字化转型，今年3月，省财政厅印发《关于全面推进财政电子票据改革的通知》。其中明确，取消江苏省暂扣款（物）专用收据、江苏省罚没物资变价专用收据等票据种类，将全省财政电子票据种类从20余种统一归并为11种，并规定从7月1日起，省本级单位全面停用纸质票并使用电子票，从明年起全省全面停用纸质票。</p>\n<p cms-style=\"font-L\">　　省财政电子票据平台还通过与民政社会组织业务管理系统对接，对全省在民政部门注册登记的6.9万家社会组织使用的捐赠和会费票据，进行归集管理；依托民政部门对社会组织的日常管理和监督，建立社会组织基本信息变动、年检和行政处罚等信息预警机制，实时监督管理社会组织用票情况，规范其用票行为。</p>\n<p cms-style=\"font-L\">　　近5年，江苏省妇女儿童福利基金会平均每年开具捐赠票据约1.2万张。如今，捐赠人通过基金会网站进行互联网捐赠后，即可获取电子票据，相关信息还会通过短信同步送达，实现从“人工核校”到“智能监管”的全流程自动化管理。“这一举措有效解决了传统纸质票据在手续、效率、成本及管理上的难题；同时，借助事前统一标准、事中动态监测、事后智能分析的全链条监管体系，有力维护了捐赠人权益，进一步增强基金会的公开透明度和公信力，有效促进基金会在公益事业领域实现专业化、规范化发展。”江苏省妇女儿童福利基金会财务部部长严隽静介绍。</p>\n<p cms-style=\"font-L\">　　自2023年起，江苏省便与上海、浙江、安徽财政部门联合建立长三角财政电子票据信息共享和运用机制，打破区域信息壁垒，让三省一市群众和企业享受便捷高效的“同城化”服务。在此基础上，省财政联合省医保部门共同推进长三角医疗电子票据共享，成功实现长三角跨省商保在线理赔和跨省医保零星报销应用场景落地，解决了群众异地就医票据使用的痛点问题。</p>\n<p cms-style=\"font-L\">　　今年，省财政进一步联合税务部门推出企业跨省公益捐赠抵税无感智享服务。通过捐赠票据共享，为长三角三省一市相关企业提供税前扣除提醒，将服务主动延伸至企业需求端，切实降低了企业跨省公益捐赠的办税成本。截至目前，江苏省财政电子票据平台已接受长三角地区票据查验超255万次、报销入账超56万次。财政电子票据的跨省一站式查询、真伪查验和报销入账等功能全面落地，真正实现了从“区域壁垒”到“跨域通办”的转变，让长三角群众切实感受到政务服务一体化带来的便利。</p>\n<p cms-style=\"font-L\">　　省财政厅综合处负责人表示，当前财政票据无纸化改革虽取得显著成效，但仍存在不少难点。部分偏远地区的群众对电子票据的认知和接受程度有待提高，尤其是老年群体，对电子操作流程不够熟悉，使用起来存在障碍；跨部门、跨区域的数据共享标准尚未完全统一，在一定程度上影响了电子票据的通认通用；电子票据的安全防护体系还需进一步加强，以应对日益复杂的网络安全威胁。“我们将通过构建全域覆盖、全程在线、全链可控的数字票据体系，打通政务服务‘最后一公里’，让数据多跑路、群众少跑腿成为常态，未来将持续深化跨部门协同、拓展应用场景，以财政数字化转型为支点，撬动社会治理效能提升和经济高质量发展。”该负责人说。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4330, NULL, '江苏高招圆满收官——录取人数稳步提升，暖心护航学子梦', 0, 1, 10, '2025-08-12 07:30:46', '2025-08-12 07:24:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksksm9095131.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　8月11日中午12时，随着最后一批考生录取审核通过，2025年江苏高招录取现场，持续奋战的工作人员终于松了口气。历时两个月，从考试组织、计划编制、评卷划线到志愿填报、招生录取，江苏省教育考试院圆满达成“平安高考”目标，本科及“双一流”高校录取人数稳步提升。</p>\n<p cms-style=\"font-L\">　　在徐州新沂市一家乡镇邮局，快递员正将一封封高考录取通知书亲手递到考生手中。“多亏了专家的志愿填报指导。”常年在外务工的张先生面对孩子的志愿填报曾一筹莫展。“这样填报，能充分利用分数优势拉开梯度，更稳妥。”在省教育考试院专家的精准指导下，小张顺利被心仪高校录取。</p>\n<p cms-style=\"font-L\">　　今年高考志愿填报期间，省教育考试院抽调30余名业务骨干，组建高考志愿填报党员先锋服务队，深入农村乡镇、中学校园、社区街巷、警营单位进行志愿填报指导。在黄桥、新沂、赣榆等地区，服务队重点帮助留守考生、家庭经济困难考生，科学把握志愿填报策略。</p>\n<p cms-style=\"font-L\">　　除了线下的“面对面”服务，省教育考试院的“线上咨询”同样高效畅通。“哪些批次不能兼报？”“特殊类型志愿如何设置？”……在江苏高考志愿填报政策咨询平台上，考生和家长提问不断。本科、专科志愿填报期间，“在苏招生高校招生网上咨询会”汇聚省市招考机构与194所省内外高校，累计解答各类问题1.3万余条。24小时在线智慧答疑平台更是全天候服务考生超30万人次。</p>\n<p cms-style=\"font-L\">　　“温馨提醒：今年高考第二阶段志愿填报7月28日17时截止，请符合条件、尚未填报的考生抓紧填报。”在志愿填报截止前夕，尚未完成填报的考生都收到了这样的短信。从考前天气提示到志愿填报提醒，一条条短信传递着关怀，让考生倍感暖心。</p>\n<p cms-style=\"font-L\">　　开展录取工作期间，省教育考试院大楼的灯光常常亮至深夜，咨询专线的铃声此起彼伏。“怎么办？我没看清学校录取要求，万一被退档怎么办？”7月2日，就在填报志愿截止的当天夜里11时多，值班人员小李接到一个电话，听筒里的声音带着哭腔。原来，该考生没有看清所报专业对于色觉的要求，可能面临退档风险。</p>\n<p cms-style=\"font-L\">　　“别慌，慢慢说。”小李一边记录，一边耐心解释平行志愿的投档规则、体检限考的有关规定，“投档是按分排序、遵循志愿的，你填的这所学校届时不一定能投到；另外，填报征求志愿也可以补救。”在小李的安抚下，考生情绪逐渐平复。本科批次录取结束后，这位考生和父母特意来到考试院致谢，并带来了好消息：已被另一所心仪的高校顺利录取。</p>\n<p cms-style=\"font-L\">　　录取结束之际，省教育考试院全面回顾今年的来时路：高考考前通过“四不两直”方式，赴市县保密室及考点实地调研；考试期间，全省281个考点、13560个考场秩序井然，未发生失泄密和群体性违纪舞弊事件；全省为223名残疾考生提供合理便利，其中为2名盲人考生提供盲文试卷、单独设置考场，并配备专业盲文教师全程保障；组建由3000名骨干教师构成的评卷队伍，严格执行“四评制”“复查制”，纪检干部全程驻点监督，以最严的纪律、最规范的操作筑牢评分公信力；1600多所在苏招生高校全面实行“网上录取”，录取现场录检联络员“一对一”服务，考生档案流转全程可溯。</p>\n<p cms-style=\"font-L\">　　“我被北京的一所高校录取了。”几天前，连云港考生小王的报喜电话让考试院工作人员眼眶湿润。高考期间，小王突发气胸，需配备氧气瓶考试。省市考试院指导考点严格遵循应急处置流程，启动备用考场，开辟绿色通道，并协调医院在考场外增派专科医生全程护考，全力保障其顺利完成考试。“考生能够被录取到自己理想的高校，我们考务人员再多的付出都是值得的。”连云港市考试院负责人感慨。</p>\n<p cms-style=\"font-L\">　　省教育考试院负责人表示，办好人民满意的教育招考，根基在作风，关键在为民。在录取开放日活动中，30多位考生、家长和媒体代表实地见证了录取流程。“从工作人员的严谨细致中，真切感受到了高考的公平公正。”南京市第十三中学教师张洁洁说。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4331, NULL, '错峰就医 专精服务 江苏99家医院为患者点亮“夜灯”', 0, 1, 10, '2025-08-12 07:30:50', '2025-08-12 07:24:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksksm9095016.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　“白天没时间，小病一拖再拖。”针对白天忙于工作无暇就医的患者，在省卫生健康委员会的推动下，我省多家医疗机构纷纷开设夜门诊。截至目前，全省已有99家三级医院提供夜诊服务，覆盖儿科、康复科、针灸推拿科、骨科、耳鼻喉科、皮肤科等多个专科，累计接诊量达860.9万人次。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">中医特色夜门诊吸引“上班族”</font></p>\n<p cms-style=\"font-L\">　　晚上6点，常州市中医院门诊二楼颈腰痛诊疗中心、传统疗法综合治疗中心热闹非凡。“大夫，我最近睡眠不好，想来调理一下。”白领王先生表示，白天工作特别忙，想看病得专门请假。该院开设的“中医夜门诊”，让他有了两全其美的解决办法：“下了班就赶过来，还不用排长队，太方便了。”</p>\n<p cms-style=\"font-L\">　　今年4月起，常州市中医院在原先颈腰痛中心、中医护理两个夜门诊的基础上，新增骨伤科、皮肤科、针灸科、耳鼻咽喉科、口腔科5个群众需求较多的科室夜门诊，延时到晚上9点，方便“上班族”“学生党”自由选择下班、下课后的时间就诊。</p>\n<p cms-style=\"font-L\">　　医院颈腰痛中心副主任中医师张云霞介绍，医院推出针刺、艾灸、刮痧、中药熏药、药棒治疗等多样化中医传统特色治疗项目，治疗颈椎病、肩周炎、腰痛、膝关节炎等，吸引了许多上班族。</p>\n<p cms-style=\"font-L\">　　泰兴市中医院今年6月推出“颈腰痛”夜门诊服务，针对颈肩腰腿痛等常见病症，开展针灸、推拿、穴位埋线等多项传统中医特色疗法，尤其适合长期伏案工作、颈腰椎不适的职场人士和学习压力较大的学生群体。</p>\n<p cms-style=\"font-L\">　　夜幕下，记者在泰兴市中医院“颈腰痛”夜门诊诊区看到，前来就诊的市民络绎不绝。从事设计工作的林先生告诉记者，他长期对着电脑工作，几年前患上了颈椎病，“以前疼了就忍忍，现在下班顺便来做个针灸，晚上睡觉踏实多了。”</p>\n<p cms-style=\"font-L\">　　为方便患者能在8小时外享受优质医疗服务，无锡市中医院17个专科开设41个中医特色夜门诊，配套开放中医传统疗法中心、检验检查科室，打造“错峰就医、专精服务”的夜间惠民健康服务平台，线下服务近万人次。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">机动调节应对暑期就诊高峰</font></p>\n<p cms-style=\"font-L\">　　“孩子白天还好好的，到了晚上突然发烧，可把我们急坏了。还好这里一直有夜门诊，不用等到明天。”一位年轻妈妈说。晚7点，苏州大学附属儿童医院依旧灯火通明，门诊楼内人来人往。夏季高温高湿，加之空调房间与室外温差较大，小儿感冒发烧、腹泻呕吐等疾病高发。</p>\n<p cms-style=\"font-L\">　　为应对近期季节性高峰夜诊量，每天下午5点后至深夜，该院夜间门急诊医务工作人员坚守一线。医院门急诊办公室主任成永介绍，早在2005年，该院就在全省率先开设夜门诊及节假日门诊。“我们根据患儿就诊习惯，合理调配医务人员，对就诊需求较多、资源紧缺的科室及专家采取增开门诊班次，紧缺专家专科增加夜间门诊。”</p>\n<p cms-style=\"font-L\">　　20年来，该院夜门诊从最初的内科夜门诊增加到皮肤科、眼科、耳鼻喉科、口腔科、内分泌遗传代谢科等，同时增开专科门诊作为补充，尽全力满足患儿需求。此外，医院动态监测当天夜门诊候诊时长，根据患儿人数对夜门诊进行机动调节。</p>\n<p cms-style=\"font-L\">　　“根据儿科患者就诊特点，我们将医院儿科夜门诊开放时间设为每天17:30至21:30。”南京鼓楼医院儿科副主任王进雅介绍，设立儿科夜门诊不仅有效缓解了白天门诊的压力，也显著提升了患儿就诊体验。自2023年夜门诊开设以来，就诊量持续增长。尤其在呼吸道疾病高发的季节，夜间门诊在短短数小时内就能接诊40至50位患儿，淡季时日均维持在20至30人次。</p>\n<p cms-style=\"font-L\">　　进入暑期以来，该院儿科夜门诊迎来一波就诊小高峰。与以往不同，今年暑期前来就诊的大多是外地来宁游玩的游客子女，临时出现的发热、寒颤、腹泻、呕吐、皮疹等急性症状令家长措手不及。“暑期夜门诊确实比平时更忙，我们医护团队早有准备，保持了平稳有序的接诊状态。”王进雅表示。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">基层医院提供家门口延时服务</font></p>\n<p cms-style=\"font-L\">　　采访中记者发现，一些大型综合医院，接诊量大，外地患者众多，虽然没有专门开设夜门诊，但其日间门诊结束时间经常拖延到傍晚下班之后，于是医院顺势开设延时门诊，对日间服务进行自然延伸——既对白天接诊的患者负责，也能让一些下班赶过来的病患看上病。</p>\n<p cms-style=\"font-L\">　　不少基层医院则在配套服务上发力。南京建邺区莲花社区卫生服务中心让居民在家门口享受“运动+医疗”的特色健康管理。在中心的体卫融合健康站内，52岁的郭先生每天都会跟着智能设备进行抗阻训练。“以前白天忙工作，血糖高了只能拖着，现在下班过来锻炼了一段时间后，降糖药从3种减到1种，餐前血糖稳稳控制在6以下。”</p>\n<p cms-style=\"font-L\">　　“以前门诊时间和上班冲突，现在晚上8点前都能看病取药，还能走医保。”在昆山市柏庐社区卫生服务中心同心院区的夜门诊里，市民姜先生因血糖问题前来复诊。中心主任张正华介绍，夜门诊提供常见病和多发病的诊疗服务，通过调整医疗资源分配、延长就诊时间，为患者提供更多便利。目前昆山已有8家社区卫生服务中心加入“夜诊联盟”，覆盖多个乡镇街道。</p>\n<p cms-style=\"font-L\">　　“对于一些患有小病且白天缺乏就医时间的患者来说，社区夜门诊不失为一个好的就诊渠道。”张正华表示，通过开设夜门诊，可将“小病”患者引导到社区卫生服务中心就诊，将“大病”患者转诊到上级医院，从而实现分级诊疗的目标。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4332, NULL, '江苏港口向新而行向智而进向绿而兴 “码头蓝领”变身“港口白领”', 0, 1, 10, '2025-08-12 07:30:55', '2025-08-12 07:23:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksksh8245762.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　步入苏州港港口全要素智慧管理系统控制室，只见大屏幕上实时滚动更新在港船舶动态、各类货物吞吐量、作业热点分布、气象水文监测等信息。原本繁杂的海量数据，通过多样化的可视化图表直观呈现，让人一目了然。</p>\n<p cms-style=\"font-L\">　　近日，记者随省国资委组织的 “央地媒体港口行” 活动，走进省港口集团。今年上半年，该集团实现利润总额、货物吞吐量、集装箱吞吐量同比分别增长10.64%、5.86%、7.18%，交出了一份积极向上、具有韧性的发展“答卷”。</p>\n<p cms-style=\"font-L\">　　“传统印象里，码头工人需要‘肩挑背扛’辛劳作业，现在变成技术工人盯着屏幕，通过远程控制进行货物卸载。”苏州港集团总经理、党委副书记张建明表示，集团的码头作业散货全流程智能操作中心实现集成门机、斗轮机、装船机作业自动化，皮带机巡检智能化，计量系统集控化，清舱机械和理货远程化，员工完成了从“码头蓝领”向“港口白领”的转型。</p>\n<p cms-style=\"font-L\">　　“允涛高精度电子皮带秤成为全国首台凭借‘双秤体结构’取得0.2级精度等级认证的计量产品，2021年量产以来已累计销售超800万元，助力客户显著降低计量误差和物料损耗。”苏州港集团科技工程部部长刘建军介绍，为建设智慧港口，集团设备智能理货系统、件杂货库场远程管理系统相继上线，成功构建“人—机—货—场”智能协同体系，以视觉识别机器人替代高强度人力作业，堆场数字化水平进一步提升。</p>\n<p cms-style=\"font-L\">　　江苏工匠工作室、省交通运输行业首席技师工作室、苏州市技能名师工作室、张家港市技能大师工作室……苏州港黄强工作室的门口荣誉墙上，满满当当挂着一系列沉甸甸的荣誉证书。“工作室现有成员22人，其中高级工程师3人，工程师7人。工作室集技能提升、科技创新、工艺革新为一体，研发创新成果50多项，创效近千万元。”工作室负责人黄强说。</p>\n<p cms-style=\"font-L\">　　苏州港是省港口集团聚力发展港口新质生产力，持续向新而行、向智而进、向绿而兴的生动缩影。依托科技创新降低物流成本、提升运输效能，省港口集团培育10多条集装箱铁水联运线路，开发26条江海河联运线路，新增30条运河支线，其中 “南京—上海” 集装箱铁水联运线路入选全国品牌线路，单箱综合运输成本降低1200元。同时，集团积极推进5个省级科创平台建设，做实数字港口研发中心和装备产业创新中心，发挥南京港机重工“科改示范”引领作用，全面完成“科改示范”改革任务。</p>\n<p cms-style=\"font-L\">　　省港口集团党委书记、董事长陈明表示，作为全国唯一同时拥有集装箱和干散货“双五星”的港口企业和省属企业唯一获批国务院国资委第一批数字化转型试点企业，集团将持续推进港口分布式光伏发电和临港分散式风电项目建设，全面打造长江“近零碳”港口试点示范，打造120标箱纯电动集装箱绿色船队，完成首笔2390吨碳资产交易，使主要港口全部达到省级四星级及以上绿色港口水平。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4333, NULL, '驻省法院纪检监察组：推动规范涉企执法司法 为企业发展保驾护航', 0, 1, 16, '2025-08-12 08:30:31', '2025-08-12 08:17:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksqym3557521.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　今年以来，省纪委监委派驻省法院纪检监察组聚焦涉企执法司法不规范这一企业、群众反映强烈的“烦心事”，以双重点、双主线、双轨道为抓手，督促省法院全力推进规范涉企执法司法专项行动，为优化营商环境、护航企业发展提供坚强纪律保障。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">聚焦“责任落实+贯通协同”双重点，贯通协同更高效</font></p>\n<p cms-style=\"font-L\">　　纪检监察组制发工作提示，督促省法院坚决扛牢政治责任、法治责任、审判责任，成立以主要负责同志为组长的工作专班，建立健全定期调度、线索收集、评查督导等机制，构建齐抓共管工作合力，确保专项整治有序推进。</p>\n<p cms-style=\"font-L\">　　纪检监察组深化贯通协同压实主体责任，充分运用督察会商机制，通过联合召开专题会议、工作调度会等，压紧压实全省各级法院责任，查纠涉企执法司法方面突出问题。在此基础上，与信访室、赔偿办、审管办等部门建立常态化会商机制，及时分析研判群众信访、国家赔偿以及案件评查中发现问题，形成同频共振的工作格局。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">紧扣“规范司法+改进作风”双主线，监督靶向更精准</font></p>\n<p cms-style=\"font-L\">　　规范涉企执法司法根本在于规范司法行为。纪检监察组从司法为民入手，督促省法院对涉企案件优先立案、优先审理、优先执行，推行“容缺”受理机制，对于事实清楚、权利义务关系明确、争议不大的简单案件，依法适用简易程序或小额诉讼程序审理，实现小事不出企业，矛盾化解在基层；从守护司法公正着力，督促省法院依法公正高效办理涉企案件，逐案排查是否存在混淆经济纠纷、行政违法与刑事犯罪界限、把经济纠纷认定为刑事犯罪案件，对重点涉企刑事案件加强跟踪指导；从护航权益兑付落脚，督促省法院开展“交叉执行暖企攻坚”行动，选定87件申请执行人为民营企业的案件，在全省范围内开展交叉执行，三级法院执行局长带头办案、包案化解、统筹推进，以胜诉权益兑付不断提升各类经营主体司法获得感。</p>\n<p cms-style=\"font-L\">　　同时，纪检监察组督促省法院将专项行动与深入贯彻中央八项规定精神学习教育、群众身边不正之风和腐败问题集中整治和全省法院“司法作风改进年”行动统筹结合、一体推进，严肃查处办案中冷硬横推、吃拿卡要、利用审判执行权谋取私利、与涉案企业不正当接触交往、接受涉案企业请托、违规干预过问案件等问题。截至目前，约谈提醒分管领导及相关部门负责人26人次。召开院机关警示教育会，通报上半年全省法院违纪违法典型案例6起。会同省法院督察室开展纪律作风明察暗访，在一定范围通报存在纪律作风问题的4家基层法院。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">构建“问题整改+完善机制”双轨道，成果落地更扎实</font></p>\n<p cms-style=\"font-L\">　　“我们发现司法环节中的程序不规范、标准不统一、自由裁量权滥用等问题较为突出。”纪检监察组主要负责人介绍，对此纪检监察组聚焦涉企案件中超标的查封、久拖不执、“重处罚轻服务”等，督促省法院建立重点涉企案件台账，将代表委员关注案件、长期重复信访案件、三年以上长期未结案件以及引发重大舆情案件等纳入其中，健全涉企案件“双包案”工作机制，找准案件未结原因、问题焦点，制定切实可行的解决方案。截至目前，全省法院已整理78件重点涉企案件，并深入开展评查自查，对发现问题及时整改，着力破解涉企案件难点堵点。</p>\n<p cms-style=\"font-L\">　　从“治已病”到“防未病”，纪检监察组把整改突出问题、完善制度机制、提高治理效能作为监督重点，督促省法院深入分析制度机制、责任落实、工作作风中的薄弱点和风险点，推动出台《企业知识产权保护和风险防范提示》等指导性文件，研究起草破产案件预重整工作指引、破产案件援助资金管理办法等机制规范5项，为高效率解决涉企纠纷提供司法指导。同时，开展送法进企业、民法典宣传月等系列活动，与企业建立常态化交流机制，为企业创新发展提供指引。（供稿派驻省法院纪检监察组 编辑 毛玉煜）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4334, NULL, '黔南：深化专项整治 严查工程建设招投标领域腐败问题', 0, 1, 24, '2025-08-12 08:31:05', '2025-08-12 07:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infksqym3548036.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　“我利用职务便利，将工程项目直接指定或交由亲属实施，并收取好处费……”近日，黔南州瓮安县某县直单位副职领导在收到处分决定时懊悔不已。</p>\n<p cms-style=\"font-L\">　　黔南州纪委监委持续深化专项整治成果，制定工程建设招投标突出问题专项整治方案，与公安、发改、审计、财政、公共资源交易等部门建立联动协作机制，形成合力深挖彻查招投标领域违纪违法行为。</p>\n<p cms-style=\"font-L\">　　工作中，州纪委监委统筹用好监督力量，有效整合室、组、地、企等纪检监察力量，明确监督检查室牵头，抽选派驻纪检监察组和国企高校医院纪检监察机构干部组建4个检查组，集中优势力量开展监督。同时，县(市)纪委监委建立片区协作、监审贯通机制，强化监督联动、案件联查、问题联解，更好发挥协作效能叠加优势。今年上半年，专项监督共发现问题线索54件，立案27件，党纪政务处分7人。</p>\n<p cms-style=\"font-L\">　　招投标领域环节多、风险点密集。州纪委监委找准“小切口”重点突破，对“中标率异常‘标王’”“职业陪标”“评标专家抽中率异常”等突出问题专项整治，运用大数据对2020年以来全州投标人投标情况、专家评审情况等进行了数据筛查和分析，梳理异常数据，推送相关县(市)、室(组)开展重点核查。</p>\n<p cms-style=\"font-L\">　　全面起底党的十九大以来受理处置的工程建设招投标领域的问题线索情况，筛选群众反映强烈、重复反映并查否等问题，建立专门台账，动态处置、跟进监督，深挖细查工程建设招投标领域问题线索。同时，畅通信、访、网、电渠道，公开发布举报电话，加大宣传力度，引导广大党员干部、企业和群众积极参与监督。今年上半年，收到涉及工程招投标领域的信访举报件21件。</p>\n<p cms-style=\"font-L\">　　“我们还通过督促指导行业监督管理部门围绕项目审批、招标准备和交易服务等方面开展自查自纠，严厉打击背后的插手干预、利益输送、徇私舞弊、失职渎职等腐败问题。截至目前，自查项目509个，发现问题项目6个。”州纪委监委相关负责人介绍。</p>\n<p cms-style=\"font-L\">　　既要“当下改”，更要“长久立”。针对监督中发现评标专家管理存在漏洞和制度短板的问题，督促指导州农业农村局及时修订《专业技术人员参与评标(评审)工作管理制度》等制度，形成管权、管事、管人的长效机制。同时，运用好纪检监察建议，督促推动相关部门强化以案促改、以案促治，推动形成高效规范、公平竞争、充分开放的招投标市场。</p>\n<p cms-style=\"font-L align-right\">　　(黔南州纪委监委)</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4335, NULL, '北京发布积水内涝蓝色预警', 0, 1, 1, '2025-08-12 09:30:25', '2025-08-12 09:29:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/246/w550h496/20250812/7eb5-b47991db79e0c2d5c7e50906479d47ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infksqyi9012631.shtml', '北京青年报', '<p>　　来源：北京青年报</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/crawl/246/w550h496/20250812/7eb5-b47991db79e0c2d5c7e50906479d47ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　北京市水务局与市气象局联合发布积水内涝蓝色预警：预计8月12日10时至8月13日8时，北京市朝阳、石景山、丰台区存在局部积水内涝风险，提醒广大市民关注天气形势及雨水情变化，出行尽量避开低洼处，同时做好地下空间防护工作。</p> \n<p>　　文/北京青年报记者 解丽</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/default/crawl/246/w550h496/20250812/7eb5-b47991db79e0c2d5c7e50906479d47ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4342, NULL, '韩国总统李在明24日至26日将访美并与美总统会谈', 0, 4, 207, '2025-08-12 10:30:17', '2025-08-12 09:43:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250809s/135/w600h335/20250809/dece-f88d7f0dbcdecf8cae5297eb3f33b2ea.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksqym3601952.shtml', '央视', '<p>　　当地时间12日，韩国总统府表示，韩国总统李在明将于8月24日至26日访问美国，并同美国总统特朗普举行会谈。（总台记者 唐鑫）</p> \n<p>　　　<strong>　相关新闻</strong></p> \n<p>　　<strong>韩国总统李在明将在8月底访日本（观察者网）</strong></p> \n<p cms-style=\"font-L\">　　日本时事通讯社8月9日消息，日韩两国政府已开始协调，推动韩国总统李在明于8月下旬访问日本。</p> \n<p cms-style=\"font-L\">　　如果成行，这将是李在明自6月就任以来首次访日。日本方面预计日本首相石破茂将与李在明举行会谈，确认双方维持两国关系改善的方针。</p> \n<p cms-style=\"font-L\">　　另据韩国《中央日报》8月9日报道，有知情人士称李在明可能会在8月25日与美国总统特朗普会晤的前后顺道访问日本。</p> \n<p cms-style=\"font-L\">　　今年6月，石破茂与李在明在加拿大七国集团（G7）峰会期间举行了首次面对面会谈，双方当时同意构建面向未来的双边关系，并继续推进“穿梭外交”。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250809s/135/w600h335/20250809/dece-f88d7f0dbcdecf8cae5297eb3f33b2ea.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"石破茂与李在明的首次会面&nbsp;韩国中央日报\">\n <span class=\"img_descr\">石破茂与李在明的首次会面<font cms-style=\"font-L\">&nbsp;韩国中央日报</font></span>\n</div> \n<p cms-style=\"font-L\">　　</p> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/sinakd20250809s/135/w600h335/20250809/dece-f88d7f0dbcdecf8cae5297eb3f33b2ea.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4343, NULL, '美关税大棒下大量出口订单被搁置 印度企业疾呼“摆脱单一市场”', 0, 4, 89, '2025-08-12 10:30:25', '2025-08-12 08:49:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/1b6b-45625e067bd6a9f81b2a713024da6b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksqyf5233125.shtml', '央视', '<p cms-style=\"font-L\">　　近日，美国大幅提高了印度出口到美国的产品关税，双方的谈判前景不明，<font cms-style=\"font-L strong-Bold\">大量的出口订单被搁置</font>，给印度相关行业带来了巨大的困扰。印度各界表示，美国对印度加征关税不仅会严重扰乱印美贸易，也会同时造成全球贸易增长疲软。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">印度钢铁烧结工协会主席 乌帕迪亚：</font>美国提高关税对金属制品行业的影响巨大，几乎所有美国订单均被取消，因此工作进度也放缓了。现在只有我身后这些机器，还正在生产美国订单，其他订单都被取消了，货物都积压着。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/1b6b-45625e067bd6a9f81b2a713024da6b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">印度出口组织联合会总干事 阿贾伊·萨海：</font>印度出口企业现在正在面临艰难的处境，许多人已经为原材料采购申请了贷款。很多情况下也已经预订了集装箱舱位，在这种情况下行业肯定会面临问题，我们正在与政府合作寻找解决办法。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/8e11-328e5ea528ce1a3994b5d0e3c9f121d2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　印度舆论指出，美国的关税政策不仅会造成全球贸易增长放缓，也会伤害美国自身的经济发展。印度企业界希望印美两国政府尽快解决纠纷，推动双边贸易平等发展，而不是牺牲印度的利益。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/7797-e87177e9f970b19f8909337f278ecf9f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">某金属制品厂负责人 巴韦什·贾因：</font>印度出口商肯定会因关税战而遭受损失，印度政府正在努力与美国政府解决此事，找到一种互惠互利的方式。在同等的平台上开展业务，但不能以牺牲印度人民的利益为代价，美国正试图在这场贸易战中占据主导地位，他们想向印度市场销售越来越多的产品，这也向印度出口商发出了一个明确的信号，不要依赖单一市场，试着将产品出口到多个不同国家。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1743637146\" target=\"_blank\">特朗普关税政策冲击全球</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/1b6b-45625e067bd6a9f81b2a713024da6b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/8e11-328e5ea528ce1a3994b5d0e3c9f121d2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/7797-e87177e9f970b19f8909337f278ecf9f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4344, NULL, '韩国前第一夫人金建希抵达法院 出席拘捕必要性审查', 0, 4, 105, '2025-08-12 10:30:35', '2025-08-12 08:37:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/397/w791h406/20250812/c401-438642117790958471b1d9c93a4207cb.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksqye8145368.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/397/w791h406/20250812/c401-438642117790958471b1d9c93a4207cb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△资料图\">\n <span class=\"img_descr\">△资料图</span>\n</div> \n<p cms-style=\"font-L\">　　韩国前第一夫人金建希12日上午抵达首尔中央地方法院，准备出席定于当地时间10时10分开始举行的拘捕必要性审查。</p> \n<p cms-style=\"font-L\">　　负责调查金建希相关嫌疑的特别检查组本月7日以涉嫌违反《资本市场法》《政治资金法》和《特定犯罪加重处罚法》等为由提请法院批捕金建希。特检组方面11日表示，特检组先后在7日和11日向法院提交了总计超过800页的拘留意见书。</p> \n<p cms-style=\"font-L\">　　特检组方面还表示，应拘押前总统尹锡悦的首尔拘留所方面的要求，特检组已向法院提交了将拘留场所从首尔拘留所变更为首尔南部拘留所的变更申请书。</p> \n<p cms-style=\"font-L\">　　由于金建希牵涉德意志汽车公司股价操纵案、政治掮客介选案等一系列案件，特检组于本月6日对金建希进行了传唤调查，但她基本否认了所有指控。如果金建希被批捕，韩国宪政史上将首次出现“前总统夫妇同时被捕”的情况。（总台记者 张昀）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250812/397/w791h406/20250812/c401-438642117790958471b1d9c93a4207cb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4348, NULL, '马斯克再因人工智能扬言开启司法论战 这次盯上了苹果', 0, 4, 207, '2025-08-12 11:30:24', '2025-08-12 09:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/533/w800h533/20250812/0773-12685dc7b3570d7909be26a9542607c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksvha8083897.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/533/w800h533/20250812/0773-12685dc7b3570d7909be26a9542607c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月11日，美国企业家埃隆·马斯克在社交平台发文称，苹果公司涉嫌通过限制措施，使除美国开放人工智能研究中心（OpenAI）外的任何人工智能公司都无法在其应用商店排行榜中登顶，称此为“明确的反垄断违规行为”。马斯克表示，其旗下xAI公司将立即采取法律行动。</p> \n<p cms-style=\"font-L\">　　xAI是马斯克于2023年创办的人工智能初创企业。该公司在7月发布最新版Grok4聊天机器人。在发布会直播视频中，马斯克和几名研发人员以对话形式介绍了该机器人处理复杂问题和回应语音指令等功能。</p> \n<p cms-style=\"font-L\">　　OpenAI于8月7日发布其最新人工智能模型GPT-5。该模型的发布引发市场积极反馈。有分析指出，同为人工智能产业的参与者，马斯克旗下的xAI面临来自竞争对手OpenAI研发的GPT的严峻挑战。在截至8月11日美国地区的苹果应用商店内的生产力软件排行中，OpenAI的ChatGPT排第一，而马斯克旗下xAI的Grok排第二。</p> \n<p cms-style=\"font-L\">　　马斯克去年先后在州和联邦两级法院起诉OpenAI，指控后者违背非营利承诺，转向商业化路线，并申请法庭阻止OpenAI转制。马斯克还多次公开批评OpenAI的首席执行官萨姆·奥尔特曼，并引发一系列公开骂战。（总台记者 张颖哲）</p> \n<p cms-style=\"font-L\">　　</p> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/533/w800h533/20250812/0773-12685dc7b3570d7909be26a9542607c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4349, NULL, '强对流黄色预警：北京天津等地部分地区将有10级以上雷暴大风', 0, 1, 1, '2025-08-12 11:30:42', '2025-08-12 10:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/700/w821h679/20250812/de75-d45504cb32845806ef736a4bd204d4d1.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infksvhc5199488.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：中央气象台8月12日10时升级发布强对流天气黄色预警：</p>\n<p cms-style=\"font-L\">　　预计8月12日14时至13日14时，内蒙古东南部、华北中北部、西南地区东部、江南东部等地的部分地区将有8级以上雷暴大风或冰雹天气，其中，北京北部、天津北部等地的部分地区将有10级以上雷暴大风，最大风力可达11级以上；内蒙古东部、华北中北部、江淮西部、江汉、江南西北部和中东部、西南地区东部和南部、华南东部和南部等地的部分地区将有小时雨量大于20毫米的短时强降水天气，其中，河北中部和东北部、北京西南部和北部、天津北部、河南南部、湖北北部、湖南西部、贵州东南部和西南部、云南东部等地的部分地区小时雨量大于50毫米，最大可达70毫米以上。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/700/w821h679/20250812/de75-d45504cb32845806ef736a4bd204d4d1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/700/w821h679/20250812/c8aa-9a16e54b5caaddc382c12b62bf08d520.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">防御指南：</font></p>\n<p cms-style=\"font-L\">　　1.政府及相关部门按照职责做好防短时暴雨、防雷、防大风应急防御工作，气象部门做好人工防雹作业准备并择机进行作业；</p>\n<p cms-style=\"font-L\">　　2.驾驶员通过积水路段应减速慢行确认安全后再通过，交管部门应当根据路况在强降雨路段和积水路段采取交通管制措施和交通引导；</p>\n<p cms-style=\"font-L\">　　3.户外人员应减少或暂停空旷地方的户外作业，选择进入抗风能力较强并具有防雷措施的建筑内，同时关闭门窗远离危险电源；</p>\n<p cms-style=\"font-L\">　　4.机场、铁路、高速公路和水上交通等单位应采取限飞、限速或暂时关闭等措施保障人员和交通安全，相关水域水上作业和过往船舶应回港规避，加固港口设施；</p>\n<p cms-style=\"font-L\">　　5.检查城市、农田、鱼塘排水系统，做好必要的排涝措施和对山洪、滑坡、泥石流等灾害的防御准备。</p>', '[\"https://k.sinaimg.cn/n/spider20250812/700/w821h679/20250812/de75-d45504cb32845806ef736a4bd204d4d1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/700/w821h679/20250812/c8aa-9a16e54b5caaddc382c12b62bf08d520.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4350, NULL, '特朗普称与英特尔CEO会面 英特尔发言人证实', 0, 4, 207, '2025-08-12 12:30:16', '2025-08-12 12:15:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infksvhc5230402.shtml', '财联社', '<p>　　来源：财联社</p> \n<p>　　财联社8月12日电，据环球网援引法新社、CNBC等媒体11日报道，美国总统特朗普当天与美国芯片制造商英特尔新任首席执行官（CEO）陈立武会面，双方均发声证实此次会面。值得注意的是，就在几天前，特朗普曾发帖点名要求陈立武立即辞职。当地时间11日，特朗普在其社交平台上发帖称他已与陈立武会面，“我与英特尔公司的陈立武先生会面，一同出席的还有（美国）商务部长霍华德·卢特尼克和财政部长斯科特·贝森特。这次会面非常有趣。他的成功和崛起令人惊叹。陈先生将与我的内阁成员们深入交流，并计划于下周向我提交具体建议方案”。CNBC称，英特尔发言人也证实了这一会面。该公司同日在一份声明中说，“今日早些时候，陈先生有幸与特朗普总统会面，就英特尔致力于加强美国技术和制造业领导地位进行了坦诚和建设性的讨论”。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4351, NULL, '柬埔寨国防部呼吁泰国释放18名被扣押柬方士兵', 0, 4, 102, '2025-08-12 12:30:32', '2025-08-12 10:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/67/w1000h667/20250812/3818-473384db0f9818ee36add826dd12904c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infksvhi3516773.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/67/w1000h667/20250812/3818-473384db0f9818ee36add826dd12904c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月12日，柬埔寨国防部发言人马莉淑洁达呼吁泰国将18名被扣押的柬埔寨士兵移交给柬埔寨。她表示，自从双方停火后，这些士兵已经被泰国羁押14天。</p> \n<p cms-style=\"font-L\">　　柬埔寨国防部此前表示，7月29日上午，两国停火协议生效后，泰国士兵非法扣押了21名柬军士兵，除1人已确认死亡遗体已由泰方交还外，其余20名柬军士兵未被释放。泰国方面则称，是柬埔寨士兵侵入泰国领土发动武装袭击，其中部分柬士兵受伤后投降，随后被泰方扣押，泰方正依法依规处理相关事务。</p> \n<p cms-style=\"font-L\">　　8月1日，泰国方面表示已遣返2名严重受伤或患有疾病的士兵。柬方确认了这一消息，并表示将继续敦促泰方根据国际人道主义法迅速遣返剩余人员。（总台记者 付新日）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L color240\"><font cms-style=\"font-L strong-Bold color240\"></font></font></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1750421506\" target=\"_blank\">泰国总理深陷“电话门”</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250812/67/w1000h667/20250812/3818-473384db0f9818ee36add826dd12904c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4359, NULL, 'DeepSeek母公司腐败大案曝光！一员工6年套取1.18亿元被抓', 0, 4, 42, '2025-08-12 13:30:15', '2025-08-12 13:22:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infkszqc8857141.shtml', '上观', '<p cms-style=\"font-L \">　　来源：上观</p> \n<p cms-style=\"font-L\">　　据红星资本局8月11日消息，时隔大半年以后，去年11月市场盛传的“幻方量化市场总监李橙涉券商返佣被带走”一事，更多细节被揭开。</p> \n<p cms-style=\"font-L\">　　近日调查显示，李橙在2018-2023年间涉嫌伙同券商营业部经理，通过虚构经纪人身份，将幻方量化交易导入指定营业部，套取券商“交易佣金40%提成”制度下的绩效奖金，6年累计1.18亿元。目前相关几名涉案人员已移交司法机关。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">6年套取1.18亿元佣金</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">涉事券商招商证券回应</font></p> \n<p cms-style=\"font-L\">　　据报道，涉事券商为招商证券，2018年6月-2023年2月期间担任该公司深南东路营业部总经理的孟鹏飞，则是串联起涉事各方之间的关键人物。</p> \n<p cms-style=\"font-L\">　　具体来看，孟鹏飞在上述营业部任职期间，招商证券总部私人客户部总经理刘欢将幻方量化的交易放在该营业部，孟鹏飞则安排自家亲戚成为幻方量化的专属经纪人，借用亲戚的银行卡收取奖金。</p> \n<p cms-style=\"font-L\">　　6年间获得的1.18亿元绩效奖金中，2000余万元流向李橙，1000万元流向刘欢，剩余8000余万元由孟鹏飞保留。孟鹏飞还曾拿出300万元等价黄金希望顶头上司高翔帮忙保全自己，高翔后将黄金退还，并在今年3月被查。</p> \n<p cms-style=\"font-L\">　　今年5月，南粤清风网曾发布消息，招商证券财富管理及机构业务总部机构业务部总经理高翔涉嫌严重违纪违法，目前正接受招商局集团纪委纪律审查和中山市监委监察调查。</p> \n<p cms-style=\"font-L\">　　招商证券相关人士表示，高翔案目前是由中山市监委调查当中，招商证券现阶段也不知晓具体案情。招商证券此前自查，高翔案属于个人行为，公司并未参与。而对于量化返佣的问题，该知情人士透露，目前券商的佣金收取比例不到万分之一，略高于万分之零点六的成本线，不存在套取绩效的利润空间。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">幻方量化此前回应：</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">系员工个人行为，公司不知情</font></p> \n<p cms-style=\"font-L\">　　去年11月，一则“幻方员工因涉及券商返佣被抓”的传言在网上引发诸多关注。后来有消息称，该员工系幻方量化市场总监李橙。</p> \n<p cms-style=\"font-L\">　　彼时，幻方量化相关人士称，李橙个人确实在协助调查。首先这是个人行为，不是公司行为，公司没有做过返佣的行为，目前也没有任何监管机构找到公司；第二，公司之前也是不知情的，券商怎么给销售人员激励，其实公司都是不知道的；第三，公司对于所有的合作渠道，都是一样的费率，一样的佣金，且佣金处于行业较低水平。他还表示，李橙并非公司高管，只是普通的市场人员。公司也在等调查结果，等调查结果出来，公司才好处理。</p> \n<p cms-style=\"font-L\">　　公开资料显示，幻方量化由梁文锋创立，是中国量化投资领域的头部机构。幻方量化旗下有两家百亿量化私募平台，分别是2015年6月成立的浙江九章资产和2016年2月成立的宁波幻方量化。</p> \n<p cms-style=\"font-L\">　　幻方量化在2021年时曾达到千亿元规模，随后，幻方量化主动调整管理规模至约600亿元，目前是国内量化巨头之一，管理业绩和规模均位居国内前列。在私募排排网最新的百亿私募榜单中（数据截至2025年5月底），幻方量化在近半年、近一年、近三年收益排名皆进入前五名。</p> \n<p cms-style=\"font-L\">　　公司于2023年4月成立深度求索（DeepSeek）公司，进军通用人工智能领域，并于2025年1月推出大模型DeepSeek。</p> \n<p cms-style=\"font-L\">　　据了解，“券商返佣”通常指券商根据交易量返还一部分佣金给投资者，包括量化私募等。</p> \n<p cms-style=\"font-L\">　　一名券商人士表示，为了争取和维护大客户，返佣的现象在业内确实存在。也有私募会与券商达成共识，以租用券商交易席位为筹码，谋求券商在代销业务方面提供相应的支持。</p> \n<p cms-style=\"font-L\">　　有私募人士表示，出现这类情况的背后可能涉及券商为了吸引客户频繁交易，从而增加自身的交易量和收入。这种行为容易引发利益冲突和腐败问题。在圈内，不少量化基金有很多高频交易，佣金很高，券商给予返点，涉及的金额可能不菲。</p> \n<p cms-style=\"font-L\">　　上海新古律师事务所主任王怀涛律师表示，“私募以交易佣金为筹码与券商谈判销售”的法律边界在于行为是否公开透明、有无个人私利及是否破坏公平性。合规行为需佣金返还至公司账户并用于合法用途，签订公开协议且基于合法对价；违法行为包括返佣流入个人账户、私下分赃、构成商业贿赂等，违反相关法规。</p> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4360, NULL, '以军袭击加沙地带多地 加沙城东部遭几周来最猛烈轰炸', 0, 4, 151, '2025-08-12 14:30:21', '2025-08-12 13:39:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infkszqc8864020.shtml', '央视', '<p cms-style=\"font-L\">　　据巴勒斯坦媒体圣城新闻网12日报道，以军继续对巴勒斯坦加沙地带多地发动空袭和炮击。11日，巴勒斯坦武装组织在加沙城和拉法与以军继续交战。</p> \n<p cms-style=\"font-L\">　　报道称，以军对加沙地带北部加沙城、中部努赛赖特难民营以及南部汗尤尼斯发动空袭和炮击，包括对位于汗尤尼斯马瓦西地区的流离失所者帐篷发起袭击。以军对多地的袭击已造成多人伤亡。路透社11日报道称，以军当天对加沙城东部地区发动了几周以来最猛烈的轰炸。</p> \n<p cms-style=\"font-L strong-Bold\">　　巴勒斯坦武装称打击以军指挥所和士兵</p> \n<p cms-style=\"font-L\">　　哈马斯下属武装派别卡桑旅11日称，该武装对位于加沙地带南部拉法南部地区和位于加沙城东部的以军指挥所发起打击。卡桑旅还称在加沙城东部开枪狙击2名以军士兵，对其造成杀伤。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4361, NULL, '河北张家口市蔚县发生3.1级地震 震源深度12千米', 0, 2, 7, '2025-08-12 14:30:41', '2025-08-12 14:12:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/1226-0ac19e3db4ff127005e083cb1e762401.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infkszqf3451325.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　中国地震台网正式测定：8月12日14时01分在河北张家口市蔚县（北纬39.74度，东经114.63度）发生3.1级地震，震源深度12千米。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/1226-0ac19e3db4ff127005e083cb1e762401.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　（总台央视记者 张腾飞）</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/1226-0ac19e3db4ff127005e083cb1e762401.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4362, NULL, '8岁自闭症男童在大理苍山走失已超72小时，涉事夏令营机构被调查', 0, 1, 25, '2025-08-12 14:30:51', '2025-08-12 12:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/0/w1024h576/20250812/a99c-e86b29d16da2b9cf58c81b89791bc466.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infkszqf3415684.shtml', '澎湃新闻', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/0/w1024h576/20250812/a99c-e86b29d16da2b9cf58c81b89791bc466.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　截至8月12日12时，8岁自闭症男童在苍山走失已超72小时，目前仍杳无音讯，当地多部门正冒雨搜救。</p> \n<p cms-style=\"font-L\">　　8月9日上午11时40分左右，自闭症儿童王一铠跟随一个夏令营团队攀登苍山时，与队伍走失。随后，当地多部门联合开展搜救，投入了搜救犬、无人机、热成像仪等。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/0/w1024h576/20250812/01bb-7b0e502cd75904bbbeb7ae6bb1e2a0c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据熟悉苍山的相关人士此前向澎湃新闻介绍，这里的危险主要是气候和地形两方面因素造成：苍山地区气候多变，即使夏天也会有气温骤降至几度的情况，而且山中多云雾，常年有雨，能见度很低，导致探险者难以辨清方向；苍山目前大部分地方都是未开发的原始森林，山谷、悬崖、峭壁林立，几乎无路可循。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/354/w415h739/20250812/c9a9-58b68d90f4a88ab3f0892c6ca730a412.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"走失男童照片 大理融媒微信公众号 图\">\n <span class=\"img_descr\">走失男童照片 大理融媒微信公众号 图</span>\n</div> \n<p cms-style=\"font-L\">　　11日晚间，救援人员曾告知王一铠的母亲，暂未发现孩子的任何痕迹，包括未发现其生活用品等。12日上午，他们将继续在孩子失联前的最后地点，排成一条线往下找。</p> \n<p cms-style=\"font-L\">　　澎湃新闻注意到，这场救援牵动着众人的心。不少网友在社交平台留言，疑惑为何热成像设备和搜救犬在此次搜救中没能发挥出预期作用。</p> \n<p cms-style=\"font-L\">　　“深山里草木茂密，再加上气温偏低，眼下又正赶上下雨，热成像设备发挥的作用有限。”现场参与搜救的专业人士告诉澎湃新闻，目前参与搜救人员较多，现场气味复杂，再加上雨水冲刷，连搜救犬也难以施展本领。他们正对重点区域内的深沟、悬崖等危险地段开展搜索。</p> \n<p cms-style=\"font-L\">　　12日上午9时10分，大理市气象台升级发布暴雨橙色预警信号：过去3小时，上关、喜洲永兴、银桥双阳降雨量分别为52.7、43.0、25.4毫米，预计未来3小时，上关、喜洲、双廊、湾桥、银桥等乡镇（街道）将出现大暴雨。</p> \n<p cms-style=\"font-L\">　　12日11时左右，大理市区暴雨如注，这为搜救工作带来了不小的挑战。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/587/w625h762/20250812/bb0a-d2ab7f1a6d406ba7e33878478f8e587c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"走失男童照片&nbsp; 大理融媒微信公众号 图\">\n <span class=\"img_descr\">走失男童照片&nbsp; 大理融媒微信公众号 图</span>\n</div> \n<p cms-style=\"font-L\">　　此外，澎湃新闻从权威人士处获悉，当地相关部门已对这家名为“明日之光”、宣称采用自然疗愈法治疗孩子的涉事夏令营机构展开调查。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/0/w1024h576/20250812/a99c-e86b29d16da2b9cf58c81b89791bc466.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/0/w1024h576/20250812/01bb-7b0e502cd75904bbbeb7ae6bb1e2a0c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/354/w415h739/20250812/c9a9-58b68d90f4a88ab3f0892c6ca730a412.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/587/w625h762/20250812/bb0a-d2ab7f1a6d406ba7e33878478f8e587c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4363, NULL, '韩国宣布：特赦83.6687万人', 0, 4, 105, '2025-08-12 15:30:15', '2025-08-12 11:53:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infksvha8140169.shtml', '参考消息', '<p cms-style=\"font-L\">　　据韩联社8月11日报道，韩国政府11日表示，在光复节（8月15日）80周年即将到来之际，将对83.6687万人实施特别赦免、减刑和复权。祖国革新党前党首曹国及其妻子郑庆心将获得特赦。</p> \n<p cms-style=\"font-L\">　　据报道，曹国因涉嫌子女升学舞弊和阻止青瓦台监察组调查，于去年12月被判有期徒刑两年，并于当月16日起服刑。其妻子、东洋大学前教授郑庆心因涉嫌向儿子的高中班主任提交虚假升学资料，去年12月终审被判有期徒刑一年、缓刑两年。</p> \n<p cms-style=\"font-L\">　　除了曹国夫妇之外，“慰安妇”支援团体前负责人、前议员尹美香，以及前议员崔康旭、首尔市前教育监曹喜昖、执政党共同民主党议员尹建永、前民政秘书官白元宇、前环境部长官金恩京等也将获得特赦。财界人士方面，SK实业前会长崔信源获得特赦，三星电子前副会长崔志成等复权。</p> \n<p cms-style=\"font-L\">　　法务部长官郑成湖表示，这是新政府成立后的首次特赦措施，重点在于促进国民和谐，推动经济复苏。期待此举能化解社会矛盾，实现国民团结。</p> \n<p cms-style=\"font-L\">　　来源：参考消息</p> \n<p cms-style=\"font-L\"></p> \n<p></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4366, NULL, '云南保山市腾冲市附近发生3.0级左右地震', 0, 2, 264, '2025-08-12 15:31:03', '2025-08-12 15:00:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250812/cf3b-d719d73c6f8590d33ba36de12ccdf1a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvz8759575.shtml', '界面', '<p cms-style=\"font-L\">　　中国地震台网自动测定：08月12日14时56分在云南保山市腾冲市附近（北纬25.72度，东经98.57度）发生3.0级左右地震，最终结果以正式速报为准。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250812/cf3b-d719d73c6f8590d33ba36de12ccdf1a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/default/crawl/163/w550h413/20250812/cf3b-d719d73c6f8590d33ba36de12ccdf1a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4367, NULL, '国家防总针对福建广东启动防汛防台风四级应急响应', 0, 1, 13, '2025-08-12 15:31:16', '2025-08-12 14:50:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfwc3337646.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：据应急管理部消息，今年第11号台风“杨柳”（强热带风暴级）8月12日11时位于台湾台东市东偏南方向约670公里的洋面上。预计，“杨柳”将于13日中午前后在台湾沿海登陆，13日夜间至14日凌晨在福建南部到广东东部一带沿海再次登陆（强热带风暴级到台风级）。受其影响，12日至15日，福建、广东等地有大到暴雨，局地大暴雨或特大暴雨。根据《国家防汛抗旱应急预案》及有关规定，国家防总决定于8月12日13时针对福建、广东启动防汛防台风四级应急响应，并派出工作组赶赴广东协助指导。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4368, NULL, '国家防总针对福建广东启动防汛防台风四级应急响应 并派出工作组赴广东', 0, 1, 19, '2025-08-12 15:31:21', '2025-08-12 14:45:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvx5027049.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　今年第11号台风“杨柳”（强热带风暴级）8月12日11时位于台湾台东市东偏南方向约670公里的洋面上。<font cms-style=\"font-L strong-Bold\">预计，“杨柳”将于13日中午前后在台湾沿海登陆，13日夜间至14日凌晨在福建南部到广东东部一带沿海再次登陆</font>（强热带风暴级到台风级）。</p> \n<p cms-style=\"font-L\">　　受其影响，12日至15日，福建、广东等地有大到暴雨，局地大暴雨或特大暴雨。根据《国家防汛抗旱应急预案》及有关规定，<font cms-style=\"font-L strong-Bold\">国家防总决定于8月12日13时针对福建、广东启动防汛防台风四级应急响应，并派出工作组赶赴广东协助指导。</font></p> \n<p cms-style=\"font-L\">　　（总台央视记者 唐国荣 王晨）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1750756116\" target=\"_blank\">全国多地遭暴雨侵袭</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4369, NULL, '已知最大火星陨石在美国拍卖 尼日尔质疑走私启动调查', 0, 4, 145, '2025-08-12 16:30:33', '2025-08-12 15:28:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/0/w1024h576/20250812/114b-27ffde88edc04daeeac13ad3bfdb2311.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktfwe4188381.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/0/w1024h576/20250812/114b-27ffde88edc04daeeac13ad3bfdb2311.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　地球上已知最大的火星陨石上月在美国成功拍卖，引发全球关注。这块陨石发现于尼日尔，如何辗转出现在美国拍卖行不得而知。尼日尔方面怀疑这当中牵涉走私，对此启动调查。</p> \n<p cms-style=\"font-L\">　　美联社11日报道，尼日尔有关部门正着手调查这块编号为“NWA 16788”的火星陨石如何从尼日尔流向意大利、继而出现在美国，并且暂时叫停各类宝石、陨石等物品的出口，以确保这些物品的可追溯性。</p> \n<p cms-style=\"font-L\">　　这块火星陨石2023年11月在尼日尔被发现，后来出现在意大利一家展览馆，上月在美国纽约被拍卖。苏富比拍卖行原本预期成交价在200万至400万美元之间，但7月16日的成交价刷新陨石拍卖价格纪录，达430万美元，加上各类费用则总额达到530万美元。这家拍卖行没有披露买家身份。</p> \n<p cms-style=\"font-L\">　　这块火星陨石长375毫米、宽279毫米、高152毫米，重近25公斤，比地球上已知第二大火星陨石大了约70%。</p> \n<p cms-style=\"font-L\">　　据推断，这块陨石是火星在某次遭小行星撞击后“迸”出的一块碎片，飞行2.25亿公里后最终坠落在地球上的撒哈拉沙漠。它的表面质地如玻璃，很可能因穿越大气层时经历高温所致。目前尚不清楚陨石在哪一年坠落到地球，检测结果显示应是在最近几年。</p> \n<p cms-style=\"font-L\">　　苏富比拍卖行说，火星陨石较为罕见。当前，全球共有超过7.7万块经过权威鉴定的陨石，其中火星陨石只有约400块。</p> \n<p cms-style=\"font-L\">　　面对媒体更多询问，尼日尔有关部门尚未作出回应。苏富比拍卖行在一份声明里表示，这块火星陨石的出口及拍卖手续合规。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/0/w1024h576/20250812/114b-27ffde88edc04daeeac13ad3bfdb2311.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4370, NULL, '“贵州男子用农药毒杀一双儿女案”将开庭，孩子母亲发声：有时候还会觉得孩子没有离开', 0, 1, 24, '2025-08-12 16:31:08', '2025-08-12 15:49:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/92/w548h344/20250812/faad-41f215da56ad17c7d15deff6b754dcda.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvx5070371.shtml', '新浪新闻综合', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">来源 |&nbsp;</font><font cms-style=\"font-L\"><font cms-style=\"font-L\">扬子晚报/紫牛新闻</font></font></p> \n<p cms-style=\"font-L\">　　8月12日，此前备受关注的贵州男子在离婚冷静期内用农药毒死一双儿女一案有了最新消息。扬子晚报/紫牛新闻记者从被害孩子的母亲黄女士处获悉，该案一审将于8月21日在贵州凤冈县人民法院开庭审理。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/92/w548h344/20250812/faad-41f215da56ad17c7d15deff6b754dcda.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"被害孩子的母亲黄女士\" data-link=\"\">\n <span class=\"img_descr\">被害孩子的母亲黄女士</span>\n</div> \n<p cms-style=\"font-L\">　　黄女士告诉记者，案发时，她的一双儿女一个10岁一个7岁，她与被告人刘某某2009年相识，2012年相恋并于2014年因未婚先孕结婚，“那一年我刚20岁，其实结婚之前我就发现他游手好闲，很少去上班，喜欢去网吧打游戏，一度考虑要和他分手，但无奈有了孩子才勉强与他结婚。”</p> \n<p cms-style=\"font-L\">　　黄女士说，婚后刘某某仍旧很少出去打工，也很少拿钱回家，“他作为一位父亲，根本没尽到抚养义务。后来没办法只好把孩子送回老家，我们俩又去到广东的一家厂里上班。后来生二胎的时候，也是借的我弟弟的钱。”</p> \n<p cms-style=\"font-L\">　　黄女士表示，丈夫长期未尽到家庭抚养义务，让她不得已提出离婚，“今年5月20日，我们俩去民政局协议离婚，约定儿子归我、女儿和房子归他。”黄女士称，当时自己从民政局出来之后一度不敢回家，“因为我知道他的性格，怕他做出一些伤害我的事。但他就以孩子为借口让我回去照顾孩子写作业，因此我就心软回家了。”</p> \n<p cms-style=\"font-L\">　　黄女士告诉记者，没想到第二天中午，刘某某突然勒住她的脖子，把她的手脚都给捆了起来。“<font cms-style=\"font-L strong-Bold\">他当时把农药拿出来，跟我说我们俩今天下午必须死，</font>还让我把能借的钱都借出来，拿给他爸养孩子。我当时很害怕，只能想办法安抚他。安抚好以后，他终于送我去上班了。”黄女士说，后来她去派出所报案，但警方以家庭矛盾为由未予立案。“于是我去到了遵义，准备起诉离婚，然后我还打电话给孩子爷爷说让老人去看一下孩子，因为我很怕刘某某一个人带孩子，会对孩子做出什么出格的事，但没想到孩子爷爷认为不会有什么事。”</p> \n<p cms-style=\"font-L\">　　黄女士记得，那天晚上她还在睡觉，接到了母亲的电话，“她让我赶紧报警，说刘某某用毒药把两个孩子给毒死了。警方说家里到处都是农药的味道，在家中发现3瓶农药，还有孩子喝了农药的呕吐物，孩子送到医院以后，医生经过抢救还是没能救得回来。后来弟弟和我说，事发当天夜里，刘某某就在群里发消息，说他给孩子喝了农药，让我去给孩子收尸。”</p> \n<p cms-style=\"font-L\">　　黄女士说，她还记得最后一次见孩子，女儿一直粘着她要她抱，“我到现在都接受不了两个孩子突然离开我的那种生活。<font cms-style=\"font-L strong-Bold\">我有时候还会觉得孩子没有离开我，期待着下班回到家，发现孩子还在家里等我。</font>我希望法院可以重判凶手。”</p> \n<p cms-style=\"font-L\">　　事发后，有网友说黄女士从事主播工作，并称其离婚是为了和“榜一大哥”在一起。对此，黄女士回应称，她确实在从事主播方面的工作，“我和‘榜一大哥’聊过，是会聊得暧昧一点，但从来不会私下见面，而且我有两个小孩要照顾，根本不会做什么出格的事。刘某某也知道我的这份工作以及工作性质，我们没有因为这件事吵过架。”黄女士坦言，从刘某某染上赌博开始，他们之间就已经没有感情了，“<font cms-style=\"font-L strong-Bold\">他不想和我离婚，完全是因为不想失去经济来源。</font>因为他之前经常向我要钱，不给的话就威胁去我公司闹，让我没法上班。”</p> \n<p cms-style=\"font-L\">　　黄女士的弟弟黄先生告诉记者，他的这个姐夫刘某某喜好赌博、又不挣钱也不照顾孩子，“一点责任心都没有，不像一个男人。还时不时找我借钱，一会说要装修房子，一会说要投资外卖店，刚结婚那会还找我爸借钱开网吧，但我爸没借，后来还以我爸的名义去借网贷，直至被起诉他才还钱。”黄先生还称，刘某某还曾打过黄女士，“当时我爸把他告到派出所了，他在那里给我们下跪道歉，我们才原谅了他。”</p> \n<p cms-style=\"font-L\">　　黄先生表示，案发前，刘某某还因为妻子要与其离婚威胁要杀他们全家。“我姐姐做主播，我也知道，但我觉得这只是一份正常的职业，陪‘榜一大哥’聊天也只是生活所迫。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">记者 徐韶达</font></font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/92/w548h344/20250812/faad-41f215da56ad17c7d15deff6b754dcda.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4371, NULL, '福建：推动建设生育友好型社会，加大税收、金融、住房支持力度', 0, 1, 13, '2025-08-12 16:31:15', '2025-08-12 15:46:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvx5067013.shtml', '界面', '<p cms-style=\"font-L\">　　福建省政府办公厅印发《关于推动建设生育友好型社会的若干措施》，其中提出，加大税收、金融、住房支持力度。落实好3岁以下婴幼儿照护、子女教育个人所得税专项附加扣除政策。住房政策向多子女家庭倾斜，适当提高多子女家庭住房公积金最高贷款额度和租住商品住房公积金的提取额度。根据养育未成年子女负担情况实施差异化租赁和购买房屋的优惠政策。完善公租房调换政策，鼓励和支持对人口增加的承租家庭及时调换房源，对三孩家庭探索实施保障房优先选择政策。支持金融机构对符合条件的母婴护理、托育服务等企业发放相关政策性优惠贷款。鼓励支持保险机构发展适合孕妇、婴幼儿等特定人群的综合保险。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">关于推动建设生育友好型社会的若干措施</font></p> \n<p cms-style=\"font-L\">　　为深入贯彻落实国务院办公厅《关于加快完善生育支持政策体系推动建设生育友好型社会的若干措施》（国办发〔2024〕48号），现就我省进一步完善生育支持政策体系，建设生育友好型社会提出以下措施。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">一、增强生育保险保障功能。</font>强化生育保险对参保女职工生育医疗费用、生育津贴待遇的保障作用。将符合条件的产前检查、分娩等生育医疗费用纳入生育保险或由基本医疗保险按规定予以报销。生育保险参保男职工的未就业配偶未参加城乡居民医保的，参照职工参保地的城乡居民医保报销标准支付生育医疗费用。支持有条件的统筹区将参加职工基本医疗保险的灵活就业人员、农民工、新就业形态人员同步纳入生育保险，合理设置待遇等待期，确保基金运行安全。</p> \n<p cms-style=\"font-L\">　　责任单位：省医保局、财政厅、人社厅、卫健委，各市、县（区）人民政府，平潭综合实验区管委会〔以下均需各市、县（区）人民政府，平潭综合实验区管委会落实，不再列出〕</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">二、加大税收、金融、住房支持力度。</font>落实好3岁以下婴幼儿照护、子女教育个人所得税专项附加扣除政策。住房政策向多子女家庭倾斜，适当提高多子女家庭住房公积金最高贷款额度和租住商品住房公积金的提取额度。根据养育未成年子女负担情况实施差异化租赁和购买房屋的优惠政策。完善公租房调换政策，鼓励和支持对人口增加的承租家庭及时调换房源，对三孩家庭探索实施保障房优先选择政策。支持金融机构对符合条件的母婴护理、托育服务等企业发放相关政策性优惠贷款。鼓励支持保险机构发展适合孕妇、婴幼儿等特定人群的综合保险。</p> \n<p cms-style=\"font-L\">　　责任单位：省住建厅、财政厅、发改委，中国人民银行福建省分行，福建金融监管局，省教育厅、卫健委，省税务局</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">三、实施育儿补贴等制度。</font>按照国家育儿补贴制度要求，制定福建省落实育儿补贴制度实施方案，指导市、县（区）做好政策衔接，积极稳妥推动落实。分类制定扶持公办、社会办普惠托育机构和幼儿园托班运营发展政策，建立更加精准的普惠托育运营补助制度。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委、财政厅、教育厅</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">四、强化职工权益保障。</font>加强用人单位用工指导，督促用人单位依法依规落实对女职工特别是孕产期、哺乳期女职工的特殊劳动保护。鼓励用人单位结合实际采取弹性上下班、居家办公等方式，营造家庭友好型工作环境。推动女职工较多的用人单位建立“妈妈小屋”。完善假期用工成本合理分担机制，督促用人单位落实好法律法规规定的产假、照顾假、育儿假等假期待遇。鼓励开办3岁以下婴幼儿暑期托育班，做优职工子女暑托班品牌。加强对女性劳动者特别是生育再就业女性相关职业技能培训。畅通劳动保障维权渠道，强化日常监督执法，坚决查处性别、年龄等就业歧视行为。鼓励建立用人单位依法保障职工生育权益的激励机制。</p> \n<p cms-style=\"font-L\">　　责任单位：省人社厅、卫健委，省总工会、省妇联</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">五、强化生殖健康服务。</font>深入实施母婴安全行动提升计划、出生缺陷防治能力提升计划、生殖健康促进行动及消除艾滋病、梅毒和乙肝母婴传播行动计划。深入开展早孕和流产关爱服务。支持危重症孕产妇救治中心建设。鼓励中医医院开设优生优育门诊，将中医药技术融入妇科、产科、产后康复等医疗服务。加强生殖保健技术研发应用，鼓励有条件的地市对困难家庭实施不孕不育治疗补助。将青春期健康教育融入有关学科课程教育内容，加强青少年、育龄人群性和生殖健康教育，预防非意愿妊娠，保护育龄人群生育力。加强生育医疗费用保障，合理确定产科医疗服务价格，将适宜的分娩镇痛以及辅助生殖技术项目纳入医保报销范围。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委、发改委、教育厅、医保局，团省委、省妇联、省计生协</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">六、优化生育全程服务。</font>加强婚前优生优育惠民政策宣传教育，推行婚孕前保健门诊紧邻婚姻登记就近就便设置。完善“新生儿出生一件事”集成服务信息平台，为符合条件的新生儿提供出生医学证明办理、预防接种证办理、科学育儿指导服务登记、户口登记、生育保险待遇核准支付、城乡居民基本医疗保险参保登记、社会保障卡申领等事项集成套餐式服务，打造“一表申请，一平台受理、一站服务”的多证联办模式。依托省一体化公共数据平台“一人一档”基础库，完善福建省全员人口数据库，实现教育、公安、民政、卫生健康、医保、人力资源社会保障等人口相关信息融合共享、科学利用。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委、发改委、公安厅、人社厅、医保局、教育厅、民政厅、数据管理局，中国人民银行福建省分行</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">七、提高儿童医疗服务水平。</font>加强儿童医院、妇幼保健机构和综合性医院产科、儿科建设，推动绩效工资分配向产科、儿科倾斜。推进生育友好和儿童友好医院建设。夯实基层儿童医疗保健服务网络，每所乡镇卫生院、社区卫生服务中心至少配备1名提供规范儿童基本医疗服务的全科医生，至少有2名具有儿童保健服务能力的医生。加强6岁以下儿童健康管理服务，开展贫血、视力不良、肥胖、龋齿、心理行为发育异常、听力障碍等疾病的防治。鼓励儿童药品研发申报，不断丰富儿童适用药品的品种、剂型和规格。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委、发改委、财政厅、工信厅、药监局</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">八、促进儿童发展和保护。</font>充分挖掘和整合现有力量，建立完善健康科普专家库和资源库，开展“优生优育进万家”等活动。统筹协调群团组织、专业服务机构、行业协会，依托村（居）委会、计生协、妇联、健康网格员等基层力量提高家庭婴幼儿照护能力。充分发挥公益慈善类社会组织的积极作用，加大对农村婴幼儿照护服务的支持。深化儿童关爱服务，加强婴幼儿早期教育指导和寒暑假儿童关爱服务。发展儿童福利事业，加强孤儿、事实无人抚养儿童基本生活保障，为有需求的困境儿童提供心理健康、结对帮扶、生活关爱等服务。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委、民政厅，省妇联、省计生协</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">九、扩大优质教育资源供给。</font>优化区域和城乡教育布局规划，建立与人口变化相协调的基本公共教育服务供给机制。推进学前教育普及普惠发展，鼓励有条件的幼儿园开设托班招收2—3岁幼儿。逐步推行免费学前教育政策。加快推进义务教育优质均衡发展，进一步缩小城乡之间、学校之间差距。统筹推进“双减”和教育教学质量提升，更高水平满足学生和家长多样化需求。推行“长幼随学”的就读举措，推动落实多孩家庭子女同校就读。落实教育救助制度，建立完善覆盖全学段学生资助体系。</p> \n<p cms-style=\"font-L\">　　责任单位：省教育厅、发改委、财政厅、卫健委</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">十、积极营造生育友好社会氛围。</font>实施人口高质量发展宣传教育专项活动。加强人口国情国策教育，将人口理论、人口形势和生育政策等纳入党校（行政学院）授课内容，将人口国情国策教育相关内容融入中小学、本专科教育。加强家教家风建设，大力倡导积极的婚恋观、生育观和家庭观。加强社会宣传倡导，办好“健康福建”人口高质量发展栏目，做好人口和生育政策宣传解读。弘扬中华民族传统美德，提倡适龄婚育、优生优育、家庭奉献，倡导尊重生育、敬畏生命、夫妻共担育儿责任，构建新型生育文化。持续开展“山盟海誓”“缘启之旅”等婚恋活动，倡导健康文明、节约适度的婚俗文化。支持鼓励创作一批积极向上的文艺作品，讲好新时代美好爱情、和谐家庭、幸福生活的福建故事。推进儿童友好城市（社区）建设。</p> \n<p cms-style=\"font-L\">　　责任单位：省卫健委，省委宣传部，省教育厅、民政厅、农业农村厅、文旅厅、广电局，省总工会、团省委、省妇联、省计生协</p> \n<p cms-style=\"font-L\">　　各地各部门要坚持一把手亲自抓、负总责，坚持和完善目标管理责任制，加强统筹规划、政策协调和工作落实，确保责任到位、措施到位、投入到位、落实到位。要进一步清理影响制约生育友好型社会建设的相关规定和政策文件，保障婴幼儿合法权益。要深入把握人口流动特点，推动相关公共服务随人走，促进城乡、区域人口合理聚集、有序流动。福州、厦门、泉州等地要发挥示范带头作用，积极探索出台更有力度的生育支持政策措施。省卫健委、发改委要切实强化工作调度，完善人口监测体系和预测预警机制，会同相关部门加强生育支持政策研究、宣传解读和成效评估，推动相关政策落地，及时总结推广典型经验做法，妥善回应社会关切。各有关部门、各单位要切实提高政治站位，增强做好新时代人口工作的责任感和使命感，落实政府、部门、用人单位、个人等多方责任，按照职责分工协同发力，完善相关配套支持措施，确保工作取得实效。</p> \n<p cms-style=\"font-L\">　　本文件自印发之日起施行，有效期十年。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4376, NULL, '印尼巴布亚省发生6.3级地震，震源深度10千米', 0, 4, 42, '2025-08-12 17:30:07', '2025-08-12 16:49:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/97bb-97b061b4afe9b1234d3cee04ca6bf0ad.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktncx8702101.shtml', '界面', '<p cms-style=\"font-L\">　　中国地震台网正式测定：08月12日16时24分在印尼巴布亚省（南纬2.10度，东经138.95度）发生6.3级地震，震源深度10千米。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/97bb-97b061b4afe9b1234d3cee04ca6bf0ad.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250812/97bb-97b061b4afe9b1234d3cee04ca6bf0ad.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4377, NULL, '辽宁抚顺一旅游大巴在景区翻车，殡仪馆接到死者遗体，目前现场交通已恢复', 0, 2, 38, '2025-08-12 17:30:19', '2025-08-12 17:25:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncv4990932.shtml', '极目新闻', '<p>　　极目新闻记者 李贤诚</p> \n<p>　　8月12日，多位网友爆料称，辽宁省抚顺市清原满族自治县红河峡谷漂流景区内，一辆旅游大巴发生翻车。8月12日下午，极目新闻记者从当地殡仪馆获悉，已收到此次事故中的死者遗体。当地官方表示，具体伤亡情况后续将对外通报，目前交通已恢复。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/674/w550h124/20250812/82b0-b5ca10eef0b4d085d2109f4732c19fe3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　12日下午，极目新闻记者致电清原满族自治县政府办、交通运输局和文化旅游和广播电视局，接线人员均表示，他们接到了上述大巴车翻车的汇报，工作人员已前往现场处理，具体情况他们暂不了解。</p> \n<p>　　清原满族自治县有关部门工作人员告诉极目新闻记者，等人员伤亡具体数据统计出来后，将对外通报，目前，现场交通已恢复畅通。</p> \n<p>　　公开报道显示，红河峡谷漂流作为清原旅游的金字招牌，是国家4A级旅游景区，漂流全长12.8公里，时长2.5小时，河水丰盈清澈，两岸森林茂密、怪石林立，是我国北方罕见的天然漂流场所，素有东北小三峡之称，荣获“中国北方第一漂”的美誉。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/674/w550h124/20250812/82b0-b5ca10eef0b4d085d2109f4732c19fe3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4378, NULL, '遵义市公安局刑事侦查支队原支队长丁钊被开除党籍和公职', 0, 2, 254, '2025-08-12 17:30:28', '2025-08-12 17:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktncv4981952.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">据遵义市纪委监委消息：</font>经遵义市委批准，遵义市纪委监委对遵义市公安局刑事侦查支队原支队长丁钊严重违纪违法问题进行了立案审查调查。</p>\n<p cms-style=\"font-L\">　　经查，丁钊丧失理想信念，背弃初心使命，对抗组织审查;违反中央八项规定精神，收受可能影响公正执行公务的礼品，收受明显超出正常礼尚往来的财物;廉洁底线失守，违规向管理和服务对象借款，违规从事营利活动;利用职务上的便利为他人谋取利益，非法收受他人巨额财物。</p>\n<p cms-style=\"font-L\">　　丁钊严重违反党的政治纪律和廉洁纪律，涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予以严肃处理。依据《中国共产党纪律处分条例》《中华人民共和国公职人员政务处分法》等有关规定，经遵义市纪委常委会会议研究并报遵义市委批准，决定给予丁钊开除党籍处分;由遵义市监委给予其开除公职处分;收缴其违纪违法所得;将其涉嫌犯罪问题移送检察机关依法审查起诉，所涉财物一并移送。(遵义市纪委监委)</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4379, NULL, '12日16时47分，北京市升级发布暴雨黄色预警', 0, 1, 1, '2025-08-12 17:30:49', '2025-08-12 16:51:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250812/b18a-b3645a08dd8d938b6d9ad921c3c2ab64.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncu7892953.shtml', '北京日报客户端', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">北京市发布暴雨黄色预警</font></p> \n<p cms-style=\"font-L\">　　目前，我市部分地区已出现强降雨并将持续，预计当前至夜间，房山、大兴、通州、丰台、朝阳、顺义、平谷、怀柔南部、密云等区将出现小时雨强超过50毫米或6小时降雨量超过70毫米的强降雨，个别点累计雨量可达100毫米以上，山区及浅山区可能出现强降水诱发的山洪、泥石流、滑坡等次生灾害，低洼地区可能出现积水，请注意防范。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250812/b18a-b3645a08dd8d938b6d9ad921c3c2ab64.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250812/b18a-b3645a08dd8d938b6d9ad921c3c2ab64.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4380, NULL, '上海机场进航站楼不再进行人身安检', 0, 1, 9, '2025-08-12 17:30:54', '2025-08-12 16:46:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/107/w550h357/20250812/77cc-92cc32c1272afe62ffc6cfd3854c17cf.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktnea4100761.shtml', '中国新闻周刊', '<p cms-style=\"font-L\">　　来源：中国新闻周刊</p> \n<p cms-style=\"font-L\">　　[上海机场进航站楼不再进行人身安检]记者今日从上海机场方面独家确认，上海虹桥机场和浦东机场今起优化出入口安检措施，进候机楼时不再进行人身和行李安检，只保留行李防爆检测。在此之前，乘客在上海两个机场搭乘航班时，除了需在登机前接受安检，还要在进入航站楼时就安检一次。国内其他机场有的与上海机场类似，有的只在航站楼入口处进行行李防爆检测。（第一财经）</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/107/w550h357/20250812/77cc-92cc32c1272afe62ffc6cfd3854c17cf.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/transform/107/w550h357/20250812/77cc-92cc32c1272afe62ffc6cfd3854c17cf.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4381, NULL, '河南“降本增效20条”如何落地？听听企业专家怎么说', 0, 1, 16, '2025-08-12 17:31:00', '2025-08-12 16:44:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/394/w1107h887/20250812/5373-75b347369ac3003e4f70818505655c53.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktnea4101045.shtml', '河南省政府网站', '来源：河南政府网\n<br>\n<br>\n<p cms-style=\"font-L\">　　近日，河南省人民政府印发《河南省支持企业降本增效若干政策措施》（以下简称《措施》），推动要素端、服务端、产业端、管理端协同发力降低企业成本。该项政策的出台对企业有何利好？企业降本增效的关键在哪儿？促进企业降本增效还能怎样做？听听企业专家怎么说——</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/394/w1107h887/20250812/5373-75b347369ac3003e4f70818505655c53.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"最高补助2000万，真金白银解决企业难题\" id=\"0\">\n <span class=\"img_descr\">最高补助2000万，真金白银解决企业难题</span>\n</div>\n<p cms-style=\"font-L\">　　当前，我省企业面临着原材料价格上涨、融资难融资贵、用工成本增加等一系列问题。如何打通卡点堵点，为企业发展增动力添活力？《措施》在落实国家关于降成本工作部署的前提下，聚焦账款清欠、信贷服务、要素供给、行政执法、信息获取等企业关注度高、涉及面广、反映强烈的重点领域和关键环节，因地制宜推出了一批政策措施。</p>\n<p cms-style=\"font-L\">　　《措施》基于对当前河南省经济发展形势的精准把握和对企业实际需求的深入调研，聚焦产业端、要素端、管理端、服务端“四端”，从10个方面提出了20项政策措施，力求发挥降本增效整体效能。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/384/w2048h1536/20250812/8e28-9a54e229351ce8583b5be70a8549da2c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center color210\">河南省药品监督管理局与交通银行河南省分行战略合作协议签约仪式暨“医证贷”产品发布会现场。</font></p>\n<p cms-style=\"font-L\">　　这20条政策涵盖了多个方面，从税费减免到融资支持，从降低用能成本到优化营商环境，每一条都直指企业发展中的痛点、难点。比如支持产业园区定制化标准厂房建设，面向中小微企业建设只租不售的“工业保障房”，鼓励运营方对租赁产业园区产业用房（含配套用房）的企业给予租金优惠，合理配套建设人才公寓、保障性租赁住房和创客交流新型空间。</p>\n<p cms-style=\"font-L\">　　同时，《措施》真金白银助力企业发展，支持企业开展产业链关键核心技术攻关，对重大攻关项目按照审定项目总投资额的30%给予支持，首次拨付补助资金总额的50%，通过验收后拨付剩余资金，单个项目补助金额最高不超过2000万元。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">成本降低了，企业更有竞争力了</font></p>\n<p cms-style=\"font-L\">　　郑州凯雪冷链股份有限公司是一家专注于冷链装备研发、生产和销售的企业。该公司郑州市冷链装备产业研究院院长龚毅对于《措施》的出台有着深切的体会，他直言，这20条措施给企业带来了实实在在的好处，让企业在发展的道路上更有底气。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/214/w2048h1366/20250812/5add-06a53509fc621bc079d1e0193554938b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"位于郑州凯雪冷链股份有限公司的中科·凯雪测试中心。\" id=\"2\">\n <span class=\"img_descr\">位于郑州凯雪冷链股份有限公司的中科·凯雪测试中心。</span>\n</div>\n<p cms-style=\"font-L\">　　“郑州凯雪冷链正在努力成为技术创新导向的科技型企业，在提质增效和降本增效方面也下足了功夫。政策的激励将大大地减少成本，有利于提高效率和效益，促进可持续发展。” 龚毅说，“根据政策，我们企业可以享受一些优惠，这直接减少了我们的支出，让我们有更多的资金投入新技术、新产品的研发中。目前，我们已经启动了一些研发项目，有望在冷链装备的节能、智能化方面取得新的突破。”</p>\n<p cms-style=\"font-L\">　　在谈及政策对企业市场竞争力的影响时，龚毅表示：“成本降低了，我们的产品在价格上就更具优势。同时，有了更多的资金投入研发，产品的质量和性能也能得到提升，这让我们在国内乃至国际市场上都更有竞争力。”</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">降本也得增效，企业发展有保障</font></p>\n<p cms-style=\"font-L\">　　实体经济企业特别是制造业企业，对用地、用能、物流成本较为敏感，河南省社会科学院经济研究所副研究员武文超表示，降低企业成本，能够提高企业的利润率，从而激励企业扩大生产、增加投资，进而带动就业和经济增长。</p>\n<p cms-style=\"font-L\">　　“这次降本增效政策实实在在地从企业的角度看待问题，因为企业运行就是要考虑原材料能源成本、用工成本、管理费用、财务成本等方方面面。”武文超认为，《措施》系统性强、精准度高，不仅降低企业运营成本和融资成本，还通过对技术创新、技术升级、数字化绿色化转型的支持，助力企业转型升级，提高效益。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/480/w768h512/20250812/c3fe-e68ba8e950f39c0b41c28aaf8eb9507b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center color210\">信阳市打造政务服务“企业会客厅”受理中心，让企业办事更省心。</font></p>\n<p cms-style=\"font-L\">　　“事实上，除了资金土地的优惠政策，当前我国区域发展竞争的重点正在向创新和营商环境转移。”武文超说。</p>\n<p cms-style=\"font-L\">　　《措施》不仅对科技创新给予补贴，还提出优化企业服务质效，健全“高效办成一件事”重点事项常态化推进机制，加快推进政务服务领域电子证照、电子材料、电子印章、电子签名应用，实现企业迁移登记与关联业务“一网通办、无感切换”。</p>\n<p cms-style=\"font-L\">　　关于进一步助力企业降本增效，武文超建议，强化产业链协同，建立区域供应链共享平台，规模化降低原材料、物流、仓储等方面成本。（杨露露 郭栩汝）</p>', '[\"https://k.sinaimg.cn/n/spider20250812/394/w1107h887/20250812/5373-75b347369ac3003e4f70818505655c53.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/384/w2048h1536/20250812/8e28-9a54e229351ce8583b5be70a8549da2c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/214/w2048h1366/20250812/5add-06a53509fc621bc079d1e0193554938b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/480/w768h512/20250812/c3fe-e68ba8e950f39c0b41c28aaf8eb9507b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4382, NULL, '河北张家口市蔚县3.1级地震，中国地震局迅速启动四级应急服务响应', 0, 2, 7, '2025-08-12 17:31:06', '2025-08-12 16:43:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvz8830981.shtml', '界面', '<p cms-style=\"font-L\">　　中国地震台网正式测定：8月12日14时1分在河北张家口市蔚县（北纬39.74度，东经114.63度）发生3.1级地震，震源深度12公里。</p> \n<p cms-style=\"font-L\">　　地震发生后，中国地震局迅速启动四级应急服务响应，调度中国地震台网中心、河北省地震局开展应急处置工作，要求有关单位开展联合会商，加强震情监测和震后趋势研判，及时报告有关情况。目前，河北省地震局已派出现场工作队赶赴震区，协助地方政府开展应急处置工作。</p> \n<p cms-style=\"font-L\">　　本次地震暂无人员伤亡情况报告。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4383, NULL, '广东佛山市新增报告基孔肯雅热确诊病例115例', 0, 2, 197, '2025-08-12 17:31:11', '2025-08-12 16:37:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvz8830862.shtml', '界面', '<p cms-style=\"font-L\">　　佛山市卫生健康局通报，8月11日，佛山市新增报告基孔肯雅热确诊病例115例，其中禅城区27例、南海区15例、顺德区68例、高明区2例、三水区3例。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">广东发现基孔肯雅热</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4384, NULL, '南宁市兴宁区原区委副书记、区长林涛严重违纪违法被开除党籍和公职', 0, 2, 213, '2025-08-12 17:31:15', '2025-08-12 16:30:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfvz8826341.shtml', '广西省纪委监委网站', '来源：广西纪检监察网\n<br>\n<br>\n<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　经自治区党委批准，自治区纪委监委对南宁市兴宁区原区委副书记、区长林涛严重违纪违法问题进行了立案审查调查。</p>\n<p cms-style=\"font-L\">　　经查，林涛丧失理想信念，背弃初心使命，对党不忠诚不老实，对抗组织审查；无视中央八项规定精神，违规收受礼品礼金，接受可能影响公正执行公务的宴请；违反组织原则，隐瞒不报个人有关事项；私欲膨胀，唯利是图，大搞权钱交易，利用职务便利以及职权和地位形成的便利条件，在工程项目承揽、城市建设有关业务等方面为他人谋利，并非法收受巨额财物。</p>\n<p cms-style=\"font-L\">　　林涛严重违反党的政治纪律、组织纪律、廉洁纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予严肃处理。依据《中国共产党纪律处分条例》《中华人民共和国监察法》《中华人民共和国公职人员政务处分法》等有关规定，经自治区纪委常委会会议研究并报自治区党委批准，决定给予林涛开除党籍处分；由自治区监委给予其开除公职处分；终止其南宁市第十三次党代会代表、兴宁区第十次党代会代表资格；收缴其违纪违法所得；将其涉嫌犯罪问题移送检察机关依法审查起诉；所涉财物一并移送。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4385, NULL, '北京已出现短时强降雨 最大降雨量53.9毫米', 0, 1, 1, '2025-08-12 17:31:28', '2025-08-12 16:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktfwe4221088.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　目前，北京西部北部已出现短时强降雨，密云出现局地暴雨。<font cms-style=\"font-L strong-Bold\">整个降雨过程自西南向东一路将覆盖整个北京地区。</font>从今天下午15点开始，门头沟、石景山、海淀等地开始降下大雨，随后降雨向东部地区蔓延。从今天早上8点到下午3点，北京全市平均降水量3.1毫米，<font cms-style=\"font-L strong-Bold\">最大降水量出现在密云花园村53.9毫米</font>。</p> \n<p cms-style=\"font-L\">　　记者从北京市气象台了解到，目前北京正处大风、暴雨及雷电蓝色预警中，今天有明显降水天气，短时雨强较大，并伴短时大风，山区可能有小冰雹，<font cms-style=\"font-L strong-Bold\">注意防雷避雨和出行安全，避免前往山区、河道等危险地带</font>。</p> \n<p cms-style=\"font-L\">　　（总台记者 张一郎）</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4386, NULL, '我为群众办实事丨监督点亮“民心灯”', 0, 2, 107, '2025-08-12 18:30:15', '2025-08-12 18:25:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktncx8748761.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　夏夜，桂林市临桂区黄沙瑶族乡黄沙村委朱家村的出村道路上，新安装的太阳能路灯在路面上投下暖黄光晕，七八个孩童在追逐嬉戏，三两位老翁倚坐石凳闲话家常，勾勒出一幅“灯火可亲、笑语盈盈”的夏夜图景，而在半年前，这里还是另一番景象。</p>\n<p cms-style=\"font-L\">　　“村道两旁没有安装路灯，每到晚上黑灯瞎火的，晚上出行十分不方便，老人小孩想饭后出去散步玩耍都不安全，要是能装上路灯就安心多了。”此前，该乡纪委在下沉走访时，有群众反映黄沙村委至朱家村道路两旁未安装路灯，且村里已将路灯安装纳入农村人居环境整治计划，但迟迟不见动静，严重影响了村民夜间出行和造成生活诸多不便。</p>\n<p cms-style=\"font-L\">　　“纳入了整治计划为何又不落实到位？”带着疑问，该乡纪委来到黄沙村委、乡村建设综合保障中心等部门了解情况。</p>\n<p cms-style=\"font-L\">　　“不是我们不想装，只是项目资金没到位，落实不了。”面对来访的乡纪委干部，该村党支部书记面露难色道。</p>\n<p cms-style=\"font-L\">　　经了解，朱家村距离主干道较远，加上电力和通信网络覆盖有限，部分项目资金还未拨付到位，导致项目推进缓慢。</p>\n<p cms-style=\"font-L\">　　路灯事虽小，却关乎民生、连接民心。为推动问题真正解决，该乡纪委立即把该问题纳入群众“急难愁盼”问题清单，建立“反馈—移交—督办”整改闭环机制，向乡村建设综合保障中心和黄沙村委制发了工作提示函，并对管片村干部及部门相关负责人进行提醒谈话，压实工作责任，督促主动作为、研究对策、解决问题。</p>\n<p cms-style=\"font-L\">　　在乡纪委跟踪督办下，该乡乡村建设综合保障中心组建了朱家村路灯建设工作小组，负责路灯前期建设的规划、设计及实施工作，并经多方协调向上级主管部门争取到乡村振兴补助资金30多万元，用于建设朱家村主干道路两旁太阳能路灯项目。</p>\n<p cms-style=\"font-L\">　　与此同时，该乡纪委通过对项目建设全程跟进监督，盯紧项目施工进度、资金支出等关键环节加强监督检查，积极协助施工队和村委解决路灯修建中的问题和困难。经过为期一个月的努力，黄沙村委至朱家村主干道路全部“点亮”，直接受益群众466户1000余人。（桂林市临桂区纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4387, NULL, '监督故事丨扎进报账单的门票', 0, 2, 222, '2025-08-12 18:30:24', '2025-08-12 18:24:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktncv5019197.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　前不久，龙胜县乐江镇纪委收到反映该镇某村原党支部书记杨某某，在党建活动中组织党员到名胜景区旅游观光，并用集体资金支付旅游景点门票的问题线索。</p>\n<p cms-style=\"font-L\">　　该镇纪委高度重视，迅速成立核查组展开调查。通过实地走访、个别谈话、查阅台账等方式层层抽丝剥茧，随着谈话的深入和当时的报账票据和凭证被一一找出，杨某某的违纪事实也逐渐清晰呈现。</p>\n<p cms-style=\"font-L\">　　“当时的党建活动方案里，行程并没有大南山名胜风景区，为什么又去了这里？”核查组工作人员向杨某某问道。</p>\n<p cms-style=\"font-L\">　　原来，为探索村级产业发展新路子，助力乡村振兴，杨某某便以开展党日活动为名，组织本村党员赴该县小南山考察黄牛、羊养殖场。观摩学习活动结束后，同行人员提议去大南山名胜风景区观光，纪法观念淡薄的杨某某当时并没有反对，甚至还自己垫资购买门票组织大家前往。</p>\n<p cms-style=\"font-L\">　　包括杨某某在内的村两委干部都没有意识到这种随意改变活动行程借机旅游、以党建活动名义变相公款旅游的行为是违规的，因而景区门票费也得以“顺利”地在“七一”党员活动的报账单中一起进行了报销。也正是这被“扎”在党建活动报账单中的景区门票，成为了杨某某违纪行为无可辩驳的铁证。</p>\n<p cms-style=\"font-L\">　　最终，杨某某因违反了中央八项规定精神及廉洁纪律，受到了党内警告处分，涉案资金全部退回到该县廉政账户。同时，该镇纪委对其余参与的2名村两委干部进行了谈话提醒。</p>\n<p cms-style=\"font-L\">　　针对该案出现的问题，该镇纪委把查处公款旅游及隐形变异问题作为日常监督重要内容，要求各村清廉乡村建设监督员对各村开展以考察学习为名外出的重点核查。同时，不定期组织各村党员开展纪法学习教育，从源头上做好防治。（龙胜各族自治县纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4388, NULL, '监督故事丨“劳务委托”背后的“猫腻”', 0, 2, 166, '2025-08-12 18:30:31', '2025-08-12 18:24:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktnea4144231.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　“没想到一笔笔涉农经费的账，能被查得这么细。”陆川县横山镇农业服务中心原主任陈某在谈话室里，看着面前整齐排列的证据材料，满脸懊悔。</p>\n<p cms-style=\"font-L\">　　此前，陆川县纪委监委第三纪检监察室在开展涉农资金专项监督检查时，一份蹊跷的劳务委托协议引起了检查人员的注意。在翻阅横山镇近5年涉农经费使用台账时，检查人员发现，由陈某签字审批的7份稻谷生产补贴、耕地地力补贴数据管理劳务协议中，被委托人竟全部指向同一人——大桥镇计生站原职工吕某某。</p>\n<p cms-style=\"font-L\">　　“为什么连续5年的涉农数据管理劳务，都委托给同一个人？”</p>\n<p cms-style=\"font-L\">　　“吕某某既不是横山镇本地人，也没有涉农工作相关资质，为何能承接专业性较强的补贴数据管理工作？”</p>\n<p cms-style=\"font-L\">　　涉农数据管理涉及农户信息核对、补贴标准核算等多项细致工作，检查组提出的这些问题背后似乎有“猫腻”。带着这些疑问，第三纪检监察室立即成立调查组，决定从这份反常的委托协议入手，依规开展初核工作。</p>\n<p cms-style=\"font-L\">　　调查组没有急于与当事人谈话，而是先调取了近5年的涉农经费财务凭证、银行对账单等书证，对协议中模糊的工作内容、不合理的报酬标准等细节反复比对。为确保证据链条严密、查证工作立体深入，调查组运用“室组地”联动机制，联合横山镇、大桥镇纪委开展实地走访，向工作涉及的职工、村干部了解涉农数据核查工作开展情况，同时找相关经手人员核实情况。走访过程中，调查组严格执行同步录音录像规定，将收集到的证言和资料按程序固化为规范笔录和书证。</p>\n<p cms-style=\"font-L\">　　随着调查深入，真相逐渐浮出水面。原来，陈某利用负责涉农经费审批的职务便利，与熟识的吕某某私下达成“默契”，虚构涉农数据管理劳务项目，通过签订虚假协议的方式，套取涉农工作经费。5年间，两人先后签订7份虚假协议，累计套取涉农工作经费2.96万元。</p>\n<p cms-style=\"font-L\">　　案件审理阶段，县纪委监委审理室对证据链完整性、程序合法性进行全面审核，反复推敲每一个环节，确保每一份证据都合法有效。最终，陈某、吕某某两人均受到相应党纪政务处分，所套取的2.96万元涉农工作经费被依法全额追回。</p>\n<p cms-style=\"font-L\">　　针对可能发生的类似“劳务委托”套取资金风险，县纪委监委举一反三，聚焦农作物补贴发放、农田水利项目经费使用等关键领域，运用大数据比对、实地查验、受理举报等方式深挖细查虚假项目、虚报冒领、优亲厚友等问题。去年以来，全县共立案13件，给予党纪政务处分8人。</p>\n<p cms-style=\"font-L\">　　此外，针对案件暴露的涉农经费监管漏洞，县纪委监委制发纪检监察建议，督促农业农村、财政等职能部门健全涉农经费审批流程，完善劳务外包项目审核机制，严格执行“事前评估、事中监管、事后审计”等制度。督促乡镇切实履行主体责任，对各村各站所委托服务进行台账化管理。同时鼓励群众监督和村务监督委员会参与，切实扎紧制度笼子，防止“劳务委托”成为蚕食涉农资金的“暗道”。（陆川县纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4389, NULL, '警方通报：南昌景区持剪刀伤人男子被刑拘，犯罪嫌疑人有精神治病治疗史', 0, 2, 120, '2025-08-12 18:30:48', '2025-08-12 18:08:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250812ac/374/w484h690/20250812/2bf8-f27db37598a7c013017f7be91dad36b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktnea4136541.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　[警方通报南昌景区伤人事件]#南昌景区持剪刀伤人男子被刑拘#</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/front20250812ac/374/w484h690/20250812/2bf8-f27db37598a7c013017f7be91dad36b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/47/w550h297/20250812/d27e-0f372b021f22a52769c51a6eed6515d0.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　相关新闻</p> \n<p>　　<strong>江西一景区内有19岁女大学生被男子捅伤致死？当地多方回应：正在处理中（<span>潇湘晨报</span>）</strong></p> \n<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/front20250812ac/374/w484h690/20250812/2bf8-f27db37598a7c013017f7be91dad36b9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/transform/47/w550h297/20250812/d27e-0f372b021f22a52769c51a6eed6515d0.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4390, NULL, '两部门：北京东北部、河南南部等地发生地质灾害的气象风险较高', 0, 1, 1, '2025-08-12 18:30:53', '2025-08-12 18:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/479/w700h579/20250812/ffa8-ff8825edc6a0a8ba913492fb25aa77b6.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktnea4140137.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">　央视网消息</font>：自然资源部与中国气象局8月12日18时联合发布地质灾害气象风险预警：</p>\n<p cms-style=\"font-L\">　　预计，8月12日20时至13日20时，北京东北部、天津北部、河北中部、河南南部、湖北北部和西部、湖南北部、四川西部、云南西部和南部、西藏东南部发生地质灾害的气象风险较高（黄色预警）。各级政府及有关部门按照应急预案做好地质灾害防御工作。请社会公众及时关注地质灾害气象风险预警信息，谨慎前往地质灾害预警区域。黄色预警区内人员，请随时关注预警信息变化，注意附近警示标志，避免在沟谷、斜坡、陡崖（坎）等高风险地带逗留。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250812/479/w700h579/20250812/ffa8-ff8825edc6a0a8ba913492fb25aa77b6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>', '[\"https://k.sinaimg.cn/n/spider20250812/479/w700h579/20250812/ffa8-ff8825edc6a0a8ba913492fb25aa77b6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4391, NULL, '00后将“炒菜多放父亲爱吃的辣椒” 写入先进事迹，引争议后被取消“吉林好人”候选资格', 0, 1, 7, '2025-08-12 18:31:00', '2025-08-12 17:46:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/69/w1080h1389/20250812/c99b-656160fb05092748b99c15c767c3b332.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncu7919933.shtml', '华西都市报', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">封面新闻记者 叶海燕</font></p> \n<p cms-style=\"font-L\">　　8月11日，吉林白城市精神文明办发布《关于白城市拟推荐申报2025年第二批“吉林好人”候选人的公示》。其中一名候选人齐某的孝老爱亲先进事迹，被网民质疑。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">记者在公示的候选人事迹中看到，齐某，女，2002年出生，镇赉县五棵树镇综合服务中心基层治理专干。践行孝道的事迹主要为：全程照料患糖尿病住院的奶奶、陪爷爷逛北京天安门；工作中，她耐心帮老人用手机办业务、教操作，入户帮做家务；生活里，记挂父母喜好，炒菜多放父亲爱吃的辣椒。该候选人事迹被网民质疑，</font><font cms-style=\"font-L strong-Bold\">“炒菜多放辣椒，这些事迹是不是太小了”。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/69/w1080h1389/20250812/c99b-656160fb05092748b99c15c767c3b332.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　11日下午，记者看到白城市精神文明办微信公众号上的候选人公示已删除。记者致电白城市文明办，工作人员表示，“这位候选人是五棵树镇作为基层推荐单位，依照推荐程序，逐级向上推荐的。我们也进行了实地复核，包括在当地也做了公示，才形成的推荐材料。这只是作为候选人推荐，省里还要层层把关，并不是评上‘吉林好人’了。”</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/783/w592h991/20250812/cce0-ecdabf64130e4ed914bf35ccd2d7ef80.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">工作人员表示，目前已经接到群众对候选人齐某候选事迹的质疑和反映，</font><font cms-style=\"font-L strong-Bold\">已经取消了齐某作为“吉林好人”的候选资格。</font><font cms-style=\"font-L\">“我们把相关材料现在进行二次审核，对于她的事迹，觉得确实比较弱，也反馈给镇政府了。目前我们把公示信息先撤了，处理后再重新进行公示，不能因为一个人影响其他人的候选。我们也会在今后的工作中，做出积极改正。”</font></p> \n<p cms-style=\"font-L\">　　记者在吉林省政府官网看到，“吉林好人”评选活动自2014年开展至今，评选范围为全省各行各业的干部群众，包括在省内学习、工作、生活的外来人员和驻地官兵，不限年龄、身份和籍贯，均可参选。各级“好人”候选人的产生，采用群众推荐、组织推荐、媒体推荐相结合的方式。评选标准主要分为助人为乐、见义勇为、诚实守信、敬业奉献、孝老爱亲五类。</p> \n<!--article_adlist[<p cms-style=\"font-L strong-Bold\"></p>]article_adlist--> \n<p></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/69/w1080h1389/20250812/c99b-656160fb05092748b99c15c767c3b332.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/783/w592h991/20250812/cce0-ecdabf64130e4ed914bf35ccd2d7ef80.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4392, NULL, '人社局回应时代少年团成员拟人才引进落户北京：公司有综合贡献，指标不占用普通名额', 0, 1, 1, '2025-08-12 18:31:27', '2025-08-12 15:47:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/647/w550h97/20250812/9376-b3cde0242b94af17c91740994658a494.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncu7920734.shtml', '九派新闻', '<p>　　来源：九派新闻</p> \n<p cms-style=\"font-L\">　　近期，北京市密云区公布了2025年拟引进非北京生源毕业生名单，其中时代峰峻旗下的两名艺人在名单内，引发网友争议。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/647/w550h97/20250812/9376-b3cde0242b94af17c91740994658a494.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"密云区2025年拟引进非北京生源毕业生名单。图/北京市密云区人民政府官网\" data-link=\"\">\n <span class=\"img_descr\">密云区2025年拟引进非北京生源毕业生名单。图/北京市密云区人民政府官网</span>\n</div> \n<p cms-style=\"font-L\">　　九派新闻注意到，不少网友对于该引进是否会占用普通人名额，引进是否符合规定仍有疑问。</p> \n<p cms-style=\"font-L\">　　8月12日，北京市密云区人力资源和社会保障局一工作人员表示，“时代峰峻引进的这两名毕业生符合相关规定和要求。”</p> \n<p cms-style=\"font-L\">　　工作人员称：“从用人单位角度上，依据《北京市引进毕业生管理办法》第六条规定：主管单位应结合发展需要分配指标。其中，各区人力资源社会保障部门应围绕区域功能定位，综合考量用人单位发展前景、财税贡献、吸纳就业、培养留用毕业生等情况进行分配。</p> \n<p cms-style=\"font-L\">　　“综上，时代峰峻对我区有综合贡献，符合《北京市引进毕业生管理办法》相关规定。”</p> \n<p cms-style=\"font-L\">　　其表示，“从毕业生方面，依据《北京市引进毕业生管理办法》第二条、第三条、第九条、第十条规定，时代峰峻符合的条件是：一是北京地区高校毕业生；二是文化行业的编剧、导演、演员、舞台技术等岗位，可引进教育部批准能够独立设置本科的艺术院校本科毕业生。”</p> \n<p cms-style=\"font-L\">　　对于许多网友关心是否会占用普通人名额，工作人员表示不会占用，“因为我们的指标是市局分配给我们的，依据《北京市引进毕业生管理办法》第十六条规定，主管单位应按照本办法建立健全毕业生重大事项决策程序，按照‘三重一大’决策制度实行集体研究决策，我们会把指标分配给用人单位。用人单位有相对独立的选人用人自主权，在单位内部选择分给哪个毕业生。”</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/68be-4b1415e3cc1ab9805e6650fdf3b3e4fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　本次拟引进的丁程鑫、张真源为时代少年团成员。时代少年团是由北京时代峰峻文化艺术发展有限公司推出的中国内地男子演唱组合，由马嘉祺、丁程鑫、宋亚轩、刘耀文、张真源、严浩翔、贺峻霖七人组成。</p> \n<p cms-style=\"font-L\">　　公开资料显示，丁程鑫2002年出生于四川，毕业于北京电影学院2021级表演实验班。张真源2003年出生于重庆市，毕业于中央戏剧学院音乐剧专业。</p> \n<p cms-style=\"font-L\">　　实习记者：孙梦婕&nbsp;</p> \n<p cms-style=\"font-L\">　　记者：吴迪</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/647/w550h97/20250812/9376-b3cde0242b94af17c91740994658a494.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/68be-4b1415e3cc1ab9805e6650fdf3b3e4fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4393, NULL, '官方：原定8月30日浙江vs天津比赛，改期至8月20日进行', 0, 1, 2, '2025-08-12 19:30:33', '2025-08-12 18:51:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/fd32-d3cacbeab9cf362d6a0034a97bbf17f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncv5033506.shtml', '直播吧', '<p cms-style=\"font-L \">　　来源：直播吧</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/fd32-d3cacbeab9cf362d6a0034a97bbf17f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　直播吧08月12日讯 官方宣布，原定于8月30日进行的中超第23轮，浙江vs天津津门虎的比赛将改期，调整至8月20日举行。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">官方公告如下：</font></p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/514/w550h764/20250812/0ff1-6a33aaa396afbb90396a27f710e59610.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　此前，原定于8月30日晚进行的大连英博vs青岛西海岸的比赛，已经调整至10月4日晚进行。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/427/w550h677/20250812/8ff9-d92cde91698e1e198b7efa52a77bcffa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1733881296\" target=\"_blank\">2025赛季中超联赛</a>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250812/fd32-d3cacbeab9cf362d6a0034a97bbf17f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/514/w550h764/20250812/0ff1-6a33aaa396afbb90396a27f710e59610.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/427/w550h677/20250812/8ff9-d92cde91698e1e198b7efa52a77bcffa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4394, NULL, '受台风“杨柳”影响 自然资源部针对福建启动海洋灾害四级应急响应', 0, 1, 13, '2025-08-12 19:30:38', '2025-08-12 18:43:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktncx8759465.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：据自然资源部微信公众号消息，受今年第11号台风“杨柳”（强热带风暴级）影响，福建沿海将有一次风暴潮过程，近岸海域将出现大浪到巨浪，国家海洋环境预报中心已发布风暴潮蓝色警报和海浪黄色警报。</p>\n<p cms-style=\"font-L\">　　根据《海洋灾害应急预案》规定，自然资源部决定于8月12日16时针对福建启动海洋灾害四级应急响应，要求福建省海洋主管部门、国家海洋环境预报中心、自然资源部海洋减灾中心、自然资源部东海局等单位组织做好应急监测、会商研判、预报预警以及灾害调查评估等工作。提醒涉海相关单位及时采取措施，组织渔船、养殖渔排、养殖场等做好防潮御浪准备。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4395, NULL, '家长网上发视频质疑校服质量被拘留，甘肃庆阳中院判警方违法', 0, 2, 302, '2025-08-12 19:30:52', '2025-08-12 18:29:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktncx8751045.shtml', '澎湃新闻', '<p>　　[家长网上发视频质疑校服质量被拘留，甘肃庆阳中院判警方违法]#家长网上质疑校服被拘警方被判违法#因在网上反映儿子学校校服存在质量问题，甘肃庆阳市宁县盘克镇36岁男子邓建国在校服厂商报案后，被宁县公安局网络安全监察大队以寻衅滋事行政拘留七天。被执行拘留后，邓建国提起行政诉讼，庆阳市中级人民法院二审认定，宁县公安局的行政处罚决定程序违法，认定事实证据不足，依法应予以撤销。鉴于案涉拘留决定已经执行完毕，无撤销的必要。但警方要承担7天拘留的国家赔偿3237.08元。</p> \n<!--WeiboOriginalContent[{\"text\": \"【#家长网上发视频质疑校服质量被拘留#，甘肃庆阳中院判警方违法】#家长网上质疑校服被拘警方被判违法#因在网上反映儿子学校校服存在质量问题，甘肃庆阳市宁县盘克镇36岁男子邓建国在校服厂商报案后，被宁县公安局网络安全监察大队以寻衅滋事行政拘留七天。被执行拘留后，邓建国提起行政诉讼，庆阳市中级人民法院二审认定，宁县公安局的行政处罚决定程序违法，认定事实证据不足，依法应予以撤销。鉴于案涉拘留决定已经执行完毕，无撤销的必要。但警方要承担7天拘留的国家赔偿3237.08元。 http://t.cn/A6sx4c6E\"}]WeiboOriginalContent--> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4396, NULL, '辽宁抚顺发生一起客车单方侧翻事故，造成4名乘客死亡', 0, 2, 38, '2025-08-12 19:30:56', '2025-08-12 18:27:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktncx8751576.shtml', '界面', '<p cms-style=\"font-L\">　　据“抚顺发布”，清原满族自治县公安局8月12日通报：8月12日10时40分许，抚顺市清原县大苏河乡双长线10公里处发生一起客车单方侧翻事故。事故发生后，公安、应急、消防救援、120急救等部门第一时间赶到现场开展紧急救援处置。目前，事故共造成4名乘客死亡，其他伤者均已被及时送医治疗，目前伤情平稳。涉事驾驶员已控制，排除酒驾毒驾和超员行为。事故正在进一步处理中。</p> \n<p>　　<strong>相关新闻</strong></p> \n<p>　　<strong>辽宁抚顺一旅游大巴在景区翻车，殡仪馆接到死者遗体，目前现场交通已恢复（极目新闻）</strong></p> \n<p>　　记者 李贤诚</p> \n<p>　　8月12日，多位网友爆料称，辽宁省抚顺市清原满族自治县红河峡谷漂流景区内，一辆旅游大巴发生翻车。8月12日下午，极目新闻记者从当地殡仪馆获悉，已收到此次事故中的死者遗体。当地官方表示，具体伤亡情况后续将对外通报，目前交通已恢复。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/674/w550h124/20250812/82b0-b5ca10eef0b4d085d2109f4732c19fe3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　12日下午，极目新闻记者致电清原满族自治县政府办、交通运输局和文化旅游和广播电视局，接线人员均表示，他们接到了上述大巴车翻车的汇报，工作人员已前往现场处理，具体情况他们暂不了解。</p> \n<p>　　清原满族自治县有关部门工作人员告诉极目新闻记者，等人员伤亡具体数据统计出来后，将对外通报，目前，现场交通已恢复畅通。</p> \n<p>　　公开报道显示，红河峡谷漂流作为清原旅游的金字招牌，是国家4A级旅游景区，漂流全长12.8公里，时长2.5小时，河水丰盈清澈，两岸森林茂密、怪石林立，是我国北方罕见的天然漂流场所，素有东北小三峡之称，荣获“中国北方第一漂”的美誉。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/437/w550h687/20250812/e66e-537ae94ffba1b31e9b7a09604063c175.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/674/w550h124/20250812/82b0-b5ca10eef0b4d085d2109f4732c19fe3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4397, NULL, '甘肃榆中：山洪灾害后 高考录取通知书全部送达！', 0, 1, 28, '2025-08-12 20:30:25', '2025-08-12 19:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/468/w1920h948/20250812/23ce-30869454ff33c2f8392452cee674086c.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktsmy4044342.shtml', '央视', '<p cms-style=\"font-L\">　　8月7日，甘肃省榆中县因持续强降雨引发山洪灾害，部分邮路中断。在道路紧急抢修后，当地邮政第一时间将高考录取通知书送至学生手里。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/468/w1920h948/20250812/23ce-30869454ff33c2f8392452cee674086c.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　灾害发生以来，榆中邮政梳理出9封送往受灾区域的高考录取通知书，其中有4封收件地址在灾情严重地区。</p> \n<p cms-style=\"font-L\">　　8月11日，榆中邮政收到一封酒泉职业技术大学的录取通知书，需要由快递员将其送至榆中县马坡乡的同学手中。而在3天前，他们也收到了一封新疆喀什大学的录取通知书。当时投递员踏着泥泞的道路，当天徒步6.8公里将通知书送到高崖镇的学生家中。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250812/478/w1920h958/20250812/833a-cd0a8399f66a7afe5c3b85e37cc324d0.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　目前，这9封受灾区域的录取通知书均已由专人逐一联系送达。</p> \n<p cms-style=\"font-L\">　　（总台记者 焦健 段博文）</p> \n<p cms-style=\"font-L\">　　&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754644472\" target=\"_blank\">甘肃榆中发生山洪灾害</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/468/w1920h948/20250812/23ce-30869454ff33c2f8392452cee674086c.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/478/w1920h958/20250812/833a-cd0a8399f66a7afe5c3b85e37cc324d0.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4398, NULL, '美国7月CPI同比上升2.7%', 0, 4, 207, '2025-08-12 21:30:15', '2025-08-12 20:33:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infktsmv8692191.shtml', '界面', '<p cms-style=\"font-L\">　　美国劳工部劳工统计局8月12日公布数据显示，美国7月CPI同比上升2.7%，环比上升0.2%，核心CPI同比上升3.1%。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4399, NULL, '俄美在阿拉斯加“试探性会晤”在即 乌欧率先“抱团取暖”为哪般？', 0, 4, 207, '2025-08-12 21:30:23', '2025-08-12 19:52:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/28ff-7a0f8e76ed30f09b4f1c2e6aa9ea4186.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktsmv8656139.shtml', '央视', '<p cms-style=\"font-L\">　　距离8月15日俄美领导人会晤越来越近，各方密集表态，不断释放信息。美国总统特朗普11日在白宫记者会上说，他在美国阿拉斯加州与俄罗斯总统普京的会晤将是一次“试探性会晤”，结果“或好或坏”，但相信双方会进行“建设性对话”。</p> \n<p cms-style=\"font-L\">　　俄美领导人会晤还没有开始，就已经搅动各方风云。特朗普抛出“试探性会晤”的说法，似乎有意降低外界期待；乌克兰则拉着欧盟说要确保自己的安全；欧盟也紧急开会，好像要为乌克兰撑腰。种种动作的背后，各方的真正目标是什么？</p> \n<p cms-style=\"font-L strong-Bold\">　　美方试图继续主导俄乌冲突解决进程</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">北京外国语大学区域与全球治理高等研究院教授 崔洪建：</font>首先，从美国的角度来看，这次会晤想要达到的目的是要继续延续美国特朗普政府上台以来所推动的乌克兰危机进程及美俄关系的缓和进程。前一段时间，由于战场形势的变化以及美国方面的策略调整，短期内美俄之间的矛盾上升，美国方面甚至用最后通牒的方式提出要对俄罗斯进行严厉制裁。在美国看来，如果现在能够实现一次和俄罗斯领导人的会晤，一定程度上能够缓和与俄罗斯的僵局，同时也能继续延续美国试图主导俄乌冲突解决的进程，这样的话就能服务于美国更大范围的全球战略的调整。</p> \n<p cms-style=\"font-L strong-Bold\">　　俄方借会晤缓解压力打破西方围堵</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/28ff-7a0f8e76ed30f09b4f1c2e6aa9ea4186.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">北京外国语大学区域与全球治理高等研究院教授 崔洪建：</font>俄美领导人会晤对俄罗斯来说，应该是一次外交上的突破。一方面，俄罗斯需要缓解来自美国的压力，同时俄罗斯要通过自身的外交策略，要不断去掌握乌克兰危机政治解决进程的主导权和节奏，不让美方按照自身的节奏去推进。俄罗斯能够去阿拉斯加州，事实上打破了欧美等西方国家对俄罗斯在外交上的围堵。</p> \n<p cms-style=\"font-L strong-Bold\">　　乌方试图坚持立场不甘于被美俄主宰</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/557b-e75c3b57d7b72fd0ad6d395553671ab7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">北京外国语大学区域与全球治理高等研究院教授 崔洪建：</font>对乌克兰方面来说，美俄领导人的会晤一定程度上让乌克兰问题的政治解决回到了特朗普刚上任时期，也就是由美俄主导，最终由乌克兰被动接受的一个局面。因此乌克兰方面现在主要的目标是要尽力对美俄领导人会晤施加影响，同时不断在停火、领土问题上表明自身的立场，因为只有这样，乌克兰方面才有可能避免被动接受美俄双方的协定或美俄双方的共识。与此同时，乌克兰的策略还在于要紧紧拉住欧洲，因为在乌克兰看来，只有和欧洲进行深度捆绑，把乌克兰的安全问题扩大成欧洲的安全问题，只有这样，才能加重它在未来自主决定进程的分量。</p> \n<p cms-style=\"font-L strong-Bold\">　　欧洲绑定乌方提升影响避免被边缘化</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">北京外国语大学区域与全球治理高等研究院教授 崔洪建：</font>至于欧洲，现在欧洲一定程度上也接受了乌方的这种说法，就是把乌克兰安全作为整个欧洲安全的一部分。甚至我们看到近一段时间以来，欧洲内部还在不断渲染俄罗斯的安全威胁。换句话说，欧洲的主要目的仍是要继续争取能参与到美俄主导的所谓竞争中，而且要从自身的立场出发，把自身的安全关切要放到美俄的议事日程中。所以我们看到近一段时间，无论是欧洲内部一些国家的联合发声，包括欧洲现在提出了比较明确的要和乌克兰提出一些共同的谈判原则等等，都可以看出，现在欧洲一方面在外交上还是要积极争取，能够获得和美俄一个相对平等的谈判地位。同时要通过继续在军事上支持乌克兰，对俄罗斯继续制裁等问题上，要发挥自己的影响力和作用。</p> \n<p cms-style=\"font-L\">　　所以从这个复杂的局面来看，这次美俄领导人在阿拉斯加会晤，应该说是在一个非常复杂的博弈环境下进行的。最终我觉得双方很难就俄乌冲突的解决达成更多的共识，可能双方会提出一些基本的方向或者是让双方的观点进行一些表达。因为接下来无论美俄之间达成何种共识，要让谈判成果真正落地，要让和平真正在俄乌之间以及在欧洲大陆上实现，其实离不开欧洲的配合和乌克兰的支持。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/28ff-7a0f8e76ed30f09b4f1c2e6aa9ea4186.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250812/600/w1920h1080/20250812/557b-e75c3b57d7b72fd0ad6d395553671ab7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4400, NULL, '“汽车第一省”易主，真相是什么？', 0, 1, 12, '2025-08-12 21:30:33', '2025-08-12 20:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/422/w1120h2502/20250812/2551-1225afbb5487c08a9815dde269b15589.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-08-12/doc-infktsmv8674796.shtml', '一财网', '<p cms-style=\"font-L\">　　在“法产并重”的新统计方法下，头部公司的产量直接影响到区域版图的变化，而中国的汽车产业版图能从数据上得到更为科学直观地反映。</p> \n<p cms-style=\"font-L\">　　近日，安徽超越广东成为“汽车第一省”的消息被广为传播。</p> \n<p cms-style=\"font-L\">　　根据公开数据，安徽上半年汽车产量149.95万辆，广东以131.34万辆排名第二。而2024年，广东省以全年汽车产量570.74万辆，位居第一，超过第二名安徽的262.03万辆两倍。</p> \n<p cms-style=\"font-L\">　　作为头部两个汽车大省，安徽和广东的产量何以在半年内突然发生落差巨大的身份互换？第一财经调查发现，这背后的关键因素是统计方法的改变。在整车制造领域，国家统计局自2021年推行“法产并重”的统计改革，随着该统计改革的持续推进，真实的汽车产业版图也正在浮出水面。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">变动最大的省份增幅超200%</font></p> \n<p cms-style=\"font-L\">　　据不完全统计，今年上半年，湖南、河南、江西、贵州的产量增幅都在50%以上，山东、江苏、四川云南和海南的增幅也在30%以上。</p> \n<p cms-style=\"font-L\">　　产量头部大省中，安徽今年上半年汽车产量149.95万辆，而去年上半年的产量为116.14万辆，同比增幅为29.1%。而广东则从去年的229.17万辆，掉到了今年的131.34万辆，跌幅42.7%。</p> \n<p cms-style=\"font-L\">　　而一些中西部省份，由于基数较小，变化幅度则更为明显。比如湖南从去年的20.46万辆，暴增到54.3万辆，增幅265.4%；贵州从2.66万辆增至9.74万辆，增幅266.2%。河南从35.09万辆增加到67.94万辆，增幅93.6%。山东、江苏两省的产量增量也在30万辆左右，半年产量也因此上了百万大关。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/422/w1120h2502/20250812/2551-1225afbb5487c08a9815dde269b15589.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　一位国内头部车企人士告诉第一财经，以往是按照法人所在地报送数据，如果法人在安徽，那在全国各地的工厂产量全部算到安徽，但从今年开始，要按照经营属地的原则了，就出现了大量产能统计归属地的变动。</p> \n<p cms-style=\"font-L\">　　在“法产并重”的新统计方法下，头部公司的产量直接影响到区域版图的变化，而中国的汽车产业版图能从数据上得到更为科学直观地反映。</p> \n<p cms-style=\"font-L\">　　以湖南为例，2024年，全省的汽车产量61万辆，但2025年上半年已达74.8万辆。除了比亚迪工厂已经建成投产之外，广汽埃安长沙工厂也于2024年8月21日正式竣工投产，具备20万辆/年的新能源车标准产能，并预留了后续产能提升空间。</p> \n<p cms-style=\"font-L\">　　受头部公司基地影响的并非只有湖南。比如头部公司中，比亚迪虽然总部位于深圳，但乘用车在国内现有9大生产基地：西安、济南、郑州、合肥、常州、襄阳、长沙、抚州、深圳。2024年，比亚迪西安工业园新能源汽车年产量突破100万辆，合肥的长丰超级工厂整车产量超95万辆，郑州基地的超级工厂生产整车54.5万辆。而奇瑞汽车除了在安徽，在河南也有生产基地。按照经营属地原则统计后，这些公司所在的总部地区汽车产量都会在统计数据上产生很大的波动。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“法产并重”已经连续推进多年</font></p> \n<p cms-style=\"font-L\">　　根据2011年的《统计单位划分及具体处理办法》，工业企业的法人单位，如经营地与工商登记住所不在同一县级行政区域，且经营地不能报送法人单位完整统计数据，按企业管理机构所在地统计。</p> \n<p cms-style=\"font-L\">　　随着新产业、新业态、新商业模式不断涌现，异地经营、跨业经营等现象越来越普遍，使得法人在地原则在准确反映地区和行业发展方面面临挑战。</p> \n<p cms-style=\"font-L\">　　近年来，为妥善解决一些大型企业分支机构因不具有法人资料而不纳统、探索解决常规年份跨地区产业活动单位在地统计等问题，国家统计局在充分试点的基础上，分步推进“法产并重”统计改革。</p> \n<p cms-style=\"font-L\">　　在汽车领域，是从2021年开始通过国家统计调查制度的形式推进汽车整车制造产业活动单位视同法人在地统计。记者获取的来自重庆、湖北、上海和杭州等地多份文件显示，国家统计局关于“法产并重”的统计改革正在陆续推行，各地推行的年份并不一致，跨度涉及2021年到2024年。</p> \n<p cms-style=\"font-L\">　　上海市统计局工业统计处培训用《工业统计报表制度修订说明（2022年统计年报和2023年定期统计报表）》中明确提到，“在调查对象中对汽车制造行业产业活动单位视同法人统计进行了修订”。</p> \n<p cms-style=\"font-L\">　　根据这个修订，“汽车整车制造行业产业活动单位视同法人单位按经营地在地原则进行统计。同时符合以下条件的跨省（区、市）汽车整车制造行业产业活动单位视同法人单位按经营地在地原则进行统计，有义务按照调查单位审核确认工作有关要求，及时在经营地所在统计机构申报纳入一套表统计调查范围，独立报送统计数据。”</p> \n<p cms-style=\"font-L\">　　这些条件包括如下三项，一是主营业务为汽车整车制造（汽车整车制造收入占企业总收入 50%以上）；二是拥有汽车整车制造资质和汽车整车制造生产线；三是年主营业务收入 2000 万元及以上。“符合上述条件的产业活动单位无论是否纳入一套表调查单位库，法人单位报送数据均不得包含以上跨省（区、市）产业活动单位数据。”</p> \n<p cms-style=\"font-L\">　　2024年，杭州市统计局的一份公开文件中也提到，根据国家制度规定，汽车整车制造行业产业活动单位视同法人单位按经营地在地原则进行统计。符合条件的跨省（区、市）汽车整车制造行业产业活动单位视同法人单位按经营地在地原则进行统计，基本条件与上述的上海修订说明培训文件中的条件完全一致。</p> \n<p cms-style=\"font-L\">　　有业内观点认为，在“法产并重”的统计改革下，数据可以更加全面客观精准反映分地区分行业经济发展情况，而数据的透明化则能够帮助倒逼行业高质量发展，促使地方政府更理性规划产能。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/422/w1120h2502/20250812/2551-1225afbb5487c08a9815dde269b15589.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4401, NULL, '宝妈带娃遛弯遭多人配合偷走手机，西安警方：作案团伙全部被抓', 0, 2, 283, '2025-08-12 21:30:42', '2025-08-12 20:39:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/317/w690h1227/20250812/bad7-a80b1deed155c036dfed7c7e7bb1ec2c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/o/2025-08-12/doc-infktsmv8672696.shtml', '新京报', '<p cms-style=\"font-L\">　　新京报讯 8月12日，西安市公安局雁塔分局发布警情通报。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/317/w690h1227/20250812/bad7-a80b1deed155c036dfed7c7e7bb1ec2c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/317/w690h1227/20250812/bad7-a80b1deed155c036dfed7c7e7bb1ec2c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4402, NULL, '时习之·总书记与人民在一起 寻古迹 看非遗 总书记重视文化传承', 0, 2, 288, '2025-08-12 21:30:54', '2025-08-12 20:31:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/xl/2025-08-12/doc-infktsmv8666657.shtml', '人民网', '<p>　　文化遗产承载着中华民族跨越千年的集体记忆，镌刻着文明发展的基因密码，是中华文明绵延赓续的历史见证。</p> \n<p>　　在贵州肇兴侗寨，观看侗族大歌表演；走进云南丽江古城，参观纳西族东巴文化研究成果展示；考察河南洛阳龙门石窟，察看石窟整体布局风貌和代表性窟龛、造像……今年以来，习近平总书记在地方考察时寻古迹、看非遗，多次强调加强文化保护与传承的重要意义。</p> \n<p>　　山高水阔，瑰宝不朽，中华文脉绵延永续。正如习近平总书记所说：“要把这些中华文化瑰宝保护好、传承好、传播好。”</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4403, NULL, '贵州茅台：上半年归母净利润454.03亿元，同比增长8.89%', 0, 1, 24, '2025-08-12 21:30:58', '2025-08-12 20:30:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktsmv8691706.shtml', '界面', '<p cms-style=\"font-L\">　　贵州茅台8月12日晚间公告，2025年<font cms-style=\"font-L\">上半年公司营业收入893.89亿元，同比增长9.10%；利润总额627.78亿元，同比增长9.03%；归属于上市公司股东的净利润454.03亿元，同比增长8.89%。</font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4415, NULL, '特朗普以“暴力犯罪”失控为由要接管华盛顿，犯罪率数据成争议焦点', 0, 4, 207, '2025-08-12 22:30:15', '2025-08-12 21:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/158/w1024h734/20250812/1893-89096b8400333f1ffede1e84828e66f1.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktsmv8699966.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　据央视新闻报道，当地时间11日，美国总统特朗普发表讲话称，将把华盛顿特区警察局置于联邦的直接管辖之下，并从当天开始部署国民警卫队，帮助重建华盛顿特区的法律、秩序和公共安全。同时宣布华盛顿特区进入公共安全紧急状态。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250812s/158/w1024h734/20250812/1893-89096b8400333f1ffede1e84828e66f1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间2025年8月11日，美国华盛顿特区，联邦探员在沃夫滨水区街道巡逻。 视觉中国 图\">\n <span class=\"img_descr\">当地时间2025年8月11日，美国华盛顿特区，联邦探员在沃夫滨水区街道巡逻。 视觉中国 图</span>\n</div> \n<p cms-style=\"font-L\">　　特朗普在讲话中称华盛顿特区“犯罪失控”、“暴力犯罪事件不断升级”，并表示将会把犯罪分子直接送入监狱，并称此次行动目标是“夺回首都”。特朗普9日曾表示，华盛顿特区已成为世界上最危险的城市之一，但很快将成为最安全的城市之一。</p> \n<p cms-style=\"font-L\">　　对此，民主党籍的华盛顿市长缪里尔·鲍泽（Muriel Bowser）10日表示，该市自两年前开始“犯罪率已大幅下降”，并且“暴力犯罪率处于30年来的最低水平”。另据新华社报道，美国警方数据显示，2025年前七个月，市内暴力犯罪案件数量较去年同期下降26%，全部犯罪案件数量同比下降约7%。</p> \n<p cms-style=\"font-L\">　　根据华盛顿特区大都会警察局 （MPDC） 公布的犯罪数据，华盛顿的暴力犯罪率在 2023 年达到顶峰后下降了35%，并在 2024 年创下30年来的最低水平。根据 2025 年的初步数据，它们正在继续下降——与 2024 年同期相比，今年的暴力犯罪总体下降了26%，抢劫下降了28%。美国犯罪统计数据的另一个主要来源美国联邦调查局（FBI）公开数据显示2024 年华盛顿暴力犯罪下降9%。尽管下降水平不同，但都一直显示出华盛顿的犯罪率呈下降趋势。</p> \n<p cms-style=\"font-L\">　　法律智库刑事司法委员会 （CCJ） 首席执行官亚当·盖尔布（Adam Gelb） 表示，下降趋势是“明确无误且巨大的”，且总体而言，自2023年夏天凶杀、枪支袭击、抢劫和劫车事件达到顶峰以来，至今暴力事件明显大幅下降。 据CCJ 研究美国30个大城市的犯罪率发现，2025年上半年（1月至6月）华盛顿的凶杀率与2024年同期相比下降了19%。这比研究样本中各城市17%的平均降幅略大。</p> \n<p cms-style=\"font-L\">　　BBC报道称，对于上述犯罪率数据，特朗普和华盛顿特区警察工会对数据真实性提出了质疑。</p> \n<p cms-style=\"font-L\">　　美国《军事时报》11日表示，陆军已启动约800名华盛顿特区国民警卫队士兵来支持全国首都的执法。有关国防官员则透露称，部队应该在本周中期抵达。曾担任国民警卫队局副局长的退役少将兰迪·曼纳 （Randy Manner）表示，华盛顿的犯罪情况远远达不到在他35年职业生涯期间或之后部署警卫队的“任何紧急标准”。他认为，“这不是真正的紧急情况”，而是总统正在“制造一种虚假局势”。同时，他对“警卫队士兵被从文职工作中拉出来，远离家人，成为字面上的、绝对的政治道具”表示失望。</p> \n<p cms-style=\"font-L\">　　据了解，陆军没有提供部署的成本估算，前军方官员预测，部署的成本可能来自国民警卫队的运营预算，金额可能达到数百万美元。前警卫队官员警告称，此次部署可能会从演习和个人训练中夺走资金，从而对战备状态产生负面影响。</p> \n<p cms-style=\"font-L\">　　美国媒体报道称，根据法律，联邦政府初次接管华盛顿特区警察局的权限最长为48小时，若要延长接管时间，则需国会两院批准。</p> \n<p cms-style=\"font-L\">　　众议院少数党领袖、民主党人杰弗里斯当天批评称，特朗普政府的做法“不具合法性”，“我们与华盛顿特区的居民站在一起，拒绝这毫无正当理由的夺权行为”。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754925007\" target=\"_blank\">特朗普宣称要“解放首都”</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/158/w1024h734/20250812/1893-89096b8400333f1ffede1e84828e66f1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4416, NULL, '韩国队33分狂胜关岛轻松晋级！八强赛将对阵中国！', 0, 4, 105, '2025-08-12 22:30:24', '2025-08-12 20:31:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/78/w550h328/20250812/44ec-b97ec4c60b14e56c449ca5763351e7a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktwtq7730316.shtml', '直播吧', '<p cms-style=\"font-L \">　　来源：直播吧</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/78/w550h328/20250812/44ec-b97ec4c60b14e56c449ca5763351e7a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　直播吧08月12日讯 <font cms-style=\"font-L\">今日男篮亚洲杯1/4决赛资格赛 ，韩国队99-66狂胜关岛，晋级1/4决赛，下场将对阵中国队。</font></p> \n<p cms-style=\"font-L\">　　本场比赛首节，韩国队三分线外手感不佳，11投仅1中。但他们迅速调整状态，依靠篮板优势与反击打出33-10的攻击波，迅速反超比分，并不断扩大领先优势，最终轻取对手。</p> \n<p cms-style=\"font-L\">　　8月14日亚洲杯1/4决赛（八强赛），中国将对阵韩国.</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754407980\" target=\"_blank\">2025年男篮亚洲杯</a>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/78/w550h328/20250812/44ec-b97ec4c60b14e56c449ca5763351e7a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4417, NULL, '首进正赛！成都蓉城3-0曼谷联晋级亚冠精英 杨明洋破僵费利佩双响', 0, 2, 231, '2025-08-12 22:30:34', '2025-08-12 21:48:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/523/w335h188/20250812/2833-72a6487f8286cb973f538a2ad1847f3c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-12/doc-infktwtr4813485.shtml', '新浪新闻综合', '<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/523/w335h188/20250812/2833-72a6487f8286cb973f538a2ad1847f3c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　直播吧8月12日讯 北京时间8月12日晚上19:35，亚冠精英联赛附加赛，成都蓉城坐镇五粮液文化体育中心专业足球场迎战曼谷联。上半场，罗慕洛远射造威胁。下半场，杨明洋头球建功，费利佩单刀梅开二度。全场结束，成都蓉城3-0曼谷联。本场过后，成都蓉城顺利晋级亚冠精英联赛正赛。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/512/w550h762/20250812/c321-c181f0ce7bb5823a40dcadd245793395.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\" data-link=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/523/w335h188/20250812/2833-72a6487f8286cb973f538a2ad1847f3c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/transform/512/w550h762/20250812/c321-c181f0ce7bb5823a40dcadd245793395.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4418, NULL, '韩国前第一夫人金建希被拘押', 0, 4, 105, '2025-08-12 23:30:15', '2025-08-12 23:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/81/w550h331/20250812/acff-0b4247cb7ec67fc309433af48e36e28a.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktwtr4837420.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/81/w550h331/20250812/acff-0b4247cb7ec67fc309433af48e36e28a.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\" △韩国前第一夫人金建希（资料图）\">\n <span class=\"img_descr\"> △韩国前第一夫人金建希（资料图）</span>\n</div> \n<p>　　当地时间12日深夜，韩国首尔中央地方法院签发对前第一夫人金建希的拘捕令，金建希随后被首尔南部拘留所拘押。（总台记者 张昀）</p> \n<p>　　<strong>此前报道：</strong></p> \n<p>　　<strong>金建希是否被捕最早今晚见分晓！她提前40分钟到法院接受审查，将在看守所等结果（红星新闻）</strong></p> \n<p cms-style=\"font-L\">　　首尔中央地方法院于12日上午10时10分许开始对韩国前总统尹锡悦夫人金建希进行拘捕必要性审查。据称，法院是否签发逮捕令将于当天晚间或次日凌晨见分晓。若金建希被批捕，韩国宪政史上将首次出现“前总统夫妇同时被捕”的情况。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/265/w1585h1080/20250812/c7ab-a39b9314779996a97de3bc3c52dad491.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲当地时间2025年8月12日，韩国前第一夫人金建希抵达首尔中央地方法院，出席逮捕必要性审查&nbsp;图据视觉中国\">\n <span class=\"img_descr\">▲当地时间2025年8月12日，韩国前第一夫人金建希抵达首尔中央地方法院，出席逮捕必要性审查&nbsp;图据视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　据介绍，负责调查金建希相关案件的金建希特检组本月7日以涉嫌违反《资本市场法》《政治资金法》《特定犯罪加重处罚法》等为由提请法院批捕金建希。特检组方面11日表示，特检组先后在7日和11日向法院提交了总计超过800页的拘留意见书。</p> \n<p cms-style=\"font-L\">　　据此前报道，金建希特检组此前就股价操纵案、介入选举案、收受请托人贿赂案讯问了金建希，时间长达7小时23分钟。后者并未拒绝陈述，但基本否认了所有指控。</p> \n<p cms-style=\"font-L\">　　目前，特检组检察官认为金建希正在与其他嫌疑人“串供”，其毁灭证据的可能性很大，因此要拘留她。金建希方律师则反驳称，金建希没有潜逃风险，且身体状况不佳。</p> \n<p cms-style=\"font-L\">　　12日上午，金建希抵达首尔中央地方法院出席拘捕必要性审查。据悉，她需在法院作出决定前陈述自己的论点。</p> \n<p cms-style=\"font-L\">　　据报道，与上一次迟到近十分钟不同，这次金建希提前近40分钟抵达法院。报道称，有媒体问她“是否就奢侈品礼物一事向检察官交代真相”“自称‘nobody’（无足轻重的人）有什么特别的含义”，但金建希一直保持沉默。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/254/w1574h1080/20250812/0f00-9bfb0e8b197fe875a54c76dc1d3fe7d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲当地时间2025年8月12日，韩国前第一夫人金建希（中）抵达首尔中央地方法院，不少媒体已在此等候 图据视觉中国\">\n <span class=\"img_descr\">▲当地时间2025年8月12日，韩国前第一夫人金建希（中）抵达首尔中央地方法院，不少媒体已在此等候 图据视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　报道称，审查结束后，金建希将前往位于首尔南部的看守所等待结果出炉。据悉，金建希原计划前往位于京畿道义王市的首尔看守所，但特检组向法院提出更改收押地点申请。值得注意的是，尹锡悦正被羁押在首尔看守所。</p> \n<p cms-style=\"font-L\">　　若法院签发逮捕令，预计针对金建希的调查范围将扩大。若法院驳回逮捕令申请，检察官可能会在进一步讯问后再次申请逮捕令。</p> \n<p cms-style=\"font-L\">　　红星新闻记者 黎谨睿 综合央视新闻</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/81/w550h331/20250812/acff-0b4247cb7ec67fc309433af48e36e28a.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/265/w1585h1080/20250812/c7ab-a39b9314779996a97de3bc3c52dad491.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/254/w1574h1080/20250812/0f00-9bfb0e8b197fe875a54c76dc1d3fe7d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4419, NULL, '泽连斯基称其将与普京和特朗普会晤', 0, 4, 204, '2025-08-12 23:30:23', '2025-08-12 22:10:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/7e7b-a7013aae22beb7e9b207a1b0187af7d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktwtw3987714.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，乌克兰总统泽连斯基表示，他将同俄罗斯总统普京和美国总统特朗普会晤，但时间期限尚不明确。（总台记者 王德禄）</p> \n<p cms-style=\"font-L \">　　<strong>相关新闻</strong></p> \n<p cms-style=\"font-L \">　　<strong>消息人士：泽连斯基立场软化，乌克兰可能同意停火并在领土问题上让步（观察者网）</strong></p> \n<p cms-style=\"font-L\">　　[文/观察者网 熊超然]随着美俄元首阿拉斯加会谈即将登场，外界越来越关注此次各方会讨论哪些内容，以真正实现结束俄乌冲突这一目标。</p> \n<p cms-style=\"font-L\">　　当地时间8月11日，英国《每日电讯报》披露报道称，作为欧洲支持的和平计划的一部分，乌克兰可能同意停止战斗，并同意俄罗斯获得冲突期间所拿下地区的控制权。乌克兰总统泽连斯基告诉欧洲领导人，他们必须拒绝美国总统特朗普提出的任何乌克兰放弃更多领土的解决方案，但俄罗斯可以保留部分已占领土地。</p> \n<p cms-style=\"font-L\">　　报道称，泽连斯基的这一谈判立场软化，意味着当前冲突前线的战火将被冻结，并让俄罗斯实际控制其在乌东四地（卢甘斯克、顿涅茨克、扎波罗热、赫尔松）以及克里米亚的占领区。</p> \n<p cms-style=\"font-L\">　　与此同时，路透社报道称，特朗普当地时间8月11日在白宫举行的新闻发布会上则表示，他与俄罗斯总统普京即将举行的阿拉斯加会谈是一次“试探性会谈”（feel-out meeting），是为了确定普京是否愿意达成协议，而他在两分钟内就能知道是否有可能取得进展。“因为这就是我的工作，我做交易。”</p> \n<p cms-style=\"font-L\">　　特朗普表示，乌克兰和俄罗斯必须相互在土地问题上让步才能结束冲突，“所以我要去和普京谈谈，我要告诉他，你必须结束这场冲突，你必须结束它”。特朗普称，未来的会谈可能会包括泽连斯基，最终变成三方会谈，他还会在与普京会谈后不久与欧洲领导人对话，目标是迅速实现这场血腥冲突的停火。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/7e7b-a7013aae22beb7e9b207a1b0187af7d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月11日，美国华盛顿，白宫詹姆斯·S·布雷迪新闻发布室，美国总统唐纳德出席新闻发布会。 视觉中国\">\n <span class=\"img_descr\">当地时间8月11日，美国华盛顿，白宫詹姆斯·S·布雷迪新闻发布室，美国总统唐纳德出席新闻发布会。 视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　路透社称，特朗普过去曾谈到土地交换，但俄罗斯和乌克兰都无意将土地作为和平协议的一部分。欧洲人则担心，对俄罗斯做出重大让步可能会在未来给西方带来安全问题。</p> \n<p cms-style=\"font-L\">　　目前，俄罗斯控制着乌克兰约五分之一的领土，而乌克兰几乎没有控制俄罗斯的任何领土。</p> \n<p cms-style=\"font-L\">　　不过，特朗普仍然坚称，“将会有一些土地交换和调整”。“我通过俄罗斯以及与各方的对话了解到这一点，这有利于乌克兰。”他表示，俄罗斯占领了一些“非常重要的领土”，“但我们将努力夺回部分领土”。</p> \n<p cms-style=\"font-L\">　　《每日电讯报》称，乌克兰和欧洲方面如今越来越担心，特朗普和普京可能会越过泽连斯基，通过谈判结束这场长期冲突。</p> \n<p cms-style=\"font-L\">　　比如，波兰总理图斯克当地时间8月11日就表示：“我有很多担忧，但也抱有很大希望。”他还表示，美国官员已承诺在特朗普和普京举行面对面会谈之前与欧洲领导人磋商。</p> \n<p cms-style=\"font-L\">　　欧洲最主要的担忧，是俄罗斯支持的一项“和平计划”，该计划包括：如果乌克兰同意从其控制的顿涅茨克和卢甘斯克地区撤军，则冻结乌克兰东南部的战线。</p> \n<p cms-style=\"font-L\">　　欧洲外交官们声称，普京的总体军事目标没有明显变化，他的目标是推翻乌克兰的亲西方政府，并用一个“亲俄代理人”取而代之。而据美国智库战争研究所的一份报告称，俄罗斯仍然希望乌克兰“全面投降”，包括阻止其加入北约和实现非军事化。</p> \n<p cms-style=\"font-L\">　　当地时间8月11日晚间，泽连斯基表示，尽管和平谈判迫在眉睫，但没有迹象表明俄罗斯准备结束冲突。他还援引乌克兰情报部门的一份报告称：“相反，他们正在调动军队和兵力，准备发动新的进攻行动。”</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/de18-6835dbed1d2a9d95e37ec53a7113795d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。 视觉中国\">\n <span class=\"img_descr\">当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。 视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　《每日电讯报》称，虽然乌克兰看起来愿意让出部分领土，但只会同意达成包含以下条件的和平协议，包括获得以武器援助形式提供强有力的安全保障，并为其加入北约开辟道路。</p> \n<p cms-style=\"font-L\">　　而欧洲各国政府则选择支持基辅方面提出的任何领土交换方案，试图让特朗普相信，围绕“乌克兰与欧洲共同划定的红线”，即拒绝在乌方控制的领土上作出让步，已形成具有外交分量的统一阵线。</p> \n<p cms-style=\"font-L\">　　“欧洲人现在明白了他们在外交谈判中支持乌克兰的角色，”一名西方官员表示：“这鼓舞了士气，也加强了乌克兰的外交地位，使其不再感到孤立无援。”</p> \n<p cms-style=\"font-L\">　　“对波兰和我们的伙伴来说，国家边界显然不能用武力改变，”图斯克则表示：“俄乌冲突绝不能给‘侵略者’带来好处。”</p> \n<p cms-style=\"font-L\">　　上周末，法国总统马克龙和德国总理默茨发表的声明，支持对领土让步采取强硬立场。而欧盟委员会、法国、意大利、英国、波兰和芬兰领导人发表的联合声明称，“目前的接触线应该成为谈判的起点”。</p> \n<p cms-style=\"font-L\">　　虽然特朗普已经“预告”，他将在和普京会谈后再同欧洲领导人对话，但欧洲领导人计划于当地时间8月13日，也就是美俄元首会谈之前，同特朗普再次举行会谈，向他阐述欧方的主张。</p> \n<p cms-style=\"font-L\">　　《每日电讯报》认为，尽管如此，但仍不排除泽连斯基可能会做出艰难决定，在领土问题做出让步。欧洲官员们也认为，泽连斯基拥有一些回旋余地，因为越来越多的国内选民愿意以领土换取冲突结束。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/aaae-ae989e5655ea830b45c935af22aa557f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。 视觉中国\">\n <span class=\"img_descr\">当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。 视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　不过，基辅方面几乎无法承受继续“领土让步”的代价，特别是在顿涅茨克东部地区，因为这将使俄军能够自由绕过自2014年顿巴斯冲突以来修建的防御工事。此外，根据乌克兰宪法，泽连斯基无法在未经全民公投的情况下作出相关决定。</p> \n<p cms-style=\"font-L\">　　当地时间8月9日，泽连斯基曾发表视频讲话强硬表态，坚称乌克兰人“不会将自己的土地送给占领者”。“乌克兰领土问题的答案已写入乌克兰宪法。没有人会偏离这一点——也没有人能够偏离，”他说：“乌克兰已准备好做出能够带来和平的真正决定。任何对我们不利的决定，任何不考虑乌克兰的决定，同时也是违背和平的决定。”</p> \n<p cms-style=\"font-L\">　　值得注意的是，对于泽连斯基拒绝让步，特朗普当地时间8月11日这样批评道：“泽连斯基说‘我必须获得宪法批准’，这让我有点不安。我的意思是，他可以发动冲突，杀光所有人，但进行土地交换却需要批准？”</p> \n<p cms-style=\"font-L\">　　此前，泽连斯基曾提议用乌克兰控制的俄罗斯库尔斯克地区领土进行交换，但随着俄军成功瓦解了乌方在该边境地区的控制，使这一谈判筹码化为乌有。泽连斯基此前也承认，其武装部队缺乏收复被占领土所需的作战能力，但他表示，在任何和平协议达成后，基辅方面仍可通过外交手段使这些领土重归乌克兰控制。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/7e7b-a7013aae22beb7e9b207a1b0187af7d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/de18-6835dbed1d2a9d95e37ec53a7113795d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/533/w800h533/20250812/aaae-ae989e5655ea830b45c935af22aa557f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4420, NULL, '扎波罗热核电站所在区域冒出浓烟 原因不明', 0, 4, 204, '2025-08-12 23:30:32', '2025-08-12 22:01:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/641/w922h519/20250812/aa6a-69a528f136ba7f57abcab84e21d5e691.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-12/doc-infktwtw3990066.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/641/w922h519/20250812/aa6a-69a528f136ba7f57abcab84e21d5e691.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，扎波罗热核电站所在区域产生浓烟，原因尚不明确。</p> \n<p cms-style=\"font-L\">　　核电站管理方暂未发表声明。（总台记者 王德禄）</p> \n<p cms-style=\"font-L\">　　&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/641/w922h519/20250812/aa6a-69a528f136ba7f57abcab84e21d5e691.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4421, NULL, '“立邦”创始人吴清亮逝世，曾以130亿美元登顶新加坡首富', 0, 4, 175, '2025-08-12 23:30:38', '2025-08-12 21:49:00', NULL, NULL, NULL, 'https://news.sina.com.cn/o/2025-08-12/doc-infktwtq7731434.shtml', '一财网', '<p cms-style=\"font-L\">　　“亚洲漆王”吴清亮于8月12日去世，享年98岁。</p> \n<p cms-style=\"font-L\">　　与油漆打了大半辈子交道的“亚洲漆王”走了。</p> \n<p cms-style=\"font-L\">　　8月12日，吴德南控股集团创办人、“立邦”品牌创始人吴清亮去世，享年98岁。 吴氏家族发布声明称，吴清亮在新加坡家人陪伴下安详离世。</p> \n<p cms-style=\"font-L\">　　吴清亮1927年出生于新加坡，祖籍广东省潮州市潮安区浮洋镇大吴村。出身贫苦的他白手起家，从一贫如洗的打工仔到富甲一方的“亚洲漆王”，成为一代商界传奇。</p> \n<p cms-style=\"font-L\">　　1962年，吴清亮的公司被日本著名老字号油漆制造商“日本漆”（ Nippon Paint）相中，决定合资经营油漆生意。日本漆是日本最大的涂料供应商，创办于1881年，也是日本的第一家涂料企业。</p> \n<p cms-style=\"font-L\">　　双方合资创办了立时集团，其中，吴清亮掌控的私人公司吴德南集团持股60%，日本漆公司占股40%。吴清亮负责管理合资公司在亚洲区的所有业务活动，通过技术引进和本地化运营，实现了行业的快速扩张，奠定了他在亚洲涂料市场的主导地位。</p> \n<p cms-style=\"font-L\">　　1990年，中国跟新加坡建立邦交。这让祖籍潮州的吴清亮感到无比的振奋。据说，当时吴清亮看到 “建立邦交”四个字便为自己的油漆品牌起名“立邦”。这里的“立”是指“立时”，“邦”是为了纪念中国与新加坡建立邦交关系。</p> \n<p cms-style=\"font-L\">　　同年，立时集团开始筹划进入中国。1992年，立时集团在中国注册成立第一家公司，成为较早进入中国的跨国企业之一。</p> \n<p cms-style=\"font-L\">　　彼时国内还没有涂料的概念，吴清亮曾回忆说自己回到潮州老家，发现很多地方都是用白水泥、白石灰来涂墙。这也让初到中国的立邦发展并不顺利，“前期投资的规模很大，亏得很惨”。但吴氏仍然坚持了自己对中国市场的判断：“中国市场太大了，我看准了中国绝对不会让我失望。”</p> \n<p cms-style=\"font-L\">　　经过多年坚持，如今立邦品牌逐渐深入人心，成为中国涂料行业的知名品牌。吴清亮曾表示在中国投资是立时集团最明智的决策之一。</p> \n<p cms-style=\"font-L\">　　根据立邦中国官网，目前立邦中国区总部设立于上海，在中国投资建设超过70家生产基地，员工近1<font cms-style=\"font-L\">。</font>1万人。</p> \n<p cms-style=\"font-L\">　　2020年8月，上市公司日本涂料控股株式会社发布公告称，公司与新加坡吴德南集团达成总价值1<font cms-style=\"font-L\">。</font>29万亿日元的交易协议，完成交易后将成为该集团的子公司。</p> \n<p cms-style=\"font-L\">　　2025年5月，吴清亮以净值130亿美元（约934亿元人民币）的个人财富，登上《福布斯》全球富豪榜第182位，新加坡第一。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4422, NULL, '台风“杨柳”来袭，珠江防总、珠江委启动Ⅳ级应急响应全力防范', 0, 1, 19, '2025-08-12 23:30:54', '2025-08-12 22:14:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktwtt8595452.shtml', '界面', '<p cms-style=\"font-L\">　　8月12日14时，今年第11号台风“杨柳”位于台湾台东市东偏南约590公里的西北太平洋洋面上，预计“杨柳”将于13日中午前后在台湾登陆，并将于13日夜间至14日凌晨在福建南部到广东东部一带沿海再次登陆。</p> \n<p cms-style=\"font-L\">　　受台风“杨柳”影响，8月13-15日，珠江流域自东向西将出现一次强降雨过程，福建南部、广东中东部、广西中北部等地有50~100毫米，部分地区可能有100~200毫米。预计，西江支流桂江、贺江，北江干流及支流连江，东江支流新丰江，韩江等河流将出现明显涨水过程，暴雨区内发生中小河流超警洪水、山洪地质灾害、城市内涝风险较大。鉴于台风防御形势，珠江防总决定于8月12日19时启动防汛防台风Ⅳ级应急响应，珠江委同步启动洪水防御Ⅳ级应急响应。</p> \n<p cms-style=\"font-L\">　　珠江防总常务副总指挥、珠江委主任吴小龙高度重视台风“杨柳”暴雨洪水防御工作，强调要深入贯彻习近平总书记关于防汛救灾工作的重要指示精神，全面落实水利部部署要求，毫不松懈坚持防汛关键期精神状态、工作机制，锚定防汛“四不”目标，做到风险预报预警再细化、隐患排查整治再深入、应急值班值守再加强，以万全准备做好防汛防台风各项工作，全力保障人民群众生命财产安全。8月12日，珠江委召开防汛会商会，滚动分析研判台风“杨柳”动态和流域防汛形势，针对性部署台风暴雨洪水防御工作。</p> \n<p cms-style=\"font-L\">　　会商要求，一是紧盯台风发展态势、移动路径、强降雨影响范围，滚动会商研判，加密洪水预测预报频次，及时发布预警信息。二是系统、科学、安全、精准调度流域防洪工程体系，充分做好韩江、东江、北江、贺江等流域水库群调度运用准备，适时拦洪削峰错峰；同时，在确保防洪安全的前提下，统筹多目标综合调度，实现水资源综合效益最大化。三是突出抓好山洪灾害防御，聚焦山洪沟道口、网红旅游景区、施工工地等关键区域，严格落实临灾预警“叫应”机制和“五个关键环节”责任、措施，坚决避免人员伤亡。四是严密防范中小河流洪水，指导地方强化薄弱环节巡查防守，预置抢险力量、料物、设备，及时排查处置险情，第一时间转移受威胁群众。五是切实做好涉水在建工程、中小水库、病险水库等安全度汛工作，督促“三个责任人”全部上岗到位，“三个重点环节”全部执行到位，前期受损水利工程及时落实应急保障措施，确保安全度汛。六是强化24小时值班值守和信息报送，加强水情预报、工程调度、数字推演等专业力量联合值守，及时报送汛情、险情、水工程调度及防御工作情况。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4423, NULL, '中国海洋大学人才政策引关注：无“非升即走”，不实行竞争性淘汰', 0, 1, 15, '2025-08-12 23:31:04', '2025-08-12 22:05:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-12/doc-infktwtt8588823.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　近日，中国海洋大学的一份引才政策引起国内高教界的广泛关注。</p> \n<p cms-style=\"font-L\">　　澎湃新闻记者注意到，“中国海洋大学”微信公众号在8月2日发布了一则消息《@全球英才，中国海大诚邀您申报国家优青（海外）项目（新增批次）！》。</p> \n<p cms-style=\"font-L\">　　消息介绍，中国海洋大学大力实施新时代人才强校战略，构建完善了独具海大特色的“筑峰”“繁荣”“绿卡”“英才”等人才工程体系，坚持内涵式发展，为人才的引进、培养和发展提供了良好的沃土，全力支持青年学者开展高水平原创性、引领性研究。中国海洋大学诚挚邀请全球英才依托学校申报2025年国家优秀青年科学基金（海外）项目（新增批次），共谱蓝色华章。</p> \n<p cms-style=\"font-L\">　　引起关注的，是中国海洋大学在这份引才政策中的第一项就明确“稳定的职业保障”。具体来看：聘任为学校高层次人才工程教授，纳入学校事业编制，聘为博士生导师，设有薪酬增长机制，享受良好的学术环境，无“非升即走”，不实行竞争性淘汰。</p> \n<p cms-style=\"font-L\">　　此外，中国海洋大学还在这一政策中给出了“优渥的薪酬待遇”“充足的经费保障”“完备的团队支撑”“优质的生活保障”“全过程的申报服务”等扶持项目。另外，中国海洋大学还特别说明：对于进入会评阶段但未入选人员，经学校人才引进程序，可聘为学校人才工程教授（事业编制），享受相关待遇。</p> \n<p cms-style=\"font-L\">　　中国海洋大学始建于1924年，坐落于青岛，1960年被中共中央确定为全国13所重点综合大学之一，1981年成为我国首批博士和硕士学位授予单位，先后入选国家“211工程”“985工程”重点建设高校，2017年入选国家“世界一流大学建设高校”（A类）。</p> \n<p cms-style=\"font-L\">　　这几年，部分高校“非升即走”政策争议连连。</p> \n<p cms-style=\"font-L\">　　央视网微信公号去年5月曾刊文介绍，非升即走，一般而言，是针对青年教师的“讲师—副教授”阶段，采取预聘制，即达不到考核要求就不再续聘，以防止他们一进高校就躺平，“倒逼”广大“青椒”尽快出成果。</p> \n<p cms-style=\"font-L\">　　央视网微信公号文章指出，不过，一些高校的“非升即走”逐渐“变异”。有的让副教授也加入“非升即走”；有的“广进广出”，堪称“不升只走”；有的“非升即转”，做不成副教授，就去做行政、后勤、保安。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4424, NULL, '巴西一炸药厂发生爆炸 8人失踪', 0, 4, 29, '2025-08-13 00:30:21', '2025-08-12 22:41:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-12/doc-infktwtw4002053.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　当地时间12日6时左右，巴西巴拉纳州库里奇巴市一座生产炸药的工厂发生爆炸，造成数人失踪。<font cms-style=\"font-L strong-Bold\">截至目前，官方尚未公布本次爆炸造成的死亡人数</font>。不过据当地媒体透露，目前已经确认有8人失踪。</p> \n<p cms-style=\"font-L\">　　据悉，该工厂实行24小时工作制，爆炸发生时，厂内有8名工作人员失踪。爆炸还导致厂外3人受轻伤。目前，救援人员正在全力搜寻失踪人员，并对事故原因展开调查。（总台记者 单既明）</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4425, NULL, '美国白宫：美国总统特朗普与俄罗斯总统普京将举行会晤', 0, 4, 207, '2025-08-13 02:30:13', '2025-08-13 01:21:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkuazp4741510.shtml', '央视', '<p>　　当地时间12日，美国白宫表示，美国总统特朗普与俄罗斯总统普京将于15日在<strong>美国阿拉斯加州的安克雷奇</strong>举行会晤。（央视记者 许骁）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4426, NULL, '哈马斯代表团抵达开罗进行停火磋商', 0, 4, 60, '2025-08-13 02:30:21', '2025-08-13 00:52:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/200/w600h400/20250813/1d08-31cc806e72356dbd2a3ac61c32768c90.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuazr8501272.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/200/w600h400/20250813/1d08-31cc806e72356dbd2a3ac61c32768c90.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△加沙地带（资料图）\">\n <span class=\"img_descr\">△加沙地带（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，由哈马斯高级官员哈利勒·哈亚率领的代表团已抵达埃及开罗，并将与埃及调解员就加沙停火框架进行会谈。</p> \n<p cms-style=\"font-L\">　　埃及外交部长表示，埃及正与卡塔尔和美国协调，寻求在以色列和巴勒斯坦武装组织之间达成一项“全面协议”，从而停止战争。</p> \n<p cms-style=\"font-L\">　　同日，以色列总理内塔尼亚胡表示，<font cms-style=\"font-L strong-Bold\">与哈马斯达成部分停火及人质释放协议的可能性“已经不存在”</font>，他引用了美国总统特朗普此前一天的评论称，哈马斯尚未准备好达成协议。（总台记者 李享）</p> \n<p></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/200/w600h400/20250813/1d08-31cc806e72356dbd2a3ac61c32768c90.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4427, NULL, '俄美外长通电话 讨论两国元首会晤筹备事宜', 0, 4, 207, '2025-08-13 02:30:29', '2025-08-13 00:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/380/w1200h780/20250813/8085-063f2c2c05533908d3f4fd4cdb78e447.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuazu3893756.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/380/w1200h780/20250813/8085-063f2c2c05533908d3f4fd4cdb78e447.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，俄罗斯外交部通报称，俄外长拉夫罗夫与美国国务卿鲁比奥通电话。双方讨论了俄美总统15日在阿拉斯加会晤的筹备工作相关事宜。<font cms-style=\"font-L strong-Bold\">双方一致认为领导人会晤将顺利举行</font>。（总台记者 王德禄）</p> \n<p></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/380/w1200h780/20250813/8085-063f2c2c05533908d3f4fd4cdb78e447.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4428, NULL, '加拿大野火肆虐 过火面积超7.3万平方公里', 0, 4, 36, '2025-08-13 02:30:34', '2025-08-13 00:28:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/367/w1180h787/20250813/20e4-c0f06e8756c4547bdbf0832f6ac5c469.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuazn7656203.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/367/w1180h787/20250813/20e4-c0f06e8756c4547bdbf0832f6ac5c469.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　根据加拿大跨部门森林火灾中心（CIFFC）和加拿大自然资源部的最新数据，截至目前，<font cms-style=\"font-L strong-Bold\">加拿大2025年全国野火过火面积已超过7.3万平方公里，是过去十年同期平均水平的两倍多</font>。</p> \n<p cms-style=\"font-L\">　　马尼托巴省和萨斯喀彻温省的过火面积占全国过火总面积的一半以上，不列颠哥伦比亚省、艾伯塔省和安大略省的过火面积也远高于各自近25年的年平均值。多个省份已宣布不同范围的紧急状态和禁火令。</p> \n<p cms-style=\"font-L\">　　加拿大野火季通常从每年5月持续至9月。尽管今年的野火季尚未结束，<font cms-style=\"font-L strong-Bold\">火灾形势已是加拿大有记录以来第二严重的年份。</font></p> \n<p cms-style=\"font-L\">　　根据加拿大联邦数据库发布的数据，过去三个野火季均位列有记录以来最严重的十个野火季之列，其中2023年的毁灭性野火位居榜首。（总台记者 张森）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/367/w1180h787/20250813/20e4-c0f06e8756c4547bdbf0832f6ac5c469.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4429, NULL, '普京与金正恩通电话 讨论俄美元首会晤等议题', 0, 4, 147, '2025-08-13 03:30:15', '2025-08-13 01:03:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/c828-7ce89b0ea8a94d0a819c20786f0e9105.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuiis3770914.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/c828-7ce89b0ea8a94d0a819c20786f0e9105.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\" △普京（资料图）\">\n <span class=\"img_descr\"> △普京（资料图）</span>\n</div> \n<p>　　当地时间8月12日，克里姆林宫发布消息称，当天俄罗斯总统普京与朝鲜劳动党总书记、国务委员长金正恩通电话。</p> \n<p>　　普京对朝鲜即将于8月15日庆祝摆脱日本殖民统治80周年表示热烈祝贺。</p> \n<p>　　双方重申致力于根据2024年6月19日在平壤签署的《俄朝全面战略伙伴关系条约》，进一步发展各领域友好睦邻合作关系。</p> \n<p>　　普京高度赞赏朝方在俄收复库尔斯克州过程中提供的支持。</p> \n<p>　　普京还就即将与美国总统特朗普在阿拉斯加举行会谈与金正恩分享了信息。双方商定将进一步加强个人接触。（总台记者 王新俊）</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/c828-7ce89b0ea8a94d0a819c20786f0e9105.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4430, NULL, '白宫：美俄元首会晤将在阿拉斯加州安克雷奇举行', 0, 4, 207, '2025-08-13 04:30:14', '2025-08-13 01:21:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkuazp4741510.shtml', '央视', '<p>　　当地时间12日，美国白宫表示，美国总统特朗普与俄罗斯总统普京将于15日在<strong>美国阿拉斯加州的安克雷奇</strong>举行会晤。（央视记者 许骁）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4431, NULL, '美国国债总额首次超过37万亿美元', 0, 4, 207, '2025-08-13 06:30:11', '2025-08-13 05:33:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/106/w1024h682/20250813/e8b8-b7e0981b09aee8dc1c8ae2df812c8ea9.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuprm8259200.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，由于美国联邦政府继续以创纪录的速度积累债务，美国国债总额首次超过37万亿美元。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/106/w1024h682/20250813/e8b8-b7e0981b09aee8dc1c8ae2df812c8ea9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　美国财政部发布的最新数据显示，截至当日下午，美国国债总额已达到37004817625842美元。</p> \n<p cms-style=\"font-L\">　　美国联邦预算问责委员会主席马娅·麦吉尼亚斯对此表示，美国财政状况严重失衡，但国会却不断让情况恶化。（总台记者 赵淼）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/106/w1024h682/20250813/e8b8-b7e0981b09aee8dc1c8ae2df812c8ea9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4432, NULL, '伊朗：若条件合适可直接与美国进行核谈判', 0, 4, 91, '2025-08-13 06:30:42', '2025-08-13 02:43:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/aa4e-be1a4e975713be294c452a9c7aca36ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuprq3655184.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/aa4e-be1a4e975713be294c452a9c7aca36ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据伊朗伊斯兰共和国通讯社12日报道，伊朗第一副总统阿雷夫当天在首都德黑兰表示，如果条件合适，伊朗可以直接与美国进行核谈判，但美方要求伊朗完全放弃铀浓缩活动是个“大笑话”。</p> \n<p cms-style=\"font-L\">　　阿雷夫在一场同媒体记者见面的活动中说，伊朗已经向美方表示，愿意建立互信，准备在“平衡的条件下”进行谈判。然而，美方似乎在“假装睡觉”。</p> \n<p cms-style=\"font-L\">　　在阿曼斡旋下，美国和伊朗自今年4月以来举行五轮由斡旋方居中传话的间接谈判，双方在若干核心议题上分歧巨大。第六轮谈判原定于6月15日举行，因以色列突袭伊朗而取消。以伊冲突的12天内，美国一度“下场”轰炸伊朗核设施，伊朗出于报复向美军驻卡塔尔的乌代德空军基地发动导弹袭击。</p> \n<p cms-style=\"font-L\">　　2015年，伊朗与美国、英国、法国、俄罗斯、中国和德国达成伊核全面协议。2018年，美国单方面退出该协议，随后恢复并不断升级对伊单边制裁。</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/aa4e-be1a4e975713be294c452a9c7aca36ce.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4433, NULL, '欧尔班评美俄会谈不带欧洲：如果不在谈判桌上 那就在菜单上', 0, 4, 87, '2025-08-13 06:30:49', '2025-08-13 02:42:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/143/w550h393/20250813/6bfc-b5fba3ad15683e534a9804854726cc65.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuprq3655212.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/143/w550h393/20250813/6bfc-b5fba3ad15683e534a9804854726cc65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　匈牙利总理欧尔班当地时间12日在接受媒体采访时表示，他之所以否决欧洲理事会当日发布的一份关于乌克兰问题的声明，是因为该声明含有明确支持乌克兰加入欧盟的表态，而匈牙利对此已做出否决，因此不会签署任何与此相关的声明。</p> \n<p cms-style=\"font-L\">　　当天早些时候，欧盟26国领导人发表关于乌克兰局势的声明，强调外交解决方案必须维护乌克兰和欧洲重大安全利益。匈牙利未参与该声明。</p> \n<p cms-style=\"font-L\">　　欧尔班表示，政治权威性至关重要，因此，当美俄谈判时，尽管欧洲没有被邀请，但也不能着急“打电话”“大喊大叫”，以此显示自己的重要性，这样只会让自己显得可悲。欧洲是一个拥有四亿人口的庞大经济体，值得尊重，有能力取得成功，而不是表现得“软弱可怜”。</p> \n<p cms-style=\"font-L\">　　谈及俄乌冲突时，欧尔班表示，<font cms-style=\"font-L strong-Bold\">俄乌冲突初期，匈牙利曾提议欧洲应独立于美国与俄罗斯谈判。而现在，美俄将就欧洲的未来进行谈判，欧洲却没有参与，这证明了“如果你不在谈判桌上，那么就在菜单上”。</font></p> \n<p cms-style=\"font-L\">　　美俄领导人定于15日在美国阿拉斯加州会晤，讨论乌克兰危机，暂无欧洲领导人受邀参与会晤。（总台记者 卜卫军）<span class=\"img_descr\"></span></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/143/w550h393/20250813/6bfc-b5fba3ad15683e534a9804854726cc65.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4434, NULL, '俄称乌策划挑衅行动 企图破坏俄美元首会谈', 0, 4, 164, '2025-08-13 06:30:56', '2025-08-13 02:41:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/126/w1024h702/20250813/c5d7-40eebd7acd43505e1ca115b68c75aa18.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuiik7535545.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/126/w1024h702/20250813/c5d7-40eebd7acd43505e1ca115b68c75aa18.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△俄罗斯国防部（资料图）\">\n <span class=\"img_descr\">△俄罗斯国防部（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，俄罗斯国防部通报称，俄方从若干渠道获得的信息显示，<font cms-style=\"font-L strong-Bold\">乌克兰当局正在策划挑衅行动，以破坏将于15日举行的俄美总统会晤</font>。</p> \n<p cms-style=\"font-L\">　　通报表示，11日乌国家安全局将一批外国媒体记者运送到哈尔科夫州丘古耶夫市（乌方称丘胡伊夫市），准备报道当地居民“在靠近前线地带的生活”。乌方计划利用无人机和导弹攻击当地人口稠密的居民区或者医院，进而引发大量伤亡，再由被运送来的外国记者报道，并将一切责任推给俄罗斯武装力量。乌方此举的意图是为俄美领导人会晤制造负面舆论并破坏俄美在调解乌克兰问题上的协作。此外，在其他乌克兰控制地区也可能发生此类挑衅事件。</p> \n<p cms-style=\"font-L\">　　乌方对此暂无回应。（总台记者 王德禄 王新俊）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/126/w1024h702/20250813/c5d7-40eebd7acd43505e1ca115b68c75aa18.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4435, NULL, '“如同在雷区工作” 加沙记者在危险中报道真相', 0, 4, 95, '2025-08-13 06:31:04', '2025-08-13 02:21:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/d4ff-6df965ddb285495be5e4aded7d443811.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuiip8381465.shtml', '央视', '<p cms-style=\"font-L\">　　据半岛电视台报道，以军10日晚空袭巴勒斯坦加沙地带北部加沙城希法医院附近的一个帐篷，造成包括半岛电视台5名人员在内的共7人死亡。遇害人员当中，就包括半岛电视台在加沙地带北部的知名记者——阿纳斯·谢里夫。11日，半岛电视台员工聚集在多哈总部，为在以军袭击中丧生的五名记者举行追悼仪式。</p> \n<p cms-style=\"font-L\">　　当天，数十名半岛电视台工作人员聚集在演播室内悼念在以军袭击中死亡的五名记者。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/d4ff-6df965ddb285495be5e4aded7d443811.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">半岛电视台加沙办公室负责人 瓦埃勒</font>：每当新闻界失去一位同仁，失去这个专业群体中的一员时，我们感到整个新闻事业仿佛在烈火中燃烧并逐渐瓦解。</p> \n<p cms-style=\"font-L strong-Bold\">　　联合国官员对以方杀害记者深感愤怒</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/6c3f-a436f67f67d4d8462135e4cf7283bfcd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　12日，以军发言人纳达夫·绍沙尼发布消息称，以色列获得的最新情报表明，在袭击中身亡的阿纳斯·谢里夫是“一名活跃的哈马斯武装派别成员”，并“同时从哈马斯和半岛电视台领取薪水”。该发言人称，此前以军曾公布文件证明谢里夫是一名活跃的哈马斯成员，但媒体忽略了以方提供的信息。</p> \n<p cms-style=\"font-L\">　　半岛电视台主持人称，以军的指控毫无根据。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/ee9c-27ea809984c72d19ca9d3b78b058d899.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">半岛电视台资深主持人 塔梅尔</font>：这些指控是捏造的，毫无根据，而且这并非首次。两年里，阿纳斯·谢里夫在加沙四处奔波，为半岛电视台报道加沙地带各地的新闻。</p> \n<p cms-style=\"font-L\">　　联合国特别报告员艾琳·汗在接受半岛电视台采访时表示，以色列军方在没有任何实质性证据的情况下提出指控，以此作为杀害记者的“许可证”，她对此深感愤怒。</p> \n<p cms-style=\"font-L strong-Bold\">　　加沙记者在危险中报道真相</p> \n<p cms-style=\"font-L\">　　半岛电视台加沙办公室负责人瓦埃勒的妻子和孩子在以色列的袭击中丧生，他在接受采访时讲述了在加沙地带从事新闻报道的经历。</p> \n<p cms-style=\"font-L\">　　瓦埃勒表示，在加沙地带从事新闻报道工作，就如同在雷区工作一样。记者们没有任何安全保障，时刻处于恐惧之中。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">半岛电视台加沙办公室负责人 瓦埃勒</font>：简单概括一下，在加沙地带做记者就像在雷区工作一样。巴勒斯坦记者们在街上工作，他们住在街上，没有家、没有办公室、没有后勤补给、没有安全保障。有机会的话，他们就躲进帐篷里。加沙地带的上空都是以军的无人机。以军的无人机离他们工作的帐篷特别近，记者们时刻都在担心成为攻击目标。</p> \n<p cms-style=\"font-L\">　　瓦埃勒表示，在加沙的记者们面临袭击、谋杀、饥饿、干渴、流离失所……记者们遭袭后，他们甚至无法根据遗体辨认出究竟是哪位同事。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">半岛电视台加沙办公室负责人 瓦埃勒</font>：记者们忍着饥饿工作，他们很饿，找不到水，记者们经历的痛苦和加沙地带其他人一样。我们甚至无法辨认死去同事的遗体。因为他们的体重只有原来的一半，我们认不出来了。</p> \n<p cms-style=\"font-L\">　　在采访的最后，瓦埃勒表示，作为一名曾在加沙地带工作的记者，自己最痛心的是不断报道加沙地带发生的悲剧，而悲剧却仍在不断发生。</p> \n<p cms-style=\"font-L strong-Bold\">　　伊斯兰合作组织谴责以空袭致多名记者遇害</p> \n<p cms-style=\"font-L\">　　12日，伊斯兰合作组织发表声明，强烈谴责以军在加沙地带空袭致多名记者遇害事件，称此次袭击公然违反国际法，是对新闻自由的严重侵犯。伊斯兰合作组织表示，以色列应对此次犯罪负全部责任，呼吁开展国际调查，追究肇事者的责任。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/d4ff-6df965ddb285495be5e4aded7d443811.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/6c3f-a436f67f67d4d8462135e4cf7283bfcd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/509/w1920h989/20250813/ee9c-27ea809984c72d19ca9d3b78b058d899.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4436, NULL, '“特普会”细节公布 泽连斯基：不接受没有乌方参与的决定', 0, 4, 207, '2025-08-13 07:30:17', '2025-08-13 07:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/108/w550h358/20250813/bc0f-726718ddab8c7b07668f28ce18e3a66f.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkutxf4380005.shtml', '央视新闻客户端', '<p cms-style=\"font-L subpect-abstract\">　　当地时间12日，美国白宫公布“特普会”更多细节，美国总统特朗普与俄罗斯总统普京将于15日在美国阿拉斯加州最大城市安克雷奇举行会晤，会晤将以一对一形式举行。白宫还称特朗普未来或有访问俄罗斯的计划。</p> \n<p cms-style=\"font-L strong-Bold\">　　俄美一致认为领导人会晤将顺利举行</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/108/w550h358/20250813/bc0f-726718ddab8c7b07668f28ce18e3a66f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　12日，俄罗斯外交部通报称，俄外长拉夫罗夫与美国国务卿鲁比奥通电话。双方讨论了俄美元首会晤的筹备工作相关事宜。<font cms-style=\"font-L strong-Bold\">双方一致认为领导人会晤将顺利举行。</font></p> \n<p cms-style=\"font-L\">　　同日，俄罗斯国防部通报称，俄方从若干渠道获得的信息显示，<font cms-style=\"font-L strong-Bold\">乌克兰当局正在策划挑衅行动</font>，以破坏将于15日举行的俄美总统会晤。</p> \n<p cms-style=\"font-L\">　　通报表示，11日乌国家安全局将一批外国媒体记者运送到哈尔科夫州丘古耶夫市（乌方称丘胡伊夫市），准备报道当地居民“在靠近前线地带的生活”。乌方计划利用无人机和导弹攻击当地人口稠密的居民区或者医院，进而引发大量伤亡，再由被运送来的外国记者报道，并将一切责任推给俄罗斯武装力量。乌方此举的意图是为俄美领导人会晤制造负面舆论并破坏俄美在调解乌克兰问题上的协作。此外，在其他乌克兰控制地区也可能发生此类挑衅事件。</p> \n<p cms-style=\"font-L\">　　针对俄方上述说法，乌方暂无回应。</p> \n<p cms-style=\"font-L strong-Bold\">　　泽连斯基：任何没有乌克兰参与的涉乌决定都不可接受</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/3c47-0ac476ede1ce141630733a1934f216f3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　12日，乌克兰总统泽连斯基表示，俄美峰会在美国领土举行是普京个人的胜利，这次会谈的地点意味着普京正在摆脱孤立状态。</p> \n<p cms-style=\"font-L\">　　泽连斯基说，尽管此类领导人层面的会谈意义重大，但任何涉及乌克兰的决定，若没有乌克兰的参与，都是不可接受的。特朗普与普京的对话，虽然可能对美俄双边关系至关重要，但在没有乌克兰参与的情况下，他们无权就乌克兰问题做出任何决定。</p> \n<p cms-style=\"font-L\">　　此外，泽连斯基还提到，未来各方将举行领导人级别的会晤，不过具体日期目前尚未确定。</p> \n<p cms-style=\"font-L strong-Bold\">　　乌方强调不会在领土问题上“让步”</p> \n<p cms-style=\"font-L\">　　特朗普此前表示俄乌停火方案将涉及“领土交换”，并于11日再次称，冲突双方都需要放弃一部分土地。</p> \n<p cms-style=\"font-L\">　　△瑟比加</p> \n<p cms-style=\"font-L\">　　就相关领土问题，<font cms-style=\"font-L strong-Bold\">乌方12日发声，明确强调不会在领土问题上“让步”</font>。乌克兰外交部长瑟比加表示，乌克兰绝不应向俄罗斯作出任何 “让步”。乌克兰最高拉达（议会）主席鲁斯兰・斯特凡丘克说，乌克兰的领土完整绝非谈判的主题，在乌克兰领土议题上，绝不容许“讨价还价”。乌克兰坚决不会同意与俄罗斯进行 “交换” 或作出让步，更不会拿自身的土地和主权进行交易。</p> \n<p cms-style=\"font-L\">　　但在此前，曾有英媒发布消息称泽连斯基在领土问题上立场有所软化。英国《每日电讯报》11日报道，乌克兰可能同意停止战斗，并同意俄罗斯获得冲突期间控制的地区。报道称，乌克兰总统泽连斯基告诉欧洲领导人，他们必须拒绝美国总统特朗普提出的任何要求乌克兰放弃更多领土的方案，但俄罗斯可以保留部分已经控制的领土。《每日电讯报》称，这意味着当前冲突前线的战火有望被冻结，并让俄罗斯实际控制在卢甘斯克、顿涅茨克、扎波罗热、赫尔松以及克里米亚已经控制的区域。</p> \n<p cms-style=\"font-L\">　　多名俄政府人士近日则对媒体透露，目前<font cms-style=\"font-L strong-Bold\">俄方在领土问题上的主张坚定不移</font>。另据《华尔街日报》报道，俄方通过美方特使递交的方案内容包括：乌克兰需从整个顿巴斯地区撤军，俄罗斯将控制顿涅茨克、卢甘斯克，并继续控制克里米亚；俄罗斯将沿当前战线停止在赫尔松和扎波罗热地区的进攻行动。</p> \n<p cms-style=\"font-L strong-Bold\">　　美国、欧盟、乌克兰今日举行线上会议</p> \n<p cms-style=\"font-L\">　　就本次俄美元首会晤，欧洲方面领导人暂未受邀参加。当地时间12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，两名美国官员证实，美国总统特朗普和副总统万斯将于13日与乌克兰总统泽连斯基和欧洲盟友举行线上会议。</p> \n<p cms-style=\"font-L\">　　欧盟委员会发言人当天稍早前表示，欧盟委员会主席冯德莱恩将参加13日由德国召集的多方视频会议，讨论乌克兰问题。发言人称，乌克兰总统泽连斯基也将参加当天的会议。该发言人表示，欧盟将继续在各个方面积极支持乌克兰，并称欧盟正在制定第19轮对俄制裁方案。</p> \n<p cms-style=\"font-L\">　　近几天，围绕此次俄美领导人会晤，欧洲方面展开了密集外交磋商。欧洲理事会12日发布了一份来自26位欧盟成员国领导人的声明，表示俄乌冲突外交解决方案必须保护乌克兰和欧洲的安全利益，只有在停火或减少敌对行动的背景下，才能进行有意义的谈判。该声明得到了除匈牙利外的所有欧盟成员国领导人的认可。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">监制丨郑弘</font><font cms-style=\"font-L\">制片人丨赵新宇</font><font cms-style=\"font-L\">主编丨崔翀</font><font cms-style=\"font-L\">编辑丨刘微</font></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1754732525\" target=\"_blank\">特朗普和普京将会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/108/w550h358/20250813/bc0f-726718ddab8c7b07668f28ce18e3a66f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/3c47-0ac476ede1ce141630733a1934f216f3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4437, NULL, '“立邦”创始人吴清亮逝世！从打工仔白手起家成“亚洲漆王”、新加坡首富，以华人身份自豪', 0, 4, 175, '2025-08-13 07:30:28', '2025-08-13 06:30:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/5b1e-fb7f994f1fece90ea98d14d64f4c1b5a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkutxe7290454.shtml', '每日经济新闻', '<p cms-style=\"font-L\">　　每经编辑｜段炼&nbsp;&nbsp;&nbsp;&nbsp;</p> \n<p cms-style=\"font-L\">　　8月12日，吴德南控股集团创办人、“立邦”品牌创始人吴清亮去世，享年98岁。 吴氏家族发布声明称，吴清亮在新加坡家人陪伴下安详离世。</p> \n<p cms-style=\"font-L\">　　2025年5月，<font cms-style=\"font-L\">吴清亮以净值130亿美元（约934亿元人民币）的个人财富，登上《福布斯》全球富豪榜第182位，新加坡第一</font><font cms-style=\"font-L\">。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/5b1e-fb7f994f1fece90ea98d14d64f4c1b5a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　从一贫如洗打工仔到“亚洲漆王”</p> \n<p cms-style=\"font-L\">　　“在中国投资是最明智的决策之一”</p> \n<p cms-style=\"font-L\">　　吴清亮1927年出生于新加坡，祖籍广东省潮州市潮安区浮洋镇大吴村。出身贫苦的他白手起家，从一贫如洗的打工仔到富甲一方的“亚洲漆王”，成为一代商界传奇。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/31/w550h281/20250813/69d8-a997ba6d28b98fba765f1c5c39784fba.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　1962年，吴清亮的公司被日本著名老字号油漆制造商“日本漆”（ Nippon Paint）相中，决定合资经营油漆生意。日本漆是日本最大的涂料供应商，创办于1881年，也是日本的第一家涂料企业。</p> \n<p cms-style=\"font-L\">　　双方合资创办了立时集团，其中，吴清亮掌控的私人公司吴德南集团持股60%，日本漆公司占股40%。吴清亮负责管理合资公司在亚洲区的所有业务活动，通过技术引进和本地化运营，实现了行业的快速扩张，奠定了他在亚洲涂料市场的主导地位。</p> \n<p cms-style=\"font-L\">　　1990年，中国跟新加坡建立邦交。这让祖籍潮州的吴清亮感到无比的振奋。据说，<font cms-style=\"font-L\">当时吴清亮看到 “建立邦交”四个字便为自己的油漆品牌起名“立邦”</font><font cms-style=\"font-L\">。这里的“立”是指“立时”，“邦”是为了纪念中国与新加坡建立邦交关系。</font></p> \n<p cms-style=\"font-L\">　　同年，立时集团开始筹划进入中国。1992年，立时集团在中国注册成立第一家公司，成为较早进入中国的跨国企业之一。</p> \n<p cms-style=\"font-L\">　　彼时国内还没有涂料的概念，吴清亮曾回忆说自己回到潮州老家，发现很多地方都是用白水泥、白石灰来涂墙。这也让初到中国的立邦发展并不顺利，“前期投资的规模很大，亏得很惨”。但吴氏仍然坚持了自己对中国市场的判断：“中国市场太大了，我看准了中国绝对不会让我失望。”</p> \n<p cms-style=\"font-L\">　　经过多年坚持，如今立邦品牌逐渐深入人心，成为中国涂料行业的知名品牌，吴清亮曾表示在中国投资是立时集团最明智的决策之一<font cms-style=\"font-L\">。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　旗下公司已是全球巨头</p> \n<p cms-style=\"font-L\">　　官网资料显示，目前立时集团已成为全球第四的涂料制造与服务商。</p> \n<p cms-style=\"font-L\">　　根据立邦中国官网，目前立邦中国区总部设立于上海，在中国投资建设超过70家生产基地，员工近1<font cms-style=\"font-L\">.</font>1万人。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/news/crawl/44/w550h294/20250813/f594-f1189579682a799d159444ee87ddcb9e.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　2020年8月，上市公司日本涂料控股株式会社发布公告称，<font cms-style=\"font-L\">公司与新加坡吴德南集团达成总价值1<font cms-style=\"font-L\">.</font>29万亿日元的交易协议，完成交易后将成为该集团的子公司</font><font cms-style=\"font-L\">。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">2025年8月8日，日本立邦涂料控股株式会社（Nippon Paint Holdings，“立邦涂料”）公布2025年度上半年经营业绩报告。</font><font cms-style=\"font-L strong-Bold\">今年上半年，得益于完成收购AOC的业绩贡献，销售额同比增长4.3%至8524.28亿日元（约合57.79亿美元或人民币420亿元）；</font>归母净利润为874.54亿日元，同比增长34.4%。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">8月12日，吴清亮逝世消息传出当天，<font cms-style=\"font-L strong-Bold\">立邦涂料股价突然大跌超10%</font><font cms-style=\"font-L strong-Bold\">，总市值2.79万亿日元（约合人民币1350亿元）。</font></font></p> \n<div class=\"img_wrapper\">\n <img id=\"5\" src=\"https://k.sinaimg.cn/n/news/crawl/398/w550h648/20250813/09a5-ab92afa40245a6104af949a06bf51caf.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">此前，高盛预测，立邦涂料在2024至2027财年期间将实现20%的每股收益复合年增长率。尽管具有这种增长潜力，但其股票目前以2026财年13倍市盈率交易，低于全球专注于装饰涂料的涂料公司约20倍的10年平均水平。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">分析师强调，立邦涂料的核心装饰涂料业务基本不受特朗普“对等关税”的影响，并受益于石化原材料价格的稳定。该公司的\"资产整合者\"商业模式也被视为关键竞争优势。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"6\" src=\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　为老家捐建基础设施价值上亿元</p> \n<p cms-style=\"font-L\">　　教育子女“根在中国”</p> \n<p cms-style=\"font-L\">　　改革开放以来，吴清亮遵循母亲遗训“毋忘家国之情，发达之日，对大吴应有援乡之建”。</p> \n<p cms-style=\"font-L\">　　他不忘初心、情系桑梓，往返家乡广东大吴村数十次<font cms-style=\"font-L\">，先后捐建了桥梁、道路、医院、电厂、水厂等基础设施，累计价值超过1亿元人民币</font><font cms-style=\"font-L\">。</font></p> \n<p cms-style=\"font-L\">　　2024年11月26日，由吴清亮捐资改建的大吴会客厅正式落成并投入使用。在落成仪式上，吴清亮先生的女儿吴婕人介绍：“虽然我父亲是我祖母怀着他到新加坡后才出世的，但在父亲心里大吴村始终是他的家乡。父亲一直很为自己的华人身份自豪，他总是说，我们吴家人的根在中国，在潮州，在大吴村；什么都可以忘，但一定不能忘记我们的根在这里。”</p> \n<div class=\"img_wrapper\">\n <img id=\"7\" src=\"https://k.sinaimg.cn/n/news/crawl/60/w550h310/20250813/1c00-b8b77030e889017ab1b736cd83ee0f53.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据了解，2024年6月，吴清亮曾在家人陪同下，最后一次回家乡大吴村探亲走访。</p> \n<div class=\"img_wrapper\">\n <img id=\"8\" src=\"https://k.sinaimg.cn/n/news/crawl/114/w525h389/20250813/5d83-1e5d629c659cc015598eae3ad3d02be3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　（免责声明：<font cms-style=\"font-L strong-Bold\">文章内容和数据仅供参考，不构成投资建议。投资者据此操作，风险自担。</font>）</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">编辑<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">|<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">|</font></font></font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">|</font></font></font></font>段炼 杜波</font></font></font></font></font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">校对|<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">赵庆</font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">封面图片：视觉中国（资料图）</font></p> \n<div class=\"img_wrapper\">\n <img id=\"9\" src=\"//n.sinaimg.cn/news/crawl/560/w550h10/20250813/ea50-7c6c4a341b65c40325da340bb1c4f53e.webp\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">每日经济新闻综合自第一财经、南方都市报、界面新闻、公开资料等</font></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/5b1e-fb7f994f1fece90ea98d14d64f4c1b5a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/31/w550h281/20250813/69d8-a997ba6d28b98fba765f1c5c39784fba.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/44/w550h294/20250813/f594-f1189579682a799d159444ee87ddcb9e.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/398/w550h648/20250813/09a5-ab92afa40245a6104af949a06bf51caf.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/608/w550h58/20250813/4ff5-57a3e2296123bb53547ccc291f3ff981.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/60/w550h310/20250813/1c00-b8b77030e889017ab1b736cd83ee0f53.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/114/w525h389/20250813/5d83-1e5d629c659cc015598eae3ad3d02be3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://n.sinaimg.cn/news/crawl/560/w550h10/20250813/ea50-7c6c4a341b65c40325da340bb1c4f53e.webp\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4438, NULL, '特朗普将与泽连斯基和欧洲盟友举行线上会议', 0, 4, 204, '2025-08-13 07:30:46', '2025-08-13 05:42:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/208b-15811853b93b8184442e1e478d5807e1.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuprq3658446.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/208b-15811853b93b8184442e1e478d5807e1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间12日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，两名美国官员证实，美国总统特朗普和副总统万斯将于13日与乌克兰总统泽连斯基和欧洲盟友举行线上会议。</p> \n<p cms-style=\"font-L\">　　欧盟委员会发言人当天稍早前表示，欧盟委员会主席冯德莱恩将参加13日由德国召集的多方视频会议，讨论乌克兰问题。发言人称，乌克兰总统泽连斯基也将参加当天的会议。（总台记者 赵淼 王德禄）<span class=\"img_descr\"></span></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1754732525\" target=\"_blank\">特朗普和普京将会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/208b-15811853b93b8184442e1e478d5807e1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4439, NULL, '江苏20项举措促进数据要素赋能新型工业化', 0, 1, 10, '2025-08-13 07:30:51', '2025-08-13 07:13:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxn3535247.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　省知识产权局、省工信厅近日联合印发《江苏省工业和信息化领域数据知识产权试点实施方案》，围绕“完善登记体系、打造服务生态、提升运用质效”三大试点任务，部署20项创新举措。方案提出，力争到2026年6月，数据知识产权登记保护运用体系基本建成，许可交易、证券化、作价入股、数据资产入表等运用场景全面落地。</p>\n<p cms-style=\"font-L\">　　此次试点旨在全面深化数据知识产权试点改革，以高标准的数据权益保护，激励高质量数据供给，激活高效率、高效益数据流通与应用，促进数据要素全方位赋能新型工业化。</p>\n<p cms-style=\"font-L\">　　方案明确，进一步深化数据知识产权审慎审查，研究出台鼓励登记运用的政策措施，让更多企业“想登记、敢登记、会登记”；培育一批数据知识产权专业服务机构，推进司法、仲裁、调解等多元保护体系建设，为数据知识产权挖掘登记、转化运用、权益保护提供全方位保障；鼓励各地探索数据知识产权许可交易、增信融资、作价入股、数据资产入表等运用场景，推动数据驱动型新兴产业和未来产业加速成长。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4440, NULL, '第一视点丨这里面既有中华优秀传统文化 也有马克思主义', 0, 1, 11, '2025-08-13 08:30:16', '2025-08-13 08:28:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/xl/2025-08-13/doc-infkutxe7314106.shtml', '中国蓝新闻', '<p>　　来源：中国蓝新闻</p> \n<p>　　“枫桥经验”在习近平总书记心中，始终有着沉甸甸的分量。在浙江工作期间，他提出要创新发展“枫桥经验”。党的十八大以来，习近平总书记多次作出重要指示批示，为坚持和发展新时代“枫桥经验”指明方向。2023年金秋，他在诸暨枫桥镇考察时指出，人与人都应该团结互助、和谐相处，这里面既有中华优秀传统文化，也有马克思主义。新时代“枫桥经验”植根于中华优秀传统文化，凝聚了中华民族的精神和智慧，实现了马克思主义治理观与中华优秀传统文化治理智慧的有机结合，为续写经济快速发展、社会长期稳定“两大奇迹”新篇章提供强大助力，成为“第二个结合”的典范。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4441, NULL, '年中看进展 |  驻省供销联社纪检监察组：靶向施治 助力企业发展', 0, 1, 13, '2025-08-13 08:30:25', '2025-08-13 08:27:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxi8157503.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　“公司法律顾问违规享受购房补贴，侵占企业利益，暴露出企业在内部管理监督、制度建设等方面存在薄弱环节……” 日前，省纪委监委派驻省供销联社纪检监察组向省供销联社所属集团党委制发纪检监察建议书，直指企业管理漏洞。</p>\n<p cms-style=\"font-L\">　　此前，派驻纪检监察组在监督检查中发现，省供销联社所属一家企业聘用的法律顾问李某，违规以公司职工名义享受购房补贴，利用职业便利侵占企业利益。2021年内部审计已发现该问题，但企业多次与李某协调，问题拖延3年始终未能解决。</p>\n<p cms-style=\"font-L\">　　面对这一遗留问题，派驻纪检监察组迅速行动，督促省供销集团及所在企业切实履行全面从严治党治企主体责任，要求立即中止与李某的合作，全面开展自查自纠，通过健全制度、强化管理堵塞漏洞。仅一个月时间，就帮助企业成功追回购房补贴款 20 余万元。</p>\n<p cms-style=\"font-L\">　　“收到纪检监察建议书后，我们立即对所属23家企业法律业务管理情况进行排查，发现并整改问题6个，解除与李某聘用关系，动态更新法律顾问库，修订完善制度8项。”近日，派驻纪检监察组开展纪检监察建议落实情况“回头看”，省供销集团相关负责人介绍了整改情况。</p>\n<p cms-style=\"font-L\">　　去年以来，派驻纪检监察组聚焦企业改革发展关键环节，将执纪办案作为最有力的监督手段，紧盯 “三重一大” 决策、企业资产处置、基建工程和招投标等领域的任性用权问题，紧盯选人用人、评优选先、对外交往中的特权思想和特权行为，紧盯投资决策、内部管理、制度执行中的肆意妄为问题，加大惩治力度，对企业改革发展中的腐败问题线索优先处置、提级查办，共处置问题线索24 件，立案2件，给予党纪政务处分3人，组织处理 19 人；针对性制发纪检监察建议 3 份。</p>\n<p cms-style=\"font-L\">　　与此同时，派驻纪检监察组整合监督力量，探索构建横向到边、纵向到底的联动监督体系。一方面充分发挥党内监督专责机关作用，联合省供销联社监事会、机关党委、财务、审计、组织人事等部门同向发力、同题共答，全年就重大事项开展定期会商 3 次，推动整改相关问题 9 项。另一方面，针对企业监督力量分散、职能弱化等问题，指导省供销集团纪委设立 3 个监督检查室开展综合监督，由室主任兼任一家较大企业纪委书记，同时监督其他 4-5 户小企业领导班子，进一步提升上级纪委监督的权威性和规范性，让监督更加精准有力。</p>\n<p cms-style=\"font-L\">　　“我们将推动‘查、改、治’贯通发力，结合查办的重点案件，深入排查省供销联社所属企业发展中的痛点堵点，坚持标本兼治、系统治理，常态化开展纪律教育，强化制度建设、堵塞监管漏洞，以有力监督护航供销企业改革发展行稳致远。” 派驻纪检监察组负责同志表示。（供稿 沈玉婷 &nbsp;编辑 张丽敏）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4442, NULL, '广西富川严明纪法要求 规范“关键少数”履职用权', 0, 1, 20, '2025-08-13 08:30:55', '2025-08-13 08:17:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxn3549656.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　“停水问题解决了，现在供水恢复正常，生活也方便了。”日前，广西壮族自治区富川瑶族自治县莲山镇龙山村村民陈大哥对前来回访的该县纪检监察干部说。</p>\n<p cms-style=\"font-L\">　　此前，由于富川县供水公司管护不到位，导致该村管网破损、漏水严重，村民对水费有异议，双方协商未果。县供水公司采取停水措施，给村民生活造成不便。</p>\n<p cms-style=\"font-L\">　　该县纪委监委针对县供水公司日常履职作风不严不实等问题，约谈行业主管部门的主要领导，压实行业监督监管责任，并督促县水利局、县供水公司和属地党委政府等多方联动，现场办公协调解决问题。最终，就水费缴纳和后续管护问题，县供水公司和该村达成一致，恢复了正常供水。</p>\n<p cms-style=\"font-L\">　　今年以来，富川县纪委监委紧盯“关键少数”，围绕全县各级各部门“一把手”抓重点中心工作落地见效和贯彻落实中央八项规定精神等情况，严明纪法要求，抓早抓小、防微杜渐，压紧压实工作责任。</p>\n<p cms-style=\"font-L\">　　同时，该县纪委监委严肃查处“一把手”违纪违法问题，截至目前，已立案查处覆盖县直、乡镇、村三级“一把手”39人。聚焦查处的“一把手”违纪违法典型案件，该县纪委监委坚持“查改治”一体推进，督促案发单位党组织开展以案促改促治。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4443, NULL, '山西应县木塔旁搭舞台每晚DJ音乐不断遭投诉后续：当地文旅局称尊重网络声音，大舞台已被拆除', 0, 1, 4, '2025-08-13 08:31:07', '2025-08-13 08:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/692/w550h942/20250813/9f0e-f73d72804702ef1603a59db5c4df88fa.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxf4394364.shtml', '极目新闻', '<p cms-style=\"font-L\">　　记者任利</p> \n<p cms-style=\"font-L\">　　8月12日，记者从山西应县文化和旅游局（下称应县文旅局）了解到，山西应县木塔旁搭建的“阿东大舞台”已于上周被拆除。据纵览新闻此前刊发的报道，有不少网友质疑，山西应县木塔旁搭建的“阿东大舞台”产生的DJ音乐声不仅扰民，还会对应县木塔的安全性造成影响。</p> \n<p cms-style=\"font-L\">　　据应县文旅局工作人员介绍，针对网友们担心的“阿东大舞台”产生的音乐声会形成共振，对应县木塔安全性造成影响的问题，该局委托第三方公司进行了检测。报告结果显示，数值是在合理的范围内。不过，该局考虑到，近期有网友、游客对应县木塔旁搭建大舞台存在异议，并进行了投诉，决定尊重大家意见，尊重网络声音，对“阿东大舞台”进行了拆除。这名工作人员称，该局感谢网民、游客对应县木塔的关心，大家发出的不同声音，对他们都是一种鞭策，“我们不好的地方我们一定改正”。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/692/w550h942/20250813/9f0e-f73d72804702ef1603a59db5c4df88fa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"搭建在应县木塔景区旁的大舞台。（来源/视频截图）\">\n <span class=\"img_descr\">　　搭建在应县木塔景区旁的大舞台。（来源/视频截图）</span>\n</div> \n<p cms-style=\"font-L\">　　根据纵览新闻此前刊发的报道，7月6日，山西应县开始举办2025年木塔景区暑期消夏文化活动，其中一项活动为才艺大比拼，名为“阿东大舞台”，举办地点位于应县木塔景区旁边。有当地网友不断发文指出，“阿东大舞台”每晚DJ等各种音乐不断，且震耳欲聋，不仅扰民，还让其担心会引发共振现象，对完全木结构的应县木塔造成影响。该网友通过12345投诉后，应县文旅局答复称，“阿东大舞台”演出前已进行相关申报，且舞台搭建在应县木塔保护范围外。该网友对此答复并不认可，认为避重就轻。不少网友对此表示了支持，纷纷@山西文旅和朔州文旅等相关部门。</p> \n<p cms-style=\"font-L\">　　在应县人民政府官方网站“互动交流”板块，也有当地居民投诉，“阿东大舞台”演出到11点多，噪音特别大，严重影响到了自己家庭和周边居民的正常生活。7月30日，应县文旅局工作人员表示，的确接到了相关投诉，会安排相关科室进行回复。</p> \n<p cms-style=\"font-L\">　　公开资料显示，应县木塔(又名佛宫寺释迦塔)，建于公元1056年（辽清宁二年，即北宋至和三年），塔高67.31米，底层直径30.27米，总重量约为7400多吨，是世界上现存最高大、最古老的纯木结构楼阁式建筑。1961年，被国务院公布为全国重点文物保护单位，2016年9月，被吉尼斯世界纪录认证为“世界上最高的木塔”。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/692/w550h942/20250813/9f0e-f73d72804702ef1603a59db5c4df88fa.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4444, NULL, '六盘水：持续深入整治形式主义为基层减负', 0, 2, 253, '2025-08-13 08:32:21', '2025-08-13 07:03:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxn3546603.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L\">　　近日，六盘水市纪委监委会同市基层减负专项工作机制办公室通报4起形式主义相关典型案例。</p>\n<p cms-style=\"font-L\">　　今年以来，六盘水市纪委监委把纠治加重基层负担的形式主义问题列入贯彻落实中央八项规定精神专项监督的重点清单，坚持问题导向，推动重点整治文山会海、督查检查调研扎堆、工作过度留痕、任务层层加码、“指尖上的形式主义”等突出问题。</p>\n<p cms-style=\"font-L\">　　“工作中，我们做实为基层‘减事务、减牌子、减证明’三个‘减法’，做好赋能增效的‘加法’。”市纪委监委有关负责人介绍，持续督促开展精简文件会议、整治“指尖上的形式主义”治理工作，推动开展市级报表台账集中清理整治，完善村级基础数据“一张表”。</p>\n<p cms-style=\"font-L\">　　强化整改整治，市纪委办公室联合市基层减负专项工作机制办公室通报3期10起典型问题，并针对典型案例开展分析研判，督促各责任部门及时制定整改措施，切实推进问题整改。</p>\n<p cms-style=\"font-L\">　　全市各级纪检监察机关结合工作实际，靶向开展监督。六枝特区纪委监委联合特区党委督查室等部门，采取“四不两直”的方式深入部门、村(社区)开展督导检查，了解基层减负落实情况。水城区纪委监委探索采取“基层点题—数据归集—分析研判—精准督办—举一反三”工作举措，倒逼健全“基层点、上级改”做法，引导用好信息化手段，着力搭建基层减负问题线索“随手报”平台，积极回应基层干部群众关切。</p>\n<p cms-style=\"font-L align-right\">　　(六盘水市纪委监委)</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4445, NULL, '8岁自闭症男童大理走失最新进展：身上带有定位器，志愿者呼吁在大理的朋友打开苹果手机蓝牙，尽可能为锁定孩子定位提供帮助', 0, 1, 25, '2025-08-13 08:32:30', '2025-08-12 20:17:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/421/w550h671/20250813/6f09-679e76577f257764a38dcbe60e97fabf.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxi8157954.shtml', '江南都市报', '<p>　　来源：江南都市报</p> \n<p>　　江南都市报全媒体记者赵琼、实习生袁知</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/421/w550h671/20250813/6f09-679e76577f257764a38dcbe60e97fabf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　8月9日，一名8岁自闭症男童在大理苍山走失，截至8月12日17时，搜救仍在继续。记者从当地志愿者获悉，有机构老师分析，孩子爱跑、爱冲下坡，有可能自己跑下山。孩子身上带有Tag定位器，如果孩子一旦路过周围，孩子的最新定位会被激活。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/86/w550h1136/20250813/42fb-a74a4e20b383fd4fdfb3c01e4ead7b00.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>　走失男童8月8日所在定位\n</div> \n<p>　　8月12日，大理苍山救援进入第4天。大理天气大雨暴雨，搜救仍在有序地进行中，志愿者和当地消防救援人员组队搜救。在当地旅居的黎可可因作为一名博主加入搜救志愿者团队，她告诉江南都市报记者，事发地点就在其居住小区对面，现在主要负责整理信息和需求发布至本地群。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/118/w550h368/20250813/9aa8-ccad045e683a978aa11a05a80ae2b79e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>带队老师手绘男童走失地图\n</div> \n<p>　　黎可可称，8月9日上午11时许，走失男童王某凯参加独立户外活动时，在苍山元阳书院附近走丢，当时老师并未报警，在其先自行搜索无果后，13时43分报警，随后警察和蓝天搜索队赶到现场开始搜救，当天，孩子背着橘色的书包、蓝色水杯。据了解，该儿童患有自闭症。</p> \n<p>　　这场救援的背后离不开志愿者的接力。救援的物资多数由志愿者和热心群众接龙购买，包含救援物料、后勤保障及相关应急物资。目前，大理已组织公安、消防救援、森林消防、应急、林草、“苍山卫士”及大理蓝天救援队、大理山地救援队等救援力量，到走失地附近开展搜救。黎可可还透露，走失男童的父母及姥姥、姥爷都在现场。</p> \n<p>　　8月12日16时许，搜救沟通群传来最新消息显示，搜救组与机构老师已确定，孩子身上的Tag定位器在书包并且有电，其定位器有一定防水性能，不会轻易出故障；有机构老师最新分析称孩子爱跑、爱冲下山坡，有很大可能自己跑下山。志愿者还呼吁在大理并持有苹果手机的朋友打开蓝牙，可能会为孩子的位置提供巨大的帮助。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/719/w550h969/20250813/85b0-a409ca6502e9840a4d80dd47f63803fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"搜救群截图，呼吁市民打开苹果手机蓝牙定位\">\n <span class=\"img_descr\">搜救群截图，呼吁市民打开苹果手机蓝牙定位</span>\n</div> \n<p>　　黎可可解释称，苹果手机打开蓝牙近距离可以直接搜到王某凯位置信息，“打开蓝牙或者App近距离会有显示，但正常是10-50米，苍山里植被比较严重，需要在5-10米内。”</p> \n<p>　　此外，有媒体报道，当地相关部门已对这家名为“明日之光”、宣称采用自然疗愈法治疗孩子的涉事夏令营机构展开调查。</p> \n<p>　　8月12日，记者联系涉事夏令营机构，对方回应称，“我们还在忙，然后你们以公安发的为准，或者有什么（问题）你直接咨询公安。”然后匆忙挂掉电话。</p> \n<p>　　记者注意到，在其管理者在介绍关于“明日之光个案定制”课程体系中提到，“我们的课程体系全天共分为三大部分，为十几个孩子配备了二十多名老师，由各专业老师来完成全天课程。”其中，自然户外课，即指大自然环境下的户外运动路线，老师以专业体育老师和退伍军人为主。关于价格方面，其管理者曾透露，“目前学堂的孩子最少一个月要一万二三”。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/news/crawl/527/w550h777/20250813/0dfc-1c976ca3403de5ade64f6acddbca1564.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　来源：江南都市报值班编辑：喻妍</p> \n<p>　　校对：张竹影</p> \n<p>　　值班主任：范俊杰</p> \n<p>　　值班编委：郭宁</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/421/w550h671/20250813/6f09-679e76577f257764a38dcbe60e97fabf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/86/w550h1136/20250813/42fb-a74a4e20b383fd4fdfb3c01e4ead7b00.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/118/w550h368/20250813/9aa8-ccad045e683a978aa11a05a80ae2b79e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/719/w550h969/20250813/85b0-a409ca6502e9840a4d80dd47f63803fb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/527/w550h777/20250813/0dfc-1c976ca3403de5ade64f6acddbca1564.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4446, NULL, '美俄峰会前，泽连斯基明确表态：不会放弃顿巴斯', 0, 4, 204, '2025-08-13 09:30:15', '2025-08-13 09:00:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250813/0905-a3006fc59717501512949a740df610f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuyfk3435584.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 熊超然】随着美俄元首阿拉斯加会谈即将登场，涉及领土的问题成为焦点。此前，英国《每日电讯报》曾于当地时间8月11日披露，乌克兰泽连斯基立场已软化，乌方可能同意停火并在领土问题上让步。</p> \n<p cms-style=\"font-L\">　　据英国广播公司（BBC）当地时间8月12日报道，仅隔一天后，泽连斯基当天明确表示，乌克兰将拒绝任何俄罗斯提出的以停火换取顿巴斯地区的提议，并警告称，该地区可能被用作未来乌军发动袭击的“跳板”。俄罗斯国防部当天也发布声明，指责乌克兰正准备在哈尔科夫地区发动挑衅计划，意图将袭击行动“栽赃”给俄军，并破坏美俄元首会谈和谈判进程。</p> \n<p cms-style=\"font-L\">　　与此同时，俄军正持续开展夏季攻势，乌克兰东部城镇多布罗皮利亚（Dobropillia）附近突然推进，并在短时间内推进了10公里。对此，泽连斯基承认俄军正在“多个地点”推进，但坚称基辅方面将很快摧毁参与袭击的部队。他在淡化俄军推进的同时补充称，莫斯科方面的目标是在俄美元首会晤前营造一个“特定信息空间”，即“俄罗斯正前进推进、步步为营，而乌克兰正节节败退”。</p> \n<p cms-style=\"font-L\">　　路透社也报道称，俄军推进至多布罗皮利亚附近，是俄罗斯总统普京全面控制顿涅茨克地区行动的一部分，也是今年迄今为止规模最大的行动之一，而乌军派遣了预备役部队，称其与俄军进行了“艰苦战斗”。报道认为，乌克兰面临兵力短缺问题，这为俄军近期推进铺平了道路。</p> \n<p cms-style=\"font-L\">　　“此次突破就像是给普京和特朗普谈判时送上的一份礼物。”克里姆林宫前顾问谢尔盖·马尔科夫（Sergei Markov）表示，并暗示这可能会加大对乌克兰的压力，迫使其在任何协议下让出领土。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250813/0905-a3006fc59717501512949a740df610f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"俄军近期的推进方向，以及多布罗皮利亚的位置（红圈处）\">\n <span class=\"img_descr\">俄军近期的推进方向，以及多布罗皮利亚的位置（红圈处）</span>\n <font cms-style=\"font-L\"> 《基辅独立报》</font>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">泽连斯基：拒绝撤出顿巴斯地区</font></p> \n<p cms-style=\"font-L\">　　顿巴斯地区由乌克兰东部的卢甘斯克地区和顿涅茨克地区组成，自2014年以来一直被俄罗斯部分控制。目前，俄罗斯控制着几乎全部的卢甘斯克地区和70%的顿涅茨克地区。当地时间8月12日，泽连斯基在接受记者采访时重申，乌克兰将拒绝任何撤出顿巴斯地区的提议。</p> \n<p cms-style=\"font-L\">　　“如果我们今天从顿巴斯撤军——包括我们的防御工事、我们的阵地以及我们控制的高地，我们显然将为俄罗斯人打开一个桥头堡，让他们准备进攻。”</p> \n<p cms-style=\"font-L\">　　路透社指出，特朗普此前曾谈到俄乌土地交换，但俄罗斯和乌克兰都无意将土地作为和平协议的一部分。欧洲人则担心，对俄罗斯做出重大让步可能会在未来给西方带来安全问题。</p> \n<p cms-style=\"font-L\">　　目前，俄罗斯控制着乌克兰约五分之一的领土，而乌克兰几乎没有控制俄罗斯的任何领土。由于所有争议地区都位于乌克兰境内，泽连斯基及其欧洲盟友担心，在领土问题上，乌克兰将比俄罗斯面临更多的压力。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/d9d9-2bdfcaff12b3906657776c6dbf930da4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。\">\n <span class=\"img_descr\">当地时间8月6日，乌克兰苏梅州，乌克兰总统泽连斯基视察前线士兵。</span>\n <font cms-style=\"font-L\"> 视觉中国</font>\n</div> \n<p cms-style=\"font-L\">　　泽连斯基和大多数欧洲国家外长都表示，如果没有乌克兰的参与，就无法实现持久的和平，而且和平协议必须符合国际法，并维护乌克兰的主权和领土完整。</p> \n<p cms-style=\"font-L\">　　“在没有我们参与的情况下，就我们（乌克兰问题）进行实质性、建设性的谈判是行不通的。这种谈判或许会发生，但在实践中不会被接受。就像我不能对另一个国家发表任何意见，也不能替它做决定一样。”泽连斯基表示。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">此前一天，泽连斯基被曝“立场软化”</font></p> \n<p cms-style=\"font-L\">　　当地时间8月11日，《每日电讯报》曾披露报道称，作为欧洲支持的和平计划的一部分，乌克兰可能同意停止战斗，并同意俄罗斯获得冲突期间所拿下地区的控制权。泽连斯基告诉欧洲领导人，他们必须拒绝美国总统特朗普提出的任何乌克兰放弃更多领土的解决方案，但俄罗斯可以保留部分已占领土地。</p> \n<p cms-style=\"font-L\">　　报道称，泽连斯基的这一谈判立场软化，意味着当前冲突前线的战火将被冻结，并让俄罗斯实际控制其在乌东四地（卢甘斯克、顿涅茨克、扎波罗热、赫尔松）以及克里米亚的占领区。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/136/w550h386/20250813/0905-a3006fc59717501512949a740df610f7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/d9d9-2bdfcaff12b3906657776c6dbf930da4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4447, NULL, '内塔尼亚胡称加沙停火谈判“已成过去时”', 0, 4, 95, '2025-08-13 09:30:23', '2025-08-13 07:39:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/4755-db664b583a56590fa58f2476c3343cc7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkutxe7303026.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/4755-db664b583a56590fa58f2476c3343cc7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　以色列总理内塔尼亚胡12日对媒体表示，以色列与巴勒斯坦伊斯兰抵抗运动（哈马斯）就在加沙地带实现短期停火、部分被扣押人员获释达成协议的可能性“已成过去时”。</p> \n<p cms-style=\"font-L\">　　内塔尼亚胡当天在接受以色列i24新闻台采访时说，与哈马斯达成“部分协议”的可能性已不复存在。他还否认对于其“延长战争”的指责，称内阁支持其缩短作战时间表、在加沙地带取得“决定性胜利”的举措。</p> \n<p cms-style=\"font-L\">　　以色列总理办公室8日宣布，以安全内阁已批准内塔尼亚胡关于“击败哈马斯”的计划，以军准备接管加沙地带北部的加沙城。多个国家和国际组织发声谴责这一决定，敦促以方立即停止“战争计划”。</p> \n<p cms-style=\"font-L\">　　根据加沙地带卫生部门12日发布的数据，自3月18日以军恢复在加沙地带的军事行动以来，已造成至少10078人死亡、42047人受伤。</p> \n<p cms-style=\"font-L\">　　<a href=\"https://news.sina.com.cn/w/2025-08-13/doc-infkuazr8501272.shtml\" target=\"_blank\" data-comos-dataid=\"comos:nfkuazr8501272\">哈马斯代表团抵达开罗进行停火磋商&gt;&gt;</a></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/4755-db664b583a56590fa58f2476c3343cc7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4448, NULL, '欧盟对外行动署前亚太总司长维冈：欧中关系不是跨大西洋关系的“衍生品”', 0, 4, 42, '2025-08-13 09:30:29', '2025-08-13 07:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/92/w550h342/20250813/94cf-e8fef9dfdb3be888281def5131cbc144.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkutxn3540652.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">【编者按】</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L underline\">五十年春风化雨，中欧从相识到相知，走过了半个世纪的合作之路。“志合者，不以山海为远”，这段跨越山海与制度差异的关系，如今已不仅是一份经贸数据的增长图谱，更是两大力量、两大市场、两大文明之间思想互鉴、理念交汇的深层对话。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L underline\">在中欧建交50周年之际，澎湃新闻推出《再遇见——中欧建交50周年特别策划》，其中邀请数十位来自中国与欧洲各国及欧盟机构的各界代表性人物，通过他们的亲历、记忆与洞见，讲述这段关系如何影响着个体、社会乃至世界的走向。我们努力呈现一幅更加立体的中欧人文关系图景，也倾听他们对中欧未来的真诚期待。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L underline\">这一次，我们对话的人物是：欧盟对外行动署前亚太总司长古纳·维冈（Gunnar Wiegand）。</font></p> \n<p cms-style=\"font-L\">　　5月14日，欧盟对外行动署前亚太总司长古纳·维冈（Gunnar Wiegand）在纪念中欧建交50年之际接受了澎湃新闻（www.thepaper.cn）专访。维冈于2016年至2023年任亚太总司长。作为在欧盟外交体系工作多年的资深官员，他的职业生涯几乎贯穿了欧盟多个关键区域的对外事务。</p> \n<p cms-style=\"font-L\">　　在履职欧盟对外行动署亚太总司长之前，维冈于2011年至2015年任欧盟对外行动署俄罗斯、东部伙伴关系、中亚、欧安组织及北方维度事务的负责人，还曾担任欧盟委员会与美国和加拿大关系处处长，欧盟对外关系总局总干事和欧盟负责与东盟关系的高级官员。卸任欧盟对外行动署亚太总司长后，维冈目前在欧洲学院布鲁日校区及巴黎政治大学巴黎国际事务学院担任客座教授。</p> \n<p cms-style=\"font-L\">　　正因有跨大西洋、欧亚大陆与亚太近乎全方位的履职经历，让他对大国、地区间的互动逻辑有着全景式的观察与深刻理解。</p> \n<p cms-style=\"font-L\">　　因此，当谈及中欧关系的外部维度时，维冈直言不讳：乌克兰问题是目前中欧最大的分歧点，他希望中方能对俄罗斯施加影响，促成停火。他也指出，“把欧中关系视为跨大西洋关系的‘衍生品’是错误判断；我想中国也不会接受‘中欧关系的质量取决于中美关系’这一说法。”</p> \n<p cms-style=\"font-L\">　　以下为专访实录（略有删减）</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/92/w550h342/20250813/94cf-e8fef9dfdb3be888281def5131cbc144.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"古纳·维冈在北京接受澎湃新闻专访。澎湃新闻记者 聂舒翼 图\">\n <span class=\"img_descr\">　　古纳·维冈在北京接受澎湃新闻专访。澎湃新闻记者 聂舒翼 图</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">50年前中欧核心议题是贸易，至今仍是</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>作为长期在欧盟对外行动署工作的资深外交官，您对中欧关系发展发挥了重要的作用。您如何评价中欧建交这50年来关系演变的主线？过去50年最值得总结的经验是什么？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>当欧中宣布建交时，我只有18岁。欧共体委员会主管外事的副主席克里斯托弗·索姆斯在1975年专程来到北京，与周恩来总理达成共识。当时核心议题是贸易关系，而我认为，贸易至今仍是欧中关系的基石。若把货物贸易与服务贸易加总，欧盟是中国最大的贸易伙伴，中国则是欧盟第三大贸易伙伴。这是企业层面的客观现实。除贸易之外，在过去15年到20年里，投资的重要性日益凸显。</p> \n<p cms-style=\"font-L\">　　50年前，双边年贸易额仅20亿欧元，如今已达到约每天20亿欧元。这是一段成功故事。但贸易逆差也逐年扩大，两年前，逆差创下纪录。去年，在超过7300亿欧元的总贸易额中，我们（欧盟）的贸易逆差为3040亿欧元。我们并非唯一遇到类似问题的中国合作伙伴，中国对约75%的贸易伙伴都存在巨额贸易顺差。这是中国经济发展的巨大成就。目前存在一些失衡问题，归因于我们所说的“产能过剩”。这是当前经济领域最大的挑战。</p> \n<p cms-style=\"font-L\">　　但是，欧中关系早已超越经贸，向更多领域拓展，其中最重要的是共同应对全球挑战。欧中都认识到，作为多边领域的重要伙伴，必须紧密合作，以双边合作促多边成果，涵盖气候变化、生物多样性、公共卫生、债务重组、减灾等方面。我们的合作已带来良好成果，并能有所作为。</p> \n<p cms-style=\"font-L\">　　外交与安全政策方面的合作是另一个重要的对话领域，从缅甸、朝鲜半岛局势，到南海、东海，再到中东问题，也涵盖俄罗斯对乌克兰发动的战争以及发生在欧盟边境附近的战争，这是欧中最大的分歧点。欧盟期待中国在领土问题上秉持原则并支持领土完整和主权，为停火止战、推动和平进程发挥更大作用。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>回顾过去，中欧关系经历了“黄金十年”。2014年中方提出了中欧在“和平、增长、改革、文明”四大领域的全球伙伴关系，随后2019年欧盟通过了新的对华政策文件《欧中关系战略展望》，将中国定位为欧盟的“伙伴、竞争者和制度性对手”。2021年欧盟发布“印太战略”文件。您如何评价这一时期在中欧关系整体发展中的作用？这些文件提出的背后基于怎样的考虑？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>尽管欧中在某些议题上存在政策分歧，但中国领导层始终与欧盟保持接触；欧盟领导人也一直把对华关系视为最重要的伙伴关系之一。</p> \n<p cms-style=\"font-L\">　　我们称之为“全面战略伙伴关系”时期，欧盟曾两次制定对华总体战略，第一次是2016年，第二次是2019年。这极大提升了成员国在对华政策上的一致性，因为不同成员国在与中国的双边互动中侧重点各不相同。但每个成员国都承认对华关系的重要性。</p> \n<p cms-style=\"font-L\">　　我们也形成了对华“三重定位”：在共同关注的领域与中国保持伙伴关系；同时也意识到我们（欧中）在经济和技术领域存在竞争；并且由于拥有截然不同的制度，我们也是“制度性对手”，面对某些挑战我们会有不同的答案。因此，在同一政策领域里，往往同时包含合作、竞争与对手三种成分。</p> \n<p cms-style=\"font-L\">　　这很复杂，但也能为一些具体问题制定解决方案。有时通过双边协商解决，有时借助欧盟层面工具，协调成员国的不同做法。比如，针对在新技术和关键基础设施领域的外来投资，不仅是来自中国，也包括其他国家的投资，欧盟制定了统一的审查机制。我们并未阻止中国投资，而是设定了允许投资的标准。</p> \n<p cms-style=\"font-L\">　　正是在这一时期，欧盟愈发意识到必须形成共同的对华政策，以应对深化欧中关系进程中存在的诸多可能性。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">中欧关系的外部因素：美国？俄罗斯？</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>下面两个问题关于外部因素，首先是美国。您如何评价欧洲近年提出的“战略自主”概念？在特朗普2.0时代，美国对欧政策更趋强硬，加之关税政策的影响，看起来似乎给中欧合作带来某种机遇，您认为这是否会加速欧洲和中国某种意义上的靠拢？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>我认为，把欧中关系视为跨大西洋关系的“衍生品”是错误判断；同样，我想中国也不会接受“中欧关系的质量取决于中美关系”这一说法。</p> \n<p cms-style=\"font-L\">　　诚然，大多数成员国在北约框架下是美国的军事盟友，且与美国拥有相近的治理和经济模式，这一现实让我们（欧美）形成了非常紧密的联系，无论白宫由谁执政，盟友之间的这种结构性力量不会改变。但众所周知，欧盟在多个领域与现任美国政府存在政策分歧。正如中国在努力寻求方案避免贸易战升级一样，就欧盟而言，我们与美国拥有全球范围内最庞大的经济关系，我们面临的挑战与中国类似，但欧美经济的互融程度甚至更高。</p> \n<p cms-style=\"font-L\">　　有人会说，当欧盟试图“去风险”减少对中国的过度依赖时，是否也要对美国的过度依赖“去风险”。这就引出了“战略自主”概念。它最初源于防务领域，指欧盟应具备在内部生产关键防务装备的足够能力。如今，这一概念已扩展至经济领域的关键产品。战略自主的讨论也与提升欧洲核心产业竞争力紧密相连。</p> \n<p cms-style=\"font-L\">　　总体而言，欧盟将增强韧性，减少在关键领域对单一供应方的依赖。这并不会导致某些人希望看到的“欧美脱钩”，欧美仍将保持基于共同利益和价值观的紧密关系。只是欧盟会付出重大努力，在本土生产更多、更好的产品，并通过与全球更多伙伴建立紧密的经贸联系，实现供应链多元化。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>其次是俄罗斯，不可否认乌克兰危机给中欧关系带来了挑战，甚至是负面影响。但中方认为从中欧关系本身来说，不应该让这些因素影响到中欧关系的核心层面。中方曾多次表态，中方坚持劝和促谈，不向冲突方提供致命性武器，严格管控两用物资，并发起了“和平之友”小组，为停火止战汇聚更大合力。对此您怎么看？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>当前，各方都在努力促成停火并达成和平协议，我由衷希望，中国能对俄罗斯施加更大影响。这关系到欧中双方最直接的安全和利益。绝不能让任何国家有理由入侵邻国、占领甚至吞并其大片领土。如果这种行为再度被国际社会接受，那么全球体系的稳定都将受到严重威胁。这就是我们对此反应强烈的原因。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“欧盟不认同任何形式的脱钩，尤其不认同与中国脱钩”</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>回到中欧关系本身，技术脱钩、产业去风险化等正重塑中欧经贸关系。您是否担心未来的中欧经济联系会“渐行渐远”？有没有什么领域可能成为下一个“稳定锚”或“桥梁”？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>我不认为我们正在“脱钩”，也不会“渐行渐远”。我想特别强调，欧盟从未主张任何形式的“脱钩政策”。“去风险”的真正含义是减少因依赖单一供应方而产生的脆弱性。也就是说，让某些目前或许仅从中国获取的技术或材料，转而从多个供应方获取。这就是通过多元化实现“去风险”，绝不是停止进口，而是不再100%或95%依赖单一来源。因此，欧盟不认同任何形式的脱钩，包括不认同与中国脱钩。</p> \n<p cms-style=\"font-L\">　　除了常规贸易，在一些中国大力推进的新技术领域，欧中有广阔的合作空间。中国在诸多领域都取得了成功，从电动汽车、电池生产，到量子计算、生物技术、纳米技术等。欧盟也并行投入取得了一些成就，并仍在部分领域保持领先，另一些领域则由中国领跑。我认为，在欧洲缺乏传统产业优势的高科技领域，与中国开展紧密的合作具有重要意义。</p> \n<p cms-style=\"font-L\">　　我们必须承认，中国在部分领域已走在前列。过去在与投资企业的谈判中，焦点始终围绕如何支持欧洲企业扎根中国、开放曾对外国投资关闭的行业、完善合资机制、加强知识产权保护、确保技术转让，这些历来是中方提出的诉求。而今在欧洲，我们对中国投资企业提出的要求，恰与当年中方诉求如出一辙。</p> \n<p cms-style=\"font-L\">　　这标志着双方关系进入了令人振奋的新阶段，我们的整体关系更趋平衡，尽管贸易往来数据尚未体现平衡。而这一点，正是我们（欧盟）希望后续能得到解决的问题。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“欧中应全力推动构建让各国都能自主决策的全球体系”</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>对于中欧关系的“下一个50年”，您最担心的是什么？最希望看到的又是什么？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>我真正担忧的是，尽管在现实层面，我们的社会、人民在全球范围内联系日益紧密，全球化已是现实，每一个欧洲人和中国人都身处其中，但是，如今人们谈论多极化的复兴时，实际上是在谈论倒退。</p> \n<p cms-style=\"font-L\">　　我们本应致力于构建一个有效的全球体系，不仅是有效的全球贸易体系，更应涵盖公共卫生、气候变化，以及安全问题。然而现实是，我们正在目睹昨日重现——形成不同的势力范围，由不同的“极”主导这些势力范围，然后要求小国“效忠”。</p> \n<p cms-style=\"font-L\">　　我可以明确地说，这不是欧洲的理念。几个世纪以来，欧洲曾通过不同的帝国推动过这种“势力范围”体系。这让我们吸取了教训，无论国家大小，都应遵循相同的规则，规则必须一视同仁地适用。</p> \n<p cms-style=\"font-L\">　　我认为，这正是欧中需要共同努力的核心使命。我们不能回到过去，而应全力推动构建一个让各国都能自主决策的全球体系。国家可以选择更倾向于加入某一方，或与各方都保持良好关系，但不应被强迫依附于任何一极。因此，多极化本身无可厚非，但胁迫行为绝对不行。必须有对所有国家一视同仁的多边规则。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">澎湃新闻：</font>最后，我们给所有受访嘉宾提的一个问题：您对中欧关系的未来有何期望寄语？</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">维冈：</font>希望欧中双方的决策者，能为这段广阔、深厚的双边关系注入最好的动力。这段关系建立在四个关键能力和潜力之上：</p> \n<p cms-style=\"font-L\">　　第一，智慧与经验，欧中双方都拥有古老文化和文明，让我们规避最坏的情况，追求最好的未来；第二是创造力；第三是双方都蕴含的能量，即便面对看似难以解决的问题，这种驱动力也能推动我们前进；最后是妥协的能力，很多时候，我们双方常执着于己方的最优先议题、愿景或诉求，但我们也必须理解对方关切。</p> \n<p cms-style=\"font-L\">　　如果我们能将这四点融入国际体系的改革中，必将成功造福于双方人民。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/92/w550h342/20250813/94cf-e8fef9dfdb3be888281def5131cbc144.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4449, NULL, '仅4天！从“立即辞职”逆转“成功典范”，英特尔CEO与特朗普的会面发生了啥？', 0, 4, 207, '2025-08-13 09:30:45', '2025-08-13 01:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/383/w1703h1080/20250812/7317-a6bf481bf7c6e4f16e00f213f6ea3752.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infktsmy4089595.shtml', '成都商报', '<p cms-style=\"font-L\">　　英特尔的命运，在短短几天内发生了戏剧性的变化。</p> \n<p cms-style=\"font-L\">　　当地时间8月7日，美国总统特朗普在社交网站发帖要求英特尔CEO陈立武立即辞职，并称他存在“严重的利益冲突”。令人意想不到的是，仅时隔4天，与陈立武会面后的特朗普就口风全改。</p> \n<p cms-style=\"font-L\">　　特朗普11日发文称，陈立武的“成功与崛起是一个了不起的故事<font cms-style=\"font-L\">”。</font>此后英特尔股价大涨超2%。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/383/w1703h1080/20250812/7317-a6bf481bf7c6e4f16e00f213f6ea3752.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲当地时间4月29日，美国加州圣何塞，英特尔代工大会上的陈立武 图源/IC photo\">\n <span class=\"img_descr\">▲当地时间4月29日，美国加州圣何塞，英特尔代工大会上的陈立武 图源/IC photo</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">扭转印象：</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">“单枪匹马”与特朗普及内阁成员会面</font></p> \n<p cms-style=\"font-L\">　　特朗普表示，11日的会面除了有陈立武之外，还有美国商务部长霍华德·卢特尼克和财政部长斯科特·贝森特在场。特朗普称：“这次会议非常有趣，他（陈立武）的成功和崛起是一个了不起的故事。”</p> \n<p cms-style=\"font-L\">　　英特尔公司随后发布声明表示，陈立武与内阁成员“共度了一段时光”，讨论其对“加强美国技术和制造业领导地位”的承诺，并补充说这场会谈是“坦诚而建设性的”。</p> \n<p cms-style=\"font-L\">　　此前，特朗普对陈立武的任职充满质疑，是因为共和党参议员汤姆·科顿给英特尔董事会主席耶里的信中表示，他“对英特尔运营的安全性和完整性及其对美国国家安全的潜在影响表示担忧”，并询问英特尔董事会是否知悉陈立武在担任楷登电子首席执行官期间，楷登电子曾收到过传票。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">临危受命：</font></p> \n<p cms-style=\"font-L align-Center strong-Bold\">　　出任“救火队长”带领英特尔转型AI</p> \n<p cms-style=\"font-L\">　　今年3月18日，作为“救火队长”的陈立武临危受命，出任英特尔CEO。上任之后陈立武立马大刀阔斧进行架构改革，要求数据中心、AI客户端和云计算部门直接向他本人汇报，减少中间管理层的臃肿。陈立武在内部备忘录中表示：“英特尔这家伟大的企业，被无比复杂的组织和沉重的官僚文化拖了后腿，扼杀了创新文化。”他还反思道：“决策时间太长了。新想法缺乏孵化的空间和资源，不必要的部门壁垒导致执行效率低下。”</p> \n<p cms-style=\"font-L\">　　陈立武上任后还任命萨钦·卡蒂为首席技术官（CTO）和AI负责人，负责AI战略、产品路线图和英特尔实验室。萨钦的斯坦福背景和创业经验被认为有助于推动AI创新。其他技术高管也直接向陈立武汇报，在内部强调“工程优先”的文化。陈立武在员工大会上表示，他将致力于打造一个专注于创新、速度和执行力的“新英特尔”。</p> \n<p cms-style=\"font-L\">　　陈立武延续了前任帕特·基辛格的裁员计划，并进一步扩大目标，要在两年内削减15亿美元的运营费用。2025年4月，他宣布裁员重点将放在中层管理，以消除效率低下的部门，裁员规模可能达到15%（约1.5万名员工）。在芯片战略上，陈立武放弃了英特尔原先准备挑战台积电2纳米工艺的18A制程计划，将资源全部转向AI芯片。他个人购买了2500万美元的英特尔股票，表明对公司未来的信心，并且表示公司股价与他的五年薪酬计划挂钩。</p> \n<p cms-style=\"font-L\">　　红星新闻记者 郑直 综合环球时报</p> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/383/w1703h1080/20250812/7317-a6bf481bf7c6e4f16e00f213f6ea3752.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4450, NULL, '东方电气集团“氢”动力保障成都世运会绿色交通', 0, 2, 231, '2025-08-13 09:31:17', '2025-08-13 08:44:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/420/w1280h740/20250813/2e1f-2154c972205f545aa9231141d42ee766.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyff8034140.shtml', '国资委网站', '<p cms-style=\"font-L\">　　8月7日，2025年第12届世界运动会在四川省成都市开幕。东方电气集团发挥优势，为成都世运会提供了24辆氢能公交车，打造世运会绿色交通“氢”洁专线，为世运会提供“氢”动力。</p>\n<p cms-style=\"font-L\">　　这是继第31届世界大学生夏季运动会后，东方电气集团再次为国际体育盛会提供服务保障。本次提供的24辆氢能公交车，穿梭于世运村与各赛场之间，承担起接送裁判、工作人员、媒体记者出行的任务，以零排放、大载量、超长续航、智慧安全、高可靠性，成为成都世运会绿色交通保障的“主力军”。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250813/420/w1280h740/20250813/2e1f-2154c972205f545aa9231141d42ee766.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　为践行成都世运会绿色低碳办赛理念，这批氢能公交车通过“氢”和“氧”的电化学反应产生电能，从而驱动车辆，全程只产生水，真正实现零排放。在动力保障上，氢能公交车搭载了东方电气集团自主研制的氢燃料电池系统，系统最高效率超过61%，百公里氢耗不到4千克，与传统内燃机相比，噪声小、安全舒适。在供氢系统上，该公交车配备了20千克大容量供氢系统，加满氢仅需10分钟，综合续航超过500公里，适应成都主城区及周边区域各种路况乘运，完全满足成都世运会交通保障需要。在驾乘体验与安全保障上，该公交车还搭载了空气悬架系统，具备享受更平稳舒适的驾乘体验，同时配备了360度视频监控、智能胎压监测、烟雾监测报警等多重安全配置，结合主动安全智能防控系统，全方位守护行车安全。不仅如此，智能网联功能的融入实现了车辆智慧化运营管理，真正做到集高效环保、安全可靠、智能智慧于一身。</p>\n<p cms-style=\"font-L align-right\">　　【责任编辑：韩梦圆】</p>', '[\"https://k.sinaimg.cn/n/spider20250813/420/w1280h740/20250813/2e1f-2154c972205f545aa9231141d42ee766.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4451, NULL, '涠洲岛一观光车司机言语威胁游客人身安全，官方通报：行拘7日', 0, 2, 217, '2025-08-13 09:31:30', '2025-08-13 08:41:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkutxi8163387.shtml', '澎湃新闻', '<p cms-style=\"font-L\">　　广西北海市涠洲岛旅游区管理委员会8月13日发布关于涠洲岛一男子威胁他人人身安全被行拘的情况通报。全文如下：</p> \n<p cms-style=\"font-L\">　　8月8日11时17分，游客张女士报警称，其因观光车接送费用问题与司机邓某发生争执，对方言语威胁其人身安全。接警后，辖区派出所依法开展调查。目前，邓某因违反《中华人民共和国治安管理处罚法》相关规定，<font cms-style=\"font-L strong-Bold\">已被公安机关依法处以行政拘留7天并处罚款。</font></p> \n<p cms-style=\"font-L\">　　我委对张女士一行在涠洲岛的不佳体验深表歉意！此事反映出涠洲岛在旅游秩序管理中存在短板，对旅游从业人员的教育引导仍有不足。我委将深刻反思、全面整改，对扰乱市场秩序、损害游客权益的行为“零容忍”严惩，坚决维护海岛形象。</p> \n<p cms-style=\"font-L\">　　广大游客的每一条意见，既是鞭策我们改进的警钟，更是提升服务品质的动力。我们始终敞开渠道倾听诉求，以实际行动保障游客权益，持续优化旅游体验，全力营造安心、舒心、放心的旅游环境。衷心感谢社会各界对涠洲岛的关心、监督与支持！</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4452, NULL, '韩国星巴克禁止顾客携带大型办公设备入店', 0, 4, 105, '2025-08-13 10:30:16', '2025-08-13 10:15:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkuyfp1140779.shtml', '参考消息', '<p>　　来源：参考消息</p> \n<p>　　参考消息网8月13日报道 据美国《财富》杂志网站8月11日报道，有人在星巴克惬意地喝着拿铁，查看电子邮件，有人则拖着打印机和台式电脑去这家咖啡连锁店打卡上班。星巴克韩国门店正在经历这种情况，现在开始禁止顾客携带大型办公设备入店，把咖啡馆当成设施齐全的办公空间。</p> \n<p>　　星巴克的一名发言人在一份声明中说：“韩国星巴克已经更新政策，旨在让所有顾客都能有愉快便捷的体验。笔记本电脑和较小的个人设备受到欢迎，但请顾客们不要携带台式电脑、打印机或其他可能限制座位并影响共享空间的大件物品。”</p> \n<p>　　星巴克开始打击“咖学族”（在咖啡馆长时间工作或学习的人），或许表明他们对顾客的态度正在发生转变。这些可能都是忠诚的顾客，却把星巴克致力于打造舒适第三空间的努力视为理所当然。</p> \n<p>　　乔治·华盛顿大学韩国语言文化与国际事务荣誉教授金荣起告诉本刊记者，韩国有浓厚的茶室文化。</p> \n<p>　　她说：“即使极度贫困，人们也会聚集在茶室里讨论文学、艺术、政治等等，觉得自己很有文化。”</p> \n<p>　　但是，“咖学族”因为韩国劳动力市场和远程办公模式的转变逐渐受到公众关注。疫情期间，大量员工需要远程办公。但是，随着许多韩国人重返办公室，政府的规定限制了企业的办公空间，尤其是在租金飞涨的首尔。</p> \n<p>　　澳大利亚科廷大学韩国社会与文化副教授乔·埃尔温·黄（音）说，一些韩国公司找不到或负担不起办公空间，就让员工到第三方共享办公空间或者远程办公，导致许多人涌向咖啡馆。（编译/赵菲菲）</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4453, NULL, '韩国前第一夫人金建希被拘押详情曝光：将被单独监禁，没有床只能睡地板，第一顿早餐为烤面包、草莓酱、牛奶等', 0, 4, 105, '2025-08-13 10:30:26', '2025-08-13 09:27:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250813/b7b1-0fbbd0650724511e99bee1c5bca7b5a0.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuyfc4299064.shtml', '南方都市报（记者 肖玥）', '<p>　　8月12日深夜，韩国首尔中央地方法院签发对尹锡悦妻子、前第一夫人金建希的拘捕令，她被首尔南部拘留所拘押。韩国首次出现前总统夫妇同时被捕的情况。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250813/b7b1-0fbbd0650724511e99bee1c5bca7b5a0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"尹锡悦和金建希\">\n <span class=\"img_descr\">尹锡悦和金建希</span>\n</div> \n<p>　　据称，有关特检组预计将首先对金建希涉嫌参与操纵宝马汽车在韩经销商德意志汽车股价、与政治掮客明泰均干预总统选举等已调查到一定程度的罪名提起诉讼。在申请拘捕令时，这些罪名均被列为重大犯罪指控。之后，特检组预计将通过进一步调查，对剩余案件进行逐一起诉。</p> \n<p>　　金建希目前已被拘押至首尔南部拘留所，接受单独监禁前的体检等，包括测量身高和体重，换上囚服，并拍摄面部照片。单独监禁房间的大小可能因拘留所的具体情况而异，但通常分配的单人间面积为2至3坪（约6.6至10平方米）。</p> \n<p>　　房间配备简易卫生间、折叠桌、电视和马桶，但没有单独的床，金建希只能睡在铺在地板上的毯子上。如果她被分配到更大的房间，可能房间内还会配备水槽等。</p> \n<p>　　其餐食与普通犯人相同，据称，13日的第一顿早餐为烤面包、草莓酱、牛奶、烤法兰克福香肠、蔬菜沙拉。</p> \n<p>　　南都此前报道，8月12日上午，金建希抵达首尔中央地方法院，出席了定于当地时间10时10分开始举行的拘捕必要性审查。相关特检组两次提交的意见书长达847页，担忧金建希可能销毁证据。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/81/w550h331/20250813/635c-33575caf2e10851fda120d434b835fc6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"金建希\">\n <span class=\"img_descr\">　　金建希</span>\n</div> \n<p>　　2009年至2013年间，金建希及其家属涉嫌参与操纵宝马汽车在韩经销商德意志汽车股价，并于2020年4月被举报。2023年2月1日，共同民主党正式推进检方对金建希涉嫌股价操纵案的特别调查。特别工作组团长宋基宪表示，金建希据此获得了相当于10.5亿韩元（约合540万元人民币）的利益。</p> \n<p>　　此外，金建希还涉嫌违反韩国《关于禁止接受不正当请托和财务的法律》（反贪法），于2022年9月13日从旅美律师崔在英处，收受价值相当于300万韩元（约合1.6万元人民币）的名牌包。</p> \n<p>　　2024年10月16日，金建希与政治掮客明泰均的昔日聊天记录又遭曝光。金建希在其中称，“你辛苦了，请原谅我那不懂事喜欢乱说话的哥哥，让我很为难。我现在完全依赖明老师”。上述内容被指涉嫌与明泰均一同干预总统竞选。明泰均此前还公开表态，称自己在总统选举时常常出入尹锡悦私宅，向其提供政治谏言。</p> \n<p>　　来源：南方都市报（记者 肖玥）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦再次被捕</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/151/w550h401/20250813/b7b1-0fbbd0650724511e99bee1c5bca7b5a0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/81/w550h331/20250813/635c-33575caf2e10851fda120d434b835fc6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4454, NULL, '北京移动致歉：少量用户出现无法使用个别APP或小程序情况，正在积极排查中', 0, 1, 1, '2025-08-13 10:30:45', '2025-08-13 10:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyfp1141571.shtml', '界面新闻', '<p cms-style=\"font-L\">　　@北京移动10086热线 发文称：8月13日早间，北京移动少量用户出现无法使用个别APP或小程序的情况。由此给用户造成的不便，我们深表歉意。我们正在积极排查中，尽快逐步恢复。衷心感谢各位网友的关注与监督！</p> \n<p cms-style=\"font-L\">　　此前报道：<a href=\"https://finance.sina.com.cn/tech/roll/2025-08-13/doc-infkuyfk3470926.shtml\" target=\"_blank\" data-comos-dataid=\"comos:nfkuyfk3470926\">北京移动网络今早疑似出现故障 网友反馈多个APP无法正常使用</a></p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4455, NULL, '内蒙古“婚内强奸案”庭审细节曝光，伤情鉴定结果与医院诊断报告有出入，男方否认处于长期分居状态', 0, 1, 5, '2025-08-13 10:30:52', '2025-08-13 10:13:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/58ac-8e3dc1bb532519fb9ae6fc9aa101ee59.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyfc4337106.shtml', '大河报', '<p>　　来源：大河报</p> \n<p>　　8月12日上午，内蒙古“婚内强奸案”在额尔古纳市人民法院一审开庭，此案非公开审理。涉案男子刘某因违背被害人王某意愿，使用暴力手段强行与被害人王某发生性关系，被以强奸罪提起公诉。</p> \n<p>　　下午4时许，庭审结束。据刘某姐姐透露，弟媳王某并未到场，委托代理律师出庭。庭审中，双方对女方伤情鉴定存在争议，对于男方家属与代理律师提出的重新做伤情鉴定的诉求，法院予以支持。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/58ac-8e3dc1bb532519fb9ae6fc9aa101ee59.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　男方代理律师付建（左）与男方姐姐</p> \n<p>　　伤情鉴定与医院诊断结果有出入，男方申请重做</p> \n<p>　　起诉书上提及，被告人刘某与被害人王某于2月27日申请协议离婚，进入离婚冷静期，双方处于分居状态。3月21日上午8时许，刘某在听到放置在王某卧室中的录音笔的内容后，因怀疑王某与他人有不正当关系，对王某殴打辱骂，然后违背王某意愿，强行与其发生性关系，并用手机拍摄两段视频。</p> \n<p>　　3月21日下午4时许，被害人王某以被殴打为由报警，次日20时许以被家暴、强奸为由再次报警。被告人刘某于3月22日被传唤到案。</p> \n<p>　　大河报《看见》记者从知情人处看到了王某的CT诊断报告与入院记录。其中提及，3月21日上午，王某被诊断为L2、L4椎体左侧横突骨折。3月21日下午4时许，王某入院治疗，3月27日，王某出院。相关记录显示，除腰椎骨折外，王某有头部外伤，腰部、上肢、下肢挫伤。</p> \n<p>　　知情人介绍，呼伦贝尔市公安司法鉴定中心出具的鉴定书鉴定王某L2-L4 腰椎左侧横突骨折，评定为轻伤一级，这与王某在医院的CT诊断报告“L2、L4椎体左侧横突骨折”不一致，前者为三处骨折，后者为两处。</p> \n<p>　　公诉方称公安司法鉴定中心与医院是根据同一份CT结果做此认定，由此男方代理律师当庭提出重新做伤情鉴定，法院予以支持。男方律师付建称，这将决定伤情鉴定是轻伤，还是轻微伤，对量刑结果有重要意义。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/235/w550h485/20250813/ec45-559861105344e24a14dfd9e4dfc1585c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　妻子称两人长期分居，丈夫利用婚姻关系实施强行性行为，男方否认</p> \n<p>　　记者从获取的女方刑事附带民事起诉状中看到，原告王某提出要被告刘某赔偿原告医疗费、护理费、误工费、精神损害抚慰金共计303496.68元，其中，精神损害抚慰金为30万元。</p> \n<p>　　起诉状中提及，妻子王某与被告刘某案发前已经长期分居，原告多次要求离婚，被告始终拒绝。此外，被告利用婚姻关系实施强行性行为，严重侵害原告的性自主权及人格尊严，认为其行为已构成强奸罪。</p> \n<p>　　对于夫妻两人是否长期分居，男方姐姐称，法庭上弟弟解释道，因自己打呼噜等问题，所以夫妻两人分屋睡觉，但他们仍一起吃饭、生活、有经济往来，不认为这属于长期分居状态。并且，弟弟表示向妻子动手确实不对，但在婚姻关系存续期间，其行为不构成强奸。</p> \n<p>　　8月12日庭审前后，记者与妻子王某联系未获回应。</p> \n<p>　　男方代理律师付建称，控辩双方在庭审中就是否构成强奸罪进行了多次辩论。付建称，法院将另行通知下次开庭时间。</p> \n<p>　　此前报道：<a href=\"https://video.sina.com.cn/p/finance/2025-08-12/detail-infktncu7949108.d.html\" target=\"_blank\" data-comos-dataid=\"comos:nfktncu7949108\">内蒙古“婚内强奸案”一审开庭 案发时两人处于“离婚冷静期”</a></p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/58ac-8e3dc1bb532519fb9ae6fc9aa101ee59.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/235/w550h485/20250813/ec45-559861105344e24a14dfd9e4dfc1585c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4456, NULL, '潍坊全城亮屏致敬！援非医生张军桥海外救人牺牲，被授予“齐鲁时代楷模”称号', 0, 1, 15, '2025-08-13 10:31:17', '2025-08-13 09:37:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/3518-eef11758695afd76280c206994250953.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyff8068097.shtml', '新黄河客户端（记者：李焜染）', '<p cms-style=\"font-L\">　　8月12日，齐鲁时代楷模发布厅举行发布仪式，授予第27批援坦桑尼亚中国（山东）医疗队队长、山东第二医科大学附属医院麻醉科专家张军桥同志“齐鲁时代楷模”称号。</p> \n<p cms-style=\"font-L\">　　2025年6月15日，在遥远的坦桑尼亚达累斯萨拉姆海域，为营救当地落水民众，张军桥奋不顾身，英勇牺牲，将生命永远定格在异国他乡的碧海蓝天之间。生前，他奔走在救死扶伤的临床一线，是患者信赖的好医生，他还发起名为“心跳行动”公益项目，组建志愿服务队，推动“急救复苏进校园”“急救复苏进企业”，惠及民众超2万人次。他甚至将自家新装修的客厅改造成了公益培训基地，免费为市民提供急救培训。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/3518-eef11758695afd76280c206994250953.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　从医16年来，他坚守临床一线治病救人，孜孜不倦教学育才，用精湛医术和奉献精神守护人民健康，他发起“心跳行动”志愿服务，驰援湖北勇战疫情，远赴非洲传递医者大爱，为当地留下一支“带不走的医疗队”。</p> \n<p cms-style=\"font-L\">　　社会各界怀念张军桥</p> \n<p cms-style=\"font-L\">　　山东大学齐鲁医学院团工委副书记王为萍：</p> \n<p cms-style=\"font-L\">　　学习了张军桥同志的事迹，真的深受感动。他以凡人之躯筑起了生命的桥，从潍坊街头广场跪地传授急救知识，再到异国他乡援非期间为救陌生人的无畏一跳，短暂的一生，却将“医者仁心”四字刻进时代丰碑。</p> \n<p cms-style=\"font-L\">　　山东省立三院运管部科员郭丰勇：</p> \n<p cms-style=\"font-L\">　　我也是一名医生，在院内宣传看到他的消息，觉得他做的事情非常感人，他特别厉害，以后要向他学习，在本职工作上向他靠拢。医务工作者都应该向他学习，在当地没有这么多医疗资源的情况下，自己单打独斗，开拓一片新的天地，非常不容易。肯定他的品质，也佩服他的专业技术。</p> \n<p cms-style=\"font-L\">　　山东中医药大学妇产科学研究生田彧潇：</p> \n<p cms-style=\"font-L\">　　我是在学校宣传栏得知了他的事迹，他也是我们的师兄，知道他去援非，不幸牺牲，感觉这位师兄令人敬佩，非洲条件艰苦，为了救人献出了自己的生命，是我们的榜样。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/568/w550h818/20250813/4221-5981ed4e84964665efed0b3daf22637d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　山东第二医科大学附属医院电生理室医生刘静：</p> \n<p cms-style=\"font-L\">　　我被张军桥的事迹感动，也想尽自己的力量去帮助更多的人，之前在广场看到张军桥给别人做科普，非常认真，被这种精神打动，后来加入到“心跳行动”志愿服务队伍，才真正感受到这种辛苦。一晚上双膝跪地，不辞辛苦，他是实实在在的，无怨无悔，也是我们对他特别敬佩的地方。很多人看到张军桥的事迹，一直也在努力加入到这个队伍中来。</p> \n<p cms-style=\"font-L\">　　同事眼中的张军桥</p> \n<p cms-style=\"font-L\">　　“我是2017年在入院实习期间认识的桥哥，我当时就觉得他没架子，特别乐观幽默，有什么不懂的问题，他总是不厌其烦地告诉我，我们都喜欢找他帮忙，因为他总是会帮我们。”山东第二医科大学附属医院消化内科二病区护师谢冠宇说，2020年，她在朋友圈看到张军桥正在广场摆地摊，教大家学习心肺复苏的知识，她觉得很好奇，就询问他，“我特意去广场看了看，看到他跪在地上全神贯注的样子，我就被打动了，从那时候起就加入了‘心跳行动’志愿服务队，也是最早加入队伍的一员。”</p> \n<p cms-style=\"font-L\">　　谢冠宇说，2020年7月份队伍才有十多个人，到了9月份就发展到了百余人，“大部分都是我们医院各个科室的医生，有呼吸科、神经内科、消化科、急诊科等等，不少群众跟着学习了几次，自己也带着亲戚过来一起学。”让谢冠宇记忆犹新的是有一位老人，之前家里两位亲人去世，就是因为没有普及心肺复苏的知识，看到张军桥他们在摆地摊，学习之后还主动教给其他人怎么操作，让他们非常感动。</p> \n<p cms-style=\"font-L\">　　现如今，“心跳行动”志愿服务队已经举行了400多场公益活动，有300多名医务工作者加入其中，“我们每周都要举行摆摊教学，有时候会去学校、社区、红十字会等地方进行义务宣讲，呼吁更多人学习心肺复苏的知识。”</p> \n<p cms-style=\"font-L\">　　“严谨、热情、纯粹”</p> \n<p cms-style=\"font-L\">　　“我和张军桥医生认识是在2020年7月份，我通过微信朋友圈看到他在摆摊急救，我就说‘桥哥，我能不能跟着你一起去做？’当时，张军桥医生非常欢迎我们医务人员一块加入到队伍当中，我们就成为最早的第一批队员，开始了摆摊教民众急救的‘科普之路’。”山东第二医科大学附属医院急诊科护师庄坤朋说，他加入到“心跳行动”志愿服务队这个队伍当中，对他的提升非常大，在授课与人交际方面，包括专业技能方面都有一些提升。</p> \n<p cms-style=\"font-L\">　　庄坤朋对张军桥的印象用“严谨”“热情”“纯粹”几个词概括。</p> \n<p cms-style=\"font-L\">　　为什么说张军桥纯粹，庄坤朋觉得他是个很简单的人，简单到有什么想法就去做，不会顾及那么多，“我们每次去广场摆地摊都需要拉着不少模拟人，模拟人其实比较大，这就需要汽车空间大一些，为了能拉更多的模拟人，桥哥就买了辆车，每次都是他拉模拟人过去，他就是这么纯粹，想到什么力所能及地就去做，不会考虑那么多。”</p> \n<p cms-style=\"font-L\">　　得知张军桥发生意外，庄坤朋一开始有点不敢相信，“他平时工作非常严谨，非常注重安全，我没想到是在海里发生了意外。他肯定是做好了很多安全措施，在发现状态不好的情况下，才把自己救生衣脱下来给了别人。”</p> \n<p cms-style=\"font-L\">　　“他平时就像一个大哥哥，会分享一些医务知识”</p> \n<p cms-style=\"font-L\">　　庄坤朋比张军桥小10岁，在他的心里，张军桥一直像一个大哥哥一样照顾他，虽然平时不在一个科室，但是只要有需要帮助的地方，张军桥总是及时出现，耐心解答。</p> \n<p cms-style=\"font-L\">　　“急诊是在院外急救，而到了住院时，就需要请麻醉科协助一起抢救，那时候会有一起共同相处的时候，也会进行交流，”庄坤朋说，“不仅是在见面时，在线上有最新的医学指南，医学论文都会分享给我，私下看到比较好的急诊工作方面的理论点，也会告诉我，‘庄啊有时间学习一下’。”庄坤朋说。</p> \n<p cms-style=\"font-L\">　　“他是在医护工作上非常严谨、技术过硬的一个人，在生活中他也是非常热爱生活的一个人。他平常喜欢户外的一些探险旅行，包括骑行。他到了非洲以后，在非洲土地上去种咱们的豆角，种一些农作物，在那么艰苦的条件下一边忙着医院的医疗工作，还要带当地的医务人员完成一些高难度的麻醉手术。”庄坤朋回忆到。</p> \n<p cms-style=\"font-L\">　　他总是在力所能及地帮助别人</p> \n<p cms-style=\"font-L\">　　除了摆摊教心肺复苏之外，平日里，“桥哥”遇到一些贫困的老人也会给予一定的帮扶。</p> \n<p cms-style=\"font-L\">　　“他虽然没有很多的财力去支持，但是逢年过节都会买一点生活用品去送给这些老人，之前就有一个小姑娘因为没钱做手术，张军桥得知后联系我们医院，在医院的帮助之下给小姑娘完成了手术。”庄坤朋说。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/205/w550h455/20250813/3756-4c38419a0553151adc68c21793a5f768.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　这样的事儿还有很多很多，比如在路上遇到有人出车祸，张军桥也会义无反顾地冲上去第一时间救人。在非洲，看到有民众落水，他也没有顾及那么多，“他可能做好了一定的措施之后，跳到水里去救人，这些都是非常英勇的一些行为，但是在他身上却特别平常，他就是这样的人。”</p> \n<p cms-style=\"font-L\">　　不仅是对待需要帮助的患者，对待同事们，张军桥也一直是一个热心肠。让庄坤朋记忆犹新的一件事是那次下班以后去广场“摆摊”，一般活动两三个小时，大家都很累，“他就鼓励大家，有时候太累他就说你歇一会我替你上，这种事经常会有，他就像一个大哥哥一样，不管是在工作中还是生活中，对我们都是非常照顾。”</p> \n<p cms-style=\"font-L\">　　来源：新黄河客户端（记者：李焜染）</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/163/w550h413/20250813/3518-eef11758695afd76280c206994250953.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/568/w550h818/20250813/4221-5981ed4e84964665efed0b3daf22637d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/205/w550h455/20250813/3756-4c38419a0553151adc68c21793a5f768.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4457, NULL, '巴拉圭代理众议长：我们在台湾问题上浪费时间，中国一丁点投资就能改变经济', 0, 4, 154, '2025-08-13 11:30:18', '2025-08-13 10:36:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/33d1-3481e240a2215d60f033af9d032abc89.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuyff8101342.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 熊超然】当地时间8月12日，巴拉圭国会举行听证会，该国政府部长概述了一项拟议的“组装产业法”，该法案将允许企业使用进口零部件（其中许多来自中国大陆）在当地生产电子和数码产品。</p> \n<p cms-style=\"font-L\">　　香港《南华早报》报道指出，这项立法的出现，正值巴拉圭国内出现越来越多的声音，要求该国重新审视数十年与中国台湾地区的所谓“外交关系”。当前，巴拉圭政界正就与台当局“断交”并与中华人民共和国建交展开激烈辩论。</p> \n<p cms-style=\"font-L\">　　报道称，今年7月下旬，巴拉圭国会众议院第一副议长，也是该国代理众议长的乌戈·梅萨访问中国大陆，他回国后呼吁就此问题展开全国性辩论。来自执政党红党（Colorado Party）的梅萨认为，巴拉圭在台湾问题上“浪费时间”，并表示即使是中国大陆在拉丁美洲巨额投资中的一小部分，也能改变巴拉圭经济。</p> \n<p cms-style=\"font-L\">　　“我们是少数几个不承认中国（未与中国建交）的国家之一，与巴拉圭给予的相比，我们从台湾地区得到的帮助微不足道。”他表示，其目的并非是想威胁或勒索，而是鼓励就潜在的经济利益进行公开讨论。他还强调，台湾只是中国的一个省，巴拉圭应基于国家利益就发展对华关系展开认真讨论，不应再做“乞丐国家”等待同台当局“合作”。</p> \n<p cms-style=\"font-L\">　　对于梅萨的相关言论，我外交部发言人郭嘉昆8月1日曾表示，中方注意到有关报道。我们已经多次听到类似的声音，有关表态反映了巴拉圭多数民众的强烈意愿。</p> \n<p cms-style=\"font-L\">　　近年来，越来越多的巴拉圭朋友认识到，巴拉圭不能再继续做国际社会的“异类”，“背对”中国。我们希望巴拉圭政府能够认真倾听这些呼声，作出真正符合巴拉圭和巴拉圭人民根本和长远利益的正确选择。我们也欢迎更多巴拉圭朋友来中国参访，亲身体验中国发展，感受中华文明的开放包容，认识真正的中国。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/33d1-3481e240a2215d60f033af9d032abc89.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"巴拉圭国会众议院第一副议长乌戈·梅萨\">\n <span class=\"img_descr\">　　巴拉圭国会众议院第一副议长乌戈·梅萨</span>\n <font cms-style=\"font-L\"> 资料图</font>\n</div> \n<p cms-style=\"font-L\">　　据报道，巴拉圭经济与财政部长卡洛斯·费尔南德斯·巴尔多维诺斯（Carlos Fernández Valdovinos）和工业和贸易部长哈维尔·希门尼斯（Javier Giménez）在国会参议院听证会上表示，这项措施将允许目前进口整机组装产品的企业转向进口零部件，并在巴拉圭组装，将产品贴上“巴拉圭制造”的标签。</p> \n<p cms-style=\"font-L\">　　政府官员们表示，这项举措可以在不限制现有进口的情况下，降低成本、创造就业机会，并实现该国生产基础多元化。</p> \n<p cms-style=\"font-L\">　　据悉，该计划将涵盖从电视、冰箱到微波炉、空调等各种商品，并将借鉴巴拉圭的汽车政策，该政策已使90%在巴拉圭道路上行驶的摩托车实现本地化组装。</p> \n<p cms-style=\"font-L\">　　希门尼斯表示，当前的全球贸易紧张局势为巴拉圭带来了难得的机遇。他表示，美国近期对中国出口商品征收的关税以及对巴西出口商品征收50%的关税，可能使巴拉圭成为“一个有吸引力的组装服务中心”。“如果我们把握这一优势，进口商和企业家就可以开设工厂，进口零部件并在这里组装。”</p> \n<p cms-style=\"font-L\">　　报道称，目前该法案仍在巴拉圭国会展开辩论，一些商业团体支持该法案，但也希望加以修改。巴拉圭进口商中心提议，将国内增值税要求从20%提高到40%，并分阶段实施该法案，以便企业有时间适应。</p> \n<p cms-style=\"font-L\">　　目前，台当局仅剩12个所谓的“邦交国”，分别为帕劳、图瓦卢、马绍尔群岛、伯利兹、圣文森特和格林纳丁斯、危地马拉、海地、巴拉圭、圣卢西亚、圣基茨和尼维斯、斯威士兰、梵蒂冈。</p> \n<p cms-style=\"font-L\">　　其中，巴拉圭是南美洲仅剩的一个仍与台湾保持所谓“外交关系”的国家，也是这12个国家中国土面积最大、人口最多的。作为南美洲内陆国家，巴拉圭与阿根廷、玻利维亚和巴西三国为邻，国土面积40.68万平方公里，人口约637万，95％为印欧混血种人，其余为印第安人和白种人。</p> \n<p cms-style=\"font-L\">　　去年8月21日，路透社曾报道，巴拉圭总统圣地亚哥·培尼亚称，尽管巴拉圭与台当局有“外交关系”，但他仍对通过南方共同市场（南共市）与中国大陆达成贸易协议持“完全开放”态度。</p> \n<p cms-style=\"font-L\">　　由阿根廷、巴西、巴拉圭、乌拉圭、玻利维亚等组成的南共市是一个关税同盟组织，正与欧盟、中国大陆等就双边贸易协议展开讨论。培尼亚当时在巴拉圭首都亚松森接受路透社访问，他谈及巴拉圭在南共市内部的立场时称：“我们对中国大陆的立场是完全开放的。”</p> \n<p cms-style=\"font-L\">　　按照培尼亚的说法，他竟声称巴拉圭方面“赞成推进”与中国大陆市场的贸易协定，但“障碍”在于中国大陆并不接受其对台当局的“承认”。</p> \n<p cms-style=\"font-L\">　　路透社则评论认为，巴拉圭对台当局的“长期外交支持”已经阻碍了当地农业出口寻求更大市场。事实上，培尼亚此前也坦言，他面临来自国内农业团体等要求巴拉圭与台当局“断交”的压力。</p> \n<p cms-style=\"font-L\">　　此前，我外交部发言人曾指出，世界上只有一个中国，台湾是中国领土不可分割的一部分，中华人民共和国政府是代表全中国的唯一合法政府。这已为联合国大会2758号决议所确认，是国际社会普遍共识。这是历史和法理事实，也是公认的国际关系准则。</p> \n<p cms-style=\"font-L\">　　我外交部发言人林剑此前也在应询时表示，关于中国同巴拉圭关系的问题，中方近期已多次阐述立场。我想强调的是，坚持一个中国原则是国际大义、人心所向、大势所趋，我们希望有关国家领导人顺应历史潮流和人民愿望，早日站到历史正确一边、站到国际社会绝大多数国家一边，做出符合本国根本和长远利益的正确决断。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/33d1-3481e240a2215d60f033af9d032abc89.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4458, NULL, '家长发视频质疑校服质量被拘7天，媒体：执法者违法岂能“罚酒三杯”', 0, 2, 302, '2025-08-13 11:30:35', '2025-08-13 11:04:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/484/w550h734/20250813/0773-7adfebee7b86b9041ed171aa7d3b67d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvenz4228134.shtml', '极目新闻', '<p>　　极目新闻评论员 纪平</p> \n<p>　　2023年12月，甘肃庆阳市宁县盘克镇36岁男子邓建国因在网上反映儿子校服存在质量问题，校服厂商报案后，遭宁县公安局网络安全监察大队以寻衅滋事为由行政拘留7天。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/484/w550h734/20250813/0773-7adfebee7b86b9041ed171aa7d3b67d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: center;\">　　宁县公安局出具的行政处罚决定书（澎湃新闻记者谢寅宗摄）&nbsp;</p> \n<p>　　被拘留后，邓建国精神状态急剧恶化，不仅导致夫妻感情破裂、婚姻解体，还被工作单位辞退，更被诊断出患有抑郁症。2024年1月10日，邓建国向宁县人民政府申请行政复议，却收到维持原处罚的决定；他随后向庆城县人民法院提起行政诉讼，将宁县政府、宁县公安局告上法庭，2024年7月11日其诉讼请求被驳回。不服一审判决的邓建国继续向庆阳市中院提起上诉。</p> \n<p>　　庆阳市中级人民法院二审认定，宁县公安局的行政处罚决定程序违法、认定事实证据不足，依法应予以撤销。但因案涉拘留决定已执行完毕，已无撤销必要，警方需承担7天拘留的国家赔偿3237.08元。（据8月12日澎湃新闻）</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/673/w550h923/20250813/858f-43c4b8853615862e757652ac55d2c78f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: center;\">　　二审判决书（澎湃新闻记者谢寅宗摄）</p> \n<p>　　当下，上网发视频曝光已成为常见维权方式。邓建国或许从未想到，自己仅因质疑校服质量，就被拘留，并从此坠入人生低谷——妻离子散、失业患病，生活彻底陷入混乱。这场或许不够理性的维权，最终付出的代价实在过于沉重。</p> \n<p>　　邓建国人生的剧变，源于宁县公安局的行政处罚决定。但在整个案件处理过程中，宁县相关部门给出的结果和决定，存在诸多可疑之处，甚至前后矛盾，让人对执法公正性产生严重质疑。</p> \n<p>　　首先，宁县公安局以寻衅滋事为由拘留邓建国，但寻衅滋事的定义是行为人在公共场所无事生非、肆意挑衅，实施殴打、辱骂、强占财物或扰乱秩序等行为，破坏社会公共秩序。邓建国在多方沟通未果、维权无门后才上网发视频，且其对校服质量的质疑有一定事实基础，何来破坏社会公共秩序？即便他的维权方式有过激、不当之处，视频中含部分未经证实的信息，也与寻衅滋事毫不相干，庆阳市中院的判决已印证这一点。那么，宁县公安局究竟依据什么作出如此处罚？作出决定的人，是不懂法还是“歪屁股”？</p> \n<p>　　其二，据邓建国所述，警方明知他要申请行政复议，却未告知其可申请暂缓执行，而让他签了相关文书后直接投入拘留所。根据相关法律规定，公安机关作出行政拘留决定时，应明确告知被处罚人享有申请暂缓执行的权利及具体流程。若未履行告知义务，可能导致被处罚人错过申请时限，损害其合法权益。显然，宁县公安局的做法不符合法定流程。如此急切地控制其人身自由，不禁让人怀疑：这是不是为了“解决提出问题的人”？是否存在滥用执法权？</p> \n<p>　　其三，校服质量是否有问题，直接关系到邓建国维权行为的正当性。庆阳市质量计量检验检测中心对涉事厂家生产的夏季校服抽样检测发现，其棉含量不达标，不符合国家标准；庆阳市市场监管局官网消息也显示，在后续专项行动中，包括兆春服装厂在内的校服供应商被查出多项问题。但宁县市场监管局此前的检测结果却称校服符合要求，这是为何？是宁县市监局检测部门技术落后、标准滞后，还是背后另有隐情？</p> \n<p>　　尤为关键的是，庆阳市中院已认定宁县公安局的行政处罚决定程序违法、事实证据不足，可为何仅由宁县公安局赔偿邓建国3237.08元，却看不到任何相关责任人为此担责？邓建国只因关心孩子健康、对校服质量疑点提出质疑，就无端失去7天自由，背负沉重心理枷锁，家庭和事业毁于一旦。这样的判决结果，与其遭受的损失相比，实在不相称。</p> \n<p>　　邓建国的遭遇，暴露出部分基层执法机关在处理民众维权诉求时的傲慢与偏见。为消除影响、捂住舆论，他们似乎更倾向于用执法权打压维权者，对可能存在质量问题的企业却偏听偏信、极力维护。这很难不让人怀疑，背后是否存在利益链条，是否涉及以权谋私。</p> \n<p>　　公平正义是司法的灵魂和生命。当执法者自身凌驾于法律之上，用权力随意碾压民意诉求，损害的不仅是个体权益，更是公众对司法体系的信任。唯有让每一次执法都严守程序、锚定事实，让违法执法者付出应有代价，才能筑牢法治防线，让民众在遭遇不公时敢发声、信法律。</p> \n<p>　　因此，对于执法者的违法行为，处理绝不能轻描淡写、“罚酒三杯”，必须彻查违法处罚的原因，将责任追究落实到人，给蒙冤者和公众一个交代，维护法律的公正与尊严。</p> \n<p>　　（来源：极目新闻）</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/484/w550h734/20250813/0773-7adfebee7b86b9041ed171aa7d3b67d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/673/w550h923/20250813/858f-43c4b8853615862e757652ac55d2c78f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4459, NULL, '教育局通报“给考上清华学生发百万奖金”学校违规，专家：要纠正错误的教育评价', 0, 2, 265, '2025-08-13 11:30:52', '2025-08-13 10:50:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/545/w550h795/20250813/c53c-a82f0b9c8cc9f4206382a3e4e56525a1.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyfk3504113.shtml', '九派新闻', '<p>　　来源：九派新闻</p> \n<p>　　日前，广西贵港一女生考上清华大学，其高中贵港市大将国际学校奖励100万元奖学金，引发网友热议。该校工作人员表示情况属实，奖学金金额依据毕业生录取大学的全国排名而定。此后，贵港市教育局一则内部通报在网络上流出，通报中，贵港市教育局将该校的重金奖励行为定性为违规宣传高考成绩。</p> \n<p>　　8月12日，贵港市教育局一工作人员证实情况属实，本是内部通报，不对外发布，目前已经在自查外传原因。此外，该工作人员解释，“该高级中学的行为是不合规的，从国家层面上来说，是不宣传高考成绩的。我们已经进行了制止。”</p> \n<p>　　同日，贵港市大将国际学校对通报内容回应，称并不清楚。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/545/w550h795/20250813/c53c-a82f0b9c8cc9f4206382a3e4e56525a1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　教育局通报。图/社交平台截图</p> \n<p>　　中国教育发展战略学会学术委员陈志文接受九派新闻采访时表示，最近十几年教育部一直在打击类似做法，核心目的还是纠正错误的教育评价。陈志文同时表示，更应该思考和反问的是，为什么学校甘愿冒着被处罚的风险去做这类违规的事情？</p> \n<p>　　陈志文认为，市场作用背后是被误导的观念，尤其是对优质教育资源的放大。“整个社会对教育的评价，都存在误导，放大了所谓优质教育资源的价值和作用。升学成绩优秀，可能并不是师资的原因，实际上是因为优秀的学生有选择权，他们就进了这些中学。起决定性作用的是优秀的学生，而不是老师。”</p> \n<p>　　陈志文表示，一个绝对优秀的孩子并不是优质教育资源造就的。首先是父母与家庭的因素，其中不仅是遗传的问题，更主要的还是良好的行为习惯的养成。他认为，不能否定优秀的老师在一个人的成长过程中的重要价值，但也不能本末颠倒。面对一个不愿意学习的孩子，缺乏最基本的行为规范的孩子，再优秀的老师也没有意义。</p> \n<p>　　“我想提醒公众，校方之所以敢铤而走险，冒着违规的风险干这件事，是因为市场和老百姓相信这件事，但是这个认知是错误的。这个错误认知不能光批评老百姓，我们教育系统要检讨，过度放大了所谓优质教育资源的决定性影响，在误导家长的同时，也在加剧择校热。”陈志文说。</p> \n<p>　　九派新闻记者 孙沁怡</p> \n<p>　　编辑 万璇 任卓</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/545/w550h795/20250813/c53c-a82f0b9c8cc9f4206382a3e4e56525a1.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4460, NULL, '生二孩最高奖补28.71万，生三孩最高奖补35.59万！湖北一地宣布', 0, 1, 17, '2025-08-13 11:30:58', '2025-08-13 10:48:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/765/w550h215/20250813/662d-502cde908e8de6389968d4876a9676ba.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyfp1157061.shtml', '中国新闻网', '<p cms-style=\"font-L\">　　据“湖北发布”微信公众号消息，近日，天门市有网友发帖分享，她于2024年5月生下二胎后，出院时领取了2300元住院补贴，今年6月又收到4200元产假补助，每月还能领取800元育儿补贴，购房时更获得6万元补贴。该网友表示，政策实实在在减轻了家庭负担。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/765/w550h215/20250813/662d-502cde908e8de6389968d4876a9676ba.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　8月12日，记者电话咨询天门市卫生健康委员会，工作人员介绍，政策规定：二孩家庭可获2300元一次性奖励，每月800元育儿补贴发放至孩子3岁；三孩家庭则有3300元一次性补贴和每月1000元育儿补贴。此外，生育二孩、三孩家庭分别可享6万、12万元购房补贴。同时，医院为二孩家庭提供建档产检、四维B超、胎儿心脏彩超等免费服务。根据上述政策，二孩家庭累计最高可享受价值约287188元的奖励、补贴及免费服务，三孩家庭累计最高可享受价值约355988元的奖励、补贴及免费服务。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/144/w550h394/20250813/4b05-e0d5891325c16752bdce43f64671cd12.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　2024年，天门市出生人口同比增长17%，8年来首次“由降转增”；今年延续向好态势，上半年出生人口同比增长5.6%。</p> \n<p cms-style=\"font-L\">　　为推动政策落地，天门市2024年至2026年投入3亿多元用于鼓励生育。该政策适用于2024年4月1日以后生育二孩或三孩的家庭，截止时间为2027年5月1日。</p> \n<p cms-style=\"font-L\">　　天门市第一人民医院工作人员证实：“鼓励生育政策出台后，生二胎、三胎的人数明显增多。”</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/624/w550h74/20250813/e54a-deeb924f5f229dae77eb7a40cb6726d5.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">原标题：《</font><font cms-style=\"font-L\">湖北一地生二孩最高奖补28.71万，生三孩最高奖补35.59万</font><font cms-style=\"font-L\">》</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L align-Center\">编辑：韩娇娇</font></p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/765/w550h215/20250813/662d-502cde908e8de6389968d4876a9676ba.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/144/w550h394/20250813/4b05-e0d5891325c16752bdce43f64671cd12.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/624/w550h74/20250813/e54a-deeb924f5f229dae77eb7a40cb6726d5.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4461, NULL, '国台办：民进党当局在关税谈判上“未谈先跪”、“打左脸送右脸”', 0, 1, 34, '2025-08-13 11:31:10', '2025-08-13 10:45:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkuyfk3502071.shtml', '人民日报客户端', '<p cms-style=\"font-L\">　　8月13日，国务院台办举行例行新闻发布会，发言人朱凤莲答记者问。</p> \n<p cms-style=\"font-L\">　　有记者问，美国总统特朗普日前受访称，将对半导体等进口商品征收100%关税，并称台积电将在美投资3000亿美元，在亚利桑那州建立全世界最大晶圆厂。对此有何评论？</p> \n<p cms-style=\"font-L\">　　朱凤莲表示，此前，台积电被迫宣布在美加码投资1000亿美元时，已使岛内业界恐慌、民怨沸腾。此次3000亿美元投资一旦落地，势必对台湾经济造成巨大影响，台湾经济的发展动能和自主性将被进一步削弱。如果说美国是掏空台湾产业的始作俑者，那么民进党当局就是最大的帮凶。他们在关税谈判上“未谈先跪”、“打左脸送右脸”，对谈判过程讳莫如深，甚至对民众一骗再骗；在产业上对美国予取予求，主动奉送台积电，任其榨干台湾优势产业价值，充分说明民进党当局根本无心也无力维护台湾经济发展和民众福祉。奉劝民进党当局在“媚美卖台”的邪路上及时悬崖勒马，台湾民众和各界有识之士应当团结起来，积极维护自身利益。(程龙)</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4462, NULL, '韩国多地出现反华集会，李在明：有损国家形象，应彻底采取措施', 0, 4, 105, '2025-08-13 12:30:15', '2025-08-13 11:39:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/128/w550h378/20250813/94d1-143a2cd5fcac989d8b1449fe9d7fc76c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvepc8003639.shtml', '观察者网', '<p cms-style=\"font-L\">　　据《韩民族日报》、韩联社消息，针对近期韩国内反华示威游行及歧视外国人事件频发，韩国总统李在明当地时间12日指出，类似事件有损韩国国家形象，要彻底采取必要措施，防止再次发生。</p> \n<p cms-style=\"font-L\">　　当天，李在明在首尔主持召开国务会议。在开场讲话中，李在明提到，“近期，针对外国人或社会弱势群体的仇恨、歧视和暴力事件似乎频频发生。”针对韩国多地近期出现反华集会，李在明批评道，“这是超越了言论自由的界限、充斥着辱骂与暴力的仇恨示威。”</p> \n<p cms-style=\"font-L\">　　“希望大家思考一下，当其他国家看到这样的场面时，会如何看待大韩民国”，他补充道，“这种行为与韩国作为重视多样性和包容性的民主国家的地位，完全不相称”。</p> \n<p cms-style=\"font-L\">　　李在明还特别向有关部门强调道，“如有必要，请制定制度性的补充对策。”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/128/w550h378/20250813/94d1-143a2cd5fcac989d8b1449fe9d7fc76c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间8月12日，李在明在国务会议上讲话\">\n <span class=\"img_descr\">当地时间8月12日，李在明在国务会议上讲话</span>\n <font cms-style=\"font-L\"> 韩联社</font>\n</div> \n<p cms-style=\"font-L\">　　此前，中国驻韩国大使馆于7月9日发文提醒在（来）韩中国公民加强安全防范。</p> \n<p cms-style=\"font-L\">　　我使馆指出，近期，韩国顺利举行总统选举，中方对此表示祝贺，祝愿韩国实现稳定、发展、繁荣。中韩双方各领域交流合作也在增加，这符合两国人民的共同利益。遗憾的是，韩国个别政治势力捏造所谓“中国干涉韩国大选”，对中国进行指责抹黑，中方坚决反对。一些人近期在中国游客集中的首尔明洞等地区举行反华集会游行，不排除个别人员采取过激行为。中国驻韩国大使馆已向韩方提出严正交涉，要求韩方采取措施保证中国公民人身安全。</p> \n<p cms-style=\"font-L\">　　中国驻韩国大使馆还提醒道，在韩中国公民和来韩中国游客应密切关注韩国当地形势和治安状况，增强自我保护意识；了解和遵守韩国法律法规，关注韩国警方发布的政治性集会游行信息，主动同其保持距离；切实加强安全防范，遇到意外情况保持冷静，及时报警并注意收集、保存证据，尽量避免发生言语或肢体冲突，确保自身安全，必要时通过法律手段应对。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/128/w550h378/20250813/94d1-143a2cd5fcac989d8b1449fe9d7fc76c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4463, NULL, '民进党当局称调查16家大陆公司 国台办：对美唯唯诺诺 破坏两岸经济合作动作频频', 0, 1, 34, '2025-08-13 12:30:34', '2025-08-13 11:58:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkvepc8015608.shtml', '央视', '<p cms-style=\"font-L\">　　8月13日，国务院台办举行例行新闻发布会。有记者问：民进党当局称，正在调查16家大陆公司，涉嫌未经当局批准在台非法招聘工程师和无证经营办公室。对此有何评论？</p> \n<p cms-style=\"font-L\">　　发言人朱凤莲表示，民进党当局心中只有一党私利，他们<font cms-style=\"font-L strong-Bold\">在关税谈判上对美国唯唯诺诺、予取予求，不关心岛内企业面对高昂的关税如何生存、不花力气研究如何应对关税霸凌</font>，却在推动两岸“脱钩断链”、破坏两岸经济合作上处心积虑、动作频频。这些出于政治私利的做法不得人心，只会损害台湾营商环境，限缩台湾经济发展空间。</p> \n<p cms-style=\"font-L\">　　（总台央视记者 赵超逸 黄惠馨）</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4464, NULL, '南昌景区持剪刀致1死1伤男子有精神病史，死者朋友：她马上读大二', 0, 2, 120, '2025-08-13 12:30:46', '2025-08-12 22:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250812/795/w690h905/20250812/5ccf-04ff0fd0eccc9fb6522dfd06f931a88c.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infktwtw3988757.shtml', '极目新闻', '<p cms-style=\"font-L\">　　极目新闻记者 郭奕</p> \n<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p cms-style=\"font-L\">　　8月12日，多位网友爆料称，江西南昌一景区发生了一起伤人事件，致1人死亡、1人受伤。</p> \n<p cms-style=\"font-L\">　　12日下午，南昌警方就此事发布警情通报称，8月10日，南昌市青云谱区青云谱路发生一起伤人案件。经初步调查，当日13时40分左右，犯罪嫌疑人席某某（男，23岁，江西高安人，有精神疾病诊疗史）持剪刀对刘某某和施某进行伤害，造成刘某某经抢救无效死亡，施某经送医救治，无生命危险。目前，席某某已被刑事拘留，案件正在进一步侦办中。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250812/795/w690h905/20250812/5ccf-04ff0fd0eccc9fb6522dfd06f931a88c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　12日晚，刘某某的朋友告诉极目新闻记者，她是通过网帖得知刘某某离世的消息，刘某某是一个很好的女孩，学习成绩也很好，开学后将读大二。</p> \n<p cms-style=\"font-L\">　　另有一位刘某某的同学告诉极目新闻记者，目前家属正和警方沟通处理，具体细节不便透露。</p> \n<p cms-style=\"font-L\">　　截至发稿，极目新闻记者多次拨打涉事景区电话，均无人接听。</p> \n<p cms-style=\"font-L\">　　针对此案涉及的法律问题，河南泽槿律师事务所主任付建认为，若经法定程序鉴定确认，如果席某某确实为精神病人，且行凶时完全不能控制和辨认自己的行为，属于无行为能力人，不负刑事责任；如果尚未完全丧失辨认或控制自己行为能力，依据刑法规定，应当负刑事责任，但可从轻或减轻处罚；如果是间歇性精神病人，且在精神正常时实施犯罪行为，应当负刑事责任，按照正常量刑标准处罚。应当由专业的精神科医生通过详细的精神检查、心理测评等手段，依据相关诊断标准进行鉴定，确定席某某是否处于发作期以及精神状态对辨认和控制自己行为能力的影响程度 。</p> \n<p cms-style=\"font-L\">　　根据《民法典》第一千一百八十八条规定，无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。有财产的无民事行为能力人、限制民事行为能力人造成他人损害的，从本人财产中支付赔偿费用；不足部分，由监护人赔偿。因此，若该男子为无民事行为能力人或限制民事行为能力人，其家属或监护人需承担民事赔偿责任，赔偿范围包括医疗费、护理费、丧葬费、死亡赔偿金等。即使男子是完全刑事责任能力人，若其财产不足以赔偿受害者，家属或监护人在有能力的情况下，也可能会被要求协助赔偿。此外，家属或监护人还负有对男子严加看管和医疗的责任，防止其再次对社会造成危害。</p> \n<p cms-style=\"font-L\">　　如果构成犯罪的，受害者家属可以在刑事诉讼过程中，提起刑事附带民事诉讼，要求犯罪嫌疑人及其家属承担民事赔偿责任。赔偿范围通常包括医疗费、误工费、护理费、交通费、住宿费、住院伙食补助费、必要的营养费被扶养人生活费等死者家属可以主张丧葬费、死亡赔偿金以及受害者家属的精神损害抚慰金等。</p> \n<p cms-style=\"font-L\">　　<strong>相关新闻</strong></p> \n<p>　　<a href=\"https://news.sina.cn/gn/2025-08-13/detail-infkutxf4387031.d.html\" target=\"_blank\" data-comos-dataid=\"comos:nfkutxf4387031\">景区遇害女生，系外交学院大一学生</a></p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/spider20250812/795/w690h905/20250812/5ccf-04ff0fd0eccc9fb6522dfd06f931a88c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4465, NULL, '美媒：为避免与美国产生矛盾，意大利政府计划限制中企在当地企业持股', 0, 4, 96, '2025-08-13 13:30:18', '2025-08-13 12:34:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/6e0c-8f602e2c5565c204c82b3df6e776da08.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvepm1063573.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 熊超然】当地时间8月12日，彭博社援引知情人士透露，梅洛尼政府正考虑限制中国投资者在意大利主要公司的持股，措施将涉及那些被认为具有战略意义的公司，包括私营和国有控股公司，以避免与美国产生潜在的紧张关系。</p> \n<p cms-style=\"font-L\">　　这名不愿透露姓名的知情人士称，轮胎制造商倍耐力公司是梅洛尼政府这一计划中最引人关注的例子之一。中国国有企业中化集团持有倍耐力公司37%的股份，而由于中资控股，作为世界一级方程式赛车（F1）专属轮胎供应商的倍耐力，正面临在美国的潜在销售限制，该公司已试图削弱中国投资者的治理权限。</p> \n<p cms-style=\"font-L\">　　知情人士透露，尽管中化集团强调其对倍耐力的持股属长期投资，但意大利政府正在评估施压中化集团出售股权的方案。</p> \n<p cms-style=\"font-L\">　　另据其他知情人士透露，倍耐力只是计划中的“最极端案例之一”，意大利政府还希望将中国投资者从CDP Reti SpA电网控股公司排除出去。知情人士称，CDP Reti SpA持有意大利能源网络的控股权，其中35%的股份由中国国家电网公司持有，该公司有两名董事可以影响决策。</p> \n<p cms-style=\"font-L\">　　另一家企业Ansaldo Energia SpA，则是全球最大的发电设备制造商之一。知情人士称，即使上海电气当前已将其持股比例从40%降至0.5%，但中资背景仍然阻碍其参与美国的一些电力项目的招标和投标。</p> \n<p cms-style=\"font-L\">　　8月11日，中国外交部发言人林剑对此表示，中意投资合作互利互惠，从不针对第三方，也不应受到第三方干扰。中国政府一贯支持中国企业在市场化原则基础上开展国际合作，希望意方为中国企业提供公平、公正、非歧视的营商环境，切实保障企业的合法权益。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/6e0c-8f602e2c5565c204c82b3df6e776da08.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"当地时间2025年7月24日，2025年F1比利时大奖赛，各支车队使用的倍耐力轮胎。\">\n <span class=\"img_descr\">当地时间2025年7月24日，2025年F1比利时大奖赛，各支车队使用的倍耐力轮胎。</span>\n <font cms-style=\"font-L\"> 视觉中国</font>\n</div> \n<p cms-style=\"font-L\">　　此前，美方已经警告倍耐力，宣称由于担心数据被收集，正严厉打击中国控股的联网汽车公司提供的软件和硬件，倍耐力在其关键市场——美国，可能受到限制。</p> \n<p cms-style=\"font-L\">　　后来，意大利政府“下黑手”，动用了所谓的“黄金权力规则”（golden power rule），这项法律手段赋予政府保护银行、能源等“对国家利益具有重要战略意义的资产”相关行业的特殊权力，免于落入非欧盟成员实体手中。意大利于2012年首次通过这一法案，后因“疫情揭露的供应链问题”，于2022年3月大幅扩大其涵盖的行业范围。</p> \n<p cms-style=\"font-L\">　　2023年，意大利政府利用该机制，限制了中化集团在倍耐力的影响力，并通过“具体条款”保护网络传感器等技术。随后，今年4月，应意大利监管机构的要求，倍耐力董事会下调了中化集团的治理评级，宣布这家中企不再拥有对倍耐力的控制权。</p> \n<p cms-style=\"font-L\">　　值得注意的是，截至2023年6月，意大利此前已经七次动用“黄金权力规则”阻止外国在意交易案，其中有六次交易来自中国。</p> \n<p cms-style=\"font-L\">　　对于彭博社这一最新报道，目前意大利政府、倍耐力、CDP Reti SpA和Ansaldo Energia SpA，以及中化集团驻意大利的代表均拒绝置评。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/ef08-368adaae895f23747ee0382248583ae5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"2024年7月29日，中国北京，“传奇之旅：马可·波罗与丝绸之路上的世界”展览开幕，意大利总理梅洛尼出席开幕式并致辞。 视觉中国\">\n <span class=\"img_descr\">2024年7月29日，中国北京，“传奇之旅：马可·波罗与丝绸之路上的世界”展览开幕，意大利总理梅洛尼出席开幕式并致辞。<font cms-style=\"font-L\"> 视觉中国</font></span>\n</div> \n<p cms-style=\"font-L\">　　彭博社指出，倍耐力的案例突显出欧洲在应对新的地缘政治格局时所面临的挑战。2008年金融危机后，欧洲曾热情欢迎中国投资者，但如今，该地区既要保护关键行业，又要与美国总统特朗普站在同一阵线。同时，意大利总理梅洛尼也试图努力在中美之间寻找平衡，欧洲也正寻求中国投资，尤其是在绿色发展项目方面，以对抗特朗普的关税威胁。</p> \n<p cms-style=\"font-L\">　　“自特朗普当选以来，跨大西洋关系的不确定性日益加剧，许多欧盟国家的政府开始重新考虑中国作为贸易伙伴的角色，”意大利前政府官员、政治风险咨询公司Highground负责人贝尼亚米诺·伊尔迪（Beniamino Irdi）表示：“但这种平衡正变得越来越难以把握。”</p> \n<p cms-style=\"font-L\">　　彭博社称，此前，意大利方面曾退出和中方合作的机制，自那以后，意方花了很长一段时间来修复两国关系，意大利总理梅洛尼更是在去年7月底访问中国。当时，梅洛尼表示，她为期五天的访华行程“展示了开启新阶段、重启双边合作的意愿”。她说，意大利与中国签署了一项为期三年的行动计划，以落实过去的协议并探索新的合作形式。</p> \n<p cms-style=\"font-L\">　　如今，对于有关梅洛尼政府计划对中企“下黑手”的报道，有意大利官员再度对意中关系感到担忧。目前，意大利是中国在欧盟的第四大贸易伙伴，中国是意大利在亚洲的第一大贸易伙伴。</p> \n<p cms-style=\"font-L\">　　知情人士透露，有中国外交官已警告称，如果中意双方未能就倍耐力问题达成一致，两国贸易关系可能会受到冲击。</p> \n<p cms-style=\"font-L\">　　去年梅洛尼访华时，中国外交部发言人毛宁就曾指出，中国和意大利同为文明古国，是全面战略伙伴，两国高层保持密切互动，各领域互利合作取得务实成果。中意关系健康稳定发展，符合两国和两国人民共同利益，有利于促进不同文明交流互鉴。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/6e0c-8f602e2c5565c204c82b3df6e776da08.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/ef08-368adaae895f23747ee0382248583ae5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4466, NULL, '“金穹”PPT被曝：要胸怀大志，先搞它个四层…但基本架构尚未确定', 0, 4, 207, '2025-08-13 13:30:25', '2025-08-13 12:34:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/8062-20aa6d7ef4f5fe08fb21cba06cfa82ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvepm1063610.shtml', '观察者网', '<p cms-style=\"font-L\">　　【文/观察者网 阮佳琪】</p> \n<p cms-style=\"font-L\">　　今年上任后不久，美国总统特朗普便宣布了名为“金穹”（Golden Dome）的导弹防御系统发展规划，旨在构建一个卫星网络，用于探测、追踪并拦截来袭导弹。该系统据称要在未来3年内建成。</p> \n<p cms-style=\"font-L\">　　据英媒路透社13日独家爆料称，一份美国政府关于该项目的幻灯片（PPT）显示，“金穹”将包括四层系统，一层基于卫星，三层部署在陆地。其中11个短程导弹发射装置将分布于美国本土、阿拉斯加和夏威夷岛。</p> \n<p cms-style=\"font-L\">　　据报道，上周在阿拉巴马州亨茨维尔，3000多家国防承包商观看了这份标为“快速行动，胸怀大志！”（Go Fast, Think Big！）的PPT。其中称，“金穹”的系统架构由四个集成层组成：一个天基传感和目标瞄准层，用于导弹预警与跟踪以及“导弹防御”；三个陆基层，包含导弹拦截器、雷达阵列，还可能配备激光武器。</p> \n<p cms-style=\"font-L\">　　路透社报道称，令人感到“意外”的是，PPT展示的地图上似乎显示，美军计划在中西部新建一个大型导弹发射场，用于部署美国洛克希德·马丁公司研发的下一代拦截器（NGI），并将与同样由洛克希德公司制造的萨德反导系统（THAAD）和“宙斯盾”作战系统一起构成所谓“上层防御”。</p> \n<p cms-style=\"font-L\">　　NGI项目作为美国防部“利用初始防线应对远程弹道导弹威胁”计划的一部分，旨在为美军“陆基中段防御系统”（GMD）研发一种新型本土防御陆基拦截弹，通过新型助推器携带多目标杀伤武器，为提升美国国土防御能力提供支持。</p> \n<p cms-style=\"font-L\">　　美国在加利福尼亚州南部和阿拉斯加州已经设有GMD发射场。PPT显示，“金穹”还计划在中西部新增第三个发射场。</p> \n<p cms-style=\"font-L\">　　据报道，被称为“下层”和“有限区域防御”的最后一道防线，还将包括新型雷达和现有系统，比如“爱国者”反导系统与一款新型“通用”发射器的组合，可以发射现有和未来的拦截器，以应对所有类型的威胁。报道称，这些模块化且可重新部署的系统旨在减少对预设场地的依赖，以便在多个战区快速部署。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/8062-20aa6d7ef4f5fe08fb21cba06cfa82ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"5月20日，特朗普在白宫宣布建造“金穹”\">\n <span class=\"img_descr\">5月20日，特朗普在白宫宣布建造“金穹” </span>\n <font cms-style=\"font-L\">视觉中国</font>\n</div> \n<p cms-style=\"font-L\">　　PPT中指出的其他技术难题，包括整个“杀伤链”上的通信延迟问题。洛克希德、诺斯罗普·格鲁曼、雷神技术和波音等承包商能够提供多种导弹防御系统，但协调这些系统之间的通信是关键瓶颈。</p> \n<p cms-style=\"font-L\">　　此外，PPT还称，“金穹”寻求开发具备助推段拦截能力的天基拦截器。美国虽然“已经造出了拦截器和再入飞行器”，但从未制造出能够在瞄准敌方导弹的同时承受再入大气层热量的飞行器。</p> \n<p cms-style=\"font-L\">　　值得一提的是，这份PPT没有提及马斯克的SpaceX。美媒4月曾报道称，该公司与美国“新军工”企业代表帕兰蒂尔、安杜里尔联合竞标‘金穹’合同。马斯克曾对此回应称，SpaceX“并未尝试竞标任何相关合同，我们更希望专注于将人类送往火星”。</p> \n<p cms-style=\"font-L\">　　6月“特马联盟”公开交恶、彻底决裂后，又有消息称，特朗普政府致力于摆脱美国军事通信对SpaceX的依赖，正在扩大寻找合作伙伴以建设“金穹”系统，吸引亚马逊和大型国防承包商参与。</p> \n<p cms-style=\"font-L\">　　其中两名消息人士透露，早在特朗普与马斯克闹翻前，美国国防部和白宫官员就已开始探索SpaceX的替代方案，担心在耗资1750亿美元的“金穹”系统中过于依赖单一伙伴。</p> \n<p cms-style=\"font-L\">　　不过，这份PPT显示，该项目的基本架构仍存在不确定性，系统所需的发射器、拦截器、地面站和导弹发射场的数量都尚未确定。一名美国官员对路透社说，“他们资金雄厚，但还没有确定成本目标。”</p> \n<p cms-style=\"font-L\">　　五角大楼则声称，其正在“从业界、学术界、国家实验室和其他政府机构收集信息以支持‘金穹’计划”，但在项目的早期阶段就公布更多信息是“不明智的”。</p> \n<p cms-style=\"font-L\">　　当地时间5月20日，特朗普在白宫宣布，他已经为“金穹”系统选定了一个设计方案，并任命美国太空军将军迈克尔·盖特莱恩担任这项计划的首席项目经理。美媒报道当时声称，这项计划被广泛视为特朗普军事计划的“基石”，旨在阻止所谓“来自中国和俄罗斯的威胁”。</p> \n<p cms-style=\"font-L\">　　两天后（22日），美国太空司令部司令史蒂芬·怀廷便在芝加哥一个论坛上添油加醋。他渲染称，中国构成的所谓“太空威胁”越来越“真实且紧迫”，“金穹”就是对这一所谓威胁的回应。</p> \n<p cms-style=\"font-L\">　　7月17日，盖特莱恩获得国会参议院确认，将领导该项目并拥有广泛权限。两名知情人士透露，根据国防部长赫格塞思此前指令，盖特莱恩在确认后有30天组建团队，60天提交初始系统设计，120天提交包括卫星和地面站细节的完整实施计划。</p> \n<p cms-style=\"font-L\">　　一旦“金穹”计划得以落实，美国将首次在太空部署武器。正如美国康奈尔大学法学教授迈克尔·多尔夫（Michael C. Dorf）所说的那样：“‘金穹’会是‘星球大战’最最糟糕的续集（Golden Dome is the Worst Star Wars Sequel Ever）。”</p> \n<p cms-style=\"font-L\">　　中国外交部发言人毛宁此前回应称，所谓“金色穹顶”计划旨在构建不受任何约束的全球性、多层次、多领域导弹防御系统，该计划公然提出大幅增加外空作战手段，包括研发、部署轨道拦截系统，具有浓厚的进攻性色彩。违反外空条约倡导的和平利用原则，将加剧外空战场化和军备竞赛风险、动摇国际安全与军用体系。</p> \n<p cms-style=\"font-L\">　　毛宁称，美国奉行“本国优先”，执迷于谋求自身绝对安全，违反各国安全不受减损的原则，损害全球的战略平衡和稳定，中方对此严重关切，我们敦促美方尽早放弃发展和部署全球反导系统，以实际行动增进大国战略互信，维护全球战略稳定。</p> \n<p cms-style=\"font-L\">　　国防部新闻发言人张晓刚大校也指出，美国推进部署“金穹”等天基武器系统，持续扩张外空军力，挑动外空军备竞赛。这违反《外空条约》相关原则，加剧外空战场化和军备竞赛风险，动摇国际安全与军控体系，犹如又一次打开潘多拉魔盒。这也再次证明，美国是外空武器化战场化的最大推手。我们敦促美方停止在外空扩军备战，以实际行动维护全球战略稳定。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/8062-20aa6d7ef4f5fe08fb21cba06cfa82ee.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4467, NULL, '今年第11号台风“杨柳”在台湾台东县太麻里乡沿海登陆', 0, 1, 34, '2025-08-13 13:30:39', '2025-08-13 13:08:00', NULL, NULL, 'https://n.sinaimg.cn/news/gif_image/362/w640h522/20250813/44c3-gifc8439e44c075c8c4e238ab67ec95d5f6.gif', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvepc8032530.shtml', '央视新闻客户端', '<p cms-style=\"font-L\">　　今年第11号台风“杨柳”（强台风级）的中心已于今天（8月13日）13时前后在台湾台东县太麻里乡沿海登陆，登陆时中心附近最大风力14级（42米/秒），中心最低气压955百帕。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"//n.sinaimg.cn/news/gif_image/362/w640h522/20250813/44c3-gifc8439e44c075c8c4e238ab67ec95d5f6.gif\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　台风“杨柳”还将于今天夜间至明天（14日）凌晨在福建厦门到广东汕头一带沿海再次登陆（强热带风暴级或台风级，25至33米/秒，10至12级），请相关区域共同做好防范。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/72/w550h5122/20250813/4124-f10d4bc823168147c5faceadd27f4710.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　（总台央视记者 刘璐璐 刘丹）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1755001953\" target=\"_blank\">台风“杨柳”来袭</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://n.sinaimg.cn/news/gif_image/362/w640h522/20250813/44c3-gifc8439e44c075c8c4e238ab67ec95d5f6.gif\",\"https://k.sinaimg.cn/n/news/crawl/72/w550h5122/20250813/4124-f10d4bc823168147c5faceadd27f4710.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4468, NULL, '吉林一地早中晚高峰禁止老年人免费乘车？交通局：通知已取消', 0, 1, 7, '2025-08-13 13:30:43', '2025-08-13 12:53:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/91/w417h474/20250813/66ad-166b419187f1d3a6c4da94d858843621.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvenz4265921.shtml', '楚天都市报', '<p cms-style=\"font-L\">　　极目新闻记者 张皓</p> \n<p cms-style=\"font-L\">　　有网友日前发布吉林省德惠市“免费老年卡错峰出行”的通知，通知提到，因早晚高峰时间段公共交通拥挤，无法保证上学、通勤人群的刚性出行需求等，从9月1日起对免费乘车的老年卡实行限时乘车。限乘分为三个时段，分别为上午5:50-8:00、中午11:00-13:00、下午16:00-17:50。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/91/w417h474/20250813/66ad-166b419187f1d3a6c4da94d858843621.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"通知截图\">\n <span class=\"img_descr\">　　通知截图</span>\n</div> \n<p cms-style=\"font-L\">　　据齐鲁晚报8月12日报道，德惠市瑞祥公共交通有限责任公司工作人员证实，此通知确实为官方通知。“有些老人一大早会去早市，有时候孩子都上不去车，这些措施是为了把孩子上学和上班的高峰错过去。”该工作人员说，本市的老年免费卡是指年龄为65周岁及以上的老年人所持乘车卡。</p> \n<p cms-style=\"font-L\">　　8月13日上午，极目新闻记者致电上述公司，询问有没有考虑高峰时段增加运力以满足所有市民需求，<font cms-style=\"font-L\">工作人员表示，她得到的最新情况是，目前已经暂缓实行老年人限时乘车，在车上已经张贴了最新的通知，其他情况需要联系公司办公室咨询，不过记者多次拨打其提供的办公室电话，暂无人接听。</font></p> \n<p cms-style=\"font-L\">　　德惠市交通运输局两名工作人员告诉极目新闻记者，目前上述公交公司已经取消了老年人限时乘车的通知。记者询问此前通知是否向政府主管部门报备，其中一名工作人员称，他问了运输科的同事，说不知道此前的通知。</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/91/w417h474/20250813/66ad-166b419187f1d3a6c4da94d858843621.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4469, NULL, '东北首座万亿城市，只差“临门一脚”？', 0, 2, 36, '2025-08-13 13:30:48', '2025-08-13 12:31:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4848-8bbfc8a4832cb88f9f7f78c474dee868.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvepm1064420.shtml', '中国新闻周刊', '<p cms-style=\"font-L\">　　来源：中国新闻周刊</p> \n<p cms-style=\"font-L\">　　大连距离“GDP万亿俱乐部”似乎仅一步之遥。</p> \n<p cms-style=\"font-L\">　　近日，大连市政府新闻办公室举行新闻发布会，介绍2025年上半年全市经济运行情况。上半年，大连地区生产总值（GDP）4647.0亿元，按可比价格计算，同比增长6.0%，分别高于全国、全省0.7个、1.3个百分点。</p> \n<p cms-style=\"font-L\">　　2024年，大连GDP为9516.9亿元，按照目前增速，距离万亿“GDP万亿俱乐部”只差“临门一脚”。今年，大连在多个重要会议上多次强调“高质量冲刺万亿GDP城市”。</p> \n<p cms-style=\"font-L\">　　在不少业内人士看来，“GDP万亿俱乐部”是衡量区域经济发展的关键指标，代表城市经济综合实力和财富积累达到新阶段。</p> \n<p cms-style=\"font-L\">　　根据各地发布的数据，当前全国共有27座城市GDP超过1万亿元。从具体区域分布看，长三角地区数量最多，共有上海、苏州、南京等9城，珠三角地区有深圳、广州、佛山、东莞等4城，中西部地区有重庆、成都、武汉等城市，而东北地区目前尚未实现“零的突破”。</p> \n<p cms-style=\"font-L\">　　作为东北经济第一城，大连能否成为东北首个万亿之城，引发了业内较大关注。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">今年有望突破万亿</font></p> \n<p cms-style=\"font-L\">　　辽宁大学二级教授、辽宁社会科学院原副院长梁启东在接受中国新闻周刊采访时表示，他对大连2025年GDP突破万亿元持乐观态度，“从当前来看，这一目标在今年实现的可能性很大”。&nbsp;</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4848-8bbfc8a4832cb88f9f7f78c474dee868.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"大连城市风光。图/图虫创意\">\n <span class=\"img_descr\">　　大连城市风光。图/图虫创意</span>\n</div> \n<p cms-style=\"font-L\">　　2024年年底，国务院正式批复《大连市国土空间总体规划（2021—2035年）》，明确大连的城市性质为“沿海重要的中心城市，现代海洋城市，国际性综合交通枢纽城市”，核心功能定位是“东北亚国际航运中心、国际物流中心、东北先进制造业基地、国际滨海旅游目的地”。</p> \n<p cms-style=\"font-L\">　　梁启东分析认为，近年来大连的发展呈现以下几个特点：一是城市定位更加明确，发展方向持续聚焦；二是港口经济优势不断强化，区域竞争力显著提升；三是产业转型升级成效突出，发展动能持续增强。</p> \n<p cms-style=\"font-L\">　　具体来看，梁启东表示，大连通过持续强化国际化航运功能，积极拓展商贸、物流、金融等中心功能，形成了较强的辐射带动效应。作为东北沿海龙头城市，大连充分利用区位优势，实施海陆联动和沿海腹地融合发展战略，有效整合港口资源与内陆经济，进一步巩固了区域竞争优势。在产业发展方面，大连招商引资工作取得重大突破，尤其是石化产业转型升级成效显著，不仅推动了大连石化产业规模扩大和结构优化，也为城市经济高质量发展注入了强劲动能。</p> \n<p cms-style=\"font-L\">　　西南交通大学经济管理学院讲师王波对中国新闻周刊表示，面对东北老工业基地转型阵痛，大连近年来聚焦高端装备制造、石油化工、软件和信息技术服务等产业，培育出恒力石化、大连船舶重工、中车大连机车等一批具有全球竞争力的企业。数据显示，2024年大连高技术制造业增加值同比增长11%，高于全市规上工业平均水平3.4个百分点，连续21个月保持两位数增长，战略性新兴产业增加值占GDP比重达14%，为冲刺万亿GDP提供了可持续的支撑。&nbsp;</p> \n<p cms-style=\"font-L\">　　在国际航运中心建设方面，大连也取得了突破性进展。2024年，大连港集装箱码头新开通4条外贸集装箱航线，其中“大连—南美”“大连—印度”“大连—墨西哥”3条外贸干线，有效填补了东北地区与南美、南亚地区的直航服务空白。2024年，大连港集装箱码头集装箱吞吐量突破500万标准箱大关，创近5年新高；2025年，大连港集装箱码头开通了大连港直航欧洲、地中海的集装箱新航线，同时，升级了大连港直航中南美洲的航线。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/3057-8aa13643e298add279835a3ec7cec880.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"大连港集装箱码头。图/图虫创意\">\n <span class=\"img_descr\">　　大连港集装箱码头。图/图虫创意</span>\n</div> \n<p cms-style=\"font-L\">　　王波认为，大连正在将地理区位优势转化为资源配置能力。2024年大连实际利用外资18.35亿美元，占辽宁全省比重达59.8%。他说，这种高水平开放带来的要素集聚效应，成为大连GDP突破万亿的重要助推力。</p> \n<p cms-style=\"font-L\">　　最新数据显示，2025年上半年大连经济呈现强劲增长态势：规上工业增加值同比增长12.5%，比上年同期提高7.8个百分点。从重点行业看，装备制造业增长16.9%，其中铁路船舶行业增长52.3%；高技术制造业增长20.1%，持续保持两位数增长。</p> \n<p cms-style=\"font-L\">　　今年上半年，大连市投资规模持续扩大，全市固定资产投资同比增长1.2%；制造业投资同比增长12.8%。上半年，全社会用电量244.6亿千瓦时，同比增长2.7%，比一季度提高2.2个百分点。</p> \n<p cms-style=\"font-L\">　　因此，在不少业内人士看来，按照这个态势发展，大连GDP有望在2025年年底突破万亿元。</p> \n<p cms-style=\"font-L\">　　然而，对于万亿GDP目标，梁启东指出：“9500亿和万亿的实际差距并不大，更多是一个象征性门槛。虽然这意味着东北地区首次有城市进入全国‘GDP万亿俱乐部’，但这500多亿的差距带来的实质变化有限，需要理性看待。”</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">石化产业是最大变量</font></p> \n<p cms-style=\"font-L\">　　中国宏观经济研究院决策咨询部战略政策处研究员卢伟在接受中国新闻周刊采访时表示，近年来大连区域发展态势良好，在经济增长、产业升级、对外开放等方面取得了显著成效，但也面临着一些挑战。</p> \n<p cms-style=\"font-L\">　　卢伟指出，大连地理位置优越、产业基础较好、开放平台众多，有利于货物、资金、技术等资源的集聚和辐射，具备承接和配置各类资源的产业支撑能力，能够吸引相关产业链上下游资源向大连集聚，自贸试验区、国家级新区等开放平台有利于吸引国际高端资源要素，提升资源配置的效率和扩大资源范围。但与国际先进的资源配置枢纽相比，大连在高端航运服务、金融服务、中介服务、人才集聚等方面仍存在差距。</p> \n<p cms-style=\"font-L\">　　多位受访专家在接受中国新闻周刊采访时指出，即便大连迈入“万亿GDP俱乐部”，科技创新能力不足、县域经济支撑减弱、产业结构失衡、外部竞争加剧等问题仍然是制约大连高质量发展的重要瓶颈。</p> \n<p cms-style=\"font-L\">　　在科技创新方面，梁启东提到，大连独角兽、瞪羚企业等高质量创新主体严重匮乏，在科技创新企业梯队建设方面，全国前1000强科技创新企业榜单中大连企业占比极低，科技创新能力亟待提升。卢伟也表示，尽管大连在科技创新方面取得了一些成绩，但与一线城市相比，在研发投入强度、高端创新人才数量、科技成果转化效率等方面仍存在差距，难以支撑其在全球产业链和创新链中占据高端位置。</p> \n<p cms-style=\"font-L\">　　县域经济发展问题同样值得关注。赛迪方略县域经济研究中心首席研究员杨文学在接受中国新闻周刊采访时指出，2012—2024年，县域GDP占大连GDP比重由44%左右下降至22%左右，即便排除2016年普兰店撤市设区等行政区划调整因素，县域经济对大连的贡献有明显的减弱。</p> \n<p cms-style=\"font-L\">　　他说，具体看，长海县经济体量小，GDP在大连各县（市、区）中长期处在末尾。瓦房店、庄河尽管是全国百强县，但GDP排名在大连各县（市、区）中也出现了下滑。普兰店撤市设区后，GDP在市内也出现了明显下滑。杨文学认为，大连需更好挖掘县域经济的潜力，支持瓦房店、庄河等强县扩权，加大要素保障，在重大项目统筹等方面给予倾斜，推动县域经济更好参与全国竞争。</p> \n<p cms-style=\"font-L\">　　卢伟指出，尽管大连新兴产业发展较快，但总体上产业体系现代化水平不高，战略性新兴产业增加值占比较小，服务业对经济增长的贡献有待进一步提升，轻工业发展质量有待提升，周边丰富的农副产品和海产品资源未能形成具有竞争力的产业集群。梁启东认为，大连经济过度依赖重工业，特钢、石化、装备制造等产业，产业结构失衡问题突出，“这些产业受国际市场和政策调控影响较大，经济抗风险能力较弱”。</p> \n<p cms-style=\"font-L\">　　梁启东在分析大连下半年经济走势时指出，装备制造业预计将保持平稳运行，但短期内难有大的突破；科创产业虽然发展迅速，但在经济总量中占比仍然有限；石化产业受国际油价波动影响显著，将成为影响下半年经济增长的最大变量。“大连下半年能否跻身‘万亿GDP俱乐部’，很大程度上取决于传统支柱产业的表现，特别是石化产业的走势。”他说。</p> \n<p cms-style=\"font-L\">　　值得注意的是，在全球产业链深度重构的背景下，大连面临的外部竞争压力日益加剧。卢伟指出，一些产业正在向成本更低、政策更优的地区转移。大连不仅面临东南亚、南亚等地区的低成本竞争，还要面对国内其他沿海城市产业升级带来的挑战。大连若不能及时提升产业竞争力，重工业与港口贸易的优势可能被削弱。</p> \n<p cms-style=\"font-L\">　　“全球产业链重构伴随技术快速迭代，大连重工业需向高端化、智能化转型，港口贸易也需借助数字化等技术提升效率。”卢伟说，大连虽有一定技术基础，但与国际先进水平和国内一线城市相比，在研发投入、高端人才吸引等方面仍有差距，若不能跟上技术创新步伐，可能在全球产业链重构中处于劣势，影响增长可持续性。</p> \n<p cms-style=\"font-L\">　　针对未来发展，梁启东建议，大连首先应在产业结构调整方面重点补齐轻工业、县域经济和民营经济三大短板。此外，大连作为东北振兴的龙头城市，应当充分发挥其区位优势和资源禀赋，通过建设“陆空海”多式联运体系，打造东北亚国际物流枢纽，强化对辽宁沿海经济带和东北腹地的辐射带动作用。重点发展高端装备制造、精细化工、新一代信息技术等战略性新兴产业，推动传统产业转型升级，构建现代化产业体系。同时，深化产学研合作，建设国家级科技创新平台，促进科技成果转化，打造东北科技创新高地。</p> \n<p cms-style=\"font-L\">　　卢伟认为，大连还需继续做足海的文章，推动海洋产业转型升级，发展海洋高端装备制造、海洋新能源、海洋生物医药等新兴海洋产业，打造具有国际竞争力的海洋产业集群，成为东北亚地区海洋经济发展的引领者。同时，加强与东北其他城市的合作，实现产业互补、资源共享，共同参与东北亚经济圈建设，提升整体竞争力。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">作者：</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">陈淑莲（149793680@qq.com）</font></font></p> \n<p cms-style=\"font-L\">　　编辑：孙晓波</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4848-8bbfc8a4832cb88f9f7f78c474dee868.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250813/3057-8aa13643e298add279835a3ec7cec880.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4470, NULL, '广东惠东18岁女孩凌晨失联，尸体在河道被发现，镇政府：以警方调查为主', 0, 1, 19, '2025-08-13 13:30:54', '2025-08-13 11:54:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/32/w550h282/20250813/ecef-aac54e90af9b0d2ee604564eace61e15.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvenz4267224.shtml', '津云新闻', '<p cms-style=\"font-L\">　　来源：津云新闻</p> \n<p cms-style=\"font-L\">　　8月12日，网传广东省惠东县平海镇一18岁女孩凌晨下夜班回家路上失联，后续尸体被发现在河道中。网传信息中有网友称：“女孩是上夜班回家路上被抓上了一辆无牌车，其家人发现失联后报警寻找。”</p> \n<p cms-style=\"font-L\">　　12日傍晚，女孩父亲向津云新闻记者证实女孩已去世，目前正在等待警方进一步调查。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/32/w550h282/20250813/ecef-aac54e90af9b0d2ee604564eace61e15.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"（网传信息中的聊天记录/图源网络）\">\n <span class=\"img_descr\">　　（网传信息中的聊天记录/图源网络）</span>\n</div> \n<p cms-style=\"font-L\">　　网传信息中还包含多张寻人启事截图。其中一张截图显示，一名据称为失联女孩同村村民的男子，将寻人启事发布在朋友圈，并表示当天找了女孩一天。寻人启事中披露，失联女孩姓黄，今年18岁，于8月6日凌晨0时左右在平海大林至油麻园方向失联。记者注意到，网传寻人启事中最初显示的日期为8月5日，家属后续证实准确失联时间为8月6日凌晨。</p> \n<p cms-style=\"font-L\">　　此外，记者在社交平台检索关键字发现，有多个账号于8月8日亦发布寻找该女孩的寻人启事。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/574/w550h824/20250813/6143-6174d03c0aa59de2fc686d0453a34d1b.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"（寻人启事截图/图源网络）\">\n <span class=\"img_descr\">　　（寻人启事截图/图源网络）</span>\n</div> \n<p cms-style=\"font-L\">　　还有网友发出多段视频，画面显示，在一处小桥的桥墩附近，疑似该失联女孩的尸体浸泡在水中，河岸上，有疑似亲属的女性在哭喊，身旁有多人在搀扶。桥面还停有警车，画面中有民警到场处置。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/484/w550h734/20250813/2832-b5f2711422565b9478498fc9e8ba38ab.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"（警察到场处置/图源网络）\">\n <span class=\"img_descr\">　　（警察到场处置/图源网络）</span>\n</div> \n<p cms-style=\"font-L\">　　8月12日下午，津云新闻记者致电平海镇政府了解此事相关情况和网传信息是否属实。一位男性工作人员称：“知道这件事情，具体情况派出所最清楚，调查出最终结果他们会给我们，目前还没有收到。”关于网传信息，还有一位女性工作人员告诉记者：“没有事实根据的东西不要传谣，一切以派出所调查为主。”</p> \n<p cms-style=\"font-L\">　　随后，记者又致电平海镇派出所，一位接电话的工作人员称：“电话中无法核实记者的身份，反映的问题需要进一步核实，关于案件问题，电话中不能告知。”</p> \n<p cms-style=\"font-L\">　　12日傍晚，记者打通前述寻人启事中留有的电话，对方表示他姓黄，是女孩的父亲。黄先生向记者确认了女儿去世的消息，并告知准确失联时间是8月6日凌晨0时左右，8月8日早上被人发现尸体在河中。当记者询问其女儿死亡原因是否确为溺水身亡，还是如网传所言属“遇害”时，他表示：“这个还需要派出所进一步去调查。”</p> \n<p cms-style=\"font-L\">　　（津云新闻记者 李杭朔）</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/32/w550h282/20250813/ecef-aac54e90af9b0d2ee604564eace61e15.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/574/w550h824/20250813/6143-6174d03c0aa59de2fc686d0453a34d1b.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/484/w550h734/20250813/2832-b5f2711422565b9478498fc9e8ba38ab.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4471, NULL, '金建希出庭受审时 念了句中国古诗“花无十日红” 韩媒解读：权力只是一时的', 0, 4, 105, '2025-08-13 14:30:18', '2025-08-13 13:41:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkvkux4147299.shtml', '海客新闻', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　来源：海客新闻</p> \n<p>　　据韩媒《朝鲜日报》报道，8月12日，韩国前第一夫人金建希出庭，接受逮捕必要性审查时，提到一句中国的古诗“花无十日红”。当晚，金建希被法院批捕，收押在单人牢房。</p> \n<p>　　“花无十日红”出自宋代诗人杨万里的《腊前月季》，原文是“只道花无十日红，此花无日不春风。”</p> \n<p>　　韩媒说，权力只是一时的。今年4月，金建希的丈夫尹锡悦被弹劾总统职务后，金建希就失去了第一夫人的地位，也失去了权力。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦再次被捕</a>\n</div> \n<p class=\"show_author\">责任编辑：王天昊 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4472, NULL, '印度总理莫迪或将9月同特朗普会晤', 0, 4, 207, '2025-08-13 14:30:26', '2025-08-13 13:16:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/533/w800h533/20250813/e5ac-4b64e9c528c26b265ed805d989f867a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvkuz7908249.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/533/w800h533/20250813/e5ac-4b64e9c528c26b265ed805d989f867a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△印度总理莫迪（资料图）\">\n <span class=\"img_descr\">△印度总理莫迪（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　据印度媒体13日报道，印度总理莫迪可能于9月底出席在美国纽约举行的联合国大会并同美国总统特朗普会晤，商讨贸易及关税问题。</p> \n<p cms-style=\"font-L\">　　报道说，印方正在积极推动这一行程，目前已向联合国提出申请。如果此访成行，莫迪将有机会在联合国大会上发表讲话，并与特朗普等多国领导人举行双边会晤。报道说，莫迪同特朗普会晤将“缓和贸易和关税问题”。</p> \n<p cms-style=\"font-L\">　　乌克兰总统泽连斯基11日与莫迪通话时表示，双方同意准备在9月联合国大会期间举行会晤。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250813/533/w800h533/20250813/e5ac-4b64e9c528c26b265ed805d989f867a3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4473, NULL, '贵州省3名县处级干部接受纪律审查和监察调查', 0, 1, 24, '2025-08-13 14:30:47', '2025-08-13 14:00:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkvkve3318799.shtml', '贵州省纪委监委网站', '来源：贵州省纪委监委网站\n<br>\n<br>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">安顺市关岭布依族苗族自治县人民政府原副县长蔡隆刚<font cms-style=\"font-L strong-Bold align-Center\">接受纪律审查和监察调查</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">据安顺市纪委监委消息：</font>安顺市关岭布依族苗族自治县人民政府原副县长蔡隆刚涉嫌严重违纪违法，目前正接受安顺市纪委监委纪律审查和监察调查。(安顺市纪委监委)</p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">黔南州福泉市政协党组成员、副主席钱发斌<font cms-style=\"font-L strong-Bold align-Center\">接受纪律审查和监察调查</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">据黔南州纪委监委消息：</font>黔南州福泉市政协党组成员、副主席钱发斌涉嫌严重违纪违法，目前正接受黔南州纪委监委纪律审查和监察调查。(黔南州纪委监委)</p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">铜仁武陵山高新技术产业发展集团有限公司党委委员、副总经理<font cms-style=\"font-L strong-Bold align-Center\">刘世红接受纪律审查和监察调查</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">据铜仁市纪委监委消息：</font>铜仁武陵山高新技术产业发展集团有限公司党委委员、副总经理刘世红涉嫌严重违纪违法，目前正接受铜仁市纪委监委纪律审查和监察调查。(铜仁市纪委监委)</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4474, NULL, '美国国债总额首次超过37万亿美元，美国人“平均”背债近11万美元', 0, 4, 207, '2025-08-13 16:30:16', '2025-08-13 15:28:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/236/w1080h756/20250813/d45d-7e68a0316f0ac571d7198d409ab433f5.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkuyfa7224344.shtml', '每日经济新闻', '<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">当地时间8月12日，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">由于美国联邦政府继续以创纪录的速度积累债务，美国国债总额</font><font cms-style=\"font-L strong-Bold color0\">首次超过37万亿美元</font><font cms-style=\"font-L\">，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">约为</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">2024年美国名义国内生产总值的1.27倍。截至2025年7月，全国总人口已经达到约3.42亿人，按此计算，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L color0\">美国人“平均”背债超10.8万美元。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">美国财政部发布的最新数据显示，截至当日下午，美国国债总额已达到</font><font cms-style=\"font-L strong-Bold color0\">37004817625842美元。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">美国联邦预算问责委员会主席马娅·麦吉尼亚斯对此表示，</font><font cms-style=\"font-L color0\">美</font><font cms-style=\"font-L strong-Bold color0\">国财政状况严</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold color0\">重失衡，但国会却不断让情况恶化。</font></font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/236/w1080h756/20250813/d45d-7e68a0316f0ac571d7198d409ab433f5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"图片来源：每经记者 郑雨航 摄\">\n <span class=\"img_descr\">图片来源：每经记者 郑雨航 摄</span>\n</div> \n<p cms-style=\"font-L\">　　值得一提的是，美国财政部公布的数据显示，2024年1月初美债总额达到34万亿美元，35万亿的数字出现在2024年7月底，间隔约7个月。但从7月底的35万亿美元到2024年11月的36万亿美元，这一万亿美债的增长用了约3个月。而从2024年11月的36万亿美元到2025年8月的37万亿美元，这一万亿美债的增长用了约9个月。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250813/629/w1080h349/20250813/f26e-d083e6612444eef2b79b8b46e5bf3f39.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△美国财政部下属的财务数据网站2024年11月数据显示，美国联邦政府债务总额已达到36.034万亿美元。\">\n <span class=\"img_descr\">△美国财政部下属的财务数据网站2024年11月数据显示，美国联邦政府债务总额已达到36.034万亿美元。</span>\n</div> \n<p cms-style=\"font-L\">　　自2022年6月，为应对居高不下的通胀，美联储进行了一揽子加息缩表计划后，美债利率进而上升，反倒增大了美国政府的偿债成本，再次推高美债水平。</p> \n<p cms-style=\"font-L\">　　作为美国国会在百年前发明的独有工具，“债务上限”为联邦政府履行已产生的支付义务敲定了举债的最高额度。触及这条红线，意味着美国财政部借款授权用尽，无权再发新债，需要国会提高或暂停债务上限，才能避免政府停摆和债务违约。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250813/528/w715h613/20250813/9302-0c077f613897cf47b7592382c380088f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△《华盛顿邮报》提供的美国债务上限示意图\">\n <span class=\"img_descr\"><font cms-style=\"font-L align-Center\">△《华盛顿邮报》提供的美国债务上限示意图</font></span>\n</div> \n<p cms-style=\"font-L\">　　但随着美国政府举债规模越来越大、美国政治越来越趋向两极分化，这一原本旨在强化财政纪律、控制债务规模的政策工具也演化成了彻头彻尾的党争工具。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">2021年债务上限被提高到31.4万亿美元。然而2023年1月美债突破了这一额度。此后国会两党撕扯了几个月，才赶在当年6月濒临债务违约的最后一刻达成妥协，通过所谓《财政责任法案》，同意在2025年1月1日之前暂停设置债务上限，同时对联邦政府20</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">24和2025财年的财政开支进行了限制。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">自1985年美国从净债权国变为净债务国之后，美债规模加速膨胀。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">特别是自2023年6月通过《财政责任法案》以来，美债更是以平均每100天增加约1万亿美元的速度疯涨。数据显示，从2017年9月至2022年1月，美债规模从20万亿美元升至30万亿美元；而</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">从2023年6月至当年9月再至当年年底，美债规模接连突破32万亿、33万亿和34万亿美元，较美国国会预算办公室所作预测提前五年冲过34万亿美元关口。</font></font></p> \n<p cms-style=\"font-L\">　　根据美国国会预算办公室此前公布的信息，美联邦政府的债务上限于今年1月2日调整为约36.1万亿美元。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">今年7月，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">美国总统</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">特朗普</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">推动的</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">“大而美”法案在美参议院、众议院获得通过，并由特朗普正式签署，使其生效。</font><font cms-style=\"font-L strong-Bold color0\">该法案包括了提高美国联邦债务上限。</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">美国媒体指出，在美国债务已达历史高位的情况下，该法案将进一步扩大结构性赤字。</font><font cms-style=\"font-L strong-Bold color0\">“美国日益增长的债务负担将惩罚子孙后代。”</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">7月21日，美国国会预算办公室发布的最新评估显示，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">未来十年，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">“大而美”税收与支出法案预计，</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">将使政府直接支出减少约1.1万亿美元，政府收入下降约4.5万亿美元。这意味着，</font></font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold color0\">美国财政赤字将增加约3.4万亿美元。</font></font><font cms-style=\"font-L\"></font></font></p> \n<p cms-style=\"font-L\">　　观察人士认为，财政赤字增加将推高美国政府本已高企的债务规模，引发市场对美国债务可持续性的担忧。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">此前，由于美国政府债务及利息支出增加，国际信用评级机构穆迪5月下调了美</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">国主权信用评级，这是第三家下调美国主权信用评级的主要国际评级机构。</font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">美国债务飙升的轨迹近年来屡遭警告。而在谁该为债务担责问</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">题上，美国两党早已习惯了相互甩锅：共和党将其归</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">咎于民主党在财政开支上的大手大脚，民主党则将其归咎于共和党多年来服务于大公司和富人的减税政策。但事实是，轮流主政白宫的两党所制造的债务没有最多，只有更多。</font></font></p> \n<p cms-style=\"font-L\">　　由于美国政府“花的钱”远远超过“挣的钱”，预算赤字逐年激增。</p> \n<p cms-style=\"font-L\">　　美国国会预算办公室（CBO）最新数据显示，2025财年美国联邦预算赤字将达1.9万亿美元，占国内生产总值（GDP）的6.2%。预计到2035年联邦预算赤字将升至2.7万亿美元，凸显未来十年美国财政政策面临的挑战。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/spider20250813/344/w1080h864/20250813/d466-6e99d366be4aad08dd7a04c06f6539c3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△美国国会预算办公室官网报告截图\">\n <span class=\"img_descr\"><font cms-style=\"font-L align-Center\">△美国国会预算办公室官网报告截图</font></span>\n</div> \n<p cms-style=\"font-L align-Center\">　　　</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">校对|</font></font><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L align-Center\">刘思琦</font></font></font></font></font></font></font></font></font></p> \n<p cms-style=\"font-L align-Center\">　　封面图片来源：视觉中国（资料图）</p> \n<p cms-style=\"font-L align-Center\">　　每日经济新闻综合自央视新闻、新华社</p> \n<!--article_adlist[<p cms-style=\"font-L\"></p>]article_adlist--> \n<p></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/236/w1080h756/20250813/d45d-7e68a0316f0ac571d7198d409ab433f5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/629/w1080h349/20250813/f26e-d083e6612444eef2b79b8b46e5bf3f39.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/528/w715h613/20250813/9302-0c077f613897cf47b7592382c380088f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/344/w1080h864/20250813/d466-6e99d366be4aad08dd7a04c06f6539c3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4475, NULL, '韩国前第一夫人金建希出庭受审时说“花无十日红”，被捕同日，其最核心亲信之一“大管家”也被捕，流亡海外数月后突然回国', 0, 4, 105, '2025-08-13 16:30:25', '2025-08-13 15:22:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250813/2e00-2c4f633c7fd15342f5ee503c03eef924.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvkve3348075.shtml', '红星新闻', '<p cms-style=\"font-L\">　　8月12日晚，韩国法院针对前总统尹锡悦夫人金建希签发逮捕令。由此，韩国宪政史上首次出现前总统夫妇都被捕的情况。韩国金建希特检组今天（8月13日）通报说，将于当地时间14日上午10时对金建希进行传唤调查。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250813/2e00-2c4f633c7fd15342f5ee503c03eef924.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/106/w550h356/20250813/f2c0-3294fb8b5f0eb3610bfe61e53229cb0d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"8月12日在韩国首尔中央地方法院拍摄的韩国前总统尹锡悦妻子金建希（中）。新华社/纽西斯通讯社\">\n <span class=\"img_descr\">8月12日在韩国首尔中央地方法院拍摄的韩国前总统尹锡悦妻子金建希（中）。新华社/纽西斯通讯社</span>\n</div> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">金建希出庭受审时</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">念了句中国古诗“花无十日红”&nbsp;</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L strong-Bold align-Center color210\">韩媒解读：权力只是一时的</font></font></font></font><font cms-style=\"font-L align-Center\"></font></p> \n<p cms-style=\"font-L\">　　据韩媒《朝鲜日报》报道，8月12日，韩国前第一夫人金建希出庭，接受逮捕必要性审查时，提到一句中国的古诗“花无十日红”。</p> \n<p cms-style=\"font-L\">　　“花无十日红”出自宋代诗人杨万里的《腊前月季》，原文是“只道花无十日红，此花无日不春风。”</p> \n<p cms-style=\"font-L\">　　韩媒说，权力只是一时的。今年4月，金建希的丈夫尹锡悦被弹劾总统职务后，金建希就失去了第一夫人的地位，也失去了权力。</p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">金建希被捕同日</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">流亡海外数月的“金建希大管家”回国被捕</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">就在金建希被捕的同一天，其最核心的亲信之一、被称为“金建希大管家”的金艺成（音译）在流亡海外数月后突然回国，并在机场被特别检察官（特检）小组当场逮捕，</font><font cms-style=\"font-L\">引发舆论对“潘多拉的盒子”是否会就此打开的广泛关注。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/275/w550h525/20250813/c98c-598c1f9b5a06ed13c06af3f7654c5342.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲12日下午，金艺成被押送至特检组办公室\">\n <span class=\"img_descr\"><font cms-style=\"font-L\">▲12日下午，金艺成被押送至特检组</font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">办公室</font></font></font></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">据报道，闵重基特别检察官小组于12日逮捕了金建希女士的亲信金艺成。</font><font cms-style=\"font-L strong-Bold\">金艺成被指涉嫌利用与</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">金建希</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">的交情，为自己参与设立并持股的租车公司IMS Mobility，从Kakao Mobility等企业处获得了高达184亿韩元（约合人民币9550万元）的特惠性投资。</font></font></font></p> \n<p cms-style=\"font-L\">　　据了解，金艺成在特检组成立前的今年4月便已出境前往越南，此后一直未回韩国，并处于红色通缉令状态。特检组在其回国后立即于仁川国际机场将其逮捕，并押送至办公室，就IMS Mobility获得大规模投资的经过，以及“是否将部分投资款项与金女士进行了分享”等问题展开了讯问。</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/122/w550h372/20250813/c494-6f314df7a2cf9ce57703d204f5ac44a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲8月12日，金艺成（中）在仁川国际机场被特别检察官小组逮捕并带走 图据视觉中国\">\n <span class=\"img_descr\">▲8月12日，金艺成（中）在仁川国际机场被特别检察官小组逮捕并带走 图据视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">在回国前，金艺成曾接受媒体采访，否认相关指控。</font><font cms-style=\"font-L\">他表示：“特检组似乎想把我塑造成‘第二个崔顺实’，但崔顺实可以随意出入青瓦台，我连汉南洞的官邸都没去过。” 对于挪用投资款并与金建希分享收益的嫌疑，他则称，金建希过去曾致电他：“听说你赚了什么钱，如果那边联系你，就去接受调查”，他因此曾在总统室公职秘书官室接受过调查。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">有分析认为，随着被媒体称为“金建希</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">大</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">管家”的金艺成戏剧性归案，金建希的艰难日子，或许才拉开序幕。</font></font></font></p> \n<p cms-style=\"font-L\">　　回顾金建希的经历，她可谓始终身处舆论的风口浪尖。有分析指出，在韩国政治史上，恐怕没有哪位第一夫人能像金建希一样，引发如此巨大且众多的争议。她从成为总统夫人之前就“杂音不断”，大选后也一直是“政权的不稳定因素”。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/news/crawl/711/w550h961/20250813/728b-b884b9535a3275a259d628cf86bd9a02.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲12日，金建希出庭\">\n <span class=\"img_descr\"><font cms-style=\"font-L align-Center\">▲12日，金建希</font><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\"><font cms-style=\"font-L align-Center\">出庭</font></font></font></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">2021年-2022年，韩国总统选举竞选期间，金建希就已被视为“一个难以驾驭的存在”。</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">当时，她不仅陷入德意志银行股价操纵、其母涉嫌骗取疗养补贴等疑云，还因履历造假等问题成为在野党的集中攻击目标。</font></font></font></p> \n<p cms-style=\"font-L\">　　在此期间，发生了多起令尹锡悦竞选团队倍感困扰的事件。其中，所谓的“给狗喂苹果”争议便是一例。在时任候选人尹锡悦因不当言论而面临巨大批评压力之际，其社交媒体上却突然出现了一张“在办公室给狗喂苹果”的照片，此举被外界批评为“是在嘲弄国民吗？”一位熟知当时情况的竞选团队相关人士近日透露：“那是金女士的杰作。金女士没有与竞选团队商量，半夜把狗带到办公室……拍照后上传到了丈夫的社交媒体上。”</p> \n<p cms-style=\"font-L\">　　另一件引发舆论的事件，是“首尔之声7小时录音”的曝光。在这段被公开的通话录音中，金建希就多项敏感议题发表了争议性言论，尤其她指着部分媒体称“等我进了青瓦台，就把他们全都送进监狱”，以及“我掌权后，‘首尔之声’那里绝对不会有好下场”等言论，引发了外界对“金建希认为不是丈夫，而是自己掌权”的担忧。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">尽管金建希曾于2021年12月公开道歉，并向国民承诺“如果丈夫成为总统，我将努力</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">只</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">忠实地扮演好妻子的角色”，但有多个报道认为，“这个承诺最终未能兑现”。</font></font></font></p> \n<p cms-style=\"font-L\">　　成为韩国第一夫人后，围绕她的争议有增无减。2022年6月，她因带并非公职人员的秘书官夫人出访西班牙，引发“金建希是尹锡悦背后实权人物”的舆论风波；当时佩戴的一条价值6000万韩元的梵克雅宝项链，后被特别检察组指认为是“收受的具有贿赂性质的贡品”。此后，在被曝出涉嫌收受名牌包后，尽管批评声浪滔天，“金建希始终没有道歉”。</p> \n<p cms-style=\"font-L\">　　有分析认为，“尹锡悦政权”最终未能控制住这一不稳定因素，从而招致了悲剧。事实上，尹锡悦团队并非没有过约束金建希的尝试。尹锡悦竞选成功后，各方曾提出过“任命特别监察官”或“设立第二附属室”等多种方案，但都“以失败告终”。去年韩国国会选举前，时任执政党高层的韩东勋也曾试图牵制，公开表示“有必要就收受名牌包嫌疑表明尹总统或金夫人的立场”，但结果“反而自己面临被驱逐的危机”。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">就这样，报道形容金建希“逐渐成为一个不可触碰的存在”。据称，12日被申请的有关金建希的逮捕令上，罗列了德意志银行股价操纵嫌疑、明泰均</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">公推</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">介入嫌疑等多项指控。</font></font></font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">金建希被关在首尔“看守所酒店”</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">将换囚服、手持编号牌拍大头照</font></p> \n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center color210\">前总统朴槿惠的“干政闺蜜”此前也被关押在此</font></p> \n<p cms-style=\"font-L\">　　据悉，法院当天上午10时10分许开庭进行逮捕必要性审查，金建希出庭受审。庭审持续4个多小时，直到下午2时35分左右结束。</p> \n<p cms-style=\"font-L\">　　金建希在庭审结束后被送至首尔南部看守所等待结果，她也将正式被羁押于此。需要注意的是，金建希原计划被移送至尹锡悦所处的首尔看守所，但特检组11日向法院提出了更换收押地点的申请。有分析认为，这表明相关方面担忧前总统夫妇被关在一处可能引发更多负面影响，比如可能发生在首尔看守所附近的抗议示威活动。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">根据首尔南部看守所发布的每日菜单，金建希在看守所的第一顿早餐包括面包、草莓酱、牛奶、法式香肠和蔬菜沙拉。午餐是猪肉泡菜汤、饺子、南瓜咸虾仁炒菜和青椒泡菜。晚餐有黄瓜凉汤、拌蔬菜、煎蛋和萝卜泡菜。</font><font cms-style=\"font-L strong-Bold\">每人每餐餐标约为1733韩元（约为人民币9元）。</font></p> \n<p cms-style=\"font-L\">　　报道称，金建希将接受全面体检，换上囚服，并手持写有其囚犯编号的牌子拍摄大头照。</p> \n<p cms-style=\"font-L\">　　在办理完手续后，金建希将被关押在约6.6至10平方米的单间，房间内没有床，会有饮水机、折叠桌、电视，还有一个卫生间。不过，报道同时指出，如果她被分配到更大的房间，房间内可能会有水槽等其他设施。据称，她每天可以进行一小时的户外运动。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">据了解，金建希将被关押在专门收押女性犯人的牢房。</font><font cms-style=\"font-L strong-Bold\">报道称，韩国前总统朴槿惠的“干政闺蜜”崔顺实此前也被关押在该监狱。</font></p> \n<p cms-style=\"font-L\">　　与上个世纪建成、设施较落后的首尔看守所不同，首尔南部看守所被称为“看守所酒店”。据报道，首尔南部看守所于2011年10月完工。除了2017年新落成的首尔东部看守所外，这是首尔及京畿道地区最新的惩教设施，其最多可以容纳1600名囚犯，配备最先进的监控和检测系统，还配有太阳能和地热供暖系统以及制冷设施。与首尔看守所相比，这里可谓是酒店级别。报道称，金建希昨日在该看守所等待结果的拘留室配有厕所、电视和沙发，但没有空调。</p> \n<p cms-style=\"font-L\">　　来源：红星新闻</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦夫妇同被羁押</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250813/2e00-2c4f633c7fd15342f5ee503c03eef924.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/106/w550h356/20250813/f2c0-3294fb8b5f0eb3610bfe61e53229cb0d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/275/w550h525/20250813/c98c-598c1f9b5a06ed13c06af3f7654c5342.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/122/w550h372/20250813/c494-6f314df7a2cf9ce57703d204f5ac44a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/711/w550h961/20250813/728b-b884b9535a3275a259d628cf86bd9a02.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4476, NULL, '柳州：“小切口”监督推动惠农惠民补贴安全“落袋”', 0, 2, 214, '2025-08-13 18:30:23', '2025-08-13 18:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkvvkt4004362.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　“补贴到手了，渔船维修、保养的钱有着落了！”近日，柳州市鹿寨县纪委监委派驻县农业农村局纪检监察组到该县鹿寨镇洛清江渔船停泊点走访了解禁渔期渔民生活补贴发放情况，正在维修渔船的黄伯高兴地说道。</p>\n<p cms-style=\"font-L\">　　此前，该县纪委监委在监督检查时发现2023年禁渔期应发渔民生活补贴拖欠近两年未发。经核查，县农业局收集补贴申报材料不及时、县财政局统筹涉农资金拨付不到位，导致300多户渔民禁渔期生活补贴共60.2万元久拖未发。县纪委监委随即对相关部门负责人进行谈话提醒，通过压实责任、跟进监督，推动禁渔期生活补贴全部发至渔民“一卡通”账户。</p>\n<p cms-style=\"font-L\">　　惠农惠民补贴事关群众切身利益，助力群众端稳了“饭碗”，鼓起了“钱袋”。柳州市纪委监委将惠农惠民补贴资金作为乡村振兴资金使用监管重点事项，从“小切口”破题，在“关键处”发力，建立健全监督检查室综合协调、派驻机构跟进监督、市县主战主抓工作机制，市县乡三级联查联治，保障惠农惠民资金精准落实，推动成果惠及群众。</p>\n<p cms-style=\"font-L\">　　该市纪委监委聚焦虚假申报、优亲厚友、设置隐形门槛“吃拿卡要”、公示流于形式等突出问题，以监督任务单为工作指引，每月分析研判、突出重点、动态更新，指导各级纪检监察机关把准监督方向、明确监督重点，重点查发放名单，看对象是否精准；查审批流程，看程序是否规范；查资金流向，看拨付是否及时；查公开情况，看公示是否到位，监督推动惠民惠农补贴算出“明白账”。</p>\n<p cms-style=\"font-L\">　　“收到群众反映油茶种好后无人前来验收，补贴迟迟未发放的问题后，结合市纪委监委制发的监督任务单内容，我们立即开展实地走访，通过查看油茶补贴台账、村委公示栏，与镇村干部、种植户面对面交谈，发现部分村因地块矛盾纠纷导致验收中断、审核流程推进缓慢等问题。”柳南区纪委监委专项监督小组工作人员介绍。</p>\n<p cms-style=\"font-L\">　　此前，该区纪委监委下沉村镇一线开展监督检查，发现惠民惠农补贴发放“中梗阻”问题，随即梳理形成问题清单，督促相关部门针对群众反映的地块矛盾纠纷导致油茶补贴迟迟无法发放、农户种植积极性受挫等问题进行集中“会诊”，分析研判，形成对策，推动48万余元油茶种植补贴发放到位。同时，将监督推动问题整改与解决群众急难愁盼问题相结合，督促辖区各镇、涉农街道举一反三，对各类惠民惠农政策落实、资金使用等方面靠前监督、跟进监督，确保惠民惠农补贴真正用在刀刃上、惠及老百姓。</p>\n<p cms-style=\"font-L\">　　以点带线深挖细查，斩断伸向群众利益的“黑手”，保障惠农惠民补贴安全“落袋”。柳城县纪委监委坚持以案件查办开局破题，严肃查处了一起“虚假申报”案，该县寨隆镇平安法制办副主任韦某某通过虚报甘蔗种植面积，投保甘蔗政策性保险获利，最终，韦某某受到党内警告处分。在严肃查处韦某某违纪行为的同时，县纪委监委对全县2021年至2023年申报的甘蔗保险、财政保费补贴拨付等数据进行关联、碰撞、比对、分析，深挖出一批虚增种植面积骗取甘蔗保险的问题线索，推动立案13件，及时发现并纠治惠民惠农补贴“跑冒滴漏”问题。（柳州市纪委监委）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4477, NULL, '受台风“杨柳”影响，部分进出海南岛列车停运', 0, 1, 21, '2025-08-13 18:30:54', '2025-08-13 18:10:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkvvky3170682.shtml', '界面', '<p cms-style=\"font-L\">　　8月13日，据海南铁路海口车务段，因受台风“杨柳”影响，铁路部门将对部分列车调整运行秩序，具体如下：8月13日出岛列车Z502次、K512次、Z112次停运。8月15日进岛列车Z501次、K511次、Z111次停运。铁路部门将持续密切关注台风路径变化和降雨影响情况，加大服务保障力度，车站将在服务台、进站口等岗位加派人员引导，为有需要的旅客提供指引和帮助，动态增加退改签窗口，方便旅客线下办理退票、改签业务。（央视新闻）</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4478, NULL, '甘肃庆阳市宁县一名家长质疑校服问题被拘 当地启动追责', 0, 2, 302, '2025-08-13 18:31:20', '2025-08-13 17:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/324/w550h574/20250813/752c-4c4fbf86b074d1016cb522071f49e774.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvvmc6179301.shtml', '现代快报', '<p cms-style=\"font-L\">　　来源：现代快报</p> \n<p cms-style=\"font-L\">　　[家长质疑校服问题被拘当地启动追责] 因在网上反映儿子学校校服存在质量问题，甘肃庆阳市宁县36岁男子邓某某被当地警方拘留。此后，经庆阳市中级人民法院二审认定，宁县公安局的行政处罚决定违法，并对当事人进行国家赔偿3237.08元。既然宁县公安局当初作出的行政处罚决定被认定有问题，当地是否会启动问责？涉事企业当初报案是否存在问题？</p> \n<p cms-style=\"font-L\">　　针对上述问题，8月13日，@现代快报 记者先后联系了宁县公安局和宁县县委宣传部。“首先感谢你们关注这个问题，我们现在已经成立了工作专班，对这个事情进行全面的调查。”宁县县委宣传部一名工作人员告诉记者，目前该县已成立工作专班，重新梳理事发经过，全面启动调查追责。相关调查结果也将通过网络，向社会公开。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/324/w550h574/20250813/752c-4c4fbf86b074d1016cb522071f49e774.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<strong><font cms-style=\"font-L\">相关新闻</font></strong></p> \n<p cms-style=\"font-L\">　　<strong><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">家长发视频质疑校服质量被拘留，法院判了（观察者网）</font></font></font></font></strong></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">甘肃庆阳市宁县盘克镇36岁男子邓建国因质疑儿子学校校服质量问题，通过抖音发布视频引发关注，最终被宁县公安局以“寻衅滋事”行政拘留7天。经行政诉讼二审，法院认定警方处罚程序违法、事实证据不足，</font></font></font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">撤销原处罚并判令赔偿国家赔偿金3237.08元</font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">。案件背后折射出公民维权与行政机关执法规范的冲突，引发社会对“网络言论边界”与“执法程序合法性”的讨论。</font></font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/790/w1024h1366/20250812/9701-db0e16f4f00595999d14eb2b0151c471.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"因在网上举报儿子学校校服质量问题，邓建国被以寻衅滋事拘留7天\">\n <span class=\"img_descr\">因在网上举报儿子学校校服质量问题，邓建国被以寻衅滋事拘留7天</span>\n</div> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">事件起因：校服质量争议与网络质疑</font></p> \n<p cms-style=\"font-L\">　　2023年9月，6岁的涵涵到盘克镇中心小学上一年级。11月29日，校服下发后，邓建国发现其服饰标签标注成分与面料质地有问题，心生疑虑。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">裁判文书材料显示，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">多方沟通未果后，邓建国于2023年12月1日通过抖音发布视频《质疑校服质量安全和校服乱象谁监管》，点击量达14.9万次。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">经调解，2023年12月7日，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">宁县市场监管局向邓建国送达了该校服检测合格的第三方质检报告，邓建国对其中甲醛等有毒物质的鉴定表示认可，但仍怀疑有质量问题。</font></font></p> \n<p cms-style=\"font-L\">　　证据材料显示，春秋季校服的标签标注为100%聚酯纤维，但检测结果为聚酯纤维94.9%、氨纶5.1%，标签成分与检测结果不符。此外，庆阳市质量计量检验检测中心对夏季校服抽样检测发现其棉含量为31.8%、涤含量为68.2%，不符合夏季校服棉含量不得低于35%的国家标准。</p> \n<p cms-style=\"font-L\">　　但检测报告认为，春秋季校服单项评定标准为符合；夏季校服所检项目符合本次监督抽查要求。</p> \n<p cms-style=\"font-L\">　　不认可该结果的邓建国于12月8日发布题为《时至今日，问题校服仍然未被召回》的视频，该条视频点击量为10.2万次。</p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">警方处罚：以“寻衅滋事”拘留7天</font></p> \n<p cms-style=\"font-L\">　　兆春服装厂（校服供应商）以“订单被取消”为由，于2023年12月8日向宁县公安局报案，要求追究邓建国“寻衅滋事”或“散布谣言”责任。宁县公安局网安大队受案后，于12月13日作出《行政处罚决定书》，认定邓建国“无相关证据情况下发布不实视频，引起网友转发，造成公共场所秩序混乱”，决定对其行政拘留7天。</p> \n<p cms-style=\"font-L\">　　邓建国称，警方未告知其可申请暂缓执行拘留，直接送达《行政处罚告知书》《决定书》后将其送拘留所。</p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">行政诉讼：一审驳回，二审认定程序违法</font></p> \n<p cms-style=\"font-L\">　　邓建国对被拘留决定不服，申请行政复议（宁县政府维持原决定），后向庆城县人民法院提起行政诉讼，请求撤销处罚。一审法院认为，邓建国“通过抖音发布质疑视频（含‘存在甲醛等有毒物质与客观实际不符’内容）”，虽校服确有质量问题，但“维权应通过正当途径，而非网络发布不实信息”，故驳回其诉讼请求。</p> \n<p cms-style=\"font-L\">　　邓建国上诉至庆阳市中级人民法院。二审法院认定：</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">程序违法</font></font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">：警方作出拘留决定前未保障邓建国的陈述、申辩权，违反法定程序；</font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">事实证据不足</font></font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">：虽邓建国的质疑“具有一定事实基础”（校服标签与检测不符、棉含量不达标），但警方未提供充分证据证明其行为“造成公共场所秩序混乱”；</font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">处罚不当</font></font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">：原处罚决定因程序违法、证据不足应撤销，但因已执行完毕，无撤销必要；</font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">国家赔偿</font></font></font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">：警方违法行政拘留，应赔偿邓建国7天工资（按日均工资462.44元计算，共3237.08元）。</font></font></font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">最终，</font></font></font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">庆阳市中院撤销一审判决及宁县政府复议决定，确认警方拘留决定违法，并判令赔偿3237.08元。</font></font></font></font></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/28/w608h1020/20250812/fc8a-905cc5ca7dad7d4c8a5847f7731c2fed.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"二审判决书\">\n <span class=\"img_descr\">二审判决书</span>\n</div> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">后续争议：服装厂“诬告陷害”未获立案</font></p> \n<p cms-style=\"font-L\">　　邓建国认为，兆春服装厂“歪曲事实、恶意陷害”致其被拘，向宁县公安局报案追究其法定代表人刑事责任，但警方未予立案，也未出具《不予立案通知书》。</p> \n<p cms-style=\"font-L\">　　律师侯亮分析：</p> \n<p cms-style=\"font-L\">　　若服装厂基于部分事实或合理怀疑报案（如校服质量问题属实），即使最终未被认定违法，也不构成“诬告陷害”；</p> \n<p cms-style=\"font-L\">　　警方超期未作出立案决定（通常30日内），可视为“不立案”，邓建国可向检察院申请立案监督。</p> \n<p style=\"text-align: center;\" cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">事件影响：家庭破裂与维权困境</font></p> \n<p cms-style=\"font-L\">　　邓建国因被拘留导致情绪崩溃、夫妻关系破裂（2024年1月离婚）、失去工作，并被诊断为抑郁症。其经历引发公众对“公民网络维权边界”“行政机关执法规范性”的关注。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/152/w1024h728/20250812/8153-2728f5359871518283a63ef3bd65811d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"今年4月，邓建国被诊断为患有抑郁症\">\n <span class=\"img_descr\">今年4月，邓建国被诊断为患有抑郁症</span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sinakd20250812s/790/w1024h1366/20250812/5504-58059555df85f351dfbd2186fd6ee4c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"被拘留后，邓建国精神状态不佳，导致夫妻感情不和并离婚。\">\n <span class=\"img_descr\">被拘留后，邓建国精神状态不佳，导致夫妻感情不和并离婚。</span>\n</div> \n<p cms-style=\"font-L\">　　庆阳市市场监管局2024年3月通报，联合教育局开展校服质量专项检查，兆春服装厂因“质量管理制度落实不到位”被责令整改。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">来源|观察者网综合澎湃新闻</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">、纵深新闻等</font></font></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/transform/324/w550h574/20250813/752c-4c4fbf86b074d1016cb522071f49e774.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/790/w1024h1366/20250812/9701-db0e16f4f00595999d14eb2b0151c471.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/28/w608h1020/20250812/fc8a-905cc5ca7dad7d4c8a5847f7731c2fed.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/152/w1024h728/20250812/8153-2728f5359871518283a63ef3bd65811d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/sinakd20250812s/790/w1024h1366/20250812/5504-58059555df85f351dfbd2186fd6ee4c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4479, NULL, '朝鲜82岁播音员李春姬再当班', 0, 4, 147, '2025-08-13 19:30:18', '2025-08-13 18:21:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkvvkv7784654.shtml', '看看新闻KNEWS', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　【#朝鲜82岁播音员李春姬再当班#】当地时间12日，俄罗斯总统普京与朝鲜劳动党总书记、国务委员长金正恩通电话。朝鲜82岁“国宝级”播音员李春姬进行了播报。媒体指出尽管李春姬已退休，但仍会负责特别重大新闻的报道。</p> \n<p>　　<strong>相关新闻</strong></p> \n<p>　　<a href=\"https://k.sina.com.cn/article_1699432410_654b47da02001jke6.html?from=news&amp;subch=onews\">普京同金正恩通电话重申发展合作承诺</a></p> \n<!--WeiboOriginalContent[{\"text\": \"【#朝鲜82岁播音员李春姬再当班#】当地时间12日，俄罗斯总统普京与朝鲜劳动党总书记、国务委员长金正恩通电话。朝鲜82岁“国宝级”播音员李春姬进行了播报。媒体指出尽管李春姬已退休，但仍会负责特别重大新闻的报道。 http://t.cn/A6saYfEk \"}]WeiboOriginalContent--> \n<p class=\"show_author\">责任编辑：刘光博 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4480, NULL, '金建希囚犯编号：4398，牢房伙食曝光', 0, 4, 105, '2025-08-13 19:30:25', '2025-08-13 17:55:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/7d83-bf06688f770bf9c8e65d139517104f27.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-13/doc-infkvvmc6195247.shtml', '直新闻', '<p cms-style=\"font-L\">　　来源：直新闻</p> \n<p cms-style=\"font-L\">　　当地时间12日深夜，韩国首尔中央地方法院签发对前第一夫人金建希的拘捕令，金建希随即被首尔南部拘留所拘押。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/7d83-bf06688f770bf9c8e65d139517104f27.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"金建希（资料图）\">\n <span class=\"img_descr\">金建希（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　据韩国《朝鲜日报》报道，当天在接受逮捕必要性审查过程中，金建希团队引用一句中国古诗发出感慨：“花无十日红”，“目前金建希女士手中的花都已凋谢了”。</p> \n<p cms-style=\"font-L\">　　“花无十日红”出自宋代诗人杨万里的《腊前月季》，原文是“只道花无十日红，此花无日不春风”。</p> \n<p cms-style=\"font-L\">　　报道称，“花无十日红”一句意在喻指“权力只是一时的”。今年4月，韩国宪法法院宣布通过对金建希丈夫尹锡悦的弹劾，尹锡悦被罢免总统职务，随后他又于7月10日被逮捕，羁押在首尔拘留所。至此，韩国宪政史上首次出现前总统夫妇同时被羁押的情况。</p> \n<p cms-style=\"font-L\">　　《朝鲜日报》不无讽刺意味地写道，金建希不仅如今没有任何实权，也从未真正拥有过实权。</p> \n<p cms-style=\"font-L\">　　与此同时，金建希被捕后住单人牢房、睡地铺，三餐菜单等拘留细节也被披露。</p> \n<p cms-style=\"font-L\">　　拘留所按照规定确认了金建希的个人信息，并进行了简短面谈，随后进行了详细的身体检查。此后，金建希穿上了女性未决犯在夏季穿着的浅绿色囚服。她的囚犯编号为4398号。接着，金建希拍摄了用于识别囚犯身份的面部照片，并领取了内衣、毛巾、牙刷、餐盘和塑料勺子后，被带往拘留室。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">金建希被关押在一间约6.6平方米的单人牢房</font>，牢房内配备储物柜、折叠饭桌、电视机、风扇和马桶等，并设有24小时闭路电视监控系统。<font cms-style=\"font-L strong-Bold\">牢房内没有床，需打地铺睡觉。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">金建希的伙食与其他收押人员相同，13日的第一顿早餐为面包、草莓酱、牛奶、香肠和蔬菜沙拉等；午餐为猪肉泡菜汤、糖醋煎饺、南瓜炒虾酱、萝卜泡菜；晚餐则是黄瓜凉汤、凉拌菜、煎鸡蛋和小萝卜泡菜。</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">此外，总统警卫处停止为金建希提供警卫服务。根据韩国《前任总统礼遇</font><font cms-style=\"font-L\">法》，可在必要时间内向前总统及其夫人提供安保服务。但因金建希被逮捕，相关待遇不再适用。</font></p> \n<p cms-style=\"font-L\">　　韩国金建希特检组13日通报说，将于当地时间14日上午10时对金建希进行传唤调查。</p> \n<p cms-style=\"font-L\">　　根据早前报道，随着尹锡悦沦为阶下囚，针对金建希的调查全面展开。2025年6月，淑明女子大学撤销了金建希的硕士学位，随后国民大学也撤销其博士学位。7月，韩国政府组建了“金建希特检组”，重启对她的调查。8月6日，特检组对金建希进行了传唤调查，但她基本否认了所有指控。次日，特检组以涉嫌违反《资本市场法》《政治资金法》和《特定犯罪加重处罚法》等为由提请法院批捕金建希。特检组先后在7日和11日向法院提交了总计超过800页的拘留意见书。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦夫妇同被羁押</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/117/w550h367/20250813/7d83-bf06688f770bf9c8e65d139517104f27.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4481, NULL, '“助农苹果汁”相关公司在社交平台删除“助农大使”证书图片，此前产品被赵露思在直播中推荐过', 0, 1, 27, '2025-08-13 21:30:26', '2025-08-13 20:50:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/50/w1022h1428/20250813/f835-01a050daf67febe81b53e459bcf03601.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/zx/2025-08-13/doc-infkvzst7696175.shtml', '成都商报', '<p cms-style=\"font-L\">　　8月13日，一款“助农苹果汁”引发了网友的关注。</p> \n<p cms-style=\"font-L\">　　据悉，该款苹果汁曾被演员赵露思在直播中推荐过。有网友发现，13日，<font cms-style=\"font-L\">该品牌的关联公司延安小小的果实农业科技有限公司（以下简称：小小的果实）在其社交平台发布了一张<font cms-style=\"font-L\"><font cms-style=\"font-L\">“助农大使”</font>证书——图片显示，该证书</font>由陕西省延长县农业农村局发出</font>，显示该公司在延安助农工作中表现突出。发证时间为2025年6月。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\">13日，有媒体报道，该证书涉嫌造假，公章是假的。</font><font cms-style=\"font-L\">红星新闻记者13日下午联系到延长县农业农村局，一名工作人员在电话中表示</font><font cms-style=\"font-L strong-Bold\">正在核实证书上公章的编号以及证书真实性，并称会在互联网上进行统一回复。</font></p> \n<p cms-style=\"font-L\">　　刚刚，红星新闻记者发现，发布在该社交平台上的“助农大使”证书，已经被删除。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/50/w1022h1428/20250813/f835-01a050daf67febe81b53e459bcf03601.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"小小的果实社交平台账号发出的“助农大使”证书，目前该图片已删除\">\n <span class=\"img_descr\">小小的果实社交平台账号发出的“助农大使”证书，目前该图片已删除</span>\n</div> \n<p cms-style=\"font-L\">　　天眼查显示，<font cms-style=\"font-L\">小小的果实</font>成立于今年5月，法定代表人为宋文章，注册资本100万元人民币，经营范围包括水果种植、供应链管理服务、农副产品销售等。股权全景穿透图显示，该公司由宋文章和厦门我很忙文化传媒有限公司分别持股70%、30%，后者由刘剑利和孙嘉蔓分别持股80%、20%。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250813/396/w2476h1120/20250813/cd3c-2bcf73d3a52f6191336e136b7a2e74bd.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"天眼查截图\">\n <span class=\"img_descr\">天眼查截图</span>\n</div> \n<p cms-style=\"font-L\">　　红星新闻记者 邱峻峰</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/spider20250813/50/w1022h1428/20250813/f835-01a050daf67febe81b53e459bcf03601.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/396/w2476h1120/20250813/cd3c-2bcf73d3a52f6191336e136b7a2e74bd.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4482, NULL, '齐聚天府赴世运，拥抱世界向未来', 0, 1, 23, '2025-08-13 21:30:32', '2025-08-13 20:38:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/26/w550h8276/20250813/9533-90e4c7a9ab58c09b32e3da8d2753e373.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvzsz6088192.shtml', '新浪新闻综合', '<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/26/w550h8276/20250813/9533-90e4c7a9ab58c09b32e3da8d2753e373.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/26/w550h8276/20250813/9533-90e4c7a9ab58c09b32e3da8d2753e373.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4498, NULL, '美国国债超37万亿美元，会爆雷吗？', 0, 4, 207, '2025-08-13 22:30:17', '2025-08-13 18:52:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-13/doc-infkvzsz6101111.shtml', '中国新闻网', '<p cms-style=\"font-L\">　　文/王恩博</p> \n<p cms-style=\"font-L\">　　美国财政部发布的最新数据显示，截至目前，美国国债总额首次超过37万亿美元。</p> \n<p cms-style=\"font-L\">　　这是什么概念？相当于平均每个美国人背债约10.7万美元，差不多可以买两辆特斯拉Model Y汽车。如果把这笔巨款换成1美元纸币，首尾相连可以绕地球赤道超过14圈。</p> \n<p cms-style=\"font-L\">　　如此大笔债务，美国能还得上吗？会不会有一天突然“爆雷”？</p> \n<p cms-style=\"font-L\">　　美国债务为何飞涨？</p> \n<p cms-style=\"font-L\">　　美国债务飞涨，并非一夜之间的事，而是由多年财政赤字累积而成。</p> \n<p cms-style=\"font-L\">　　美国国会预算办公室（CBO）在2020年曾预测，至2030财年美国国债才会达到37万亿美元。但2025年，便提前“撞线”。</p> \n<p cms-style=\"font-L\">　　主要原因有两个：</p> \n<p cms-style=\"font-L\">　　第一，花得太多。美国政府一边减税，一边狂撒钱——军费、医保、社会福利，样样不能少。最近通过的“大而美”法案，将债务上限进一步提高了5万亿美元，未来10年预计赤字还会增加超过3.4万亿美元（不含利息）。花得多、借得多，连利息也成了“吞金兽”。2025财年，美国光还利息就要接近1万亿美元，相当于每天睁眼先欠约27亿美元利息。</p> \n<p cms-style=\"font-L\">　　第二，收得不够。近几年，美国税收占GDP的比例总体已低于战后历史平均水平。尽管对外屡屡挥出关税大棒，但对内大规模减税叠加经济结构变化，仍然让财政收入增速赶不上支出膨胀。有专家指出，现在美国的债务每5个月就多出1万亿美元，这几乎是过去25年平均速度的两倍。</p> \n<p cms-style=\"font-L\">　　巨额债务能否还上？</p> \n<p cms-style=\"font-L\">　　很多人会说，美国不会破产，因为它可以自己印钱。</p> \n<p cms-style=\"font-L\">　　的确，美国的债务几乎全部以美元计价，而美元是其自己发行的货币。理论上，美国总能用新债换旧债，把账一直“滚”下去。美国财政部数据显示，约四分之一的美债由政府内部持有，比如社保信托基金，相当于左口袋欠右口袋。</p> \n<p cms-style=\"font-L\">　　而且，2024年美国经济总量超29万亿美元，美元是全球储备货币，美债依然是世界上最受欢迎的安全资产。国际货币基金组织（IMF）也认为，美债短期违约风险很低。</p> \n<p cms-style=\"font-L\">　　但问题是，这种借新还旧的利息成本正越来越高。</p> \n<p cms-style=\"font-L\">　　国际信用评级机构穆迪今年5月宣布，将美国主权信用评级从Aaa下调至Aa1，理由正是美国政府债务和利率支付比例增加。</p> \n<p cms-style=\"font-L\">　　此前，惠誉、标准普尔已经下调了美国的主权信用评级。这意味着，美国在三大主要国际信用机构中的主权信用评级均失去了AAA的最高等级。</p> \n<p cms-style=\"font-L\">　　还不上债会怎样？</p> \n<p cms-style=\"font-L\">　　美国知名智库布鲁金斯学会警告，如果投资者开始怀疑美国的还债能力，后果可能是多米诺骨牌式的：国债利率飙升、美元贬值、进口价格上涨，股市和债市同步大跌。</p> \n<p cms-style=\"font-L\">　　在全球金融体系中，美元的作用牵一发而动全身。据IMF数据，全球近六成外汇储备是美元，几乎所有石油、黄金、大宗商品都用美元定价。如果美国财政失控、债务爆雷，就像在金融体系的心脏引爆一颗炸弹。这不仅是美国的问题，而是全世界的系统性风险。</p> \n<p cms-style=\"font-L\">　　虽然美债短期内不太可能会像某些“爆雷预言”那样瞬间崩掉，但债务雪球越滚越大，财政空间就越被压缩。靠着经济体量和美元霸权，美国当然可以继续“躺着还钱”，但也可能在某个临界点被迫作出痛苦选择。</p> \n<p cms-style=\"font-L\">　　更重要的是，这笔账不是美国一个国家的事。全球经济已在同一条船上，一旦债务风浪翻船，浪头会打到每一个人。在这个问题上，美国该长长心了。</p> \n<p cms-style=\"font-L\"></p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4499, NULL, '走失8岁男童找到：已无生命体征', 0, 1, 25, '2025-08-13 22:30:27', '2025-08-13 22:11:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-13/doc-infkwfyr7589810.shtml', '云南发布', '<p>　　来源:云南发布</p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">走失8岁男童找到：已无生命体征</font></p>\n<p cms-style=\"font-L align-Center\"></p>\n<p cms-style=\"font-L\">　　2025年8月9日，一名8岁男童在大理镇阳和茶厂附近走失。大理市立即启动应急响应机制，组织公安、消防救援、森林消防、应急、林草“苍山卫士”、大理蓝天救援队、大理山地救援队等救援队伍及干部群众、志愿者全力持续开展搜救工作。</p>\n<p cms-style=\"font-L\"></p>\n<p cms-style=\"font-L\">　　2025年8月13日17时许，救援人员在大理镇清碧溪北侧山涧发现走失男童，已无生命体征。经现场勘验和综合调查，排除外力损伤致死，初步排除刑事案件可能。</p>\n<p cms-style=\"font-L\"></p>\n<p cms-style=\"font-L\">　　我们对孩子的离去深感痛心，向家属表示深切慰问，同时感谢社会各界在搜救过程中给予的关注与支持。</p>\n<p cms-style=\"font-L\"></p>\n<p cms-style=\"font-L\">　　相关后续工作正在开展中。</p>\n<p cms-style=\"font-L\"></p>\n<p cms-style=\"font-L align-right\">　　大理市“8·9”搜救工作组</p>\n<p cms-style=\"font-L align-right\">　　2025年8月13日</p>\n<p cms-style=\"font-L align-Center\"></p>\n<p cms-style=\"font-L\">　　编辑：马正麟</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4500, NULL, '广东揭阳一绿化带堆积大量过期药品，当地回应：属实，正在清理', 0, 2, 211, '2025-08-13 22:30:34', '2025-08-13 21:38:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/765/w550h1015/20250813/5697-665d907be9d8b7c479c72389cf51f350.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvzsr3928009.shtml', '读特新闻', '<p cms-style=\"font-L\">　　来源：读特新闻</p> \n<p cms-style=\"font-L\">　　8月10日，有网友发帖称，在揭阳市榕江边散步时发现大量过期药品，相关帖子引发网友关注。12日下午，揭阳市榕城区榕华街道办事处工作人员告诉读特新闻记者，接到记者反映后，街道及区相关职能部门已经前往现场，并发现了药品盒，现在已经在清理。“具体还需要调查。”</p> \n<p cms-style=\"font-L\">　　记者从发帖人提供的现场图片中注意到，大量未开封的白色的药品盒子堆在一个绿化带旁边，堆积面积范围较大，药盒数量超百盒。记者注意到，该药品名为“枸橼酸铋钾颗粒”。公开资料显示，该药物主要用于治疗慢性胃炎，由哈尔滨三联药业股份有限公司生产。2024年12月31日，国家药监局发布公告，枸橼酸铋钾颗粒由处方药转换为非处方药。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/765/w550h1015/20250813/5697-665d907be9d8b7c479c72389cf51f350.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/344/w550h594/20250813/ab19-497a7b4d7610dd7bd448a89b1b5116d5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"图源：网络\" data-link=\"\">\n <span class=\"img_descr\">图源：网络</span>\n</div> \n<p cms-style=\"font-L\">　　据读特新闻记者核实了解，事发地点为揭阳市榕城区临江南路边一湿地公园内。该区域紧邻榕江北河，是当地居民散步休闲的地方。为什么会堆满药品？是否会造成污染？8月12日下午，记者分别致电揭阳市榕城区市场监督管理局、揭阳市生态环境局榕城分局、榕城区卫生健康局、榕城区城市管理和综合执法局，接线工作人员均表示不了解此事。12日15时30分许，榕城区榕华街道工作人员称，根据记者提供的线索，会马上到现场核查情况。</p> \n<p cms-style=\"font-L\">　　当天16时20分许，榕城区榕华街道工作人员回复读特新闻记者称，已在现场发现药品，相关职能部门正在清理。“这个公园的环卫工作是外包的，目前在处理，相关职能部门也在现场。”上述工作人员表示，该湿地公园是居民散步的地方，猜测是有人趁人不注意乱扔的。目前，相关部门已经介入，尚未找到违法乱扔的人员。至于是否会造成污染，则还需专业部门进一步调查。</p> \n<p cms-style=\"font-L\">　　“我们争取尽快处理，非常感谢及时提供线索。”该工作人员称。</p> \n<p cms-style=\"font-L\">　　公开资料显示，榕江北河是榕江最大支流，在揭阳市榕城区双溪嘴合而为一，经牛田洋进入汕头港后奔向南海。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold color210\">[读特新闻+]</font></p> \n<p cms-style=\"font-L\">　　据中新网报道，根据《国家危险废物名录（2021年版）》，过期药品属于危险废物。随意丢弃的药品在分解后容易污染土壤和水体，从而对人和动植物造成危害。一些挥发性强的过期药品还可能成为过敏源。此外，过期药品在随意丢弃后可能会被不法商贩或不法医疗机构二次回收并再次出售，对服药者身体造成不利影响。</p> \n<p cms-style=\"font-L\">　　2022年，最高人民法院通报了一批固体废物污染环境典型案例。其中，某生化药业公司未经无害化处理，将一批超3吨的过期药品私自倾倒、处置，涉案被告人最高被判处有期徒刑十个月并罚款。</p> \n<p class=\"show_author\">责任编辑：刘德宾 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/765/w550h1015/20250813/5697-665d907be9d8b7c479c72389cf51f350.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/344/w550h594/20250813/ab19-497a7b4d7610dd7bd448a89b1b5116d5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4501, NULL, '焦点访谈丨拿奖牌 涮火锅 多彩世运遇见成都烟火', 0, 2, 231, '2025-08-13 22:30:39', '2025-08-13 21:36:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/61e7-501a25847604061587b0100fe474e7a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkvzst7707158.shtml', '央视', '<p style=\"text-align: left;\">　　目前，第12届世界运动会正在四川成都举行。这一届世运会是历史上规模最大、人数最多的一届世界运动会，也是中国体育代表团参加世运会以来，参赛项目最广、参赛人数最多的一届。今天赛程已经过半。作为全球最高水平的非奥项目综合性体育盛会，成都世运会不仅以“运动无限、气象万千”的愿景吸引着世界目光，更以独特的城市魅力、新兴项目的创新活力和全民参与的热情，为这座城市注入了前所未有的激情。从赛场上的拼搏到运动场上的娱乐，从特许商品的火爆销售到文旅融合的热潮，成都正以一场“体育+城市”的盛宴，向世界展示着这座现代化都市的东方神韵。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/61e7-501a25847604061587b0100fe474e7a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　在这片充满活力的赛场，传统与现代碰撞，力量与艺术交融。武术的东方哲学、飞盘的团队默契……每一项赛事都在重新定义体育的边界。作为一个非奥项目的比赛平台，世运会像体育界的创新实验室，为那些独具特色项目提供了广阔的舞台。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/1a44-805a00b9913156264823eb2660939478.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>成都世运会执委会副秘书长 王毅：</strong>世运会聚焦的点主要是非奥比赛项目，世运会的氛围不像奥运会那么严肃，既有竞技体育的对抗性，也强调趣味性和参与感，这是一个融合了传统与现代的体育嘉年华。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/d65e-10dde2f7d52bc6dd9f9d46d85e4ac0ec.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　本届世运会34个大项、60个分项、256个小项中，既有武术、龙舟、地掷球等传统项目，也有飞盘、跑酷、无人机竞速等新兴项目。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/b701-b4b61849501932d8f553b11e9d7c7306.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　中国体育代表团本次派出489人，其中运动员321人，参加28个大项、152个小项，参赛人数和项目数都是历史之最。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/a064-483a2e825d4f60ac0467111847ca9c60.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　世运会赛场上，比赛精彩纷呈。自从8月8日，卢卓灵在女子太极拳-太极剑的决赛中为中国代表团摘得成都世运会首枚金牌以来，截至8月11日18时，中国代表团已经在武术、潜水、滑水、泰拳等比赛中收获了14金4银2铜的成绩，暂列金牌榜第一名。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/d493-c33b7050f1f66b6d4b843d9526a306d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　世运会赛场上的火热也激发了赛场外的运动热情。8月8日，在成都锦江区仁德足球公园，哥伦比亚队和德国队进行了一场团队飞盘训练赛。赛后，哥伦比亚队的教练还与中国的飞盘爱好者们进行了一场现场教学。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/2095-7f6eed569a15b2067a5530ce22ae1bc5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　来自上海的陈杰浤是飞盘运动的资深爱好者，飞盘已经成了他生活中不可或缺的部分。这次为了观看世运会飞盘比赛，和世界的顶尖高手有学习交流的机会，他专门从上海飞到成都。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/99c1-fa426ade7676d6131191971f005eb5c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　这场学习交流吸引了来自全国70余名飞盘爱好者参与。世运会不仅点燃了飞盘爱好者的热情，也推动这项运动向更广阔的人群延伸。世运会期间，在体育场上、公园里，经常可以看到飞盘爱好者的身影。世运会的示范效应，让更多市民发现运动的乐趣，也让飞盘成为成都城市活力的新标签。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4324-ec7f21f34a0d283ceb45131453ca490c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　世运会作为非奥运项目的顶级赛事，为新兴运动提供了极佳的推广普及机会。飞盘、匹克球、跑酷等项目通过世运会的集中展示，吸引了公众关注，观众对这些运动的认知度显著提升。近年来，全市已建成87个体育公园，其中专门规划了板式网球、飞盘等新兴运动场地。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/5333-91ae22e3781067258c7b44e63283d2b3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　成都世运会27个竞赛场馆中，18个为既有场馆局部功能调整，如四川省体育馆，9个依托兴隆湖、桂溪生态公园等自然场地临时搭建。跑酷赛道设于湖岸之间，飞盘赛场融入城市绿道，践行“公园城市”理念。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/6833-de78db13e838cbad8ca581d7b9201d76.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>成都世运会执委会副秘书长 王毅：</strong>我们充分运用成都大运会场馆和现有设施，按照“绿色、节俭、必须”原则推进场馆改造，在满足国际赛事的标准基础上，充分挖掘既有设施利旧潜力，“一馆一策”深化设计方案，室内场馆不大改大建，室外场地少填少挖，最大限度减少建设规模。这种“改造+自然”的模式，既保留了城市原有风貌，又为赛事注入生态活力。</p> \n<p style=\"text-align: left;\">　　在成都，世运会的影响力并没有停留在体育场上，更是以“体育+文旅”模式激活了整座城市的活力。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/db8a-01186ceb448220a7b47a08a890d72b42.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　坐落在成都玉林路商圈的四川省体育馆是世运会泰拳和自由搏击的比赛场馆，为此，当地还在离四川省体育馆不远的地方，为世运会专门设立了仲夏消费月活动现场，泰拳表演、民谣歌手和咖啡市集吸引了大量游客驻足。凭借世运会门票或票根，游客可享受餐饮折扣、抽奖等专属福利。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/a6a6-fb9ca0891f30b64b69e0b9ad3eac075a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　在世运会开幕前，四川省就举办了“跟着赛事去旅行”的活动，通过赛事这一纽带，带动更多的境内外游客游览四川省的名山大川。在成都街头巷尾，精彩纷呈的文旅消费场景，掀起“全城悦客”热潮。为了当好世运会的东道主，成都还专门策划推出了“迎世运游成都”为主题的系列文旅活动。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/2025-2a9a5004e4001720732423929508918a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>四川成都市文化广电旅游局副局长 魏湘军：</strong>我们精心设置了7条主题线路，把成都17个最具代表性的文化体验点位串联起来。这几天，我们也看到很多国内外游客朋友和运动员在熊猫基地、武侯祠、宽窄巷子、青城山、都江堰等体验成都的文化，沉浸式感受这座公园城市、幸福成都。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4005-e71de209250190d65c1a99fa7a9546d5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　成都宽窄巷子依托世运吉祥物“蜀宝”“锦仔”变身世运主题街，世运吉祥物，搭配主题打卡墙、沿街形象架等氛围装置，生动展现“世运双宝”可爱形象。在宽窄巷子，还专门设置了“世运•天府”文化艺术展。</p> \n<p style=\"text-align: left;\">　　世运会的举行和暑期双重叠加，文旅市场持续火爆。为把赛事流量转化为文旅“留量”，做好“跟着世运游成都”这篇文章，成都市文旅部门还推出了专属优惠政策。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/957f-c5fee4e8479b149c32b5c2d1f506795f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>四川成都市文化广电旅游局副局长 魏湘军：</strong>世运会的运动员、随队官员等7类嘉宾，可以凭证件免费畅游13个景区，观看世运会比赛的观众也可以凭着票根享受市内所有国有景区的5折优惠。为了感谢志愿者的辛勤付出，在世运会结束之后，直到明年8月31日，志愿者都可以免费游览市内所有的国有景区。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/646f-fbbd7b6e631fa84dab41685432372f4d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　为让游客在成都“玩得开心、省心又省钱”，成都市文旅还分批次通过几大主流的商旅平台向游客发放旅游住宿的消费券，累计金额达到3000万元。而作为世界美食之都，成都在餐饮方面也准备了实实在在的优惠。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/f61f-a0362d8f94f31c7035f3daf64637df2b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>四川成都市商务局副局长 兰华娟：</strong>我们通过市区两级共同发放了超过3000万元的餐饮消费券，此外，持有效凭证的世运会的观众和志愿者，还可以在近万家的餐饮门店享受到额外的折扣和优惠。希望大家在成都能够玩得开心，吃得尽兴。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/81e0-5023e8e5845cb751e2b07c5ea139174e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　踏着世运会的热潮，不仅玩得开心，吃得尽兴，与世运会相关的主题商品、文创产品更是卖得火爆。位于春熙路红星广场的世运会特许商品经营店也成为市民和游客的“打卡新地标”。从美食主题盲盒到赛事徽章，特许商品以“赛事+文旅”融合创新，掀起了消费热潮。其中世运会与武侯祠联名款的“蜀宝”熊猫玩偶最为火热。</p> \n<p style=\"text-align: left;\">　　不仅仅是特许商品销售火热，世运会给成都带来了运动的热度，也为文旅消费带来了一大波人气和流量。世运会举办期间，成都的各大旅游景区和主题街区每天都是游客爆满。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/7080-7e7af13a8bb40053cb900c20a5d58060.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p style=\"text-align: left;\">　　<strong>四川成都市商务局副局长 兰华娟：</strong>我们也看到暑期叠加世运会，给成都带来了超旺的人气和流量，我们将持续打造更丰富、更多样化的消费场景，进一步提升整体的消费体验，把这次世运会带来的巨大的流量实实在在的转化为成都消费的增量。</p> \n<p style=\"text-align: left;\">　　当运动的激情与城市的脉动同频共振，成都，正以一场世界级的体育盛会，向世界递出一张新名片。从赛场上的拼搏到街头巷尾的欢腾，世运会不仅带来了竞技的荣光，更点燃了全民参与的热情，激荡着城市更新的活力。这是一次体育与文化、赛事与城市、传统与潮流的深度交融。成都，用开放包容的姿态拥抱世界，用创新务实的行动诠释“公园城市”的幸福样本。我们看到的，不仅是赛事的火热，更是体育的力量，运动带来的改变已在成都生根发芽，属于这座城市的活力故事，还在继续书写。这里是成都，一座因体育而炽热，因包容而精彩的城市。</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/61e7-501a25847604061587b0100fe474e7a2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/1a44-805a00b9913156264823eb2660939478.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/d65e-10dde2f7d52bc6dd9f9d46d85e4ac0ec.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/b701-b4b61849501932d8f553b11e9d7c7306.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/a064-483a2e825d4f60ac0467111847ca9c60.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/d493-c33b7050f1f66b6d4b843d9526a306d9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/2095-7f6eed569a15b2067a5530ce22ae1bc5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/99c1-fa426ade7676d6131191971f005eb5c9.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4324-ec7f21f34a0d283ceb45131453ca490c.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/5333-91ae22e3781067258c7b44e63283d2b3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/6833-de78db13e838cbad8ca581d7b9201d76.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/db8a-01186ceb448220a7b47a08a890d72b42.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/a6a6-fb9ca0891f30b64b69e0b9ad3eac075a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/2025-2a9a5004e4001720732423929508918a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/4005-e71de209250190d65c1a99fa7a9546d5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/957f-c5fee4e8479b149c32b5c2d1f506795f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/646f-fbbd7b6e631fa84dab41685432372f4d.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/f61f-a0362d8f94f31c7035f3daf64637df2b.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/81e0-5023e8e5845cb751e2b07c5ea139174e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/59/w550h309/20250813/7080-7e7af13a8bb40053cb900c20a5d58060.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4502, NULL, '想尽一切办法，穷尽一切力量！内蒙古自治区党委书记，赴一线指导抢险救灾', 0, 1, 5, '2025-08-14 00:30:16', '2025-08-13 23:46:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/114/w550h364/20250813/ce9c-51b7f533aecfc27c9e6767c23e483622.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-13/doc-infkwfyx5998852.shtml', '北京青年报', '<p>　　来源：北京青年报</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">据内蒙古日报8月13日消息，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">今年入汛以来，内蒙古迎来多轮强降水天气过程，</font><font cms-style=\"font-L strong-Bold\">全区8个国家站、65个区域站日降水量均突破历史极值，部分地区“三天下了一年的雨”，</font><font cms-style=\"font-L\">多地遭受严重洪涝灾害。</font></font></font></p> \n<p cms-style=\"font-L\">　　自治区党委和政府对此高度重视，自治区党委书记孙绍骋主持召开党委常委会会议传达学习习近平总书记有关重要指示精神、研究部署防汛抢险救灾工作，自治区党委副书记、自治区人民政府主席王莉霞多次召开会议调度有关情况、部署相关任务，有关方面及时启动应急响应，持续加强预报预测和会商研判、高密度发布预警信息，深入开展重点部位隐患排查，精准调配救援力量物资，扎实做好防汛抢险救灾各项工作。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/114/w550h364/20250813/ce9c-51b7f533aecfc27c9e6767c23e483622.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/news/crawl/101/w550h351/20250813/fc8f-cbe5a1853fb8e17b74c37f744c9aa0f8.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">土默特左旗、土默特右旗、托克托县汛情灾情较为严重</font><font cms-style=\"font-L\">，孙绍骋和王莉霞对此十分关注，先后多次赶赴抢险救灾现场察看情况。</font></p> \n<p cms-style=\"font-L\">　　8月8日孙绍骋来到土默特右旗实地了解有关情况，现场指导抢险救灾工作，13日又赶赴托克托县，详细察看防汛、排水等情况，并到安置区看望受灾群众。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">他说，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">要想尽一切办法，穷尽一切力量，全力做好防汛抢险工作</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">。要加快排水，多上大型设备集中攻坚，尽快将水位降下来。要安置好受灾群众，保障好他们的生活，及时做好灾后重建工作，尽快让受灾群众返回家园。</font></font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">据悉，为有效应对哈素海地区近期出现的汛情，在国家防汛抗旱总指挥部的指导和支持下，</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">自治区专门成立哈素海防汛应急处置工作前线指挥部，自治区党委常委、自治区人民政府常务副主席黄志强任总指挥</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">，自治区人民政府副主席代钦任副总指挥。</font></font></p> \n<p cms-style=\"font-L\">　　指挥部成立以来，累计调动军区、武警、消防救援和中国安能集团等央企、民兵组织、社会救援力量及乡镇基干队伍2.7万余人，大功率排水车、挖机、装载机等大型机械5600余台次，消防车、救护车等救援车辆6800余台次和舟艇460余台次，组织开展巡堤、排水、抢险、救援、转移安置等工作。目前，共转移安置人口3.1万人，未发生人员伤亡，哈素海退水渠溃口和大黑河溃口全部完成封堵，哈素海水库水位已降至校核水位以下。</p> \n<p cms-style=\"font-L\">　　当前仍处于“七下八上”防汛关键期。孙绍骋要求各级各有关方面始终绷紧弦，认真贯彻落实习近平总书记重要指示精神，强化底线思维、极限思维，紧盯病险水库、山洪沟、险工险段、工矿企业、旅游景区、城市地下空间等重点区域重点部位，进一步加大查险排险力度，以“时时放心不下”的责任感扎实做好风险预报预警、隐患排查整治、应急值班值守等工作，确保群众安全度汛。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\"><font cms-style=\"font-L strong-Bold align-Center\">编辑｜余晖</font></font></font></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/114/w550h364/20250813/ce9c-51b7f533aecfc27c9e6767c23e483622.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/101/w550h351/20250813/fc8f-cbe5a1853fb8e17b74c37f744c9aa0f8.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4503, NULL, '台风“杨柳”在福建漳浦县沿海再次登陆', 0, 2, 116, '2025-08-14 01:30:13', '2025-08-14 00:42:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/723/w550h173/20250814/ce4b-90bec8e47ddbb750fbc80b639cd9414b.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkwnhm3706854.shtml', '央视新闻客户端', '<p>　　据福建省气象台消息，今年第11号台风“杨柳”于8月14日0时30分前后在福建漳州市漳浦县沿海再次登陆。</p> \n<p>　　（总台记者 吴燕敏）</p> \n<p>　　　<strong>　相关新闻：</strong></p> \n<p>　　<strong>台风“杨柳”将再次登陆！广东发布山洪灾害风险预警、有地区已“疯狂倒水”1小时、多地停课、景区关闭，广州2区有地质灾害风险（广州日报）</strong></p> \n<p>　　今明两天又是持续雨雨雨</p> \n<p>　　大家的大件衣物都洗晒好了吗？</p> \n<p>　　13日广东多地还是高温依旧</p> \n<p>　　韶关南雄录得全省最高气温37.3℃</p> \n<p>　　但马上暴雨就来……</p> \n<p>　　今年第11号台风“杨柳”的中心已于13日13时前后在台湾台东县太麻里乡沿海登陆，登陆时中心附近最大风力有14级（42米/秒，强台风级）。预计，“杨柳”将于13日夜间至14日凌晨在福建厦门到广东汕头一带沿海再次登陆。</p> \n<p>　　据广东天气，2025年8月13日22时，受台风“杨柳”螺旋雨带影响，过去1小时揭阳惠来县前詹镇出现13级阵风（40.7米/秒），另外伴随强降水，揭阳惠来县靖海镇1小时疯狂倒水87毫米，当地暴雨红色预警信号生效中。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/723/w550h173/20250814/ce4b-90bec8e47ddbb750fbc80b639cd9414b.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　截至发稿前，</p> \n<p>　　广州全区台风白色预警生效中。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/700/w314h386/20250814/b5eb-9e8aac6602454d755d408989d3e6baef.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　黄埔区、从化区各一街道</p> \n<p>　　须防范地质灾害</p> \n<p>　　广州预警发布中心8月13日18时02分发布消息：经广州市规划和自然资源局与市气象局联合会商，预计未来24小时黄埔区永和街道，从化区江埔街道地质灾害气象风险预警级别为3级。</p> \n<p>　　上述地区地质灾害发生风险较高，请各行业主管单位按照各自职责做好本行业本领域内地质灾害防治工作，特别是对房前、屋后、人工边坡和道路交通沿线边坡加强巡查。提醒风险隐患区域附近的居民、厂矿、学校、企事业单位密切关注天气预报和地质灾害气象风险预警，发现险情及时果断撤离受威胁人员。</p> \n<p>　　广东这些区域存在山洪灾害风险</p> \n<p>　　广东省水利厅于8月13日18时发布山洪灾害风险预警。根据广东省山洪灾害监测预报预警平台和综合分析研判，预计未来24小时：惠州龙门县，局地发生山洪灾害可能性很大（红色预警）。</p> \n<p>　　河源东源县、龙川县、紫金县，惠州博罗县，汕尾陆河县，梅州大埔县、丰顺县、梅江区、梅县区、平远县、五华县、兴宁市，广州从化区，揭阳揭东区、揭西县、普宁市，清远佛冈县、英德市，韶关翁源县、新丰县，潮州潮安区、饶平县，局地发生山洪灾害可能性大（橙色预警）。</p> \n<p>　　河源源城区、连平县、和平县，肇庆广宁县、怀集县，惠州惠东县，梅州蕉岭县，清远清城区、清新区、阳山县、连南瑶族自治县、连山壮族瑶族自治县、连州市，汕头潮阳区，汕尾陆丰市，韶关乐昌市、南雄市、曲江区、仁化县、始兴县、乳源瑶族自治县、武江区、浈江区，局地发生山洪灾害可能性较大（黄色预警）。</p> \n<p>　　其他地区也可能因局地短历时强降水引发山洪灾害。</p> \n<p>　　受台风“杨柳”影响</p> \n<p>　　部分进出海南岛列车停运</p> \n<p>　　8月13日，因受台风“杨柳”影响， 铁路部门将对部分列车调整运行秩序，具体如下：</p> \n<p>　　8月13日出海南岛列车Z502次、K512次、Z112次停运。8月15日进海南岛列车Z501次、K511次、Z111次停运。</p> \n<p>　　13日杭深高铁、甬广高铁、梅汕高铁、梅龙高铁部分列车停运，14日10时30分前以上高铁线路列车全部停运，预计10时30分后各停运线路列车根据实际影响情况陆续恢复开行。</p> \n<p>　　广东多地停课</p> \n<p>　　受台风“杨柳”影响，潮州全市中小学、幼儿园、托儿所、培训机构等停课。</p> \n<p>　　梅州梅江、梅县、兴宁、五华、丰顺、平远、大埔地区的中小学、幼儿园、培训机构等停课。</p> \n<p>　　停课期间，请家长切实履行对子女的监护职责，密切配合学校做好安全教育工作，确保学生安全。同时，密切留意气象部门预警信息，及时做好避险工作。</p> \n<p>　　广东多个景区关闭</p> \n<p>　　汕头市所有A级旅游景区于8月13日14时前关停。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/360/w468h692/20250814/1991-79d20e7b974f79226af019cbb93840b4.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　惠州惠东县A级旅游景区（海滨温泉旅游区、惠州巽寮国际滨海旅游度假区、惠州海龟湾旅游区、好招楼湿地旅游景区、高潭中洞红色旅游区、广东梁化森林公园景区、横江贸宝旅游景区、白马易吉旅游景区、栖野·绿石河谷旅游景区、高潭旅游区）于8月13日18时起暂停对外开放，开放时间另行通知。</p> \n<p>　　8月12日起，汕尾市红海湾旅游区、金町湾旅游度假区、金厢滨海红色旅游区、上海外滩旅游区等景区发布闭园公告，暂停开放。</p> \n<p>　　台风影响期间，请广大游客不要前往受强降雨、台风天气影响的区域游玩；切勿参与非法涉海旅游项目，靠近景区山体边坡等危险范围；切勿擅自进入未开发、未对社会公众开放的无居民海岛、海滩、礁石、野景点等不明区域开展游览、探险、戏水、宿营等活动。</p> \n<p>　　广州或有</p> \n<p>　　8级左右短时大风、短时强降水、局地龙卷等</p> \n<p>　　强对流天气</p> \n<p>　　广东省气象台预计，受台风“杨柳”影响，8月14日白天到夜间，粤北和珠三角北部有暴雨到大暴雨，局部特大暴雨。</p> \n<p>　　广州市气象台预计，8月14日—15日早晨受“杨柳”影响，广州有暴雨到大暴雨过程，并伴有8级左右短时大风、短时强降水、强雷电、局地龙卷等强对流天气。8月15日白天起降水减弱，以雷阵雨天气为主。</p> \n<p>　　广东具体预报：</p> \n<p>　　8月14日白天到夜间，粤北、惠州北部、广州北部、肇庆北部自东向西有暴雨到大暴雨局部特大暴雨（面上雨量60～120毫米，最大雨量300毫米左右），粤东、珠江三角洲其余市县有大雨到暴雨局部大暴雨，粤西市县有中雨局部暴雨。最高气温：粤西市县31～34℃，其余市县普遍介于28～30℃。</p> \n<p>　　8月15日白天，降水明显减弱，粤西、珠江三角洲和清远中到大雨局部暴雨转阵雨，其余大部市县多云，有阵雨。最高气温：全省市县普遍介于30～33℃。</p> \n<p>　　8月15日夜间—16日，粤西市县多云，有（雷）阵雨局部暴雨，其余市县晴到多云，局部有（雷）阵雨。最高气温：中北部市县33～35℃，其余市县30～33℃。</p> \n<p>　　广州具体预报：</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/159/w550h409/20250814/f32f-fc33f64d0f2fc5bfe9f3cb8e3e181ae2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　遇暴雨天气，</p> \n<p>　　应该如何进行科学应对？</p> \n<p>　　↓↓↓↓</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/edb1-fd11c1ec7a323fde5a3fe4bede62d3bb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/dfcd-e942ce56df5fb5805dad96739b34e14e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　台风来袭</p> \n<p>　　我们应该如何应对？</p> \n<p>　　↓↓↓</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/254/w550h1304/20250814/daf4-cddafaa4d6cb8b2d6b79d874b926999f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　请大家保持关注，</p> \n<p>　　留意最新预报预警！</p> \n<p>　　转发，提醒身边人！</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/hot_zt/subject-175508478118\" target=\"_blank\">关注台风“杨柳”实时路径</a> \n <a href=\"https://news.sina.cn/zt_d/subject-1755104309\" target=\"_blank\">台风“杨柳”再次登陆</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/723/w550h173/20250814/ce4b-90bec8e47ddbb750fbc80b639cd9414b.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/700/w314h386/20250814/b5eb-9e8aac6602454d755d408989d3e6baef.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/360/w468h692/20250814/1991-79d20e7b974f79226af019cbb93840b4.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/159/w550h409/20250814/f32f-fc33f64d0f2fc5bfe9f3cb8e3e181ae2.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/edb1-fd11c1ec7a323fde5a3fe4bede62d3bb.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/dfcd-e942ce56df5fb5805dad96739b34e14e.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/254/w550h1304/20250814/daf4-cddafaa4d6cb8b2d6b79d874b926999f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4504, NULL, '江苏淮安市盱眙县发生3.3级地震 震源深度12千米', 0, 2, 78, '2025-08-14 01:30:21', '2025-08-14 00:25:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/600/w800h600/20250814/1fd1-0204078d785f11130c192969b349f451.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkwfyx6007693.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/600/w800h600/20250814/1fd1-0204078d785f11130c192969b349f451.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　中国地震台网正式测定：8月14日0时13分在江苏淮安市盱眙县（北纬33.03度，东经118.68度）发生3.3级地震，震源深度12千米。</p> \n<p cms-style=\"font-L\">　　（总台央视记者 张腾飞）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/600/w800h600/20250814/1fd1-0204078d785f11130c192969b349f451.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4505, NULL, '波兰斥资38亿美元升级全部F-16战斗机', 0, 4, 157, '2025-08-14 06:30:15', '2025-08-14 06:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250814/9f14-8eefb7b979135a1c9fd99874d296f805.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwwwn2649368.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250814/9f14-8eefb7b979135a1c9fd99874d296f805.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，波兰与美国签署价值38亿美元的合同，计划将本国所有F-16战斗机升级至“Block 72”标准。</p> \n<p cms-style=\"font-L\">　　在波兰中北部比得哥什第二军事航空工厂举行的签约仪式上，波兰副总理兼国防部长卡梅什表示，此次现代化改造将涵盖全部48架F-16C/D Block 52+战机，<font cms-style=\"font-L strong-Bold\">将其升级为现有最先进的版本之一</font>。</p> \n<p cms-style=\"font-L\">　　卡梅什表示，升级后的F-16将增强侦察能力，并提升与F-35等已订购装备的协同作战能力。（总台记者 徐明）</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/116/w550h366/20250814/9f14-8eefb7b979135a1c9fd99874d296f805.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4506, NULL, '两艘非法移民船在意大利南部海域倾覆 至少27人死亡', 0, 4, 96, '2025-08-14 06:30:38', '2025-08-14 03:25:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/425/w700h525/20250814/db21-458de5a3d9be448b5ebca61255ad3b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwsqq2767062.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/425/w700h525/20250814/db21-458de5a3d9be448b5ebca61255ad3b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△意大利兰佩杜萨岛的海警船（图源：安莎社）\">\n <span class=\"img_descr\">△意大利兰佩杜萨岛的海警船（图源：安莎社）</span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，两艘载有非法移民的船只在意大利南部兰佩杜萨岛附近海域倾覆。<font cms-style=\"font-L strong-Bold\">据意大利安莎社报道，事故已造成至少27人死亡</font>，多人失踪。</p> \n<p cms-style=\"font-L\">　　当天，意大利方面发现沉船事故后展开搜救，共60人被救起。据生还者透露，12日夜间两艘船从利比亚出发，一艘船只先进水开始沉没，船上非法移民被迫转移至另一艘船，导致第二艘船倾覆。</p> \n<p cms-style=\"font-L\">　　意大利方面仍在相关海域继续搜救，并对事故展开调查。</p> \n<p cms-style=\"font-L\">　　（总台记者 李耀洋）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/425/w700h525/20250814/db21-458de5a3d9be448b5ebca61255ad3b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4507, NULL, '墨西哥总统：向美国引渡26名毒枭基于国家安全考虑', 0, 4, 130, '2025-08-14 06:30:55', '2025-08-14 02:45:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/106/w1024h682/20250814/98a1-a941e6e218d9d3cc9e45a23ab310a3fd.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwsqq2763959.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/106/w1024h682/20250814/98a1-a941e6e218d9d3cc9e45a23ab310a3fd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△墨西哥总统辛鲍姆（资料图）\">\n <span class=\"img_descr\">△墨西哥总统辛鲍姆（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，墨西哥总统辛鲍姆表示，向美国移交26名贩毒集团高级头目是基于墨西哥国家安全考虑的主权决定。</p> \n<p cms-style=\"font-L\">　　辛鲍姆强调，引渡决定是墨西哥国家安全委员会基于“国家安全”考量作出的决策。移交行动严格遵循《国家安全法》规定、应美国司法部请求实施，美方承诺不对这些人寻求死刑判决。</p> \n<p cms-style=\"font-L\">　　被引渡人员包括墨西哥新一代贩毒集团头目阿比盖尔·冈萨雷斯（绰号“库伊尼”）、“圣殿骑士团”首领塞尔万多·戈麦斯（绰号“图塔”），以及与锡那罗亚贩毒集团头目伊斯梅尔·赞巴达（绰号“梅奥”）、蒂华纳卡特尔、“矮子”古兹曼之子团伙有关联的多名罪犯。（总台记者 马天静 盛嘉迪）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">墨西哥驱逐26名美国通缉的贩毒集团头目&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/106/w1024h682/20250814/98a1-a941e6e218d9d3cc9e45a23ab310a3fd.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4508, NULL, '野火蔓延 加拿大艾伯尼港进入紧急状态', 0, 4, 36, '2025-08-14 06:31:03', '2025-08-14 01:55:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/230/w1200h630/20250814/2cc5-ecb55a41785d22cabd759656b4bdb65c.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwsqt5763453.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/230/w1200h630/20250814/2cc5-ecb55a41785d22cabd759656b4bdb65c.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间13日，加拿大西部不列颠哥伦比亚省温哥华岛艾伯尼港附近的<font cms-style=\"font-L strong-Bold\">野火已烧毁超过20平方公里森林</font>。为应对野火，<font cms-style=\"font-L strong-Bold\">艾伯尼港当天宣布进入紧急状态</font>，温哥华岛南部社区居民进行了疏散。</p> \n<p cms-style=\"font-L\">　　该省野火管理局当天表示，火势目前已达到4级和5级，这意味着火势正以极度旺盛的速度燃烧。</p> \n<p cms-style=\"font-L\">　　由于预计烟雾将在未来24至48小时内持续笼罩温哥华岛内陆地区，加拿大环境部也发布了针对该地区的特别空气质量声明，要求限制户外活动时间。</p> \n<p cms-style=\"font-L\">　　目前，不列颠哥伦比亚省约有90处野火肆虐，其中7处已被列为失控。</p> \n<p cms-style=\"font-L\">　　（总台记者 张森）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">过火面积近1400公顷 加拿大不列颠哥伦比亚省野火加速蔓延&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/230/w1200h630/20250814/2cc5-ecb55a41785d22cabd759656b4bdb65c.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4509, NULL, '安理会强烈反对苏丹快速支援部队建立“平行政府”', 0, 4, 184, '2025-08-14 06:31:10', '2025-08-14 01:52:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/700/w900h600/20250814/f3ba-3b21cea1746c6b47b4131366fb43faa2.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwnhv5893789.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/700/w900h600/20250814/f3ba-3b21cea1746c6b47b4131366fb43faa2.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　联合国安理会当地时间13日发表声明，坚决拒绝苏丹快速支援部队在其控制地区建立平行治理机构，认为此举直接威胁苏丹的领土完整与统一，<font cms-style=\"font-L strong-Bold\">可能加剧持续冲突，导致国家分裂，并恶化严峻的人道主义危机</font>。</p> \n<p cms-style=\"font-L\">　　安理会重申坚定支持苏丹的主权、独立、统一和领土完整，并警告任何破坏这些原则的单方面行动将危及苏丹未来和地区和平。<font cms-style=\"font-L strong-Bold\">安理会呼吁冲突各方立即恢复谈判，达成持久停火，推动包容性政治进程</font>，并在民选政府的过渡期后实现民主选举，以满足苏丹人民对和平与繁荣的诉求。</p> \n<p cms-style=\"font-L\">　　声明特别提及安理会第2736号决议，要求快速支援部队解除对达尔富尔地区法希尔的围困，并停止军事行动，以防饥荒和极端粮食不安全进一步扩散。安理会对有关苏丹快速支援部队在法希尔发起新攻势的报道表示严重关切，并敦促其允许人道救援不受阻碍地进入。</p> \n<p cms-style=\"font-L\">　　安理会还谴责近期在科尔多凡地区造成大量平民死亡的袭击事件，并对冲突对人道救援造成的影响深表忧虑。<font cms-style=\"font-L strong-Bold\">安理会要求冲突各方保护平民、遵守国际人道法、落实《吉达宣言》</font>，并追究严重违法者的责任。</p> \n<p cms-style=\"font-L\">　　安理会呼吁避免任何煽动冲突的外部干涉，支持和平努力，并全面执行包括第2750号在内的相关决议。</p> \n<p cms-style=\"font-L\">　　声明最后重申，安理会将继续与苏丹人民站在一起，并全力支持联合国秘书长苏丹问题特使拉姆丹·拉马姆拉推动政治对话、实现冲突可持续解决的努力。</p> \n<p cms-style=\"font-L\">　　（央视记者 徐德智）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">苏丹快速支援部队主导的联盟宣布组建“平行政府”&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/700/w900h600/20250814/f3ba-3b21cea1746c6b47b4131366fb43faa2.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4510, NULL, '哈马斯代表团与埃及官员磋商：希望尽快恢复加沙停火谈判', 0, 4, 60, '2025-08-14 06:31:19', '2025-08-14 00:16:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/533/w800h533/20250814/69a2-a7946c0a4091126bd15d0eb147101ac0.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwsqm7371255.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/533/w800h533/20250814/69a2-a7946c0a4091126bd15d0eb147101ac0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△加沙地带（资料图）\">\n <span class=\"img_descr\">△加沙地带（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>当地时间13日获悉，巴勒斯坦伊斯兰抵抗运动（哈马斯）代表团当天与埃及情报总局局长拉沙德在开罗举行会谈。双方就如何推进加沙地带停火进程进行磋商，哈马斯代表团表示<font cms-style=\"font-L strong-Bold\">希望尽快恢复加沙停火谈判</font>。</p> \n<p cms-style=\"font-L\">　　双方会谈的重点是推动加沙地带局势降温，埃及正在加紧与各方沟通以达成停火协议，为结束冲突铺平道路。哈马斯对埃及协助援助物资进入加沙、为当地民众提供救济的努力表示赞赏。</p> \n<p cms-style=\"font-L\">　　哈马斯13日凌晨发表声明说，哈马斯领导层代表团已抵达开罗，与埃方官员就加沙地带最新情况举行会谈。双方将讨论加沙地带停火、为加沙地带民众提供援助，以及协调巴勒斯坦内部、巴勒斯坦与埃及的关系等问题。</p> \n<p cms-style=\"font-L\">　　据以色列国防军发布的声明，以军总参谋长扎米尔13日举行会议，提出并批准了以军在加沙地带下一阶段行动计划的“核心框架”。</p> \n<p cms-style=\"font-L\">　　以总理内塔尼亚胡12日对媒体表示，以色列与哈马斯就在加沙地带实现短期停火、部分被扣押人员获释达成协议的可能性“已成过去时”。（总台记者 吴爱民）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">哈马斯代表团将与埃及官员就加沙停火等问题举行会谈&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">以军批准加沙地带未来作战计划框架&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/533/w800h533/20250814/69a2-a7946c0a4091126bd15d0eb147101ac0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4511, NULL, '特朗普：将寻求长期接管华盛顿特区警察部队', 0, 4, 207, '2025-08-14 06:31:26', '2025-08-14 00:07:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/107/w1024h683/20250814/48a3-5f3ad3b0d1064b865adda32b24ad1f1a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkwnhm3717293.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/107/w1024h683/20250814/48a3-5f3ad3b0d1064b865adda32b24ad1f1a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△特朗普（资料图）\">\n <span class=\"img_descr\">△特朗普（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">央视记者</font></font>当地时间8月13日获悉，美国总统特朗普当日在肯尼迪中心发表讲话时表示，<font cms-style=\"font-L strong-Bold\">他将寻求联邦政府对华盛顿特区警察部队的长期控制</font>。</p> \n<p cms-style=\"font-L\">　　根据华盛顿特区《地方自治法》第七百四十条，除非国会延长，否则特朗普对该市执法部门的控制期限只能为30天。</p> \n<p cms-style=\"font-L\">　　据美国广播公司（ABC）报道，当被问及是否会与国会合作，延长允许临时控制地方执法部门的紧急授权时，特朗普表示，国会需要通过一项解决犯罪问题的法案，该法案应包括延长联邦警察控制华盛顿特区的30天期限。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/33fc-833983b9d4eafceff731bc4f4731c855.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　特朗普11日宣布首都华盛顿进入“治安紧急状态”，并将首都警察局置于联邦直接管控之下。华盛顿市长鲍泽表示，华盛顿的暴力犯罪率现已降至30年来最低点，联邦政府的行为“令人不安”。12日，美国国民警卫队进驻首都华盛顿。（央视记者 刘骁骞）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">美国国民警卫队进驻首都华盛顿&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\">以治安之名行党争之实 美联邦政府为何要对华盛顿等地下手？&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754925007\" target=\"_blank\">特朗普宣称要“解放首都”</a> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/107/w1024h683/20250814/48a3-5f3ad3b0d1064b865adda32b24ad1f1a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/33fc-833983b9d4eafceff731bc4f4731c855.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4521, NULL, '前7月全省机场客货吞吐量双增长', 0, 1, 10, '2025-08-14 07:30:33', '2025-08-14 07:23:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkwwwf3487748.shtml', '江苏省人民政府网站', '<p cms-style=\"font-L\">　　8月13日，记者从东部机场集团获悉，前7月集团客货运量均显著增长，呈现“客货两旺”态势，航空枢纽能级显著提升。</p>\n<p cms-style=\"font-L\">　　客运方面，受益于暑运期间学生流、家庭游、团队游等多重客流叠加，前7月集团旅客吞吐量2922万人次，同比增长5.7%。其中，南京机场客流量实现同比增长，执行率和客座率创历史新高；其余6家成员机场旅客吞吐量同比增幅均达到两位数。货运方面，前7月货邮吞吐量30万吨，同比增长15.3%。南京、徐州、常州、淮安等6家机场实现两位数增长，其中淮安机场同比增幅高达72.6%。今年以来，集团新开南京至墨西哥城、首尔，淮安至大阪等全货机航线，加密南京至卢森堡等航线，复航盐城至大阪航线，助力“中国制造”走向全球。</p>\n<p cms-style=\"font-L\">　　基础工程建设同步推进。目前，南京禄口机场三期工程预可行性研究报告已上报审批；淮安机场航站区改扩建取得进展，X2滑行道基本建成，航站楼桩基工程加速推进；盐城机场飞行区等级提升工程有序实施。此外，徐州、常州、扬泰等机场的改扩建项目均按计划稳步推进。</p>\n<p cms-style=\"font-L\"></p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4522, NULL, '女厅官田蓉被“双开”：违规拥有非上市企业股份、收受巨额财物', 0, 1, 23, '2025-08-14 07:30:40', '2025-08-14 06:51:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/112/w550h362/20250814/774e-f3a9e8747ccc3d08cccbfefd637e0834.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkwwwf3482910.shtml', '江南都市报', '<p cms-style=\"font-L\">　　来源：江南都市报</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">8月13日，中央纪委国家监委网站通报，据</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">四川省纪委监委消息：</font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">日前，经四川省委批准，四川省纪委监委对成都市政协原党组副书记、副主席田蓉严重违纪违法问题进行了立案审查调查。</font></font></p> \n<p cms-style=\"font-L\">　　经查，田蓉丧失理想信念，背弃初心使命，对党不忠诚不老实，对抗组织审查；罔顾中央八项规定精神，多次接受可能影响公正执行公务的旅游活动安排；违反组织原则，在组织谈话时不如实向组织说明问题；廉洁底线失守，长期违规收受礼金，违规拥有非上市企业股份；违反生活纪律；将党和人民赋予的公权力异化为谋取私利的工具，利用职务便利，为他人在企业经营等方面谋取利益，并单独或与他人共同收受财物，数额特别巨大。</p> \n<p cms-style=\"font-L\">　　田蓉严重违反党的政治纪律、组织纪律、廉洁纪律和生活纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予严肃处理。依据《中国共产党纪律处分条例》《中华人民共和国监察法》《中华人民共和国公职人员政务处分法》等有关规定，经四川省纪委常委会会议研究并报四川省委批准，决定给予田蓉开除党籍处分；由四川省监委给予其开除公职处分；终止其成都市第十四次党代会代表资格；收缴其违纪违法所得；将其涉嫌犯罪问题移送检察机关依法审查起诉，所涉财物一并移送。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/112/w550h362/20250814/774e-f3a9e8747ccc3d08cccbfefd637e0834.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据政事儿消息，今年2月5日消息，成都市政协党组副书记、副主席田蓉涉嫌严重违纪违法被查。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/28/w550h278/20250814/d767-25a0a5e5775be4b628ddd5d36b7fde77.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　官方简历介绍，田蓉，女，土家族，1962年12月生，湖南龙山人，大学学历。1984年7月参加工作，1988年3月加入中国共产党。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L\"><font cms-style=\"font-L\">她历任：西南民族学院法律系辅导员、团总支书记，院团委副书记、书记；共青团成都市委组织部部长、学校部部长、宣传部部长、机关党委书记；成都市计生委党组成员、副主任，</font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">市妇联党组书记、主席，市广播电视局党组书记、局长</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">等职。</font></font></p> \n<p cms-style=\"font-L\">　　2007年12月开始，她历任成都市温江区委副书记、区长，区委书记、区人大常委会主任，区委书记；2012年9月起历任成都市政府党组成员、副市长，市委常委、宣传部部长。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\"><font cms-style=\"font-L\">2022年4月，田蓉任成都市政协党组副书记、副主席</font></font></font><font cms-style=\"font-L\"><font cms-style=\"font-L\">，至被查。</font></font></p> \n<p cms-style=\"font-L align-right\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\">来</font></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\">源：中央纪委国家监委网站、政事儿</font></font><font cms-style=\"font-L strong-Bold\"></font><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L\">值班编辑：肖琳琪</font></font></font><font cms-style=\"font-L strong-Bold\"></font></font></p> \n<p cms-style=\"font-L align-right\"></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/112/w550h362/20250814/774e-f3a9e8747ccc3d08cccbfefd637e0834.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/28/w550h278/20250814/d767-25a0a5e5775be4b628ddd5d36b7fde77.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4523, NULL, '男童大理走失背后的研学乱象：有私人机构挂靠旅行社，销售人员暗示可隐瞒孩子病史报名', 0, 1, 25, '2025-08-14 07:31:16', '2025-08-13 18:52:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250813/267/w640h427/20250813/9b0c-f6abaebc4c67eb79cf278569361c09c4.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkvvkv7792921.shtml', '成都商报', '<blockquote> \n <p>　　近日，“自闭症男孩在大理苍山夏令营活动中失联”事件引发关注。据此前多家媒体报道，这名8岁男孩来自北京，疑似患有自闭症。根据当地警方通报，8月9日下午，该男孩在大理市大理镇阳和茶厂附近走失，至今仍未找到。</p> \n</blockquote> \n<p>　　寻找失踪男孩牵动着无数人的心，同时也引发了人们对研学机构正规性的思考。研学旅游中，孩子的安全如何保障？研学机构的资质是否正规？自闭症等特殊儿童能否独立参团？带着种种问题，红星新闻记者以一名多动症儿童家长的身份暗访了多家研学机构。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250813/267/w640h427/20250813/9b0c-f6abaebc4c67eb79cf278569361c09c4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲资料图片 图据图虫创意\">\n <span class=\"img_descr\">▲资料图片 图据图虫创意</span>\n</div> \n<p>　　<strong>报名家长：</strong></p> \n<p>　　<strong>为找一家正规且合适的研学机构</strong></p> \n<p>　　<strong>足足做了一个月准备</strong></p> \n<p>　　研学旅行，一种研究性学习和旅行体验相结合的校外教育活动。近些年里，研学旅游热潮正在全国各地上演。据艾媒咨询数据显示，2023年中国研学游行业市场规模已达1469亿元，预计2028年将突破3000亿元。</p> \n<p>　　早在2016年，教育部等11部门就曾出台《关于推进中小学生研学旅行的意见》（下称《意见》）的指导文件，其中提到：各地积极探索开展研学旅行，部分试点地区取得显著成效，在促进学生健康成长和全面发展等方面发挥了重要作用，积累了有益经验。</p> \n<p>　　然而研学热潮背后，市场乱象也不断涌现。上述《意见》中也指出：一些地区在推进研学旅行工作过程中，存在思想认识不到位、协调机制不完善、责任机制不健全、安全保障不规范等问题，制约了研学旅行有效开展。</p> \n<p>　　北京青年报2024年发表的报道中就曾讲述多个“研学踩坑”案例。如一位参加某教培机构组织的“海南户外自然探索研学团”家长，就通过黑猫投诉平台投诉称，该研学团每人费用10780元，一大一小费用共21560元，但宣传的6天实际游玩只有4天，前后两天都是接送机，没有任何行程。此外，研学团里全程没有导游讲解，也没有任何有关海南或三亚的地理、历史、人文等知识讲解，带队老师只是每天通报行程等。</p> \n<p>　　今年7月下旬，张女士带着8岁的儿子刚在贵州结束了一次亲子研学旅行。“一来想让孩子亲近大自然，二来也想寓教于乐，让孩子在游山玩水中开拓眼界。”在张女士看来，正规合格的研学旅游团，能配备安全和生活导师、在不同景点请到讲解专家，是一家三口单独出游难以全部实现的。</p> \n<p>　　张女士此次6天的研学团，不含往返机票，亲子报名费为9200元，在她看来是值得的。而为了找到这家正规且合适的研学机构，张女士告诉红星新闻，她足足做了一个月的准备。</p> \n<p>　　一开始，各大研学机构的精美宣传图册、销售人员天花乱坠的讲解也让张女士挑花了眼。但在确定自然研学这一主题后，她便开始比对各大机构的游学路线：“比如线路里有很小众的景区、丛林探险，我就不会去，因为担心不安全。我也会问机构这条线开了多少年，只运营了两三年那也不行，因为怕他们没经验。”</p> \n<p>　　除了优选研学路线，张女士也会检查带团者的资格证：“我的要求是，带队者至少有一个有急救证、领队有导游证、机构得有旅行社资质、生活老师最好有教师资格证……”就这样一点一点咨询比对，张女士才选到了一家自己心仪的研学机构：“但这样也很累，我很希望这个市场规范起来，别再让家长为了不踩坑拿着放大镜去选机构。</p> \n<p>　　<strong>孩子有疾病能报名吗？</strong></p> \n<p>　　<strong>有销售称可瞒报，并授意选填无相关病史</strong></p> \n<p>　　为了解更多研学旅游情况，记者以一名多动症儿童家长的身份询问了多家研学机构。有部分机构销售人员暗示记者：“可以为孩子选填无精神病史。”</p> \n<p>　　红星新闻记者随机咨询了一家开展“神农架森林科考独立营”的研学机构。根据销售人员介绍，该研学行程为期6天，面向7岁至13岁未成年人进行独立研学旅行，不含往返机票，报名费近8000元。完成研学后，机构将为孩子颁发“科考实践认证”等证书。</p> \n<p>　　记者以家长身份向销售人员表示孩子患多动症，需每日服用精神类药物，是否能独立参团？该销售人员表示需向上级领导请示，但很快，对方给出了肯定的回答：“我们会跟带队老师说明情况，让老师多照顾你家孩子，再签署一份《用药委托书》即可。”</p> \n<p>　　而当红星新闻记者尝试在平台报名时，页面随即弹出一则《健康风险提示》，其中明确提醒：如罹患哮喘、身体残疾、心理或精神类疾病，请勿报名本项目。</p> \n<p>　　不过，当记者就这份《健康风险提示》询问研学机构如何应对时，对方称，“我们之前带团也有和你家孩子类似情况的，问题不大。”对方还暗示记者，可瞒报实际情况，直接点击下方的“不存在上述健康风险”即可。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250813/120/w1440h1080/20250813/2a38-2d034b4d7287afff653fd2b9cd038bde.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲研学机构销售人员暗示记者可隐瞒病史报名\">\n <span class=\"img_descr\">▲研学机构销售人员暗示记者可隐瞒病史报名</span>\n</div> \n<p>　　红星新闻记者注意到，在各大社交媒体和在线旅游预定平台上，不少机构推出了所谓“自然疗愈+研学”的新概念，行程中也大多涉及野外徒步和生存锻炼。而当记者询问孩子患多动症、自闭症、焦虑症等能否报名时，机构几乎都给出了肯定的回答。</p> \n<p>　　但当记者询问对“特殊儿童”是否有特殊照顾，或团队配备相应的心理学从业者时，不少机构闪烁其词：“我们肯定会给予特殊儿童更多关注，带队老师很有经验，能应付得了。”</p> \n<p>　　而这样的做法在专业人士看来并不妥当。“我个人非常不建议特殊儿童与普通儿童混合参团，尤其在没有家长陪同的情况下，外出特别是到野外研学旅行。”冯先生说。</p> \n<p>　　作为一名自2017年就创办青少年游学机构的业内人士，冯先生主要负责研学路线后端的景点选择、研学基地开发，以此为前方机构提供研学服务。但冯先生也告诉红星新闻：“根据我掌握的情况，目前国内有能力接待特殊儿童研学旅游的机构非常稀少，因为这背后要求很高。”</p> \n<p>　　冯先生解释称，没有父母的陪伴，如果将自闭症、多动症等疾病的儿童突然送入全是陌生人的团队，又前往陌生的城市，后方如果缺乏专业的心理医生，孩子的精神压力会急剧上升；而团队如果不配备专业的救援人员，那么这些孩子一来学习各类探险能力相对低下，二来因缺乏生存经验和自救能力，一旦出现问题脱团，普通带队老师几乎难以应对。而在冯先生看来，“一个普通团队既要配备专业急救人员又要聘请心理医生，经营成本将急剧上升，所以大部分研学机构不会这样操作。”</p> \n<p>　　<strong>有机构称工作人员无官方资质证明</strong></p> \n<p>　　<strong>一些私人机构会挂靠旅行社接研学团</strong></p> \n<p>　　在政策层面，规范研学市场的文件要求不断出台，进入研学市场的机构也在不断增加。</p> \n<p>　　如上述2016年出台的《意见》规定，旅游部门负责审核开展研学旅行的企业或机构的准入条件和服务标准。到2022年，《中华人民共和国职业分类大典（2022年版）》出台，研学旅行指导师作为新职业被纳入其中，实现研学带队教师的身份认证有据可查。</p> \n<p>　　2024年，文化和旅游部办公厅下发《关于促进旅行社研学旅游业务健康发展的通知》，要求旅行社应选择具备资质的供应商，不得将未开发开放、缺乏安全保障的区域纳入研学旅游产品。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/spider20250813/551/w1871h1080/20250813/5f3f-dd0eecbfcc955fcf394fd1ff52d97e64.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲相关截图\">\n <span class=\"img_descr\">▲相关截图</span>\n</div> \n<p>　　“如果要做研学旅行，那就必须得有旅行社资质，并缴纳保证金；如果只是城市内研学活动，如一些公园、科技馆等，不涉及交通住宿问题，则只需具备户外拓展资质和露营地服务许可证。”另一名从事青少年研学游的前端机构从业者林女士告诉红星新闻。</p> \n<p>　　不过，林女士透露：“因旅行社资质很难获取，所以一些私人机构想操作研学旅游，就会找旅行社进行挂靠，而家长往往不会去考察机构背后的经营主体，也就很难发现是旅行社自己的研学机构，还是私人挂靠的。”</p> \n<p>　　林女士称，在研学热潮之下，部分教培从业者因具有教师资格证，也有教学经验，所以转向做起了研学旅游。“比如他们作为个人想带队研学，也会成为旅行社的兼职人员。但实际上一名真正的研学带队者，还应该具备如研学实践指导证书、户外教育引导员证书、研学旅行指导师证书等。”</p> \n<p>　　红星新闻记者也注意到，上述研学机构销售提供的“神农架”行程路线中，涉及洞穴探险、进入湿地调查等活动。但记者询问研学团是否会临时匹配专业洞穴探险人员以及应急救援人员时，销售人员给出了模棱两可的回答：“部分带团经验丰富的生活老师会有急救证，但不能保证每个团都能有一个有急救证的老师。”</p> \n<p>　　同时，记者以家长身份咨询另一家推出“贵州野外探险”主题的研学机构。当记者询问机构相关资质证明时，对方提供了旅行社的营业执照。但当记者询问带队老师资质时，对方明确告知：“目前，我们工作人员都没有官方的资质证明。”</p> \n<div class=\"img_wrapper\">\n <img id=\"3\" src=\"https://k.sinaimg.cn/n/spider20250813/663/w730h733/20250813/33f2-552572924c636c368fc4c41eb01562d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲推出“贵州野外探险”的机构销售人员坦言带队者没有资质证明\">\n <span class=\"img_descr\">▲推出“贵州野外探险”的机构销售人员坦言带队者没有资质证明</span>\n</div> \n<p>　　至于具体原因，这名销售人员解释：“因为带团众多，所以带队人员不可能都来自旅行社内部。”红星新闻记者也在社交平台看到，不少机构发帖寻找“研学带队兼职人员”，但要求中并不涉及任何资格认证。</p> \n<div class=\"img_wrapper\">\n <img id=\"4\" src=\"https://k.sinaimg.cn/n/spider20250813/639/w1080h1959/20250813/095c-440036c567969e2970c0791c0f719d63.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲社交平台上发布的研学带队人员兼职信息\">\n <span class=\"img_descr\">▲社交平台上发布的研学带队人员兼职信息</span>\n</div> \n<p>　　针对暗访发现的研学机构乱象问题，红星新闻记者也就此致电多地文旅、市场监管、行政审批、教育等多部门，均表示会核实记者反映的情况并做进一步调查。同时，上述部门也提醒消费者，选择研学机构应查验相关资质，报名过程中对参团者信息不可故意隐瞒，以免在危险发生后陷入维权难。</p> \n<p>　　<strong>业内人士：</strong></p> \n<p>　　<strong>不建议13岁以下孩子独立研学</strong></p> \n<p>　　<strong>不可进入会“短暂失联”区域</strong></p> \n<p>　　今年5月19日，经文化和旅游部批准，《研学旅游服务要求》（下称《要求》）的行业标准也正式实施，其中对研学机构的人员配置给出明确规定：承担研学指导岗位职责人员与参与者配比不低于1：30；同时，研学旅游团队服务人员应括：项目管理人员、研学旅游指导人员、生活及后勤保障人员、安全防控人员等。</p> \n<p>　　“其中最难落地的，就是安全防控人员的配置。”作为游学路线供应商的王先生坦言，确定一条游学线路，往往要投入大量人力和财力，其中最大的考验就是安全。</p> \n<p>　　他解释称，尤其是开辟一条自然风貌的游学路线，过程中会带领孩子进入野外，如溶洞、丛林等，可能会有艰难的路段，有突变的天气，“如果这些没有专业人员加持，就容易有突发情况。”</p> \n<p>　　而最理想的状态，王先生认为，是游学线路里全程配备急救人员，在进入溶洞时还有专业的溶洞教练，但这样一来，游学项目于机构而言将无利可图。</p> \n<p>　　此外，王先生也坦言，在其从业经历里，也接触过一些私人小游学机构，为了吸引客户开辟所谓新路线，带领家长孩子进入未被选为研学景区的户外甚至丛林等“禁区”，“看似是没人走过的新路线，实际背后存在很大安全隐患。”</p> \n<p>　　因此，王先生也呼吁家长，在选择研学机构时，除了检查相应资质外，还需考察路线中“不曾听过”的景区是否安全，且需明确向机构表示，不可带孩子进入会“短暂失联”的区域。他同时指出，特殊儿童不建议与普通儿童混合参团，也不建议13岁以下孩子进行独立研学。</p> \n<p>　　红星新闻记者 杨雨奇</p> \n<p>　　编辑 张莉 责编 官莉</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1755054529\" target=\"_blank\">自闭症男童参加夏令营失联</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250813/267/w640h427/20250813/9b0c-f6abaebc4c67eb79cf278569361c09c4.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/120/w1440h1080/20250813/2a38-2d034b4d7287afff653fd2b9cd038bde.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/551/w1871h1080/20250813/5f3f-dd0eecbfcc955fcf394fd1ff52d97e64.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/663/w730h733/20250813/33f2-552572924c636c368fc4c41eb01562d0.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250813/639/w1080h1959/20250813/095c-440036c567969e2970c0791c0f719d63.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4524, NULL, '甘州区：提级监督破解基层治理难题', 0, 2, 299, '2025-08-14 08:30:20', '2025-08-14 08:16:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcek2542987.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　“村里多年的土地纠纷终于解决了，你们真是帮我们办了实事！”近日，张掖市甘州区上秦镇东王堡村村民看着刚划定的土地边界，难掩心中喜悦。这是区纪委监委实行重点村（社区）提级监督、化解基层矛盾的一次生动实践。</p>\n<p cms-style=\"font-L\">　　今年以来，区纪委监委聚焦基层治理“痛点”，以提级监督为抓手，构建统筹联动、精准施策、标本兼治的工作体系，让监督力量直插基层，将治理效能转化为群众看得见的实惠。</p>\n<p cms-style=\"font-L\">　　“提级监督能够打破基层监督‘看得见却管不着、管得着却管不好’的壁垒，通过力量下沉，为破解基层治理难题提供有力支撑。”区纪委监委主要负责人说。</p>\n<p cms-style=\"font-L\">　　区纪委监委建立“三级联动”责任体系，10名班子成员分片包抓重点村（社区），将提级监督与薄弱乡镇治理等15项任务一体推进。5个片区协作组联动乡镇（街道）党（工）委，形成指导、督责、整改闭环。今年，通过任务清单调度、蹲点调研等方式，班子成员累计下沉指导69次，推动开展17次联动监督。</p>\n<p cms-style=\"font-L\">　　不久前，在区纪委监委提级监督推动下，靖安乡上堡村围绕低价长期合同开展全面排查，建立合同审核、动态监管等长效机制，从源头防范风险，让规范意识融入乡村治理各环节。</p>\n<p cms-style=\"font-L\">　　“我们针对农村集体‘三资’管理不规范、矛盾纠纷积压等突出问题，实行一村一策精准治理。”区纪委监委相关负责人介绍。</p>\n<p cms-style=\"font-L\">　　区纪委监委对重点村（社区）民主决策、项目建设、民生实事、矛盾纠纷等7类问题建立台账，采取列席会议、走访群众等方式跟踪督办。同时，将群众诉求作为监督导向，确定独居老人就餐保障等24件民生实事跟进监督，推动职能部门履职尽责，目前已完成7件。（供稿 朱玉琢 编辑 毛玉煜）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4525, NULL, '驻省委统战部纪检监察组：聚焦关键领域一体“督查改”', 0, 1, 27, '2025-08-14 08:30:30', '2025-08-14 08:14:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcec3366869.shtml', '甘肃省纪委监委网站', '<p cms-style=\"font-L\">　　今年以来，省纪委监委派驻省委统战部纪检监察组在全覆盖日常监督的同时，聚焦关键领域一体“督查改”，以精准有力监督推动各项重点工作落地见效。</p>\n<p cms-style=\"font-L\">　　纪检监察组聚焦深入贯彻中央八项规定精神学习教育部署要求、群众身边不正之风和腐败问题集中整治等重点工作，全面分析监督检查发现问题，找准切入点和着力点，确定中央八项规定精神学习教育贯彻落实、民主党派省委会机关内部监督、5家省级宗教团体公职人员履职、对口帮扶工作开展等4项专项督查调研。督查调研采取听取汇报、查阅资料、实地查看、座谈交流等方式，与各被监督单位开展座谈交流18场次、122人次。</p>\n<p cms-style=\"font-L\">　　围绕学习教育贯彻落实，纪检监察组全覆盖督查调研省级统战系统单位，聚焦理论学习、内控制度修订完善、“三公”经费报销等方面，发现并反馈问题29个，提出工作建议36条。对问题突出的单位，及时发出工作提示督促整改。</p>\n<p cms-style=\"font-L\">　　为有效发挥民主党派省委会机关内部监督委员会监督职能作用，纪检监察组走访调研6家民主党派省委会机关，深入了解各民主党派省委会机关落实中央八项规定精神、“三重一大”事项、制度运行以及机关干部履职担当、工作作风等情况，对关键岗位、关键人开展廉政谈话34人次，发现并指出问题23个，提出工作建议26条，对共性问题下发工作提示，推动加强机关思想政治建设、组织建设、作风建设、制度建设。</p>\n<p cms-style=\"font-L\">　　纪检监察组调研监督5家省级宗教团体，督促加强政治理论学习、健全完善内部管理制度、严格执行财经纪律，推动公职人员认真履行职责，发挥好党和政府团结联系宗教界人士和信教群众的桥梁纽带作用。</p>\n<p cms-style=\"font-L\">　　纪检监察组专项督查文县范坝镇、玉垒乡、铁楼藏族乡、尚德镇及5个帮扶村，监督检查帮扶项目资金管理使用、驻村帮扶干部履职尽责情况等，指出问题9个，提出工作建议4条。</p>\n<p cms-style=\"font-L\">　　针对督查调研发现的重点、难点问题，纪检监察组通过专题会商、工作提示、反馈通报等方式，督促被监督单位扛牢主体责任，建立问题落实台账，细化问题整改任务书、时间表，明确问题整改责任单位、责任人，加强全程监督，推动问题整改到位。</p>\n<p cms-style=\"font-L\">　　纪检监察组主要负责人表示，下一步将紧盯问题整改，常态化开展抽查检查，对问题整改走过场、假整改、不到位的，严肃问责相关责任单位和责任人。（供稿 牟克明&nbsp;吴庭悦 编辑 毛玉煜）</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4526, NULL, '【8点见】大理通报“8岁男童在苍山走失遇难”', 0, 1, 25, '2025-08-14 08:30:40', '2025-08-14 08:00:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/d6e6-b3ed1e81a1f9f4a566da6d092eeb99d2.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcek2541405.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息</font>：每天8点，央视网为您梳理24小时内发生在咱们身边的大小事儿。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/d6e6-b3ed1e81a1f9f4a566da6d092eeb99d2.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·水利部针对福建等4省区启动洪水防御Ⅳ级应急响应。</p>\n<p cms-style=\"font-L\">　　·商务部：13日起对欧盟两家金融机构采取反制措施。</p>\n<p cms-style=\"font-L\">　　·两部门紧急预拨1.7亿元支持7省市应急抢险救灾。</p>\n<p cms-style=\"font-L\">　　·市场监管总局、国家卫生健康委、国家中医药局13日联合发布《医疗广告认定指南》，加强医疗广告监管。</p>\n<p cms-style=\"font-L\">　　·两部门征求意见：辅助驾驶不能当自动驾驶，未经备案OTA不得升级。</p>\n<p cms-style=\"font-L\">　　·北京 2025世界人形机器人运动会14日开幕。</p>\n<p cms-style=\"font-L\">　　·2025年暑期档电影总票房（含预售）突破90亿元。</p>\n<p cms-style=\"font-L\">　　·美驱逐舰非法闯入中国黄岩岛领海，南部战区依法依规警告驱离。</p>\n<p cms-style=\"font-L\">　　·广西被列为基孔肯雅热流行风险Ⅰ类地区。</p>\n<p cms-style=\"font-L\">　　·我国成功发射卫星互联网低轨08组卫星。</p>\n<p cms-style=\"font-L\">　　·8月15日至17日，北京天安门地区及相关道路临时交通管制。按照天安门广场及周边区域施工作业安排，天安门广场8月20日至23日暂停开放。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/1fa6-53f516b3e9e32f8476a80f98e6ef81cc.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·印度西部拉贾斯坦邦发生一起车祸，造成至少10人死亡，其中包括7名儿童。</p>\n<p cms-style=\"font-L\">　　·内塔尼亚胡称加沙停火谈判“已成过去时”。</p>\n<p cms-style=\"font-L\">　　·美国联邦政府债务突破37万亿美元。</p>\n<p cms-style=\"font-L\">　　·美国政府宣布首都华盛顿进入治安紧急状态，国民警卫队进驻首都华盛顿。</p>\n<p cms-style=\"font-L\">　　·特朗普：考虑对美联储主席鲍威尔提起诉讼。</p>\n<p cms-style=\"font-L\">　　·6米29，杜普兰蒂斯再破撑竿跳世界纪录。</p>\n<p cms-style=\"font-L\">　　·墨西哥驱逐26名美国通缉的贩毒集团头目，有人涉嫌杀害警员。</p>\n<p cms-style=\"font-L\">　　·南极冰川消融露出遗骸，失踪66年的英国科考人员丹尼斯·贝尔终于“归家”。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/7e1d-4b387103b86d2e5e80c43ced5d7ed709.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"2\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/462/w734h528/20250814/ebe0-c0b54a67e83da6d0d9babeeebec9d3b9.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·大理通报“8岁自闭症男童遗体被找到”：排除外力损伤致死，初步排除刑案可能。</p>\n<p cms-style=\"font-L\">　　·女子怀孕7周遭医院误诊，卫健委回应：正协调处理。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/192/w1024h768/20250814/4664-605e293d42d5ee58e6478a482c84a4ee.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"4\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·用外挂软件抢购演唱会门票，3人非法牟利10万元被刑拘。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/386/w738h1248/20250814/e4df-a36cefa66622eb9c2e5dfb4086a41651.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"5\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·“炒菜多放辣椒”写入先进事迹引争议后被取消“吉林好人”候选资格？当地回应。</p>\n<p cms-style=\"font-L\">　　·三亚一豪华酒店被指虫子成群，酒店致歉：已全面加大蚊虫消杀力度。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/91/w417h474/20250814/3288-8b8dff2f34b372f0c4d27ea82da73e26.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"6\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　·吉林一地早中晚高峰禁止老年人免费乘车？交通局回应：通知已取消。</p>\n<p cms-style=\"font-L\">　　·广西一高中给考上清华学生发百万奖金，当地教育局：违规宣传高考成绩，已进行制止。</p>\n<p cms-style=\"font-L\">　　·长春一安置小区每天凌晨听到狼群嚎叫，养殖户称养了40余只草原狼，官方：合法圈养居民不用担心。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/9d8a-861a8fa7ca9b3e8edf0b8d7d26b4064c.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"7\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　网络时代，每个人都有前所未有的发声机会，舆论的力量也常常超出想象。但是，在调动这种力量维权之前，当事人应当扪心自问、慎之又慎，要恪守边界，发出理性、真实的声音，要给出确凿可信的证据。</p>\n<p cms-style=\"font-L\">　　——工人日报：《网络空间不能成为信口雌黄之地》</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/b590-588f32b81554fa6b9d1e69105d9a3c03.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"8\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/762/w1000h562/20250814/7dd0-7d5b777f5b9029efce795117d98e0d66.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"9\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　8月13日，浙江省桐庐县的富春江小三峡现晨雾中梦幻景观，寂静的江面云雾蒸腾缭绕，船只若隐若现、在江水中荡漾，仿佛现实版的富春山居图。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/99/w1000h1499/20250814/405b-1fd72eab40c4065e54065b035648bc96.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"10\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　8月12日傍晚，山东省青岛市，海边罕见出现“日柱”，灿烂的晚霞云朵一度宛如“游龙吐火”。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/b590-588f32b81554fa6b9d1e69105d9a3c03.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"11\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/200/w1080h720/20250814/24e4-4589d770781ab12e9b873ba3dfe51915.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"12\">\n <span class=\"img_descr\"></span>\n</div>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/99fb-a28207bf3802c8f7b82299a9b17677f9.png/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"13\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　近日，在甘肃金昌金川公园观赏湖喂鱼区，一名女孩在投喂鱼食时不慎滑入湖中。母亲呼救后，正在附近巡逻的保安苑其桥迅速赶到，纵身跳入湖中，将孩子托举上岸。苑其桥回忆，当时自己距离孩子落水位置有五六米，“鞋都跑丢了，来不及考虑，只能想到把人救上来。”</p>\n<p cms-style=\"font-L\">　　明天8点见！</p>\n<p cms-style=\"font-L\">　　编辑：陈平丽 甄涛</p>\n<p cms-style=\"font-L\">　　责任编辑：钱景童 宿党辉</p>', '[\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/d6e6-b3ed1e81a1f9f4a566da6d092eeb99d2.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/1fa6-53f516b3e9e32f8476a80f98e6ef81cc.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/7e1d-4b387103b86d2e5e80c43ced5d7ed709.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/462/w734h528/20250814/ebe0-c0b54a67e83da6d0d9babeeebec9d3b9.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/192/w1024h768/20250814/4664-605e293d42d5ee58e6478a482c84a4ee.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/386/w738h1248/20250814/e4df-a36cefa66622eb9c2e5dfb4086a41651.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/91/w417h474/20250814/3288-8b8dff2f34b372f0c4d27ea82da73e26.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/590/w440h150/20250814/9d8a-861a8fa7ca9b3e8edf0b8d7d26b4064c.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/b590-588f32b81554fa6b9d1e69105d9a3c03.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/762/w1000h562/20250814/7dd0-7d5b777f5b9029efce795117d98e0d66.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/99/w1000h1499/20250814/405b-1fd72eab40c4065e54065b035648bc96.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/407/w303h104/20250814/b590-588f32b81554fa6b9d1e69105d9a3c03.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/200/w1080h720/20250814/24e4-4589d770781ab12e9b873ba3dfe51915.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/99fb-a28207bf3802c8f7b82299a9b17677f9.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4527, NULL, '台风“杨柳”最新路径：已进入广东梅州 强度逐渐减弱', 0, 2, 203, '2025-08-14 08:31:02', '2025-08-14 07:10:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/480/w1280h800/20250814/e261-5e965d59ce20a2a8f4ece1a2916f19c3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcek2533212.shtml', '央视', '<p cms-style=\"font-L\">　　8月14日3时至6时，今年第11号台风“杨柳”进入广东省梅州市境内，中心附近最大风力9级，达到23米/秒的风速，六级大风范围半径约280公里。“杨柳”以每小时30公里左右的速度向西偏北方向移动，强度逐渐减弱。</p> \n<p cms-style=\"font-L\">　　受“杨柳”环流影响，粤东、河源、梅州等地市县出现强降水。据气象水文监测，8月14日5时到6时，各市雨量最大的镇街有：河源紫金县好义镇81.4毫米、汕尾城区遮浪街道73.5毫米、惠州惠东县多祝镇63.9毫米、深圳深汕特别合作区鲘门镇48.3毫米、揭阳普宁市流沙南街道33.2毫米。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/480/w1280h800/20250814/e261-5e965d59ce20a2a8f4ece1a2916f19c3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　截至6时17分，河源紫金、揭阳普宁、汕尾城区和红海湾暴雨红色预警信号生效中，另外广东东部还有大范围暴雨预警信号，雨区随着台风逐渐西移。</p> \n<p cms-style=\"font-L\">　　根据气象预测，受台风“杨柳”影响，13日夜间至14日广东梅州市有暴雨局部（特）大暴雨。广东省水文局梅州水文分局预测石窟河新铺站及梅江中下游可能出现超警戒洪水；韩江三河坝（三）站可能出现接近或超警戒洪水。</p> \n<p cms-style=\"font-L\">　　根据相关规定，8月14日梅州市全市中小学、幼儿园、培训机构等停课，暂停夏令营、研学实践等集体活动。梅州市所有高速公路主线及入口封闭，禁止一切车辆和人员通行。除高速公路封闭外，梅州所有公交车临时停运。当天途经杭深、梅汕、梅龙高铁线路的列车全部停运。辖区游览船、客渡船停航。A级旅游景区停止营业。</p> \n<p cms-style=\"font-L\">　　（总台记者 陈惠婷）&nbsp;&nbsp;</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1755104309\" target=\"_blank\">台风“杨柳”再次登陆</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/480/w1280h800/20250814/e261-5e965d59ce20a2a8f4ece1a2916f19c3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4528, NULL, '受台风“杨柳”影响，广东潮州全市实行“五停”措施', 0, 2, 210, '2025-08-14 08:31:10', '2025-08-14 07:05:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcef7135857.shtml', '界面', '<p cms-style=\"font-L\">　　潮州市人民政府防汛防旱防风指挥部8月13日晚发布《关于在全市范围内实行防台风“五停”的指令》：据气象部门预测，今年第11号台风“杨柳”将于13日夜间至14日凌晨以强热带风暴级或台风级在福建漳浦到潮州市饶平一带沿海再次登陆，登陆时强度可能在11-12级，将给潮州市造成较大风雨影响。市三防指挥部已于13日13时将防台风Ⅲ级应急响应提升为Ⅱ级。</p> \n<p cms-style=\"font-L\">　　为全力保障人民群众生命财产安全，最大程度减少灾害损失，经综合会商研判，根据《潮州市应对重大自然灾害“五停”工作指引》，市三防指挥部定于8月13日23时，除直接保障城市供水、供电、供气、通信、医疗等关乎民生的单位和参与抢险救灾的单位外，在全市范围内实行“五停”（停课、停工、停产、停运、停业）措施。各地开放避险庇护场所供群众避风避险。</p> \n<p cms-style=\"font-L\">　　各地各行业主管部门要落实好本行业、本辖区“五停”措施。各抢险救灾和民生保障单位，采取措施做好供水、供电、供气、交通、通信、民政、医疗防疫和主副食品供应等救灾救助准备工作。</p> \n<p cms-style=\"font-L\">　　实行“五停”期间，广大市民要居家避险，请勿随意外出。如身处危险区域，请拨打110、119、120等紧急救援电话求救。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1755104309\" target=\"_blank\">台风“杨柳”再次登陆</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4529, NULL, '金与正：朝方从未也无意拆除朝韩边境地区的扩音器', 0, 4, 147, '2025-08-14 09:30:16', '2025-08-14 08:28:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-14/doc-infkxcek2546770.shtml', '央视', '<p cms-style=\"font-L\">　　朝鲜劳动党中央委员会副部长金与正8月14日发表谈话“首尔的企盼不过是一场梦”。</p> \n<p cms-style=\"font-L\">　　谈话称，12日韩国新闻媒体妄加臆测，说在俄美峰会上朝方对美方的示意很有可能被传达，<font cms-style=\"font-L strong-Bold\">这是韩方的白日梦，是韩国媒体的妄加揣测</font>。</p> \n<p cms-style=\"font-L\">　　金与正还对韩国称朝鲜已拆除朝韩边境地区扩音器一事进行了说明。金与正明确指出，所谓朝鲜已拆除在朝韩边境地区的扩音器是韩国舆论的误导。<font cms-style=\"font-L strong-Bold\">朝方从未拆除在朝韩边境地区布置的扩音器，也无意拆除</font>。</p> \n<p cms-style=\"font-L\">　　金与正说，韩国误导舆论主张他们近期采取的“善意措施”和“柔和政策”似乎得到回应，试图营造朝韩关系看似“恢复”的舆论氛围。韩国现政权只取消尹锡悦政权单方面采取的措施，却期望得到办成大事的评价，企图诱导谁的回应。在联合军演问题上，说什么“调整”“延缓”，为表现出其关心缓和紧张局势的样子煞费苦心，可这不是值得评价的事，而是徒劳之举。</p> \n<p cms-style=\"font-L\">　　金与正表示，不管韩国拆除扩音器、停止广播、延缓或缩减训练，朝方对此毫不在乎，也毫无关心。（总台记者 董海涛）</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4530, NULL, '特朗普称华盛顿特区犯罪率“位居全球前列”', 0, 4, 207, '2025-08-14 09:30:25', '2025-08-14 08:17:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/d265-308a41bc480461ad1837c04f25939b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxcec3367824.shtml', '央视', '<p>　　当地时间8月13日，美国总统特朗普在其社交媒体平台上发文称，<strong>华盛顿特区的犯罪率“位居全球前列”。</strong>他表示，如果特区是一个州，其凶杀率将高居全美首位。</p> \n<p>　　特朗普称，过去十多年间华盛顿特区谋杀率几乎翻倍，暴力犯罪率恶化，而实际情况“远比官方统计更糟”。他指责当地政府在犯罪调查、逮捕和起诉方面消极应对。他援引华盛顿特区警察工会的说法称，真实的犯罪数字可能比公布数据高出数倍。</p> \n<p>　　特朗普表示，华盛顿特区已重新回到联邦控制之下，由白宫主导，军方与警方将“使城市再次宜居和美丽”。</p> \n<p>　　<strong>新闻多看点</strong></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/d265-308a41bc480461ad1837c04f25939b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　特朗普11日宣布首都华盛顿进入“治安紧急状态”，并将首都警察局置于联邦直接管控之下。华盛顿市长鲍泽表示，华盛顿的暴力犯罪率现已降至30年来最低点，联邦政府的行为“令人不安”。12日，美国国民警卫队进驻首都华盛顿。特朗普13日表示，他将寻求联邦政府对华盛顿特区警察部队的长期控制。（央视记者 曹健）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754925007\" target=\"_blank\">特朗普宣称要“解放首都”</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/d265-308a41bc480461ad1837c04f25939b2a.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4531, NULL, '特朗普称美国愿在特定条件下为乌克兰提供安全保障', 0, 4, 207, '2025-08-14 09:30:35', '2025-08-14 08:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/9/w516h293/20250814/0e74-104b9919ce92359f735151ee1e531443.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxcep5553684.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/9/w516h293/20250814/0e74-104b9919ce92359f735151ee1e531443.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，<font cms-style=\"font-L\"><font cms-style=\"font-L strong-Bold\">央视记者</font></font>获悉，美国总统特朗普在与欧洲及乌克兰领导人的视频会议上表示，<font cms-style=\"font-L strong-Bold\">美国愿在特定条件下为乌克兰提供安全保障，但这一承诺不纳入北约框架。</font></p> \n<p cms-style=\"font-L\">　　该会议由德国总理默茨发起<font cms-style=\"font-L italic\">，</font>目的是在本周特朗普与俄总统普京会晤前协调美欧立场。消息人士称，<font cms-style=\"font-L strong-Bold\">特朗普未详细说明安全保障的形式</font>，仅表示其应成为最终和解的一部分，并强调美国不会继续直接向乌克兰提供武器或派遣部队，但会向欧洲出售武器供乌方使用。（央视记者 曹健）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold color240\"></font></font></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/9/w516h293/20250814/0e74-104b9919ce92359f735151ee1e531443.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4532, NULL, '网友称因举报养殖企业污染遭到报复？江西高安通报', 0, 1, 14, '2025-08-14 09:30:50', '2025-08-14 09:21:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcec3398091.shtml', '界面新闻', '<p>　　<span></span>高安市委政法委8月14日通报，近日，针对网友反映因举报养殖企业污染遭到报复一事，高安市迅速安排市委政法委牵头，联合市纪委监委、市检察院、市公安局等单位开展调查。目前，网友反映的涉事人员已被相关部门传唤调查。将根据调查情况，坚决依规依纪依法严肃处理。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4533, NULL, '近观“两山”丨大漠绘丹青', 0, 2, 88, '2025-08-14 09:31:12', '2025-08-14 08:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/519b-a5efcb2f9f511e2b1b2d07ec9ef3f759.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/xl/2025-08-14/doc-infkxcec3374256.shtml', '央视新闻客户端', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p>　　我国是世界上荒漠化最严重的国家之一。在辽阔的中国西北、华北、东北地区，分布着我国84%的沙化土地，合称“三北沙化地区”，总面积超过全国现有耕地面积的总和。</p> \n<p>　　习近平总书记对国土绿化工作一直高度重视。他反复强调：“我国总体上仍然是一个缺林少绿、生态脆弱的国家，植树造林，改善生态，任重而道远。”</p> \n<p>　　党的十八大以来，习近平总书记连续13年参加首都义务植树活动，多次谈到植树造林的重大意义。从内蒙古马鞍山林场，到河北塞罕坝机械林场；从甘肃八步沙林场，到巴彦淖尔新华林场······习近平总书记一次次实地考察防沙治沙情况。</p> \n<p>　　在“三北”等重点生态工程推动下，我国率先在世界范围内实现了土地退化“零增长”，重点治理区实现了从“沙进人退”到“绿进沙退”的历史性转变，走出了一条符合中国实际、具有中国特色的防沙治沙道路。</p> \n<p>　　经过多年努力，我国森林覆盖率已经超过25%，森林蓄积量超过200亿立方米，人工林面积稳居世界第一。近20年来，在全球新增的绿化面积中，中国贡献占比达到25%，居全球首位。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/519b-a5efcb2f9f511e2b1b2d07ec9ef3f759.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　总监制丨闫帅南 王姗姗监制丨马丽君制片人丨杜晓东编导丨刘雪锋配音丨王帅天编辑丨严佳 卢慧 王萧宇</p> \n<p class=\"show_author\">责任编辑：王天昊 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/728/w550h978/20250814/519b-a5efcb2f9f511e2b1b2d07ec9ef3f759.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4534, NULL, '广东一家三口遭杀害案下周将开庭，凶手叶某某被鉴定为精神分裂，被害人家属：不理解不接受', 0, 1, 19, '2025-08-14 09:31:18', '2025-08-14 08:38:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/81/w1080h601/20250814/1a89-d7357382a19e13f333ffe40a8a19baa8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcef7163110.shtml', '极目新闻', '<p cms-style=\"font-L\">　　2025年8月13日，“广东廉江一家三口遭同村村民杀害”一案，其中被害人潇潇（化名）的姐姐叶女士向潮新闻记者透露，其律师通知她该案将于8月18日上午9时30分在湛江市中级人民法院开庭审理，届时家中兄弟姐妹还有妹夫都会出席庭审。</p> \n<p cms-style=\"font-L\">　　2025年4月，该案在网上引发高度关注——被害人潇潇的小姑子何女士在网上发文称，嫂子潇潇带着两个孩子一同暂住廉江石颈镇东涌村娘家期间，于2025年3月27日晚上19时45分许，包括潇潇、其母亲和未满两岁的大儿子三人在内，被同村村民叶某某骑着摩托车持刀冲进家里残忍杀害。其中万幸的是，当时不到三个月大的小儿子因在睡梦中，逃过一劫。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/81/w1080h601/20250814/1a89-d7357382a19e13f333ffe40a8a19baa8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"事发当天现场监控截图 受访者供图\">\n <span class=\"img_descr\">事发当天现场监控截图 受访者供图</span>\n</div> \n<p cms-style=\"font-L\">　　潮新闻此前报道，何女士曾向记者透露，“目前案件已经向中院（湛江市中级人民法院）递交了材料，但鉴定意见显示凶手叶某某有精神分裂。”对此，何女士及被害人潇潇的家人都无法理解和接受这个情况。</p> \n<p cms-style=\"font-L\">　　根据被害人家属提供的廉江市公安局鉴定意见通知书照片显示，鉴定意见为：一是鉴定诊断为精神分裂症；二是被鉴定人叶某某在本次作案时的刑事责任能力可评定为限定刑事责任能力。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250814/126/w1080h646/20250814/0de5-885952ccdae3618425002049e30e8a18.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"起诉书 受访者供图\">\n <span class=\"img_descr\">起诉书 受访者供图</span>\n</div> \n<p cms-style=\"font-L\">　　今年8月份，叶女士曾向记者透露，开庭前收到公安机关的鉴定意见通知书称，对被告叶某某鉴定诊断为——精神分裂症，目前处于疾病缓解期；受审能力评定为叶某某目前有受审能力。</p> \n<p cms-style=\"font-L\">　　根据叶女士提供的起诉书提到，被告叶某某因臆想被他人释放毒气加害及汽车打不着火均与同村叶某有关，便拿上两把菜刀，到叶某家。未找到叶某，叶某某见到被害人坐在叶某家门口，即下车持刀砍击三名被害人。起诉书认为，被告叶某某故意剥夺他人生命，致三人死亡，犯罪事实清楚，证据确实、充分，应当以故意杀人罪追究其刑事责任。另外，起诉书中也提到，被告叶某某的鉴定诊断为精神分裂症。</p> \n<p cms-style=\"font-L\">　　发稿前，叶女士表示，家属曾经要求重新对叶某某进行精神鉴定，但未被接受，“我们对精神病轻判这个事情依然不能理解和接受，这不能作为逃脱惩罚的借口。”此次开庭，她表示，家人都希望了解案件的真相。</p> \n<p cms-style=\"font-L\">　　潮新闻记者 李沐子</p> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/81/w1080h601/20250814/1a89-d7357382a19e13f333ffe40a8a19baa8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/126/w1080h646/20250814/0de5-885952ccdae3618425002049e30e8a18.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4535, NULL, '国产最大直径盾构机“沧渊号”在海太长江隧道始发', 0, 1, 10, '2025-08-14 09:31:23', '2025-08-14 08:34:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/216/w2048h1368/20250814/098a-9c556d669fae95b6937f5d608d2c7236.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcef7153640.shtml', '国资委网站', '<p cms-style=\"font-L\">　　8月11日，由中交天和自主研制的国产最大直径盾构机“沧渊号”在一公局集团隧道局承建的海太长江隧道正式始发掘进，标志着我国在大型工程装备制造和隧道建设领域再次取得新突破。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/216/w2048h1368/20250814/098a-9c556d669fae95b6937f5d608d2c7236.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　据悉，海太长江隧道位于江苏省长江入海口，北起南通市海门区，南至苏州太仓市，线路全长39.07公里，其中盾构隧道段长9327米，开挖直径达16.66米，最高水压达0.75兆帕，是世界最长公路水下盾构隧道。面对超长距离、超大直径、超高水压等挑战，中交天和研制团队为海太长江隧道量身定制了“沧渊号”盾构机。</p>\n<p cms-style=\"font-L\">　　研制团队围绕刀盘刀具、主驱动、推进、同步注浆等九大系统，为“沧渊号”搭载了三大利器。一是“数字大脑”构建智能掘进生态。搭载的智能掘进系统，实现一键启动、自主巡航掘进、姿态自主控制、泥水环流智能控制、同步注浆自动控制全程自主可控；智能诊断与维护系统覆盖设备全生命周期护理，打造绿色掘进闭环。二是“智刃铁齿”革新高效掘进法则。配置常压换刀功能的软土刀盘，搭配梯度分布的合金刀具，构成“超硬龙齿矩阵”，可实现石英砂含量约65%地层单次掘进2000米内不换刀；刀盘搭配伸缩摄像装置，无需人工带压进舱即可观察刀盘作业状况。三是“智慧心脏”主动防护安全升级。配备全球首套具备主动防护功能主驱动系统，实现掘进可视、可达、可控；集成管片连接构件智能拼装及掘进同步拼装控制系统，实现智能拼装与掘进作业同步，生产效率提高50%；同步搭载管片上浮、盾尾间隙及管片变形监测预警系统和绿色换管装置及智能控制系统，可有效保证掘进安全环保和隧道成形质量。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/323/w2048h1475/20250814/9436-9436d2a780ac4f492632cb3116e78419.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L\">　　作为长三角区域一体化和长江经济带发展的关键工程，海太长江隧道建成后，将优化长江干线过江通道布局，对推动沿江城市群跨江融合发展具有重大意义。</p>\n<p cms-style=\"font-L align-right\">　　【责任编辑：韩梦圆】</p>', '[\"https://k.sinaimg.cn/n/spider20250814/216/w2048h1368/20250814/098a-9c556d669fae95b6937f5d608d2c7236.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/323/w2048h1475/20250814/9436-9436d2a780ac4f492632cb3116e78419.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4536, NULL, '美财政部为“特普会”发豁免令 允许俄方在现行制裁下与会', 0, 4, 207, '2025-08-14 10:30:18', '2025-08-14 10:15:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250814/e8f0-e8b173ecf416ad71ca09940a33f961c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxinc7091376.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间8月13日，美国财政部外国资产控制办公室（OFAC）签发第125号一般许可证，<font cms-style=\"font-L strong-Bold\">授权俄罗斯总统普京及其代表团在现行制裁下在阿拉斯加与美方会晤。</font></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250814/e8f0-e8b173ecf416ad71ca09940a33f961c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\" △美国财政部外国资产控制办公室（资料图）\">\n <span class=\"img_descr\"> △美国财政部外国资产控制办公室（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　许可证规定，在2025年8月20日凌晨00时01分（美东时间）前，<font cms-style=\"font-L strong-Bold\">与美俄政府在阿拉斯加会晤有关且“必要的”交易可获得豁免，但不包括解冻俄方被冻结资产或其他制裁下禁止的交易。</font></p> \n<p cms-style=\"font-L\">　　美国总统特朗普与俄罗斯总统普京将于15日在美国阿拉斯加州最大城市安克雷奇举行会晤，会晤将以一对一形式举行。（央视记者 曹健）</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/default/crawl/117/w550h367/20250814/e8f0-e8b173ecf416ad71ca09940a33f961c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4537, NULL, '美国弗吉尼亚州发生枪击事件 多名执法人员中弹', 0, 4, 207, '2025-08-14 10:30:25', '2025-08-14 09:24:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/26/w523h303/20250814/fa4d-62fb964bc1d4c252fdab18df5127a612.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxcep5593544.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/26/w523h303/20250814/fa4d-62fb964bc1d4c252fdab18df5127a612.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">央视记者</font></font>获悉，美国弗吉尼亚州南部皮茨尔瓦尼亚县发生枪击事件，<font cms-style=\"font-L strong-Bold\">多名执法人员中弹受伤</font>。</p> \n<p cms-style=\"font-L\">　　现场照片显示，大量警车及紧急救援车辆停靠在事发区域。（央视记者 曹健）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/26/w523h303/20250814/fa4d-62fb964bc1d4c252fdab18df5127a612.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4538, NULL, '金建希接受韩国特检组传唤调查', 0, 4, 105, '2025-08-14 10:30:34', '2025-08-14 08:54:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/498/w810h488/20250814/5d1b-4c7d46f665e974f9132212a545b73061.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxcep5558709.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/498/w810h488/20250814/5d1b-4c7d46f665e974f9132212a545b73061.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△金建希（资料图）\">\n <span class=\"img_descr\">△金建希（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，当地时间14日上午，韩国前总统尹锡悦夫人金建希乘坐韩国法务部的护送车辆抵达金建希特检组所在地，<font cms-style=\"font-L strong-Bold\">接受被捕后的首次传唤调查。</font></p> \n<p cms-style=\"font-L\">　　本月6日，由于牵涉德意志汽车公司股价操纵案、政治掮客介选案等一系列案件，特检组对金建希进行了传唤调查，但她基本否认了所有指控。7日，特检组以涉嫌违反《资本市场法》《政治资金法》和《特定犯罪加重处罚法》等为由提请法院批捕金建希。12日上午，金建希抵达首尔中央地方法院，出席拘捕必要性审查。</p> \n<p cms-style=\"font-L\">　　12日深夜，韩国首尔中央地方法院签发对金建希的拘捕令，金建希随即被首尔南部拘留所拘押。韩国宪政史上首次出现“前总统夫妇同时被捕”的情况。（总台记者 张昀）</p> \n<!--article_adlist[<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">金建希被拘押 韩国宪政史首次出现“前总统夫妇同时被捕”&gt;&gt;</font></font></p>\n<p cms-style=\"font-L\">　　©2025中央广播电视总台版权所有。未经许可，请勿转载使用。</p>\n<p cms-style=\"font-L\">　　<img src=\"http://n.sinaimg.cn/spider20250814/251/w1600h251/20250814/9a06-gif1a2f9d638b0b2bf6530bad0dbbf1f2cc.gif\"></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦夫妇同被羁押</a>\n</div> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/498/w810h488/20250814/5d1b-4c7d46f665e974f9132212a545b73061.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4539, NULL, '广西南宁青秀区发现8例基孔肯雅热病例', 0, 2, 213, '2025-08-14 10:30:41', '2025-08-14 10:20:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxinh2489586.shtml', '界面新闻', '<p>　　广西南宁青秀区疾病预防控制中心通报，截至2025年8月13日18时，青秀区在主动排查外省协查病例中，于青秀区建政街道及其周边陆续发现8例基孔肯雅热病例，患者均为轻症，目前所有患者均得到有效处置。</p> \n<p>　　为控制基孔肯雅热传播，青秀已在相关区域开展蚊媒专项消杀工作，并将在全城区继续深入开展爱国卫生运动。在此，建议广大市民积极做好个人防护，清理积水、灭蚊虫、防叮咬。若出现发热、皮疹及关节疼痛等症状，请及时到医疗机构就诊，并主动告知旅居史和蚊虫叮咬史。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">多地现基孔肯雅热疫情</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4540, NULL, '全国首台国产商业电子束光刻机在杭“出炉”', 0, 2, 84, '2025-08-14 10:31:05', '2025-08-14 09:33:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxcec3409270.shtml', '财联社', '<p>　　来源：财联社</p> \n<p>　　财联社8月14日电，据杭州日报，近日，作为基地首批签约孵化项目之一，全国首台国产商业电子束光刻机“羲之”已进入应用测试，其精度比肩国际主流设备，标志着量子芯片研发从此有了“中国刻刀”。在测试现场，浙大余杭量子研究院相关团队紧张忙碌着，一台模样酷似大型钢柜的机器正在做应用测试，电子显示屏上不断闪烁着实时参数。“这不是普通的机器，而是一支能在头发丝上雕刻出整座城市地图的‘纳米神笔’！”团队负责人告诉记者，依托省重点实验室，这台研究院自主研发的新一代100kV电子束光刻机“羲之”已正式投入市场。</p> \n<p>　　“羲之”取名自书法家王羲之，“只不过我们的‘毛笔’是电子束，在芯片上刻写电路。”研发团队相关负责人介绍，这台设备专攻量子芯片、新型半导体研发的核心环节，它通过高能电子束在硅基上“手写”电路，精度达到0.6nm，线宽8nm，可灵活修改设计无须掩膜版，如同用纳米级毛笔在芯片上精准作画，特别适合芯片研发初期的反复调试。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4541, NULL, '巴西总统卢拉称已邀请特朗普出席COP30气候大会', 0, 4, 29, '2025-08-14 11:30:17', '2025-08-14 09:45:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/105/w1024h681/20250814/35d1-f630c67cb504dc1a109d08f3a8551538.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxinh2480684.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/105/w1024h681/20250814/35d1-f630c67cb504dc1a109d08f3a8551538.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△巴西总统卢拉（资料图）\">\n <span class=\"img_descr\">△巴西总统卢拉（资料图）</span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月13日，巴西总统卢拉透露，已致函美国总统特朗普，邀请其参加11月在该国帕拉州首府贝伦市举行的《联合国气候变化框架公约》第三十次缔约方大会（COP30）。</p> \n<p cms-style=\"font-L\">　　卢拉表示，已向美国总统特朗普发出邀请，并将要求各国领导人明确表态是否认同需采取更多措施改善地球环境。（总台记者 马天静 冯丽）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/105/w1024h681/20250814/35d1-f630c67cb504dc1a109d08f3a8551538.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4542, NULL, '（讲述·典型故事） 英雄浩气满昆仑——追记在新疆勇救落水群众牺牲的退役军人胥飞', 0, 1, 31, '2025-08-14 11:30:28', '2025-08-14 11:19:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/124/w1080h644/20250814/940a-f36d4a30914e54d697726575a6f8da05.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxinh2520776.shtml', '退役军人事务部', '<p cms-style=\"font-L\">　　昆仑山下，桑株河滚滚流淌。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/124/w1080h644/20250814/940a-f36d4a30914e54d697726575a6f8da05.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"监控视频拍下胥飞营救落水者的最后镜头。（当地供图）\" id=\"0\">\n <span class=\"img_descr\">监控视频拍下胥飞营救落水者的最后镜头。（当地供图）</span>\n</div>\n<p cms-style=\"font-L\">　　时至今日，新疆和田地区皮山县桑株镇艾日格勒村空气中仍弥漫着痛失英雄的悲伤。当地群众路过水渠时，脚步总会不自觉地放慢，目光投向湍急的水流，英雄最后的奋力呐喊和托举生命的身影，仿佛依然清晰。</p>\n<p cms-style=\"font-L\">　　“胥飞是我们心中的英雄，我们会永远怀念他。”一声声对英雄的呼唤，回响在桑株河畔。</p>\n<p cms-style=\"font-L\">　　2025年6月19日15时55分，来自四川射洪的退役军人胥飞勇救当地落水群众，29岁的生命定格在这一刻。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“这一刻，我真正懂得了军人的品格。”</font></p>\n<p cms-style=\"font-L\">　　回忆起胥飞当时的壮举，工友马良红了眼眶。马良与胥飞同时期来到和田，二人年龄相仿，兴趣相投，平时几乎形影不离。事发当天，他们一起去给工地汽车加油。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/789/w1080h509/20250814/3840-d203f5406d0806bacbf9138403153e83.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"监控视频。（当地供图）\" id=\"1\">\n <span class=\"img_descr\">监控视频。（当地供图）</span>\n</div>\n<p cms-style=\"font-L\">　　“如果那天胥飞听到呼救声后继续往前行驶，就不会有生命危险。”马良带领记者重回事发地，声音哽咽得像是被堵住了喉咙。</p>\n<p cms-style=\"font-L\">　　当时，他们正在返回工地的路上，突然听到路边有人大声呼喊。“老乡们喊的是民族语言，我们确实没听懂，但看手势，似乎是有人落水。几乎是一瞬间，胥飞给疾驶的汽车来了一脚急刹，刹车声在空旷的田埂上特别刺耳。”马良说，胥飞想也没想就赶紧调头，车轮碾过路边的碎石子，发出“咯吱咯吱”的响声。</p>\n<p cms-style=\"font-L\">　　胥飞把车开到桥边，二人下车观察确认有人落水，胥飞冲着马良喊：“我当过兵，会游泳，你不要过来！”然后迅速返回车上，把车开到水渠对岸，一路追赶落水者。车子在土路上飞速疾驰，扬起大片尘土。他加足油门，超越落水者，找准时机跳下车，车门都没来得及关，一跃跳入冰冷的水中。</p>\n<p cms-style=\"font-L\">　　马良用低沉的话语，比划着手势，在我们眼前勾勒出胥飞最后的救援现场：奔腾的冰雪融水从远处的昆仑山直冲而下，翻起白色浪花，发出低沉的轰鸣滚滚而来。胥飞站在齐腰深的水中，迎着强劲的水流弯着腰、张开双臂，寻找着落水者的身影。“那一刻，他就像一名严阵以待的战士，准备迎战。”</p>\n<p cms-style=\"font-L\">　　落水的阿卜杜热合曼・艾拜杜拉很快被水流冲到近前，胥飞一把抱住，用尽全力往岸上拽。但强大的水流，很快把他们冲散，胥飞也失去平衡跌入水中。“胥飞拼命抓住落水者，成功让他面部朝上，避免了再次呛水。然后使劲往岸边推，眼看快成功，一阵激流袭来，他们又被冲散……”</p>\n<p cms-style=\"font-L\">　　英勇的举动，带动了更多群众行动。不远处刚收拾完农具准备回家的邻村居民阿卜力孜・麦提吐尔迪看到有人落水，赶忙拿着农具前来救人，见来不及抓住，他便也跳进大渠与胥飞一同救人。奈何主干渠水流湍急，任凭他们怎么努力，始终无法将落水者救上岸。</p>\n<p cms-style=\"font-L\">　　岸边，居民阿卜杜热西提·买提努日和库德热提·艾海提目睹救人的困难，立即报警并果断跳入水中支援。沿途，接到报警的派出所民警、驻村工作队、村干部和附近居民，争分夺秒地从四面八方赶来，大家在沿渠多个渠段，设置了多个拦截救援点。众人拉起绳索、扛来梯子，一次次尝试、一次次接力，历经4次拦截和惊心动魄的30分钟后，终于在距离落水点8公里外的渠段，成功将落水者救起。然而，令人痛心的是，胥飞因体力严重透支再加上长时间浸泡在冰冷的水中导致身体失温休克，虽经全力抢救，仍不幸牺牲，年仅29岁。</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“胥飞是好样的，没给老部队丢脸。”</font></p>\n<p cms-style=\"font-L\">　　2013年，从小怀着军旅梦的胥飞如愿入伍，在驻西藏某部服役。在战友印象中，胥飞一直是一个踏实肯干、乐于助人的“知心战友”，他始终用乐观的性格感染着身边的人。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/290/w1080h810/20250814/484a-0a531a18d030104e5ca2b06abf408eb6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"胥飞退役时与战友合影。（左二为胥飞）（家属供图）\" id=\"2\">\n <span class=\"img_descr\">胥飞退役时与战友合影。（左二为胥飞）（家属供图）</span>\n</div>\n<p cms-style=\"font-L\">　　2018年夏季，胥飞所在部队驻地突遭暴雨袭击。周边村落地势低洼，周边山高林立，面临着洪水、山体滑坡、泥石流的威胁。当地村委会向部队求援，请求派出技术骨干和工程机械，挖掘防洪沟渠。听到这个消息，胥飞主动站了出来：“这个任务我一定能完成好！请组织批准我的请战要求！”胥飞被编入防洪抗灾预备队中担任小组骨干，每天迎着狂风暴雨带领小组成员执行任务。当时天气预报显示，未来7天当地将遭遇更严重的暴雨侵袭，必须在降水量达到极值之前完成防洪沟的挖掘任务，否则藏族同胞的村庄可能会遭遇灭顶之灾。</p>\n<p cms-style=\"font-L\">　　面对危险，胥飞再次挺身而出：“我是机械驾驶骨干，我要去最危险的前沿！”胥飞和其他战友组成突击队，连续驾驶三种工程机械，在山石密布的高原开始了“战斗”。饿了，就在车厢里吃点干粮；困了，就守在设备边眯一会。战友让他撤下去休整，他说：“我们多干一些，群众就会安全一些。不能撤！”</p>\n<p cms-style=\"font-L\">　　当地藏族群众看在眼里，冒雨送来牛肉酥油茶，拉着战士们的手，让大家休息。大家赶忙撑起伞，告诉老乡：“谢谢乡亲们，有我们守护，请大家放心！”</p>\n<p cms-style=\"font-L\">　　在大家共同努力下，五公里长的防洪沟施工完毕，村庄保住了、上百亩农田保住了。胥飞和战友们一身泥泞，湿透的脸上分不清哪是雨水、哪是汗水。</p>\n<p cms-style=\"font-L\">　　雨过天晴，任务圆满完成。村委会带着乡亲们敲锣打鼓来到驻地，把一封村民签名的感谢信和慰问品送到战士们手中。胥飞又恢复了往日的腼腆，红着脸躲在队伍中，脸上带着标志性的微笑，跟身边战友说：“我们是军人，这都是咱们应该做的。”</p>\n<p cms-style=\"font-L\">　　正当胥飞在努力准备军士选晋的时候，噩耗传来，父亲去世，母亲身体每况愈下。再三思量，他决定退役返乡，照顾母亲。时任宣传干事祝禄源还记得，胥飞对着镜头腼腆地说：“感谢部队，我学习到很多。”然后，他挺了挺胸膛，目光忽然坚毅起来，像是下定了某种决心：“我保证，退役后一定做到退役不褪色！”最后的画面，定格在他行庄重军礼的时刻。</p>\n<p cms-style=\"font-L\">　　“若有战，召必回！”姐姐胥英说，这是胥飞经常挂在嘴边的一句话。打开胥飞的衣柜，军装熨烫整齐，被细心地罩住，这是他最珍视的东西。</p>\n<p cms-style=\"font-L\">　　退役后，胥飞依然保持着军人作风。来到胥飞宿舍，工友林杰指着门口左手边的床铺说，这是胥飞的位置。“他的床铺，总是干干净净，被子叠得整整齐齐。早晨起来，他总会抢着整理房间内务，在他身上，我们能感觉到一股‘兵味’。胥飞也经常提起当年在西藏当兵的经历，他感觉现在大家在大山里并肩奋斗，也是‘战友’。”</p>\n<p cms-style=\"font-L\">　　2004年出生的赵少恒，微信里还留着发给胥飞的最后一条信息：“飞哥，干嘛呢？”听到他牺牲的消息，赵少恒两眼一黑，瘫坐在地上。</p>\n<p cms-style=\"font-L\">　　作为年纪最小的工友，胥飞像兄长、像班长一样照顾他。有一次，得知胥飞要去城里办事，赵少恒很不好意思地找到他，说自己想吃肯德基。胥飞笑了笑，一口答应下来。</p>\n<p cms-style=\"font-L\">　　那天特别冷，胥飞直到很晚还没回来，赵少恒以为他肯定把这件事忘了。没想到凌晨时分，胥飞悄悄来到宿舍，把还有余温的汉堡、鸡块放到了桌上。“那天他在城里处理工作到很晚，夜晚山路又难走，他不知道费了多大周折才回来。而且食物还带着余温，或许是他一直紧紧捂在怀里。”讲到这里，这个腼腆的大男孩失声痛哭：“飞哥是多好的大哥哥啊……”</p>\n<p cms-style=\"font-L\">　　“他其实很舍不得部队。”战友张柱说，胥飞责任心强、能力突出，他如果继续在部队，肯定能带出更多好兵。说完，张柱陷入了沉默：“……胥飞是好样的，没给老部队丢脸。”</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">“胥飞是我们的英雄。”</font></p>\n<p cms-style=\"font-L\">　　6月20日，胥飞同志遗体告别仪式在皮山县举行。母亲、姐姐、姐夫来到皮山县，送胥飞最后一程。看着壮实的儿子躺在冰冷的水晶棺中，母亲罗贤益眼神空洞，呆呆地望着前方，满身的力气仿佛被瞬间抽走。</p>\n<p cms-style=\"font-L\">　　那天，落水者仍在医院救治，他的妹妹努尔曼·阿卜杜热西提流着泪找到胥飞母亲，扑通一声跪倒在地，被胥飞母亲赶忙搀起。“胥飞是我们的英雄，他用自己的生命换回了我哥哥的生命，他就是我的哥哥，我真的舍不得他离开。我们永远感恩胥飞和您！”说到这里，二人相拥而泣。</p>\n<p cms-style=\"font-L\">　　在众人的搀扶下，罗贤益沿着水渠，完整走完胥飞最后的一段路。“我对组织没有别的要求，只想走一遍儿子救人的路，看看他当时经历了什么。”</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/200/w1080h720/20250814/88b9-82b6ba8b34eb6f48859305bbe53181da.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"村民自发准备祭品，悼念胥飞。夏华广 摄\" id=\"3\">\n <span class=\"img_descr\">村民自发准备祭品，悼念胥飞。夏华广 摄</span>\n</div>\n<p cms-style=\"font-L\">　　艾日格勒村的乡亲们自发准备了各种民族特色食品、水果，献给心目中的英雄。</p>\n<p cms-style=\"font-L\">　　“胥飞就是民族团结最鲜活的注脚，他的故事将永远在艾日格勒村流传！”在送行的人群中，同为退役军人的和田地区农业科技园驻艾日格勒村第一书记陆岩提起这位牺牲的战友，眼眶泛红，心情沉重：“这些天，村里都在传颂胥飞的事迹，好几位维吾尔族群众找到我，说要给胥飞家人送点东西，表达哀思。多好的巴郎子，要是不牺牲，肯定能为国家做更多事情……”</p>\n<p cms-style=\"font-L\">　　如今，胥飞的名字飞跃昆仑山，传遍祖国各地。在家乡射洪，亲人、朋友、慕名前来送别的群众，纷纷赶来送胥飞最后一程。新疆和田地区皮山县见义勇为评定委员会依法确认胥飞见义勇为行为，正在按照程序启动烈士评定流程。“向胥飞同志学习”的呐喊声响彻各地。网友纷纷留言：“致敬英雄！”“很抱歉以这样一种方式知道你的名字，英雄走好！”“这就是中国军魂！”在留言的网友中，有一位与胥飞重名的网友留言说：“我也叫胥飞，今后一定向他学习，要对得起英雄的名字！”</p>\n<p cms-style=\"font-L\">　　英雄长眠，精神不朽。</p>\n<p cms-style=\"font-L\">　　桑株河的流水会记得，这位退役军人最后一次纵身跃入时的背影；艾日格勒村的炊烟会记得，“好巴郎子”身上那股军人的担当；祖国人民会记得，脱下军装时那句庄严的承诺：退役不褪色！</p>\n<p cms-style=\"font-L\">　　（中国退役军人·全媒体记者 王栋 王非凡 通讯员 夏华广，宋沅城、祝禄源对本文亦有贡献）</p>', '[\"https://k.sinaimg.cn/n/spider20250814/124/w1080h644/20250814/940a-f36d4a30914e54d697726575a6f8da05.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/789/w1080h509/20250814/3840-d203f5406d0806bacbf9138403153e83.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/290/w1080h810/20250814/484a-0a531a18d030104e5ca2b06abf408eb6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/200/w1080h720/20250814/88b9-82b6ba8b34eb6f48859305bbe53181da.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4543, NULL, '受“杨柳”过境福建影响 途经赣深、福厦等高铁线路停运', 0, 1, 13, '2025-08-14 12:30:18', '2025-08-14 12:28:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxpui5406742.shtml', '央视', '<p>　　记者从国铁南昌局了解到，受“杨柳”过境福建的影响，<strong>福建东南部、江西南部等地今天（14日）有大到暴雨，局地有大暴雨或特大暴雨。</strong></p> \n<p>　　为确保铁路运输安全，铁路部门调整部分旅客列车运行方案，<strong>停运途经</strong><strong>赣</strong><strong>深、福</strong><strong>厦</strong><strong>等高铁线路，以及</strong><strong>厦</strong><strong>深、京九等普速铁路部分区段的旅客列车。</strong>同时，在台风过境线路安排人员对设备进行全面检查，确认安全后，在福州、厦门、龙岩、南昌、赣州等城市间<strong>加开18趟中短途旅客列车</strong>，满足旅客出行需要。据了解，<strong>8月15日起，赣闽两省旅客列车将陆续恢复运行秩序。</strong></p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4544, NULL, '云南怒江大雨引发泥石流 有人员伤亡 受灾群众紧急撤离', 0, 1, 25, '2025-08-14 12:30:26', '2025-08-14 11:38:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/44/w550h294/20250814/c00f-b848a05eded9d40b58fce066a0cb4096.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxinh2530277.shtml', '央视', '<p>　　13日傍晚，云南省怒江州持续强降雨天气导致部分地区出现滑坡泥石流等灾害，泸水市称杆乡堵堵洛村<strong>多栋房屋受损，已发现一人遇难，并有人员失联。</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/crawl/44/w550h294/20250814/c00f-b848a05eded9d40b58fce066a0cb4096.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　灾害发生后，称杆边境派出所联合当地消防等职能部门紧急疏散居民群众，<strong>截至今日（14日）10时，已安全转移重点受灾群众10户23人</strong>。目前3台大型机械已进场，抢险救援工作仍在进行，具体受灾情况正在统计中。</p> \n<p>　　（总台记者 李讯）</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/default/crawl/44/w550h294/20250814/c00f-b848a05eded9d40b58fce066a0cb4096.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4545, NULL, '广西武宣:抓实指导督导 助力巡察提质增效', 0, 1, 20, '2025-08-14 13:30:16', '2025-08-14 12:36:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxpui5408329.shtml', '广西纪委监委网站', '<p cms-style=\"font-L \"></p>\n<p cms-style=\"font-L\">　　近日，广西壮族自治区武宣县二塘镇朗村村民方家超向前来走访的巡察干部反馈，村里定期公示集体资金使用情况。“以前不知道钱花在哪里，现在笔笔分明，大家都更加放心了。”</p>\n<p cms-style=\"font-L\">　　今年以来，武宣县在十三届县委第八轮巡察中，坚持通过抓实培训指导、“办组融合”、细化过程督导、压实整改责任，确保对县人民检察院等3个单位的常规巡察，对县农业农村局以及二塘镇朗村等7个行政村的巡察“回头看”工作有序推进、取得实效。</p>\n<p cms-style=\"font-L\">　　“本轮巡察涉及政法系统和农村基层，政策性强、群众关注度高，我们必须把准方向、精准发力。”县委巡察工作领导小组主要负责人表示。为提升巡察干部履职能力，巡察机构采取“专题培训+实战练兵”等模式，围绕党纪法规、财务审计、基层治理等开展针对性培训，巡中不定期邀请纪检监察、组织、审计等部门业务骨干深入巡察现场答疑。</p>\n<p cms-style=\"font-L\">　　参与巡察的第四组干部小梁说：“巡察培训内容很实用，边巡边学，学以致用，特别是对农村集体‘三资’监管的案例分析，让我们在走访群众时更有针对性。”</p>\n<p cms-style=\"font-L\">　　在巡察“回头看”中，各巡察组沉下身子深入一线走访摸排，注重倾听群众呼声，通过“码上巡”“夜访农户”等形式收集问题线索，推动解决民生诉求23件。“巡察组连田间地头的灌溉渠都看了，我们反映的问题也很快有了回音。”东乡镇风沿村一位村民说。</p>\n<p cms-style=\"font-L\">　　本轮巡察中，县委同步派出由县纪委监委、县委组织部、县委巡察办等人员组成的整改督导组，对上一轮被巡察单位的整改情况开展督导检查，对整改不力的3个党组织负责人进行约谈，确保巡察工作巡出震慑、察出实效。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4546, NULL, '贪官挖出327枚比特币？贵州省纪委回应', 0, 1, 24, '2025-08-14 13:30:24', '2025-08-14 12:32:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxpui5407467.shtml', '中国新闻周刊', '<p>　　来源：中国新闻周刊</p> \n<p>　　近日，落马女官员挖出327枚比特币（价值约1.5亿元）的消息引发诸多关注。流传的网络信息显示，这“挖矿”的女官员被指是贵州省大数据发展管理局原局长景亚萍。</p> \n<p>　　多则互联网视频消息显示，这则新闻源自西南一家媒体。记者向这家媒体求证，该媒体相关工作人员表示，此新闻并非该媒体原创，“目前已删稿”。</p> \n<p>　　贵州省纪委监委宣传部的一位工作人员向中国新闻周刊表示，景亚萍利用政府服务器挖出327枚比特币的消息“是谣言”。据其了解，景亚萍的案情并不涉及比特币。</p> \n<p>　　上述工作人员说，此消息最初是一些自媒体利用AI（人工智能）生成的，目的是博流量。后来被一家媒体报道了，相关部门已就此事进行了沟通。</p> \n<p>　　资料显示，景亚萍生于1964年，籍贯四川富顺，出生地贵州遵义，长期在贵州省工作，早年曾任高校教师，后来担任过贵州理工学院副院长、贵州省大数据发展管理局局长等职。</p> \n<p>　　今年2月，景亚萍涉嫌严重违纪违法被查。今年8月初，景亚萍被开除党籍和公职。</p> \n<p>　　官方通报指出，景亚萍丧失理想信念，背弃初心使命，无视中央八项规定精神，收受可能影响公正执行公务的礼品，将应由本人支付的费用交由他人支付；违背组织原则，不如实报告个人有关事项；贪欲膨胀，大搞权钱交易，利用职务上的便利为他人在项目审批、项目承接等方面谋取利益，非法收受巨额财物。</p> \n<p>　　通报还提到，景亚萍严重违反党的组织纪律和廉洁纪律，构成严重职务违法并涉嫌受贿犯罪，且在党的十八大后不收敛、不收手，性质严重，影响恶劣，应予严肃处理。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4547, NULL, '台风“杨柳”肆虐福建：风力发电机吹折腰，车辆被飞落的铁皮架砸中……', 0, 1, 13, '2025-08-14 13:30:34', '2025-08-14 11:57:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/335/w550h585/20250814/a96f-04d7f67b66e9f0f111a02c276a6ef495.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxptz7026990.shtml', '大风新闻', '<!--video-list--> \n<div class=\"video-2017\" id=\"videoList0\"></div>  \n<!--/video-list--> \n<p cms-style=\"font-L \">　　来源：大风新闻</p> \n<p cms-style=\"font-L\">　　8月13日，受台风“杨柳”影响，福建多地出现险情，有的树木被吹倒，汽车被吹落的铁皮架子砸中。</p> \n<p cms-style=\"font-L\">　　华商报大风新闻记者从莆田警方处获悉，台风天，接到很多广告牌被刮落的“报警”。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">&gt;&gt;&gt;飞来横祸</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">台风刮落铁皮架子，路过车辆被砸中</font></p> \n<p cms-style=\"font-L\">　　现场视频显示，疑似在莆田市一处路段，满地落叶，大风将一个铁皮架子吹落，压住一辆路过的车辆，尚不清楚有无人员受伤。</p> \n<p cms-style=\"font-L\">　　“连着下了几个小时的雨。”发视频的网友提醒大家，台风天还是待在室内安全。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/335/w550h585/20250814/a96f-04d7f67b66e9f0f111a02c276a6ef495.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　8月13日，受台风“杨柳”影响，闽粤沿海一带出现大风降雨，福建沿海阵风风力达到8级以上。8月14日00时30分前后，在福建漳浦县沿海登陆，中心附近最大风力达11级（30米/秒）。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/news/crawl/591/w540h851/20250814/6696-732e6c5976d466516ed987ef1f69528f.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　一位网友告诉记者，家住泉州，楼下的车也被大风刮倒的树砸中。“没下雨，但是风特别大，我在家里6楼，就感觉家都像要被吹走了。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">&gt;&gt;&gt;大风肆虐</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">一处风电设备被吹折腰，当地正跟进处理</font></p> \n<p cms-style=\"font-L\">　　此外，一位网友告诉记者，8月13日，福清市沙埔镇东陈村附近，一处架设的风电设备也被大风吹倒，图片显示已拦腰折断，坠落的风叶已受损。</p> \n<div class=\"img_wrapper\">\n <img id=\"2\" src=\"https://k.sinaimg.cn/n/news/crawl/126/w550h376/20250814/ce26-82938993ed8cbd2406c3291cee1bd13b.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　8月14日，记者联系沙埔镇政府，工作人员证实称，刮台风导致风叶坠落，“我们已经有人在跟进处理了，但具体进度不清楚。”</p> \n<p cms-style=\"font-L\">　　此外，有网友表示：“从福建往广东方向的高速都封路了。”记者注意到，受台风影响，福建厦金航线、泉金航线停航；京广铁路、京九铁路部分列车停运，杭深高铁、甬广高铁、梅汕高铁部分列车停运。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">&gt;&gt;&gt;台风惹祸</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">大风刮倒树木，园林局业务科室对接处理</font></p> \n<p cms-style=\"font-L\">　　8月14日，记者联系莆田事故报警平台，民警答复称；“昨天台风天，很多广告牌都掉下来了，昨天这类报警都挺多的。交通指示牌应该是属于路政管，具体需要到现场去查看。”</p> \n<p cms-style=\"font-L\">　　记者联系莆田市园林管理局，工作人员表示被大风刮倒树木是业务科室在对接处理，需要确定具体的路段，市区道路和县道分属于不同的管理部门。</p> \n<p cms-style=\"font-L\">　　“昨天是受台风影响，具体也要看是不是属于我们管的，我们只负责管市属的，它有些是县区管的。”</p> \n<p cms-style=\"font-L\">　　工作人员表示：“这个得问具体业务科室，如果是安装在绿化带上的指示牌或者广告牌不归我们管，有一些是交管部门的，如果是道路安全的指示牌，那归交警管，广告牌是城管管。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">&gt;&gt;&gt;城管回应</font></p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">已终止台风应急响应，会对吹落的广告牌及时清理</font></p> \n<p cms-style=\"font-L\">　　记者联系莆田市城管局，工作人员答复称：“我们可以通知广告商去加固处理。如果是被刮下来的，我们肯定组织人去清理嘛，把它运走，应该是已经有人清走了。现在没有再刮风下雨，我们已经终止台风的应急响应了。”</p> \n<p cms-style=\"font-L\">　　工作人员表示：“因为视频里没办法确认是广告牌，我们还需要确认一下，我们让人员核实一下，如果是的话，我们会及时处理的；如果不是，我们也会直接转交给其他相关部门。”</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">华商报大风新闻记者 李华 编辑 李婧</font></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1755104309\" target=\"_blank\">台风“杨柳”再次登陆</a> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1755001953\" target=\"_blank\">台风“杨柳”来袭</a>\n</div> \n<p class=\"show_author\">责任编辑：刘鹏林 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/335/w550h585/20250814/a96f-04d7f67b66e9f0f111a02c276a6ef495.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/591/w540h851/20250814/6696-732e6c5976d466516ed987ef1f69528f.png/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/news/crawl/126/w550h376/20250814/ce26-82938993ed8cbd2406c3291cee1bd13b.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4548, NULL, '巴基斯坦宣布成立陆军火箭部队司令部', 0, 4, 150, '2025-08-14 14:30:11', '2025-08-14 13:50:00', NULL, NULL, 'https://k.sinaimg.cn/n/sinakd20250814s/533/w800h533/20250814/f5e2-355cfef62da621e27ebaf9963afff2e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxpum3921103.shtml', '中国新闻网', '<p cms-style=\"font-L\">　　当地时间8月13日，巴基斯坦总理夏巴兹·谢里夫在当天庆祝巴基斯坦独立78周年的仪式上宣布成立新的陆军火箭军司令部，以增强国家防御能力。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/sinakd20250814s/533/w800h533/20250814/f5e2-355cfef62da621e27ebaf9963afff2e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△巴基斯坦总理夏巴兹·谢里夫（资料图）\">\n <span class=\"img_descr\"><font cms-style=\"font-L align-Center\">△巴基斯坦总理夏巴兹·谢里夫（资料图）</font></span>\n</div> \n<p cms-style=\"font-L\">　　他表示，新的火箭军司令部将配备最先进的技术，进一步增强巴基斯坦的常规作战能力。</p> \n<p></p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/sinakd20250814s/533/w800h533/20250814/f5e2-355cfef62da621e27ebaf9963afff2e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4549, NULL, '以军批准加沙行动计划大纲 专家：“清空加沙”进入初级阶段', 0, 4, 95, '2025-08-14 14:30:22', '2025-08-14 13:43:00', NULL, NULL, 'https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/dd29-2e140315921272d6ef1117d67e9e8538.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxpum3918138.shtml', '央视', '<p>　　以色列国防军13日称，以军总参谋长扎米尔当天召集会议，以军总参谋部官员、以色列国家安全总局（辛贝特）代表以及其他一些指挥官参与了会议。会议讨论了以军接下来在加沙地带的行动计划大纲，并得到扎米尔的批准。</p> \n<p>　　以军总参谋长批准加沙行动计划大纲，<strong>此举有怎样的目的，对加沙地区形势会造成怎样的影响？</strong></p> \n<p>　　<strong>中东问题专家 董漫远：</strong>从性质上来讲，现在以色列推进的这个军事计划，是未来<strong>所谓的“清空加沙”进入了初级阶段</strong>。根据这个计划，初级阶段需要6个月左右时间完成，其中占领加沙城需要3个月。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/dd29-2e140315921272d6ef1117d67e9e8538.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>中东问题专家 董漫远：</strong>为什么需要3个月呢？以色列打算利用加沙总面积10%的土地，新建4到5个所谓人道主义园区。然后，由美国支持的“加沙人道主义基金会”来管理，把加沙200多万百姓关进去，进去以后就出不来了。只有一个可能——愿意前往其他阿拉伯国家，才能出来。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/35b7-950704f51186e01b03346a5753d4fdcf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>中东问题专家 董漫远：</strong>他认为，这样事实上就把哈马斯开展武装斗争的条件剥夺了，因为进去以后不能挖地道了、资金也进不去了。哈马斯人员如果和民众脱离了接触的话，它是难以生存的。最后恐怕随着战场条件的恶化，就要迫使哈马斯做出分散。</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/5161-c0280f2b1bdcd6c291c1d145ab450eb6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p>　　<strong>中东问题专家 董漫远：</strong>把哈马斯的地面反抗基本消除，然后逼着加沙城的老百姓迁移到南方的马瓦西、拉法地区等等，需要3个月的时间。但以色列军方是这样计划的，将来预备役人员、预备役部队主要从事这警戒以及人员甄别，作战行动由其主要作战部队来进行。当中如果有机会，还不放弃任何对哈马斯迫降、诱降的机会。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1727132934\" target=\"_blank\">加沙局势再度紧张</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/dd29-2e140315921272d6ef1117d67e9e8538.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/35b7-950704f51186e01b03346a5753d4fdcf.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/default/crawl/59/w550h309/20250814/5161-c0280f2b1bdcd6c291c1d145ab450eb6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4550, NULL, '韩国特检组：金建希在传唤调查中行使了缄默权 将于18日再次传唤调查', 0, 4, 105, '2025-08-14 14:30:29', '2025-08-14 13:34:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/247/w2048h1399/20250814/b6bb-119a4dba18f62db737bf9b7eabb97984.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxpui5429917.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/247/w2048h1399/20250814/b6bb-119a4dba18f62db737bf9b7eabb97984.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"△金建希（资料图）\">\n <span class=\"img_descr\">△金建希（资料图）</span>\n</div> \n<p>　　当地时间14日，金建希特检组通报称，韩国前总统尹锡悦夫人金建希在传唤调查中行使了缄默权，特检组将于18日再次对她进行传唤调查。（总台记者 张昀）</p> \n<p>　　<strong>此前报道</strong></p> \n<p cms-style=\"font-L\">　　<strong>金建希接受韩国特检组传唤调查</strong></p> \n<p>　　当地时间14日上午，韩国前总统尹锡悦夫人金建希乘坐韩国法务部的护送车辆抵达金建希特检组所在地，接受被捕后的首次传唤调查。</p> \n<p>　　本月6日，由于牵涉德意志汽车公司股价操纵案、政治掮客介选案等一系列案件，特检组对金建希进行了传唤调查，但她基本否认了所有指控。7日，特检组以涉嫌违反《资本市场法》《政治资金法》和《特定犯罪加重处罚法》等为由提请法院批捕金建希。12日上午，金建希抵达首尔中央地方法院，出席拘捕必要性审查。</p> \n<p>　　12日深夜，韩国首尔中央地方法院签发对金建希的拘捕令，金建希随即被首尔南部拘留所拘押。韩国宪政史上首次出现“前总统夫妇同时被捕”的情况。</p> \n<!--article_adlist[<p cms-style=\"font-L\"></p>]article_adlist--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦夫妇同被羁押</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/247/w2048h1399/20250814/b6bb-119a4dba18f62db737bf9b7eabb97984.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4551, NULL, '安徽省濉溪县“黑臭水体流入农灌区”情况基本属实 相关负责人已停职', 0, 1, 12, '2025-08-14 14:30:37', '2025-08-14 12:59:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxpui5423044.shtml', '央视', '<p cms-style=\"font-L\">　　近日，有网民反映<font cms-style=\"font-L strong-Bold\">“安徽省</font><font cms-style=\"font-L strong-Bold\">濉溪县黑水河黑臭水体流入大平原农灌区，农民无法用于灌溉”</font>问题。濉溪县成立由生态环境、农业农村、水务等部门组成的联合调查组，赶赴现场核查处理。相关情况通报如下：</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">经初核，网民反映情况基本属实。</font>濉溪县已采取筑堤截污、回抽污水、清理淤泥、生态修复等整改措施，同步加密水质监测，最大限度地减少影响。</p> \n<p cms-style=\"font-L\">　　经研究，对百善现代农业综合开发示范区负有监管责任的分管负责人作出停职处理。下一步，濉溪县将根据调查结果，对相关责任人依规依纪依法严肃处理，并在全县范围内举一反三，开展类似问题排查。</p> \n<p cms-style=\"font-L\">　　（总台记者 刘军）&nbsp;&nbsp;</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4552, NULL, '水利部针对贵州省启动洪水防御Ⅳ级应急响应', 0, 1, 24, '2025-08-14 15:30:28', '2025-08-14 14:39:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkxuaa2330816.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息：</font>据水利部网站消息，受台风“杨柳”影响，预计8月14日至15日，贵州将有暴雨到大暴雨，珠江流域西江上游支流北盘江、柳江上游都柳江，长江流域乌江上游、洞庭湖水系沅江上游等主要河流将出现涨水过程，暴雨区内部分中小河流可能发生超警以上洪水。</p>\n<p cms-style=\"font-L\">　　依据《水利部水旱灾害防御应急响应工作规程》，水利部于8月14日14时针对贵州省启动洪水防御Ⅳ级应急响应。要求贵州省水利部门和相关流域管理机构密切关注台风及残留云系、雨水情和汛情发展变化，加强监测预报预警和会商研判，系统、科学、安全、精准调度防洪工程体系，切实落实水库及在建工程安全度汛措施，突出抓好山洪灾害和中小河流洪水防御，协同做好城市内涝防范，及时提请地方转移受威胁群众，做到应转早转、应转尽转、应转快转，确保人民群众生命财产安全。</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4553, NULL, '“杨柳”成为有记录来第73个在闽“二次登陆”的台风', 0, 1, 13, '2025-08-14 15:30:36', '2025-08-14 14:20:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/e3c4-90e802729e1c343cf3f914e6626bf3e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxuai3797949.shtml', '央视', '<p cms-style=\"font-L\">　　今年第11号台风“杨柳”13日中午以强台风级在台湾省台东县沿海登陆。今天凌晨0时30分前后，“杨柳”二次登陆福建省漳浦县沿海，登陆时由台风级减弱为强热带风暴级，这是今年首个登陆福建的台风。</p> \n<p cms-style=\"font-L\">　　台风“杨柳”是今年以来登陆我国的最强台风，也是今年首个登陆福建的台风，同时，<font cms-style=\"font-L strong-Bold\">它还是有气象记录以来，第73个在福建“二次登陆”的台风。</font>登陆福建的台风都有哪些特点呢？一起来看↓↓↓</p> \n<p cms-style=\"font-L\">　　从地理位置上看，登陆福建的台风不容易避开台湾岛。菲律宾吕宋岛和我国台湾岛上的高山对途经该区域的台风有着巨大的削弱作用，这些台风在“二次登陆”福建时，强度会出现明显衰减。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/e3c4-90e802729e1c343cf3f914e6626bf3e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　据中央气象台统计，1949年至2024年间，共有109个台风登陆福建（仅统计热带风暴级及以上级别），其中仅有37个台风直奔福建而来，另72个则是先登陆台湾岛，再二次及以上登陆福建。</p> \n<p cms-style=\"font-L\">　　从登陆地点分布来看，福建沿海各县市都有台风登陆的经历。其中最“招风”的当数福清和连江。同时也可以看出，大部分台风二次登陆福建的地点集中在其中部沿海地区。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/5577-f759872a55b76597a00335b02a63bdda.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　从时间分布上看，6月至10月都可能有台风登陆福建，其中8月最多。根据中央气象台数据统计，1949年至2024年，共有38个台风在8月登陆福建。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1755104309\" target=\"_blank\">台风“杨柳”再次登陆</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/e3c4-90e802729e1c343cf3f914e6626bf3e3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250814/600/w1920h1080/20250814/5577-f759872a55b76597a00335b02a63bdda.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4554, NULL, '美国会山“股神”的好日子到头了？美财长点名佩洛西“通过股票交易发横财”', 0, 4, 207, '2025-08-14 16:30:19', '2025-08-14 15:40:00', NULL, NULL, NULL, 'https://news.sina.com.cn/o/2025-08-14/doc-infkxuaa2362884.shtml', '一财网', '<p cms-style=\"font-L\">　　当地时间周三（8月13日），美国财政部长贝森特呼吁禁止国会议员交易个股。</p> \n<p cms-style=\"font-L\">　　“我将开始推动个股交易禁令，因为这事关众议院和参议院的信誉。” 贝森特当天还点名批评加利福尼亚州民主党众议员佩洛西和俄勒冈州民主党众议员元怀登（Ron Wyden）“通过股票交易发横财”。</p> \n<p cms-style=\"font-L\">　　“当你看看这些令人瞠目结舌的（炒股）回报，所有的对冲基金都会羡慕他们，美国人民值得有更好的选择。”贝森特说。</p> \n<p cms-style=\"font-L\">　　根据国会成员披露的个人财产报告，佩洛西在2024年的收入在780万至4200万美元之间，她与丈夫、风险投资家保罗·佩洛西的净资产估计达到4.13亿美元。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">佩洛西办公室这样回应</font></p> \n<p cms-style=\"font-L\">　　贝森特发表此番言论之际，众议院和参议院共和党领导层正面临压力，他们被要求就近几个月来获得广泛支持的禁止国会成员炒股的提案采取行动。</p> \n<p cms-style=\"font-L\">　　“人们不应该来华盛顿致富，这会降低人们对金融体系的信任度，因为我可以告诉你，如果有任何普通公民以这种方式进行交易，美国证券交易委员会（SEC）都会找上门来。”贝森特说。</p> \n<p cms-style=\"font-L\">　　一直以来，佩洛西因其夫一系列极其成功的股票交易而饱受争议，按照规定，她需要在每年的财务报告中公布这些股票交易的信息。</p> \n<p cms-style=\"font-L\">　　针对贝森特的批评，佩洛西的发言人克雷格（Ian Krager）回应称：“佩洛西（前）议长不持有任何股票，对任何交易都不知情，也没有参与后续交易。”</p> \n<p cms-style=\"font-L\">　　众议员怀登在回应贝森特的批评时则援引一篇报道称，贝森特在成为特朗普内阁官员前“并未完全遵守剥离其金融资产的协议”。</p> \n<p cms-style=\"font-L\">　　“特朗普手下的人根本没资格假装关心伦理道德或股票交易禁令，我对该禁令是支持的。”怀登表示。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">国会山新股民</font></p> \n<p cms-style=\"font-L\">　　除了前述国会山“传统资深股民”外，刚进入国会的新议员的炒股行为也在引发外界关注。</p> \n<p cms-style=\"font-L\">　　34岁的宾夕法尼亚州共和党众议员布雷斯纳汉（Rob Bresnahan）去年刚进国会，近来因频繁的股票交易遭质疑。</p> \n<p cms-style=\"font-L\">　　在进入国会前，布雷斯纳汉曾担任布雷斯纳汉家族公司库哈奇克建筑公司的首席执行官。在竞选时，他曾呼吁禁止国会成员进行股票交易，然而，从布雷斯纳汉披露的个人财政报告看，他的交易量几乎超过其他任何国会成员。</p> \n<p cms-style=\"font-L\">　　根据布雷斯纳汉的个人财务数据，自今年1月宣誓就职以来，布雷斯纳汉至少进行了617次股票交易。</p> \n<p cms-style=\"font-L\">　　布雷斯纳汉曾多次声称他的交易是由他的财务顾问管理的。最近在当地一家电台追问他“为什么不指示他们停止交易”时，布雷斯纳汉反问说：“然后怎么办？把钱全部留在账户里，然后赔钱破产？”</p> \n<p cms-style=\"font-L\">　　今年年初，布雷斯纳汉曾提出一项法案，禁止国会成员及其配偶进行股票交易，而当时他仍在继续进行股票交易。</p> \n<p cms-style=\"font-L\">　　据报道，在特朗普的“大而美法案”在国会通过之前，布雷斯纳汉宣布出售医疗保健公司Centene的股票，后来，该公司因该法案中医疗补助计划的削减而股价暴跌超过一半。</p> \n<p cms-style=\"font-L\">　　佐治亚州共和党众议员格林（Marjorie Taylor Greene）也被看作是一名炒股业绩“非常良好”的国会山新股民。</p> \n<p cms-style=\"font-L\">　　在特朗普宣布所谓“对等关税”政策，美国股市下跌后，格林大举买入了折价股票。她于4月4日买入了科技股Impinj，该股在过去几个月里飙升逾100%。</p> \n<p cms-style=\"font-L\">　　在4月8日买入科技股Palantir后，格林的投资所获得的回报超过115%。Palantir为美国联邦政府，包括五角大楼以及国土安全部提供人工智能解决方案和软件。</p> \n<p cms-style=\"font-L\">　　格林目前是众议院国土安全委员会的成员，该委员会负责批准国土安全部和移民及海关执法局（ICE）的资金。</p> \n<p cms-style=\"font-L\">　　格林也称，她的投资由一位财务顾问管理。</p> \n<p cms-style=\"font-L\">　　“在今年之前，我们只看到一位国会议员购买Palantir的股票。2025年前两个月，我们看到6位不同的议员买入。”股票咨询平台Quiver Quantitative的联合创始人卡尔达茨克（Christopher Kardatzke）表示， “也许他们都共用同一个财务顾问。今年迄今为止，该股已上涨148%。”</p> \n<p class=\"show_author\">责任编辑：刘光博 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4555, NULL, '俄罗斯罗斯托夫市中心发生强烈爆炸', 0, 4, 164, '2025-08-14 16:30:27', '2025-08-14 15:32:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/774/w352h422/20250814/1e72-05ea9372a68f9f6712a26389259a7169.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxuaa2365537.shtml', '央视', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250814/774/w352h422/20250814/1e72-05ea9372a68f9f6712a26389259a7169.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>当地时间8月14日获悉，<font cms-style=\"font-L strong-Bold\">俄罗斯罗斯托夫州罗斯托夫市中心发生强烈爆炸，并升起大量浓烟。</font></p> \n<p cms-style=\"font-L\">　　目前，爆炸的具体细节尚不清楚。</p> \n<p cms-style=\"font-L\">　　据俄罗斯卫星通讯社此前报道，罗斯托夫地区已宣布存在导弹威胁。（总台记者 程谟）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/spider20250814/774/w352h422/20250814/1e72-05ea9372a68f9f6712a26389259a7169.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4556, NULL, '一定之规丨这些扰乱社会管理秩序的行为不能有', 0, 1, 24, '2025-08-14 16:30:36', '2025-08-14 15:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/656/w1320h9736/20250814/8050-060b0320690a95d41255e387e57c73ec.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkxtzx6967841.shtml', '河北省纪委监委网站', '来源：中央纪委国家监委网站\n<br>\n<br>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/656/w1320h9736/20250814/8050-060b0320690a95d41255e387e57c73ec.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>', '[\"https://k.sinaimg.cn/n/spider20250814/656/w1320h9736/20250814/8050-060b0320690a95d41255e387e57c73ec.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4557, NULL, '俄方公布普京与特朗普会谈开始时间', 0, 4, 164, '2025-08-14 17:30:12', '2025-08-14 17:19:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-14/doc-infkxykc5270296.shtml', '界面', '<p cms-style=\"font-L \"></p> \n<p cms-style=\"font-L\">　　俄罗斯总统助理乌沙科夫8月14日通报，普京总统与特朗普总统的会晤将于15日莫斯科时间22点30（北京时间16日凌晨3点30分），在翻译的陪同下以“一对一”形式开始。（CCTV国际时讯）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4558, NULL, '俄罗斯托夫市中心遭无人机袭击 已致13人受伤', 0, 4, 164, '2025-08-14 17:30:22', '2025-08-14 16:11:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250814ac/774/w352h422/20250814/48d1-c79266d4c34301207edbaa8d105ace13.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkxykf3733744.shtml', '央视', '<p cms-style=\"font-L\">　　当地时间14日，俄罗斯罗斯托夫州代州长斯柳萨尔通报称，<font cms-style=\"font-L strong-Bold\">罗斯托夫市中心遭乌克兰无人机袭击，目前已致13人受伤。</font>伤亡人数仍在持续更新当中。</p> \n<p cms-style=\"font-L\">　　当天稍早前，<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>获悉，俄罗斯罗斯托夫州罗斯托夫市中心发生强烈爆炸，并升起大量浓烟。罗斯托夫州代州长斯柳萨尔随后通报称，当地多处居民楼遭无人机袭击。</p> \n<p cms-style=\"font-L\">　　目前，乌克兰方面对此暂无回应。（总台记者 程谟）</p> \n<p></p> \n<p>　　<strong>此前报道</strong></p> \n<p>　　<strong>俄罗斯罗斯托夫市中心发生强烈爆炸</strong></p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/front20250814ac/774/w352h422/20250814/48d1-c79266d4c34301207edbaa8d105ace13.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\"><font cms-style=\"font-L strong-Bold\">总台记者</font></font>当地时间8月14日获悉，<font cms-style=\"font-L strong-Bold\">俄罗斯罗斯托夫州罗斯托夫市中心发生强烈爆炸，并升起大量浓烟。</font></p> \n<p cms-style=\"font-L\">　　目前，爆炸的具体细节尚不清楚。</p> \n<p cms-style=\"font-L\">　　据俄罗斯卫星通讯社此前报道，罗斯托夫地区已宣布存在导弹威胁。（总台记者 程谟）</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1663722974\" target=\"_blank\">俄乌冲突牵动多方博弈</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/front20250814ac/774/w352h422/20250814/48d1-c79266d4c34301207edbaa8d105ace13.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4581, NULL, '巴基斯坦宣布成立火箭兵司令部，印度有人急了：这是学中国的，我们也要有', 0, 4, 150, '2025-08-14 19:30:18', '2025-08-14 17:13:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-14/doc-infkxyiy2282691.shtml', '观察者网', '<p cms-style=\"font-L\">　　据巴基斯坦联合通讯社报道，巴基斯坦总理夏巴兹·谢里夫当地时间13日宣布成立新的陆军火箭兵司令部，以增强国家防御能力。</p> \n<p cms-style=\"font-L\">　　谢里夫表示，新的陆军火箭兵司令部将配备最先进技术，进一步增强巴基斯坦的常规作战能力。</p> \n<p cms-style=\"font-L\">　　当天，谢里夫在庆祝巴基斯坦独立78周年盛大仪式上宣布了上述消息。</p> \n<p cms-style=\"font-L\">　　路透社援引一位巴高级安全官员的话称，新的火箭兵司令部将专门负责在常规战争中管理和部署导弹。</p> \n<p cms-style=\"font-L\">　　该官员还表示，“很明显，这是针对印度的。”</p> \n<p cms-style=\"font-L\">　　印度空军退役上校奥古斯丁·维诺德在《欧亚时报》上发文称，巴基斯坦的陆军火箭兵司令部是“明确仿照”中国人民解放军火箭军而成立的“新军事实体”。</p> \n<p cms-style=\"font-L\">　　文章称，巴方此举在印度新德里的战略界引起了波澜，并建议说，作为应对，印度也迫切需要建立自身的独立火箭部队。</p> \n<p cms-style=\"font-L\">　　今年5月7日至10日，印巴两国爆发短暂军事冲突，随后达成停火协议。</p> \n<p cms-style=\"font-L\">　　谢里夫8月13日表示，两国的军事冲突在三到四天内以巴方决定性胜利而告终，给印度带去了永远无法忘记的教训。</p> \n<p cms-style=\"font-L\">　　谢里夫还说，感谢中国、土耳其、伊朗等友好国家在冲突期间为巴方提供的支持。</p> \n<p cms-style=\"font-L\">　　</p> \n<p class=\"show_author\">责任编辑：祝加贝 </p>', NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4588, NULL, '黄色预警！湖北、湖南等地部分地区发生地质灾害的气象风险较高', 0, 1, 17, '2025-08-14 20:30:55', '2025-08-14 18:02:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250814/700/w821h679/20250814/c114-1678c4d7efcde98612827f11fc1e6abc.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkyert6817088.shtml', '央视网', '<p>　　来源：央视网</p>\n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">央视网消息：</font>自然资源部与中国气象局8月14日18时联合发布地质灾害气象风险预警：</p>\n<p cms-style=\"font-L\">　　预计，8月14日20时至15日20时，湖北西南部、湖南西部、广东北部和南部、广西北部、重庆东南部、贵州东南部和东部、云南西部等地部分地区发生地质灾害的气象风险较高（黄色预警）。</p>\n<p cms-style=\"font-L\">　　各级政府及有关部门按照应急预案做好地质灾害防御工作。请社会公众及时关注地质灾害气象风险预警信息，谨慎前往地质灾害预警区域。黄色预警区内人员，请随时关注预警信息变化，注意附近警示标志，避免在沟谷、斜坡、陡崖（坎）等高风险地带逗留。</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250814/700/w821h679/20250814/c114-1678c4d7efcde98612827f11fc1e6abc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>', '[\"https://k.sinaimg.cn/n/spider20250814/700/w821h679/20250814/c114-1678c4d7efcde98612827f11fc1e6abc.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4595, NULL, '意媒：曼联对桑乔要价不贵，但他要600万税后年薪1000万经纪佣金', 0, 4, 96, '2025-08-14 21:30:15', '2025-08-14 21:15:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/193/w550h443/20250814/e301-367dc1021ec13283563a23c308a20d4f.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-14/doc-infkykxr6723176.shtml', '直播吧', '<p cms-style=\"font-L \">　　来源：直播吧</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/193/w550h443/20250814/e301-367dc1021ec13283563a23c308a20d4f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　直播吧8月14日讯 据Ilromanista报道称，曼联对桑乔要价不算贵，但球员要税后600万欧年薪＋1000万欧经纪人佣金。</p> \n<p cms-style=\"font-L\">　　桑乔至少早在1个月前就准备离开曼联，但目前还没有任何俱乐部与红魔达成一致。从接下来要提到的一些数据来看，各家俱乐部在完成这笔交易上遇到的困难似乎也不难理解，毕竟不止罗马，切尔西和国米等多支球队都曾对桑乔感兴趣，但都没能拿下他。</p> \n<p cms-style=\"font-L\">　　<font cms-style=\"font-L strong-Bold\">目前由中间人马修-康宁代表的曼联方面为桑乔标价2000万欧元，尽管他与曼联的合同直到2026年6月才到期，但这个价格到本月底可能会下降近一半。到目前为止，这一切还不算离谱，问题出在球员本人及其团队的要求：桑乔希望的税后年薪略高于600万欧元，而他的经纪人埃梅卡-奥巴西甚至提出了近1000万欧元的佣金要求。</font></p> \n<p cms-style=\"font-L\">　　这种要价，让给交易毫无进展可言。如果到了8月末这些要求有所下降，事情也许还能重新推进，尤其是如果曼联激活合同中可续约一年的条款，那可能就会转向租借的方式。</p> \n<p cms-style=\"font-L\">　　如果说桑乔的交易被认为非常复杂，那么关于罗马和埃切维里的传闻基本可以说已经落空。还算有希望的是来自狼队的法比奥-席尔瓦，不过多特蒙德和莱比锡都非常认真地在追逐这位球员。相比之下，更有可能的是顿涅茨克矿工的巴西边锋埃吉纳尔多，马萨拉仍在密切关注这笔交易：预计花费不到1500万欧元。</p> \n<p cms-style=\"font-L\">　　至于齐奥尔科夫斯基的交易，已经进入最后细节阶段：一切应该会在圣母升天节（8月15日）后尘埃落定，让他可以参加本队明天对阵AEK拉纳卡的欧联资格赛。</p> \n<p cms-style=\"font-L\">　　在转出方面：关于恩迪卡的沙特俱乐部传闻越来越多；多夫比克暂无报价，一旦他离队，克尔斯托维奇仍是备选目标之一，但罗马和莱切已经超过20天没有联系了。</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1749081642\" target=\"_blank\">2025国际足坛夏季转会窗</a>\n</div> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/193/w550h443/20250814/e301-367dc1021ec13283563a23c308a20d4f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4596, NULL, '广西：部分地区出现基孔肯雅热疫情，倡议开展“清除蚊虫孳生地，防控蚊媒传染病”爱国卫生运动', 0, 1, 20, '2025-08-14 21:30:26', '2025-08-14 21:20:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-14/doc-infkykxx5115642.shtml', '界面', '<p cms-style=\"font-L \"></p> \n<p cms-style=\"font-L\">　　8月14日，“广西疾控”微信公众号发布关于开展“清除蚊虫孳生地，防控蚊媒传染病”爱国卫生运动的倡议书。全文如下：</p> \n<p cms-style=\"font-L\">　　广大居民朋友们：</p> \n<p cms-style=\"font-L\">　　近期，我区部分地区出现基孔肯雅热疫情，其主要传播媒介白纹伊蚊（俗称“花蚊子”）在全区广泛分布，个人感染风险持续上升。</p> \n<p cms-style=\"font-L\">　　防蚊灭蚊是防控蚊媒传染病最经济、最有效的根本措施。为守护您和家人的健康，广西壮族自治区爱国卫生运动委员会办公室呼吁全区各企事业单位、学校、建筑工地、村（社区）、家庭及全体居民立即行动，充分利用休息时间，开展以清除蚊虫孳生地和杀灭成蚊为重点的爱国卫生运动，共创美好健康生活！</p> \n<p cms-style=\"font-L\">　　一、清洁换水，做好屋内卫生</p> \n<p cms-style=\"font-L\">　　（一）给水生植物换水，并刷洗花盆（瓶）；撤掉土养植物花盆托，或浇水后及时倾倒花盆托积水。水生植物应每3—5天换水并洗刷容器、冲洗植物根部，条件允许的改为泥沙种养或封闭容器开口，或直接弃养，不给蚊虫产卵孳生提供机会。</p> \n<p cms-style=\"font-L\">　　（二）及时清理室内易积水的容器、区域，如蓄水桶、腌菜坛、洗衣机底部、拖把池（桶）、地漏、窗户槽等部位。</p> \n<p cms-style=\"font-L\">　　（三）开展一次彻底的搬家式清洁行动，全面清理积存垃圾和杂物，减少蚊虫藏匿。</p> \n<p cms-style=\"font-L\">　　二、翻坛倒罐，做好屋外卫生</p> \n<p cms-style=\"font-L\">　　（一）认真检查房前屋后、夹巷、天台、阳台，暂时闲置不用的容器（如花盆、瓦罐等）应当逐一翻转倒放；清除院落内的泡沫箱、一次性杯子、饭盒等各类废弃容器，清理绿化带内的垃圾；定期清理杂草落叶；堵塞树洞、假山石洞。</p> \n<p cms-style=\"font-L\">　　（二）阳台、天台、绿地、菜园里的蓄水池、缸、盆、桶等应加盖密封或投放灭蚊幼药物，空调接水容器及时清倒。</p> \n<p cms-style=\"font-L\">　　（三）雨后楼顶、屋檐和阳台等容易因为排水管道堵塞造成积水，挡雨篷布也容易积水，要注意及时检查清理。</p> \n<p cms-style=\"font-L\">　　（四）清理各类水坑、水塘，填平洼地。</p> \n<p cms-style=\"font-L\">　　（五）旧轮胎可采用防雨布遮盖、滴入废机油、戳洞等方式避免蚊虫孳生。</p> \n<p cms-style=\"font-L\">　　三、正确使用卫生杀虫剂，做好个人防护</p> \n<p cms-style=\"font-L\">　　（一）安装纱门和纱窗，日常要关严；睡觉使用蚊帐，防止成蚊入侵叮咬。</p> \n<p cms-style=\"font-L\">　　（二）室内发现有蚊虫时，可选用气雾剂、蚊香、电热蚊香液（片）等卫生杀虫剂或使用电蚊拍。</p> \n<p cms-style=\"font-L\">　　（三）前往公园、河边等蚊虫密度高的区域，要做好防蚊措施，穿着浅色长衣长裤，或使用有农药登记证（WP开头）的驱蚊液喷涂在裸露皮肤和衣物上。</p> \n<p cms-style=\"font-L\">　　（四）外出旅行、工作，要提前了解目的地的蚊媒传染病疫情信息，准备好防蚊物品；如有发热、皮疹或关节痛症状，立即到正规医院就诊，同时做好个人防护，避免蚊虫叮咬传染给其他人。</p> \n<p cms-style=\"font-L\">　　居民朋友们，蚊子虽小，却可能危害你我健康，清洁家园，人人有责，人人受益。让我们积极行动起来，从大扫除做起，从自身做起，用自觉守护小家，用合力保卫大家，让蚊子无处藏身，让病毒无法传播，共同守护自己和家人的健康！</p> \n<p cms-style=\"font-L\">　　广西壮族自治区爱国卫生运动委员会办公室</p> \n<p cms-style=\"font-L\">　　2025年8月14日</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1753229908\" target=\"_blank\">多地现基孔肯雅热疫情</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4605, NULL, '世界人形机器人运动会特许店火爆，徽章爱好者狂喜！', 0, 1, 1, '2025-08-14 23:30:25', '2025-08-14 21:14:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/transform/60/w550h310/20250814/8f66-8b27808b9654e682146e85f060abaa20.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkykxu2145778.shtml', '北京日报客户端', '<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/news/transform/60/w550h310/20250814/8f66-8b27808b9654e682146e85f060abaa20.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\" data-link=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　8月14日，北京国家速滑馆西门，世界人形机器人运动会特许商品店成了赛事期间热闹的消费地标。限量版机器人徽章、机器人马拉松徽章设计非常精美，吸引了许多徽章爱好者前来购买！</p> \n<p class=\"show_author\">责任编辑：过博文 </p>', '[\"https://k.sinaimg.cn/n/news/transform/60/w550h310/20250814/8f66-8b27808b9654e682146e85f060abaa20.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4606, NULL, '“馆长”深圳行引发两岸热议，无滤镜直播打破“民进党滤镜”', 0, 2, 194, '2025-08-15 00:30:22', '2025-08-14 23:12:00', NULL, NULL, 'https://k.sinaimg.cn/n/front20250814ac/62/w1000h662/20250814/f295-9e562852cce7e923905044d69116f5fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-14/doc-infkyrfx3504770.shtml', '直新闻　', '<p cms-style=\"font-L\">　　来源：直新闻　</p> \n<p cms-style=\"font-L\">　　观看量超115万，评论区被“统一”呼声填满。这是台湾网红“馆长”陈之汉深圳行首场直播最直接的效果。</p> \n<p cms-style=\"font-L\">　　这场全程无滤镜地展示大陆科技进步、城市发展和民众热情的直播，打破了台湾网友对大陆的刻板印象，激发了他们对大陆的好奇与探索欲望，在网络上引发“跟着馆长游大陆”的热潮。热潮之下不堪一击的，是民进党苦心经营的“信息茧房”。</p> \n<p cms-style=\"font-L\">　　14日下午两点， “馆长”深圳之行的直播，如约而至。在无人驾驶出租车上，“馆长”大喊：“我超紧张啊！伙计（指无人驾驶出租车），你稳点啊！”当看到机器人能自如地起坐、步行，甚至动感起舞，“馆长”直呼：“台湾同胞，我从来没有唬烂（闽南方言，意为夸大其词）的，中国人就是世界第一！”</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/front20250814ac/62/w1000h662/20250814/f295-9e562852cce7e923905044d69116f5fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L align-Center\">　　留言区被“统一”填满了</p> \n<p cms-style=\"font-L\">　　“馆长”的直播，拉近了两岸民众的心理距离。这两天在深圳的直播当中，他多次用质朴的话语道出了对祖国统一的深切期盼，真情流露且毫无矫饰。他总能以真诚打动观众，引发评论区和弹幕中“两岸一家亲”“统一是心声”的强烈共鸣，让广大网友在直播中感受到那份共同的民族归属感与和平的希望。以8月13日为例，长达7小时的直播，观看次数高达115万，点赞量4.4万；超过4000条评论中，期盼祖国统一的相关内容占据主流。</p> \n<p cms-style=\"font-L\">　　“馆长”的直播展现了大陆的科技成就与经济活力，从而消减误解、增强民族认同感。13日下午在大疆欢乐海岸旗舰店，“馆长”体验了大疆的产品后，对大疆的产品不吝赞美之词，称自己购买的大疆设备表现十分出色，市面上没有能与之媲美的品牌，“大疆不用打广告，大疆强到必须所有人买大疆”。</p> \n<p cms-style=\"font-L\">　　最有力量的，永远是真实。13日晚，无人机再一次带给“馆长”不一样的震撼。在深圳人才公园，2000架无人机的飞行表演，让“馆长”颇为感慨。他坦言，台湾没有这种表演形式，“台湾朋友应该很期待，让他们瞧瞧中国人的厉害”。在与粉丝现场交流过程中，“馆长”认为，两岸的民间交流越频繁，“我们两岸在一起的时机就越来越快”。此外，“馆长”还喊话岛内同胞，希望他们多到大陆走走、看看，“大陆对台湾人特别友爱，特别友爱。台湾人真的幸福，他们自己没来过，不知道”。</p> \n<p cms-style=\"font-L align-Center\">　　台湾网友：“求祖国收留了”</p> \n<p cms-style=\"font-L\">　　“馆长”的直播，为台湾年轻人提供了重新认识大陆的契机，激起了不少网友的共鸣。有祖籍是福建省龙岩市的台湾网友留言：“我是台湾人更是中国人！同宗同源永远是都是中国人。”不少台湾网友还纷纷表达对“馆长”的感谢，让大家得以看见大陆的真实情况，“好感动！看到大陆现在建设是多么好、人也好热情”“求祖国收留了”“这是‘馆长’的一小步，却是两岸同胞的一大步”“我为我的祖国中国感到无比的光荣与骄傲”。</p> \n<div class=\"img_wrapper\">\n <img id=\"1\" src=\"https://k.sinaimg.cn/n/front20250814ac/42/w1024h618/20250814/e9ef-942beb214618eeef0f7351c175151959.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　对于“馆长”的深圳之行，台湾“中时新闻网”13日引述台湾地区前民意代表邱毅的话指出，深圳从一个落后小渔村，到现在成为繁华的“明珠”，“馆长”可利用这次机会，为深圳的“美丽传奇”，留下永恒的脚注。邱毅还向“馆长”喊话，或许他也可以在这个城市找到灵感，找到机遇，找到朋友伙伴，“成为下一个郭台铭，下一个王传福”。</p> \n<p cms-style=\"font-L\">　　台湾“今日新闻”13日以《“馆长”在深圳！赞“比亚迪舒适”、“台湾人要回家”：气死民进党》为题，对“馆长”第一天的深圳之行进行了报道。报道中提到，“馆长”要让台湾民众近距离了解大陆科技发展状况，“我以后更有底气回台湾告诉同胞，其实大家应该回家，不是敌人，而是家人，家人就该手牵手”。</p> \n<p cms-style=\"font-L\">　　针对“馆长”的直播，台湾新党副主席李胜峰在14日的一档岛内政论节目中感慨，秉持“两岸一家人”的理念，可以解决很多问题，但“如果今天不敢面对大陆，我们就有解决不了的问题；如果台湾不敢面对大陆的很多现实，那么我们就要面对更多的困难”。</p> \n<p cms-style=\"font-L align-Center\">　　“馆长”的长镜头直播 拉近两岸民心</p> \n<p cms-style=\"font-L\">　　从今年6月的上海、杭州之行，到这次深圳，“馆长”用真实、接地气的直播，展现大陆的现代化与人文温度，戳破了民进党当局长期灌输的“大陆落后”谎言，瓦解了民进党通过媒体和教育对大陆构建的负面刻板印象，引发巨大反差效应。</p> \n<p cms-style=\"font-L\">　　“馆长”6月六天五夜大陆行，前5天的9场直播累计观看次数突破2000万，最高同时在线人数43万，创下台湾YouTube纪录，这也在一定程度上反映了台湾民众——尤其是40岁以下从未到过大陆的群体，对大陆真实状况的好奇与渴望。同时，也引发了岛内网友对民进党制造的“信息茧房”的反思，激发广泛共鸣，促进了台湾民众对大陆的重新认知。</p> \n<p cms-style=\"font-L\">　　正如馆长所言，“两岸是自家人”。民间交流的热潮势不可挡，为两岸关系注入理性与善意，自然也能拉近民心。</p> \n<p cms-style=\"font-L\">　　作者丨郭永佶</p> \n<p cms-style=\"font-L\">　　排版丨赖信宏</p> \n<p cms-style=\"font-L\">　　编辑丨侯军义</p> \n<p cms-style=\"font-L\">　　审校丨李怡</p> \n<p cms-style=\"font-L\">　　监制丨周玉</p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/front20250814ac/62/w1000h662/20250814/f295-9e562852cce7e923905044d69116f5fe.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/front20250814ac/42/w1024h618/20250814/e9ef-942beb214618eeef0f7351c175151959.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4607, NULL, '苏丹武装部队总司令：不会与快速支援部队和解', 0, 4, 184, '2025-08-15 01:30:14', '2025-08-15 00:54:00', NULL, NULL, 'https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250815/d71b-2701e1d0be05a7123e9f60023c019a10.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-15/doc-infkyrfv5041932.shtml', '央视新闻客户端', '<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250815/d71b-2701e1d0be05a7123e9f60023c019a10.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月14日，苏丹主权委员会主席兼武装部队总司令布尔汉表示，<font cms-style=\"font-L strong-Bold\">苏丹武装部队不会与苏丹快速支援部队进行和解</font>。</p> \n<p cms-style=\"font-L\">　　布尔汉当天在苏丹武装部队成立一百周年之际发表讲话称，<font cms-style=\"font-L strong-Bold\">苏丹武装部队将不惜一切代价击败快速支援部队，不会对其作出任何妥协，不会与其进行和解</font>。</p> \n<p cms-style=\"font-L\">　　布尔汉此前曾多次表示，苏丹武装部队拒绝与快速支援部队谈判，将继续战斗，直至将快速支援部队彻底“铲除”。</p> \n<p cms-style=\"font-L\">　　2023年4月15日，苏丹武装部队与快速支援部队在首都喀土穆爆发武装冲突，战火随后蔓延至其他地区。持续两年多的武装冲突已造成近3万人丧生，超1200万人流离失所。（总台记者 赵远方）<span class=\"img_descr\"></span></p> \n<p class=\"show_author\">责任编辑：于啸歌 </p>', '[\"https://k.sinaimg.cn/n/news/crawl/123/w550h373/20250815/d71b-2701e1d0be05a7123e9f60023c019a10.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
