INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4696, NULL, '海南：取消普通住宅和非普通住宅标准', 0, 1, 21, '2025-08-15 10:30:56', '2025-08-15 09:48:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-15/doc-infkznmc6237976.shtml', '界面', '<p cms-style=\"font-L\">　　海南省住房和城乡建设厅发布进一步优化调整有关调控政策的通知，其中提到，取消海南省普通住宅和非普通住宅标准。同时，根据《中华人民共和国土地增值税暂行条例》第八条第一项，纳税人建造普通标准住宅出售，增值额未超过扣除项目金额20%的，继续免征土地增值税，普通住宅免税标准按照《海南省人民政府关于明确普通住宅认定标准的通知》（琼府﹝2019﹞40号）有关规定执行。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4697, NULL, '海南进一步优化调整有关调控政策，支持盘活存量房地产用地和用房', 0, 1, 21, '2025-08-15 10:31:06', '2025-08-15 09:41:00', NULL, NULL, NULL, 'https://news.sina.com.cn/c/2025-08-15/doc-infkznmh1636008.shtml', '界面', '<p cms-style=\"font-L\">　　8月15日，海南省住房和城乡建设厅等部门发布关于进一步优化调整有关调控政策的通知：</p> \n<p cms-style=\"font-L\">　　一、支持盘活存量房地产用地和用房</p> \n<p cms-style=\"font-L\">　　（一）结合本地区实际需求，稳妥有序推进收购存量商品房用作保障性住房、城中村和危旧房改造安置房。继续利用住房公积金增值收益收购适量存量商品住房房源用作公共租赁住房，谋划用好保障性住房再贷款收购存量商品房用作保障性住房配售或租赁。收购存量商品房用作保障性租赁住房的，可适当放宽收购面积标准。</p> \n<p cms-style=\"font-L\">　　（二）进一步盘活存量商服用地和商办用房，支持商服用地转型用于发展鼓励类产业，依法依程序调整为安居房、租赁住房等用地。符合住宅设计相关强制性规范并经论证通过的商办用房，可转型为租赁住房、安居房。具体政策措施按资规、住建部门有关规定执行。</p> \n<p cms-style=\"font-L\">　　（三）对商品住房去化期高的市县，在推动城市更新过程中，涉及被征迁居民安置的，鼓励优先采用“以购代建”方式安置，支持采用房票方式安置，鼓励收购商品房用于城中村改造安置房。</p> \n<p cms-style=\"font-L\">　　二、加大财税、金融支持力度</p> \n<p cms-style=\"font-L\">　　（四）取消我省普通住宅和非普通住宅标准。同时，根据《中华人民共和国土地增值税暂行条例》第八条第一项，纳税人建造普通标准住宅出售，增值额未超过扣除项目金额20%的，继续免征土地增值税，普通住宅免税标准按照《海南省人民政府关于明确普通住宅认定标准的通知》（琼府﹝2019﹞40号）有关规定执行。</p> \n<p cms-style=\"font-L\">　　（五）多孩家庭（二孩及以上）申请商业贷款购买商品住房时，家庭成员在拟购住房所属市县名下已有住房的，套数认定核减一套，银行业金融机构按有关部门出具的套数查询结果或认定证明执行住房信贷政策。</p> \n<p cms-style=\"font-L\">　　（六）继续支持居民改善住房条件，符合国家有关规定的出售自有住房并在现住房出售后1年内在同一市县市场重新购买住房的纳税人，对其出售现住房已缴纳的个人所得税按规定予以退税优惠。</p> \n<p cms-style=\"font-L\">　　三、着力满足引进人才住房需求</p> \n<p cms-style=\"font-L\">　　（七）引进人才已享受各市县推出的专项购房补贴政策，可继续申领引进人才购房补贴。引进人才可凭保障性租赁住房相关租赁凭证，申请人才住房租赁补贴。</p> \n<p cms-style=\"font-L\">　　四、优化相关审批措施</p> \n<p cms-style=\"font-L\">　　（八）推行适宜的装配式技术体系。对因技术原因不宜采用装配式方式建造的新建项目，由建设单位报省装配式建筑联席会议办公室，经专家论证后采取其他方式建造。</p> \n<p cms-style=\"font-L\">　　（九）坚持商品住宅全装修制度，按照试点先行、稳步推进的总体原则，由海口市先行探索，进一步优化现房销售节点，具体试点方案由海口市相关部门报省住房城乡建设厅备案。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4698, NULL, '“两山”绿美看中原', 0, 1, 16, '2025-08-15 10:31:10', '2025-08-15 09:40:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/2d16-0b4babd192a6150e4fd005f06e83b2b3.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/c/2025-08-15/doc-infkznmc6219819.shtml', '河南省政府网站', '来源：河南政府网\n<br>\n<br>\n<p cms-style=\"font-L align-Center\">　　青山不老</p>\n<p cms-style=\"font-L align-Center\">　　碧水东流</p>\n<p cms-style=\"font-L align-Center\">　　绿水青山</p>\n<p cms-style=\"font-L align-Center\">　　是最美的诗和远方</p>\n<p cms-style=\"font-L align-Center\">　　是当下的金山银山</p>\n<p cms-style=\"font-L align-Center\">　　今天是第三个全国生态日</p>\n<p cms-style=\"font-L align-Center\">　　也是“两山”理念</p>\n<p cms-style=\"font-L align-Center\">　　提出二十周年的日子</p>\n<p cms-style=\"font-L align-Center\">　　近些年来河南通过</p>\n<p cms-style=\"font-L align-Center\">　　打造山水林田湖草沙生命共同体</p>\n<p cms-style=\"font-L align-Center\">　　走好绿色发展之路</p>\n<p cms-style=\"font-L align-Center\">　　写出“两山”生态答卷</p>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【山】</font></p>\n<p cms-style=\"font-L align-Center\">　　太行伏牛桐柏</p>\n<p cms-style=\"font-L align-Center\">　　蜿蜒秦岭余脉</p>\n<p cms-style=\"font-L align-Center\">　　山是河南的脊梁</p>\n<p cms-style=\"font-L align-Center\">　　山有自然的底色</p>\n<p cms-style=\"font-L align-Center\">　　三面环山的河南</p>\n<p cms-style=\"font-L align-Center\">　　塑造最硬的家底</p>\n<p cms-style=\"font-L align-Center\">　　矿山疮痍，细致修复</p>\n<p cms-style=\"font-L align-Center\">　　荒山石漠，科学疗愈</p>\n<p cms-style=\"font-L align-Center\">　　飞播造林，增加绿度</p>\n<p cms-style=\"font-L align-Center\">　　通过统筹实施山水工程</p>\n<p cms-style=\"font-L align-Center\">　　建成生态环境监测系统</p>\n<p cms-style=\"font-L align-Center\">　　严格生态保护红线监管</p>\n<p cms-style=\"font-L align-Center\">　　山色抹上苍翠色</p>\n<p cms-style=\"font-L align-Center\">　　成为诗意的远方</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/2d16-0b4babd192a6150e4fd005f06e83b2b3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"0\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【水】</font></p>\n<p cms-style=\"font-L align-Center\">　　山清水秀，本是一体</p>\n<p cms-style=\"font-L align-Center\">　　青山涵养了水源</p>\n<p cms-style=\"font-L align-Center\">　　山泉汇成了河流</p>\n<p cms-style=\"font-L align-Center\">　　纵跨四大流域的河南</p>\n<p cms-style=\"font-L align-Center\">　　河流织出繁密的水网</p>\n<p cms-style=\"font-L align-Center\">　　整治工业污染源</p>\n<p cms-style=\"font-L align-Center\">　　保护饮用水源地</p>\n<p cms-style=\"font-L align-Center\">　　排查水污染问题</p>\n<p cms-style=\"font-L align-Center\">　　让河水更清澈</p>\n<p cms-style=\"font-L align-Center\">　　让母亲河苏醒</p>\n<p cms-style=\"font-L align-Center\">　　看湖光山色相映</p>\n<p cms-style=\"font-L align-Center\">　　看天光云影徘徊</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/f2e8-3ae01565abb72f7bfb87df4fba037757.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"1\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【林】</font></p>\n<p cms-style=\"font-L align-Center\">　　山水有清音</p>\n<p cms-style=\"font-L align-Center\">　　山水能生金</p>\n<p cms-style=\"font-L align-Center\">　　青山白水，绿色富民</p>\n<p cms-style=\"font-L align-Center\">　　林木加工成了家具</p>\n<p cms-style=\"font-L align-Center\">　　果树托举出了香甜</p>\n<p cms-style=\"font-L align-Center\">　　森林发展起了康养</p>\n<p cms-style=\"font-L align-Center\">　　山区开发出了旅游</p>\n<p cms-style=\"font-L align-Center\">　　大食物观下，前景广阔</p>\n<p cms-style=\"font-L align-Center\">　　向森林要食物</p>\n<p cms-style=\"font-L align-Center\">　　绿色粮仓放异彩</p>\n<p cms-style=\"font-L align-Center\">　　中药花卉，鸡鸭成群</p>\n<p cms-style=\"font-L align-Center\">　　绿色银行，林下生金</p>\n<p cms-style=\"font-L align-Center\">　　森林成了聚宝盆</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/c31b-c5db0f48da8126ab86f75c4462311482.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"2\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【田】</font></p>\n<p cms-style=\"font-L align-Center\">　　绿满山原白满川</p>\n<p cms-style=\"font-L align-Center\">　　子规声里雨如烟</p>\n<p cms-style=\"font-L align-Center\">　　山水是脉络</p>\n<p cms-style=\"font-L align-Center\">　　农田如棋枰</p>\n<p cms-style=\"font-L align-Center\">　　江河润厚土</p>\n<p cms-style=\"font-L align-Center\">　　厚土育食粮</p>\n<p cms-style=\"font-L align-Center\">　　河南是全国粮食生产核心区</p>\n<p cms-style=\"font-L align-Center\">　　也是小麦主产区</p>\n<p cms-style=\"font-L align-Center\">　　严守着耕地红线</p>\n<p cms-style=\"font-L align-Center\">　　打造着高标准农田</p>\n<p cms-style=\"font-L align-Center\">　　从“会种田”到“慧种田”</p>\n<p cms-style=\"font-L align-Center\">　　从藏粮于地，到藏粮于技</p>\n<p cms-style=\"font-L align-Center\">　　麦浪滚滚，稻香阵阵</p>\n<p cms-style=\"font-L align-Center\">　　端稳“中国饭碗”</p>\n<p cms-style=\"font-L align-Center\">　　展现河南担当</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/c70f-d2dc6c64152f665e418302072aff7386.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"3\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【湖】</font></p>\n<p cms-style=\"font-L align-Center\">　　人行明镜中</p>\n<p cms-style=\"font-L align-Center\">　　鸟度屏风里</p>\n<p cms-style=\"font-L align-Center\">　　以后的河南河湖</p>\n<p cms-style=\"font-L align-Center\">　　要加入更多李白诗中的意境</p>\n<p cms-style=\"font-L align-Center\">　　山水有山水的韵味</p>\n<p cms-style=\"font-L align-Center\">　　河湖有河湖的幸福</p>\n<p cms-style=\"font-L align-Center\">　　通过“五年计划”</p>\n<p cms-style=\"font-L align-Center\">　　让河安湖晏</p>\n<p cms-style=\"font-L align-Center\">　　让水清鱼跃</p>\n<p cms-style=\"font-L align-Center\">　　让岸绿景美</p>\n<p cms-style=\"font-L align-Center\">　　更宜居宜业</p>\n<p cms-style=\"font-L align-Center\">　　促人水和谐</p>\n<p cms-style=\"font-L align-Center\">　　治理与发展双赢</p>\n<p cms-style=\"font-L align-Center\">　　百湖千河富万民</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/3c25-2ae48a4be7d535c254af0253b967d338.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"4\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【草】</font></p>\n<p cms-style=\"font-L align-Center\">　　青青河畔草</p>\n<p cms-style=\"font-L align-Center\">　　绵绵思远道</p>\n<p cms-style=\"font-L align-Center\">　　今日的黄河滩区</p>\n<p cms-style=\"font-L align-Center\">　　青草增加了绿度</p>\n<p cms-style=\"font-L align-Center\">　　郑州、开封、洛阳</p>\n<p cms-style=\"font-L align-Center\">　　新乡、焦作、濮阳</p>\n<p cms-style=\"font-L align-Center\">　　六个黄河滩区</p>\n<p cms-style=\"font-L align-Center\">　　种植全株青贮玉米</p>\n<p cms-style=\"font-L align-Center\">　　苜蓿等优质饲草</p>\n<p cms-style=\"font-L align-Center\">　　既能固氮改良土壤</p>\n<p cms-style=\"font-L align-Center\">　　又能防治水土流失</p>\n<p cms-style=\"font-L align-Center\">　　还能带来可观的经济效益</p>\n<p cms-style=\"font-L align-Center\">　　黄河滩区如今正在形成</p>\n<p cms-style=\"font-L align-Center\">　　草畜肥粮循环经济</p>\n<p cms-style=\"font-L align-Center\">　　奏响一曲草业强</p>\n<p cms-style=\"font-L align-Center\">　　农民富、生态美的协奏曲</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/03aa-e7b3fd1eaba3aca4651f4eb0a24276c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"5\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　<font cms-style=\"font-L strong-Bold align-Center\">【沙】</font></p>\n<p cms-style=\"font-L align-Center\">　　黄河是母亲河</p>\n<p cms-style=\"font-L align-Center\">　　一碗水半碗沙</p>\n<p cms-style=\"font-L align-Center\">　　自古以来脾气暴躁</p>\n<p cms-style=\"font-L align-Center\">　　摆荡扭动，多次改道</p>\n<p cms-style=\"font-L align-Center\">　　黄河故道宛在</p>\n<p cms-style=\"font-L align-Center\">　　沙岗沙丘遍布</p>\n<p cms-style=\"font-L align-Center\">　　大风起尘飞扬</p>\n<p cms-style=\"font-L align-Center\">　　土地瘠难种粮</p>\n<p cms-style=\"font-L align-Center\">　　河南持续治理沙化土地</p>\n<p cms-style=\"font-L align-Center\">　　林草植被增加</p>\n<p cms-style=\"font-L align-Center\">　　绿色覆盖土色</p>\n<p cms-style=\"font-L align-Center\">　　生态环境改善</p>\n<p cms-style=\"font-L align-Center\">　　瘠田成为良田</p>\n<p cms-style=\"font-L align-Center\">　　做好沙文章</p>\n<p cms-style=\"font-L align-Center\">　　绘就好风光</p>\n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/e0a9-516f9f860200c38e091f14e5334a814f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" id=\"6\">\n <span class=\"img_descr\"></span>\n</div>\n<p cms-style=\"font-L align-Center\">　　王安石有诗</p>\n<p cms-style=\"font-L align-Center\">　　一水护田将绿绕</p>\n<p cms-style=\"font-L align-Center\">　　两山排闼送青来</p>\n<p cms-style=\"font-L align-Center\">　　山水林田湖草沙生命共同体</p>\n<p cms-style=\"font-L align-Center\">　　是人与自然和谐共生的本质要求</p>\n<p cms-style=\"font-L align-Center\">　　在“两山理论”统领下</p>\n<p cms-style=\"font-L align-Center\">　　河南坚持发展中保护</p>\n<p cms-style=\"font-L align-Center\">　　在保护中发展的理念</p>\n<p cms-style=\"font-L align-Center\">　　打造好山好水好风光</p>\n<p cms-style=\"font-L align-Center\">　　探索金山银山新路径</p>\n<p cms-style=\"font-L align-Center\">　　统筹：银新玉 安艳鸽 石金红</p>\n<p cms-style=\"font-L align-Center\">　　执行：刘瑞朝 郭栩汝 杨露露 何山</p>\n<p cms-style=\"font-L align-Center\">　　设计：张谷臻</p>', '[\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/2d16-0b4babd192a6150e4fd005f06e83b2b3.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/f2e8-3ae01565abb72f7bfb87df4fba037757.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/c31b-c5db0f48da8126ab86f75c4462311482.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/c70f-d2dc6c64152f665e418302072aff7386.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/3c25-2ae48a4be7d535c254af0253b967d338.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/03aa-e7b3fd1eaba3aca4651f4eb0a24276c8.jpg/w700d1q75cms.jpg?by=cms_fixed_width\",\"https://k.sinaimg.cn/n/spider20250815/80/w1080h2200/20250815/e0a9-516f9f860200c38e091f14e5334a814f.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
