INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4714, 608, '巴以冲突持续 停火谈判取得进展', 1, 4, 95, '2025-08-15 12:25:49', '2025-08-15 12:25:49', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250114/video_001.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250114/video_001_thumb.png', NULL, NULL, NULL, NULL);
