INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4716, 608, '韩国总统弹劾案进展', 1, 4, 105, '2025-08-15 12:25:52', '2025-08-15 12:25:52', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250114/video_005.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250114/video_005_thumb.png', NULL, NULL, NULL, NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4717, NULL, '李在明发表“光复节”演讲：敦促日本正视“痛苦历史”，维护韩日两国信任', 0, 4, 105, '2025-08-15 12:30:26', '2025-08-15 11:26:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250815/259/w664h395/20250815/1fd0-ffef7187d6605ad0e54b40c2dd208819.png/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-15/doc-infkzssz6147398.shtml', '环球网', '<p cms-style=\"font-L\">　　[环球网报道 记者 索炎琦]据韩联社报道，韩国总统李在明15日发表“光复节”演讲，敦促日本正视“痛苦的历史”，维护韩日两国之间信任。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250815/259/w664h395/20250815/1fd0-ffef7187d6605ad0e54b40c2dd208819.png/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　李在明表示，在韩日两国邦交正常化60周年之际，应正视“痛苦历史”，重新定义双边关系，以推动两国关系向前发展。</p> \n<p cms-style=\"font-L\">　　“我希望日本政府能够正视我们痛苦的历史，努力维护两国之间的信任。”李在明表示，他将寻求通过积极的“穿梭外交”，与日本开展“面向未来的互利合作”。</p> \n<p cms-style=\"font-L\">　　韩联社提到，李在明作出上述表态之际，他将于8月23日至24日访问日本，并与日本首相石破茂举行韩日首脑会谈。</p> \n<p cms-style=\"font-L\">　　1945年8月15日，日本宣布无条件投降，朝鲜半岛从日本殖民统治下获得解放。此后，每年8月15日是韩国的“光复节”。</p> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250815/259/w664h395/20250815/1fd0-ffef7187d6605ad0e54b40c2dd208819.png/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4718, NULL, '妻子被关，尹锡悦戴手铐脚镣外出就医，患有可致盲眼病 其“狱中特权”也被中止', 0, 4, 105, '2025-08-15 12:30:33', '2025-08-15 10:46:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250815/299/w1619h1080/20250815/783b-539492877293050428db6f7319fed6b7.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-15/doc-infkzstm3016483.shtml', '成都商报', '<p cms-style=\"font-L\">　　韩国官员14日证实，被羁押在首尔看守所的前总统尹锡悦戴着手铐和电子脚镣，在一家外部医院接受眼睛治疗。</p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250815/299/w1619h1080/20250815/783b-539492877293050428db6f7319fed6b7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"▲韩国前总统尹锡悦（中）资料图片 图据视觉中国\">\n <span class=\"img_descr\">▲韩国前总统尹锡悦（中）资料图片 图据视觉中国</span>\n</div> \n<p cms-style=\"font-L\">　　据环球网报道，尹锡悦患有可致盲<font cms-style=\"font-L\">的</font>眼病黄斑变性。其此前曾数次以“身体原因”为由缺席传唤调查。由于担心尹锡悦失明，其被允许于本周三（13日）、周四（14日）两次前往位于京畿道的翰林大学圣心医院接受治疗。</p> \n<p cms-style=\"font-L\">　　就在他外出就医的这段时间，其妻子金建希被捕，并被送至首尔南部看守所。据此前报道，韩国法院12日晚针对金建希签发逮捕令，金建希随即被送往看守所<font cms-style=\"font-L\">。</font></p> \n<p cms-style=\"font-L\">　　惩教部门表示，尹锡悦外出就医时应遵守的规则与其他在押人员外出就医时相同。报道称，近日来出现了不少有关“尹锡悦狱中享特权”的批评声，为此韩国司法部更换了首尔看守所的负责人。据悉，韩国司法部14日宣布，原首尔看守所负责人金铉宇（音译）被调离，金道亨（音译）被任命为新负责人。</p> \n<p cms-style=\"font-L\">　　此外，从14日开始，尹锡悦不能再使用私人探视室与律师会面。报道称，他将与其他犯人共同使用一个探视设施。司法部官员郑成镐（音译）在社交平台上称，此举是为了防止尹锡悦滥用探视权。</p> \n<p cms-style=\"font-L\">　　据报道，尹锡悦在被羁押期间接受了总计395小时18分钟的法律咨询，共计与348人会面。郑成镐指责尹锡悦把私人探视室当作私人休息室。郑成镐补充称，同样的政策也将适用于金建希：“法律面前人人平等。”</p> \n<p cms-style=\"font-L\">　　红星新闻记者 黎谨睿 综合环球网</p> \n<p cms-style=\"font-L\">　　编辑 杨珒 责编 官莉</p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1752109465\" target=\"_blank\">尹锡悦夫妇同被羁押</a>\n</div> \n<p class=\"show_author\">责任编辑：陈建瑞 SN243</p>', '[\"https://k.sinaimg.cn/n/spider20250815/299/w1619h1080/20250815/783b-539492877293050428db6f7319fed6b7.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
