INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4736, 615, '以军轰炸加沙多地致巴勒斯坦人员伤亡 联合国呼吁落实两国方案', 1, 4, 151, '2025-08-15 16:00:33', '2025-08-15 16:00:33', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250729/video_002.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250729/video_002_thumb.png', NULL, NULL, NULL, NULL);
