INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4749, 618, '欧洲多国遭遇极端高温天气', 1, 4, 66, '2025-08-15 17:48:50', '2025-08-15 17:48:50', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250723/video_0010.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250723/video_0010_thumb.png', NULL, NULL, NULL, NULL);
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4750, NULL, '美媒曝特朗普政府考虑入股英特尔，英特尔股价暴涨超7%', 0, 4, 207, '2025-08-15 18:30:15', '2025-08-15 17:26:00', NULL, NULL, NULL, 'https://news.sina.com.cn/w/2025-08-15/doc-infmachv6045328.shtml', '界面', '<p cms-style=\"font-L \"></p> \n<p cms-style=\"font-L\">　　据彭博社8月14日报道，美国特朗普政府目前正在与英特尔公司进行谈判，并考虑入股该公司，但目前尚不清楚美国政府可能持有的股份数量。受此消息影响，英特尔公司股价14日尾盘一度大涨8.9%，随后涨幅有所收窄，截至收盘，英特尔股价上涨7.38%。据彭博社援引知情人士的话报道，这一入股计划源于本周美国总统特朗普与英特尔公司首席执行官陈立武的一次会面。有分析人士称，美国政府的入股将能够为英特尔目前在俄亥俄州规划的新建工厂提供资金。此前，英特尔曾承诺将把这座工厂建设成全球最大的芯片制造厂，但项目多次延期。（央视财经）</p> \n<p class=\"show_author\">责任编辑：刘光博 </p>', NULL);
