INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4783, NULL, '外媒：特朗普将以最高礼遇接待普京', 0, 4, 207, '2025-08-15 21:30:17', '2025-08-15 20:50:00', NULL, NULL, 'https://k.sinaimg.cn/n/sni/400/w1200h800/20250815/0a36-e8313065e36dc85a510066888c06e8f6.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-15/doc-infmapwx4234829.shtml', '参考消息', '<p>　　来源：参考消息</p> \n<p>　　【外媒：#特朗普将以最高礼遇接待普京#】据俄罗斯卫星社8月15日报道，美国全国广播公司电视台援引白宫消息人士的话称，美国总统特朗普将在阿拉斯加以最高礼遇接待俄罗斯总统普京，并在其抵达时亲自迎接。</p> \n<p></p> \n<p>　　报道说：“据两名高级政府官员称，预计特朗普将在俄罗斯总统普京15日抵达埃尔门多夫-理查森联合基地时以最高礼遇迎接，他计划亲自迎接俄罗斯领导人。”</p> \n<p></p> \n<p>　　官员们强调，会谈的具体细节仍在协调中。</p> \n<p></p> \n<p>　　俄美两国总统将于8月15日举行会谈。两位领导人的会晤将在阿拉斯加的埃尔门多夫-理查森联合基地举行。#俄美总统会晤或涉4项议题#</p> \n<div class=\"img_wrapper\">\n <img src=\"https://k.sinaimg.cn/n/sni/400/w1200h800/20250815/0a36-e8313065e36dc85a510066888c06e8f6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\" alt=\"\">\n <span class=\"img_descr\"></span>\n</div> \n<!--WeiboOriginalContent[{\"text\": \"【外媒：#特朗普将以最高礼遇接待普京#】据俄罗斯卫星社8月15日报道，美国全国广播公司电视台援引白宫消息人士的话称，美国总统特朗普将在阿拉斯加以最高礼遇接待俄罗斯总统普京，并在其抵达时亲自迎接。\\n\\n报道说：“据两名高级政府官员称，预计特朗普将在俄罗斯总统普京15日抵达埃尔门多夫-理查森联合基地时以最高礼遇迎接，他计划亲自迎接俄罗斯领导人。”\\n\\n官员们强调，会谈的具体细节仍在协调中。\\n\\n俄美两国总统将于8月15日举行会谈。两位领导人的会晤将在阿拉斯加的埃尔门多夫-理查森联合基地举行。#俄美总统会晤或涉4项议题#\"}]WeiboOriginalContent--> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/sni/400/w1200h800/20250815/0a36-e8313065e36dc85a510066888c06e8f6.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4784, NULL, '俄美元首会晤“所有选项”均未排除 特朗普或提前离场', 0, 4, 207, '2025-08-15 21:30:25', '2025-08-15 20:05:00', NULL, NULL, 'https://k.sinaimg.cn/n/spider20250815/0/w1920h1280/20250815/a3c2-2dcc17203e15ac2c8d3890ab1dc593c5.jpg/w700d1q75cms.jpg?by=cms_fixed_width', 'https://news.sina.com.cn/w/2025-08-15/doc-infmapwu1254437.shtml', '央视', '<p cms-style=\"font-L \"></p> \n<div class=\"img_wrapper\">\n <img id=\"0\" src=\"https://k.sinaimg.cn/n/spider20250815/0/w1920h1280/20250815/a3c2-2dcc17203e15ac2c8d3890ab1dc593c5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\">\n <span class=\"img_descr\"></span>\n</div> \n<p cms-style=\"font-L\">　　当地时间8月15日，一位美国官员表示，关于美国总统特朗普与俄罗斯总统普京即将在阿拉斯加举行的峰会，<font cms-style=\"font-L strong-Bold\">“所有选项仍在桌面上”</font>，包括如果特朗普认为普京并未认真对待达成协议，<font cms-style=\"font-L strong-Bold\">他可能会提前离开会场。</font></p> \n<p cms-style=\"font-L\">　　特朗普14日在与记者交流时暗示了这一可能性。他说：“我们会很快知道每个人的立场，我可能在前两分钟、三分钟、四分钟或五分钟内就能判断。我们往往很快就会看出，这会是一次好的会面还是坏的会面。如果是坏的会面，它会很快结束；如果是好的会面，我们可能会在不久的将来实现和平。”</p> \n<p cms-style=\"font-L\">　　这名美国官员补充说，<font cms-style=\"font-L strong-Bold\">白宫对这次会晤持谨慎乐观态度</font>，并强调特朗普认为必须与普京面对面，才能判断普京在停火问题上的真实意向。（央视记者 徐德智）</p> \n<p></p> \n<div class=\"wap_special\" data-sudaclick=\"content_relativetopics_p\"> \n <div class=\"tlt\">\n  点击进入专题：\n </div> \n <a href=\"https://news.sina.cn/zt_d/subject-1754958723\" target=\"_blank\">美俄元首会晤</a> \n <a href=\"https://sinanews.sina.cn/hot_zt/yingyanlandingpage1754732525\" target=\"_blank\">特朗普和普京将会晤</a>\n</div> \n<p class=\"show_author\">责任编辑：刘光博 </p>', '[\"https://k.sinaimg.cn/n/spider20250815/0/w1920h1280/20250815/a3c2-2dcc17203e15ac2c8d3890ab1dc593c5.jpg/w700d1q75cms.jpg?by=cms_fixed_width\"]');
