INSERT INTO `t_news` (`id`, `combo_id`, `title`, `map_news`, `area_level`, `area_id`, `create_time`, `news_time`, `location_subtitle`, `video_url`, `thumb_img`, `source_url`, `source_name`, `news_content`, `images`) VALUES (4833, 1227, '欧洲多国林火频发，西班牙已造成三人死亡', 1, 4, 179, '2025-08-16 07:57:31', '2025-08-16 07:57:31', NULL, 'https://map-question.gz.bcebos.com/mapnews_video/20250814/video_0017.mp4', 'https://map-question.gz.bcebos.com/mapnews_video/20250814/video_0017_thumb.png', NULL, NULL, NULL, NULL);
